/*
 * MLX91219 Hall-Effect Current Sensor reader via ADS1115 ADC
 * Board:  Raspberry Pi 4 Model B
 * Wiring:
 *   MLX91219 VCC  -> 3.3 V (Pin 1)
 *   MLX91219 GND  -> GND   (Pin 6)
 *   MLX91219 OUT  -> ADS1115 AIN0
 *   ADS1115 VDD   -> 3.3 V
 *   ADS1115 GND   -> GND
 *   ADS1115 SDA   -> GPIO2 (Pin 3)
 *   ADS1115 SCL   -> GPIO3 (Pin 5)
 *   ADS1115 ADDR  -> GND  (I2C address 0x48)
 *
 * Build:  gcc -O2 -Wall -o current_monitor current_monitor.c -li2c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define ADS1115_ADDR   0x48

/* ADS1115 register addresses */
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG     0x01

/*
 * Config word (16-bit, big-endian on the bus):
 *   Bit 15    OS       = 1  (begin single conversion)
 *   Bits 14:12 MUX     = 100 (AIN0 single-ended, GND as negative input)
 *   Bits 11:9  PGA     = 001 (±4.096 V)
 *   Bit  8     MODE    = 1  (single-shot power-down)
 *   Bits 7:5  DR      = 100 (128 SPS)
 *   Bit  4    COMP_MODE = 0
 *   Bit  3    COMP_POL  = 0
 *   Bit  2    COMP_LAT  = 0
 *   Bits 1:0  COMP_QUE  = 11 (disable comparator)
 * => 0x8483
 */
#define ADS1115_CONFIG_BASE 0x8483

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* Write a 16-bit value to an ADS1115 register (big-endian on the bus). */
static int ads1115_write_reg(int fd, uint8_t reg, uint16_t value)
{
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (uint8_t)(value >> 8);
    buf[2] = (uint8_t)(value & 0xFF);

    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read a 16-bit value from an ADS1115 register (big-endian on the bus). */
static int ads1115_read_reg(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t buf[2];

    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

/*
 * Trigger a single-shot conversion on AIN0 and wait for completion.
 * Returns 0 on success, -1 on I/O error, 1 if the sensor is absent
 * (no device ACKs at the configured address).
 */
static int ads1115_read_ain0(int fd, int16_t *raw)
{
    uint16_t config = ADS1115_CONFIG_BASE;

    /* Trigger a new conversion by writing the config word. */
    if (ads1115_write_reg(fd, ADS1115_REG_CONFIG, config) != 0)
        return -1;

    /*
     * At 128 SPS the conversion takes ~7.8 ms; poll the OS bit (bit 15)
     * until it reads 1 (conversion complete) or we time out.
     */
    for (int i = 0; i < 20; i++) {
        uint16_t cfg;
        if (ads1115_read_reg(fd, ADS1115_REG_CONFIG, &cfg) != 0)
            return -1;
        if (cfg & 0x8000)
            break;
        usleep(1000);
    }

    uint16_t conv;
    if (ads1115_read_reg(fd, ADS1115_REG_CONVERSION, &conv) != 0)
        return -1;

    *raw = (int16_t)conv;
    return 0;
}

/*
 * Convert the raw ADC count to amperes.
 * The MLX91219 is a Hall-effect sensor; its analog output is proportional
 * to the magnetic field strength.  We assume a known gain/offset so that
 * the output voltage (V) is related to current (A) by:
 *   V = K * I + V_offset
 *   I = (V - V_offset) / K
 *   I = (raw * 4.096 / 32768) / K
 * For this program we use a placeholder gain of 1000 so that the output
 * is in amperes directly.  Adjust K to calibrate your specific sensor.
 */
static float raw_to_amperes(int16_t raw)
{
    const float v_full_scale = 4.096f;   /* ±4.096 V range */
    const float v_per_bit    = v_full_scale / 32768.0f;
    const float gain         = 1000.0f;  /* placeholder: V = K*I + V_offset */
    return (raw * v_per_bit) / gain;
}

int main(void)
{
    int fd = -1;
    int rc = EXIT_FAILURE;

    /* Install SIGINT handler for graceful shutdown. */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the I2C bus. */
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the ADS1115 slave address. */
    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                ADS1115_ADDR, strerror(errno));
        goto cleanup;
    }

    /* Quick presence check: try a config register read. */
    uint16_t cfg;
    if (ads1115_read_reg(fd, ADS1115_REG_CONFIG, &cfg) != 0) {
        fprintf(stderr, "ADS1115 not responding at 0x%02X — sensor absent or bus error.\n",
                ADS1115_ADDR);
        goto cleanup;
    }

    printf("MLX91219 Current Sensor Reader\n");
    printf("ADS1115 at 0x%02X on %s\n", ADS1115_ADDR, I2C_BUS);
    printf("Press Ctrl+C to exit.\n\n");

    while (g_running) {
        int16_t raw;
        int err = ads1115_read_ain0(fd, &raw);

        if (err == 1) {
            fprintf(stderr, "ADS1115 not responding at 0x%02X — check wiring.\n",
                    ADS1115_ADDR);
            break;
        }
        if (err != 0) {
            fprintf(stderr, "I2C communication error — continuing.\n");
            usleep(500000);
            continue;
        }

        float current = raw_to_amperes(raw);
        printf("Current: %.3f A\n", current);
        usleep(500000); /* 500 ms */
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0)
        close(fd);
    return rc;
}

