#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN 27
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERSION 0x00
#define TEMP_THRESHOLD 60.0
#define LOG_FILE "fire_log.txt"
#define POLL_DELAY_US 100000
#define DEBOUNCE_DELAY_US 50000
#define BUZZER_DURATION_US 2000000

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(BUZZER_PIN, 0);
    gpioTerminate();
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }
    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set flame sensor pin mode\n");
        return -1;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set buzzer pin mode\n");
        return -1;
    }
    if (gpioWrite(BUZZER_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise buzzer state\n");
        return -1;
    }
    return 0;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C bus %d at address 0x%02X (code %d)\n",
                I2C_BUS, ADS1115_ADDR, i2c_handle);
        return -1;
    }
    /* Config: AIN0 single-ended, PGA ±4.096 V, single-shot, 128 SPS, no comparator */
    unsigned short config = 0xC083;
    char buf[3];
    buf[0] = ADS1115_REG_CONFIG;
    buf[1] = (char)((config >> 8) & 0xFF);
    buf[2] = (char)(config & 0xFF);
    if (i2cWriteDevice(i2c_handle, buf, 3) != 0) {
        fprintf(stderr, "Error: failed to write ADS1115 config\n");
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }
    return 0;
}

static int read_temperature(void) {
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C handle invalid\n");
        return -1;
    }
    /* Point to conversion register */
    char reg = ADS1115_REG_CONVERSION;
    if (i2cWriteDevice(i2c_handle, &reg, 1) != 0) {
        fprintf(stderr, "Error: failed to select ADS1115 conversion register\n");
        return -1;
    }
    char data[2];
    if (i2cReadDevice(i2c_handle, data, 2) != 2) {
        fprintf(stderr, "Error: failed to read ADS1115 conversion data\n");
        return -1;
    }
    int16_t raw = (int16_t)((data[0] << 8) | data[1]);
    /* PGA ±4.096 V, 16-bit signed => 1 bit = 125 µV */
    return (int)(raw * 0.000125);
}

static void log_event(const char *message) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: log file not open\n");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        return;
    }
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file);
}

static void activate_buzzer(void) {
    if (gpioWrite(BUZZER_PIN, 1) != 0) {
        fprintf(stderr, "Error: failed to activate buzzer\n");
        return;
    }
    gpioDelay(BUZZER_DURATION_US);
    if (gpioWrite(BUZZER_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to deactivate buzzer\n");
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (init_gpio() != 0) {
        return 1;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        cleanup();
        return 1;
    }

    printf("Fire detection system started. Press Ctrl+C to exit.\n");

    int flame_debounced = 0;

    while (running) {
        int flame = gpioRead(FLAME_SENSOR_PIN);
        if (flame < 0) {
            fprintf(stderr, "Error: failed to read flame sensor\n");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        if (flame) {
            if (!flame_debounced) {
                gpioDelay(DEBOUNCE_DELAY_US);
                flame = gpioRead(FLAME_SENSOR_PIN);
                if (flame > 0) {
                    flame_debounced = 1;
                }
            }
        } else {
            flame_debounced = 0;
        }

        int temp = read_temperature();
        if (temp < 0) {
            fprintf(stderr, "Warning: temperature read failed, skipping\n");
        }

        if (flame_debounced && temp >= 0 && temp > TEMP_THRESHOLD) {
            log_event("Fire detected! Temperature: 60.0 C");
            activate_buzzer();
        } else if (flame_debounced) {
            log_event("Flame detected!");
            activate_buzzer();
        } else if (temp >= 0 && temp > TEMP_THRESHOLD) {
            char msg[64];
            snprintf(msg, sizeof(msg), "Temperature: %.1f C", (double)temp);
            log_event(msg);
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

