#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <linux/gpio.h>
#include <linux/gpio/driver.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define GPIO_CHIP_NAME  "gpiochip4"
#define FAN_GPIO_LINE   18
#define CURRENT_THRESHOLD 1000
#define LOG_FILE        "current_log.txt"
#define SAMPLE_INTERVAL 1
#define SPI_SPEED_HZ    1000000
#define SPI_BITS        8
#define SPI_MODE        0

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;
static int g_gpio_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int spi_init(void) {
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI max speed: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    return 0;
}

static int gpio_init(void) {
    g_gpio_fd = open(GPIO_CHIP_NAME, O_RDWR);
    if (g_gpio_fd < 0) {
        g_gpio_fd = open("gpiochip0", O_RDWR);
        if (g_gpio_fd < 0) {
            fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
            return -1;
        }
    }

    struct gpio_line_request req;
    memset(&req, 0, sizeof(req));
    req.line_offset = FAN_GPIO_LINE;
    req.request_type = GPIO_LINE_REQUEST_DIRECTION_OUTPUT;
    req.flags = 0;
    strncpy(req.consumer_label, "current_monitor", sizeof(req.consumer_label) - 1);

    if (ioctl(g_gpio_fd, GPIO_GET_LINE_REQUEST_IOCTL, &req) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d: %s\n", FAN_GPIO_LINE, strerror(errno));
        close(g_gpio_fd);
        g_gpio_fd = -1;
        return -1;
    }

    if (ioctl(g_gpio_fd, GPIO_SET_LINE_VALUES_IOCTL, &req) < 0) {
        fprintf(stderr, "Error setting GPIO line value: %s\n", strerror(errno));
        close(g_gpio_fd);
        g_gpio_fd = -1;
        return -1;
    }

    return 0;
}

static int read_adc(int channel) {
    if (g_spi_fd < 0) {
        fprintf(stderr, "SPI device not initialized.\n");
        return -1;
    }

    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = 3;
    tr.speed_hz = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs = 0;

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Error during SPI transfer: %s\n", strerror(errno));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];

    if (adc_value == 0 || adc_value == 1023) {
        fprintf(stderr, "Warning: ADC value %d indicates sensor absent or wiring fault.\n", adc_value);
    }

    return adc_value;
}

static int log_data(int current_value) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

