static void control_fan(int current_value) {
    if (g_gpio_fd < 0) {
        fprintf(stderr, "GPIO not initialized.\n");
        return;
    }

    struct gpio_line_values values;
    memset(&values, 0, sizeof(values));
    values.mask = 1 << FAN_GPIO_LINE;

    if (current_value > CURRENT_THRESHOLD) {
        values.values[0] = 1;
        if (ioctl(g_gpio_fd, GPIO_SET_LINE_VALUES_IOCTL, &values) < 0) {
            fprintf(stderr, "Error setting fan GPIO HIGH: %s\n", strerror(errno));
        } else {
            printf("Fan ON (Current: %d)\n", current_value);
        }
    } else {
        values.values[0] = 0;
        if (ioctl(g_gpio_fd, GPIO_SET_LINE_VALUES_IOCTL, &values) < 0) {
            fprintf(stderr, "Error setting fan GPIO LOW: %s\n", strerror(errno));
        } else {
