static double raw_to_ppm(int16_t raw);
static int  log_ppm(const char *filename, double ppm);
static void cleanup(void);

/* ----------------------------- Signal handler ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- Cleanup ----------------------------------- */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ----------------------------- ADS1115 helpers ---------------------------- */
static int ads1115_init(int handle)
{
    /*
     * Config: single-shot, AIN0 single-ended, +/-4.096 V, 128 SPS,
     * disable comparator, no queue.
     */
    uint16_t config = ADS1115_CFG_OS
                    | ADS1115_CFG_MUX_A0
                    | ADS1115_CFG_PGA_4V
                    | ADS1115_CFG_MODE_SS
                    | ADS1115_CFG_DR_128
                    | ADS1115_CFG_CQUE_NONE;

    char buf[3];
    buf[0] = ADS1115_REG_CONFIG;
    buf[1] = (char)(config >> 8);
    buf[2] = (char)(config & 0xFF);

    if (i2cWriteDevice(handle, buf, 3) < 0) {
        fprintf(stderr, "Error: ADS1115 config write failed\n");
        return -1;
    }
    return 0;
}

static int ads1115_read_raw(int handle, int16_t *raw_out)
{
    char reg = ADS1115_REG_CONV;
    char data[2];

    /* Point to conversion register */
    if (i2cWriteDevice(handle, &reg, 1) < 0) {
        fprintf(stderr, "Error: ADS1115 register select failed\n");
        return -1;
    }

    /* Read 2 bytes (big-endian) */
    if (i2cReadDevice(handle, data, 2) != 2) {
        fprintf(stderr, "Error: ADS1115 conversion read failed\n");
        return -1;
    }

    *raw_out = (int16_t)(((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1]);
    return 0;
}

/* ----------------------------- Conversion -------------------------------- */
static double raw_to_ppm(int16_t raw)
{
    if (raw == 0) {
        return 0.0;
    }

    /* Convert raw ADC value to voltage */
    double voltage = (double)raw * MICS4514_VREF / 32768.0;

    /* Sensor resistance from voltage divider: R_sensor = R_load * V_ref / V_out */
    double rs = MICS4514_RLOAD * MICS4514_VREF / voltage;

    /* ppm = R0 * (Rs / R0) ^ -slope */
    double ratio = rs / MICS4514_R0_CO;
    double ppm = 100.0 * pow(ratio, -1.15);

    return ppm;
}

/* ----------------------------- Logging ------------------------------------ */
static int log_ppm(const char *filename, double ppm)
{
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("Error getting local time");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s, %.2f ppm\n", timestamp, ppm);
    fclose(fp);
    return 0;
}

/* ----------------------------- Main --------------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus to ADS1115 */
    g_i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure ADS1115 */
    if (ads1115_init(g_i2c_handle) < 0) {
        fprintf(stderr, "Error: ADS1115 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Error installing signal handlers");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("CO Monitor started. Logging to %s every %d seconds.\n",
           LOG_FILE, SAMPLE_INTERVAL_S);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        int16_t raw = 0;
        int ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (ads1115_read_raw(g_i2c_handle, &raw) == 0) {
                ok = 1;
                break;
            }
            fprintf(stderr, "Warning: I2C read attempt %d/%d failed\n",
                    attempt + 1, MAX_RETRIES);
            sleep(1);
        }

        if (!ok) {
            fprintf(stderr, "Error: I2C read failed after %d attempts. "
                            "Sensor may be disconnected or bus error.\n",
                    MAX_RETRIES);
            break;
        }

        double ppm = raw_to_ppm(raw);

        if (log_ppm(LOG_FILE, ppm) < 0) {
            fprintf(stderr, "Warning: failed to log CO value\n");
        }

        printf("CO: %.2f ppm (raw=%d)\n", ppm, raw);

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_S && g_running; i++) {
            sleep(1);
        }
    }

    cleanup();
    printf("\nCO Monitor stopped.\n");
    return EXIT_SUCCESS;
}

