#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS 1
#define I2C_ADDR 0x01
#define CO_LOG_FILE "co_log.txt"
#define ALERT_LOG_FILE "alert_log.txt"
#define ALERT_THRESHOLD 25.0f
#define READ_INTERVAL_SEC 5
#define READ_DELAY_US 100000
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor_data(int handle, uint16_t *ox, uint16_t *red) {
    char buf[4];
    int result = i2cReadDevice(handle, buf, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading sensor data: expected 4 bytes, got %d\n", result);
        return -1;
    }
    *ox = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *red = ((uint16_t)(uint8_t)buf[2] << 8) | (uint8_t)buf[3];
    return 0;
}

static float calculate_co_ppm(uint16_t ox_value) {
    return (float)ox_value * 0.01f;
}

static int log_co_ppm(const char *filename, float co_ppm) {
    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening %s: %s\n", filename, strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, %.2f ppm\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, co_ppm);
    fclose(fp);
    return 0;
}

static int log_alert(const char *filename, float co_ppm) {
    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening %s: %s\n", filename, strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, CO concentration exceeded %.2f ppm\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, co_ppm);
    fclose(fp);
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting up signal handlers: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at bus %d, addr 0x%02X: %d\n", I2C_BUS, I2C_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("CO Monitoring System started. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t ox_value = 0, red_value = 0;
        int success = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && running; attempt++) {
            if (read_sensor_data(i2c_handle, &ox_value, &red_value) == 0) {
                success = 1;
                break;
            }
            fprintf(stderr, "Read attempt %d/%d failed, retrying...\n", attempt + 1, MAX_RETRIES);
            gpioDelay(READ_DELAY_US);
        }

        if (!success) {
            fprintf(stderr, "Failed to read sensor data after %d attempts.\n", MAX_RETRIES);
            continue;
        }

        float co_ppm = calculate_co_ppm(ox_value);

        if (log_co_ppm(CO_LOG_FILE, co_ppm) != 0) {
            fprintf(stderr, "Error logging CO ppm value.\n");
        }

        if (co_ppm >= ALERT_THRESHOLD) {
            if (log_alert(ALERT_LOG_FILE, co_ppm) != 0) {
                fprintf(stderr, "Error logging alert.\n");
            }
        }

        gpioDelay(READ_INTERVAL_SEC * 1000000);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

