/*
 * audio_logger.c — Dual IMP23ABSU analog MEMS microphone sampler
 *
 * Board:  Raspberry Pi 4 Model B
 * Bus:    I2C bus 1 (GPIO2 = SDA, GPIO3 = SCL)
 * Sensors: Two IMP23ABSU analog OUTs on GPIO2 and GPIO3
 *
 * Build:  gcc -O2 -Wall -Wextra -o audio_logger audio_logger.c
 *
 * NOTE: The IMP23ABSU has an I2C-compatible digital output; this program
 *       reads the two analog OUT pins bit-banged via GPIO bit-banging.
 *       For a true I2C sensor, replace the GPIO reads with i2c_read_byte_data().
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

