{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read one sample from an IMP23ABSU analog OUT pin.
 * Returns 0 on success, -1 on read error. */
static int read_microphone(int gpio_pin, float *out_dB)
{
    /*
     * IMP23ABSU analog OUT: 0 V = 0 dB, 3.3 V = 120 dB.
     * We read the pin and convert to a scaled dB value.
     */
    int level = gpioRead(gpio_pin);
    if (level < 0) {
        fprintf(stderr, "gpioRead failed on GPIO %d\n", gpio_pin);
        return -1;
    }

    /* Map 0 (low) -> -60 dB, 1 (high) -> +60 dB */
    *out_dB = (float)level * 120.0f / 2.0f - 60.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
static float calculate_average(float v1, float v2)
{
    return (v1 + v2) / 2.0f;
}

