    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Audio logger started. Logging to %s every 100 ms.\n", LOG_FILE);
    printf("Press Ctrl+C to stop.\n");

    /* --- Main sampling loop ----------------------------------------- */
    while (g_running) {
        float v1 = ERROR_VALUE;
        float v2 = ERROR_VALUE;

        if (read_microphone(MIC1_GPIO, &v1) != 0) {
            fprintf(stderr, "Error reading MIC1 (GPIO %d)\n", MIC1_GPIO);
        }
        if (read_microphone(MIC2_GPIO, &v2) != 0) {
