#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

#define MIC1_CS_PIN 8
#define MIC2_CS_PIN 9
#define LED_PIN 27
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SAMPLE_WINDOW_MS 100
#define SAMPLE_INTERVAL_US 1000
#define THRESHOLD_HIGH 0.5
#define LED_ON_TIME_MS 500
#define NUM_SAMPLES (SAMPLE_WINDOW_MS / (SAMPLE_INTERVAL_US / 1000))

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mic(int cs_pin) {
    char tx[3] = {0x01, 0x80, 0x00};
    char rx[3] = {0, 0, 0};
    if (gpioWrite(cs_pin, 0) < 0) return -1;
    int ret = spiXfer(SPI_CHANNEL, tx, rx, 3);
    if (gpioWrite(cs_pin, 1) < 0) return -1;
    if (ret < 0) return -1;
    return ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
}

static double calculate_rms(const int *samples, int num_samples) {
    double sum_sq = 0.0;
    for (int i = 0; i < num_samples; i++) {
        double v = (double)samples[i];
        sum_sq += v * v;
    }
    return sqrt(sum_sq / num_samples);
}

static void log_data(FILE *f, double rms1, double rms2) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char tbuf[32];
    strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(f, "%s.%03ld,%.4f,%.4f\n", tbuf, ts.tv_nsec / 1000000, rms1, rms2);
    fflush(f);
}

static void cleanup(void) {
    if (log_file) { fclose(log_file); log_file = NULL; }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }
    gpioSetMode(MIC1_CS_PIN, PI_OUTPUT);
    gpioSetMode(MIC2_CS_PIN, PI_OUTPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(MIC1_CS_PIN, 1);
    gpioWrite(MIC2_CS_PIN, 1);
    gpioWrite(LED_PIN, 0);
    log_file = fopen("audio_events.csv", "a");
    if (!log_file) {
        perror("fopen");
        gpioTerminate();
        return 1;
    }
    struct sigaction sa = {0};
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    int mic1_samples[NUM_SAMPLES], mic2_samples[NUM_SAMPLES];
    while (running) {
        for (int i = 0; i < NUM_SAMPLES && running; i++) {
            int v1 = read_mic(MIC1_CS_PIN);
            int v2 = read_mic(MIC2_CS_PIN);
            if (v1 < 0 || v2 < 0) {
                fprintf(stderr, "SPI read error at sample %d\n", i);
                cleanup();
                return 1;
            }
            mic1_samples[i] = v1;
            mic2_samples[i] = v2;
            gpioDelay(SAMPLE_INTERVAL_US);
        }
        double rms1 = calculate_rms(mic1_samples, NUM_SAMPLES);
        double rms2 = calculate_rms(mic2_samples, NUM_SAMPLES);
        log_data(log_file, rms1, rms2);
        if (rms1 > THRESHOLD_HIGH || rms2 > THRESHOLD_HIGH) {
            gpioWrite(LED_PIN, 1);
            gpioDelay(LED_ON_TIME_MS * 1000);
            gpioWrite(LED_PIN, 0);
        }
    }
    cleanup();
    return 0;
}

