                      ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_CQUE_NONE;

    if (i2c_write16(fd, ADS1115_REG_CONFIG, config) < 0) {
        return -1;
    }

    for (int i = 0; i < 100; i++) {
        uint16_t cfg;
        if (i2c_read16(fd, ADS1115_REG_CONFIG, &cfg) < 0) {
            return -1;
        }
        if (cfg & ADS1115_CONFIG_OS_BEGIN) {
            break;
        }
        usleep(1000);
        if (i == 99) {
            return -1;
        }
    }

    uint16_t conv;
    if (i2c_read16(fd, ADS1115_REG_CONVERSION, &conv) < 0) {
        return -1;
    }

    *raw = (int16_t)conv;
    return 0;
}

static double convert_to_current(int16_t raw) {
    double voltage = (raw * 4.096) / 32768.0;
    return voltage * 100.0;
}

static double calculate_average(const double *buf, int size) {
    double sum = 0.0;
    for (int i = 0; i < size; i++) {
        sum += buf[i];
    }
    return sum / size;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open " I2C_BUS);
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(fd);
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(fd);
        return EXIT_FAILURE;
    }

    FILE *fp = fopen("current_log.txt", "a");
    if (!fp) {
        perror("fopen current_log.txt");
        close(fd);
        return EXIT_FAILURE;
    }

    double buffer[BUFFER_SIZE];
    int buffer_index = 0;
    int buffer_count = 0;

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED pin mode\n");
        fclose(fp);
        close(fd);
        return EXIT_FAILURE;
    }
    gpioWrite(LED_PIN, 0);

    printf("Starting current monitoring...\n");

    while (running) {
        int16_t raw;
        if (read_ads1115(fd, &raw) < 0) {
            fprintf(stderr, "Error reading ADS1115: %s\n", strerror(errno));
            break;
        }

        double current = convert_to_current(raw);

        buffer[buffer_index] = current;
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;
        if (buffer_count < BUFFER_SIZE) {
            buffer_count++;
        }

        double average = calculate_average(buffer, buffer_count);

        if (average > CURRENT_THRESHOLD) {
            gpioWrite(LED_PIN, 1);
        } else {
            gpioWrite(LED_PIN, 0);
        }

        fprintf(fp, "%ld,%.2f,%.2f\n", (long)time(NULL), current, average);
        fflush(fp);

        usleep(SAMPLE_DELAY_MS * 1000);
    }

    gpioWrite(LED_PIN, 0);
    fclose(fp);
    close(fd);
    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

