#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define TCS34725_ADDRESS         0x29
#define TCS34725_COMMAND_BIT     0x80
#define TCS34725_ENABLE          0x00
#define TCS34725_ENABLE_PON      0x01
#define TCS34725_ENABLE_AEN      0x02
#define TCS34725_ID              0x12
#define TCS34725_CDATAL          0x14
#define TCS34725_RDATAL          0x16
#define TCS34725_GDATAL          0x18
#define TCS34725_BDATAL          0x1A
#define TCS34725_EXPECTED_ID     0x44
#define LOG_FILE_NAME           "color_log.csv"
#define SAMPLE_INTERVAL_US      1000000
#define POWER_UP_DELAY_US       3000

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int tcs34725_write(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, TCS34725_COMMAND_BIT | reg, value);
    if (rc < 0)
        fprintf(stderr, "Warning: I2C write to reg 0x%02X failed (rc=%d)\n", reg, rc);
    return rc;
}

static int tcs34725_read(int handle, uint8_t reg, uint8_t *buf, uint32_t len)
{
    int rc = i2cReadI2CBlockData(handle, TCS34725_COMMAND_BIT | reg, (char *)buf, len);
    if (rc < 0)
        fprintf(stderr, "Warning: I2C read from reg 0x%02X failed (rc=%d)\n", reg, rc);
    return rc;
}

static int tcs34725_init(int handle)
{
    uint8_t id = 0;
    if (tcs34725_read(handle, TCS34725_ID, &id, 1) < 0)
        return -1;
    if (id != TCS34725_EXPECTED_ID) {
        fprintf(stderr, "Error: TCS34725 ID mismatch (got 0x%02X, expected 0x%02X)\n",
                id, TCS34725_EXPECTED_ID);
        return -1;
    }
    if (tcs34725_write(handle, TCS34725_ENABLE, TCS34725_ENABLE_PON) < 0)
        return -1;
    gpioDelay(3000);
    if (tcs34725_write(handle, TCS34725_ENABLE, TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN) < 0)
        return -1;
    return 0;
}

static int tcs34725_read_crgb(int handle, uint16_t *clear, uint16_t *red,
                               uint16_t *green, uint16_t *blue)
{
    uint8_t buf[8];
    if (tcs34725_read(handle, TCS34725_CDATAL, buf, 8) < 0)
        return -1;
    *clear = (uint16_t)((buf[1] << 8) | buf[0]);
    *red   = (uint16_t)((buf[3] << 8) | buf[2]);
    *green = (uint16_t)((buf[5] << 8) | buf[4]);
    *blue  = (uint16_t)((buf[7] << 8) | buf[6]);
    return 0;
}

static int log_data(FILE *fp, uint16_t clear, uint16_t red,
                    uint16_t green, uint16_t blue)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (fprintf(fp, "%s,%u,%u,%u,%u\n", timestamp, clear, red, green, blue) < 0)
        return -1;
    fflush(fp);
    return 0;
}

static void cleanup(void)
{
    if (g_log_file) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(1, TCS34725_ADDRESS, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (rc=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (tcs34725_init(g_i2c_handle) != 0) {
        fprintf(stderr, "Error: TCS34725 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (!g_log_file) {
        fprintf(stderr, "Error: cannot open %s: %s\n", LOG_FILE_NAME, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,clear,red,green,blue\n");
        fflush(g_log_file);
    }

    uint16_t clear, red, green, blue;
    int consecutive_failures = 0;

    while (g_running) {
        if (tcs34725_read_crgb(g_i2c_handle, &clear, &red, &green, &blue) == 0) {
            consecutive_failures = 0;
            if (log_data(g_log_file, clear, red, green, blue) != 0) {
                fprintf(stderr, "Error: failed to write to log file\n");
                break;
            }
        } else {
            consecutive_failures++;
            if (consecutive_failures >= 3) {
                fprintf(stderr, "Error: 3 consecutive I2C failures, aborting\n");
                break;
            }
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

