#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x08
#define LOG_FILE       "pressure_log.csv"
#define SAMPLE_PERIOD  1.0
#define MAX_CONSEC_ERR 10

/* MLX90817 register addresses (16-bit, big-endian on the bus) */
#define REG_PRESSURE   0x0000
#define REG_TEMP       0x0002
#define REG_ID         0x0004

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Read a 16-bit big-endian register from the MLX90817.
 * Returns 0 on success and stores the value in *out; returns -1 on error. */
static int read_register(uint16_t reg, uint16_t *out)
{
    char buf[2];
    int  rc;

    rc = i2cWriteByte(g_i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C write (reg 0x%04X) failed: %d\n", reg, rc);
        return -1;
    }

    rc = i2cReadDevice(g_i2c_handle, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "I2C read (reg 0x%04X) failed: %d\n", reg, rc);
        return -1;
    }

    *out = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

/* Convert raw pressure reading to kPa.
 * The MLX90817 pressure register is 16-bit unsigned; the conversion
 * factor depends on the specific sensor variant.  This implementation
 * uses a common 16-bit variant scaling factor of 0.01 kPa per LSB. */
static float raw_to_kpa(uint16_t raw)
{
    return (float)raw * 0.01f;
}

static int log_data(FILE *fp, float pressure)
{
    time_t     now;
    struct tm  tm_utc;
    char       ts[32];

    time(&now);
    gmtime_r(&now, &tm_utc);
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc);

    if (fprintf(fp, "%s,%.2f\n", ts, pressure) < 0) {
        fprintf(stderr, "fprintf to log failed\n");
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed\n");
        return -1;
    }
    return 0;
}

int main(void)
{
    uint16_t raw_pressure = 0;
    int      consecutive_errors = 0;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %d\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("fopen log");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,pressure_kPa\n");
        fflush(g_log_file);
    }

    printf("MLX90817 logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        if (read_register(REG_PRESSURE, &raw_pressure) == 0) {
            consecutive_errors = 0;
            float pressure = raw_to_kpa(raw_pressure);
            if (log_data(g_log_file, pressure) != 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            }
        } else {
            consecutive_errors++;
            fprintf(stderr, "Sensor read failed (%d consecutive)\n",
                    consecutive_errors);
            if (consecutive_errors >= MAX_CONSEC_ERR) {
                fprintf(stderr, "Too many consecutive errors; aborting.\n");
                break;
            }
        }
        time_sleep(SAMPLE_PERIOD);
    }

    /* Clean shutdown */
    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();

    printf("Program terminated cleanly.\n");
    return EXIT_SUCCESS;
}

