/*
 * Raspberry Pi 4 Model B — MLX90834 pressure sensor via ADS1115 ADC
 *
 * Wiring:
 *   ADS1115 SDA  -> GPIO2  (I2C bus 1)
 *   ADS1115 SCL  -> GPIO3  (I2C bus 1)
 *   ADS1115 ADDR -> GND   (I2C address 0x48)
 *   ADS1115 AIN0 -> MLX90834 pressure output
 *   ADS1115 AIN1 -> MLX90834 NTC temperature output
 *   ADS1115 AIN3 -> GND
 *   LED + 330 Ω -> GPIO17 -> GND
 *
 * Build: gcc -O2 -Wall -o mlx90834_ads1115 mlx90834_ads1115.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- ADS1115 constants ---- */
#define ADS1115_ADDR        0x48
#define ADS1115_REG_CONV    0x00
#define ADS1115_REG_CONFIG  0x01

/* Config register bit fields */
#define ADS1115_CFG_OS      (1u << 15)          /* Operational status / single-shot start */
#define ADS1115_CFG_MUX_P0 (0x4000u)            /* AIN0 single-ended */
#define ADS1115_CFG_MUX_T1 (0x5000u)            /* AIN1 single-ended */
#define ADS1115_CFG_PGA_4V (0x0200u)            /* ±4.096 V */
#define ADS1115_CFG_MODE_SS (0x0100u)           /* Single-shot mode */
#define ADS1115_CFG_DR_128 (0x0080u)            /* 128 SPS */
#define ADS1115_CFG_CQUE_NONE (0x0003u)         /* Disable comparator */

#define ADS1115_PGA_4V_FULL (4.096f)
#define ADS1115_MAX_COUNT   32767.0f            /* 16-bit signed, single-ended positive */

/* ---- MLX90834 calibration (example — replace with your calibrated values) ---- */
#define MLX90834_PRESSURE_OFFSET  0.0f
#define MLX90834_PRESSURE_SCALE   0.001f         /* kPa per LSB */
#define MLX90834_TEMP_OFFSET     0.0f
#define MLX90834_TEMP_SCALE      0.001f          /* °C per LSB */

#define PRESSURE_THRESHOLD 105.0f   /* kPa */
#define LED_GPIO           17
#define I2C_BUS            1
#define MAX_RETRIES        3
#define SAMPLE_PERIOD_US   1000000  /* 1 s */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a 16-bit value to an ADS1115 register (MSB first). */
static int ads1115_write_reg(int handle, uint8_t reg, uint16_t value)
{
    char buf[3];
    buf[0] = (char)reg;
    buf[1] = (char)((value >> 8) & 0xFF);
    buf[2] = (char)(value & 0xFF);
    return i2cWriteDevice(handle, buf, 3);
}

/* Read a 16-bit value from an ADS1115 register (MSB first). */
static int ads1115_read_reg(int handle, uint8_t reg, uint16_t *out)
{
    char reg_buf[1] = { (char)reg };
    char data[2] = { 0 };

    if (i2cWriteDevice(handle, reg_buf, 1) < 0)
        return -1;
    if (i2cReadDevice(handle, data, 2) != 2)
        return -1;

    *out = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

/* Trigger a single-shot conversion on the given mux channel and read the raw count. */
static int ads1115_read_channel(int handle, uint16_t mux, int16_t *raw_out)
{
    uint16_t config = ADS1115_CFG_OS | mux | ADS1115_CFG_PGA_4V |
                      ADS1115_CFG_MODE_SS | ADS1115_CFG_DR_128 |
                      ADS1115_CFG_CQUE_NONE;

    if (ads1115_write_reg(handle, ADS1115_REG_CONFIG, config) < 0)
        return -1;

    /* Wait for conversion to complete (~8 ms at 128 SPS). */
    gpioDelay(10000);

    uint16_t val;
    if (ads1115_read_reg(handle, ADS1115_REG_CONV, &val) < 0)
        return -1;

    *raw_out = (int16_t)val;
    return 0;
}

/* Convert raw ADC count to engineering units. */
static float convert_pressure(int16_t raw)
{
    float voltage = (float)raw * ADS1115_PGA_4V_FULL / ADS1115_MAX_COUNT;
    return (voltage - MLX90834_PRESSURE_OFFSET) * MLX90834_PRESSURE_SCALE;
}

static float convert_temperature(int16_t raw)
{
    float voltage = (float)raw * ADS1115_PGA_4V_FULL / ADS1115_MAX_COUNT;
    return (voltage - MLX90834_TEMP_OFFSET) * MLX90834_TEMP_SCALE;
}

int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus to ADS1115 --- */
    int i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (code %d). Check wiring and address.\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Configure LED GPIO --- */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO %d.\n", LED_GPIO);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    /* --- Install signal handler --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed.\n");
    }

    printf("MLX90834 pressure monitor started. Press Ctrl+C to exit.\n");
    printf("ADS1115 at 0x%02X on I2C bus %d. LED on GPIO%d.\n\n",
           ADS1115_ADDR, I2C_BUS, LED_GPIO);

    /* --- Main sampling loop --- */
    while (g_running) {
        int16_t raw_p = 0, raw_t = 0;
        bool ok = false;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; ++attempt) {
            if (ads1115_read_channel(i2c_handle, ADS1115_CFG_MUX_P0, &raw_p) == 0 &&
                ads1115_read_channel(i2c_handle, ADS1115_CFG_MUX_T1, &raw_t) == 0) {
                ok = true;
                break;
            }
            fprintf(stderr, "Warning: I2C read failed (attempt %d/%d).\n",
                    attempt + 1, MAX_RETRIES);
            gpioDelay(100000); /* 100 ms backoff */
        }

        if (!ok) {
            fprintf(stderr, "Error: sensor read failed after %d retries. "
                            "Check wiring and ADS1115 power.\n", MAX_RETRIES);
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        float pressure = convert_pressure(raw_p);
        float temperature = convert_temperature(raw_t);

        printf("Pressure: %7.2f kPa | Temperature: %6.2f °C | LED: %s\n",
               pressure, temperature,
               (pressure > PRESSURE_THRESHOLD) ? "ON" : "OFF");

        if (pressure > PRESSURE_THRESHOLD) {
            gpioWrite(LED_GPIO, 1);
        } else {
            gpioWrite(LED_GPIO, 0);
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* --- Cleanup --- */
    gpioWrite(LED_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

