code:
/*
 * MLX91209 Hall-effect current sensor reader via MCP3008 ADC on Raspberry Pi 3 B+.
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3 V (Pin 1)
 *   MCP3008 VREF -> 3.3 V (Pin 1)
 *   MCP3008 AGND -> GND
 *   MCP3008 DGND -> GND
 *   MCP3008 CLK  -> GPIO11 (BCM, SPI0 SCLK)
 *   MCP3008 DOUT -> GPIO9  (BCM, SPI0 MISO)
 *   MCP3008 DIN  -> GPIO10 (BCM, SPI0 MOSI)
 *   MCP3008 CS   -> GPIO8  (BCM, SPI0 CE0)
 *   MCP3008 CH0  -> MLX91209 analog output
 *   GPIO27       -> Motor shutdown control (active HIGH)
 *
 * Build: gcc -O2 -Wall -o current_monitor current_monitor.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define SPI_BUS          0
#define SPI_CHIP_SELECT  0
#define SPI_SPEED_HZ     1000000          /* 1 MHz */
#define SPI_MODE         0

#define ADC_CHANNEL      0                /* MCP3008 single-ended channel 0 */
#define ADC_MAX_VALUE    1023             /* 10-bit ADC */

#define GPIO_SHUTDOWN    27               /* BCM pin for motor shutdown */
#define OVERCURRENT_THRESHOLD 10.0       /* Amperes */
#define SAMPLE_INTERVAL_US 100000         /* 100 ms */

#define LOG_FILE_NAME    "current_log.txt"

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_file = NULL;
static struct gpiod_chip *g_chip = NULL;
static struct gpiod_line *g_shutdown_line = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_shutdown_line) {
        gpiod_line_set_value(g_shutdown_line, 0);   /* Motor OFF */
        gpiod_line_release(g_shutdown_line);
        g_shutdown_line = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
}

/* ------------------------------------------------------------------ */
/* MCP3008 single-ended read                                           */
/* ------------------------------------------------------------------ */
/*
 * MCP3008 SPI protocol (3 bytes):
 *   Byte 0: 0x01                       (start bit)
 *   Byte 1: (0x08 | channel) << 4      (single-ended + channel)
 *   Byte 2: 0x00                       (don't care, clocks out low bits)
 *
 * Response:
 *   rx[1] bits 1..0  -> MSB of result
 *   rx[2]           -> LSB of result
 */
static int read_mcp3008(int channel, int *out_value)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = {
        0x01,
        (uint8_t)((0x08 | channel) << 4),
        0x00
    };
    uint8_t rx[3] = {0};

    struct gpiod_line *cs = gpiod_chip_get_line(g_chip, SPI_CHIP_SELECT);
    if (!cs) {
        fprintf(stderr, "Failed to get CS line: %s\n", strerror(errno));
        return -1;
    }

    /* Assert CS (active LOW) */
    if (gpiod_line_set_value(cs, 0) < 0) {
        fprintf(stderr, "Failed to assert CS: %s\n", strerror(errno));
        return -1;
    }

    /* Small delay so the ADC is ready to receive */
    usleep(10);

    /* Full-duplex transfer: write command, read response */
    struct gpiod_line *mosi = gpiod_chip_get_line(g_chip, 10);   /* MOSI */
    struct gpiod_line *miso = gpiod_chip_get_line(g_chip, 9);    /* MISO */
    struct gpiod_line *sclk = gpiod_chip_get_line(g_chip, 11);   /* SCLK */

    if (!mosi || !miso || !sclk) {
        fprintf(stderr, "Failed to get SPI GPIO lines\n");
        gpiod_line_set_value(cs, 1);   /* deassert CS */
        return -1;
    }

    /* Manual SPI bit-bang using gpiod_line_set_value */
    for (int i = 0; i < 3; i++) {
        uint8_t byte = tx[i];
        for (int bit = 7; bit >= 0; bit--) {
            if (gpiod_line_set_value(mosi, (byte >> bit) & 1) < 0) {
                fprintf(stderr, "MOSI write failed: %s\n", strerror(errno));
                gpiod_line_set_value(cs, 1);
                return -1;
            }
            usleep(1);   /* ~1 us clock period at 1 MHz */

            if (gpiod_line_set_value(sclk, 1) < 0) {
                fprintf(stderr, "SCLK high failed: %s\n", strerror(errno));
                gpiod_line_set_value(cs, 1);
                return -1;
            }
            usleep(1);

            if (gpiod_line_set_value(sclk, 0) < 0) {
                fprintf(stderr, "SCLK low failed: %s\n", strerror(errno));
                gpiod_line_set_value(cs, 1);
                return -1;
            }
            usleep(1);

            if (i == 1 && bit == 0) {
                /* Last bit of command byte: read first data bit */
                int val = gpiod_line_get_value(miso);
                if (val < 0) {
                    fprintf(stderr, "MISO read failed: %s\n", strerror(errno));
                    gpiod_line_set_value(cs, 1);
                    return -1;
                }
                rx[i] = (uint8_t)(val ? 0x80 : 0x00);
            }
        }
    }

    /* Deassert CS */
    if (gpiod_line_set_value(cs, 1) < 0) {
        fprintf(stderr, "Failed to deassert CS: %s\n", strerror(errno));
        return -1;
    }

    /* Extract 10-bit result */
    int value = ((rx[1] & 0x03) << 8) | rx[2];
    *out_value = value;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Current conversion                                                  */
/* ------------------------------------------------------------------ */
/*
 * MLX91209 analog output is proportional to current.
 * Calibration: adjust SCALE and OFFSET to match your specific sensor
 * and supply voltage.  Example for 5 V supply, 10 A range:
 *   SCALE   = 5.0 / 10.0 = 0.5 V/A
 *   OFFSET  = 0.0 V
 */
static const float SCALE   = 0.5f;   /* V/A */
static const float OFFSET  = 0.0f;   /* V   */

static float adc_to_current(int adc_value)
{
    if (adc_value < 0) adc_value = 0;
    if (adc_value > ADC_MAX_VALUE) adc_value = ADC_MAX_VALUE;
    return ((float)adc_value / (float)ADC_MAX_VALUE) * SCALE + OFFSET;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_reading(float current)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    if (fprintf(g_log_file, "%s, Current: %.2f A\n", ts, current) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
    } else {
        fflush(g_log_file);
    }
}

/* ------------------------------------------------------------------ */
/* Overcurrent shutdown                                                */
/* ------------------------------------------------------------------ */
static void handle_overcurrent(float current)
{
    fprintf(stderr, "OVERCURRENT DETECTED: %.2f A exceeds %.1f A threshold\n",
            current, OVERCURRENT_THRESHOLD);

    if (g_shutdown_line) {
        if (gpiod_line_set_value(g_shutdown_line, 1) < 0) {
            fprintf(stderr, "Failed to set shutdown HIGH: %s\n", strerror(errno));
        } else {
            fprintf(stderr, "Motor shutdown initiated (GPIO%d HIGH)\n", GPIO_SHUTDOWN);
        }
    }

    log_reading(current);
    cleanup();
    exit(EXIT_FAILURE);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install signal handlers: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (!g_log_file) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open GPIO chip ---- */
    g_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!g_chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        fclose(g_log_file);
        g_log_file = NULL;
        return EXIT_FAILURE;
    }

    /* ---- Get shutdown line ---- */
    g_shutdown_line = gpiod_chip_get_line(g_chip, GPIO_SHUTDOWN);
    if (!g_shutdown_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_SHUTDOWN, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Request output, initial LOW */
    if (gpiod_line_request_output(g_shutdown_line, "current_monitor", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO %d as output: %s\n",
                GPIO_SHUTDOWN, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Open SPI via gpiod (bit-bang) ---- */
    /* For production, use spidev directly; gpiod does not expose SPI. */
    /* We use spidev0.0 for the MCP3008. */
    /* ---- (Note: gpiod does not expose SPI; use spidev directly.) ---- */
    /* ---- (Continuing with spidev-based approach for correctness.) ---- */
    int spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open /dev/spidev0.0: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        cleanup();
        return EXIT_FAILURE;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to set SPI speed: %s\n", strerror(errno));
        close(spi_fd);
        cleanup();
        return EXIT_FAILURE;
    }

    uint8_t bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        close(spi_fd);
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Main loop ---- */
    while (g_running) {
        int adc_value = 0;
        if (read_mcp3008(ADC_CHANNEL, &adc_value) < 0) {
            fprintf(stderr, "ADC read error; retrying in 100 ms\n");
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }

        float current = adc_to_current(adc_value);
        log_reading(current);

        if (current > OVERCURRENT_THRESHOLD) {
            handle_overcurrent(current);
        }

        usleep(SAMPLE_INTERVAL_US);
    }

    /* ---- Graceful shutdown ---- */
    if (g_shutdown_line) {
        gpiod_line_set_value(g_shutdown_line, 0);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    cleanup();
    return EXIT_SUCCESS;
}

