/*
 * Raspberry Pi 4 Model B – MLX90830 pressure logger via ADS1115 ADC
 *
 * Wiring:
 *   ADS1115 SDA  -> GPIO2  (BCM)
 *   ADS1115 SCL  -> GPIO3  (BCM)
 *   ADS1115 ADDR -> GND    (I2C address 0x48)
 *   ADS1115 VDD  -> 3.3 V
 *   ADS1115 GND  -> GND
 *   MLX90830 VOUT-> ADS1115 AIN0
 *   MLX90830 VCC -> 3.3 V
 *   MLX90830 GND -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o pressure_logger pressure_logger.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define ADS1115_ADDR   0x48

/* ADS1115 register addresses */
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG     0x01

/* Config-register bit fields */
#define ADS1115_CFG_OS_BEGIN   (1u << 15)          /* assert single-shot start */
#define ADS1115_CFG_MUX_AIN0  (0x4000u)            /* AIN0 vs GND */
#define ADS1115_CFG_PGA_4_096 (0x0200u)            /* +/-4.096 V range */
#define ADS1115_CFG_MODE_SS  (0x0100u)            /* single-shot mode */
#define ADS1115_CFG_DR_128   (0x0080u)            /* 128 SPS (slow but reliable) */
#define ADS1115_CFG_CQUE_NONE (0x0003u)           /* disable comparator */

#define LOG_FILE        "pressure_log.txt"
#define SAMPLE_PERIOD_S 1
#define ADC_MAX_COUNT   32767.0f                 /* 16-bit signed, positive range */
#define ADC_VREF        4.096f                   /* PGA full-scale */
#define PRESSURE_MIN    0.0f
#define PRESSURE_MAX    100.0f
#define VOUT_MIN        0.0f
#define VOUT_MAX        (ADC_VREF * 0.95f)        /* 95% of VREF headroom */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a 16-bit value to an ADS1115 register (MSB first). */
static int ads1115_write_reg(int fd, uint8_t reg, uint16_t value)
{
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (uint8_t)(value >> 8);
    buf[2] = (uint8_t)(value & 0xFF);

    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "ads1115_write_reg: write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read a 16-bit value from an ADS1115 register (MSB first). */
static int ads1115_read_reg(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t buf[2];

    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "ads1115_read_reg: select reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "ads1115_read_reg: read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

/* Trigger a single-shot conversion on AIN0 and return the raw count. */
static int ads1115_read_ain0(int fd, int16_t *raw_out)
{
    uint16_t config = ADS1115_CFG_OS_BEGIN | ADS1115_CFG_MUX_AIN0 |
                      ADS1115_CFG_PGA_4_096 | ADS1115_CFG_MODE_SS |
                      ADS1115_CFG_DR_128 | ADS1115_CFG_CQUE_NONE;

    if (ads1115_write_reg(fd, ADS1115_REG_CONFIG, config) != 0)
        return -1;

    /* 128 SPS -> ~8 ms conversion; poll OS bit with timeout. */
    for (int i = 0; i < 20; i++) {
        uint16_t cfg;
        if (ads1115_read_reg(fd, ADS1115_REG_CONFIG, &cfg) != 0)
            return -1;
        if (cfg & ADS1115_CFG_OS_BEGIN)
            break;
        usleep(5000);
    }

    uint16_t raw;
    if (ads1115_read_reg(fd, ADS1115_REG_CONVERSION, &raw) != 0)
        return -1;

    *raw_out = (int16_t)raw;
    return 0;
}

/* Convert raw ADC count to pressure (kPa). */
static float raw_to_pressure(int16_t raw)
{
    float vout = ((float)raw / ADC_MAX_COUNT) * ADC_VREF;
    return (vout / VOUT_MAX) * (PRESSURE_MAX - PRESSURE_MIN) + PRESSURE_MIN;
}

/* Append a timestamped pressure reading to the log file. */
static int log_pressure(float pressure)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "log_pressure: cannot open %s: %s\n",
                LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "log_pressure: localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "log_pressure: strftime failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s, %.2f kPa\n", ts, pressure) < 0) {
        fprintf(stderr, "log_pressure: write failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "log_pressure: close failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                ADS1115_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /* Verify ADS1115 is present by reading the config register. */
    uint16_t cfg;
    if (ads1115_read_reg(fd, ADS1115_REG_CONFIG, &cfg) != 0) {
        fprintf(stderr, "ADS1115 not responding on 0x%02X\n", ADS1115_ADDR);
        close(fd);
        return EXIT_FAILURE;
    }

    printf("ADS1115 detected (config=0x%04X). Starting pressure logging (1 Hz)...\n",
           cfg);

    while (g_running) {
        int16_t raw;
        if (ads1115_read_ain0(fd, &raw) != 0) {
            fprintf(stderr, "ADC read error – continuing\n");
            sleep(SAMPLE_PERIOD_S);
            continue;
        }

        float pressure = raw_to_pressure(raw);

        if (pressure < PRESSURE_MIN || pressure > PRESSURE_MAX) {
            fprintf(stderr, "Pressure out of range: %.2f kPa (raw=%d)\n",
                    pressure, raw);
        } else {
            if (log_pressure(pressure) != 0)
                fprintf(stderr, "Logging failed\n");
            else
                printf("Pressure: %.2f kPa\n", pressure);
        }

        sleep(SAMPLE_PERIOD_S);
    }

    printf("\nShutting down cleanly.\n");
    close(fd);
    return EXIT_SUCCESS;
}

