                      ADS1115_CFG_PGA_4_096 | ADS1115_CFG_MODE_SS |
                      ADS1115_CFG_DR_128 | ADS1115_CFG_CQUE_NONE;

    if (ads1115_write_reg(fd, ADS1115_REG_CONFIG, config) != 0)
        return -1;

    /* 128 SPS -> ~8 ms conversion; poll OS bit with timeout. */
    for (int i = 0; i < 20; i++) {
        uint16_t cfg;
        if (ads1115_read_reg(fd, ADS1115_REG_CONFIG, &cfg) != 0)
            return -1;
        if (cfg & ADS1115_CFG_OS_BEGIN)
            break;
        usleep(5000);
    }

    uint16_t raw;
    if (ads1115_read_reg(fd, ADS1115_REG_CONVERSION, &raw) != 0)
        return -1;

    *raw_out = (int16_t)raw;
    return 0;
}

/* Convert raw ADC count to pressure (kPa). */
static float raw_to_pressure(int16_t raw)
{
    float vout = ((float)raw / ADC_MAX_COUNT) * ADC_VREF;
    return (vout / VOUT_MAX) * (PRESSURE_MAX - PRESSURE_MIN) + PRESSURE_MIN;
}

/* Append a timestamped pressure reading to the log file. */
static int log_pressure(float pressure)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "log_pressure: cannot open %s: %s\n",
                LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "log_pressure: localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "log_pressure: strftime failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s, %.2f kPa\n", ts, pressure) < 0) {
        fprintf(stderr, "log_pressure: write failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "log_pressure: close failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                ADS1115_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /* Verify ADS1115 is present by reading the config register. */
    uint16_t cfg;
    if (ads1115_read_reg(fd, ADS1115_REG_CONFIG, &cfg) != 0) {
        fprintf(stderr, "ADS1115 not responding on 0x%02X\n", ADS1115_ADDR);
        close(fd);
        return EXIT_FAILURE;
    }

    printf("ADS1115 detected (config=0x%04X). Starting pressure logging (1 Hz)...\n",
           cfg);

    while (g_running) {
        int16_t raw;
        if (ads1115_read_ain0(fd, &raw) != 0) {
            fprintf(stderr, "ADC read error – continuing\n");
            sleep(SAMPLE_PERIOD_S);
            continue;
        }

        float pressure = raw_to_pressure(raw);

        if (pressure < PRESSURE_MIN || pressure > PRESSURE_MAX) {
            fprintf(stderr, "Pressure out of range: %.2f kPa (raw=%d)\n",
                    pressure, raw);
        } else {
            if (log_pressure(pressure) != 0)
                fprintf(stderr, "Logging failed\n");
            else
                printf("Pressure: %.2f kPa\n", pressure);
        }

        sleep(SAMPLE_PERIOD_S);
    }

    printf("\nShutting down cleanly.\n");
    close(fd);
    return EXIT_SUCCESS;
}

