#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define HUMIDITY_THRESHOLD 80.0
#define LOG_FILE "humidity_log.txt"
#define EMAIL_RECIPIENT "recipient@example.com"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3208(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel: %d\n", channel);
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(SPI_CHANNEL, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    return ((rx[1] & 0x0F) << 8) | (rx[2] & 0xFF);
}

static float convert_adc_to_humidity(int adc_value) {
    if (adc_value < 0) return -1.0;
    float humidity = ((float)adc_value / 4095.0) * 100.0;
    if (humidity < 0.0) humidity = 0.0;
    if (humidity > 100.0) humidity = 100.0;
    return humidity;
}

static float convert_adc_to_temperature(int adc_value) {
    if (adc_value < 0) return -100.0;
    float temperature = ((float)adc_value / 4095.0) * 165.0 - 40.0;
    return temperature;
}

static int log_data(float humidity, float temperature) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, humidity, temperature);
    fclose(fp);
    return 0;
}

static void send_email_alert(float humidity, float temperature) {
    char command[512];
    snprintf(command, sizeof(command),
             "echo \"Subject: Humidity Alert\n\nHumidity: %.2f%%, Temperature: %.2fC\" | ssmtp %s",
             humidity, temperature, EMAIL_RECIPIENT);

    int ret = system(command);
    if (ret == -1) {
        perror("Error executing ssmtp command");
    } else if (ret != 0) {
        fprintf(stderr, "ssmtp command failed with exit code %d\n", ret);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction SIGINT");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction SIGTERM");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    printf("Humidity monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = read_mcp3208(0);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            sleep(1);
            continue;
        }

        float humidity = convert_adc_to_humidity(adc_value);
        float temperature = convert_adc_to_temperature(adc_value);

        if (humidity < 0.0 || temperature < -40.0) {
            fprintf(stderr, "Invalid sensor reading (humidity=%.2f, temp=%.2f)\n", humidity, temperature);
            sleep(1);
            continue;
        }

        if (log_data(humidity, temperature) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        if (humidity > HUMIDITY_THRESHOLD) {
            send_email_alert(humidity, temperature);
        }

        sleep(1);
    }

    spiClose(spi_handle);
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return 0;
}

