#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_MODE        SPI_MODE_0
#define SPI_BITS        8
#define SPI_SPEED       1000000
#define MCP3208_CHANNEL 0
#define LOG_FILE        "temperature_log.csv"
#define SAMPLE_PERIOD   1
#define VREF            3.3f
#define ADC_MAX         4095.0f
#define TEMP_MIN        -40.0f
#define TEMP_MAX        125.0f

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;
static FILE *g_log_fp = NULL;
static struct gpiod_chip *g_chip = NULL;
static struct gpiod_line *g_ce0 = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int spi_init(void)
{
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI speed: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    return 0;
}

static int gpio_init(void)
{
    g_chip = gpiod_chip_open_by_name("gpiochip4");
    if (!g_chip) {
        fprintf(stderr, "Error opening gpiochip4: %s\n", strerror(errno));
        return -1;
    }

    g_ce0 = gpiod_chip_get_line(g_chip, 8);
    if (!g_ce0) {
        fprintf(stderr, "Error getting GPIO8 (CE0): %s\n", strerror(errno));
        gpiod_chip_close(g_chip);
        g_chip = NULL;
        return -1;
    }

    if (gpiod_line_request_output(g_ce0, "mcp3208-ce0", 1) < 0) {
        fprintf(stderr, "Error requesting GPIO8 as output: %s\n", strerror(errno));
        gpiod_chip_close(g_chip);
        g_chip = NULL;
        g_ce0 = NULL;
        return -1;
    }

    return 0;
}

static int read_mcp3208(uint16_t *adc_value)
{
    if (!adc_value) return -1;

    uint8_t tx[3] = { 0x01, (uint8_t)(0x80 | (MCP3208_CHANNEL << 4)), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (gpiod_line_set_value(g_ce0, 0) < 0) {
        fprintf(stderr, "Error asserting CE0: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Error during SPI transfer: %s\n", strerror(errno));
        gpiod_line_set_value(g_ce0, 1);
        return -1;
    }

    if (gpiod_line_set_value(g_ce0, 1) < 0) {
        fprintf(stderr, "Error deasserting CE0: %s\n", strerror(errno));
        return -1;
    }

    *adc_value = ((uint16_t)(rx[1] & 0x0F) << 8) | rx[2];
    return 0;
}

static float adc_to_celsius(uint16_t adc_value)
{
    float voltage = ((float)adc_value / ADC_MAX) * VREF;
    return (voltage - 0.5f) * 100.0f;
}

static int log_temperature(float temperature)
{
    if (!g_log_fp) {
        fprintf(stderr, "Log file not open.\n");
        return -1;
    }

    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (fprintf(g_log_fp, "%s,%.2f\n", timestamp, temperature) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    fflush(g_log_fp);
    return 0;
}

static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    if (g_ce0) {
        gpiod_line_release(g_ce0);
        g_ce0 = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (spi_init() < 0) {
        return 1;
    }

    if (gpio_init() < 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
        return 1;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    fseek(g_log_fp, 0, SEEK_END);
    long file_size = ftell(g_log_fp);
    if (file_size == 0) {
        fprintf(g_log_fp, "timestamp,temperature_celsius\n");
        fflush(g_log_fp);
    }

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        uint16_t adc_value = 0;

        if (read_mcp3208(&adc_value) < 0) {
            fprintf(stderr, "Error reading ADC value.\n");
            sleep(SAMPLE_PERIOD);
            continue;
        }

        float temperature = adc_to_celsius(adc_value);

        if (temperature < TEMP_MIN || temperature > TEMP_MAX) {
            fprintf(stderr, "Warning: Temperature out of range: %.2f C\n", temperature);
        }

        if (log_temperature(temperature) < 0) {
            fprintf(stderr, "Error logging temperature.\n");
        }

        sleep(SAMPLE_PERIOD);
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return 0;
}

