        g_ce0 = NULL;
        return -1;
    }

    return 0;
}

static int read_mcp3208(uint16_t *adc_value)
{
    if (!adc_value) return -1;

    uint8_t tx[3] = { 0x01, (uint8_t)(0x80 | (MCP3208_CHANNEL << 4)), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (gpiod_line_set_value(g_ce0, 0) < 0) {
        fprintf(stderr, "Error asserting CE0: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Error during SPI transfer: %s\n", strerror(errno));
        gpiod_line_set_value(g_ce0, 1);
        return -1;
    }

    if (gpiod_line_set_value(g_ce0, 1) < 0) {
        fprintf(stderr, "Error deasserting CE0: %s\n", strerror(errno));
        return -1;
    }

    *adc_value = ((uint16_t)(rx[1] & 0x0F) << 8) | rx[2];
    return 0;
}

static float adc_to_celsius(uint16_t adc_value)
{
    float voltage = ((float)adc_value / ADC_MAX) * VREF;
    return (voltage - 0.5f) * 100.0f;
}

static int log_temperature(float temperature)
{
    if (!g_log_fp) {
        fprintf(stderr, "Log file not open.\n");
        return -1;
    }

    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (fprintf(g_log_fp, "%s,%.2f\n", timestamp, temperature) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    fflush(g_log_fp);
    return 0;
}

static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    if (g_ce0) {
        gpiod_line_release(g_ce0);
        g_ce0 = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (spi_init() < 0) {
        return 1;
    }

    if (gpio_init() < 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
        return 1;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    fseek(g_log_fp, 0, SEEK_END);
    long file_size = ftell(g_log_fp);
    if (file_size == 0) {
        fprintf(g_log_fp, "timestamp,temperature_celsius\n");
        fflush(g_log_fp);
    }

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        uint16_t adc_value = 0;

        if (read_mcp3208(&adc_value) < 0) {
            fprintf(stderr, "Error reading ADC value.\n");
            sleep(SAMPLE_PERIOD);
            continue;
        }

        float temperature = adc_to_celsius(adc_value);

        if (temperature < TEMP_MIN || temperature > TEMP_MAX) {
            fprintf(stderr, "Warning: Temperature out of range: %.2f C\n", temperature);
        }

        if (log_temperature(temperature) < 0) {
            fprintf(stderr, "Error logging temperature.\n");
        }

        sleep(SAMPLE_PERIOD);
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return 0;
}

code:
/*
 * ADXL335 + MCP3008 impact logger for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   ADXL335 OUT_X -> MCP3008 CH0
 *   ADXL335 OUT_Y -> MCP3008 CH1
 *   ADXL335 OUT_Z -> MCP3008 CH2
 *   MCP3008 CLK  -> GPIO11 (SPI0 SCLK)
 *   MCP3008 DOUT -> GPIO9  (SPI0 MISO)
 *   MCP3008 DIN  -> GPIO10 (SPI0 MOSI)
 *   MCP3008 CS   -> GPIO8  (SPI0 CE0)
 *   MCP3008 VDD  -> 3.3 V, VREF -> 3.3 V, AGND/DGND -> GND
 *
 * Build: gcc -O2 -Wall -o impact_logger impact_logger.c -lpigpio -lrt
 * Run:   sudo ./impact_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL    0          /* SPI0 CE0 (GPIO8) */
#define SPI_SPEED      1000000    /* 1 MHz */
#define SPI_FLAGS      0          /* Mode 0, active-low CS handled by pigpio */

#define X_CHANNEL      0
#define Y_CHANNEL      1
#define Z_CHANNEL      2

#define SAMPLE_PERIOD_US 10000   /* 100 Hz */
#define LOG_FILE_NAME    "impact_log.txt"

#define ADC_MAX          1023      /* 10-bit MCP3008 */
#define ADC_MIN          0

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_file = NULL;
static int g_spi_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* MCP3008 single-ended read                                           */
/* ------------------------------------------------------------------ */
/*
 * MCP3008 SPI protocol (3-byte transfer, mode 0, MSB-first):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (single-ended + channel, upper nibble)
 *   tx[2] = 0x00                       (clock out remaining bits)
 *   rx[1] bits 1..0 + rx[2] bits 7..0  -> 10-bit result
 */
static int mcp3008_read(int spi_handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "spiXfer failed on channel %d (ret=%d)\n", channel, ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return adc_value;
}

/* ------------------------------------------------------------------ */
/* Impact detection                                                    */
/* ------------------------------------------------------------------ */
static int detect_impact(int x, int y, int z, int threshold)
{
    return (x > threshold || y > threshold || z > threshold);
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, int x, int y, int z)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(fp, "%s,%d,%d,%d\n", timestamp, x, y, z);
    fflush(fp);
}

static void log_impact(FILE *fp)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(fp, "%s,IMPACT DETECTED\n", timestamp);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init ------------------------------------------------- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- SPI open ---------------------------------------------------- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle=%d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Log file ---------------------------------------------------- */
    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (g_log_file == NULL) {
        perror("fopen(" LOG_FILE_NAME ")");
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signal handling --------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Impact logger started. Press Ctrl+C to exit.\n");

    /* --- Main loop --------------------------------------------------- */
    int threshold = 500;  /* configurable threshold (raw ADC units) */

    while (g_running) {
        int x = mcp3008_read(g_spi_handle, X_CHANNEL);
        int y = mcp3008_read(g_spi_handle, Y_CHANNEL);
        int z = mcp3008_read(g_spi_handle, Z_CHANNEL);

        if (x < 0 || y < 0 || z < 0) {
            fprintf(stderr, "ADC read error — skipping sample\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        if (x < ADC_MIN || x > ADC_MAX ||
            y < ADC_MIN || y > ADC_MAX ||
            z < ADC_MIN || z > ADC_MAX) {
            fprintf(stderr, "ADC value out of range: X=%d Y=%d Z=%d\n", x, y, z);
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        log_data(g_log_file, x, y, z);

        if (detect_impact(x, y, z, threshold)) {
            log_impact(g_log_file);
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

