/*
 * Si1172-A30-GMR Optical Heart Rate Sensor reader for Raspberry Pi Zero W
 *
 * NOTE: The Si1172 requires a proprietary algorithm from Silicon Labs
 *       to convert raw PPG samples into meaningful HR and SpO2 values.
 *       This program reads the 16-bit IR and RED ADC values as proxy
 *       data and logs them as "HR" and "SpO2" in the CSV file.
 *       A real deployment requires the full Si117x SDK and calibration.
 *
 * Wiring:
 *   Si1172 SDA  -> GPIO2 (I2C bus 1 SDA)
 *   Si1172 SCL  -> GPIO3 (I2C bus 1 SCL)
 *   Si1172 VDD  -> 3.3 V
 *   Si1172 GND  -> GND
 *
 * Build: gcc -O2 -Wall -o si1172_log si1172_log.c -li2c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x60
#define LOG_FILE       "biometric_log.csv"
#define SAMPLE_PERIOD  1.0   /* seconds */

/* Si1172 register addresses (from datasheet) */
#define REG_PART_ID     0x00
#define REG_HW_ID       0x01
#define REG_SEQ_ID      0x02
#define REG_INT_CFG     0x03
#define REG_INT_EN      0x04
#define REG_IRQ_STATUS  0x05
#define REG_HW_KEY      0x07
#define REG_MEAS_RATE0  0x08
#define REG_MEAS_RATE1  0x09
#define REG_ALS_RATE    0x0A
#define REG_ALS_IR_ADCMUX 0x0B
#define REG_ALS_RED_ADCMUX 0x0C
#define REG_ALS_GREEN_ADCMUX 0x0D
#define REG_ALS_WHITE_ADCMUX 0x0E
#define REG_PS_ADCMUX   0x0F
#define REG_PS_LED21    0x10
#define REG_PS_LED3     0x11
#define REG_PS1_ADC_GAIN 0x12
#define REG_PS2_ADC_GAIN 0x13
#define REG_PS3_ADC_GAIN 0x14
#define REG_PS1_ADC_MISC 0x15
#define REG_PS2_ADC_MISC 0x16
#define REG_PS3_ADC_MISC 0x17
#define REG_ALS_IR_ADC_GAIN 0x18
#define REG_ALS_RED_ADC_GAIN 0x19
#define REG_ALS_GREEN_ADC_GAIN 0x1A
#define REG_ALS_WHITE_ADC_GAIN 0x1B
#define REG_ALS_IR_ADC_MISC 0x1C
#define REG_ALS_RED_ADC_MISC 0x1D
#define REG_ALS_GREEN_ADC_MISC 0x1E
#define REG_ALS_WHITE_ADC_MISC 0x1F
#define REG_ALS_IR_DATA0 0x20
#define REG_ALS_IR_DATA1 0x21
#define REG_ALS_RED_DATA0 0x22
#define REG_ALS_RED_DATA1 0x23
#define REG_ALS_GREEN_DATA0 0x24
#define REG_ALS_GREEN_DATA1 0x25
#define REG_ALS_WHITE_DATA0 0x26
#define REG_ALS_WHITE_DATA1 0x27
#define REG_PS1_DATA0   0x28
#define REG_PS1_DATA1   0x29
#define REG_PS2_DATA0   0x2A
#define REG_PS2_DATA1   0x2B
#define REG_PS3_DATA0   0x2C
#define REG_PS3_DATA1   0x2D
#define REG_PARAM_WR    0x17
#define REG_COMMAND     0x18

/* Si1172 command codes */
#define CMD_RESET       0x01
#define CMD_PS_FORCE    0x05
#define CMD_ALS_FORCE   0x06
#define CMD_PSALS_FORCE 0x07
#define CMD_PS_PAUSE    0x0A
#define CMD_ALS_PAUSE   0x0B
#define CMD_PSALS_PAUSE 0x0C
#define CMD_PS_AUTO     0x0D
#define CMD_ALS_AUTO    0x0E
#define CMD_PSALS_AUTO  0x0F

/* Expected PART_ID for Si1172-A30 */
#define EXPECTED_PART_ID 0x72

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int handle, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(handle, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int handle, uint8_t reg, uint8_t *value)
{
    if (write(handle, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(handle, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int handle, uint8_t reg, uint16_t *value)
{
    uint8_t buf[2];
    if (write(handle, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(handle, buf, 2) != 2) {
        fprintf(stderr, "I2C read16 from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *value = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Si1172 driver                                                       */
/* ------------------------------------------------------------------ */
static int si1172_reset(int handle)
{
    if (i2c_write_reg8(handle, REG_COMMAND, CMD_RESET) < 0)
        return -1;
    gpioDelay(10000); /* 10 ms reset settling */
    return 0;
}

static int si1172_init(int handle)
{
    uint8_t part_id = 0;

    if (si1172_reset(handle) < 0)
        return -1;

    /* Read PART_ID to confirm sensor is present */
