    /* Start autonomous PS+ALS measurement */
    if (i2c_write_reg8(handle, REG_COMMAND, CMD_PSALS_AUTO) < 0)
        return -1;

    return 0;
}

static int si1172_read_data(int handle, uint16_t *ir, uint16_t *red)
{
    if (i2c_read_reg16(handle, REG_ALS_IR_DATA0, ir) < 0)
        return -1;
    if (i2c_read_reg16(handle, REG_ALS_RED_DATA0, red) < 0)
        return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_sample(FILE *fp, time_t ts, uint16_t ir, uint16_t red,
                       int hr, int spo2, int error_code)
