    fprintf(fp, "%ld,%d,%d,%d,%d\n", (long)ts, hr, spo2, error_code);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
