#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0
#define ADC_CHANNEL 0
#define FLOW_LOG_FILE "flow_log.csv"
#define MIN_FLOW_RATE 0.0
#define MAX_FLOW_RATE 5.0
#define SAMPLE_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int spi_handle, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    if (spiXfer(spi_handle, (char *)tx, (char *)rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static double adc_to_flow_rate(int adc_value) {
    return (double)adc_value * (MAX_FLOW_RATE / 1023.0);
}

static int log_flow_rate(double flow_rate) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return -1;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    if (fprintf(log_file, "%s.%06ld,%.2f\n", timestamp, ts.tv_nsec / 1000, flow_rate) < 0) {
        perror("fprintf");
        return -1;
    }

    if (fflush(log_file) != 0) {
        perror("fflush");
        return -1;
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(FLOW_LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    while (running) {
        int adc_value = read_mcp3008(spi_handle, ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read failed\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        if (adc_value == 0 || adc_value == 1023) {
            fprintf(stderr, "Sensor absent or disconnected (ADC value: %d)\n", adc_value);
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        double flow_rate = adc_to_flow_rate(adc_value);

        if (flow_rate < MIN_FLOW_RATE || flow_rate > MAX_FLOW_RATE) {
            fprintf(stderr, "Flow rate out of range: %.2f L/min\n", flow_rate);
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        if (log_flow_rate(flow_rate) != 0) {
            fprintf(stderr, "Logging failed\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }

    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

