#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define ICP10125_ADDR 0x77
#define CMD_MEASURE_HP 0x40
#define MEASURE_DELAY_MS 50
#define SAMPLE_INTERVAL_S 5
#define LOG_FILE "environmental_data.csv"

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static void msleep(unsigned ms) {
    struct timespec ts = { ms / 1000, (long)(ms % 1000) * 1000000L };
    nanosleep(&ts, NULL);
}

static int i2c_write_cmd(int fd, uint8_t cmd) {
    if (write(fd, &cmd, 1) != 1) {
        perror("i2c write failed");
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, int len) {
    int total = 0;
    while (total < len) {
        int n = read(fd, buf + total, len - total);
        if (n < 0) {
            perror("i2c read failed");
            return -1;
        }
        if (n == 0) {
            fprintf(stderr, "i2c read: unexpected EOF\n");
            return -1;
        }
        total += n;
    }
    return 0;
}

static int read_icp10125(int fd, float *temp_c, float *press_pa) {
    uint8_t buf[6];

    if (i2c_write_cmd(fd, CMD_MEASURE_HP) < 0) return -1;
    msleep(MEASURE_DELAY_MS);

    if (i2c_read_bytes(fd, buf, 6) < 0) return -1;

    uint16_t raw_p = ((uint16_t)buf[0] << 8) | buf[1];
    uint16_t raw_t = ((uint16_t)buf[3] << 8) | buf[4];

    *temp_c = (float)raw_t / 100.0f;
    *press_pa = (float)raw_p / 100.0f;
    return 0;
}

static void log_data(FILE *fp, float temp_c, float press_pa) {
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f,%.2f\n", ts, temp_c, press_pa);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ICP10125_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(i2c_fd);
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("fopen log");
        close(i2c_fd);
        return 1;
    }

    printf("ICP-10125 logger started. Press Ctrl+C to stop.\n");

    while (running) {
        float temp_c, press_pa;
        if (read_icp10125(i2c_fd, &temp_c, &press_pa) == 0) {
            printf("Temperature: %.2f C, Pressure: %.2f Pa\n", temp_c, press_pa);
            log_data(log_fp, temp_c, press_pa);
        } else {
            fprintf(stderr, "Sensor read error; retrying in %d s\n", SAMPLE_INTERVAL_S);
            log_data(log_fp, -999.0f, -999.0f);
        }
        sleep(SAMPLE_INTERVAL_S);
    }

    printf("\nShutting down...\n");
    if (log_fp) fclose(log_fp);
    if (i2c_fd >= 0) close(i2c_fd);
    return 0;
}

