#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0

#define MIC1_CHANNEL 0
#define MIC2_CHANNEL 1

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mic(int spi_handle, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    if (spiXfer(spi_handle, (char *)tx, (char *)rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed on channel %d\n", channel);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <gain1> <gain2>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int gain1 = atoi(argv[1]);
    int gain2 = atoi(argv[2]);

    if (gain1 < 0 || gain1 > 100 || gain2 < 0 || gain2 > 100) {
        fprintf(stderr, "Gain values must be between 0 and 100\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("gain1,gain2,cancelled\n");

    while (running) {
        int mic1 = read_mic(spi_handle, MIC1_CHANNEL);
        int mic2 = read_mic(spi_handle, MIC2_CHANNEL);

        if (mic1 < 0 || mic2 < 0) {
            fprintf(stderr, "Error reading microphone data\n");
            break;
        }

        int cancelled = mic1 - (mic2 * gain2 / 100);
        printf("%d,%d,%d\n", gain1, gain2, cancelled);
        fflush(stdout);

        gpioDelay(10000);
    }

    spiClose(spi_handle);
    gpioTerminate();
    return EXIT_SUCCESS;

