#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define SPI_CHANNEL    0
#define SPI_SPEED      1000000
#define SPI_FLAGS      0
#define LED_GPIO       17
#define WATER_LEVEL_GPIO 0
#define WATER_LEVEL_THRESHOLD_HIGH 75
#define WATER_LEVEL_THRESHOLD_LOW  70
#define SAMPLE_INTERVAL_US 5000000
#define LED_HYSTERESIS_DELAY_US 100000

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;
static FILE *g_json_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, (char *)tx, (char *)rx, 3);
    if (ret < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", pigpio_error(ret));
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float calculate_water_level(int adc_value) {
    if (adc_value < 0) return -1.0f;
    return 100.0f - ((float)adc_value / 1023.0f) * 100.0f;
}

static void log_water_level(float water_level) {
    if (g_json_file == NULL) return;

    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);
    long ms = ts.tv_nsec / 1000000;

    fprintf(g_json_file, "{\"timestamp\": \"%s.%03ld\", \"water_level\": %.2f}\n",
            timestamp, ms, water_level);
    fflush(g_json_file);
}

static void control_led(float water_level) {
    static int led_state = 0;

    if (water_level > WATER_LEVEL_THRESHOLD_HIGH && led_state == 0) {
        gpioWrite(LED_GPIO, 1);
        led_state = 1;
        printf("LED ON (Water level: %.2f%%)\n", water_level);
    } else if (water_level < WATER_LEVEL_THRESHOLD_LOW && led_state == 1) {
        gpioWrite(LED_GPIO, 0);
        led_state = 0;
        printf("LED OFF (Water level: %.2f%%)\n", water_level);
    }
}

static void cleanup(void) {
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    if (g_json_file != NULL) {
        fclose(g_json_file);
        g_json_file = NULL;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %s\n", pigpio_error(g_spi_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED GPIO %d as output\n", LED_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    g_json_file = fopen("water_levels.json", "w");
    if (g_json_file == NULL) {
        perror("Failed to open water_levels.json");
        cleanup();
        return EXIT_FAILURE;
    }

    fprintf(g_json_file, "[\n");
    fflush(g_json_file);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Water level monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int adc_value = read_mcp3008(WATER_LEVEL_GPIO);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value, skipping sample.\n");
        } else {
            float water_level = calculate_water_level(adc_value);
            if (water_level < 0.0f) {
                fprintf(stderr, "Error calculating water level, skipping sample.\n");
            } else {
                log_water_level(water_level);
                control_led(water_level);
                printf("Water level: %.2f%%\n", water_level);
            }
        }

        for (int i = 0; i < 50 && g_running; i++) {
            gpioDelay(LED_HYSTERESIS_DELAY_US);
        }
    }

    printf("\nShutting down...\n");
    fprintf(g_json_file, "\n]\n");
    fflush(g_json_file);
    cleanup();
    return EXIT_SUCCESS;
}

