#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define DEFAULT_SPI_CHANNEL 0
#define DEFAULT_ADC_CHANNEL 0
#define DEFAULT_MIN_CALIBRATION_VALUE 200
#define DEFAULT_MAX_CALIBRATION_VALUE 800
#define DEFAULT_MOISTURE_THRESHOLD 30
#define DEFAULT_LOGGING_INTERVAL 60
#define DEFAULT_RECIPIENT_EMAIL "recipient@example.com"
#define DEFAULT_MSMTP_CONFIG_FILE "/etc/msmtprc"
#define DATA_FILE "plant_data.txt"
#define SPI_SPEED 500000
#define MOISTURE_MIN 0.0f
#define MOISTURE_MAX 100.0f

static int spi_channel = DEFAULT_SPI_CHANNEL;
static int adc_channel = DEFAULT_ADC_CHANNEL;
static int min_calibration_value = DEFAULT_MIN_CALIBRATION_VALUE;
static int max_calibration_value = DEFAULT_MAX_CALIBRATION_VALUE;
static int moisture_threshold = DEFAULT_MOISTURE_THRESHOLD;
static int logging_interval = DEFAULT_LOGGING_INTERVAL;
static char *recipient_email = DEFAULT_RECIPIENT_EMAIL;
static char *msmtp_config_file = DEFAULT_MSMTP_CONFIG_FILE;
static int spi_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }
    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };
    if (spiXfer(spi_handle, (char *)tx, (char *)rx, 3) != 3) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float calculate_moisture_level(int adc_value) {
    if (max_calibration_value <= min_calibration_value) {
        fprintf(stderr, "Error: Invalid calibration values (max <= min)\n");
        return -1.0f;
    }
    float moisture = ((float)(adc_value - min_calibration_value) /
                      (float)(max_calibration_value - min_calibration_value)) *
                     (MOISTURE_MAX - MOISTURE_MIN) + MOISTURE_MIN;
    if (moisture < MOISTURE_MIN) moisture = MOISTURE_MIN;
    if (moisture > MOISTURE_MAX) moisture = MOISTURE_MAX;
    return moisture;
}

static void log_data(float moisture_level) {
    FILE *fp = fopen(DATA_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error: Could not open data file %s\n", DATA_FILE);
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, %.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, moisture_level);
    fclose(fp);
}

static void send_email_alert(float moisture_level) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    char command[512];
    snprintf(command, sizeof(command),
             "echo \"Subject: Plant Moisture Alert\n\n"
             "Plant moisture level is below threshold: %.2f%% at %s\" | "
             "msmtp -C %s %s",
             moisture_level, timestamp, msmtp_config_file, recipient_email);
    FILE *fp = popen(command, "r");
    if (!fp) {
        fprintf(stderr, "Error: Failed to execute msmtp command\n");
        return;
    }
    int status = pclose(fp);
    if (status != 0) {
        fprintf(stderr, "Error: msmtp returned non-zero status %d\n", status);
    }
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "s:a:m:M:t:i:e:c:h")) != -1) {
        switch (opt) {
            case 's': spi_channel = atoi(optarg); break;
            case 'a': adc_channel = atoi(optarg); break;
            case 'm': min_calibration_value = atoi(optarg); break;
            case 'M': max_calibration_value = atoi(optarg); break;
            case 't': moisture_threshold = atoi(optarg); break;
            case 'i': logging_interval = atoi(optarg); break;
            case 'e': recipient_email = optarg; break;
            case 'c': msmtp_config_file = optarg; break;
            case 'h':
            default:
                fprintf(stderr, "Usage: %s [-s spi_channel] [-a adc_channel] "
                                "[-m min_calibration] [-M max_calibration] "
                                "[-t moisture_threshold] [-i logging_interval] "
                                "[-e recipient_email] [-c msmtp_config_file]\n",
                        argv[0]);
                return EXIT_FAILURE;
        }
    }
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }
    spi_handle = spiOpen(spi_channel, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed on channel %d\n", spi_channel);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    printf("Plant monitoring started. Logging every %d seconds.\n", logging_interval);
    while (!terminate) {
        int adc_value = read_mcp3008(adc_channel);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
        } else {
            float moisture_level = calculate_moisture_level(adc_value);
            if (moisture_level < 0.0f) {
                fprintf(stderr, "Error: Failed to calculate moisture level\n");
            } else {
                log_data(moisture_level);
                if (moisture_level < (float)moisture_threshold) {
                    send_email_alert(moisture_level);
                }
            }
        }
        for (int i = 0; i < logging_interval && !terminate; i++) {
            sleep(1);
        }
    }
    cleanup();
    printf("Plant monitoring stopped.\n");
    return EXIT_SUCCESS;
}

