/*
 * soil_moisture.c — Raspberry Pi 3 Model B+
 *
 * Reads a Keyes KY-036 analog soil-moisture sensor through an MCP3008
 * 10-bit SPI ADC (single-ended channel 0) and logs timestamped readings
 * to soil_moisture.log.
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3 V (Pin 1)
 *   MCP3008 VREF -> 3.3 V (Pin 1)
 *   MCP3008 AGND -> GND
 *   MCP3008 DGND -> GND
 *   MCP3008 CLK  -> GPIO11 (SPI0 SCLK)
 *   MCP3008 DOUT -> GPIO9  (SPI0 MISO)
 *   MCP3008 DIN  -> GPIO10 (SPI0 MOSI)
 *   MCP3008 CS   -> GPIO8  (SPI0 CE0)
 *   KY-036 A0    -> MCP3008 CH0
 *   KY-036 VCC   -> 3.3 V
 *   KY-036 GND   -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o soil_moisture soil_moisture.c
 *
 * Run:
 *   ./soil_moisture [interval_seconds]
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U   /* 1 MHz */
#define SPI_BITS        8
#define SPI_MODE        0
#define ADC_CHANNEL     0          /* MCP3008 single-ended channel 0 */
#define LOG_FILE        "soil_moisture.log"
#define SAMPLE_INTERVAL 1          /* seconds */
#define ADC_MAX_VALUE   1023       /* 10-bit ADC */

static volatile sig_atomic_t g_running = 1;
static int  g_spi_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;          /* tell main loop to exit cleanly          */
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1)
        perror("warning: sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) == -1)
        perror("warning: sigaction(SIGTERM)");
}

/* ------------------------------------------------------------------ */
/* MCP3008                                                             */
/* ------------------------------------------------------------------ */
/*
 * MCP3008 single-ended read (3-byte transfer):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
 *   tx[2] = 0x00                       (clock out remaining bits)
 * Result: bits 9..0 are in rx[1] (low 2 bits) and rx[2] (8 bits).
 */
static int mcp3008_read(int fd, uint8_t channel)
{
    if (channel > 7) {
        fprintf(stderr, "error: invalid MCP3008 channel %u\n", channel);
        return -1;
    }

    uint8_t tx[3] = {
        0x01,
        (uint8_t)((0x08 | channel) << 4),
        0x00
    };
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = sizeof(tx);
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        fprintf(stderr, "error: SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_reading(FILE *fp, int adc_value, float moisture_pct)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "warning: time() failed: %s\n", strerror(errno));
        return;
    }

    struct tm tm_local;
    if (localtime_r(&now, &tm_local) == NULL) {
        fprintf(stderr, "warning: localtime_r() failed\n");
        return;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_local) == 0) {
        fprintf(stderr, "warning: strftime() failed\n");
        return;
    }

    if (fprintf(fp, "%s, ADC: %d, Moisture: %.2f%%\n",
                ts, adc_value, moisture_pct) < 0) {
        fprintf(stderr, "error: fprintf to log failed: %s\n", strerror(errno));
        return;
    }

    if (fflush(fp) != 0)
        fprintf(stderr, "warning: fflush failed: %s\n", strerror(errno));
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    unsigned int interval = SAMPLE_INTERVAL;

    if (argc > 1) {
        char *endptr = NULL;
        errno = 0;
        long val = strtol(argv[1], &endptr, 10);
        if (errno != 0 || endptr == argv[1] || *endptr != '\0' || val <= 0) {
            fprintf(stderr, "error: invalid interval '%s' (must be positive integer)\n",
                    argv[1]);
            return EXIT_FAILURE;
        }
        interval = (unsigned int)val;
    }

    install_signal_handlers();

    /* Open SPI device */
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "error: cannot open %s: %s\n",
                SPI_DEVICE, strerror(errno));
        return EXIT_FAILURE;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "error: SPI_IOC_WR_MODE: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "error: SPI_IOC_WR_BITS_PER_WORD: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "error: SPI_IOC_WR_MAX_SPEED_HZ: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "error: cannot open %s: %s\n",
                LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Soil moisture monitoring started.\n");
    printf("  SPI device : %s @ %u Hz, mode %u\n",
           SPI_DEVICE, SPI_SPEED_HZ, SPI_MODE);
    printf("  ADC channel: %u\n", ADC_CHANNEL);
    printf("  Log file   : %s\n", LOG_FILE);
    printf("  Interval   : %u second%s\n",
           interval, interval == 1 ? "" : "s");
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        int adc_value = mcp3008_read(g_spi_fd, ADC_CHANNEL);

        if (adc_value < 0) {
            fprintf(stderr, "warning: ADC read failed; will retry next cycle\n");
        } else {
            float moisture_pct = ((float)adc_value / (float)ADC_MAX_VALUE) * 100.0f;
            log_reading(g_log_fp, adc_value, moisture_pct);
            printf("ADC: %4d  Moisture: %5.2f%%\n", adc_value, moisture_pct);
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (unsigned int i = 0; i < interval && g_running; i++)
            sleep(1);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

