    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI max speed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    *fd_out = fd;
    return 0;
}

static int read_mcp3008(int fd, int channel, uint16_t *adc_value) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    uint8_t tx_buf[3] = {0};
    uint8_t rx_buf[3] = {0};

    /* MCP3008 single-ended mode: start bit, SGL/DIFF=1, D2 D1 D0 */
    tx_buf[0] = 0x01;  /* Start bit */
    tx_buf[1] = (0x08 | (channel & 0x07)) << 4; /* Single-ended, channel */
    tx_buf[2] = 0x00;

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx_buf;
    tr.rx_buf = (unsigned long)rx_buf;
    tr.len = 3;
    tr.speed_hz = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS_PER_WORD;
    tr.delay_usecs = 0;
    tr.cs_change = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Error during SPI transfer: %s\n", strerror(errno));
        return -1;
    }

    /* Extract 10-bit ADC value from the response */
    *adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
    return 0;
}

static float calculate_moisture_percentage(uint16_t adc_value) {
    /* DFRobot Soil Moisture Sensor v2.0:
     *   - 0V (dry)  -> 0%
     *   - 3.3V (wet) -> 100%
     *   - 10-bit ADC: 0-1023
     */
    return ((float)adc_value / 1023.0f) * 100.0f;
}

int main(void) {
    int fd = -1;

    if (setup_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    if (spi_init(&fd) != 0) {
        return EXIT_FAILURE;
    }

    printf("Soil Moisture Sensor Data Logger\n");
    printf("SPI device: %s | Speed: %d Hz | Mode: %d\n", SPI_DEVICE, SPI_SPEED_HZ, SPI_MODE);
    printf("Reading channel %d every %d seconds. Press Ctrl+C to exit.\n\n", ADC_CHANNEL, SAMPLE_INTERVAL_SEC);

    while (g_running) {
        uint16_t adc_value = 0;

        if (read_mcp3008(fd, ADC_CHANNEL, &adc_value) != 0) {
            fprintf(stderr, "Failed to read ADC value. Retrying in %d seconds...\n", SAMPLE_INTERVAL_SEC);
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        float moisture_percentage = calculate_moisture_percentage(adc_value);

        printf("Raw ADC Value: %u, Moisture Percentage: %.2f%%\n", adc_value, moisture_percentage);
        fflush(stdout);

        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nExiting gracefully...\n");

    if (fd >= 0) {
        if (close(fd) < 0) {
            fprintf(stderr, "Error closing SPI device: %s\n", strerror(errno));
        }
    }

    return EXIT_SUCCESS;

