/*
 * MLX90823 Pressure Sensor Reader via MCP3008 ADC on Raspberry Pi 4 Model B
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3V (Pin 1)
 *   MCP3008 VREF -> 3.3V (Pin 1)
 *   MCP3008 AGND -> GND  (Pin 6)
 *   MCP3008 DGND -> GND  (Pin 6)
 *   MCP3008 CLK  -> GPIO11 (SCLK, Pin 23)
 *   MCP3008 DOUT -> GPIO9  (MISO, Pin 21)
 *   MCP3008 DIN  -> GPIO10 (MOSI, Pin 19)
 *   MCP3008 CS   -> GPIO8  (CE0,  Pin 24)
 *   MCP3008 CH0  -> MLX90823 analog output
 *
 * Build: gcc -O2 -Wall -o mlx90823_reader mlx90823_reader.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define SPI_CHANNEL    0          /* CE0 on GPIO8 */
#define SPI_SPEED      1000000    /* 1 MHz */
#define SPI_FLAGS      0          /* Mode 0, active-low CE */

#define ADC_CHANNEL    0          /* MCP3008 CH0 */
#define ADC_MAX_VALUE  1023       /* 10-bit ADC */

#define SAMPLE_PERIOD_US 1000000 /* 1 second */

/* Calibration parameters (example values — replace with your sensor's datasheet values) */
#define VREF           3.3f
#define ADC_ZERO       512.0f     /* ADC value at 0 pressure (mid-scale) */
#define ADC_SPAN       200.0f     /* ADC range over full pressure span */
#define PRESSURE_MIN   0.0f       /* Pa */
#define PRESSURE_MAX   100000.0f  /* Pa */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a single-ended sample from the MCP3008.
 * Returns 0 on success and stores the 10-bit value in *adc_value.
 * Returns -1 on SPI transfer failure.
 */
static int read_mcp3008(int spi_handle, int channel, uint16_t *adc_value)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 SPI protocol (Mode 0, MSB-first):
     *   Byte 0: 0x01  (start bit)
     *   Byte 1: (0x08 | channel) << 4  (single-ended + channel select)
     *   Byte 2: 0x00  (don't care, clocks out low 8 bits)
     *
     * Response:
     *   rx[0] = don't care
     *   rx[1] = [null bit][b9 b8] in the low nibble
     *   rx[2] = b7..b0
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int bytes = spiXfer(spi_handle, tx, rx, 3);
    if (bytes != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", bytes);
        return -1;
    }

    uint16_t value = ((uint16_t)(rx[1] & 0x03) << 8) | (uint16_t)(rx[2] & 0xFF);
    *adc_value = value;
    return 0;
}

static float adc_to_pressure(uint16_t adc_value)
{
    float voltage = (float)adc_value * VREF / (float)ADC_MAX_VALUE;
    float pressure = (voltage - (ADC_ZERO * VREF / (float)ADC_MAX_VALUE)) *
                     (PRESSURE_MAX - PRESSURE_MIN) / ADC_SPAN + PRESSURE_MIN;
    return pressure;
}

static void log_pressure(float pressure)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char timestamp[32];

    if (localtime_r(&now, &tm_info) != NULL) {
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);
    } else {
        snprintf(timestamp, sizeof(timestamp), "1970-01-01T00:00:00");
    }

    printf("%s Pressure: %.2f Pa\n", timestamp, pressure);
    fflush(stdout);
}

int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI0 CE0 at 1 MHz, Mode 0 */
    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("MLX90823 Pressure Sensor Reader\n");
    printf("SPI0 CE0 @ %d Hz, MCP3008 CH0\n", SPI_SPEED);
    printf("Press Ctrl+C to exit.\n");

    int consecutive_errors = 0;

    while (g_running) {
        uint16_t adc_value = 0;

        if (read_mcp3008(spi_handle, ADC_CHANNEL, &adc_value) != 0) {
            consecutive_errors++;
            if (consecutive_errors > 10) {
                fprintf(stderr, "Too many SPI errors; aborting.\n");
                break;
            }
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }
        consecutive_errors = 0;

        /* Detect sensor-absent / wiring-fault conditions */
        if (adc_value == 0) {
            fprintf(stderr, "Warning: ADC reads 0 — sensor may be disconnected or V+ is low.\n");
        } else if (adc_value == ADC_MAX_VALUE) {
            fprintf(stderr, "Warning: ADC saturated at VREF — sensor may be shorted or V- is high.\n");
        }

        float pressure = adc_to_pressure(adc_value);
        log_pressure(pressure);

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* Clean resource release on every exit path */
    if (spiClose(spi_handle) != 0) {
        fprintf(stderr, "Warning: spiClose failed\n");
    }
    gpioTerminate();

    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

