    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = 3;
    tr.speed_hz = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs = 0;
    tr.cs_change = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("ioctl(SPI_IOC_MESSAGE)");
        return -1;
    }

    *adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return 0;
}

static void log_data(uint16_t adc_value) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) != NULL) {
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);
    } else {
        snprintf(timestamp, sizeof(timestamp), "UNKNOWN");
    }

    printf("[%s] ADC Channel %d: %u\n", timestamp, MCP3008_CHANNEL, adc_value);
    fflush(stdout);
}

int main(void) {
    int fd = -1;

    if (setup_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    if (spi_init(&fd) != 0) {
        return EXIT_FAILURE;
    }

    printf("MCP3008 Soil Moisture Sensor Reader\n");
    printf("SPI: %s | Mode: %d | Speed: %d Hz | Channel: %d\n",
           SPI_DEVICE, SPI_MODE, SPI_SPEED_HZ, MCP3008_CHANNEL);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (g_running) {
        uint16_t adc_value = 0;

        if (read_mcp3008(fd, MCP3008_CHANNEL, &adc_value) != 0) {
            fprintf(stderr, "Error reading MCP3008. Retrying in %d seconds.\n", SAMPLE_INTERVAL);
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        if (adc_value == 0 || adc_value == 1023) {
            fprintf(stderr, "Warning: ADC value at extreme (%u). Sensor absent or wiring fault?\n", adc_value);
        }

        log_data(adc_value);

        if (g_running) {
            sleep(SAMPLE_INTERVAL);
        }
    }

    printf("\nShutting down...\n");
    if (fd >= 0) {
        close(fd);
    }
    return EXIT_SUCCESS;
}

