        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PUMP_GPIO);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    control_pump(0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioSetTimerFuncEx(0, SAMPLE_INTERVAL_SEC * 1000, timer_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set timer function\n");
        control_pump(0);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
