#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define MAX30102_ADDR 0x57

#define REG_INTR_STATUS_1 0x00
#define REG_INTR_ENABLE_1 0x01
#define REG_FIFO_WR_PTR 0x02
#define REG_OVERFLOW_CTR 0x03
#define REG_FIFO_RD_PTR 0x04
#define REG_FIFO_DATA 0x05
#define REG_FIFO_CONFIG 0x06
#define REG_MODE_CONFIG 0x07
#define REG_SPO2_CONFIG 0x08
#define REG_LED1_PA 0x09
#define REG_LED2_PA 0x0A
#define REG_PART_ID 0xFF

#define EXPECTED_PART_ID 0x15

#define SPO2_THRESHOLD 95
#define HR_THRESHOLD 100

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg(uint8_t reg, uint8_t *val) {
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) return -1;
    *val = (uint8_t)rc;
    return 0;
}

static int i2c_write_reg(uint8_t reg, uint8_t val) {
    return i2cWriteByteData(i2c_handle, reg, val);
}

static int i2c_read_burst(uint8_t reg, uint8_t *buf, uint32_t len) {
    return i2cReadI2CBlockData(i2c_handle, reg, (char *)buf, len);
}

static int max30102_init(void) {
    uint8_t part_id;
    if (i2c_read_reg(REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "Error: Failed to read Part ID register.\n");
        return -1;
    }
    if (part_id != EXPECTED_PART_ID) {
        fprintf(stderr, "Error: Unexpected Part ID 0x%02X (expected 0x%02X). Sensor not present.\n",
                part_id, EXPECTED_PART_ID);
        return -1;
    }

    if (i2c_write_reg(REG_MODE_CONFIG, 0x40) != 0) return -1;
    gpioDelay(10000);

    if (i2c_write_reg(REG_INTR_ENABLE_1, 0x00) != 0) return -1;
    if (i2c_write_reg(REG_FIFO_WR_PTR, 0x00) != 0) return -1;
    if (i2c_write_reg(REG_OVERFLOW_CTR, 0x00) != 0) return -1;
    if (i2c_write_reg(REG_FIFO_RD_PTR, 0x00) != 0) return -1;
    if (i2c_write_reg(REG_FIFO_CONFIG, 0x4F) != 0) return -1;
    if (i2c_write_reg(REG_MODE_CONFIG, 0x03) != 0) return -1;
    if (i2c_write_reg(REG_SPO2_CONFIG, 0x27) != 0) return -1;
    if (i2c_write_reg(REG_LED1_PA, 0x24) != 0) return -1;
    if (i2c_write_reg(REG_LED2_PA, 0x24) != 0) return -1;

    return 0;
}

static int read_spo2_hr(int *spo2, int *hr) {
    uint8_t wr_ptr, rd_ptr;
    if (i2c_read_reg(REG_FIFO_WR_PTR, &wr_ptr) != 0) return -1;
    if (i2c_read_reg(REG_FIFO_RD_PTR, &rd_ptr) != 0) return -1;

    if (wr_ptr == rd_ptr) {
        *spo2 = -1;
        *hr = -1;
        return 0;
    }

    uint8_t buf[64];
    int len = wr_ptr - rd_ptr;
    if (len > 64) len = 64;
    if (i2c_read_burst(REG_FIFO_DATA, buf, len) != len) return -1;

    int ir = 0, red = 0;
    for (int i = 0; i < len; i += 3) {
        ir += (buf[i] << 8) | buf[i + 1];
        red += (buf[i + 2] << 8) | buf[i + 1];
    }

    if (ir == 0) {
        *spo2 = -1;
        *hr = -1;
        return 0;
    }

    int ratio = (red * 100) / ir;
    *spo2 = 110 - (ratio * 2);
    if (*spo2 < 0) *spo2 = 0;
    if (*spo2 > 100) *spo2 = 100;

    *hr = 60 + (ratio / 10);
    if (*hr < 0) *hr = 0;
    if (*hr > 200) *hr = 200;

    return 0;
}

static void log_health_data(int spo2, int hr) {
    FILE *fp = fopen("health_log.txt", "a");
    if (!fp) return;

    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);

    fprintf(fp, "%s, SpO2: %d%%, HR: %dBPM\n", ts, spo2, hr);
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MAX30102_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X.\n", I2C_BUS, MAX30102_ADDR);
        gpioTerminate();
        return 1;
    }

    if (max30102_init() != 0) {
        fprintf(stderr, "Error: MAX30102 initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("MAX30102 initialized. Monitoring SpO2 and HR...\n");

    while (running) {
        int spo2, hr;
        if (read_spo2_hr(&spo2, &hr) != 0) {
            fprintf(stderr, "Error: I2C read failed.\n");
        } else {
            printf("SpO2: %d%%, HR: %dBPM\n", spo2, hr);
            if (spo2 < SPO2_THRESHOLD || hr > HR_THRESHOLD) {
                log_health_data(spo2, hr);
            }
        }
        gpioDelay(1000000);
    }

    printf("\nShutting down...\n");
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

