/*
 * MQ-2 gas sensor monitor via MCP3008 ADC on Raspberry Pi.
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3 V (Pin 1)
 *   MCP3008 VREF -> 3.3 V (Pin 1)
 *   MCP3008 AGND -> GND
 *   MCP3008 DGND -> GND
 *   MCP3008 CLK  -> GPIO11 (SPI0 SCLK)
 *   MCP3008 DOUT -> GPIO9  (SPI0 MISO)
 *   MCP3008 DIN  -> GPIO10 (SPI0 MOSI)
 *   MCP3008 CS   -> GPIO8  (SPI0 CE0)
 *   MCP3008 CH0  -> MQ-2 analog output
 *   Buzzer +     -> GPIO24 (BCM)
 *   Buzzer -     -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o mq2_monitor mq2_monitor.c \
 *       -lpigpio -lrt
 * Run:
 *   sudo ./mq2_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL    0          /* SPI0 CE0 (GPIO8) */
#define SPI_SPEED      1000000    /* 1 MHz */
#define SPI_FLAGS      0          /* Mode 0, active-low CE */

#define BUZZER_GPIO    24         /* BCM */
#define ADC_CHANNEL    0          /* MCP3008 CH0 */

#define THRESHOLD      500        /* 10-bit ADC: 0–1023 */
#define SAMPLE_US      500000     /* 500 ms */

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read a single-ended channel from the MCP3008.
 * Returns 0–1023 on success, -1 on error. */
static int read_mcp3008(int handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, padded)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result: bits 9..0 are in rx[1] (low 2 bits) and rx[2] (8 bits).
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int bytes = spiXfer(handle, tx, rx, 3);
    if (bytes != 3) {
        fprintf(stderr, "spiXfer failed (returned %d)\n", bytes);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return adc_value;
}

/* ------------------------------------------------------------------ */
static int set_buzzer(int state)
{
    if (gpioWrite(BUZZER_GPIO, state) < 0) {
        fprintf(stderr, "gpioWrite(%d, %d) failed\n", BUZZER_GPIO, state);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    /* Ensure buzzer is off before releasing pigpio. */
    gpioWrite(BUZZER_GPIO, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init ------------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- buzzer GPIO setup ------------------------------------------ */
    if (gpioSetMode(BUZZER_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_OUTPUT) failed\n", BUZZER_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (set_buzzer(0) < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- SPI open --------------------------------------------------- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- signal handling -------------------------------------------- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MQ-2 monitor started. Threshold=%d, sampling every %d ms.\n",
           THRESHOLD, SAMPLE_US / 1000);
    printf("Press Ctrl-C to exit.\n");

    /* --- main loop -------------------------------------------------- */
    while (g_running) {
        int adc = read_mcp3008(g_spi_handle, ADC_CHANNEL);
        if (adc < 0) {
            fprintf(stderr, "ADC read error; retrying in 500 ms...\n");
            gpioDelay(SAMPLE_US);
            continue;
        }

        printf("ADC CH%d: %4d  Buzzer: %s\n",
               ADC_CHANNEL, adc,
               (adc >= THRESHOLD) ? "ON" : "OFF");

        if (set_buzzer(adc >= THRESHOLD) < 0) {
            fprintf(stderr, "Buzzer write failed; continuing.\n");
        }

        gpioDelay(SAMPLE_US);
    }

    /* --- graceful shutdown ------------------------------------------ */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

