/*
 * door_lock.c — Raspberry Pi 5 (64-bit Bookworm, kernel 6.6+)
 *
 * Monitors a GP2Y0A21YK0F Sharp IR distance sensor via an ADS1115 ADC
 * on /dev/i2c-1, energizes a 5 V relay on GPIO17 when distance falls
 * below a calibrated threshold, and logs reed-sensor events to
 * /var/log/door_events.log.
 *
 * Wiring:
 *   ADS1115 SDA  -> GPIO2  (BCM)
 *   ADS1115 SCL  -> GPIO3  (BCM)
 *   ADS1115 ADDR -> GND    (I2C address 0x48)
 *   ADS1115 A0   -> GP27   (reed door sensor, active-low, pull-up)
 *   Relay IN     -> GPIO17 (BCM, active-high)
 *
 * Build:  gcc -O2 -Wall -Wextra -o door_lock door_lock.c
 */

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

#define I2C_BUS        "/dev/i2c-1"
#define ADS1115_ADDR   0x48

/* ADS1115 register addresses */
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG     0x01

/* Config-register bit fields */
#define ADS1115_CFG_OS_BEGIN   (1u << 15)
#define ADS1115_CFG_MUX_A0_GND (0x4000u)   /* AIN0 single-ended vs GND */
#define ADS1115_CFG_PGA_4_096V (0x0200u)   /* +/-4.096 V range */
#define ADS1115_CFG_MODE_SS   (0x0100u)   /* Single-shot mode */
#define ADS1115_CFG_DR_128SPS (0x0080u)   /* 128 SPS */
#define ADS1115_CFG_CQUE_NONE (0x0003u)   /* Disable comparator */

#define RELAY_GPIO       17
#define REED_GPIO        27
#define LOG_FILE         "/var/log/door_events.log"
#define SAMPLE_PERIOD_MS 200
#define CALIB_SAMPLES    10
#define CALIB_DELAY_MS   50
#define RELAY_PULSE_MS   3000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg16(int fd, uint8_t reg, uint16_t val)
{
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (uint8_t)(val >> 8);
    buf[2] = (uint8_t)(val & 0xFF);

    struct i2c_msg msg = {
        .addr  = ADS1115_ADDR,
        .flags = 0,
        .len   = 3,
        .buf   = buf,
    };
    struct i2c_rdwr_ioctl_data data = {
        .msgs  = &msg,
        .nmsgs = 1,
    };

    if (ioctl(fd, I2C_RDWR, &data) < 0) {
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t wbuf[1] = { reg };
    uint8_t rbuf[2] = { 0 };

    struct i2c_msg msgs[2] = {
        { .addr = ADS1115_ADDR, .flags = 0,            .len = 1, .buf = wbuf },
        { .addr = ADS1115_ADDR, .flags = I2C_M_RD,     .len = 2, .buf = rbuf },
    };
    struct i2c_rdwr_ioctl_data data = {
        .msgs  = msgs,
        .nmsgs = 2,
    };

    if (ioctl(fd, I2C_RDWR, &data) < 0) {
        return -1;
    }

    *out = ((uint16_t)rbuf[0] << 8) | rbuf[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* ADS1115                                                             */
/* ------------------------------------------------------------------ */
static int ads1115_init(int fd)
{
    /*
     * Config: single-shot, AIN0 vs GND, +/-4.096 V, 128 SPS, no comp.
     * Write twice to ensure the config is latched.
     */
    if (i2c_write_reg16(fd, ADS1115_REG_CONFIG,
                        ADS1115_CFG_OS_BEGIN | ADS1115_CFG_MUX_A0_GND |
                        ADS1115_CFG_PGA_4_096V | ADS1115_CFG_MODE_SS |
                        ADS1115_CFG_DR_128SPS | ADS1115_CFG_CQUE_NONE) < 0) {
        return -1;
    }
    usleep(1000);
    return 0;
}

static int ads1115_read(int fd, int16_t *raw)
{
    uint16_t cfg;
    if (i2c_read_reg16(fd, ADS1115_REG_CONFIG, &cfg) < 0) {
        return -1;
    }
    if (!(cfg & ADS1115_CFG_OS_BEGIN)) {
        /* Conversion not ready yet */
        return 1;
    }

    uint16_t val;
    if (i2c_read_reg16(fd, ADS1115_REG_CONVERSION, &val) < 0) {
        return -1;
    }
    *raw = (int16_t)val;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Calibration                                                         */
/* ------------------------------------------------------------------ */
static double calibrate_distance(int fd, int num_samples)
{
    double sum = 0.0;
    int    valid = 0;

    for (int i = 0; i < num_samples; i++) {
        int16_t raw;
        int rc = ads1115_read(fd, &raw);
        if (rc == 0) {
            sum += (double)raw;
            valid++;
        } else if (rc < 0) {
            fprintf(stderr, "Warning: I2C read failed during calibration (rc=%d)\n", rc);
        }
        if (i < num_samples - 1) {
            usleep(CALIB_DELAY_MS * 1000);
        }
    }

    if (valid == 0) {
        fprintf(stderr, "Error: calibration failed — no valid samples\n");
        return -1.0;
    }
    return sum / valid;
}

/* ------------------------------------------------------------------ */
/* Relay                                                               */
/* ------------------------------------------------------------------ */
static int relay_set(int fd, int state)
{
    if (state != 0 && state != 1) {
        return -1;
    }
    if (ioctl(fd, GPIO_TIOCGVALUE, &state) < 0) {
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Reed sensor                                                         */
/* ------------------------------------------------------------------ */
static int reed_read(int fd)
{
    int val;
    if (ioctl(fd, GPIO_TIOCGVALUE, &val) < 0) {
        return -1;
    }
    return val;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_event(const char *msg)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return;
    }

    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) == 0) {
        struct tm tm;
        localtime_r(&ts.tv_sec, &tm);
        char tbuf[32];
        strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s.%03ld: %s\n", tbuf, ts.tv_nsec / 1000000L, msg);
    } else {
        fprintf(fp, "[timestamp-error]: %s\n", msg);
    }
    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus ---- */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        perror("open(" I2C_BUS ")");
        return EXIT_FAILURE;
    }

    /* ---- ADS1115 init ---- */
    if (ads1115_init(g_i2c_fd) < 0) {
        fprintf(stderr, "Error: ADS1115 init failed\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* ---- GPIO setup (libgpiod-style ioctl interface) ---- */
    /* Open gpiochip4 (RPi5 default) */
    int gpio_fd = open("/dev/gpiochip4", O_RDWR);
    if (gpio_fd < 0) {
        perror("open(/dev/gpiochip4)");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Configure relay as output, initial value 0 */
    if (ioctl(gpio_fd, GPIO_REQUEST_OUTPUT, RELAY_GPIO) < 0) {
        perror("ioctl(GPIO_REQUEST_OUTPUT, relay)");
        goto cleanup;
    }
    if (ioctl(gpio_fd, GPIO_SET_VALUE, RELAY_GPIO) < 0) {
        perror("ioctl(GPIO_SET_VALUE, relay)");
        goto cleanup;
    }

    /* Configure reed sensor as input with pull-up */
    if (ioctl(gpio_fd, GPIO_REQUEST_INPUT, REED_GPIO) < 0) {
        perror("ioctl(GPIO_REQUEST_INPUT, reed)");
        goto cleanup;
    }
    if (ioctl(gpio_fd, GPIO_SET_PULL, REED_GPIO) < 0) {
        perror("ioctl(GPIO_SET_PULL, reed)");
        goto cleanup;
    }

    /* ---- Calibration ---- */
    double threshold = calibrate_distance(g_i2c_fd, CALIB_SAMPLES);
    if (threshold < 0) {
        fprintf(stderr, "Error: calibration failed — sensor absent or bus error\n");
        goto cleanup;
    }
    printf("Calibration complete. Threshold: %.2f\n", threshold);

    /* ---- Main loop ---- */
    while (g_running) {
        int16_t raw;
        int rc = ads1115_read(g_i2c_fd, &raw);
        if (rc == 0) {
            double distance = (double)raw;
            printf("Distance: %.2f\n", distance);

            if (distance < threshold) {
                printf("Distance below threshold — energizing relay\n");
                if (ioctl(gpio_fd, GPIO_SET_VALUE, RELAY_GPIO) < 0) {
                    perror("ioctl(GPIO_SET_VALUE, relay on)");
                } else {
                    usleep(RELAY_PULSE_MS * 1000);
                    if (ioctl(gpio_fd, GPIO_SET_VALUE, RELAY_GPIO) < 0) {
                        perror("ioctl(GPIO_SET_VALUE, relay off)");
                    }
                }

                int reed = reed_read(gpio_fd);
                if (reed < 0) {
                    log_event("door_lock: reed read error");
                } else if (reed == 0) {
                    log_event("door_lock: door opened");
                } else {
                    log_event("door_lock: door not opened");
                }
            }
        } else if (rc < 0) {
            fprintf(stderr, "Error: I2C read failed (rc=%d)\n", rc);
            log_event("door_lock: I2C read error");
        }
        /* rc > 0: conversion not ready yet — just wait */

        usleep(SAMPLE_PERIOD_MS * 1000);
    }

cleanup:
    /* ---- Cleanup ---- */
    if (gpio_fd >= 0) {
        ioctl(gpio_fd, GPIO_SET_VALUE, RELAY_GPIO);
        close(gpio_fd);
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
    }
    return EXIT_SUCCESS;
}

