#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define PUMP_GPIO 18
#define LOG_FILE "irrigation.log"
#define MAX_RETRIES 3
#define DEFAULT_THRESHOLD 30
#define DEFAULT_PUMP_DURATION 10
#define DEFAULT_SLEEP_INTERVAL 60

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    } else {
        fprintf(fp, "[timestamp error] %s\n", message);
    }
    fclose(fp);
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        log_event("Invalid MCP3008 channel requested");
        return -1;
    }

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
        unsigned char rx[3] = { 0 };

        int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
        if (ret == 3) {
            int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
            return adc_value;
        }
        char msg[128];
        snprintf(msg, sizeof(msg), "SPI transfer failed (attempt %d/%d), pigpio error: %d",
                 attempt + 1, MAX_RETRIES, ret);
        log_event(msg);
        if (attempt < MAX_RETRIES - 1) {
            gpioDelay(100000);
        }
    }
    log_event("SPI read failed after all retries");
    return -1;
}

static int calculate_moisture_level(int adc_value) {
    if (adc_value < 0) return -1;
    return (int)(((float)adc_value / 1023.0f) * 100.0f);
}

static void control_pump(int state) {
    if (gpioWrite(PUMP_GPIO, state) != 0) {
        log_event("Failed to write pump GPIO");
    }
}

static void cleanup(void) {
    control_pump(0);
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int threshold = DEFAULT_THRESHOLD;
    int pump_duration = DEFAULT_PUMP_DURATION;
    int sleep_interval = DEFAULT_SLEEP_INTERVAL;

    int opt;
    while ((opt = getopt(argc, argv, "t:d:s:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atoi(optarg);
                if (threshold < 0 || threshold > 100) {
                    fprintf(stderr, "Threshold must be 0-100\n");
                    return 1;
                }
                break;
            case 'd':
                pump_duration = atoi(optarg);
                if (pump_duration < 0) {
                    fprintf(stderr, "Pump duration must be non-negative\n");
                    return 1;
                }
                break;
            case 's':
                sleep_interval = atoi(optarg);
                if (sleep_interval < 0) {
                    fprintf(stderr, "Sleep interval must be non-negative\n");
                    return 1;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-d pump_duration] [-s sleep_interval]\n", argv[0]);
                return 1;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set pump GPIO mode\n");
        cleanup();
        return 1;
    }
    control_pump(0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_event("Irrigation system started");

    while (running) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            log_event("Sensor read error, skipping cycle");
            sleep(sleep_interval);
            continue;
        }

        int moisture_level = calculate_moisture_level(adc_value);
        char msg[128];
        snprintf(msg, sizeof(msg), "Moisture level: %d%% (ADC: %d)", moisture_level, adc_value);
        log_event(msg);

        if (moisture_level < threshold) {
            snprintf(msg, sizeof(msg), "Moisture below threshold (%d%% < %d%%), activating pump for %d seconds",
                     moisture_level, threshold, pump_duration);
            log_event(msg);
            control_pump(1);
            gpioDelay(pump_duration * 1000000);
            control_pump(0);
            snprintf(msg, sizeof(msg), "Pump deactivated");
            log_event(msg);
        }

        sleep(sleep_interval);
    }

    log_event("Shutting down");
    cleanup();
    return 0;
}

