#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define PCF8591_ADDR   0x48
#define PCF8591_CTRL   0x40   /* single-ended, AIN0, auto-increment off */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

int main(void)
{
    int fd = -1;
    int rc = EXIT_FAILURE;

    /* Install SIGINT handler for clean shutdown on Ctrl-C */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the I2C bus */
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the PCF8591 device */
    if (ioctl(fd, I2C_SLAVE, PCF8591_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                PCF8591_ADDR, strerror(errno));
        goto cleanup;
    }

    /* Dummy write to select AIN0 single-ended (control byte 0x40) */
    unsigned char ctrl = PCF8591_CTRL;
    ssize_t w = write(fd, &ctrl, 1);
    if (w < 0) {
        fprintf(stderr, "write(control byte) failed: %s\n", strerror(errno));
        goto cleanup;
    }
    if (w != 1) {
        fprintf(stderr, "write(control byte) short write: %zd bytes\n", w);
        goto cleanup;
    }

    /* Dummy read: the PCF8591 returns the result of the *previous* conversion */
    unsigned char dummy;
    ssize_t r = read(fd, &dummy, 1);
    if (r < 0) {
        fprintf(stderr, "dummy read failed: %s\n", strerror(errno));
        goto cleanup;
    }
    if (r != 1) {
        fprintf(stderr, "dummy read short read: %zd bytes\n", r);
        goto cleanup;
    }

    /* Main sampling loop */
    while (g_running) {
        unsigned char value;
        r = read(fd, &value, 1);
        if (r < 0) {
            fprintf(stderr, "ADC read failed: %s\n", strerror(errno));
            goto cleanup;
        }
        if (r != 1) {
            fprintf(stderr, "ADC read short read: %zd bytes\n", r);
            goto cleanup;
        }

        printf("AIN0: %u\n", (unsigned int)value);
        fflush(stdout);

        /* Sleep 100 ms; usleep is interruptible by signals */
        usleep(100000);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        if (close(fd) < 0) {
            fprintf(stderr, "close(fd) failed: %s\n", strerror(errno));
            rc = EXIT_FAILURE;
        }
    }
    return rc;
}

