/*
 * Hall-effect sensor monitor using ADS1115 ADC on Raspberry Pi 3 Model B+.
 *
 * Hardware:
 *   - Honeywell SS49E linear Hall-effect sensor (V+ -> 3.3V, V- -> GND, OUT -> AIN0)
 *   - ADS1115 ADC on I2C bus 1, address 0x48
 *   - GPIO27 (BCM) as shutdown indicator
 *
 * Behavior:
 *   - Samples AIN0 at 1 Hz.
 *   - Converts voltage to magnetic field strength (Gauss).
 *   - Stores readings in a circular buffer for rolling average.
 *   - Drives GPIO27 HIGH on threshold crossing and keeps it HIGH.
 *   - Logs all events to syslog.
 *   - Clean shutdown on SIGINT/SIGTERM.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <pigpio.h>

#define I2C_BUS              1
#define ADS1115_ADDR         0x48
#define ADS1115_REG_CONV     0x00
#define ADS1115_REG_CONFIG   0x01

/* Config: AIN0 single-ended, PGA 4.096V, single-shot, 128 SPS, no comparator */
#define ADS1115_CONFIG_BASE  0x8000  /* OS bit */
#define ADS1115_CONFIG_MUX   0x4000  /* AIN0 vs GND */
#define ADS1115_CONFIG_PGA   0x0200  /* PGA = 4.096V */
#define ADS1115_CONFIG_MODE  0x0100  /* Single-shot */
#define ADS1115_CONFIG_DR    0x0080  /* 128 SPS */
#define ADS1115_CONFIG_CQUE  0x0003  /* Disable comparator */
#define ADS1115_CONFIG       (ADS1115_CONFIG_BASE | ADS1115_CONFIG_MUX | \
                              ADS1115_CONFIG_PGA | ADS1115_CONFIG_MODE | \
                              ADS1115_CONFIG_DR | ADS1115_CONFIG_CQUE)

#define SHUTDOWN_PIN         27
#define BUFFER_SIZE          10
#define THRESHOLD_GAUSS      500.0f
#define SAMPLE_PERIOD_US     1000000  /* 1 Hz */
#define CONV_TIMEOUT_MS      100
#define VREF                 3.3f
#define PGA_VREF             4.096f

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static bool g_gpio_init  = false;

/* ---- Circular buffer ---- */
typedef struct {
    float buffer[BUFFER_SIZE];
    int   head;
    int   count;
} CircularBuffer;

static void cb_init(CircularBuffer *cb) {
    memset(cb, 0, sizeof(*cb));
}

static void cb_add(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) cb->count++;
}

static float cb_average(const CircularBuffer *cb) {
    if (cb->count == 0) return 0.0f;
    float sum = 0.0f;
    for (int i = 0; i < cb->count; i++) sum += cb->buffer[i];
    return sum / (float)cb->count;
}

/* ---- ADS1115 helpers ---- */
static int ads1115_write_config(int handle, uint16_t config) {
    char buf[3];
    buf[0] = ADS1115_REG_CONFIG;
    buf[1] = (config >> 8) & 0xFF;
    buf[2] = config & 0xFF;
    if (i2cWriteDevice(handle, buf, 3) < 0) {
        syslog(LOG_ERR, "ADS1115 config write failed");
        return -1;
    }
    return 0;
}

static int ads1115_read_conversion(int handle, int16_t *raw) {
    char reg = ADS1115_REG_CONV;
    if (i2cWriteDevice(handle, &reg, 1) < 0) {
        syslog(LOG_ERR, "ADS1115 reg select failed");
        return -1;
    }
    char data[2];
    if (i2cReadDevice(handle, data, 2) != 2) {
        syslog(LOG_ERR, "ADS1115 conversion read failed");
        return -1;
    }
    *raw = (int16_t)((data[0] << 8) | data[1]);
    return 0;
}

static int ads1115_wait_conversion(int handle) {
    for (int i = 0; i < CONV_TIMEOUT_MS; i++) {
        if (ads1115_read_conversion(handle, NULL) == 0) return 0;
        gpioDelay(1000); /* 1 ms */
    }
    syslog(LOG_ERR, "ADS1115 conversion timeout");
    return -1;
}

static int ads1115_read_raw(int handle, int16_t *raw) {
    if (ads1115_write_config(handle, ADS1115_CONFIG) < 0) return -1;
    if (ads1115_wait_conversion(handle) < 0) return -1;
    return ads1115_read_conversion(handle, raw);
}

/* ---- Conversion: voltage -> Gauss ---- */
static float voltage_to_gauss(float voltage) {
    /* SS49E transfer function: B = K * V, where K = 100000 Gauss/V
     * for a 100 mT full-scale range. */
    return voltage * 100000.0f;
}

/* ---- GPIO setup ---- */
static int gpio_setup(void) {
    if (gpioSetMode(SHUTDOWN_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "gpioSetMode failed for pin %d", SHUTDOWN_PIN);
        return -1;
    }
    if (gpioWrite(SHUTDOWN_PIN, 0) < 0) {
        syslog(LOG_ERR, "gpioWrite failed for pin %d", SHUTDOWN_PIN);
        return -1;
    }
    return 0;
}

static void gpio_shutdown(void) {
    if (g_gpio_init) {
        gpioWrite(SHUTDOWN_PIN, 0);
        g_gpio_init = false;
    }
}

/* ---- Signal handling ---- */
static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* ---- Cleanup ---- */
static void cleanup(void) {
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpio_shutdown();
    if (g_gpio_init) {
        gpioTerminate();
        g_gpio_init = false;
    }
    closelog();
}

/* ---- Main ---- */
int main(void) {
    openlog("hall_monitor", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "sigaction failed: %m");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }
    g_gpio_init = true;

    if (gpio_setup() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (g_i2c_handle < 0) {
        syslog(LOG_ERR, "i2cOpen failed (bus %d, addr 0x%02X): %d",
               I2C_BUS, ADS1115_ADDR, g_i2c_handle);
        cleanup();
        return EXIT_FAILURE;
    }

    CircularBuffer buffer;
    cb_init(&buffer);

    syslog(LOG_INFO, "Hall monitor started (threshold %.1f Gauss, sample 1 Hz)",
           THRESHOLD_GAUSS);

    while (g_running) {
        int16_t raw;
        if (ads1115_read_raw(g_i2c_handle, &raw) < 0) {
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        float voltage = (raw / 32767.0f) * PGA_VREF;
        if (voltage < 0.0f || voltage > VREF) {
            syslog(LOG_WARNING, "Out-of-range voltage: %.4f V (raw=%d)",
                   voltage, raw);
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        float gauss = voltage_to_gauss(voltage);
        cb_add(&buffer, gauss);

        float avg = cb_average(&buffer);
        syslog(LOG_INFO, "V=%.4f V  B=%.1f Gauss  avg=%.1f Gauss",
               voltage, gauss, avg);

        if (avg > THRESHOLD_GAUSS) {
            syslog(LOG_CRIT, "Threshold exceeded: %.1f Gauss (avg), driving shutdown pin",
                   avg);
            gpioWrite(SHUTDOWN_PIN, 1);
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    syslog(LOG_INFO, "Shutting down cleanly");
    cleanup();
