#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL      0
#define SPI_SPEED        1000000
#define SPI_FLAGS        0
#define ADC_CHANNEL      0
#define MOISTURE_THRESHOLD 300
#define PUMP_GPIO        18
#define WATERING_DURATION 10
#define LOG_FILE         "watering_events.txt"
#define SAMPLE_INTERVAL  60

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int read_mcp3008(int spi_handle, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d (must be 0-7)\n", channel);
        return -1;
    }

    unsigned char tx[3] = {
        0x01,
        (unsigned char)((0x08 | channel) << 4),
        0x00
    };
    unsigned char rx[3] = {0};

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Error: ADC value out of range: %d\n", adc_value);
        return -1;
    }
    return adc_value;
}

static int control_pump(int gpio_pin, int state) {
    int ret = gpioWrite(gpio_pin, state);
    if (ret != 0) {
        fprintf(stderr, "Error: Failed to write GPIO %d (ret=%d)\n", gpio_pin, ret);
        return -1;
    }
    return 0;
}

static void log_event(const char *filename, int moisture_level) {
    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file %s\n", filename);
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        fclose(fp);
        return;
    }

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s - Watering event: Moisture Level = %d\n", timestamp, moisture_level);
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return 1;
    }

    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", PUMP_GPIO);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    if (control_pump(PUMP_GPIO, 0) != 0) {
        fprintf(stderr, "Error: Failed to initialize pump to OFF state\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int moisture_level = read_mcp3008(spi_handle, ADC_CHANNEL);
        if (moisture_level < 0) {
            fprintf(stderr, "Error: Failed to read moisture level. Retrying in %d seconds.\n", SAMPLE_INTERVAL);
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        printf("Moisture level: %d\n", moisture_level);

        if (moisture_level < MOISTURE_THRESHOLD) {
            printf("Moisture level below threshold. Activating pump for %d seconds.\n", WATERING_DURATION);

            if (control_pump(PUMP_GPIO, 1) != 0) {
                fprintf(stderr, "Error: Failed to activate pump. Exiting.\n");
                break;
            }

            for (int i = 0; i < WATERING_DURATION && g_running; i++) {
                sleep(1);
            }

            if (control_pump(PUMP_GPIO, 0) != 0) {
                fprintf(stderr, "Error: Failed to deactivate pump. Exiting.\n");
                break;
            }

            log_event(LOG_FILE, moisture_level);
            printf("Pump deactivated.\n");
        }

        for (int i = 0; i < SAMPLE_INTERVAL && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    control_pump(PUMP_GPIO, 0);
    spiClose(spi_handle);
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
    return 0;
}

