/*
 * Raspberry Pi 4 Model B – Honeywell SS49E Hall-effect sensor monitor
 *
 * Hardware:
 *   - ADS1115 ADC on I2C bus 1, address 0x48
 *   - SS49E analog output wired to ADS1115 AIN0 (single-ended)
 *   - LED on GPIO17 (BCM), 330 Ω series resistor
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o hall_monitor hall_monitor.c -lpigpio -lm
 *   (pigpio must be installed and the daemon must be running)
 *
 * Usage:
 *   ./hall_monitor [-t threshold_gauss]
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <math.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS            1
#define ADS1115_ADDR       0x48

#define ADS1115_REG_CONV   0x00
#define ADS1115_REG_CONFIG 0x01

/* Config register bits */
#define ADS1115_CFG_OS     (1 << 15)   /* Operational status / single-shot */
#define ADS1115_CFG_MUX_A0 (0x4000)   /* AIN0 single-ended */
#define ADS1115_CFG_PGA_4096 (0x0200) /* PGA gain = 4.096 V */
#define ADS1115_CFG_MODE_SS (0x0100)  /* Single-shot mode */
#define ADS1115_CFG_DR_128 (0x0080)   /* 128 SPS */
#define ADS1115_CFG_CQUE_NONE (0x0003) /* Disable comparator */

#define LED_GPIO           17
#define SAMPLE_PERIOD_US   100000     /* 100 ms */
#define BLINK_DURATION_US  1000000    /* 1 s total */
#define BLINK_HALF_PERIOD  50000      /* 50 ms on / 50 ms off */

#define DEFAULT_THRESHOLD  100.0      /* Gauss */
#define ADC_MAX_COUNT      32767.0    /* 16-bit signed, single-ended positive */
#define ADC_VREF           4.096      /* PGA gain 1 = 4.096 V */
#define GAUSS_PER_VOLT     100.0      /* SS49E: 100 Gauss/V */

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* --------------------------- Signal handling ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- ADS1115 helpers ----------------------------- */
static int ads1115_write_config(uint16_t config)
{
    char buf[3];
    buf[0] = ADS1115_REG_CONFIG;
    buf[1] = (config >> 8) & 0xFF;
    buf[2] = config & 0xFF;
    return i2cWriteDevice(g_i2c_handle, buf, 3);
}

static int ads1115_read_conversion(int16_t *value)
{
    char reg = ADS1115_REG_CONV;
    char buf[2];

    if (i2cWriteDevice(g_i2c_handle, &reg, 1) < 0)
        return -1;

    if (i2cReadDevice(g_i2c_handle, buf, 2) != 2)
        return -1;

    *value = (int16_t)(((uint16_t)(unsigned char)buf[0] << 8) |
                       (uint16_t)(unsigned char)buf[1]);
    return 0;
}

static int ads1115_start_single_shot(int16_t *value)
{
    uint16_t config = ADS1115_CFG_OS | ADS1115_CFG_MUX_A0 |
                      ADS1115_CFG_PGA_4096 | ADS1115_CFG_MODE_SS |
                      ADS1115_CFG_DR_128 | ADS1115_CFG_CQUE_NONE;

    if (ads1115_write_config(config) < 0)
        return -1;

    /* Wait for conversion to complete (~8 ms at 128 SPS) */
    gpioDelay(10000);

    if (ads1115_read_conversion(value) < 0)
        return -1;

    return 0;
}

/* ------------------------------- Cleanup --------------------------------- */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

/* ------------------------------- Main ------------------------------------ */
int main(int argc, char *argv[])
{
    double threshold = DEFAULT_THRESHOLD;

    /* Parse optional threshold argument */
    if (argc > 1) {
        threshold = atof(argv[1]);
        if (threshold <= 0.0) {
            fprintf(stderr, "Invalid threshold: %s\n", argv[1]);
            return EXIT_FAILURE;
        }
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure LED GPIO */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    /* Open I2C bus to ADS1115 */
    g_i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d).\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Monitoring SS49E Hall sensor via ADS1115 (0x%02X)...\n",
           ADS1115_ADDR);
    printf("Threshold: %.2f Gauss | LED on GPIO%d\n", threshold, LED_GPIO);
    printf("Press Ctrl+C to exit.\n\n");

    /* Main sampling loop */
    while (g_running) {
        int16_t raw;
        if (ads1115_start_single_shot(&raw) < 0) {
            fprintf(stderr, "Warning: ADC read failed, retrying...\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        double voltage = (double)raw / ADC_MAX_COUNT * ADC_VREF;
        double gauss = voltage * GAUSS_PER_VOLT;

        printf("Field: %7.2f Gauss | Raw: %6d | Voltage: %6.4f V\n",
               gauss, raw, voltage);

        if (gauss > threshold) {
            printf("*** Threshold exceeded (%.2f > %.2f) – LED blink ***\n",
                   gauss, threshold);

            uint32_t elapsed = 0;
            while (g_running && elapsed < BLINK_DURATION_US) {
                gpioWrite(LED_GPIO, 1);
                gpioDelay(BLINK_HALF_PERIOD);
                if (!g_running) break;
                gpioWrite(LED_GPIO, 0);
                gpioDelay(BLINK_HALF_PERIOD);
                elapsed += BLINK_HALF_PERIOD * 2;
            }
            gpioWrite(LED_GPIO, 0);
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

