        int16_t raw;
        if (ads1115_start_single_shot(&raw) < 0) {
            fprintf(stderr, "Warning: ADC read failed, retrying...\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        double voltage = (double)raw / ADC_MAX_COUNT * ADC_VREF;
        double gauss = voltage * GAUSS_PER_VOLT;

        printf("Field: %7.2f Gauss | Raw: %6d | Voltage: %6.4f V\n",
               gauss, raw, voltage);

        if (gauss > threshold) {
            printf("*** Threshold exceeded (%.2f > %.2f) – LED blink ***\n",
                   gauss, threshold);

            uint32_t elapsed = 0;
            while (g_running && elapsed < BLINK_DURATION_US) {
                gpioWrite(LED_GPIO, 1);
                gpioDelay(BLINK_HALF_PERIOD);
                if (!g_running) break;
                gpioWrite(LED_GPIO, 0);
                gpioDelay(BLINK_HALF_PERIOD);
                elapsed += BLINK_HALF_PERIOD * 2;
            }
            gpioWrite(LED_GPIO, 0);
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

