#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <syslog.h>
#include <pthread.h>
#include <gpiod.h>
#include <mosquitto.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_DEVICE        "/dev/spidev0.0"
#define SPI_SPEED_HZ      1000000U   /* 1 MHz — well within MCP3008 spec */
#define SPI_BITS_PER_WORD 8U
#define SPI_MODE          0          /* SPI mode 0 (CPOL=0, CPHA=0) */

#define MCP3008_CHANNEL   0          /* Single-ended channel 0 */
