#define MQTT_PORT         1883
#define MQTT_CLIENT_ID    "soil_monitor_pi4"
#define MQTT_TOPIC        "soil_moisture"
#define MQTT_PUMP_TOPIC   "pump_control"

#define SAMPLE_INTERVAL_S 60
#define MAX_SPI_RETRIES    3

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static struct mosquitto *g_mqtt = NULL;
static struct gpiod_chip *g_chip = NULL;
static struct gpiod_line *g_pump_line = NULL;
static int g_spi_fd = -1;

/* --------------------------- Function prototypes -------------------------- */
static int  spi_init(void);
static int  spi_read_channel(uint8_t channel, uint16_t *out_value);
static float adc_to_moisture(uint16_t adc_value);
static int  pump_set(bool on);
static void mqtt_connect_callback(struct mosquitto *mosq, void *userdata,
                                  int result);
static void mqtt_disconnect_callback(struct mosquitto *mosq, void *userdata,
                                     int rc);
static void mqtt_message_callback(struct mosquitto *mosq, void *userdata,
                                  const struct mosquitto_message *message);
static int  mqtt_init(void);
static void mqtt_publish(const char *topic, const char *payload);
static void mqtt_subscribe(void);
static void mqtt_cleanup(void);
static void cleanup(void);
static void signal_handler(int sig);

/* ------------------------------- SPI layer ------------------------------- */
static int spi_init(void)
{
    uint8_t mode = SPI_MODE;
    uint8_t bits = SPI_BITS_PER_WORD;
    uint32_t speed = SPI_SPEED_HZ;

    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        syslog(LOG_ERR, "open(%s): %s", SPI_DEVICE, strerror(errno));
        return -1;
    }

    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        syslog(LOG_ERR, "SPI_IOC_WR_MODE: %s", strerror(errno));
        close(g_spi_fd); g_spi_fd = -1; return -1;
    }
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        syslog(LOG_ERR, "SPI_IOC_WR_BITS_PER_WORD: %s", strerror(errno));
        close(g_spi_fd); g_spi_fd = -1; return -1;
    }
