        syslog(LOG_ERR, "SPI_IOC_WR_MAX_SPEED_HZ: %s", strerror(errno));
        close(g_spi_fd); g_spi_fd = -1; return -1;
    }
    return 0;
}

/*
 * MCP3008 single-ended read (3-byte transfer):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
 *   tx[2] = 0x00                       (clock out remaining bits)
 * Result: 10-bit value in rx[1] (low 2 bits) and rx[2] (8 bits).
 */
static int spi_read_channel(uint8_t channel, uint16_t *out_value)
{
    if (channel > 7) {
        syslog(LOG_ERR, "Invalid MCP3008 channel %u", channel);
        return -1;
    }
    if (out_value == NULL) {
        syslog(LOG_ERR, "spi_read_channel: NULL output pointer");
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = 3;
    tr.speed_hz = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS_PER_WORD;
    tr.delay_usecs = 0;
    tr.cs_change = 0;

    for (int attempt = 1; attempt <= MAX_SPI_RETRIES; ++attempt) {
        if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) >= 0) {
            *out_value = (uint16_t)(((rx[1] & 0x03) << 8) | rx[2]);
            return 0;
        }
        syslog(LOG_ERR, "SPI transfer failed (attempt %d/%d): %s",
               attempt, MAX_SPI_RETRIES, strerror(errno));
        usleep(10000); /* 10 ms back-off */
    }
    return -1;
}

/* ------------------------------- GPIO layer ------------------------------ */
static int pump_set(bool on)
{
    int rv = gpiod_line_set_value(g_pump_line, on ? 1 : 0);
    if (rv < 0) {
        syslog(LOG_ERR, "gpiod_line_set_value(%d): %s",
               on ? 1 : 0, strerror(errno));
        return -1;
    }
    syslog(LOG_INFO, "Pump %s", on ? "ON" : "OFF");
    return 0;
}

/* ------------------------------- MQTT layer ------------------------------ */
static void mqtt_connect_callback(struct mosquitto *mosq, void *userdata,
                                  int result)
{
