    if (result == MOSQ_ERR_SUCCESS) {
        syslog(LOG_INFO, "MQTT connected to %s:%d",
               MQTT_BROKER, MQTT_PORT);
        mqtt_subscribe();
    } else {
        syslog(LOG_ERR, "MQTT connect error: %s",
               mosquitto_strerror(result));
    }
}

static void mqtt_disconnect_callback(struct mosquitto *mosq, void *userdata,
                                     int rc)
{
    (void)mosq; (void)userdata;
    syslog(LOG_WARNING, "MQTT disconnected (rc=%d)", rc);
}

static void mqtt_message_callback(struct mosquitto *mosq, void *userdata,
                                  const struct mosquitto_message *message)
{
    (void)mosq; (void)userdata;

    if (message->payloadlen <= 0 || message->payload == NULL) {
        syslog(LOG_WARNING, "Empty MQTT payload on topic %s",
               message->topic);
        return;
    }

    /* NUL-terminate payload for safe string comparison */
    char payload[32];
    size_t copy_len = (size_t)message->payloadlen;
    if (copy_len >= sizeof(payload)) copy_len = sizeof(payload) - 1;
    memcpy(payload, message->payload, copy_len);
    payload[copy_len] = '\0';

    syslog(LOG_INFO, "MQTT message: topic=%s payload=%s",
           message->topic, payload);

    if (strcmp(message->topic, MQTT_PUMP_TOPIC) == 0) {
        if (strcmp(payload, "pump_on") == 0) {
            pump_set(true);
        } else if (strcmp(payload, "pump_off") == 0) {
            pump_set(false);
        } else {
            syslog(LOG_WARNING, "Invalid pump command: %s", payload);
        }
    }
}

static int mqtt_init(void)
{
    mosquitto_lib_init();
    g_mqtt = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (g_mqtt == NULL) {
        syslog(LOG_ERR, "mosquitto_new failed: %s", strerror(errno));
        return -1;
    }

    mosquitto_connect_callback_set(g_mqtt, mqtt_connect_callback);
    mosquitto_disconnect_callback_set(g_mqtt, mqtt_disconnect_callback);
    mosquitto_message_callback_set(g_mqtt, mqtt_message_callback);

    int rc = mosquitto_connect(g_mqtt, MQTT_BROKER, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "mosquitto_connect(%s:%d): %s",
               MQTT_BROKER, MQTT_PORT, mosquitto_strerror(rc));
        mosquitto_destroy(g_mqtt);
