    int rc = mosquitto_publish(g_mqtt, NULL, topic, (int)strlen(payload),
                               payload, 0, false);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "mosquitto_publish(%s): %s",
               topic, mosquitto_strerror(rc));
    }
}

static void mqtt_subscribe(void)
{
    if (g_mqtt == NULL) return;
    int rc = mosquitto_subscribe(g_mqtt, NULL, MQTT_PUMP_TOPIC, 0);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "mosquitto_subscribe(%s): %s",
               MQTT_PUMP_TOPIC, mosquitto_strerror(rc));
    } else {
        syslog(LOG_INFO, "Subscribed to %s", MQTT_PUMP_TOPIC);
    }
}

static void mqtt_cleanup(void)
{
    if (g_mqtt != NULL) {
        mosquitto_disconnect(g_mqtt);
        mosquitto_destroy(g_mqtt);
        g_mqtt = NULL;
    }
    mosquitto_lib_cleanup();
}

/* ------------------------------- Cleanup --------------------------------- */
static void cleanup(void)
{
    syslog(LOG_INFO, "Cleaning up...");

    /* Ensure pump is OFF */
    if (g_pump_line != NULL) {
        (void)gpiod_line_set_value(g_pump_line, 0);
        gpiod_line_release(g_pump_line);
        g_pump_line = NULL;
    }
    if (g_chip != NULL) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    mqtt_cleanup();
    closelog();
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------- Main ------------------------------------ */
int main(void)
{
    openlog("soil_monitor", LOG_PID | LOG_CONS, LOG_USER);

    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "sigaction: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    /* GPIO setup */
    g_chip = gpiod_chip_open_by_name(PUMP_CHIP_NAME);
    if (g_chip == NULL) {
        syslog(LOG_ERR, "gpiod_chip_open_by_name(%s): %s",
               PUMP_CHIP_NAME, strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }
    g_pump_line = gpiod_chip_get_line(g_chip, PUMP_GPIO_LINE);
    if (g_pump_line == NULL) {
        syslog(LOG_ERR, "gpiod_chip_get_line(%d): %s",
               PUMP_GPIO_LINE, strerror(errno));
        gpiod_chip_close(g_chip); g_chip = NULL;
        closelog();
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(g_pump_line, "soil_monitor", 0) < 0) {
        syslog(LOG_ERR, "gpiod_line_request_output: %s", strerror(errno));
        gpiod_line_release(g_pump_line); g_pump_line = NULL;
        gpiod_chip_close(g_chip); g_chip = NULL;
        closelog();
        return EXIT_FAILURE;
    }

    /* SPI setup */
    if (spi_init() < 0) {
        syslog(LOG_ERR, "SPI initialization failed");
        cleanup();
        return EXIT_FAILURE;
    }

    /* MQTT setup */
    if (mqtt_init() < 0) {
        syslog(LOG_ERR, "MQTT initialization failed");
        cleanup();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Soil moisture monitor started (channel %u, "
                    "pump GPIO %u, low %.1f%%, high %.1f%%)",
           MCP3008_CHANNEL, PUMP_GPIO_LINE, MOISTURE_LOW, MOISTURE_HIGH);

    bool pump_on = false;

    while (g_running) {
        uint16_t adc_value = 0;
        if (spi_read_channel(MCP3008_CHANNEL, &adc_value) < 0) {
            syslog(LOG_ERR, "SPI read failed — skipping cycle");
            sleep(SAMPLE_INTERVAL_S);
            continue;
        }

        float moisture = adc_to_moisture(adc_value);
        char payload[32];
        snprintf(payload, sizeof(payload), "%.2f", moisture);
        mqtt_publish(MQTT_TOPIC, payload);

        /* Hysteresis control */
        if (moisture < MOISTURE_LOW && !pump_on) {
            if (pump_set(true) == 0) pump_on = true;
        } else if (moisture > MOISTURE_HIGH && pump_on) {
            if (pump_set(false) == 0) pump_on = false;
        }

        sleep(SAMPLE_INTERVAL_S);
    }

    cleanup();
    return EXIT_SUCCESS;
}

/* ------------------------------- Helpers --------------------------------- */
static float adc_to_moisture(uint16_t adc_value)
{
    if (adc_value > ADC_MAX_VALUE) {
        syslog(LOG_WARNING, "ADC value out of range: %u", adc_value);
        return -1.0f;
    }
    /* HL-69: higher voltage (higher ADC) → drier soil → lower moisture % */
    return 100.0f - ((float)adc_value / (float)ADC_MAX_VALUE) * 100.0f;
}

