        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("MCP3008 logging started. Press Ctrl+C to stop.\n");

    /* --- Main sampling loop --- */
    while (g_running) {
        float voltages[NUM_CHANNELS];

        if (read_all_channels(voltages) != 0) {
            fprintf(stderr, "Error reading channels; aborting.\n");
            break;
        }

        if (log_data(voltages) != 0) {
            fprintf(stderr, "Error logging data; aborting.\n");
            break;
        }

        /* Sleep in small increments so signals are caught promptly */
        for (int i = 0; i < 50 && g_running; i++) {
            gpioDelay(100000);  /* 100 ms */
        }
    }

    /* --- Clean shutdown --- */
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();

    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

