#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>

#define BH1750_ADDR 0x23
#define BH1750_CONT_HIGH_RES 0x10
#define MCP3008_CHANNEL 0
#define SPI_DEVICE "/dev/spidev0.0"
#define I2C_DEVICE "/dev/i2c-1"
#define LOG_FILE "tamper_log.csv"
#define SAMPLE_INTERVAL 5
#define BH1750_MEASUREMENT_DELAY_MS 180

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static int spi_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_bh1750(int fd, float *lux) {
    unsigned char cmd = BH1750_CONT_HIGH_RES;
    if (write(fd, &cmd, 1) != 1) {
        return -1;
    }
    usleep(BH1750_MEASUREMENT_DELAY_MS * 1000);
    unsigned char buf[2];
    if (read(fd, buf, 2) != 2) {
        return -1;
    }
    unsigned int raw = ((unsigned int)buf[0] << 8) | buf[1];
    *lux = (float)raw / 1.2f;
    return 0;
}

static int read_mcp3008(int fd, int channel, int *value) {
    if (channel < 0 || channel > 7) return -1;
    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = 1000000,
        .bits_per_word = 8,
        .delay_usecs = 0
    };
    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        return -1;
    }
    *value = ((rx[1] & 0x03) << 8) | rx[2];
    return 0;
}

static float adc_to_db(int adc_value) {
    if (adc_value < 0) return -99.0f;
    float voltage = (float)adc_value / 1023.0f * 3.3f;
    if (voltage < 0.001f) return -99.0f;
    return 20.0f * log10f(voltage);
}

static void log_data(FILE *fp, float sound_db, float light_lux, int err_code) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) return;
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f,%.2f,%d\n", ts, sound_db, light_lux, err_code);
    fflush(fp);
}

int main(void) {
    struct sigaction sa = {0};
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        return 1;
    }

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("open I2C");
        fclose(log_file);
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(i2c_fd);
        fclose(log_file);
        return 1;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open SPI");
        close(i2c_fd);
        fclose(log_file);
        return 1;
    }
    unsigned char spi_mode = SPI_MODE_0;
    unsigned char spi_bits = 8;
    unsigned int spi_speed = 1000000;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &spi_mode) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &spi_bits) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &spi_speed) < 0) {
        perror("ioctl SPI");
        close(spi_fd);
        close(i2c_fd);
        fclose(log_file);
        return 1;
    }

    while (running) {
        float sound_db = -99.0f;
        float light_lux = -1.0f;
        int err_code = 0;

        int adc_val = 0;
        if (read_mcp3008(spi_fd, MCP3008_CHANNEL, &adc_val) != 0) {
            err_code |= 0x01;
            fprintf(stderr, "Error reading ADC\n");
        }
        sound_db = adc_to_db(adc_val);

        if (read_bh1750(i2c_fd, &light_lux) != 0) {
            err_code |= 0x02;
            fprintf(stderr, "Error reading BH1750\n");
        }

        log_data(log_file, sound_db, light_lux, err_code);
        sleep(SAMPLE_INTERVAL);
    }

    if (i2c_fd >= 0) close(i2c_fd);
    if (spi_fd >= 0) close(spi_fd);
    if (log_file) fclose(log_file);
    return 0;
}

