/*
 * Raspberry Pi 4 Model B — Soil Moisture Monitor & Pump Controller
 *
 * Hardware:
 *   - Vegetronix VH400 soil moisture sensor (0-3 V output) -> MCP3008 CH0
 *   - MCP3008 10-bit ADC on SPI0 (CE0 / GPIO8), 1 MHz, Mode 0
 *   - Relay-controlled water pump on BCM GPIO 17 (active-high)
 *
 * Behavior:
 *   - Reads CH0 every 60 s.
 *   - Logs timestamped moisture percentage to stdout.
 *   - Activates pump when moisture < 30 %.
 *   - Graceful shutdown on SIGINT / SIGTERM.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL    0          /* CE0 / GPIO8 */
#define SPI_SPEED      1000000    /* 1 MHz */
#define SPI_FLAGS      0          /* Mode 0, active-low CE */

#define PUMP_GPIO      17         /* BCM GPIO 17 */
#define MOISTURE_THRESHOLD 30.0f
#define SAMPLE_INTERVAL_S 60
#define MAX_RETRIES      3

/* MCP3008 single-ended read: start bit, SGL/DIFF=1, D2 D1 D0 */
#define MCP3008_START   0x01
#define MCP3008_SGL_CH0 0x80       /* single-ended, channel 0 */

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read 10-bit value from MCP3008 channel (0-7). Returns 0-1023 or -1. */
static int mcp3008_read(int handle, uint8_t channel)
{
    if (channel > 7) {
        fprintf(stderr, "Invalid channel %u\n", channel);
        return -1;
    }

    /* MCP3008 SPI frame: 3 bytes
     *   tx[0] = 0x01                       start bit
     *   tx[1] = (0x08 | channel) << 4      SGL/DIFF=1, D2 D1 D0, padded
     *   tx[2] = 0x00                       clock out low bits
     */
    char tx[3] = { MCP3008_START, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "spiXfer failed (ret=%d)\n", ret);
        return -1;
    }

    /* 10-bit result: low 2 bits of rx[1] << 8 | rx[2] */
    int adc = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return adc;
}

/* ------------------------------------------------------------------ */
static float adc_to_moisture(int adc)
{
    /* VH400 0-3 V output maps to 0-1023; 0 % = dry, 100 % = wet. */
    return ((float)adc / 1023.0f) * 100.0f;
}

/* ------------------------------------------------------------------ */
static void control_pump(float moisture)
{
    int target = (moisture < MOISTURE_THRESHOLD) ? 1 : 0;

    if (gpioWrite(PUMP_GPIO, target) < 0) {
        fprintf(stderr, "gpioWrite(%d) failed\n", PUMP_GPIO);
        return;
    }

    printf("Pump %s\n", target ? "ON" : "OFF");
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioWrite(PUMP_GPIO, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init ------------------------------------------------- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise failed\n");
        return EXIT_FAILURE;
    }

    /* --- pump GPIO setup --------------------------------------------- */
    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%d) failed\n", PUMP_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(PUMP_GPIO, 0);

    /* --- SPI open ---------------------------------------------------- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle=%d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- signals ----------------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Soil Moisture Monitor started. Sampling every %d s.\n",
           SAMPLE_INTERVAL_S);

    /* --- main loop --------------------------------------------------- */
    while (g_running) {
        int adc = -1;
        int attempt;

        for (attempt = 0; attempt < MAX_RETRIES && g_running; ++attempt) {
            adc = mcp3008_read(g_spi_handle, 0);
            if (adc >= 0)
                break;
            fprintf(stderr, "SPI read failed (attempt %d/%d)\n",
                    attempt + 1, MAX_RETRIES);
            if (attempt < MAX_RETRIES - 1)
                gpioDelay(100000); /* 100 ms backoff */
        }

        if (adc < 0) {
            fprintf(stderr, "SPI read failed after %d attempts; skipping cycle\n",
                    MAX_RETRIES);
        } else {
            float moisture = adc_to_moisture(adc);

            time_t now = time(NULL);
            struct tm tm_buf;
            struct tm *t = localtime_r(&now, &tm_buf);
            char ts[32];
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

            printf("[%s] CH0: %4d  Moisture: %5.1f%%  Pump: %s\n",
                   ts, adc, moisture,
                   (moisture < MOISTURE_THRESHOLD) ? "ON" : "OFF");

            control_pump(moisture);
        }

        /* Sleep in 1 s increments so signals are caught promptly. */
        for (int i = 0; i < SAMPLE_INTERVAL_S && g_running; ++i)
            gpioDelay(1000000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

