#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define MCP3008_CHANNEL 0
#define RELAY_GPIO 17
#define DISTANCE_THRESHOLD_CM 20.0
#define DEBOUNCE_DELAY_US 1000000
#define POLL_DELAY_US 100000
#define LOG_FILE "door_events.log"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    int ret = spiXfer(SPI_CHANNEL, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static double adc_to_distance_cm(int adc_value) {
    if (adc_value < 0) return -1.0;
    if (adc_value > 1023) adc_value = 1023;
    return 27.0 - 0.08 * adc_value;
}

static int log_event(const char *event) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s: %s\n", timestamp, event) < 0) {
        perror("fprintf");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose");
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    gpioWrite(RELAY_GPIO, 0);
    spiClose(SPI_CHANNEL);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_GPIO, 0);

    if (spiOpen(SPI_CHANNEL, SPI_SPEED, 0) < 0) {
        fprintf(stderr, "SPI open failed on channel %d\n", SPI_CHANNEL);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction SIGINT");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Door monitoring system started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading MCP3008. Retrying in 100ms.\n");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        double distance = adc_to_distance_cm(adc_value);
        if (distance < 0) {
            fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        printf("Distance: %.2f cm\n", distance);

        if (distance < DISTANCE_THRESHOLD_CM) {
            printf("Object detected below %.0f cm! Opening door.\n", DISTANCE_THRESHOLD_CM);
            if (gpioWrite(RELAY_GPIO, 1) != 0) {
                fprintf(stderr, "Failed to activate relay on GPIO %d\n", RELAY_GPIO);
            } else {
                if (log_event("Door opened") != 0) {
                    fprintf(stderr, "Failed to log event\n");
                }
            }
            gpioDelay(DEBOUNCE_DELAY_US);
            if (gpioWrite(RELAY_GPIO, 0) != 0) {
                fprintf(stderr, "Failed to deactivate relay on GPIO %d\n", RELAY_GPIO);
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

