/*
 * Raspberry Pi Zero W – YL-69 soil-moisture logger via MCP3008 ADC
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3 V (Pin 1)
 *   MCP3008 VREF -> 3.3 V (Pin 1)
 *   MCP3008 AGND -> GND
 *   MCP3008 DGND -> GND
 *   MCP3008 CLK  -> GPIO11 (SPI0 SCLK)
 *   MCP3008 DOUT -> GPIO9  (SPI0 MISO)
 *   MCP3008 DIN  -> GPIO10 (SPI0 MOSI)
 *   MCP3008 CS   -> GPIO8  (SPI0 CE0)
 *   YL-69 A0     -> MCP3008 CH0
 *   YL-69 VCC    -> 3.3 V
 *   YL-69 GND    -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o soil_logger soil_logger.c -lpigpio -lrt
 * Run:    sudo ./soil_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL    0          /* SPI0 CE0 (GPIO8) */
#define SPI_SPEED      1000000    /* 1 MHz – well within MCP3008 spec */
#define SPI_FLAGS      0          /* Mode 0, active-low CE, 8-bit words */
#define ADC_CHANNEL    0          /* MCP3008 CH0 */
#define MAX_RETRIES    5
#define SAMPLE_PERIOD  5          /* seconds between samples */
#define LOG_FILE       "soil_data.txt"

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* SPI helpers                                                         */
/* ------------------------------------------------------------------ */
static int spi_init(void)
{
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (pigpio error %d).\n",
                g_spi_handle);
        return -1;
    }
    return 0;
}

/*
 * MCP3008 single-ended read (3-byte transfer):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
 *   tx[2] = 0x00                       (clock out remaining bits)
 *   rx[1] bits 1..0 + rx[2] bits 7..0  -> 10-bit result
 */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid ADC channel %d.\n", channel);
        return -1;
    }

    char tx[3] = { 0x01,
                   (char)((0x08 | channel) << 4),
                   0x00 };
    char rx[3] = { 0 };

    for (int attempt = 1; attempt <= MAX_RETRIES; ++attempt) {
        int rc = spiXfer(g_spi_handle, tx, rx, 3);
        if (rc == 3) {
            int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
            if (adc_value < 0 || adc_value > 1023) {
                fprintf(stderr,
                        "Warning: ADC value out of range (%d).\n",
                        adc_value);
                return -1;
            }
            return adc_value;
        }

        fprintf(stderr,
                "Warning: SPI transfer failed (pigpio error %d), "
                "attempt %d/%d.\n",
                rc, attempt, MAX_RETRIES);

        if (attempt < MAX_RETRIES) {
            gpioDelay(100000 * (1 << (attempt - 1))); /* 100 ms, 200 ms, … */
        }
    }

    fprintf(stderr, "Error: SPI communication failed after %d attempts.\n",
            MAX_RETRIES);
    return -1;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_data(int adc_value, float moisture_pct)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("Error getting local time");
        fclose(fp);
        return;
    }

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (adc_value >= 0) {
        fprintf(fp, "%s, ADC: %d, Moisture: %.2f%%\n",
                timestamp, adc_value, moisture_pct);
    } else {
        fprintf(fp, "%s, ERROR: ADC read failed\n", timestamp);
    }

    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Error registering SIGINT handler");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error registering SIGTERM handler");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    if (spi_init() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Soil moisture logger started. Logging to %s every %d s.\n",
           LOG_FILE, SAMPLE_PERIOD);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        int adc_value = read_mcp3008(ADC_CHANNEL);

        if (adc_value >= 0) {
            /*
             * YL-69 output is higher when dry and lower when wet.
             * A dry soil (high moisture) reads close to VREF (1023).
             * A wet soil (low moisture) reads close to GND (0).
             * Map 1023 -> 100 % and 0 -> 0 %.
             */
            float moisture_pct = 100.0f - ((float)adc_value / 1023.0f) * 100.0f;
            log_data(adc_value, moisture_pct);
            printf("ADC: %d, Moisture: %.2f%%\n", adc_value, moisture_pct);
        } else {
            log_data(-1, -1.0f);
            fprintf(stderr, "Error: Failed to read ADC value.\n");
        }

        /* Sleep in 100 ms increments so signals are caught promptly. */
        for (int i = 0; i < SAMPLE_PERIOD * 10 && g_running; ++i) {
            gpioDelay(100000); /* 100 ms */
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

