#define ECHO_TIMEOUT_US 30000

static volatile sig_atomic_t running = 1;
static double last_distance = 0.0;
static int last_volume = 0;
static double distance_slope = 0.0;
static double distance_intercept = 0.0;
static double volume_slope = 0.0;
static double volume_intercept = 0.0;

static int spi_fd = -1;
static int pwm_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }
    unsigned int speed = SPI_SPEED;
    unsigned char bits = 8;
    unsigned char mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd); spi_fd = -1; return -1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd); spi_fd = -1; return -1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd); spi_fd = -1; return -1;
    }
    return 0;
}

static int pwm_init(void) {
    char pwm_path[64];
    snprintf(pwm_path, sizeof(pwm_path), "/sys/class/pwm/pwmchip%d/pwm%d", PWM_CHIP, PWM_CHANNEL);
    struct stat st;
    if (stat(pwm_path, &st) != 0) {
        fprintf(stderr, "PWM device not found: %s\n", pwm_path);
        return -1;
    }
    snprintf(pwm_path, sizeof(pwm_path), "/sys/class/pwm/pwmchip%d/pwm%d/enable", PWM_CHIP, PWM_CHANNEL);
    int enable_fd = open(pwm_path, O_WRONLY);
    if (enable_fd < 0) {
        perror("Failed to open PWM enable");
        return -1;
    }
    if (write(enable_fd, "0", 1) < 0) {
        perror("Failed to disable PWM");
        close(enable_fd); return -1;
    }
    close(enable_fd);
    snprintf(pwm_path, sizeof(pwm_path), "/sys/class/pwm/pwmchip%d/pwm%d/period", PWM_CHIP, PWM_CHANNEL);
    pwm_fd = open(pwm_path, O_WRONLY);
    if (pwm_fd < 0) {
        perror("Failed to open PWM period");
        return -1;
    }
    char period_str[32];
    snprintf(period_str, sizeof(period_str), "%d", PWM_PERIOD_NS);
    if (write(pwm_fd, period_str, strlen(period_str)) < 0) {
        perror("Failed to set PWM period");
        close(pwm_fd); pwm_fd = -1; return -1;
    }
    snprintf(pwm_path, sizeof(pwm_path), "/sys/class/pwm/pwmchip%d/pwm%d/duty_cycle", PWM_CHIP, PWM_CHANNEL);
    int duty_fd = open(pwm_path, O_WRONLY);
    if (duty_fd < 0) {
        perror("Failed to open PWM duty cycle");
        close(pwm_fd); pwm_fd = -1; return -1;
    }
    if (write(duty_fd, "0", 1) < 0) {
        perror("Failed to set PWM duty cycle");
        close(duty_fd); close(pwm_fd); pwm_fd = -1; return -1;
    }
    close(duty_fd);
    snprintf(pwm_path, sizeof(pwm_path), "/sys/class/pwm/pwmchip%d/pwm%d/enable", PWM_CHIP, PWM_CHANNEL);
    enable_fd = open(pwm_path, O_WRONLY);
    if (enable_fd < 0) {
        perror("Failed to open PWM enable");
        close(pwm_fd); pwm_fd = -1; return -1;
    }
    if (write(enable_fd, "1", 1) < 0) {
        perror("Failed to enable PWM");
        close(enable_fd); close(pwm_fd); pwm_fd = -1; return -1;
    }
    close(enable_fd);
    return 0;
}

static void pwm_set_duty(int duty_percent) {
    if (pwm_fd < 0) return;
    if (duty_percent < 0) duty_percent = 0;
    if (duty_percent > 100) duty_percent = 100;
    long duty_ns = (long)PWM_PERIOD_NS * duty_percent / 100;
    char duty_str[32];
    snprintf(duty_str, sizeof(duty_str), "%ld", duty_ns);
    if (lseek(pwm_fd, 0, SEEK_SET) < 0) {
        perror("lseek PWM duty cycle");
        return;
    }
    if (write(pwm_fd, duty_str, strlen(duty_str)) < 0) {
        perror("write PWM duty cycle");
    }
}

static int read_ldr(void) {
    unsigned char tx[3] = {0x01, (0x08 | 0x00) << 4, 0x00};
    unsigned char rx[3] = {0};
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0
    };
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }
    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static double measure_distance(void) {
    if (gpio_set_mode(TRIG_PIN, 1) < 0) return -1.0;
    if (gpio_write(TRIG_PIN, 0) < 0) return -1.0;
    usleep(2);
    if (gpio_write(TRIG_PIN, 1) < 0) return -1.0;
    usleep(10);
    if (gpio_write(TRIG_PIN, 0) < 0) return -1.0;
    if (gpio_set_mode(ECHO_PIN, 0) < 0) return -1.0;
    struct timespec start, end;
    long long start_ns, end_ns;
    int timeout = ECHO_TIMEOUT_US;
    while (gpio_read(ECHO_PIN) == 0) {
        if (timeout-- <= 0) return -1.0;
        usleep(1);
    }
    clock_gettime(CLOCK_MONOTONIC, &start);
    timeout = ECHO_TIMEOUT_US;
    while (gpio_read(ECHO_PIN) == 1) {
        if (timeout-- <= 0) return -1.0;
        usleep(1);
    }
    clock_gettime(CLOCK_MONOTONIC, &end);
    start_ns = (long long)start.tv_sec * 1000000000LL + start.tv_nsec;
    end_ns = (long long)end.tv_sec * 1000000000LL + end.tv_nsec;
    long long diff_ns = end_ns - start_ns;
    double distance = (double)diff_ns / 58.0;
    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) return -1.0;
    return distance;
}

static void calibrate(double distance, int volume) {
    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) return;
    double new_slope = (distance - last_distance) / (double)(volume - last_volume);
    double new_intercept = distance - new_slope * volume;
    distance_slope = (distance_slope + new_slope) / 2.0;
    distance_intercept = (distance_intercept + new_intercept) / 2.0;
    volume_slope = (volume_slope + (double)(volume - last_volume)) / 2.0;
    volume_intercept = (volume_intercept + (double)volume) / 2.0;
    last_distance = distance;
    last_volume = volume;
}

static void save_config(void) {
    FILE *fp = fopen(CONFIG_FILE, "w");
    if (!fp) {
        perror("Failed to open config file for writing");
        return;
    }
    fprintf(fp, "distance_slope=%.6f\ndistance_intercept=%.6f\nvolume_slope=%.6f\nvolume_intercept=%.6f\n",
            distance_slope, distance_intercept, volume_slope, volume_intercept);
    fclose(fp);
}

static void load_config(void) {
    FILE *fp = fopen(CONFIG_FILE, "r");
    if (!fp) return;
    double ds = 0.0, di = 0.0, vs = 0.0, vi = 0.0;
    if (fscanf(fp, "distance_slope=%lf\ndistance_intercept=%lf\nvolume_slope=%lf\nvolume_intercept=%lf\n",
               &ds, &di, &vs, &vi) == 4) {
        distance_slope = ds; distance_intercept = di;
        volume_slope = vs; volume_intercept = vi;
    }
    fclose(fp);
}

static int gpio_set_mode(int pin, int mode) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", pin);
    int fd = open(path, O_WRONLY);
    if (fd < 0) return -1;
    const char *val = mode ? "out" : "in";
    if (write(fd, val, 3) < 0) { close(fd); return -1; }
    close(fd);
    return 0;
}

static int gpio_write(int pin, int val) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    int fd = open(path, O_WRONLY);
    if (fd < 0) return -1;
    char v = val ? '1' : '0';
    if (write(fd, &v, 1) < 0) { close(fd); return -1; }
    close(fd);
    return 0;
}

static int gpio_read(int pin) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    int fd = open(path, O_RDONLY);
    if (fd < 0) return -1;
    char buf[2] = {0};
    if (read(fd, buf, 1) < 0) { close(fd); return -1; }
    close(fd);
    return (buf[0] == '1') ? 1 : 0;
}

static void cleanup(void) {
    if (pwm_fd >= 0) {
        if (lseek(pwm_fd, 0, SEEK_SET) >= 0) {
            write(pwm_fd, "0", 1);
        }
        close(pwm_fd);
        pwm_fd = -1;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
}

int main(void) {
    struct sigaction sa = {0};
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    if (spi_init() < 0) { cleanup(); return 1; }
    if (pwm_init() < 0) { cleanup(); return 1; }
    load_config();
    printf("Theremin started. Press Ctrl+C to exit.\n");
    while (running) {
        double distance = measure_distance();
        int ldr = read_ldr();
        if (distance < 0 || ldr < 0) {
            fprintf(stderr, "Sensor read error, using last valid values.\n");
            distance = last_distance;
            ldr = last_volume;
        }
        int volume = (int)((ldr - LDR_MIN) * (MAX_VOLUME - MIN_VOLUME) / (LDR_MAX - LDR_MIN) + MIN_VOLUME);
        if (volume > MAX_VOLUME) volume = MAX_VOLUME;
        if (volume < MIN_VOLUME) volume = MIN_VOLUME;
        double freq = 220.0 + (distance - MIN_DISTANCE) * 1000.0 / (MAX_DISTANCE - MIN_DISTANCE);
        if (freq < 220.0) freq = 220.0;
        if (freq > 1000.0) freq = 1000.0;
        int duty = (int)((freq - 220.0) * 100.0 / (1000.0 - 220.0));
        if (duty < 0) duty = 0;
        if (duty > 100) duty = 100;
        pwm_set_duty(duty);
        calibrate(distance, volume);
        usleep(50000);
    }
    cleanup();
    printf("Theremin stopped.\n");
    return 0;
}

