#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL      0
#define SPI_SPEED        1000000
#define SPI_FLAGS        0
#define PUMP_GPIO        18
#define MOISTURE_THRESHOLD 300
#define LOG_FILE         "irrigation.log"
#define SAMPLE_INTERVAL  60

static volatile sig_atomic_t g_running = 1;
static int  g_spi_handle = -1;
static FILE *g_log_file  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {
        0x01,
        (unsigned char)((0x08 | channel) << 4),
        0x00
    };
    unsigned char rx[3] = {0};

    if (spiXfer(g_spi_handle, (char *)tx, (char *)rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static void log_data(int moisture, int pump_status)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char timestamp[32];

    if (t == NULL) {
        strncpy(timestamp, "UNKNOWN", sizeof(timestamp) - 1);
        timestamp[sizeof(timestamp) - 1] = '\0';
    } else {
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    }

    fprintf(g_log_file, "%s, Moisture: %d, Pump: %s\n",
            timestamp, moisture, pump_status ? "ON" : "OFF");
    fflush(g_log_file);
}

static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle=%d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PUMP_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(PUMP_GPIO, 0);

    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("fopen(" LOG_FILE ")");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Soil Moisture Monitoring Started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int moisture = read_mcp3008(0);
        if (moisture < 0) {
            fprintf(stderr, "Error reading moisture sensor\n");
        } else {
            int pump_status = (moisture < MOISTURE_THRESHOLD) ? 1 : 0;
            if (gpioWrite(PUMP_GPIO, pump_status) != 0) {
                fprintf(stderr, "Failed to write pump GPIO\n");
            }
            log_data(moisture, pump_status);
            printf("Moisture: %d, Pump: %s\n", moisture, pump_status ? "ON" : "OFF");
        }

        for (int i = 0; i < SAMPLE_INTERVAL && g_running; i++) {
            sleep(1);
        }
    }

    gpioWrite(PUMP_GPIO, 0);
    cleanup();
    printf("Soil Moisture Monitoring Stopped.\n");
    return EXIT_SUCCESS;
}

