#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define MOTOR1_PWM_PIN 18
#define MOTOR2_PWM_PIN 24
#define MOTOR1_DIR_PIN 23
#define MOTOR2_DIR_PIN 25

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0

#define POT1_CHANNEL 0
#define POT2_CHANNEL 1

#define ACCELERATION_TIME_MS 100
#define DECELERATION_TIME_MS 100
#define HOLD_TIME_MS 2000
#define PAUSE_TIME_MS 5000
#define LOOP_DELAY_MS 100

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

int read_mcp3008(int spi_handle, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buf[3] = {0x01, (char)((0x08 | channel) << 4), 0x00};
    char rx_buf[3] = {0};

    int bytes = spiXfer(spi_handle, tx_buf, rx_buf, 3);
    if (bytes != 3) {
        fprintf(stderr, "SPI transfer failed on channel %d (returned %d)\n", channel, bytes);
        return -1;
    }

    return ((rx_buf[1] & 0x03) << 8) | (rx_buf[2] & 0xFF);
}

int map_potentiometer_to_speed(int pot_value) {
    if (pot_value < 0 || pot_value > 1023) {
        fprintf(stderr, "Invalid potentiometer value: %d\n", pot_value);
        return -1;
    }
    return (int)(((float)pot_value / 1023.0f) * 255.0f);
}

void set_motor_speed(int motor1_speed, int motor2_speed) {
    if (motor1_speed < 0 || motor1_speed > 255 || motor2_speed < 0 || motor2_speed > 255) {
        fprintf(stderr, "Invalid motor speed values: M1=%d, M2=%d\n", motor1_speed, motor2_speed);
        return;
    }

    gpioPWM(MOTOR1_PWM_PIN, motor1_speed);
    gpioPWM(MOTOR2_PWM_PIN, motor2_speed);
}

void accelerate(int target_speed, int acceleration_time_ms) {
    int current_speed = 0;
    int steps = acceleration_time_ms / LOOP_DELAY_MS;
    if (steps == 0) steps = 1;

    for (int i = 0; i <= steps && program_running; i++) {
        int speed_increment = target_speed / steps;
        current_speed += speed_increment;
        if (current_speed > target_speed) current_speed = target_speed;
        set_motor_speed(current_speed, current_speed);
        gpioDelay(LOOP_DELAY_MS * 1000);
    }
}

void decelerate(int target_speed, int deceleration_time_ms) {
    int current_speed = target_speed;
    int steps = deceleration_time_ms / LOOP_DELAY_MS;
    if (steps == 0) steps = 1;

    for (int i = 0; i <= steps && program_running; i++) {
        int speed_decrement = target_speed / steps;
        current_speed -= speed_decrement;
        if (current_speed < 0) current_speed = 0;
        set_motor_speed(current_speed, current_speed);
        gpioDelay(LOOP_DELAY_MS * 1000);
    }
}

void hold_speed(int hold_time_ms) {
    int hold_steps = hold_time_ms / LOOP_DELAY_MS;
    if (hold_steps == 0) hold_steps = 1;

    for (int i = 0; i < hold_steps && program_running; i++) {
        gpioDelay(LOOP_DELAY_MS * 1000);
    }
}

void pause_motor(int pause_time_ms) {
    int pause_steps = pause_time_ms / LOOP_DELAY_MS;
    if (pause_steps == 0) pause_steps = 1;

    for (int i = 0; i < pause_steps && program_running; i++) {
        gpioDelay(LOOP_DELAY_MS * 1000);
    }
}

void reverse_motors() {
    gpioWrite(MOTOR1_DIR_PIN, 1);
    gpioWrite(MOTOR2_DIR_PIN, 0);
    gpioDelay(100000);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(MOTOR1_PWM_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR2_PWM_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR1_DIR_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR2_DIR_PIN, PI_OUTPUT);

    gpioSetPWMfrequency(MOTOR1_PWM_PIN, 1000);
    gpioSetPWMfrequency(MOTOR2_PWM_PIN, 1000);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Motor control program started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int pot1_value = read_mcp3008(spi_handle, POT1_CHANNEL);
