#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LED_PIN 17
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define THRESHOLD 100
#define DEBOUNCE_DELAY_US 10000
#define CALIBRATION_TIME 5

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int calibrate_threshold(int num_samples) {
    int sum = 0;
    int valid = 0;

    for (int i = 0; i < num_samples; i++) {
        int val = read_mcp3008(0);
        if (val < 0) {
            fprintf(stderr, "Error reading ADC during calibration\n");
            return -1;
        }
        sum += val;
        valid++;
        gpioDelay(10000);
    }

    if (valid == 0) {
        fprintf(stderr, "No valid samples during calibration\n");
        return -1;
    }

    return sum / valid;
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_PIN, 0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Calibrating threshold for %d seconds...\n", CALIBRATION_TIME);
    int threshold = calibrate_threshold(CALIBRATION_TIME * 10);
    if (threshold < 0) {
        fprintf(stderr, "Calibration failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    printf("Calibration complete. Threshold: %d\n", threshold);

    int led_state = 0;
    uint32_t last_toggle = 0;

    while (running) {
        int sound_level = read_mcp3008(0);
        if (sound_level < 0) {
            fprintf(stderr, "Error reading sound level\n");
            break;
        }

        if (sound_level > threshold) {
            uint32_t now = gpioTick();
            if (now - last_toggle > DEBOUNCE_DELAY_US) {
                led_state = !led_state;
                gpioWrite(LED_PIN, led_state);
                last_toggle = now;
            }
        } else {
            led_state = 0;
            gpioWrite(LED_PIN, 0);
        }

        gpioDelay(10000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

