#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0
#define ADC_CHANNEL 0
#define SAMPLE_INTERVAL_MS 100
#define LOG_FILE "airflow_log.txt"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static int spi_handle = -1;

void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "ERROR: Invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx[3] = {0x01, (0x08 | channel) << 4, 0x00};
    char rx[3] = {0};

    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        fprintf(stderr, "ERROR: SPI transfer failed\n");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

float voltage_to_airflow(float voltage) {
    if (voltage < 0.0f) return 0.0f;
    if (voltage < 0.5f) return 0.0f;
    if (voltage < 1.0f) return 0.0f;
    if (voltage < 1.5f) return (voltage - 1.0f) * 10.0f;
    if (voltage < 2.0f) return 10.0f + (voltage - 1.5f) * 20.0f;
    return 30.0f + (voltage - 2.0f) * 50.0f;
}

void log_data(float voltage, float airflow) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Voltage: %.3f V, Airflow: %.2f CFM\n", timestamp, voltage, airflow);
    fflush(log_file);
}

void log_error(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, ERROR: %s\n", timestamp, message);
    fflush(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "ERROR: pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "ERROR: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "ERROR: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    while (running) {
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            log_error("ADC read failed");
        } else {
            float voltage = (float)adc_value * 3.3f / 1024.0f;
            float airflow = voltage_to_airflow(voltage);
            log_data(voltage, airflow);
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000);
    }

    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

