/*
 * ADXL335 + MCP3008 Kalman filter reader for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   ADXL335 X -> MCP3008 CH0
 *   ADXL335 Y -> MCP3008 CH1
 *   ADXL335 Z -> MCP3008 CH2
 *   MCP3008  VDD -> 3.3 V, VREF -> 3.3 V, AGND/DGND -> GND
 *   MCP3008  CLK  -> GPIO11 (BCM SCLK)
 *   MCP3008  DOUT -> GPIO9  (BCM MISO)
 *   MCP3008  DIN  -> GPIO10 (BCM MOSI)
 *   MCP3008  CS   -> GPIO8  (BCM CE0)
 *   MCP3008  CH0/CH1/CH2 -> ADXL335 X/Y/Z analog outputs
 *
 * Build: gcc -O2 -Wall -o adxl335_mcp3008 adxl335_mcp3008.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL    0          /* CE0 on GPIO8 */
#define SPI_SPEED      1000000    /* 1 MHz */
#define SPI_FLAGS      0          /* mode 0, active-low CE */

#define MCP3008_X_CH   0
#define MCP3008_Y_CH   1
#define MCP3008_Z_CH   2

#define VREF           3.3f
#define ADC_MAX        1023.0f    /* 10-bit ADC */

#define SAMPLE_HZ      10
#define SAMPLE_US      (1000000 / SAMPLE_HZ)

/* Kalman filter parameters (tuned for ~1 g, 0.1 g/s noise) */
#define Q_ANGLE        0.001f
#define Q_BIAS         0.003f
#define R_MEASUREMENT  0.03f

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;

/* ----------------------------- Signal handler ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- MCP3008 read ------------------------------ */
/*
 * MCP3008 single-ended read (3-byte transfer):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (single-ended + channel, upper nibble)
 *   tx[2] = 0x00                       (clock out remaining bits)
 *   rx[1] bits 1..0 + rx[2] bits 7..0  -> 10-bit result
 */
static int mcp3008_read(int spi_handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed on channel %d (ret=%d)\n",
                channel, ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return adc_value;
}

/* ----------------------------- Kalman filter ----------------------------- */
typedef struct {
    float angle;
    float bias;
    float P[2][2];
} kalman_state_t;

static void kalman_init(kalman_state_t *st)
{
    st->angle  = 0.0f;
    st->bias   = 0.0f;
    st->P[0][0] = 0.0f;
    st->P[0][1] = 0.0f;
    st->P[1][0] = 0.0f;
    st->P[1][1] = 0.0f;
}

static float kalman_update(kalman_state_t *st, float measurement)
{
    /* Prediction */
    float angle_hat = st->angle;
    float P00 = st->P[0][0];
    float P01 = st->P[0][1];
    float P10 = st->P[1][0];
    float P11 = st->P[1][1];

    st->P[0][0] = P00;
    st->P[0][1] = P01;
    st->P[1][0] = P10;
    st->P[1][1] = P11;

    /* Update */
    float y = measurement - (angle_hat + st->bias);
    float S = P11 + R_MEASUREMENT;

    float K0 = P00 / S;
    float K1 = P10 / S;

    st->angle  = angle_hat + K0 * y;
    st->bias   += K1 * y;

    st->P[0][0] = P00 - K0 * P00;
    st->P[0][1] = P01 - K0 * P01;
    st->P[1][0] = P10 - K1 * P00;
    st->P[1][1] = P11 - K1 * P01;

    return st->angle;
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    /* Install signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI bus */
    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
