}

static int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %s\n", gpio_pin, pigpio_error(value));
        return -1;
    }
    return value;
}

static float calculate_magnetic_field(int sensor_value) {
    return (float)sensor_value * 1.0f;
}

static int log_data(float sensor1, float sensor2, float sensor3) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    if (fprintf(fp, "%.2f,%.2f,%.2f\n", sensor1, sensor2, sensor3) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static void check_magnetic_field_range(float sensor1, float sensor2, float sensor3) {
    if (sensor1 < MIN_MAGNITUDE_MT || sensor1 > MAX_MAGNITUDE_MT) {
        fprintf(stderr, "Warning: Sensor 1 magnetic field %.2f mT out of range\n", sensor1);
    }
    if (sensor2 < MIN_MAGNITUDE_MT || sensor2 > MAX_MAGNITUDE_MT) {
        fprintf(stderr, "Warning: Sensor 2 magnetic field %.2f mT out of range\n", sensor2);
    }
    if (sensor3 < MIN_MAGNITUDE_MT || sensor3 > MAX_MAGNITUDE_MT) {
        fprintf(stderr, "Warning: Sensor 3 magnetic field %.2f mT out of range\n", sensor3);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR1_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR2_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR3_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR3_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Starting magnetic field monitoring. Press Ctrl+C to exit.\n");

    while (program_running) {
        int sensor1_value = read_sensor(SENSOR1_GPIO);
        int sensor2_value = read_sensor(SENSOR2_GPIO);
        int sensor3_value = read_sensor(SENSOR3_GPIO);

        if (sensor1_value < 0 || sensor2_value < 0 || sensor3_value < 0) {
            fprintf(stderr, "Error reading sensor data, skipping logging.\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        float sensor1_magnitude = calculate_magnetic_field(sensor1_value);
        float sensor2_magnitude = calculate_magnetic_field(sensor2_value);
        float sensor3_magnitude = calculate_magnetic_field(sensor3_value);

        check_magnetic_field_range(sensor1_magnitude, sensor2_magnitude, sensor3_magnitude);

        if (log_data(sensor1_magnitude, sensor2_magnitude, sensor3_magnitude) != 0) {
            fprintf(stderr, "Error logging data.\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    gpioTerminate();
    printf("\nProgram terminated gracefully.\n");
    return EXIT_SUCCESS;
}

