}

static int calculate_moisture_level(int adc_value) {
    if (adc_value < 0) return -1;
    return (int)(((float)adc_value / 1023.0f) * 100.0f);
}

static void control_pump(int moisture_level) {
    static int pump_on = 0;

    if (moisture_level < MOISTURE_THRESHOLD && !pump_on) {
        if (gpioWrite(PUMP_GPIO, 1) == 0) {
            pump_on = 1;
            char msg[128];
            snprintf(msg, sizeof(msg), "Pump turned ON (Moisture: %d%%)", moisture_level);
            log_event(msg);
        } else {
            log_event("Error: Failed to turn pump ON.");
        }
    } else if (moisture_level >= MOISTURE_THRESHOLD && pump_on) {
        if (gpioWrite(PUMP_GPIO, 0) == 0) {
            pump_on = 0;
            char msg[128];
            snprintf(msg, sizeof(msg), "Pump turned OFF (Moisture: %d%%)", moisture_level);
            log_event(msg);
        } else {
            log_event("Error: Failed to turn pump OFF.");
        }
    }
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file) {
        log_event("Program terminated.");
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(PUMP_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_event("Program started.");

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        log_event("Error: Failed to set pump GPIO mode.");
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(PUMP_GPIO, 0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        log_event("Error: SPI open failed.");
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (running) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            log_event("Error: Failed to read ADC value.");
        } else {
            int moisture_level = calculate_moisture_level(adc_value);
            if (moisture_level < 0) {
                log_event("Error: Failed to calculate moisture level.");
            } else {
                char msg[128];
                snprintf(msg, sizeof(msg), "Moisture level: %d%% (ADC: %d)", moisture_level, adc_value);
                log_event(msg);
                control_pump(moisture_level);
            }
        }
        sleep(SAMPLE_INTERVAL);
    }

    cleanup();
    return EXIT_SUCCESS;
}

