#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <errno.h>
#include <stdbool.h>
#include <mosquitto.h>
#include <gpiod.h>

#define MQTT_BROKER_ADDRESS "mqtt.eclipseprojects.io"
#define MQTT_BROKER_PORT 1883
#define MQTT_TOPIC "home/led_control"
#define MQTT_CLIENT_ID "rpi_led_control"
#define GPIO_CHIP_NAME "gpiochip4"
#define GPIO_LINE_OFFSET 17
#define MAX_RECONNECT_DELAY 60

static volatile sig_atomic_t running = 1;
static struct mosquitto *mosq = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;

static void signal_handler(int signum) {
    (void)signum;
    running = 0;
}

static void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(stderr, "[%s] ERROR: %s\n", timestamp, message);
}

static void cleanup(void) {
    if (line) {
        gpiod_line_set_value(line, 0);
        gpiod_line_release(line);
        line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosq = NULL;
    }
    mosquitto_lib_cleanup();
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        log_error("Failed to open GPIO chip");
        return -1;
    }
    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        log_error("Failed to get GPIO line");
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }
    if (gpiod_line_request_output(line, "rpi_led_control", 0) < 0) {
        log_error("Failed to request GPIO line as output");
        gpiod_line_release(line);
        line = NULL;
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }
    return 0;
}

static int parse_json(const char *json_string, bool *led_state) {
    if (!json_string || !led_state) {
        log_error("Invalid JSON parsing arguments");
        return -1;
    }
    *led_state = false;
    if (sscanf(json_string, "{\"led_state\":%b}", led_state) != 1) {
        log_error("Failed to parse JSON or invalid JSON format");
        return -1;
    }
    return 0;
}

static void control_led(bool state) {
    if (line) {
        if (gpiod_line_set_value(line, state ? 1 : 0) < 0) {
            log_error("Failed to set GPIO value");
        }
    }
}

static void on_connect(struct mosquitto *m, void *userdata, int result) {
    (void)userdata;
    if (result == MOSQ_ERR_SUCCESS) {
        printf("Connected to MQTT broker\n");
        int rc = mosquitto_subscribe(m, NULL, MQTT_TOPIC, 0);
        if (rc != MOSQ_ERR_SUCCESS) {
            log_error("Failed to subscribe to topic");
        }
    } else {
        log_error("Connection to MQTT broker failed");
    }
}

static void on_disconnect(struct mosquitto *m, void *userdata, int rc) {
    (void)m;
    (void)userdata;
    if (rc != MOSQ_ERR_SUCCESS) {
        log_error("Unexpected MQTT disconnect");
    }
}

static void on_message(struct mosquitto *m, void *userdata, const struct mosquitto_message *message) {
    (void)m;
    (void)userdata;
    if (!message || !message->payload || message->payloadlen <= 0) {
        log_error("Invalid MQTT message received");
        return;
    }
    char *json_string = malloc(message->payloadlen + 1);
    if (!json_string) {
        log_error("Failed to allocate memory for JSON string");
        return;
    }
    memcpy(json_string, message->payload, message->payloadlen);
    json_string[message->payloadlen] = '\0';
    bool led_state;
    if (parse_json(json_string, &led_state) == 0) {
        control_led(led_state);
        printf("LED state set to: %s\n", led_state ? "ON" : "OFF");
    } else {
        log_error("Failed to parse JSON payload");
    }
    free(json_string);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        log_error("Failed to set signal handlers");
        return 1;
    }
    if (init_gpio() != 0) {
        return 1;
    }
    if (mosquitto_lib_init() != MOSQ_ERR_SUCCESS) {
        log_error("Failed to initialize mosquitto library");
        cleanup();
        return 1;
    }
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        log_error("Failed to create mosquitto instance");
        mosquitto_lib_cleanup();
        cleanup();
        return 1;
    }
    mosquitto_connect_callback_set(mosq, on_connect);
    mosquitto_disconnect_callback_set(mosq, on_disconnect);
    mosquitto_message_callback_set(mosq, on_message);
    int reconnect_delay = 1;
    while (running) {
        int rc = mosquitto_connect(mosq, MQTT_BROKER_ADDRESS, MQTT_BROKER_PORT, 60);
        if (rc != MOSQ_ERR_SUCCESS) {
            log_error("Failed to connect to MQTT broker");
            sleep(reconnect_delay);
            reconnect_delay *= 2;
            if (reconnect_delay > MAX_RECONNECT_DELAY) {
                reconnect_delay = MAX_RECONNECT_DELAY;
            }
            continue;
        }
        reconnect_delay = 1;
        while (running) {
            rc = mosquitto_loop(mosq, 100, 1);
            if (rc != MOSQ_ERR_SUCCESS) {
                log_error("MQTT loop error");
                break;
            }
        }
        mosquitto_disconnect(mosq);
        if (running) {
            sleep(reconnect_delay);
            reconnect_delay *= 2;
            if (reconnect_delay > MAX_RECONNECT_DELAY) {
                reconnect_delay = MAX_RECONNECT_DELAY;
            }
        }
    }
    cleanup();
    return 0;
}

