#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN    18
#define POLL_DELAY_US    100000   /* 100 ms */
#define ALARM_DURATION_US 1000000 /* 1 s   */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

int main(void)
{
    /* --- Install signal handlers for clean shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO pins --- */
    if (gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", SOUND_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(ALARM_LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", ALARM_LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure alarm LED is off at start */
    if (gpioWrite(ALARM_LED_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize GPIO%d to LOW.\n", ALARM_LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Sound sensor monitoring started.\n");
    printf("  Sensor DO pin : GPIO%d (BCM)\n", SOUND_SENSOR_PIN);
    printf("  Alarm LED     : GPIO%d (BCM)\n", ALARM_LED_PIN);
    printf("Press Ctrl-C to exit.\n");

    /* --- Main monitoring loop --- */
    while (g_running) {
        int sound_level = gpioRead(SOUND_SENSOR_PIN);

        if (sound_level < 0) {
            fprintf(stderr, "Error: failed to read GPIO%d.\n", SOUND_SENSOR_PIN);
            break;
        }

        printf("Sound level: %d\n", sound_level);

        /* KY-038 DO goes LOW when sound exceeds threshold */
        if (sound_level == 0) {
            printf("Sound detected! Triggering alarm.\n");
            if (gpioWrite(ALARM_LED_PIN, 1) != 0) {
                fprintf(stderr, "Error: failed to turn on alarm LED.\n");
                break;
            }
            gpioDelay(ALARM_DURATION_US);
            if (gpioWrite(ALARM_LED_PIN, 0) != 0) {
                fprintf(stderr, "Error: failed to turn off alarm LED.\n");
                break;
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* --- Clean shutdown --- */
    gpioWrite(ALARM_LED_PIN, 0);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

