/*
 * SW-420 vibration monitor for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   SW-420 VCC  -> 5V  (pin 2 or 4)
 *   SW-420 GND  -> GND (pin 6)
 *   SW-420 DO   -> GPIO17 (BCM 17, physical pin 11)
 *
 * The sensor's DO line is active-low (idle HIGH, pulled LOW on vibration).
 * We request falling-edge events so that a LOW->HIGH transition is
 * interpreted as a vibration event.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o vibration_monitor vibration_monitor.c
 *
 * Run:
 *   sudo ./vibration_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>
#include <linux/gpio_event.h>

#define GPIO_CHIP       "/dev/gpiochip0"
#define GPIO_LINE       17
#define LOG_FILE        "/var/log/vibration_shutdown.log"
#define CONSUMER_LABEL  "vibration-monitor"

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_event(const char *message)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("time()");
        fclose(fp);
        return -1;
    }

    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r()");
        fclose(fp);
        return -1;
    }

    char ts[64];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s: %s\n", ts, message) < 0) {
        perror("fprintf()");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose()");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                        */
/* ------------------------------------------------------------------ */
static int gpio_request_falling_edge(int chip_fd, unsigned int offset)
{
    struct gpio_line_request req;
    memset(&req, 0, sizeof(req));

    req.line_offset = offset;
    req.request_type = GPIO_REQUEST_EVENT_FALLING_EDGE;
    req.flags = 0;
    strncpy(req.consumer, CONSUMER_LABEL, sizeof(req.consumer) - 1);
    req.consumer[sizeof(req.consumer) - 1] = '\0';

    if (ioctl(chip_fd, GPIO_GET_LINE_REQUEST_IOCTL, &req) < 0) {
        perror("ioctl(GPIO_GET_LINE_REQUEST_IOCTL)");
        return -1;
    }

    return 0;
}

static int gpio_wait_event(int chip_fd, struct gpio_event *event)
{
    ssize_t n = read(chip_fd, event, sizeof(*event));
    if (n < 0) {
        if (errno == EINTR) {
            return -1; /* interrupted by signal */
        }
        perror("read()");
        return -1;
    }
    if (n != (ssize_t)sizeof(*event)) {
        fprintf(stderr, "read() returned %zd bytes, expected %zu\n",
                n, sizeof(*event));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int chip_fd = -1;
    int ret = EXIT_FAILURE;

    if (install_signal_handlers() < 0) {
        goto cleanup;
    }

    chip_fd = open(GPIO_CHIP, O_RDONLY);
    if (chip_fd < 0) {
        perror("open(" GPIO_CHIP ")");
        goto cleanup;
    }

    if (gpio_request_falling_edge(chip_fd, GPIO_LINE) < 0) {
        goto cleanup;
    }

    printf("Vibration monitoring started on GPIO%d. Press Ctrl+C to exit.\n",
           GPIO_LINE);
    fflush(stdout);

    struct gpio_event event;

    while (g_running) {
        if (gpio_wait_event(chip_fd, &event) < 0) {
            if (!g_running) {
                break; /* signal received during wait */
            }
            continue;
        }

        /* Re-read the event to confirm the falling-edge type */
        if (ioctl(chip_fd, GPIO_GET_LINE_EVENT_IOCTL, &event) < 0) {
            perror("ioctl(GPIO_GET_LINE_EVENT_IOCTL)");
            continue;
        }

        if (event.event_type != GPIO_EVENT_FALLING_EDGE) {
            continue; /* unexpected event type */
        }

        printf("Vibration detected!\n");
        fflush(stdout);

        if (log_event("Vibration detected!") < 0) {
            fprintf(stderr, "Failed to log event.\n");
        }

        int rc = system("sudo shutdown -h now");
        if (rc == -1) {
            perror("system(shutdown)");
        } else if (rc != 0) {
            fprintf(stderr, "Shutdown command returned %d\n", rc);
        }
        break;
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (chip_fd >= 0) {
        if (close(chip_fd) < 0) {
            perror("close(chip_fd)");
        }
    }
    return ret;
}

