code:
/*
 * BMP280 Altitude Logger for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   BMP280 SDA  -> GPIO2 (pin 3, I2C bus 1 SDA)
 *   BMP280 SCL  -> GPIO3 (pin 5, I2C bus 1 SCL)
 *   BMP280 VDD  -> 3.3 V
 *   BMP280 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o bmp280_altitude bmp280_altitude.c -lpigpio -lrt
 * Run:    sudo ./bmp280_altitude
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- BMP280 constants (datasheet rev 1.26) ---- */
#define BMP280_I2C_ADDR        0x76   /* SDO tied to GND */
#define BMP280_REG_ID          0xD0
#define BMP280_REG_RESET       0xE0
#define BMP280_REG_STATUS      0xF3
#define BMP280_REG_CTRL_MEAS   0xF4
#define BMP280_REG_CONFIG      0xF5
#define BMP280_REG_PRESS_MSB   0xF7
#define BMP280_REG_TEMP_MSB    0xFA
#define BMP280_REG_CALIB00     0x88
#define BMP280_CHIP_ID         0x58
#define BMP280_RESET_CMD       0xB6

/* ctrl_meas: osrs_t=001 (x1), osrs_p=001 (x1), mode=11 (forced) -> 0x27 */
#define BMP280_CTRL_MEAS_FORCED 0x27
/* config: t_sb=000 (0.5ms), filter=000 (off), spi3w_en=0 -> 0x00 */
#define BMP280_CONFIG_DEFAULT   0x00

/* ---- Globals for cleanup ---- */
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;
static volatile sig_atomic_t g_terminate = 0;

/* Calibration coefficients (read once from sensor) */
static uint16_t dig_T1;
static int16_t  dig_T2, dig_T3;
static uint16_t dig_P1;
static int16_t  dig_P2, dig_P3, dig_P4, dig_P5, dig_P6, dig_P7, dig_P8, dig_P9;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_terminate = 1;
}

/* ---- Low-level I2C helpers ---- */
static int i2c_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len)
{
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc != (int)len) {
        fprintf(stderr, "I2C read block failed at reg 0x%02X (rc=%d, expected=%u)\n",
                reg, rc, len);
        return -1;
    }
    return 0;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t val)
{
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write byte failed at reg 0x%02X (rc=%d)\n", reg, rc);
        return -1;
    }
    return 0;
}

/* ---- Sensor init ---- */
static int bmp280_init(int handle)
{
    uint8_t id;
    if (i2c_read_block(handle, BMP280_REG_ID, &id, 1) != 0)
        return -1;
    if (id != BMP280_CHIP_ID) {
        fprintf(stderr, "Chip ID mismatch: got 0x%02X, expected 0x%02X\n",
                id, BMP280_CHIP_ID);
        return -1;
    }

    if (i2c_write_byte(handle, BMP280_REG_RESET, BMP280_RESET_CMD) != 0)
        return -1;
    gpioDelay(2000); /* 2 ms reset wait */

    /* Wait for NVM calibration to become ready (status bit 3 = calib) */
    for (int i = 0; i < 20; i++) {
        uint8_t status;
        if (i2c_read_block(handle, BMP280_REG_STATUS, &status, 1) != 0)
            return -1;
        if ((status & 0x08) == 0)
            break;
        gpioDelay(2000);
    }

    if (i2c_write_byte(handle, BMP280_REG_CONFIG, BMP280_CONFIG_DEFAULT) != 0)
        return -1;
    if (i2c_write_byte(handle, BMP280_REG_CTRL_MEAS, BMP280_CTRL_MEAS_FORCED) != 0)
        return -1;

    return 0;
}

/* ---- Read calibration coefficients ---- */
static int bmp280_read_calibration(int handle)
{
    uint8_t cal[24];
    if (i2c_read_block(handle, BMP280_REG_CALIB00, cal, sizeof(cal)) != 0)
        return -1;

    dig_T1 = (uint16_t)((cal[1]  << 8) | cal[0]);
    dig_T2 = (int16_t) ((cal[3]  << 8) | cal[2]);
    dig_T3 = (int16_t) ((cal[5]  << 8) | cal[4]);
    dig_P1 = (uint16_t)((cal[7]  << 8) | cal[6]);
    dig_P2 = (int16_t) ((cal[9]  << 8) | cal[8]);
    dig_P3 = (int16_t) ((cal[11] << 8) | cal[10]);
    dig_P4 = (int16_t) ((cal[13] << 8) | cal[12]);
    dig_P5 = (int16_t) ((cal[15] << 8) | cal[14]);
    dig_P6 = (int16_t) ((cal[17] << 8) | cal[16]);
    dig_P7 = (int16_t) ((cal[19] << 8) | cal[18]);
    dig_P8 = (int16_t) ((cal[21] << 8) | cal[20]);
    dig_P9 = (int16_t) ((cal[23] << 8) | cal[22]);
    return 0;
}

/* ---- Trigger forced measurement and read raw data ---- */
static int bmp280_read_raw(int handle, int32_t *raw_t, int32_t *raw_p)
{
    if (i2c_write_byte(handle, BMP280_REG_CTRL_MEAS, BMP280_CTRL_MEAS_FORCED) != 0)
        return -1;

    /* Wait for measurement to complete (status bit 3 = measuring) */
    for (int i = 0; i < 20; i++) {
        uint8_t status;
        if (i2c_read_block(handle, BMP280_REG_STATUS, &status, 1) != 0)
            return -1;
        if ((status & 0x08) == 0)
            break;
        gpioDelay(2000);
    }

    uint8_t data[6];
    if (i2c_read_block(handle, BMP280_REG_PRESS_MSB, data, 6) != 0)
        return -1;

    *raw_p = ((int32_t)data[0] << 12) | ((int32_t)data[1] << 4) | (data[2] >> 4);
    *raw_t = ((int32_t)data[3] << 12) | ((int32_t)data[4] << 4) | (data[5] >> 4);
    return 0;
}

/* ---- Compensation (datasheet 3.11.3 / 3.11.4) ---- */
static double bmp280_compensate_temp(int32_t raw_t, int32_t *t_fine)
{
    double v1 = ((double)raw_t / 16384.0 - (double)dig_T1 / 1024.0) * (double)dig_T2;
    double v2 = (((double)raw_t / 131072.0 - (double)dig_T1 / 8192.0) *
                 ((double)raw_t / 131072.0 - (double)dig_T1 / 8192.0)) * (double)dig_T3;
    *t_fine = (int32_t)(v1 + v2);
    return (v1 + v2) / 5120.0;
}

static double bmp280_compensate_press(int32_t raw_p, int32_t t_fine)
{
    double v1 = ((double)t_fine / 2.0) - 64000.0;
    double v2 = v1 * v1 * (double)dig_P6 / 32768.0;
    v2 = v2 + v1 * (double)dig_P5 * 2.0;
    v2 = (v2 / 4.0) + ((double)dig_P4 * 65536.0);
    v1 = ((double)dig_P3 * v1 * v1 / 524288.0 + (double)dig_P2 * v1) / 524288.0;
    v1 = (1.0 + v1 / 32768.0) * (double)dig_P1;

    if (v1 == 0.0)
        return 0.0; /* avoid div-by-zero */

    double p = 1048576.0 - (double)raw_p;
    p = (p - (v2 / 4096.0)) * 6250.0 / v1;
    v1 = (double)dig_P9 * p * p / 2147483648.0;
    v2 = p * (double)dig_P8 / 32768.0;
    p = p + (v1 + v2 + (double)dig_P7) / 16.0;
    return p;
}

static double calculate_altitude(double pressure_hpa)
{
    const double sea_level_hpa = 1013.25;
    return 44330.0 * (1.0 - pow(pressure_hpa / sea_level_hpa, 0.1903));
}

/* ---- Logging ---- */
static void log_data(FILE *fp, double altitude)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    fprintf(fp, "%s,%.2f\n", ts, altitude);
    fflush(fp);
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(1, BMP280_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (rc=%d) — check wiring and that the sensor is present at 0x%02X\n",
                g_i2c_handle, BMP280_I2C_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (bmp280_init(g_i2c_handle) != 0) {
        fprintf(stderr, "BMP280 init failed — sensor may be absent or not responding\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (bmp280_read_calibration(g_i2c_handle) != 0) {
        fprintf(stderr, "Failed to read calibration data\n");
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_file = fopen("altitude_log.txt", "a");
    if (!g_log_file) {
        fprintf(stderr, "Error opening altitude_log.txt: %m\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("BMP280 initialised. Logging altitude every 5 s. Press Ctrl+C to stop.\n");

    while (!g_terminate) {
        int32_t raw_t = 0, raw_p = 0;
        if (bmp280_read_raw(g_i2c_handle, &raw_t, &raw_p) != 0) {
            fprintf(stderr, "Sensor read error — continuing\n");
            gpioDelay(5000000);
            continue;
        }

        int32_t t_fine;
        double temp_c = bmp280_compensate_temp(raw_t, &t_fine);
        double press_hpa = bmp280_compensate_press(raw_p, t_fine) / 100.0;
        double altitude = calculate_altitude(press_hpa);

        log_data(g_log_file, altitude);
        printf("Altitude: %.2f m  (T=%.2f C)\n", altitude, temp_c);

        gpioDelay(5000000); /* 5 s */
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

