#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>

#define BH1750_ADDR 0x23
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x10
#define BH1750_CONV_TIME_MS 180

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define MCP3008_CHANNEL 0

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_byte(int fd, uint8_t *value) {
    if (read(fd, value, 1) != 1) {
        return -1;
    }
    return 0;
}

static int i2c_write_byte(int fd, uint8_t value) {
    if (write(fd, &value, 1) != 1) {
        return -1;
    }
    return 0;
}

static int read_bh1750(int fd, float *lux) {
    if (i2c_write_byte(fd, BH1750_CONTINUOUS_HIGH_RES_MODE) < 0) {
        return -1;
    }
    usleep(BH1750_CONV_TIME_MS * 1000);

    uint8_t msb, lsb;
    if (i2c_read_byte(fd, &msb) < 0) {
        return -1;
    }
    if (i2c_read_byte(fd, &lsb) < 0) {
        return -1;
    }

    uint16_t raw = ((uint16_t)msb << 8) | lsb;
    *lux = (float)raw / 1.2f;
    return 0;
}

static int read_mcp3008(int fd, int channel, int *value) {
    if (channel < 0 || channel > 7) {
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
        .tx_nbits = 0,
        .rx_nbits = 0,
        .pad = 0
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        return -1;
    }

    *value = ((rx[1] & 0x03) << 8) | rx[2];
    return 0;
}

static void log_data(float lux, int sound_level) {
    FILE *fp = fopen("environmental_log.txt", "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, Light: %.2f, Sound: %d\n", timestamp, lux, sound_level);
    fclose(fp);
}

