        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        close(i2c_fd);
        return 1;
    }

    uint8_t spi_mode = SPI_MODE_0;
    uint8_t spi_bits = 8;
    uint32_t spi_speed = SPI_SPEED;

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &spi_mode) < 0) {
        perror("Failed to set SPI mode");
        goto cleanup;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &spi_bits) < 0) {
        perror("Failed to set SPI bits per word");
        goto cleanup;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &spi_speed) < 0) {
        perror("Failed to set SPI max speed");
        goto cleanup;
    }

    printf("Environmental monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        float lux = 0.0f;
        int sound_level = 0;
        int bh1750_error = 0;
        int mcp3008_error = 0;

        if (read_bh1750(i2c_fd, &lux) < 0) {
            fprintf(stderr, "Error reading BH1750 sensor: %s\n", strerror(errno));
            bh1750_error = 1;
        }

        if (read_mcp3008(spi_fd, MCP3008_CHANNEL, &sound_level) < 0) {
            fprintf(stderr, "Error reading MCP3008 channel %d: %s\n", MCP3008_CHANNEL, strerror(errno));
            mcp3008_error = 1;
        }

        if (!bh1750_error && !mcp3008_error) {
            log_data(lux, sound_level);
        } else {
            fprintf(stderr, "Sensor read error. Skipping logging.\n");
        }

        sleep(1);
    }

cleanup:
    printf("\nCleaning up and exiting...\n");
    close(i2c_fd);
    close(spi_fd);
    return 0;
}

