#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define FLAME_SENSOR_PIN 17
#define LOG_FILE "flame_events.log"
#define POLL_INTERVAL_US 1000000

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int log_event(FILE *fp, int pin, int state) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%d,%d\n", timestamp, pin, state) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    FILE *log_fp = NULL;
    int ret = EXIT_FAILURE;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", FLAME_SENSOR_PIN);
        goto cleanup;
    }

    if (gpioSetPullUpDown(FLAME_SENSOR_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down on GPIO %d\n", FLAME_SENSOR_PIN);
        goto cleanup;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    if (fprintf(log_fp, "# Flame sensor monitoring started on GPIO %d\n", FLAME_SENSOR_PIN) < 0) {
        fprintf(stderr, "Error writing header to log file: %s\n", strerror(errno));
        goto cleanup;
    }

    if (fflush(log_fp) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        goto cleanup;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        goto cleanup;
    }

    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("Flame sensor monitoring started on GPIO %d. Press Ctrl+C to exit.\n", FLAME_SENSOR_PIN);

    while (program_running) {
        int state = gpioRead(FLAME_SENSOR_PIN);

        if (state < 0) {
            fprintf(stderr, "Error reading GPIO %d: %s\n", FLAME_SENSOR_PIN, strerror(errno));
            goto cleanup;
        }

        if (log_event(log_fp, FLAME_SENSOR_PIN, state) != 0) {
            goto cleanup;
        }

        if (state == 1) {
            printf("ALARM: Flame detected on GPIO %d!\n", FLAME_SENSOR_PIN);
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nExiting gracefully...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (log_fp != NULL) {
        if (fclose(log_fp) != 0) {
            fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        }
    }
    gpioTerminate();
    return ret;
}

