    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to register signal handler\n");
        cleanup();
        return 1;
    }

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            int adc_value = read_mcp3008(sensor_channels[i]);
            if (adc_value < 0) {
                fprintf(stderr, "Error: Failed to read sensor %d\n", i + 1);
                continue;
            }

            float moisture = calculate_moisture(adc_value);
            if (moisture < 0.0f) {
                fprintf(stderr, "Error: Invalid moisture reading from sensor %d\n", i + 1);
                continue;
            }

            log_data(i + 1, moisture);
        }

        if (running) {
            sleep(SLEEP_INTERVAL);
        }
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    printf("Resources released. Goodbye.\n");
    return 0;
}

