static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int deactivate_all_relays(void)
{
    int pins[NUM_RELAYS] = { RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN };
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpioWrite(pins[i], 0) != 0) {
            fprintf(stderr, "Warning: failed to deactivate relay on BCM %d\n",
                    pins[i]);
        }
    }
    return 0;
}

int main(void)
{
    int pins[NUM_RELAYS] = { RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN };

    /* --- Initialize pigpio daemon/library --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed (code %d).\n",
                gpioInitialise());
        return EXIT_FAILURE;
    }

    /* --- Configure relay pins as outputs --- */
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: gpioSetMode failed for BCM %d.\n",
                    pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    /* --- Ensure all relays start in the OFF state --- */
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpioWrite(pins[i], 0) != 0) {
            fprintf(stderr, "Error: gpioWrite(0) failed for BCM %d.\n",
                    pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    /* --- Install signal handlers for graceful shutdown --- */
    if (install_signal_handlers() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Relay sequencer started.  Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* --- Main sequencing loop --- */
    while (g_running) {
        for (int i = 0; i < NUM_RELAYS && g_running; i++) {
            /* Activate relay (active-high: HIGH energizes the module) */
            if (gpioWrite(pins[i], 1) != 0) {
                fprintf(stderr, "Error: gpioWrite(1) failed for BCM %d.\n",
                        pins[i]);
                goto cleanup;
            }

            /* Keep relay energized for 1 second */
            gpioDelay(CYCLE_DELAY_US);

            /* Deactivate relay (LOW de-energizes the module) */
            if (gpioWrite(pins[i], 0) != 0) {
                fprintf(stderr, "Error: gpioWrite(0) failed for BCM %d.\n",
                        pins[i]);
                goto cleanup;
            }

            /* Inter-relay delay */
            gpioDelay(CYCLE_DELAY_US);
        }
    }

cleanup:
    /* --- Graceful shutdown: deactivate all relays and release GPIO --- */
    deactivate_all_relays();
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

