    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen log file");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    while (running) {
        int rain_level = read_mcp3008(0);
        if (rain_level < 0) {
            fprintf(stderr, "Failed to read rain sensor\n");
        } else {
            if (log_rain_level(rain_level) != 0) {
                fprintf(stderr, "Failed to log rain level\n");
            }
            if (rain_level > RAIN_THRESHOLD) {
                control_motor(1);
                sleep(3);
                control_motor(0);
            } else {
                control_motor(-1);
                sleep(3);
                control_motor(0);
            }
        }
        sleep(1);
    }

    cleanup();
    return 0;
}

