#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define ADC_CS_PIN 26
#define ADC_CLK_PIN 21
#define ADC_DIN_PIN 20
#define ADC_DOUT_PIN 26
#define LED_PIN 16

#define ADC_CHANNEL 0
#define ADC_RESOLUTION 10
#define ADC_VREF 3.3
#define ADC_MAX_VALUE (1 << ADC_RESOLUTION) - 1

#define SAMPLE_RATE 1000
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE)
#define DEBOUNCE_MS 50
#define LED_ON_MS 500

#define THRESHOLD_HIGH 0.5
#define THRESHOLD_LOW 0.3

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    gpioWrite(ADC_CS_PIN, 0);
    gpioDelay(1);

    uint32_t command = 0x8000 | (channel << 12);
    for (int i = 11; i >= 0; i--) {
        gpioWrite(ADC_CLK_PIN, 0);
        gpioDelay(1);
        gpioWrite(ADC_DIN_PIN, (command >> i) & 1);
        gpioDelay(1);
        gpioWrite(ADC_CLK_PIN, 1);
        gpioDelay(1);
    }

    uint32_t result = 0;
    for (int i = 0; i < ADC_RESOLUTION; i++) {
        gpioWrite(ADC_CLK_PIN, 0);
        gpioDelay(1);
        gpioWrite(ADC_CLK_PIN, 1);
        gpioDelay(1);
        result <<= 1;
        if (gpioRead(ADC_DOUT_PIN)) {
            result |= 1;
        }
    }

    gpioWrite(ADC_CS_PIN, 1);
    return (int)result;
}

static double adc_to_voltage(int adc_value) {
    return ((double)adc_value / (double)ADC_MAX_VALUE) * ADC_VREF;
}

static bool detect_clap(double voltage) {
    static bool in_clap = false;
    static uint32_t last_detection_time = 0;

    uint32_t now = gpioTick();

    if (voltage > THRESHOLD_HIGH && !in_clap) {
        in_clap = true;
        last_detection_time = now;
        return false;
    } else if (voltage < THRESHOLD_LOW && in_clap) {
        in_clap = false;
        if (now - last_detection_time >= DEBOUNCE_MS * 1000) {
            return true;
        }
    }
    return false;
}

static void trigger_led(void) {
    gpioWrite(LED_PIN, 1);
    gpioDelay(LED_ON_MS * 1000);
    gpioWrite(LED_PIN, 0);
}

static void log_detection(void) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] Clap detected!\n", timestamp);
    fflush(stdout);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(ADC_CS_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(ADC_CLK_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(ADC_DIN_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(ADC_DOUT_PIN, PI_INPUT) != 0 ||
        gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioWrite(ADC_CS_PIN, 1);
    gpioWrite(ADC_CLK_PIN, 0);
    gpioWrite(LED_PIN, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register signal handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Clap detection started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (running) {
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read error\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        double voltage = adc_to_voltage(adc_value);

        if (detect_clap(voltage)) {
            trigger_led();
            log_detection();
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

