#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#define GPIO_PIN 17
#define LOG_FILE "distance_log.txt"
#define FEEDER_THRESHOLD 200
#define POLL_INTERVAL_SEC 1

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_distance(void) {
    char path[64];
    char value_str[4];
    int distance = -1;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", GPIO_PIN);
    FILE *fp = fopen(path, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening GPIO value file: %s\n", strerror(errno));
        return -1;
    }

    if (fgets(value_str, sizeof(value_str), fp) == NULL) {
        fprintf(stderr, "Error reading GPIO value: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);

    distance = atoi(value_str);
    if (distance < 0 || distance > 1000) {
        fprintf(stderr, "Invalid distance value: %d\n", distance);
        return -1;
    }
    return distance;
}

static void log_distance(int distance) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, Distance: %d mm\n", timestamp, distance);
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    char export_path[64];
    snprintf(export_path, sizeof(export_path), "/sys/class/gpio/export");
    FILE *export_fp = fopen(export_path, "w");
    if (export_fp == NULL) {
        if (errno != EBUSY) {
            fprintf(stderr, "Error opening export file: %s\n", strerror(errno));
            return 1;
        }
    } else {
        fprintf(export_fp, "%d", GPIO_PIN);
        fclose(export_fp);
    }

    char direction_path[64];
    snprintf(direction_path, sizeof(direction_path), "/sys/class/gpio/gpio%d/direction", GPIO_PIN);
    export_fp = fopen(direction_path, "w");
    if (export_fp == NULL) {
        fprintf(stderr, "Error opening direction file: %s\n", strerror(errno));
        return 1;
    }
    fprintf(export_fp, "in");
    fclose(export_fp);

    while (running) {
        int distance = read_distance();
        if (distance < 0) {
            sleep(POLL_INTERVAL_SEC);
            continue;
        }

        log_distance(distance);

        if (distance < FEEDER_THRESHOLD) {
            printf("Feeder Activated\n");
        } else {
            printf("Feeder Idle\n");
        }
        fflush(stdout);

        sleep(POLL_INTERVAL_SEC);
    }

    char unexport_path[64];
    snprintf(unexport_path, sizeof(unexport_path), "/sys/class/gpio/unexport");
    export_fp = fopen(unexport_path, "w");
    if (export_fp != NULL) {
        fprintf(export_fp, "%d", GPIO_PIN);
        fclose(export_fp);
    }

    printf("Program terminated gracefully.\n");
    return 0;
}

