#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <linux/gpio.h>
#include <linux/gpio/driver.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define GPIO_CHIP       "/dev/gpiochip0"
#define GPIO_ENABLE     17
#define ADC_CHANNEL     0
#define ADC_MAX         1023
#define VREF            5.0
#define SENSITIVITY     0.1
#define LOG_FILE        "current_log.txt"
#define SAMPLE_DELAY_S  1

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;
static int g_gpio_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int spi_init(void)
{
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    unsigned int mode = SPI_MODE_0;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    unsigned int bits = 8;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    unsigned int speed = 1000000;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI max speed: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    return 0;
}

static int gpio_init(void)
{
    g_gpio_fd = open(GPIO_CHIP, O_RDWR);
    if (g_gpio_fd < 0) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return -1;
    }

    struct gpiohandle_request req;
    memset(&req, 0, sizeof(req));
    req.lineoffsets[0] = GPIO_ENABLE;
    req.flags = GPIOHANDLE_REQUEST_OUTPUT;
    req.default_values[0] = 1;
    strncpy(req.consumer_label, "mlx91209_enable", sizeof(req.consumer_label) - 1);
    req.consumer_label[sizeof(req.consumer_label) - 1] = '\0';
    req.lines = 1;

    if (ioctl(g_gpio_fd, GPIO_GET_LINEHANDLE_IOCTL, &req) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d: %s\n", GPIO_ENABLE, strerror(errno));
        close(g_gpio_fd);
        g_gpio_fd = -1;
        return -1;
    }

    return 0;
}

static int read_adc(int channel)
{
    if (g_spi_fd < 0) {
        fprintf(stderr, "SPI device not initialized\n");
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = 3;
    tr.speed_hz = 1000000;
    tr.bits_per_word = 8;

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Error sending SPI message: %s\n", strerror(errno));
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static double adc_to_current(int adc_value)
{
    double voltage = (double)adc_value / (double)ADC_MAX * VREF;
    return voltage / SENSITIVITY;
}

static int log_data(double current)
{
    if (g_log_fp == NULL) {
        fprintf(stderr, "Log file not open\n");
        return -1;
    }

    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(g_log_fp, "%s,%.3f\n", timestamp, current) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(g_log_fp) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_gpio_fd >= 0) {
        struct gpiohandle_request req;
        memset(&req, 0, sizeof(req));
        req.lineoffsets[0] = GPIO_ENABLE;
        req.flags = GPIOHANDLE_REQUEST_OUTPUT;
        req.default_values[0] = 0;
        req.lines = 1;
        ioctl(g_gpio_fd, GPIO_GET_LINEHANDLE_IOCTL, &req);
        close(g_gpio_fd);
        g_gpio_fd = -1;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (spi_init() < 0) {
        return 1;
    }

    if (gpio_init() < 0) {
        cleanup();
        return 1;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    printf("Starting current monitoring. Press Ctrl+C to exit.\n");

    while (g_running) {
        if (ioctl(g_gpio_fd, GPIOHANDLE_GET_LINE_VALUES_IOCTL, NULL) < 0) {
            fprintf(stderr, "Error reading GPIO value: %s\n", strerror(errno));
            sleep(SAMPLE_DELAY_S);
            continue;
        }

        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value\n");
            sleep(SAMPLE_DELAY_S);
            continue;
        }

        double current = adc_to_current(adc_value);

        if (log_data(current) < 0) {
            fprintf(stderr, "Error logging data\n");
        }

        sleep(SAMPLE_DELAY_S);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

