{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    int spi_fd = -1;
    if (spi_init(&spi_fd) < 0) {
        return 1;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n",
                LOG_FILE, strerror(errno));
        close(spi_fd);
        return 1;
    }

    printf("Starting current monitoring. Press Ctrl+C to exit.\n");

    while (g_running) {
        int adc_value = 0;

        if (read_adc(spi_fd, ADC_CHANNEL, &adc_value) < 0) {
            fprintf(stderr, "Error reading ADC value, skipping sample.\n");
            usleep(SAMPLE_DELAY_US);
            continue;
        }

        float current = adc_to_current(adc_value);

        if (current < 0.0f || current > 10.0f) {
            fprintf(stderr, "Warning: Current value %.2f A out of range, skipping sample.\n",
                    current);
            usleep(SAMPLE_DELAY_US);
            continue;
        }

        if (log_current(fp, current) < 0) {
            fprintf(stderr, "Error logging current value, exiting.\n");
            fclose(fp);
            close(spi_fd);
            return 1;
        }

        usleep(SAMPLE_DELAY_US);
    }

    printf("\nExiting gracefully.\n");

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
    }

    if (close(spi_fd) < 0) {
        fprintf(stderr, "Error closing SPI device: %s\n", strerror(errno));
    }

    return 0;
}

