#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <stdbool.h>

#define SENSOR_1_GPIO 4
#define SENSOR_2_GPIO 17
#define DEBOUNCE_SAMPLES 5
#define DEBOUNCE_DELAY_US 2000
#define POLL_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor_debounced(int gpio_pin) {
    int ones = 0;
    for (int i = 0; i < DEBOUNCE_SAMPLES; i++) {
        int v = gpioRead(gpio_pin);
        if (v < 0) {
            fprintf(stderr, "Error reading GPIO %d: %s\n", gpio_pin, pigpio_error(v));
            return -1;
        }
        if (v == 1) ones++;
        if (i < DEBOUNCE_SAMPLES - 1) {
            gpioDelay(DEBOUNCE_DELAY_US);
        }
    }
    return (ones >= (DEBOUNCE_SAMPLES + 1) / 2) ? 1 : 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to register SIGINT handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_1_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR_2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_2_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_1_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", SENSOR_1_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(SENSOR_2_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", SENSOR_2_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        int s1 = read_sensor_debounced(SENSOR_1_GPIO);
        int s2 = read_sensor_debounced(SENSOR_2_GPIO);

        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "Sensor read error, exiting\n");
            break;
        }

        printf("Sensor 1: %d, Sensor 2: %d\n", s1, s2);
        fflush(stdout);

        if (s1 == 1 && s2 == 1) {
            printf("ALERT: Both sensors detect object\n");
            fflush(stdout);
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

