#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <driver/spi_master.h>
#include <driver/gpio.h>

#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define MCP3008_CHANNEL 0
#define READ_DELAY 60
#define MIN_ADC 300
#define MAX_ADC 800
#define LOG_FILE "soil_moisture_log.csv"

static int spi_handle = -1;
static volatile sig_atomic_t program_running = 1;

static int read_mcp3008(int channel);
static double calculate_moisture_level(int adc_value);
static int log_data(double moisture_level);
static void signal_handler(int signal);
static int spi_setup(spi_config_t config);

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    uint8_t tx_buf[3] = {0x01, (uint8_t)((0x08 | channel) << 4), 0x00};
    uint8_t rx_buf[3] = {0};

    spi_transaction_t transaction;
    memset(&transaction, 0, sizeof(transaction));
    transaction.length = 24;
    transaction.tx_buffer = tx_buf;
    transaction.rx_buffer = rx_buf;

    if (spi_device_transmit(spi_handle, &transaction) != ESP_OK) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    int adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
    return adc_value;
}

static double calculate_moisture_level(int adc_value) {
    if (adc_value < MIN_ADC) adc_value = MIN_ADC;
    if (adc_value > MAX_ADC) adc_value = MAX_ADC;
    return 100.0 - ((double)(adc_value - MIN_ADC) / (double)(MAX_ADC - MIN_ADC) * 100.0);
}

static int log_data(double moisture_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        return -1;
    }

    fprintf(fp, "%s,%.2f\n", timestamp, moisture_level);
    fclose(fp);
    return 0;
}

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static int spi_setup(spi_config_t config) {
