static int spi_setup(spi_config_t config);

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    uint8_t tx_buf[3] = {0x01, (uint8_t)((0x08 | channel) << 4), 0x00};
    uint8_t rx_buf[3] = {0};

    spi_transaction_t transaction;
    memset(&transaction, 0, sizeof(transaction));
    transaction.length = 24;
    transaction.tx_buffer = tx_buf;
    transaction.rx_buffer = rx_buf;

    if (spi_device_transmit(spi_handle, &transaction) != ESP_OK) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    int adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
    return adc_value;
}

