/*
 * security_cam.c — Raspberry Pi 4 Model B
 *
 * Monitors an HC-SR501 PIR sensor on GPIO17 (BCM) with a 200 ms debounce
 * after a state change, then captures a libcamera-still JPEG snapshot
 * into /home/pi/security_cam/ with a timestamped filename.
 *
 * Build:  gcc -O2 -Wall -Wextra -o security_cam security_cam.c -lgpiod
 * Run:    sudo ./security_cam   (root needed for libcamera access)
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <syslog.h>
#include <sys/wait.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <gpiod.h>

#define PIR_PIN          17
#define DEBOUNCE_MS      200
#define POLL_MS          50
#define CAPTURE_DIR      "/home/pi/security_cam"
#define MAX_FILENAME     256
#define MAX_PATH         512

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1)
        syslog(LOG_WARNING, "sigaction(SIGINT) failed: %m");
    if (sigaction(SIGTERM, &sa, NULL) == -1)
        syslog(LOG_WARNING, "sigaction(SIGTERM) failed: %m");
}

/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    time_t t = time(NULL);
    struct tm tmv;
    if (localtime_r(&t, &tmv) != NULL)
        strftime(buf, len, "%Y-%m-%dT%H:%M:%S%z", &tmv);
    else
        snprintf(buf, len, "UNKNOWN");
}

/* ------------------------------------------------------------------ */
static int ensure_directory(const char *path)
{
    struct stat st;
    if (stat(path, &st) == 0) {
        if (S_ISDIR(st.st_mode))
            return 0;
        syslog(LOG_ERR, "Path '%s' exists but is not a directory", path);
        return -1;
    }
    if (errno != ENOENT) {
        syslog(LOG_ERR, "stat('%s') failed: %m", path);
        return -1;
    }
    if (mkdir(path, 0755) == -1) {
        syslog(LOG_ERR, "mkdir('%s') failed: %m", path);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int capture_image(const char *filepath)
{
    pid_t pid = fork();
    if (pid == -1) {
        syslog(LOG_ERR, "fork() failed: %m");
        return -1;
    }

    if (pid == 0) {
        /* Child: redirect stdout/stderr to /dev/null to keep syslog clean */
        freopen("/dev/null", "w", stdout);
        freopen("/dev/null", "w", stderr);

        char *const argv[] = {
            "libcamera-still",
            "-o", (char *)filepath,
            "--nopreview",
            "--timeout", "1000",
            "--width", "1280",
            "--height", "720",
            NULL
        };

        execvp("libcamera-still", argv);
        syslog(LOG_ERR, "execvp(libcamera-still) failed: %m");
        _exit(127);
    }

    /* Parent: wait for child and check exit status */
    int status = 0;
    while (waitpid(pid, &status, 0) == -1) {
        if (errno == EINTR) {
            if (!g_running)
                return -1;
            continue;
        }
        syslog(LOG_ERR, "waitpid() failed: %m");
        return -1;
    }

    if (WIFEXITED(status) && WEXITSTATUS(status) == 0)
        return 0;

    syslog(LOG_ERR, "libcamera-still failed (exit status %d)",
           WIFEXITED(status) ? WEXITSTATUS(status) : -1);
    return -1;
}

/* ------------------------------------------------------------------ */
static int generate_filename(char *buf, size_t len)
{
    char ts[32];
    get_timestamp(ts, sizeof(ts));

    if (snprintf(buf, len, "%s/motion_%s.jpg", CAPTURE_DIR, ts) >= (int)len) {
        syslog(LOG_ERR, "Filename too long");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    openlog("security_cam", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting security camera monitor");

    install_signal_handlers();

    if (ensure_directory(CAPTURE_DIR) != 0) {
        syslog(LOG_ERR, "Cannot use capture directory '%s'", CAPTURE_DIR);
        closelog();
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        syslog(LOG_ERR, "gpiod_chip_open_by_name failed: %m");
        closelog();
        return EXIT_FAILURE;
    }

    struct gpiod_line *pir = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir) {
        syslog(LOG_ERR, "gpiod_chip_get_line(%d) failed: %m", PIR_PIN);
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input_flags(pir, "security_cam",
                                       GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_DOWN) < 0) {
        syslog(LOG_ERR, "gpiod_line_request_input_flags failed: %m");
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "PIR sensor monitoring started on GPIO%d", PIR_PIN);

    int last_state = gpiod_line_get_value(pir);
    if (last_state < 0) {
        syslog(LOG_ERR, "Initial gpiod_line_get_value failed: %m");
        gpiod_line_release(pir);
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    while (g_running) {
        int val = gpiod_line_get_value(pir);
        if (val < 0) {
            syslog(LOG_ERR, "gpiod_line_get_value failed: %m");
            usleep(POLL_MS * 1000);
            continue;
        }

        if (val != last_state) {
            syslog(LOG_INFO, "Motion detected (state %d -> %d)",
                   last_state, val);

            usleep(DEBOUNCE_MS * 1000);

            int confirm = gpiod_line_get_value(pir);
            if (confirm < 0) {
                syslog(LOG_ERR, "Confirm read failed: %m");
                last_state = val;
                continue;
            }

            if (confirm == val) {
                char filepath[MAX_PATH];
                if (generate_filename(filepath, sizeof(filepath)) != 0) {
                    last_state = val;
                    continue;
                }

                syslog(LOG_INFO, "Capturing image: %s", filepath);
                if (capture_image(filepath) == 0) {
                    syslog(LOG_INFO, "Image captured successfully: %s", filepath);
                } else {
                    syslog(LOG_ERR, "Failed to capture image: %s", filepath);
                }
            }

            last_state = val;
        }

        usleep(POLL_MS * 1000);
    }

    syslog(LOG_INFO, "Shutting down");
    gpiod_line_release(pir);
    gpiod_chip_close(chip);
    closelog();
    return EXIT_SUCCESS;
}

