#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <linux/videodev2.h>
#include <signal.h>

#define DEFAULT_DEVICE "/dev/video0"
#define MAX_FILENAME 64
#define MAX_IMAGE_NUMBER 1000000
#define SELECT_TIMEOUT_SEC 2

static volatile sig_atomic_t g_stop = 0;

static void signal_handler(int sig) {
    (void)sig;
    g_stop = 1;
}

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static int capture_image(int fd, unsigned char *buffer, size_t buffer_size, int *image_number) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
        if (errno == EAGAIN) {
            return -1;
        }
        fprintf(stderr, "VIDIOC_DQBUF failed: %s\n", strerror(errno));
        return -2;
    }

    if (buf.bytesused > buffer_size) {
        fprintf(stderr, "Buffer overflow: bytesused=%zu, buffer_size=%zu\n", buf.bytesused, buffer_size);
        xioctl(fd, VIDIOC_QBUF, &buf);
        return -3;
    }

    char filename[MAX_FILENAME];
    snprintf(filename, sizeof(filename), "image_%04d.pgm", *image_number);

    FILE *fp = fopen(filename, "wb");
    if (!fp) {
        fprintf(stderr, "Failed to open %s: %s\n", filename, strerror(errno));
        xioctl(fd, VIDIOC_QBUF, &buf);
        return -4;
    }

    if (fwrite(buffer, 1, buf.bytesused, fp) != buf.bytesused) {
        fprintf(stderr, "Failed to write %s: %s\n", filename, strerror(errno));
        fclose(fp);
        xioctl(fd, VIDIOC_QBUF, &buf);
        return -5;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Failed to close %s: %s\n", filename, strerror(errno));
        xioctl(fd, VIDIOC_QBUF, &buf);
        return -6;
    }

    (*image_number)++;
    printf("Saved %s (%zu bytes)\n", filename, buf.bytesused);

