    const char *api_call_2 = argv[2];

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Error setting up signal handler");
        return 1;
    }

    int fd = -1;
    buffer_t buffers[NUM_BUFFERS];
    for (int i = 0; i < NUM_BUFFERS; i++) {
        buffers[i].start = NULL;
        buffers[i].length = 0;
    }

    if (init_camera(&fd, buffers) < 0) {
        fprintf(stderr, "Error initializing camera\n");
        return 1;
    }

    int sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("Error creating socket");
        cleanup_camera(fd, buffers);
        return 1;
    }

    unsigned char frame_buffer[WIDTH * HEIGHT * 2];
    unsigned char packet[MAX_FRAME_SIZE];
    int frame_index = 0;

    while (running) {
        if (capture_frame(fd, frame_buffer, sizeof(frame_buffer)) < 0) {
            fprintf(stderr, "Error capturing frame\n");
            break;
        }

        int num_fragments = (WIDTH * HEIGHT * 2 + MAX_FRAME_SIZE - 1) / MAX_FRAME_SIZE;
        for (int i = 0; i < num_fragments; i++) {
            size_t payload_size = MAX_FRAME_SIZE - sizeof(int) * 4;
            size_t remaining = WIDTH * HEIGHT * 2 - i * MAX_FRAME_SIZE;
            size_t actual_payload = (remaining < payload_size) ? remaining : payload_size;

            memcpy(packet + sizeof(int) * 4, frame_buffer + i * MAX_FRAME_SIZE, actual_payload);

            int header[4] = {
