            };

            memcpy(packet, header, sizeof(header));

            if (send_udp_packet(sockfd, packet, sizeof(header) + actual_payload) < 0) {
                fprintf(stderr, "Error sending UDP packet\n");
                break;
            }
        }

        frame_index++;
    }

    close(sockfd);
    cleanup_camera(fd, buffers);

    printf("Program finished.\n");
    return 0;
}

