    if (xioctl(*fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Error starting stream");
        goto fail_buffers;
    }

    return 0;

fail_buffers:
    for (unsigned int j = 0; j < i; j++) {
        if ((*buffers)[j].start != NULL && (*buffers)[j].start != MAP_FAILED) {
            munmap((*buffers)[j].start, (*buffers)[j].length);
