/*
 * Camera Pan-Tilt Mount Control (Raspberry Pi)
 *
 * Wiring (BCM numbering):
 *   GPIO4  -> Pan servo signal
 *   GPIO5  -> Tilt servo signal
 *   GPIO6  -> Tilt-up button  (active-low, internal pull-up)
 *   GPIO7  -> Tilt-down button (active-low, internal pull-up)
 *   GPIO8  -> Pan-left button  (active-low, internal pull-up)
 *   GPIO9  -> Pan-right button (active-low, internal pull-up)
 *
 * PWM: 50 Hz (20 ms period), pulse 1-2 ms -> duty 50-100 out of 1000.
 * Initial position: pan=75, tilt=75.  Adjustments: +/-5 per press.
 * Range: 25-125.  SIGINT releases resources cleanly.
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PAN_PIN        4
#define TILT_PIN       5
#define TILT_UP_PIN    6
#define TILT_DOWN_PIN  7
#define PAN_LEFT_PIN   8
#define PAN_RIGHT_PIN  9

#define PWM_FREQ       50          /* Hz  */
#define PWM_RANGE      1000        /* duty range 0-1000 */
#define MIN_DUTY       50          /* 1 ms pulse  */
#define MAX_DUTY       1000        /* 2 ms pulse  */
#define MID_DUTY       75          /* 1.5 ms mid */
#define STEP           5
#define POLL_US        50000       /* 50 ms */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int clamp(int v, int lo, int hi)
{
    if (v < lo) return lo;
    if (v > hi) return hi;
    return v;
}

static int set_servo(int pin, int duty)
{
    if (gpioServo(pin, duty) < 0) {
        fprintf(stderr, "gpioServo(pin=%d, duty=%d) failed\n", pin, duty);
        return -1;
    }
    return 0;
}

int main(void)
{
    int pan_pos  = MID_DUTY;
    int tilt_pos = MID_DUTY;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Install SIGINT handler for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure button pins as inputs with internal pull-ups */
    int btn_pins[] = { TILT_UP_PIN, TILT_DOWN_PIN, PAN_LEFT_PIN, PAN_RIGHT_PIN };
    for (size_t i = 0; i < sizeof(btn_pins) / sizeof(btn_pins[0]); ++i) {
        if (gpioSetMode(btn_pins[i], PI_INPUT) < 0) {
            fprintf(stderr, "gpioSetMode failed for pin %d\n", btn_pins[i]);
            goto fail;
        }
        if (gpioSetPullUpDown(btn_pins[i], PI_PUD_UP) < 0) {
            fprintf(stderr, "gpioSetPullUpDown failed for pin %d\n", btn_pins[i]);
            goto fail;
        }
    }

    /* Configure servo pins as hardware PWM-capable outputs */
    int servo_pins[] = { PAN_PIN, TILT_PIN };
    for (size_t i = 0; i < sizeof(servo_pins) / sizeof(servo_pins[0]); ++i) {
        if (gpioSetMode(servo_pins[i], PI_OUTPUT) < 0) {
            fprintf(stderr, "gpioSetMode failed for pin %d\n", servo_pins[i]);
            goto fail;
        }
        if (gpioSetPWMfrequency(servo_pins[i], PWM_FREQ) < 0) {
            fprintf(stderr, "gpioSetPWMfrequency failed for pin %d\n", servo_pins[i]);
            goto fail;
        }
        if (gpioSetPWMrange(servo_pins[i], PWM_RANGE) < 0) {
            fprintf(stderr, "gpioSetPWMrange failed for pin %d\n", servo_pins[i]);
            goto fail;
        }
    }

    /* Initialize servos to mid-position */
    if (set_servo(PAN_PIN, pan_pos) < 0)  goto fail;
    if (set_servo(TILT_PIN, tilt_pos) < 0) goto fail;

    printf("Pan-Tilt Mount Control (pigpio)\n");
    printf("Pan:  GPIO%d  Tilt: GPIO%d\n", PAN_PIN, TILT_PIN);
    printf("Tilt-up:   GPIO%d  Tilt-down: GPIO%d\n", TILT_UP_PIN, TILT_DOWN_PIN);
    printf("Pan-left:  GPIO%d  Pan-right: GPIO%d\n", PAN_LEFT_PIN, PAN_RIGHT_PIN);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        int tilt_up   = gpioRead(TILT_UP_PIN);
        int tilt_down = gpioRead(TILT_DOWN_PIN);
        int pan_left  = gpioRead(PAN_LEFT_PIN);
        int pan_right = gpioRead(PAN_RIGHT_PIN);

        if (tilt_up == 0) {
            tilt_pos += STEP;
            tilt_pos = clamp(tilt_pos, MIN_DUTY, MAX_DUTY);
            if (set_servo(TILT_PIN, tilt_pos) < 0) break;
        }
        if (tilt_down == 0) {
            tilt_pos -= STEP;
            tilt_pos = clamp(tilt_pos, MIN_DUTY, MAX_DUTY);
            if (set_servo(TILT_PIN, tilt_pos) < 0) break;
        }
        if (pan_left == 0) {
            pan_pos -= STEP;
            pan_pos = clamp(pan_pos, MIN_DUTY, MAX_DUTY);
            if (set_servo(PAN_PIN, pan_pos) < 0) break;
        }
        if (pan_right == 0) {
            pan_pos += STEP;
            pan_pos = clamp(pan_pos, MIN_DUTY, MAX_DUTY);
            if (set_servo(PAN_PIN, pan_pos) < 0) break;
        }

        gpioDelay(POLL_US);
    }

    /* Clean shutdown: stop PWM and release pigpio */
    gpioServo(PAN_PIN, 0);
    gpioServo(TILT_PIN, 0);
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;

fail:
    gpioTerminate();
    return EXIT_FAILURE;
}

