            fprintf(stderr, "gpioSetPWMfrequency failed for pin %d\n", servo_pins[i]);
            goto fail;
        }
        if (gpioSetPWMrange(servo_pins[i], PWM_RANGE) < 0) {
            fprintf(stderr, "gpioSetPWMrange failed for pin %d\n", servo_pins[i]);
            goto fail;
        }
    }

    /* Initialize servos to mid-position */
    if (set_servo(PAN_PIN, pan_pos) < 0)  goto fail;
    if (set_servo(TILT_PIN, tilt_pos) < 0) goto fail;

    printf("Pan-Tilt Mount Control (pigpio)\n");
    printf("Pan:  GPIO%d  Tilt: GPIO%d\n", PAN_PIN, TILT_PIN);
    printf("Tilt-up:   GPIO%d  Tilt-down: GPIO%d\n", TILT_UP_PIN, TILT_DOWN_PIN);
    printf("Pan-left:  GPIO%d  Pan-right: GPIO%d\n", PAN_LEFT_PIN, PAN_RIGHT_PIN);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        int tilt_up   = gpioRead(TILT_UP_PIN);
        int tilt_down = gpioRead(TILT_DOWN_PIN);
        int pan_left  = gpioRead(PAN_LEFT_PIN);
        int pan_right = gpioRead(PAN_RIGHT_PIN);

        if (tilt_up == 0) {
            tilt_pos += STEP;
            tilt_pos = clamp(tilt_pos, MIN_DUTY, MAX_DUTY);
            if (set_servo(TILT_PIN, tilt_pos) < 0) break;
        }
        if (tilt_down == 0) {
            tilt_pos -= STEP;
            tilt_pos = clamp(tilt_pos, MIN_DUTY, MAX_DUTY);
            if (set_servo(TILT_PIN, tilt_pos) < 0) break;
        }
        if (pan_left == 0) {
            pan_pos -= STEP;
            pan_pos = clamp(pan_pos, MIN_DUTY, MAX_DUTY);
            if (set_servo(PAN_PIN, pan_pos) < 0) break;
        }
        if (pan_right == 0) {
            pan_pos += STEP;
            pan_pos = clamp(pan_pos, MIN_DUTY, MAX_DUTY);
            if (set_servo(PAN_PIN, pan_pos) < 0) break;
        }

        gpioDelay(POLL_US);
    }

    /* Clean shutdown: stop PWM and release pigpio */
    gpioServo(PAN_PIN, 0);
    gpioServo(TILT_PIN, 0);
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;

fail:
    gpioTerminate();
    return EXIT_FAILURE;
}

