#include <time.h>
#include <errno.h>
#include <signal.h>

#define CLEAR(x) memset(&(x), 0, sizeof(x))

typedef struct {
    void *start;
    size_t length;
} buffer;

static volatile sig_atomic_t stop_flag = 0;

static void signal_handler(int signum) {
    (void)signum;
    stop_flag = 1;
}

static int xioctl(int fh, int request, void *arg) {
    int r;
    do {
        r = ioctl(fh, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static int process_image(unsigned char *yuyv_data, int width, int height, unsigned char *rgb_data) {
    for (int i = 0; i < height; i++) {
        for (int j = 0; j < width; j++) {
            int y_index = (i * width + j) * 2;
            int u_index = (i * width + j) * 2 + 1;
            int v_index = (i * width + j) * 2 + 1;

            int y = yuyv_data[y_index];
            int u = yuyv_data[u_index] - 128;
            int v = yuyv_data[v_index] - 128;

            int r = y + (1402 * v) / 1000;
            int g = y - (344 * u) / 1000 - (714 * v) / 1000;
            int b = y + (1772 * u) / 1000;

            if (r < 0) r = 0; if (r > 255) r = 255;
            if (g < 0) g = 0; if (g > 255) g = 255;
            if (b < 0) b = 0; if (b > 255) b = 255;

            int rgb_index = (i * width + j) * 3;
            rgb_data[rgb_index] = r;
            rgb_data[rgb_index + 1] = g;
            rgb_data[rgb_index + 2] = b;
        }
    }
    return 0;
}

static int encode_jpeg(unsigned char *rgb_data, int width, int height, const char *filename) {
    unsigned char *jpeg_data = NULL;
    unsigned long jpeg_size = 0;
    int quality = 75;

    extern int jpeg_create_compress(void);
    extern void jpeg_destroy_compress(void);
    extern void jpeg_set_defaults(void);
    extern void jpeg_set_quality(void *cinfo, int quality, int force_baseline);
    extern void jpeg_start_compress(void *cinfo, int write_all);
    extern JSAMPROW *jpeg_write_scanlines(void *cinfo, JSAMPROW *buffer, int rows);
    extern void jpeg_finish_compress(void *cinfo);
    extern void jpeg_stdio_dest(void *cinfo, FILE *outfile);
    extern int jpeg_write_header(void *cinfo, int need_sof0);

    void *cinfo = jpeg_create_compress();
    if (!cinfo) {
        fprintf(stderr, "Error: jpeg_create_compress failed\n");
        return -1;
    }

    FILE *outfile = fopen(filename, "wb");
    if (!outfile) {
        fprintf(stderr, "Error: Cannot open file %s for writing: %s\n", filename, strerror(errno));
        jpeg_destroy_compress(cinfo);
        return -1;
    }

    jpeg_stdio_dest(cinfo, outfile);
    jpeg_set_defaults(cinfo);
    jpeg_set_quality(cinfo, quality, TRUE);
    jpeg_start_compress(cinfo, TRUE);

    int row_stride = width * 3;
    JSAMPROW row_pointer[1];
    while (cinfo->next_scanline < cinfo->image_height) {
        row_pointer[0] = &rgb_data[cinfo->next_scanline * row_stride];
        jpeg_write_scanlines(cinfo, row_pointer, 1);
    }

    jpeg_finish_compress(cinfo);
    fclose(outfile);
    jpeg_destroy_compress(cinfo);

    return 0;
}

int main(void) {
    int fd = -1;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    buffer *buffers = NULL;
    unsigned int n_buffers = 0;
    unsigned char *yuyv_data = NULL;
    unsigned char *rgb_data = NULL;
    char filename[64];
    time_t rawtime;
    struct tm *timeinfo;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error: sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    fd = open("/dev/video0", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error: Cannot open /dev/video0: %s\n", strerror(errno));
        return 1;
    }

    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "Error: VIDIOC_QUERYCAP failed: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Error: /dev/video0 does not support video capture\n");
        close(fd);
        return 1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Error: /dev/video0 does not support streaming\n");
        close(fd);
        return 1;
    }

    CLEAR(fmt);
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640;
    fmt.fmt.pix.height = 480;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        fprintf(stderr, "Error: VIDIOC_S_FMT failed: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    CLEAR(req);
    req.count = 4;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        fprintf(stderr, "Error: VIDIOC_REQBUFS failed: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    if (req.count < 2) {
        fprintf(stderr, "Error: Insufficient buffer memory\n");
        close(fd);
        return 1;
    }

    buffers = calloc(req.count, sizeof(*buffers));
    if (!buffers) {
        fprintf(stderr, "Error: Out of memory allocating buffer structures\n");
        close(fd);
        return 1;
    }

    for (n_buffers = 0; n_buffers < req.count; n_buffers++) {
        CLEAR(buf);
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = n_buffers;

        if (xioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
            fprintf(stderr, "Error: VIDIOC_QUERYBUF failed for buffer %u: %s\n", n_buffers, strerror(errno));
            goto cleanup;
        }

        buffers[n_buffers].length = buf.length;
        buffers[n_buffers].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
        if (buffers[n_buffers].start == MAP_FAILED) {
            fprintf(stderr, "Error: mmap failed for buffer %u: %s\n", n_buffers, strerror(errno));
            buffers[n_buffers].start = NULL;
            goto cleanup;
        }
    }

    for (unsigned int i = 0; i < n_buffers; i++) {
        CLEAR(buf);
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            fprintf(stderr, "Error: VIDIOC_QBUF failed for buffer %u: %s\n", i, strerror(errno));
            goto cleanup;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        fprintf(stderr, "Error: VIDIOC_STREAMON failed: %s\n", strerror(errno));
        goto cleanup;
    }

    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    tv.tv_sec = 2;
    tv.tv_usec = 0;

    r = select(fd + 1, &fds, NULL, NULL, &tv);

    if (r == -1) {
        if (errno == EINTR) {
            fprintf(stderr, "Interrupted by signal\n");
            goto cleanup;
        }
        fprintf(stderr, "Error: select failed: %s\n", strerror(errno));
        goto cleanup;
    } else if (r == 0) {
        fprintf(stderr, "Error: select timeout\n");
        goto cleanup;
    }

    CLEAR(buf);
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        fprintf(stderr, "Error: VIDIOC_DQBUF failed: %s\n", strerror(errno));
        goto cleanup;
    }

    if (buf.index >= n_buffers) {
        fprintf(stderr, "Error: Invalid buffer index %u\n", buf.index);
        goto cleanup;
    }

    yuyv_data = (unsigned char *)buffers[buf.index].start;
    if (!yuyv_data) {
        fprintf(stderr, "Error: yuyv_data is NULL\n");
        goto cleanup;
    }

    rgb_data = malloc(640 * 480 * 3);
    if (!rgb_data) {
        fprintf(stderr, "Error: Out of memory allocating RGB data\n");
        goto cleanup;
    }

    if (process_image(yuyv_data, 640, 480, rgb_data) < 0) {
        fprintf(stderr, "Error: Image processing failed\n");
        goto cleanup;
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(filename, sizeof(filename), "capture_%Y%m%d_%H%M%S.jpg", timeinfo);

    if (encode_jpeg(rgb_data, 640, 480, filename) < 0) {
        fprintf(stderr, "Error: JPEG encoding failed\n");
        goto cleanup;
    }

    printf("Image saved as %s\n", filename);

cleanup:
    if (rgb_data) free(rgb_data);
    if (yuyv_data) {
        CLEAR(buf);
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = buf.index;
        xioctl(fd, VIDIOC_QBUF, &buf);
    }
    if (fd >= 0) {
        enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        xioctl(fd, VIDIOC_STREAMOFF, &type);
        for (unsigned int i = 0; i < n_buffers; i++) {
            if (buffers[i].start && buffers[i].start != MAP_FAILED) {
                munmap(buffers[i].start, buffers[i].length);
            }
        }
        close(fd);
    }
    if (buffers) free(buffers);
    return 0;
}

