/*
 * csi_info.c - Report CSI camera capabilities on a Raspberry Pi.
 *
 * Build:  gcc -O2 -Wall -Wextra -o csi_info csi_info.c
 * Run:    ./csi_info
 *
 * Reports supported resolutions, frame rates, and autofocus capability
 * for the first V4L2 device found at /dev/video0.
 */

#include <errno.h>
#include <fcntl.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

#include <linux/videodev2.h>
#include <sys/ioctl.h>

#define DEVICE_NAME "/dev/video0"

static void print_error(const char *msg)
{
    fprintf(stderr, "Error: %s (errno %d: %s)\n", msg, errno, strerror(errno));
}

/*
 * Enumerate all frame sizes supported by the device.
 * Returns 0 on success, -1 on error.
 */
static int enumerate_frame_sizes(int fd)
{
    struct v4l2_frmsizeenum fs;
    memset(&fs, 0, sizeof(fs));
    fs.index = 0;

    printf("Supported resolutions:\n");

    while (1) {
        if (ioctl(fd, VIDIOC_ENUM_FRAMESIZES, &fs) < 0) {
            if (errno == EINVAL) {
                break; /* No more frame sizes */
            }
            print_error("VIDIOC_ENUM_FRAMESIZES failed");
            return -1;
        }

        switch (fs.type) {
        case V4L2_FRMSIZE_TYPE_DISCRETE:
            printf("  %ux%u\n", fs.discrete.width, fs.discrete.height);
            break;
        case V4L2_FRMSIZE_TYPE_STEPWISE:
            printf("  %ux%u - %ux%u (step %ux%u)\n",
                   fs.stepwise.min_width, fs.stepwise.min_height,
                   fs.stepwise.max_width, fs.stepwise.max_height,
                   fs.stepwise.step_width, fs.stepwise.step_height);
            break;
        case V4L2_FRMSIZE_TYPE_CONTINUOUS:
            printf("  Continuous: %ux%u - %ux%u\n",
                   fs.stepwise.min_width, fs.stepwise.min_height,
                   fs.stepwise.max_width, fs.stepwise.max_height);
            break;
        default:
            printf("  (unknown frame size type %u)\n", fs.type);
            break;
        }

        fs.index++;
    }

    return 0;
}

/*
 * Enumerate all frame intervals (frame rates) for a given frame size.
 * Returns 0 on success, -1 on error.
 */
static int enumerate_frame_intervals(int fd, unsigned int width, unsigned int height)
{
    struct v4l2_frmivalenum fi;
    memset(&fi, 0, sizeof(fi));
    fi.index = 0;
    fi.width = width;
    fi.height = height;

    while (1) {
        if (ioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, &fi) < 0) {
            if (errno == EINVAL) {
                break; /* No more frame intervals for this size */
            }
            print_error("VIDIOC_ENUM_FRAMEINTERVALS failed");
            return -1;
        }

        switch (fi.type) {
        case V4L2_FRMIVAL_TYPE_DISCRETE:
            printf("    %u/%u fps\n", fi.discrete.numerator, fi.discrete.denominator);
            break;
        case V4L2_FRMIVAL_TYPE_STEPWISE:
            printf("    %u/%u - %u/%u fps (step %u/%u)\n",
                   fi.stepwise.min.numerator, fi.stepwise.min.denominator,
                   fi.stepwise.max.numerator, fi.stepwise.max.denominator,
                   fi.stepwise.step.numerator, fi.stepwise.step.denominator);
            break;
        case V4L2_FRMIVAL_TYPE_CONTINUOUS:
            printf("    Continuous: %u/%u - %u/%u fps\n",
                   fi.stepwise.min.numerator, fi.stepwise.min.denominator,
                   fi.stepwise.max.numerator, fi.stepwise.max.denominator);
            break;
        default:
            printf("    (unknown frame interval type %u)\n", fi.type);
            break;
        }

        fi.index++;
    }

    return 0;
}

/*
 * Check whether autofocus is supported.
 * Returns 1 if autofocus is supported, 0 if not, -1 on error.
 */
static int check_autofocus(int fd)
{
    struct v4l2_queryctrl qc;
    memset(&qc, 0, sizeof(qc));
    qc.id = V4L2_CID_FOCUS_AUTO;

    if (ioctl(fd, VIDIOC_QUERYCTRL, &qc) < 0) {
        if (errno == EINVAL) {
            return 0; /* Focus control not supported */
        }
        print_error("VIDIOC_QUERYCTRL (focus) failed");
        return -1;
    }

    if (qc.flags & V4L2_CTRL_FLAG_DISABLED) {
        return 0;
    }

    printf("Autofocus: %s\n", qc.default_value ? "supported" : "not supported");
    return 1;
}

int main(void)
{
    int fd = open(DEVICE_NAME, O_RDWR);
    if (fd < 0) {
        print_error("Failed to open " DEVICE_NAME);
        return EXIT_FAILURE;
    }

    printf("CSI Camera Information for %s\n", DEVICE_NAME);
    printf("----------------------------------------\n");

    struct v4l2_capability cap;
    memset(&cap, 0, sizeof(cap));

    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        print_error("VIDIOC_QUERYCAP failed");
        close(fd);
        return EXIT_FAILURE;
    }

    printf("Driver : %s\n", cap.driver);
    printf("Card   : %s\n", cap.card);
    printf("Bus    : %s\n", cap.bus_info);
    printf("Version: %u.%u.%u\n",
           (cap.version >> 16) & 0xFF,
           (cap.version >> 8) & 0xFF,
           cap.version & 0xFF);
    printf("Cap    : %s%s%s%s%s%s%s\n",
           cap.capabilities & V4L2_CAP_VIDEO_CAPTURE ? " video-capture" : "",
           cap.capabilities & V4L2_CAP_VIDEO_OUTPUT ? " video-output" : "",
           cap.capabilities & V4L2_CAP_VIDEO_OVERLAY ? " video-overlay" : "",
           cap.capabilities & V4L2_CAP_VBI_CAPTURE ? " vbi-capture" : "",
           cap.capabilities & V4L2_CAP_VBI_OUTPUT ? " vbi-output" : "",
           cap.capabilities & V4L2_CAP_SLICED_VBI_CAPTURE ? " sliced-vbi-capture" : "",
           cap.capabilities & V4L2_CAP_SLICED_VBI_OUTPUT ? " sliced-vbi-output" : "",
           cap.capabilities & V4L2_CAP_RDS_CAPTURE ? " rds-capture" : "");

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Warning: device does not advertise video-capture capability.\n");
    }

    if (enumerate_frame_sizes(fd) < 0) {
        close(fd);
        return EXIT_FAILURE;
    }

    printf("\nFrame rates:\n");
    struct v4l2_frmsizeenum fs;
    memset(&fs, 0, sizeof(fs));
    fs.index = 0;

    while (1) {
        if (ioctl(fd, VIDIOC_ENUM_FRAMESIZES, &fs) < 0) {
            if (errno == EINVAL) {
                break; /* No more frame sizes */
            }
            print_error("VIDIOC_ENUM_FRAMESIZES failed");
            close(fd);
            return EXIT_FAILURE;
        }

        if (fs.type == V4L2_FRMSIZE_TYPE_DISCRETE) {
            printf("  %ux%u: ", fs.discrete.width, fs.discrete.height);
            if (enumerate_frame_intervals(fd, fs.discrete.width, fs.discrete.height) < 0) {
                close(fd);
                return EXIT_FAILURE;
            }
        }

        fs.index++;
    }

    printf("\nAutofocus: ");
    int autofocus = check_autofocus(fd);
    if (autofocus < 0) {
        close(fd);
        return EXIT_FAILURE;
    }

    printf("\n");
    close(fd);
    return EXIT_SUCCESS;
}

