#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PAN_SERVO_PIN   4
#define TILT_SERVO_PIN  5
#define UP_BUTTON_PIN   6
#define DOWN_BUTTON_PIN 7
#define LEFT_BUTTON_PIN 8
#define RIGHT_BUTTON_PIN 9

#define MIN_PULSE_WIDTH  1000
#define MAX_PULSE_WIDTH  2000
#define CENTER_PULSE_WIDTH 1500
#define STEP_US         10
#define LOOP_DELAY_US   50000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int set_servo_pulse(int pin, int pulse_width)
{
    if (pulse_width < MIN_PULSE_WIDTH || pulse_width > MAX_PULSE_WIDTH) {
        fprintf(stderr, "Error: pulse width %d out of range [%d, %d]\n",
                pulse_width, MIN_PULSE_WIDTH, MAX_PULSE_WIDTH);
        return -1;
    }
    if (gpioServo(pin, pulse_width) < 0) {
        fprintf(stderr, "Error: gpioServo failed on pin %d\n", pin);
        return -1;
    }
    return 0;
}

int main(void)
{
    int pan_pulse  = CENTER_PULSE_WIDTH;
    int tilt_pulse = CENTER_PULSE_WIDTH;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for pan pin %d\n", PAN_SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for tilt pin %d\n", TILT_SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(UP_BUTTON_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for UP button pin %d\n", UP_BUTTON_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(DOWN_BUTTON_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for DOWN button pin %d\n", DOWN_BUTTON_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(LEFT_BUTTON_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for LEFT button pin %d\n", LEFT_BUTTON_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(RIGHT_BUTTON_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for RIGHT button pin %d\n", RIGHT_BUTTON_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(UP_BUTTON_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for UP button pin %d\n", UP_BUTTON_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(DOWN_BUTTON_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for DOWN button pin %d\n", DOWN_BUTTON_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(LEFT_BUTTON_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for LEFT button pin %d\n", LEFT_BUTTON_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(RIGHT_BUTTON_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for RIGHT button pin %d\n", RIGHT_BUTTON_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (set_servo_pulse(PAN_SERVO_PIN, pan_pulse) < 0 ||
        set_servo_pulse(TILT_SERVO_PIN, tilt_pulse) < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Pan-tilt mount control started.\n");
    printf("  Pan  servo: GPIO%d\n", PAN_SERVO_PIN);
    printf("  Tilt servo: GPIO%d\n", TILT_SERVO_PIN);
    printf("  UP    button: GPIO%d\n", UP_BUTTON_PIN);
    printf("  DOWN  button: GPIO%d\n", DOWN_BUTTON_PIN);
    printf("  LEFT  button: GPIO%d\n", LEFT_BUTTON_PIN);
    printf("  RIGHT button: GPIO%d\n", RIGHT_BUTTON_PIN);
    printf("  Center position: pan=%d us, tilt=%d us\n",
           CENTER_PULSE_WIDTH, CENTER_PULSE_WIDTH);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        int up     = gpioRead(UP_BUTTON_PIN);
        int down   = gpioRead(DOWN_BUTTON_PIN);
        int left   = gpioRead(LEFT_BUTTON_PIN);
        int right  = gpioRead(RIGHT_BUTTON_PIN);

        if (up == 0) {
            tilt_pulse += STEP_US;
            if (tilt_pulse > MAX_PULSE_WIDTH) tilt_pulse = MAX_PULSE_WIDTH;
            if (set_servo_pulse(TILT_SERVO_PIN, tilt_pulse) < 0) break;
        }
        if (down == 0) {
            tilt_pulse -= STEP_US;
            if (tilt_pulse < MIN_PULSE_WIDTH) tilt_pulse = MIN_PULSE_WIDTH;
            if (set_servo_pulse(TILT_SERVO_PIN, tilt_pulse) < 0) break;
        }
        if (left == 0) {
            pan_pulse -= STEP_US;
            if (pan_pulse < MIN_PULSE_WIDTH) pan_pulse = MIN_PULSE_WIDTH;
            if (set_servo_pulse(PAN_SERVO_PIN, pan_pulse) < 0) break;
        }
        if (right == 0) {
            pan_pulse += STEP_US;
            if (pan_pulse > MAX_PULSE_WIDTH) pan_pulse = MAX_PULSE_WIDTH;
            if (set_servo_pulse(PAN_SERVO_PIN, pan_pulse) < 0) break;
        }

        gpioDelay(LOOP_DELAY_US);
    }

    gpioServo(PAN_SERVO_PIN, 0);
    gpioServo(TILT_SERVO_PIN, 0);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

