#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/time.h>
#include <errno.h>
#include <pigpio.h>

#define PIR_GPIO 17
#define DEBOUNCE_TIME 2
#define POLL_INTERVAL 0.1
#define SNAPSHOT_QUALITY 85
#define MOTION_CAPTURES_DIR "motion_captures"
#define MAX_FILENAME_LENGTH 256
#define MAX_JSON_LENGTH 512

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int ensure_directory(const char *path) {
    struct stat st;
    if (stat(path, &st) == 0) {
        if (S_ISDIR(st.st_mode)) return 0;
        fprintf(stderr, "Error: '%s' exists but is not a directory.\n", path);
        return -1;
    }
    if (mkdir(path, 0755) != 0 && errno != EEXIST) {
        fprintf(stderr, "Error creating directory '%s': %s\n", path, strerror(errno));
        return -1;
    }
    return 0;
}

static int capture_image(const char *filename) {
    char command[512];
    snprintf(command, sizeof(command), "raspistill -q %d -o %s", SNAPSHOT_QUALITY, filename);
    int status = system(command);
    if (status == -1) {
        fprintf(stderr, "Error executing raspistill: %s\n", strerror(errno));
        return -1;
    }
    if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
        fprintf(stderr, "raspistill failed with status %d\n", status);
        return -1;
    }
    return 0;
}

static int create_json_payload(const char *filename, const char *timestamp, const char *motion_status, int gpio_pin, char *json_string, size_t json_string_size) {
    int ret = snprintf(json_string, json_string_size,
                       "{\"filename\": \"%s\", \"timestamp\": \"%s\", \"motion\": \"%s\", \"gpio_pin\": %d}",
                       filename, timestamp, motion_status, gpio_pin);
    if (ret < 0 || (size_t)ret >= json_string_size) {
        fprintf(stderr, "Error: JSON payload truncated.\n");
        return -1;
    }
    return 0;
}

static void log_event(const char *message) {
    FILE *fp = fopen("motion_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <IP> <port>\n", argv[0]);
        return 1;
    }

    const char *ip_address = argv[1];
    const char *port = argv[2];

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(PIR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", PIR_GPIO);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(PIR_GPIO, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down on GPIO %d\n", PIR_GPIO);
        gpioTerminate();
        return 1;
    }

    if (ensure_directory(MOTION_CAPTURES_DIR) != 0) {
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to set up signal handlers: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    printf("Motion detection started on GPIO %d. Press Ctrl+C to exit.\n", PIR_GPIO);

    while (running) {
        if (gpioRead(PIR_GPIO) == 1) {
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[32];
            char filename[MAX_FILENAME_LENGTH];
            char json_string[MAX_JSON_LENGTH];
            int motion_detected = 0;

            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

            snprintf(filename, sizeof(filename), "%s/%s.jpg", MOTION_CAPTURES_DIR, timestamp);

            if (capture_image(filename) == 0) {
                motion_detected = 1;
                printf("Motion detected! Capturing image: %s\n", filename);
                log_event("Motion detected");
            } else {
                fprintf(stderr, "Failed to capture image.\n");
                log_event("Failed to capture image");
            }

            if (motion_detected) {
                if (create_json_payload(filename, timestamp, "true", PIR_GPIO, json_string, sizeof(json_string)) == 0) {
                    printf("JSON Payload: %s\n", json_string);
                } else {
                    fprintf(stderr, "Failed to create JSON payload.\n");
                }
            }

            time_t start_time = time(NULL);
            while (running && (time(NULL) - start_time) < DEBOUNCE_TIME) {
                if (gpioRead(PIR_GPIO) == 0) {
                    break;
                }
                time_sleep(POLL_INTERVAL);
            }
        }
        time_sleep(POLL_INTERVAL);
    }

    printf("\nShutting down...\n");
    gpioTerminate();
    printf("Cleanup complete.\n");
    return 0;
}

