#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME      "gpiochip0"
#define PIR_PIN             17
#define IMAGE_DIR           "/home/pi/images"
#define LOG_FILE            "/home/pi/motion_capture.log"
#define DEBOUNCE_MS         50
#define POLL_TIMEOUT_MS     1000
#define CAPTURE_TIMEOUT_MS  2000
#define MAX_FILENAME_LEN    128
#define MAX_CMD_LEN         512

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void log_message(const char *msg)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(log)");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    } else {
        fprintf(fp, "[unknown time] %s\n", msg);
    }
    fclose(fp);
}

static int capture_image(const char *filename)
{
    char command[MAX_CMD_LEN];
    snprintf(command, sizeof(command),
             "raspistill -o %s -w 640 -h 480 -q 85 --timeout %d --nopreview",
             filename, CAPTURE_TIMEOUT_MS);

    int status = system(command);
    if (status == -1) {
        log_message("system() failed to launch raspistill");
        return -1;
    }
    if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
        char buf[256];
        snprintf(buf, sizeof(buf),
                 "raspistill exited with status %d", WEXITSTATUS(status));
        log_message(buf);
        return -1;
    }
    return 0;
}

static int generate_filename(char *buf, size_t buflen)
{
    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm))
        return -1;
    if (strftime(buf, buflen, "%Y%m%d_%H%M%S_%3N.jpg", &tm) == 0)
        return -1;
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        char buf[256];
        snprintf(buf, sizeof(buf), "gpiod_chip_open_by_name(%s) failed: %s",
                 GPIO_CHIP_NAME, strerror(errno));
        log_message(buf);
        return EXIT_FAILURE;
    }

    struct gpiod_line *pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        char buf[256];
        snprintf(buf, sizeof(buf), "gpiod_chip_get_line(%d) failed: %s",
                 PIR_PIN, strerror(errno));
        log_message(buf);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_falling_edge_events(pir_line, "pir_monitor") < 0) {
        char buf[256];
        snprintf(buf, sizeof(buf), "gpiod_line_request_falling_edge_events failed: %s",
                 strerror(errno));
        log_message(buf);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    log_message("PIR monitor started on GPIO17 (falling edge).");

    while (g_running) {
        int ret = gpiod_line_event_wait(pir_line, NULL);
        if (ret < 0) {
            if (errno == EINTR)
                continue;
            char buf[256];
            snprintf(buf, sizeof(buf), "gpiod_line_event_wait failed: %s",
                     strerror(errno));
            log_message(buf);
            break;
        }
        if (ret == 0)
            continue;

        struct gpiod_line_event event;
        if (gpiod_line_event_read(pir_line, &event) < 0) {
            char buf[256];
            snprintf(buf, sizeof(buf), "gpiod_line_event_read failed: %s",
                     strerror(errno));
            log_message(buf);
            continue;
        }

        if (event.event_type != GPIOD_LINE_EVENT_FALLING_EDGE)
            continue;

        char filename[MAX_FILENAME_LEN];
        if (generate_filename(filename, sizeof(filename)) != 0) {
            log_message("Failed to generate filename.");
            continue;
        }

        char log_buf[512];
        snprintf(log_buf, sizeof(log_buf),
                 "Motion detected on GPIO17. Capturing %s", filename);
        log_message(log_buf);

        if (capture_image(filename) == 0) {
            snprintf(log_buf, sizeof(log_buf),
                     "Image saved: %s", filename);
            log_message(log_buf);
        } else {
            snprintf(log_buf, sizeof(log_buf),
                     "Image capture failed for %s", filename);
            log_message(log_buf);
        }

        usleep(DEBOUNCE_MS * 1000);
    }

    log_message("PIR monitor shutting down.");
    gpiod_line_release(pir_line);
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

