#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <linux/videodev2.h>

#define WIDTH  640
#define HEIGHT 480
#define CROP_WIDTH  200
#define CROP_HEIGHT 150
#define FILENAME "cropped.yuv"
#define NUM_BUFFERS 1

static volatile sig_atomic_t stop = 0;

static void signal_handler(int sig) {
    (void)sig;
    stop = 1;
}

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static int process_frame(const unsigned char *src, unsigned char *dst,
                         int width, int height,
                         int crop_width, int crop_height,
                         int crop_x, int crop_y) {
    int src_stride = width * 2;
    int dst_stride = crop_width * 2;
    int rows = height;
    int cols = width;

    for (int row = 0; row < rows; row++) {
        for (int col = 0; col < cols; col++) {
            int src_idx = (row * src_stride) + (col * 2);
            int dst_idx = ((row - crop_y) * dst_stride) + ((col - crop_x) * 2);
            if (row >= crop_y && row < crop_y + crop_height &&
                col >= crop_x && col < crop_x + crop_width) {
                dst[dst_idx]     = src[src_idx];     /* Y0 */
                dst[dst_idx + 1] = src[src_idx + 1]; /* U */
                dst[dst_idx + 2] = src[src_idx + 2]; /* Y1 */
                dst[dst_idx + 3] = src[src_idx + 3]; /* V */
            }
        }
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    int fd = open("/dev/video0", O_RDWR);
    if (fd < 0) {
        perror("open /dev/video0");
        return EXIT_FAILURE;
    }

    struct v4l2_capability cap;
    memset(&cap, 0, sizeof(cap));
    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("VIDIOC_QUERYCAP");
        close(fd);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        close(fd);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming I/O\n");
        close(fd);
        return EXIT_FAILURE;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("VIDIOC_S_FMT");
        close(fd);
        return EXIT_FAILURE;
    }

    if (fmt.fmt.pix.width != WIDTH || fmt.fmt.pix.height != HEIGHT ||
        fmt.fmt.pix.pixelformat != V4L2_PIX_FMT_YUYV) {
        fprintf(stderr, "Camera did not accept requested format\n");
        close(fd);
        return EXIT_FAILURE;
    }

    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("VIDIOC_REQBUFS");
        close(fd);
        return EXIT_FAILURE;
    }

    if (req.count < 1) {
        fprintf(stderr, "Insufficient buffer memory\n");
        close(fd);
        return EXIT_FAILURE;
    }

    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (xioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        perror("VIDIOC_QUERYBUF");
        close(fd);
        return EXIT_FAILURE;
    }

    void *buffer_start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (buffer_start == MAP_FAILED) {
        perror("mmap");
        close(fd);
        return EXIT_FAILURE;
    }

    if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("VIDIOC_QBUF");
        munmap(buffer_start, buf.length);
        close(fd);
        return EXIT_FAILURE;
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("VIDIOC_STREAMON");
        munmap(buffer_start, buf.length);
        close(fd);
        return EXIT_FAILURE;
    }

    fd_set fds;
    struct timeval tv;
    int r;

    for (;;) {
        FD_ZERO(&fds);
        FD_SET(fd, &fds);

        tv.tv_sec = 2;
        tv.tv_usec = 0;

        r = select(fd + 1, &fds, NULL, NULL, &tv);

        if (r == -1) {
            if (errno == EINTR) {
                if (stop) {
                    break;
                }
                continue;
            }
            perror("select");
            break;
        }

        if (r == 0) {
            fprintf(stderr, "select timeout\n");
            break;
        }

        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;

        if (xioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
            perror("VIDIOC_DQBUF");
            break;
        }

        if (buf.bytesused < (WIDTH * HEIGHT * 2)) {
            fprintf(stderr, "Incomplete frame (%u bytes)\n", buf.bytesused);
            break;
        }

        unsigned char *cropped = malloc(CROP_WIDTH * CROP_HEIGHT * 2);
        if (!cropped) {
            perror("malloc");
            break;
        }

        process_frame((unsigned char *)buffer_start, cropped,
                      WIDTH, HEIGHT,
                      CROP_WIDTH, CROP_HEIGHT,
                      (WIDTH - CROP_WIDTH) / 2,
                      (HEIGHT - CROP_HEIGHT) / 2);

        FILE *fp = fopen(FILENAME, "wb");
        if (!fp) {
            perror("fopen");
            free(cropped);
            break;
        }

        size_t to_write = CROP_WIDTH * CROP_HEIGHT * 2;
        size_t written = fwrite(cropped, 1, to_write, fp);
        if (written != to_write) {
            perror("fwrite");
            fclose(fp);
            free(cropped);
            break;
        }

        if (fclose(fp) != 0) {
            perror("fclose");
            free(cropped);
            break;
        }

        free(cropped);

        if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            perror("VIDIOC_QBUF");
            break;
        }

        if (stop) {
            break;
        }
    }

    if (xioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        perror("VIDIOC_STREAMOFF");
    }

    munmap(buffer_start, buf.length);
    close(fd);

    if (stop) {
        return EXIT_SUCCESS;
    }
    return EXIT_SUCCESS;
}

