#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PAN_SERVO_PIN   17
#define TILT_SERVO_PIN  18
#define SERVO_FREQ_HZ   50
#define SERVO_RANGE     1000000
#define NEUTRAL_ANGLE   90
#define STEP_DEGREES    5
#define DELAY_MS        100

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int angle_to_pulse_us(int angle) {
    if (angle < 0 || angle > 180) {
        fprintf(stderr, "Error: angle %d out of range (0-180)\n", angle);
        return -1;
    }
    return (int)(500 + (angle * 1000.0 / 180.0));
}

static int set_servo_angle(int pin, int angle) {
    int pulse = angle_to_pulse_us(angle);
    if (pulse < 0) return -1;
    if (gpioServo(pin, pulse) < 0) {
        fprintf(stderr, "Error: gpioServo failed on pin %d\n", pin);
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for pan pin %d\n", PAN_SERVO_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for tilt pin %d\n", TILT_SERVO_PIN);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMfrequency(PAN_SERVO_PIN, SERVO_FREQ_HZ) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency failed for pan pin %d\n", PAN_SERVO_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetPWMfrequency(TILT_SERVO_PIN, SERVO_FREQ_HZ) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency failed for tilt pin %d\n", TILT_SERVO_PIN);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMrange(PAN_SERVO_PIN, SERVO_RANGE) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed for pan pin %d\n", PAN_SERVO_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetPWMrange(TILT_SERVO_PIN, SERVO_RANGE) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed for tilt pin %d\n", TILT_SERVO_PIN);
        gpioTerminate();
        return 1;
    }

    int pan_angle = NEUTRAL_ANGLE;
    int tilt_angle = NEUTRAL_ANGLE;

    if (set_servo_angle(PAN_SERVO_PIN, pan_angle) < 0 ||
        set_servo_angle(TILT_SERVO_PIN, tilt_angle) < 0) {
        gpioTerminate();
        return 1;
    }

    printf("Pan/Tilt Servo Control (pigpio)\n");
    printf("  Pan  : GPIO%d\n", PAN_SERVO_PIN);
    printf("  Tilt : GPIO%d\n", TILT_SERVO_PIN);
    printf("  Angle range: 0-180 degrees\n");
    printf("  Commands: left/right/up/down/q\n");
    printf("Press Ctrl+C to exit.\n\n");

    while (g_running) {
        int c = getchar();
        if (c == EOF) break;

        switch (c) {
            case 'q':
            case 'Q':
                printf("Exiting...\n");
                g_running = 0;
                break;

            case 'a':
            case 'A':
                if (pan_angle > 0) {
                    pan_angle -= STEP_DEGREES;
