#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define SSD1306_I2C_ADDR 0x3C
#define SSD1306_WIDTH 128
#define SSD1306_HEIGHT 64
#define OLED_ROWS 8
#define OLED_COLS 16
#define OLED_CHAR_WIDTH 6
#define OLED_CHAR_HEIGHT 8

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write(int fd, const unsigned char *buf, size_t len) {
    if (write(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int ssd1306_command(int fd, unsigned char cmd) {
    unsigned char buf[2] = {0x00, cmd};
    return i2c_write(fd, buf, 2);
}

static int ssd1306_data(int fd, const unsigned char *data, size_t len) {
    unsigned char *buf = malloc(len + 1);
    if (!buf) return -1;
    buf[0] = 0x40;
    memcpy(buf + 1, data, len);
    int ret = i2c_write(fd, buf, len + 1);
    free(buf);
    return ret;
}

static int ssd1306_init(int fd) {
    if (ssd1306_command(fd, 0xAE) < 0) return -1;
    if (ssd1306_command(fd, 0xD5) < 0) return -1;
    if (ssd1306_command(fd, 0x80) < 0) return -1;
    if (ssd1306_command(fd, 0xA8) < 0) return -1;
    if (ssd1306_command(fd, 0x3F) < 0) return -1;
    if (ssd1306_command(fd, 0xD3) < 0) return -1;
    if (ssd1306_command(fd, 0x00) < 0) return -1;
    if (ssd1306_command(fd, 0x40) < 0) return -1;
    if (ssd1306_command(fd, 0x8D) < 0) return -1;
    if (ssd1306_command(fd, 0x14) < 0) return -1;
    if (ssd1306_command(fd, 0x20) < 0) return -1;
    if (ssd1306_command(fd, 0x00) < 0) return -1;
    if (ssd1306_command(fd, 0xA1) < 0) return -1;
    if (ssd1306_command(fd, 0xC8) < 0) return -1;
    if (ssd1306_command(fd, 0xDA) < 0) return -1;
    if (ssd1306_command(fd, 0x12) < 0) return -1;
    if (ssd1306_command(fd, 0x81) < 0) return -1;
    if (ssd1306_command(fd, 0xCF) < 0) return -1;
    if (ssd1306_command(fd, 0xD9) < 0) return -1;
    if (ssd1306_command(fd, 0xF1) < 0) return -1;
    if (ssd1306_command(fd, 0xDB) < 0) return -1;
    if (ssd1306_command(fd, 0x40) < 0) return -1;
    if (ssd1306_command(fd, 0xA4) < 0) return -1;
    if (ssd1306_command(fd, 0xA6) < 0) return -1;
    if (ssd1306_command(fd, 0xAF) < 0) return -1;
    return 0;
}

static int ssd1306_clear(int fd) {
    unsigned char buf[SSD1306_WIDTH * (SSD1306_HEIGHT / 8)];
    memset(buf, 0x00, sizeof(buf));
    if (ssd1306_command(fd, 0x21) < 0) return -1;
    if (ssd1306_command(fd, 0x00) < 0) return -1;
    if (ssd1306_command(fd, 0x7F) < 0) return -1;
    if (ssd1306_command(fd, 0x22) < 0) return -1;
    if (ssd1306_command(fd, 0x00) < 0) return -1;
    if (ssd1306_command(fd, 0x07) < 0) return -1;
    return ssd1306_data(fd, buf, sizeof(buf));
}

static int ssd1306_set_cursor(int fd, int col, int row) {
    int col_start = (SSD1306_WIDTH / 16) * row;
    if (ssd1306_command(fd, 0xB2) < 0) return -1;
    if (ssd1306_command(fd, (unsigned char)(col_start + (col / 2))) < 0) return -1;
    if (ssd1306_command(fd, (unsigned char)(col % 2)) < 0) return -1;
    return 0;
}

static int ssd1306_print_char(int fd, char c) {
    if (c < 32 || c > 126) c = '?';
    unsigned char font[5];
    for (int i = 0; i < 5; i++) {
        font[i] = (unsigned char)pgm_read_byte(&font5x7[c - 32][i]);
    }
    return ssd1306_data(fd, font, 5);
}

static int read_cpu_temp(void) {
    FILE *fp = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
    if (!fp) {
        fprintf(stderr, "Failed to open CPU temperature file: %s\n", strerror(errno));
        return -1;
    }
    int temp;
    if (fscanf(fp, "%d", &temp) != 1) {
        fprintf(stderr, "Failed to parse CPU temperature\n");
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return temp / 1000;
}

static int read_cpu_usage(void) {
    FILE *fp = fopen("/proc/stat", "r");
    if (!fp) {
        fprintf(stderr, "Failed to open /proc/stat: %s\n", strerror(errno));
        return -1;
    }
    unsigned long long user, nice, system, idle, iowait, irq, softirq, steal, guest, guest_nice;
    int ret = fscanf(fp, "cpu  %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
                     &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal, &guest, &guest_nice);
    fclose(fp);
    if (ret != 10) {
        fprintf(stderr, "Failed to parse /proc/stat\n");
        return -1;
    }
    static unsigned long long prev_idle = 0, prev_total = 0;
    unsigned long long idle_total = idle + iowait;
    unsigned long long total = user + nice + system + idle + iowait + irq + softirq + steal + guest + guest_nice;
    if (prev_total == 0) {
        prev_idle = idle_total;
        prev_total = total;
        return 0;
    }
    unsigned long long idle_diff = idle_total - prev_idle;
    unsigned long long total_diff = total - prev_total;
    prev_idle = idle_total;
    prev_total = total;
    if (total_diff == 0) return 0;
    return (int)(((total_diff - idle_diff) * 100ULL / total_diff) & 0xFF);
}

static void render_text(int fd, const char *text, int row, int col) {
    if (ssd1306_set_cursor(fd, col, row) < 0) return;
    for (int i = 0; text[i] != '\0'; i++) {
        if (ssd1306_print_char(fd, text[i]) < 0) break;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open /dev/i2c-1: %s\n", strerror(errno));
        return 1;
    }
    if (ioctl(fd, I2C_SLAVE, SSD1306_I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        close(fd);
        return 1;
    }
    if (ssd1306_init(fd) < 0) {
        fprintf(stderr, "SSD1306 initialization failed\n");
        close(fd);
        return 1;
    }
    if (ssd1306_clear(fd) < 0) {
        fprintf(stderr, "SSD1306 clear failed\n");
        close(fd);
        return 1;
    }

    while (running) {
        int cpu_temp = read_cpu_temp();
        int cpu_usage = read_cpu_usage();

        char temp_str[16];
        char usage_str[16];
        if (cpu_temp < 0) {
            snprintf(temp_str, sizeof(temp_str), "Temp: ERR");
        } else {
            snprintf(temp_str, sizeof(temp_str), "Temp: %d C", cpu_temp);
        }
        if (cpu_usage < 0) {
            snprintf(usage_str, sizeof(usage_str), "Usage: ERR");
        } else {
            snprintf(usage_str, sizeof(usage_str), "Usage: %d%%", cpu_usage);
        }

        if (ssd1306_clear(fd) < 0) {
            fprintf(stderr, "SSD1306 clear failed\n");
            break;
        }
        render_text(fd, temp_str, 0, 0);
        render_text(fd, usage_str, 1, 0);
        usleep(1000000);
    }

    ssd1306_clear(fd);
    close(fd);
    return 0;
}

