    if (ssd1306_clear(fd) < 0) {
        fprintf(stderr, "SSD1306 clear failed\n");
        close(fd);
        return 1;
    }

    while (running) {
        int cpu_temp = read_cpu_temp();
        int cpu_usage = read_cpu_usage();

        char temp_str[16];
        char usage_str[16];
        if (cpu_temp < 0) {
            snprintf(temp_str, sizeof(temp_str), "Temp: ERR");
        } else {
            snprintf(temp_str, sizeof(temp_str), "Temp: %d C", cpu_temp);
        }
        if (cpu_usage < 0) {
            snprintf(usage_str, sizeof(usage_str), "Usage: ERR");
        } else {
            snprintf(usage_str, sizeof(usage_str), "Usage: %d%%", cpu_usage);
        }

        if (ssd1306_clear(fd) < 0) {
            fprintf(stderr, "SSD1306 clear failed\n");
            break;
        }
        render_text(fd, temp_str, 0, 0);
        render_text(fd, usage_str, 1, 0);
        usleep(1000000);
    }

    ssd1306_clear(fd);
    close(fd);
    return 0;
}

