#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <errno.h>

#define FLOW_SENSOR_GPIO 17
#define I2C_BUS 1
#define I2C_ADDR 0x27
#define LCD_WIDTH 16
#define LCD_CHR 1
#define LCD_CMD 0
#define LCD_LINE_1 0x80
#define LCD_LINE_2 0xC0
#define LCD_BACKLIGHT 0x08
#define ENABLE 0x04

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void lcd_strobe(int data) {
    if (i2c_handle < 0) return;
    if (i2cWriteByte(i2c_handle, data | ENABLE | LCD_BACKLIGHT) < 0) return;
    usleep(500);
    if (i2cWriteByte(i2c_handle, (data & ~ENABLE) | LCD_BACKLIGHT) < 0) return;
    usleep(500);
}

static void lcd_byte(int bits, int mode) {
    int high = mode | (bits & 0xF0) | LCD_BACKLIGHT;
    int low = mode | ((bits << 4) & 0xF0) | LCD_BACKLIGHT;
    if (i2c_handle < 0) return;
    if (i2cWriteByte(i2c_handle, high) < 0) return;
    lcd_strobe(high);
    if (i2cWriteByte(i2c_handle, low) < 0) return;
    lcd_strobe(low);
    if (bits == 0x01 || bits == 0x02) usleep(2000);
}

static void lcd_init(void) {
    if (i2c_handle < 0) return;
    usleep(50000);
    lcd_byte(0x33, LCD_CMD);
    lcd_byte(0x32, LCD_CMD);
    lcd_byte(0x28, LCD_CMD);
    lcd_byte(0x0C, LCD_CMD);
    lcd_byte(0x06, LCD_CMD);
    lcd_byte(0x01, LCD_CMD);
    usleep(2000);
}

static void lcd_clear(void) {
    lcd_byte(0x01, LCD_CMD);
    usleep(2000);
}

static void lcd_set_cursor(int col, int row) {
    int addr = (row == 0) ? 0x80 + col : 0xC0 + col;
    lcd_byte(addr, LCD_CMD);
}

static void lcd_print(const char *str) {
    while (*str) lcd_byte((unsigned char)*str++, LCD_CHR);
}

static void lcd_update(float flow_rate, float volume) {
    char buf[20];
    if (i2c_handle < 0) return;
    lcd_clear();
    lcd_set_cursor(0, 0);
    snprintf(buf, sizeof(buf), "Flow: %.2f L/min", flow_rate);
    lcd_print(buf);
    lcd_set_cursor(0, 1);
    snprintf(buf, sizeof(buf), "Vol: %.2f L", volume);
    lcd_print(buf);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", FLOW_SENSOR_GPIO);
        gpioTerminate();
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d addr 0x%02X: %s\n", I2C_BUS, I2C_ADDR, strerror(errno));
        gpioTerminate();
        return 1;
    }

    lcd_init();
    lcd_clear();
    lcd_set_cursor(0, 0);
    lcd_print("Initializing...");

    int pulse_count = 0;
    float flow_rate = 0.0f;
    float volume = 0.0f;
    time_t last_log_time = time(NULL);
    time_t last_lcd_time = time(NULL);

    while (running) {
        int level = gpioRead(FLOW_SENSOR_GPIO);
        if (level < 0) {
            fprintf(stderr, "GPIO read error on pin %d\n", FLOW_SENSOR_GPIO);
            break;
        }
        if (level == 1) {
            pulse_count++;
            usleep(10000);
            level = gpioRead(FLOW_SENSOR_GPIO);
            if (level == 1) pulse_count++;
        }

        time_t now = time(NULL);
        if (now - last_log_time >= 1) {
            float pulses_per_second = (float)pulse_count;
            flow_rate = pulses_per_second * 60.0f / 7.5f;
            volume += flow_rate / 60.0f;
            printf("Flow Rate: %.2f L/min, Volume: %.2f L\n", flow_rate, volume);
            last_log_time = now;
            pulse_count = 0;
        }

        if (now - last_lcd_time >= 10) {
            lcd_update(flow_rate, volume);
            last_lcd_time = now;
        }
    }

    if (i2c_handle >= 0) {
        lcd_clear();
        lcd_set_cursor(0, 0);
        lcd_print("Shutting down...");
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

