#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define ANEMOMETER_GPIO 17
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS 8
#define I2C_BUS 1
#define I2C_ADDR 0x27
#define LCD_WIDTH 16
#define SAMPLE_WINDOW_MS 500
#define ADC_CHANNEL 0
#define ADC_MAX 1023
#define ADC_MIN 0
#define ADC_STUCK_THRESHOLD 10

static volatile sig_atomic_t running = 1;
static volatile int pulse_count = 0;
static int spi_fd = -1;
static int i2c_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void anemometer_isr(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)level; (void)tick; (void)userdata;
    pulse_count++;
}

static int spi_init(void) {
    char path[32];
    snprintf(path, sizeof(path), "/dev/spidev0.%d", SPI_CHANNEL);
    spi_fd = open(path, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", path, strerror(errno));
        return -1;
    }
    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(spi_fd); spi_fd = -1; return -1;
    }
    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(spi_fd); spi_fd = -1; return -1;
    }
    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI speed: %s\n", strerror(errno));
        close(spi_fd); spi_fd = -1; return -1;
    }
    return 0;
}

static int i2c_init(void) {
    char path[20];
    snprintf(path, sizeof(path), "/dev/i2c-%d", I2C_BUS);
    i2c_fd = open(path, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device %s: %s\n", path, strerror(errno));
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", I2C_ADDR, strerror(errno));
        close(i2c_fd); i2c_fd = -1; return -1;
    }
    return 0;
}

static int read_adc(int channel) {
    if (spi_fd < 0) return -1;
    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = {0};
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0
    };
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    int value = ((rx[1] & 0x03) << 8) | rx[2];
    if (value < ADC_MIN || value > ADC_MAX) {
        fprintf(stderr, "ADC value out of range: %d\n", value);
        return -1;
    }
    return value;
}

static int read_wind_direction(int *direction) {
    int adc_value = read_adc(ADC_CHANNEL);
    if (adc_value < 0) return -1;
    if (adc_value <= ADC_MIN + ADC_STUCK_THRESHOLD || adc_value >= ADC_MAX - ADC_STUCK_THRESHOLD) {
        fprintf(stderr, "Warning: ADC reading at extreme (%d), sensor may be absent or disconnected\n", adc_value);
        return -1;
