#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <errno.h>

#define FLOW_SENSOR_GPIO 17
#define LCD_I2C_ADDR 0x27
#define LCD_WIDTH 16
#define LCD_CHR 1
#define LCD_CMD 0
#define LCD_LINE_1 0x80
#define LCD_LINE_2 0xC0
#define LCD_BACKLIGHT 0x08
#define ENABLE 0x04
#define E_PULSE_US 1000
#define E_DELAY_US 50
#define PULSE_TO_LITER 0.001
#define MAX_PULSES_PER_SEC 1000
#define SENSOR_TIMEOUT_SEC 60

static volatile sig_atomic_t running = 1;
static volatile int pulse_count = 0;
static volatile uint32_t last_pulse_tick = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void pulse_callback(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)level; (void)userdata;
    if (tick - last_pulse_tick > 1000000) {
        pulse_count++;
        last_pulse_tick = tick;
    }
}

static int lcd_write_byte(int fd, unsigned char val, int mode) {
    unsigned char data[4];
    data[0] = val & 0xF0;
    data[1] = (val << 4) & 0xF0;
    data[2] = data[0] | ENABLE | LCD_BACKLIGHT;
    data[3] = data[1] | ENABLE | LCD_BACKLIGHT;

    for (int i = 0; i < 4; i++) {
        if (i == 0) data[i] |= LCD_CMD;
        else data[i] |= mode;
        if (i < 3) data[i] |= ENABLE;
        if (i > 0) data[i] &= ~ENABLE;

        if (i == 0) usleep(E_PULSE_US);
        if (i == 3) usleep(E_DELAY_US);

        if (i2cWriteByteData(fd, 0x00, data[i]) < 0) {
            fprintf(stderr, "I2C write error: %s\n", strerror(errno));
            return -1;
        }
    }
    return 0;
}

static int lcd_send_command(int fd, unsigned char cmd) {
    return lcd_write_byte(fd, cmd, LCD_CMD);
}

static int lcd_send_data(int fd, unsigned char data) {
    return lcd_write_byte(fd, data, LCD_CHR);
}

static int lcd_init(int fd) {
    usleep(50000);
    lcd_write_byte(fd, 0x33, LCD_CMD);
    lcd_write_byte(fd, 0x32, LCD_CMD);
    lcd_write_byte(fd, 0x28, LCD_CMD);
    lcd_write_byte(fd, 0x0C, LCD_CMD);
    lcd_write_byte(fd, 0x06, LCD_CMD);
    lcd_write_byte(fd, 0x01, LCD_CMD);
    usleep(2000);
    return 0;
}

static int lcd_clear(int fd) {
    if (lcd_send_command(fd, 0x01) < 0) return -1;
    usleep(2000);
    return 0;
}

static int lcd_set_cursor(int fd, int row, int col) {
    unsigned char addr = (row == 0) ? 0x80 : 0xC0;
    addr |= col;
    return lcd_send_command(fd, addr);
}

static int lcd_print(int fd, const char *str) {
    while (*str) {
        if (lcd_send_data(fd, (unsigned char)*str) < 0) return -1;
        str++;
    }
    return 0;
}

static void display_flow_rate(int fd, float flow_rate) {
    char line1[LCD_WIDTH + 1];
    char line2[LCD_WIDTH + 1];

    snprintf(line1, sizeof(line1), "Flow Rate:");
    snprintf(line2, sizeof(line2), "%.2f L/min", flow_rate);

    lcd_clear(fd);
    lcd_set_cursor(fd, 0, 0);
    lcd_print(fd, line1);
    lcd_set_cursor(fd, 1, 0);
    lcd_print(fd, line2);
}

int main(void) {
    int fd = -1;
    int ret = 1;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handlers: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", FLOW_SENSOR_GPIO);
        goto cleanup_gpio;
    }

    if (gpioSetPullUpDown(FLOW_SENSOR_GPIO, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", FLOW_SENSOR_GPIO);
        goto cleanup_gpio;
    }

    if (gpioSetAlertFuncEx(FLOW_SENSOR_GPIO, pulse_callback, NULL) < 0) {
        fprintf(stderr, "Failed to set alert function on GPIO %d\n", FLOW_SENSOR_GPIO);
        goto cleanup_gpio;
    }

    fd = i2cOpen(1, LCD_I2C_ADDR, 0);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus 1 at address 0x%02X: %s\n", LCD_I2C_ADDR, strerror(errno));
        goto cleanup_gpio;
    }

    if (lcd_init(fd) < 0) {
        fprintf(stderr, "LCD initialization failed\n");
        goto cleanup_i2c;
    }

    printf("Water flow monitoring started. Press Ctrl+C to exit.\n");

    time_t last_pulse_time = time(NULL);
    int consecutive_zero_count = 0;

    while (running) {
        sleep(1);

        int current_count = pulse_count;
        pulse_count = 0;

        if (current_count == 0) {
            consecutive_zero_count++;
            if (consecutive_zero_count >= SENSOR_TIMEOUT_SEC) {
                fprintf(stderr, "Warning: No pulses detected for %d seconds. Sensor may be absent or disconnected.\n", SENSOR_TIMEOUT_SEC);
                consecutive_zero_count = 0;
            }
        } else {
            consecutive_zero_count = 0;
        }

        float flow_rate = (float)current_count * PULSE_TO_LITER * 60.0f;

        display_flow_rate(fd, flow_rate);
        printf("Flow Rate: %.2f L/min\n", flow_rate);
    }

    printf("\nShutting down gracefully...\n");
    ret = 0;

cleanup_i2c:
    if (fd >= 0) {
        lcd_clear(fd);
        i2cClose(fd);
    }
cleanup_gpio:
    gpioTerminate();
    return ret;
}

