/*
 * wave_matrix.c — 8x8 common-anode LED matrix wave animation
 *
 * Row anodes (BCM):  2,  3,  4, 17, 27, 22, 10,  9
 * Column cathodes (BCM): 14, 15, 18, 23, 24, 25,  8,  7
 *
 * Build:  gcc -O2 -Wall -Wextra -o wave_matrix wave_matrix.c -lgpiod
 *
 * Each column is scanned left-to-right.  A column lights when its
 * cathode is LOW and all row anodes are HIGH.  The animation runs
 * indefinitely until SIGINT/SIGTERM.
 */

#include <errno.h>
#include <gpiod.h>
#include <signal.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

#define NUM_ROWS    8
#define NUM_COLS    8
#define DELAY_MS    150

static const unsigned int row_pins[NUM_ROWS] = {2, 3, 4, 17, 27, 22, 10, 9};
static const unsigned int col_pins[NUM_COLS] = {14, 15, 18, 23, 24, 25, 8, 7};

static volatile sig_atomic_t g_running = 1;

static void sighandler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static void sleep_ms(unsigned int ms)
{
    while (ms > 0) {
        unsigned int chunk = (ms > 1000) ? 1000 : ms;
        usleep(chunk * 1000U);
        ms -= chunk;
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *row_lines[NUM_ROWS];
    struct gpiod_line *col_lines[NUM_COLS];
    int ret = EXIT_FAILURE;

    for (int i = 0; i < NUM_ROWS; i++) row_lines[i] = NULL;
    for (int i = 0; i < NUM_COLS; i++) col_lines[i] = NULL;

    if (install_signal_handlers() != 0)
        goto cleanup;

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (chip == NULL) {
        chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (chip == NULL) {
        chip = gpiod_chip_open_by_label("pinctrl-bcm2711");
    }
    if (chip == NULL) {
        chip = gpiod_chip_open_by_number(0);
    }
    if (chip == NULL) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        goto cleanup;
    }

    for (int i = 0; i < NUM_ROWS; i++) {
        row_lines[i] = gpiod_chip_get_line(chip, row_pins[i]);
        if (row_lines[i] == NULL) {
            fprintf(stderr, "Failed to get row line %u: %s\n",
                    row_pins[i], strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_request_output(row_lines[i], "wave_matrix", 0) < 0) {
            fprintf(stderr, "Failed to request row line %u as output: %s\n",
                    row_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    for (int i = 0; i < NUM_COLS; i++) {
        col_lines[i] = gpiod_chip_get_line(chip, col_pins[i]);
        if (col_lines[i] == NULL) {
            fprintf(stderr, "Failed to get column line %u: %s\n",
                    col_pins[i], strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_request_output(col_lines[i], "wave_matrix", 1) < 0) {
            fprintf(stderr, "Failed to request column line %u as output: %s\n",
                    col_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    /* Ensure all columns are off (cathodes HIGH) and all rows are off
     * (anodes LOW). */
    for (int i = 0; i < NUM_ROWS; i++) {
        if (gpiod_line_set_value(row_lines[i], 0) < 0) {
            fprintf(stderr, "Failed to set row %u LOW: %s\n",
                    row_pins[i], strerror(errno));
            goto cleanup;
        }
    }
    for (int i = 0; i < NUM_COLS; i++) {
        if (gpiod_line_set_value(col_lines[i], 1) < 0) {
            fprintf(stderr, "Failed to set column %u HIGH: %s\n",
                    col_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    while (g_running) {
        for (int col = 0; col < NUM_COLS && g_running; col++) {
            /* Clear the previous column by setting its cathode HIGH. */
            if (gpiod_line_set_value(col_lines[col], 1) < 0) {
                fprintf(stderr, "Failed to set column %u HIGH: %s\n",
                        col_pins[col], strerror(errno));
                goto cleanup;
            }

            /* Light the LEDs in this column sequentially. */
            for (int row = 0; row < NUM_ROWS; row++) {
                if (gpiod_line_set_value(row_lines[row], 1) < 0) {
                    fprintf(stderr, "Failed to set row %u HIGH: %s\n",
                            row_pins[row], strerror(errno));
                    goto cleanup;
                }
            }

            sleep_ms(DELAY_MS);

            for (int row = 0; row < NUM_ROWS; row++) {
                if (gpiod_line_set_value(row_lines[row], 0) < 0) {
                    fprintf(stderr, "Failed to set row %u LOW: %s\n",
                            row_pins[row], strerror(errno));
                    goto cleanup;
                }
            }

            /* Re-enable this column for the next iteration. */
            if (gpiod_line_set_value(col_lines[col], 0) < 0) {
                fprintf(stderr, "Failed to set column %u LOW: %s\n",
                        col_pins[col], strerror(errno));
                goto cleanup;
            }
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Turn off all LEDs and release lines. */
    for (int i = 0; i < NUM_ROWS; i++) {
        if (row_lines[i] != NULL) {
            gpiod_line_set_value(row_lines[i], 0);
            gpiod_line_release(row_lines[i]);
        }
    }
    for (int i = 0; i < NUM_COLS; i++) {
        if (col_lines[i] != NULL) {
            gpiod_line_set_value(col_lines[i], 1);
            gpiod_line_release(col_lines[i]);
        }
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    return ret;
}

