/*
 * VL53L3CX Multi-Target Distance Reader for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   VL53L3CX SDA  -> GPIO2 (I2C1 SDA, pin 3)
 *   VL53L3CX SCL  -> GPIO3 (I2C1 SCL, pin 5)
 *   VL53L3CX VDD  -> 3.3 V
 *   VL53L3CX GND  -> GND
 *
 * Build: gcc -O2 -Wall -o vl53l3cx_multi vl53l3cx_multi.c -lpigpio -lrt
 * Run:   sudo ./vl53l3cx_multi
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- VL53L3CX I2C address ---- */
#define VL53L3CX_ADDR 0x29

/* ---- VL53L3CX register addresses (16-bit, big-endian on bus) ---- */
#define VL53L3CX_REG_IDENTIFICATION_MODEL_ID  0x010F
#define VL53L3CX_REG_SYSTEM_MODE_START        0x0000
#define VL53L3CX_REG_RESULT_RANGE_STATUS      0x0014
#define VL53L3CX_REG_RESULT_DISTANCE          0x0096
#define VL53L3CX_REG_RESULT_AMBIENT          0x0098
#define VL53L3CX_REG_RESULT_SIGMA            0x009A
#define VL53L3CX_REG_RESULT_TARGET_STATUS     0x009C
#define VL53L3CX_REG_RESULT_NB_TARGET_DETECTED 0x009E

/* ---- Expected model ID ---- */
#define VL53L3CX_MODEL_ID 0xEA

/* ---- Polling interval (microseconds) ---- */
#define POLL_INTERVAL_US 100000

/* ---- Global state for signal handler ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Low-level I2C helpers                                               */
/* ------------------------------------------------------------------ */
static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (char)value;
    return i2cWriteDevice(handle, buf, 3);
}

static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *buf, uint32_t len)
{
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;

    if (i2cWriteDevice(handle, reg_buf, 2) < 0)
        return -1;
    return i2cReadDevice(handle, (char *)buf, len);
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                    */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    time_t rawtime;
    struct tm timeinfo;

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &timeinfo);
}

/* ------------------------------------------------------------------ */
/* Sensor initialization                                               */
/* ------------------------------------------------------------------ */
static int init_vl53l3cx(int handle)
{
    uint8_t model_id = 0;

    /* Read and verify model ID */
    if (i2c_read_reg16(handle, VL53L3CX_REG_IDENTIFICATION_MODEL_ID, &model_id, 1) < 0) {
        fprintf(stderr, "Error: Failed to read model ID (I2C bus error or sensor absent).\n");
        return -1;
    }
    if (model_id != VL53L3CX_MODEL_ID) {
        fprintf(stderr, "Error: Unexpected model ID 0x%02X (expected 0x%02X). Wrong sensor?\n",
                model_id, VL53L3CX_MODEL_ID);
        return -1;
    }
    printf("VL53L3CX detected (model ID 0x%02X).\n", model_id);

    /*
     * Perform the full VL53L3CX proprietary initialization sequence.
     * This includes firmware download, system configuration, and
     * ranging mode setup.  The exact register values and sequence
     * depend on the specific firmware revision; the code below
     * serves as a placeholder that must be replaced with the
     * official STMicroelectronics initialization routine.
     */
    printf("Initializing VL53L3CX (placeholder firmware download)...\n");

    /* Placeholder: write configuration registers */
    if (i2c_write_reg16(handle, 0x0001, 0x01) < 0) return -1;
    if (i2c_write_reg16(handle, 0x0002, 0x02) < 0) return -1;
    if (i2c_write_reg16(handle, 0x0003, 0x03) < 0) return -1;
    if (i2c_write_reg16(handle, 0x0004, 0x04) < 0) return -1;

    /* Start ranging */
    if (i2c_write_reg16(handle, VL53L3CX_REG_SYSTEM_MODE_START, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to start ranging.\n");
        return -1;
    }

    printf("VL53L3CX initialized and ranging started.\n");
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read distance data for all detected targets                         */
/* ------------------------------------------------------------------ */
static int read_distance_data(int handle, int *distances, int *num_targets)
{
    uint8_t status = 0;
    uint8_t buf[2];
    int ret;

    /* Check if new data is ready */
    ret = i2c_read_reg16(handle, VL53L3CX_REG_RESULT_RANGE_STATUS, &status, 1);
    if (ret < 0) {
        fprintf(stderr, "Error: Failed to read range status.\n");
        return -1;
    }

    /* Bit 0 of RANGE_STATUS indicates data ready */
    if (!(status & 0x01)) {
        return 1; /* No new data yet */
    }

    /* Read number of detected targets */
    ret = i2c_read_reg16(handle, VL53L3CX_REG_RESULT_NB_TARGET_DETECTED, buf, 2);
    if (ret < 0) {
        fprintf(stderr, "Error: Failed to read number of targets.\n");
        return -1;
    }
    *num_targets = (buf[0] << 8) | buf[1];

    if (*num_targets > 4) {
        fprintf(stderr, "Warning: %d targets detected (max 4). Clipping.\n", *num_targets);
        *num_targets = 4;
    }

    /* Read distance for each target (2 bytes each, big-endian) */
    for (int i = 0; i < *num_targets; i++) {
        uint16_t reg = VL53L3CX_REG_RESULT_DISTANCE + (uint16_t)(i * 2);
        ret = i2c_read_reg16(handle, reg, buf, 2);
        if (ret < 0) {
            fprintf(stderr, "Error: Failed to read distance for target %d.\n", i);
            return -1;
        }
        distances[i] = (buf[0] << 8) | buf[1];
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int distances[4];
    int num_targets;
    char timestamp[32];

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at VL53L3CX address */
    g_i2c_handle = i2cOpen(1, VL53L3CX_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus 1 at address 0x%02X (code %d).\n",
                VL53L3CX_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (init_vl53l3cx(g_i2c_handle) != 0) {
        fprintf(stderr, "Error: VL53L3CX initialization failed.\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Reading distance data every 100 ms. Press Ctrl+C to exit.\n");

    /* Main polling loop */
    while (g_running) {
        int rc = read_distance_data(g_i2c_handle, distances, &num_targets);
        if (rc == 0) {
            get_timestamp(timestamp, sizeof(timestamp));
            printf("%s - Targets detected: %d\n", timestamp, num_targets);
            for (int i = 0; i < num_targets; i++) {
                printf("  Target %d: %d mm\n", i + 1, distances[i]);
            }
            printf("\n");
        } else if (rc < 0) {
            fprintf(stderr, "Error reading distance data. Continuing...\n");
        }
        /* rc == 1: no new data, just wait */
        gpioDelay(POLL_INTERVAL_US);
    }

    /* Graceful shutdown */
    printf("\nShutting down...\n");
    if (g_i2c_handle >= 0) {
        i2c_write_reg16(g_i2c_handle, VL53L3CX_REG_SYSTEM_MODE_START, 0x00);
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

