static void cleanup(void) {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction failed");
        return EXIT_FAILURE;
    }

    if (init_sensor() < 0) {
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen log file failed");
        cleanup();
        return EXIT_FAILURE;
    }

    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Distance\n");
        fflush(log_file);
    }

    while (running) {
        uint16_t distance;
        if (read_distance(&distance) < 0) {
            fprintf(stderr, "I2C read error, attempting to re-open I2C bus...\n");
            if (i2c_fd >= 0) {
                close(i2c_fd);
                i2c_fd = -1;
            }
            usleep(1000000);
            if (init_sensor() < 0) {
                fprintf(stderr, "Failed to re-initialize I2C sensor.\n");
            } else {
                fprintf(stderr, "I2C bus re-initialized successfully.\n");
            }
            continue;
        }
        log_data(log_file, (int)distance);
        usleep(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

