#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define IR_SENSOR_PIN 4
#define LED_PIN 17
#define LOG_FILE "proximity.log"
#define POLL_INTERVAL_US 100000
#define LED_BLINK_US 100000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "Error getting time: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    struct tm tm_utc;
    if (gmtime_r(&t, &tm_utc) == NULL) {
        fprintf(stderr, "Error converting time to UTC\n");
        fclose(fp);
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s %s\n", timestamp, message) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static void blink_led(void) {
    if (gpioWrite(LED_PIN, 1) < 0) {
        fprintf(stderr, "Error turning LED on\n");
        return;
    }
    gpioDelay(LED_BLINK_US);
    if (gpioWrite(LED_PIN, 0) < 0) {
        fprintf(stderr, "Error turning LED off\n");
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error registering SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error registering SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(IR_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error setting IR sensor pin mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting LED pin mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioWrite(LED_PIN, 0) < 0) {
        fprintf(stderr, "Error initializing LED state\n");
        gpioTerminate();
        return 1;
    }

    int last_state = gpioRead(IR_SENSOR_PIN);
    if (last_state < 0) {
        fprintf(stderr, "Error reading initial IR sensor state\n");
        gpioTerminate();
        return 1;
    }

    printf("Proximity detection started. Press Ctrl+C to exit.\n");

    while (running) {
        int current_state = gpioRead(IR_SENSOR_PIN);
        if (current_state < 0) {
            fprintf(stderr, "Error reading IR sensor\n");
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        if (current_state == 0 && last_state == 1) {
            if (log_event("Object detected") != 0) {
                fprintf(stderr, "Error logging event\n");
            }
            blink_led();
        }

        last_state = current_state;
        gpioDelay(POLL_INTERVAL_US);
    }

    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return 0;
}

