/*
 * HC-SR04 Ultrasonic Distance Sensor Logger
 * Board:  Raspberry Pi Zero W
 * Trigger: GPIO 17 (BCM)  - 3.3 V output
 * Echo:    GPIO 27 (BCM)  - 3.3 V input (via 1 k/2 k divider from 5 V echo)
 *
 * Build:  gcc -O2 -Wall -Wextra -o distance_logger distance_logger.c -lpigpio -lrt
 * Run:    sudo ./distance_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN      17
#define ECHO_PIN         27

#define SPEED_OF_SOUND   34300.0   /* cm/s at 20 °C */
#define MIN_DISTANCE_CM  2.0
#define MAX_DISTANCE_CM  400.0
#define WATER_THRESHOLD  15.0
#define LOG_FILE         "distance_log.txt"
#define SAMPLE_INTERVAL  60       /* seconds between readings */
#define ECHO_TIMEOUT_US  30000    /* 30 ms max echo wait */
#define TRIGGER_PULSE_US 10       /* 10 µs trigger pulse */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Returns elapsed microseconds between two pigpio tick values.       */
static uint32_t elapsed_us(uint32_t start, uint32_t end)
{
    return end - start;  /* pigpio ticks are uint32_t; subtraction wraps */
}

/* ------------------------------------------------------------------ */
/* Issue a 10 µs trigger pulse.                                       */
static int trigger_sensor(void)
{
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 1) failed\n");
        return -1;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 0) failed\n");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Wait for the echo pin to go HIGH, returning the tick at which it   */
/* rises, or 0 on timeout / error.                                     */
static uint32_t wait_for_echo_rise(void)
{
    uint32_t start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if (elapsed_us(start_tick, gpioTick()) > ECHO_TIMEOUT_US)
            return 0;  /* timeout */
    }
    return gpioTick();
}

/* ------------------------------------------------------------------ */
/* Wait for the echo pin to go LOW, returning the tick at which it    */
/* falls, or 0 on timeout / error.                                     */
static uint32_t wait_for_echo_fall(uint32_t rise_tick)
{
    while (gpioRead(ECHO_PIN) == 1) {
        if (elapsed_us(rise_tick, gpioTick()) > ECHO_TIMEOUT_US)
            return 0;  /* timeout */
    }
    return gpioTick();
}

/* ------------------------------------------------------------------ */
/* Compute distance (cm) from the pulse width in microseconds.        */
static double calculate_distance(uint32_t pulse_us)
{
    return (double)pulse_us * SPEED_OF_SOUND / 2000000.0;
}

/* ------------------------------------------------------------------ */
/* Append a timestamped entry to the log file.                        */
static void log_entry(const char *msg)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];

    if (t == NULL) {
        strncpy(ts, "UNKNOWN", sizeof(ts) - 1);
        ts[sizeof(ts) - 1] = '\0';
    } else {
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    }

    if (g_log_fp) {
        fprintf(g_log_fp, "%s: %s\n", ts, msg);
        fflush(g_log_fp);
    }
    printf("%s: %s\n", ts, msg);
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure GPIO ---- */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(TRIGGER) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(ECHO) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    /* Ensure trigger starts LOW */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(50000);  /* 50 ms settle */

    /* ---- Open log file ---- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 logger started. Logging to %s every %d s. Press Ctrl+C to exit.\n",
           LOG_FILE, SAMPLE_INTERVAL);

    /* ---- Main loop ---- */
    while (g_running) {
        if (trigger_sensor() < 0) {
            log_entry("ERROR: trigger pulse failed");
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        uint32_t rise_tick = wait_for_echo_rise();
        if (rise_tick == 0) {
            log_entry("ERROR: echo pin never went HIGH (sensor absent or wiring fault)");
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        uint32_t fall_tick = wait_for_echo_fall(rise_tick);
        if (fall_tick == 0) {
            log_entry("ERROR: echo pin never went LOW (timeout)");
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        uint32_t pulse_us = elapsed_us(rise_tick, fall_tick);
        double distance = calculate_distance(pulse_us);

        if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
            char msg[128];
            snprintf(msg, sizeof(msg),
                     "ERROR: distance %.2f cm out of range [%.0f-%.0f] cm",
                     distance, MIN_DISTANCE_CM, MAX_DISTANCE_CM);
            log_entry(msg);
        } else {
            char msg[128];
            snprintf(msg, sizeof(msg), "Distance: %.2f cm", distance);
            log_entry(msg);

            if (distance < WATER_THRESHOLD) {
                log_entry("Time to water the plant!");
            }
        }

        sleep(SAMPLE_INTERVAL);
    }

    /* ---- Cleanup ---- */
    printf("\nShutting down...\n");
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

