/*
 * Raspberry Pi 4 Model B - APDS9960 Proximity & RGB Logger
 *
 * Wiring:
 *   APDS9960 SDA -> GPIO2 (I2C1 SDA, pin 3)
 *   APDS9960 SCL -> GPIO3 (I2C1 SCL, pin 5)
 *   APDS9960 VDD -> 3.3 V
 *   APDS9960 GND -> GND
 *
 * Build: gcc -O2 -Wall -o apds9960_logger apds9960_logger.c -lpigpio -lrt
 * Run:   sudo ./apds9960_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- APDS9960 register addresses ---- */
#define APDS9960_I2C_ADDR        0x39

#define APDS9960_ENABLE          0x80
#define APDS9960_ATIME           0x81
#define APDS9960_PTIME           0x82
#define APDS9960_WTIME           0x83
#define APDS9960_PPULSE          0x8E
#define APDS9960_CONTROL         0x8F
#define APDS9960_CONFIG1         0x90
#define APDS9960_CONFIG2         0x91
#define APDS9960_ID              0x92
#define APDS9960_STATUS          0x93
#define APDS9960_CDATAL          0x94
#define APDS9960_CDATAH          0x95
#define APDS9960_RDATAL          0x96
#define APDS9960_RDATAH          0x97
#define APDS9960_GDATAL          0x98
#define APDS9960_GDATAH          0x99
#define APDS9960_BDATAL          0x9A
#define APDS9960_BDATAH          0x9B
#define APDS9960_PDATA           0x9C

#define APDS9960_ENABLE_PON      0x01
#define APDS9960_ENABLE_AEN      0x02
#define APDS9960_ENABLE_PEN      0x04
#define APDS9960_ENABLE_RUNEN    0x08

#define APDS9960_PERS            0x61
#define APDS9960_CONFIG3         0x62
#define APDS9960_CONFIG4         0x63
#define APDS9960_CONFIG5         0x64

#define APDS9960_ID_VAL          0xAB

#define PROXIMITY_THRESHOLD      200
#define POLL_DELAY_US            100000  /* 100 ms */
#define I2C_BUS                  1

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Low-level I2C helpers ---- */
static int i2c_write_byte(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0)
        fprintf(stderr, "i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, value, rc);
    return rc;
}

static int i2c_read_byte(int handle, uint8_t reg, uint8_t *value)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "i2cReadByteData(reg=0x%02X) failed: %d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int i2c_read_word(int handle, uint8_t reg, uint16_t *value)
{
    int rc = i2cReadWordData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "i2cReadWordData(reg=0x%02X) failed: %d\n", reg, rc);
        return -1;
    }
    *value = (uint16_t)rc;
    return 0;
}

/* ---- APDS9960 driver ---- */
static int apds9960_init(int handle)
{
    uint8_t id = 0;

    if (i2c_read_byte(handle, APDS9960_ID, &id) < 0)
        return -1;
    if (id != APDS9960_ID_VAL) {
        fprintf(stderr, "APDS9960 ID mismatch: got 0x%02X, expected 0x%02X\n",
                id, APDS9960_ID_VAL);
        return -1;
    }

    if (i2c_write_byte(handle, APDS9960_ENABLE, 0x00) < 0) return -1;
    if (i2c_write_byte(handle, APDS9960_ATIME, 0xFF)   < 0) return -1;
    if (i2c_write_byte(handle, APDS9960_PTIME, 0x00)   < 0) return -1;
    if (i2c_write_byte(handle, APDS9960_WTIME, 0xFF)   < 0) return -1;
    if (i2c_write_byte(handle, APDS9960_PPULSE, 0x0C)  < 0) return -1;
    if (i2c_write_byte(handle, APDS9960_CONTROL, 0x03) < 0) return -1;
    if (i2c_write_byte(handle, APDS9960_CONFIG1, 0x60) < 0) return -1;
    if (i2c_write_byte(handle, APDS9960_CONFIG2, 0x01) < 0) return -1;
    if (i2c_write_byte(handle, APDS9960_PERS, 0x01)   < 0) return -1;
    if (i2c_write_byte(handle, APDS9960_CONFIG3, 0x00) < 0) return -1;
    if (i2c_write_byte(handle, APDS9960_CONFIG4, 0x00) < 0) return -1;
    if (i2c_write_byte(handle, APDS9960_CONFIG5, 0x00) < 0) return -1;

    if (i2c_write_byte(handle, APDS9960_ENABLE,
                       APDS9960_ENABLE_PON | APDS9960_ENABLE_PEN) < 0)
        return -1;

    return 0;
}

static int apds9960_read_proximity(int handle, uint8_t *prox)
{
    return i2c_read_byte(handle, APDS9960_PDATA, prox);
}

static int apds9960_read_rgb(int handle, uint16_t *r, uint16_t *g, uint16_t *b)
{
    if (i2c_read_word(handle, APDS9960_RDATAL, r) < 0) return -1;
    if (i2c_read_word(handle, APDS9960_GDATAL, g) < 0) return -1;
    if (i2c_read_word(handle, APDS9960_BDATAL, b) < 0) return -1;
    return 0;
}

/* ---- Logging ---- */
static void log_data(FILE *fp, uint16_t r, uint16_t g, uint16_t b, uint8_t prox)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    localtime_r(&t, &tm);
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%u,%u,%u,%u\n", ts, r, g, b, prox);
    fflush(fp);
}

/* ---- Main ---- */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, APDS9960_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, APDS9960_I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (apds9960_init(g_i2c_handle) < 0) {
        fprintf(stderr, "APDS9960 initialisation failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen("color_proximity_log.csv", "a");
    if (!g_log_file) {
        perror("fopen(color_proximity_log.csv)");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0)
        fprintf(g_log_file, "timestamp,red,green,blue,proximity\n");

    printf("APDS9960 logger started. Press Ctrl+C to exit.\n");

    while (g_running) {
        uint8_t prox = 0;
        uint16_t r = 0, g = 0, b = 0;

        if (apds9960_read_proximity(g_i2c_handle, &prox) < 0) {
            fprintf(stderr, "Proximity read error - re-initialising I2C\n");
            i2cClose(g_i2c_handle);
            g_i2c_handle = i2cOpen(I2C_BUS, APDS9960_I2C_ADDR, 0);
            if (g_i2c_handle < 0) {
                fprintf(stderr, "i2cOpen() failed: %d\n", g_i2c_handle);
                break;
            }
            if (apds9960_init(g_i2c_handle) < 0) {
                fprintf(stderr, "APDS9960 re-init failed\n");
                break;
            }
            continue;
        }

        if (apds9960_read_rgb(g_i2c_handle, &r, &g, &b) < 0) {
            fprintf(stderr, "RGB read error - re-initialising I2C\n");
            i2cClose(g_i2c_handle);
            g_i2c_handle = i2cOpen(I2C_BUS, APDS9960_I2C_ADDR, 0);
            if (g_i2c_handle < 0) {
                fprintf(stderr, "i2cOpen() failed: %d\n", g_i2c_handle);
                break;
            }
            if (apds9960_init(g_i2c_handle) < 0) {
                fprintf(stderr, "APDS9960 re-init failed\n");
                break;
            }
            continue;
        }

        if (prox > PROXIMITY_THRESHOLD) {
            log_data(g_log_file, r, g, b, prox);
            printf("Proximity: %u, RGB: (%u, %u, %u)\n", prox, r, g, b);
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* ---- Cleanup ---- */
    printf("\nShutting down...\n");
    if (g_log_file) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

