static int read_proximity(int fd, uint8_t *prox) {
    return i2c_read_reg8(fd, PROX_DATA_REG, prox);
}

static float calculate_bpm(uint8_t prox) {
    return (float)prox * 60.0f;
}

static void get_timestamp(char *buf, size_t len) {
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tm);
}

static int write_csv(const char *ts, float bpm) {
    FILE *fp = fopen(CSV_FILENAME, "a");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", CSV_FILENAME, strerror(errno));
        return -1;
    }
    fprintf(fp, "%s,%.2f\n", ts, bpm);
    fflush(fp);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM): %s\n", strerror(errno));
        return 1;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, SI1182_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n", SI1182_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    if (init_si1182(fd) < 0) {
        fprintf(stderr, "Sensor init failed: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    printf("Si1182 initialized. Logging to %s every %d ms. Ctrl+C to stop.\n",
           CSV_FILENAME, SAMPLE_MS);

    while (running) {
        uint8_t prox;
        if (read_proximity(fd, &prox) < 0) {
            fprintf(stderr, "Warning: I2C read failed: %s\n", strerror(errno));
            usleep(SAMPLE_MS * 1000);
            continue;
        }

        float bpm = calculate_bpm(prox);
        char ts[32];
        get_timestamp(ts, sizeof(ts));

        if (write_csv(ts, bpm) < 0) {
            fprintf(stderr, "Warning: CSV write failed\n");
        }

        usleep(SAMPLE_MS * 1000);
    }

    printf("\nShutting down cleanly.\n");
    close(fd);
    return 0;
}

