        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n", SI1182_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    if (init_si1182(fd) < 0) {
        fprintf(stderr, "Sensor init failed: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

