    if (write(handle, buf, 3) != 3) return -1;
    return 0;
}

static int i2c_read_byte(int handle, uint16_t reg, uint8_t *value) {
    uint8_t buf[2] = { (uint8_t)(reg >> 8), (uint8_t)(reg & 0xFF) };
    if (write(handle, buf, 2) != 2) return -1;
    if (read(handle, value, 1) != 1) return -1;
    return 0;
}

static int i2c_read_word(int handle, uint16_t reg, uint16_t *value) {
    uint8_t buf[2] = { (uint8_t)(reg >> 8), (uint8_t)(reg & 0xFF) };
    if (write(handle, buf, 2) != 2) return -1;
    uint8_t data[2];
    if (read(handle, data, 2) != 2) return -1;
    *value = (uint16_t)data[0] | ((uint16_t)data[1] << 8);
    return 0;
}

static int vl53l0x_init(int handle) {
    uint8_t model_id = 0;
