        return -1;
    }
    return 0;
}

static int i2c_read_byte(int fd, uint8_t reg, uint8_t *out)
{
    if (write(fd, &reg, 1) != 1) {
        perror("i2c_read_byte: write");
        return -1;
    }
    if (read(fd, out, 1) != 1) {
        perror("i2c_read_byte: read");
        return -1;
    }
    return 0;
}

static int ch101_init(int fd)
{
    if (ioctl(fd, I2C_SLAVE, CH101_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        return -1;
    }
    return 0;
}

static int ch101_read_distance(int fd, int *distance_mm)
{
    if (i2c_write_byte(fd, TRIGGER_REG, 0x01) < 0)
        return -1;

    usleep(TRIGGER_DELAY * 1000);

    uint8_t raw;
    if (i2c_read_byte(fd, DISTANCE_REG, &raw) < 0)
        return -1;

    *distance_mm = (int)raw;
    return 0;
}

static void get_timestamp(char *buf, size_t len)
{
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tm);
}

