/*
 * Raspberry Pi Zero W – TDK InvenSense ICU-20201 Ultrasonic ToF Sensor
 *
 * Reads distance from the ICU-20201 via I2C bus 1, samples every 100 ms,
 * lights an LED on GPIO 17 when distance < 20 cm, and logs readings
 * with timestamps to distance_log.txt.
 *
 * Wiring:
 *   ICU-20201 SDA  -> Pi GPIO 2 (I2C1 SDA)
 *   ICU-20201 SCL  -> Pi GPIO 3 (I2C1 SCL)
 *   ICU-20201 VDD  -> 3.3 V
 *   ICU-20201 GND  -> GND
 *   LED anode      -> Pi GPIO 17 (BCM) via 330 Ω resistor
 *   LED cathode    -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o icu20201_monitor icu20201_monitor.c \
 *       -lpigpio -lrt
 *   (pigpio requires root or gpio group membership)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS            1
#define I2C_ADDR           0x62          /* ICU-20201 default I2C address */
#define GPIO_LED           17            /* BCM pin for the LED */
#define DISTANCE_THRESHOLD 20.0f         /* cm */
#define SAMPLE_PERIOD_US   100000        /* 100 ms */
#define LOG_FILE           "distance_log.txt"

/* ICU-20201 register addresses (16-bit, big-endian on the bus) */
#define REG_WHO_AM_I       0x00
#define REG_DISTANCE_LSB   0x04
#define REG_DISTANCE_MSB   0x05
#define REG_CONFIG         0x0A
#define REG_POWER_MGMT     0x0B

#define WHO_AM_I_EXPECTED  0x20          /* Expected value for WHO_AM_I */

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* --------------------------- Signal handling ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- I2C helpers --------------------------------- */
static int i2c_read_reg8(int handle, uint8_t reg, uint8_t *val)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[I2C] read reg 0x%02X failed: %s\n",
                reg, pigpio_error(rc));
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

static int i2c_write_reg8(int handle, uint8_t reg, uint8_t val)
{
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "[I2C] write reg 0x%02X val 0x%02X failed: %s\n",
                reg, val, pigpio_error(rc));
        return -1;
    }
    return 0;
}

/* --------------------------- Sensor init --------------------------------- */
static int init_sensor(int handle)
{
    uint8_t who;
    if (i2c_read_reg8(handle, REG_WHO_AM_I, &who) != 0)
        return -1;

    if (who != WHO_AM_I_EXPECTED) {
        fprintf(stderr, "[Sensor] WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who, WHO_AM_I_EXPECTED);
        return -1;
    }

    /* Power on: clear SLEEP bit (bit 0) in POWER_MGMT */
    if (i2c_write_reg8(handle, REG_POWER_MGMT, 0x00) != 0)
        return -1;

    /* Configure: 100 ms measurement period, continuous mode */
    if (i2c_write_reg8(handle, REG_CONFIG, 0x01) != 0)
        return -1;

    return 0;
}

/* --------------------------- Distance read ------------------------------- */
static int read_distance(int handle, float *distance_cm)
{
    uint8_t lsb, msb;
    if (i2c_read_reg8(handle, REG_DISTANCE_LSB, &lsb) != 0)
        return -1;
    if (i2c_read_reg8(handle, REG_DISTANCE_MSB, &msb) != 0)
        return -1;

    uint16_t raw = ((uint16_t)msb << 8) | lsb;

    /* Convert raw to centimetres (per datasheet: 1 LSB = 0.01 cm) */
    *distance_cm = (float)raw * 0.01f;
    return 0;
}

/* --------------------------- Logging ------------------------------------- */
static void log_distance(FILE *fp, float distance_cm)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "[Log] localtime_r failed\n");
        return;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "[Log] strftime failed\n");
        return;
    }

    fprintf(fp, "%s,%.2f\n", ts, distance_cm);
    fflush(fp);
}

/* --------------------------- Cleanup ------------------------------------- */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    /* gpioTerminate is safe to call even if gpioInitialise failed */
    gpioTerminate();
}

/* ------------------------------- Main ------------------------------------ */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- I2C open --- */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %s\n", pigpio_error(g_i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Sensor init --- */
    if (init_sensor(g_i2c_handle) != 0) {
        fprintf(stderr, "Sensor initialisation failed (sensor absent or bus error)\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- GPIO setup --- */
    if (gpioSetMode(GPIO_LED, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d) failed\n", GPIO_LED);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(GPIO_LED, 0);

    /* --- Log file --- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("fopen(" LOG_FILE ")");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Signals --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("ICU-20201 monitoring started. Press Ctrl+C to exit.\n");

    /* --- Main loop --- */
    while (g_running) {
        float distance;
        if (read_distance(g_i2c_handle, &distance) != 0) {
            fprintf(stderr, "Distance read failed; retrying next cycle\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        log_distance(g_log_file, distance);

        if (distance < DISTANCE_THRESHOLD) {
            gpioWrite(GPIO_LED, 1);
        } else {
            gpioWrite(GPIO_LED, 0);
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* --- Graceful shutdown --- */
    gpioWrite(GPIO_LED, 0);
    cleanup();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

