/*
 * Si1182-GMR Proximity & Ambient Light Logger for Raspberry Pi Zero W
 *
 * Wiring:
 *   Si1182 SDA  -> GPIO2 (I2C bus 1 SDA)
 *   Si1182 SCL  -> GPIO3 (I2C bus 1 SCL)
 *   Si1182 VDD  -> 3.3 V
 *   Si1182 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -o si1182_logger si1182_logger.c -li2c
 * Run:    sudo ./si1182_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SI1182_ADDR    0x60
#define LOG_FILE       "biometric_log.txt"
#define SAMPLE_MS      500
#define MAX_RETRIES    3

/* Si1182 register addresses (from datasheet) */
#define REG_PART_ID        0x00
#define REG_REV_ID         0x01
#define REG_SEQ_ID         0x02
#define REG_INT_CFG        0x03
#define REG_IRQ_ENABLE     0x04
#define REG_IRQ_MODE1      0x05
#define REG_IRQ_MODE2      0x06
#define REG_HW_KEY         0x07
#define REG_MEAS_RATE0     0x08
#define REG_MEAS_RATE1     0x09
#define REG_ALS_RATE       0x0A
#define REG_PS_RATE        0x0B
#define REG_ALS_IR_ADCMUX  0x0C
#define REG_PS1_ADCMUX     0x0D
#define REG_PS2_ADCMUX     0x0E
#define REG_PS3_ADCMUX     0x0F
#define REG_ALS_IR_ADC_GAIN 0x10
#define REG_PS_ADC_GAIN    0x11
#define REG_ALS_IR_ADC_MISC 0x12
#define REG_PS_ADC_MISC    0x13
#define REG_ALS_VIS_ADC_GAIN 0x14
#define REG_PS_ADC_GAIN2   0x15
#define REG_ALS_VIS_ADC_MISC 0x16
#define REG_PS_ADC_MISC2   0x17
#define REG_ALS_VIS_DATA0  0x22
#define REG_ALS_VIS_DATA1  0x23
#define REG_ALS_IR_DATA0   0x24
#define REG_ALS_IR_DATA1   0x25
#define REG_PS1_DATA0      0x26
#define REG_PS1_DATA1      0x27
#define REG_PS2_DATA0      0x28
#define REG_PS2_DATA1      0x29
#define REG_PS3_DATA0      0x2A
#define REG_PS3_DATA1      0x2B

#define EXPECTED_PART_ID   0x82

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (write(fd, buf, sizeof(buf)) == (ssize_t)sizeof(buf))
            return 0;
        if (errno == EINTR) continue;
        fprintf(stderr, "[WARN] I2C write to reg 0x%02X failed (attempt %d/%d): %s\n",
                reg, attempt + 1, MAX_RETRIES, strerror(errno));
        usleep(10000);
    }
    return -1;
}

/* ------------------------------------------------------------------ */
static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *out)
{
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (write(fd, &reg, 1) != 1) {
            if (errno == EINTR) continue;
            fprintf(stderr, "[WARN] I2C write (reg select 0x%02X) failed (attempt %d/%d): %s\n",
                    reg, attempt + 1, MAX_RETRIES, strerror(errno));
            usleep(10000);
            continue;
        }
        uint8_t val;
        if (read(fd, &val, 1) != 1) {
            if (errno == EINTR) continue;
            fprintf(stderr, "[WARN] I2C read from reg 0x%02X failed (attempt %d/%d): %s\n",
                    reg, attempt + 1, MAX_RETRIES, strerror(errno));
            usleep(10000);
            continue;
        }
        *out = val;
        return 0;
    }
    return -1;
}

/* ------------------------------------------------------------------ */
static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t buf[2];
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (write(fd, &reg, 1) != 1) {
            if (errno == EINTR) continue;
            fprintf(stderr, "[WARN] I2C write (reg select 0x%02X) failed (attempt %d/%d): %s\n",
                    reg, attempt + 1, MAX_RETRIES, strerror(errno));
            usleep(10000);
            continue;
        }
        if (read(fd, buf, 2) != 2) {
            if (errno == EINTR) continue;
            fprintf(stderr, "[WARN] I2C read16 from reg 0x%02X failed (attempt %d/%d): %s\n",
                    reg, attempt + 1, MAX_RETRIES, strerror(errno));
            usleep(10000);
            continue;
        }
        *out = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
        return 0;
    }
    return -1;
}

/* ------------------------------------------------------------------ */
static int init_si1182(int fd)
{
    uint8_t part_id = 0;
    if (i2c_read_reg8(fd, REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "[ERROR] Cannot read PART_ID — sensor absent or bus error.\n");
        return -1;
    }
    if (part_id != EXPECTED_PART_ID) {
        fprintf(stderr, "[ERROR] Unexpected PART_ID 0x%02X (expected 0x%02X).\n",
                part_id, EXPECTED_PART_ID);
        return -1;
    }
    printf("[INFO] Si1182 detected (PART_ID=0x%02X).\n", part_id);

    /* Hardware key (required by datasheet) */
    if (i2c_write_reg8(fd, REG_HW_KEY, 0x17) != 0) return -1;

    /* Measurement rates: 0x00 = one-shot / manual mode */
    if (i2c_write_reg8(fd, REG_MEAS_RATE0, 0x00) != 0) return -1;
    if (i2c_write_reg8(fd, REG_MEAS_RATE1, 0x00) != 0) return -1;
    if (i2c_write_reg8(fd, REG_ALS_RATE,   0x00) != 0) return -1;
    if (i2c_write_reg8(fd, REG_PS_RATE,    0x00) != 0) return -1;

    /* ADC mux: VIS for ALS, IR for ALS_IR, PS1 for proximity */
    if (i2c_write_reg8(fd, REG_ALS_IR_ADCMUX, 0x03) != 0) return -1;
    if (i2c_write_reg8(fd, REG_PS1_ADCMUX,    0x01) != 0) return -1;

    /* Gain: 0x00 = default */
    if (i2c_write_reg8(fd, REG_ALS_IR_ADC_GAIN, 0x00) != 0) return -1;
    if (i2c_write_reg8(fd, REG_PS_ADC_GAIN,     0x00) != 0) return -1;
    if (i2c_write_reg8(fd, REG_ALS_VIS_ADC_GAIN,0x00) != 0) return -1;
    if (i2c_write_reg8(fd, REG_PS_ADC_GAIN2,    0x00) != 0) return -1;

    /* Misc: 0x00 = default */
    if (i2c_write_reg8(fd, REG_ALS_IR_ADC_MISC, 0x00) != 0) return -1;
    if (i2c_write_reg8(fd, REG_PS_ADC_MISC,     0x00) != 0) return -1;
    if (i2c_write_reg8(fd, REG_ALS_VIS_ADC_MISC,0x00) != 0) return -1;
    if (i2c_write_reg8(fd, REG_PS_ADC_MISC2,    0x00) != 0) return -1;

    /* Interrupt configuration: clear any pending */
    if (i2c_write_reg8(fd, REG_INT_CFG, 0x00) != 0) return -1;
    if (i2c_write_reg8(fd, REG_IRQ_ENABLE, 0x00) != 0) return -1;
    if (i2c_write_reg8(fd, REG_IRQ_MODE1, 0x00) != 0) return -1;
    if (i2c_write_reg8(fd, REG_IRQ_MODE2, 0x00) != 0) return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
static int read_sensor_data(int fd, uint16_t *prox, uint16_t *als_vis, uint16_t *als_ir)
{
    if (i2c_read_reg16(fd, REG_PS1_DATA0, prox) != 0) return -1;
    if (i2c_read_reg16(fd, REG_ALS_VIS_DATA0, als_vis) != 0) return -1;
    if (i2c_read_reg16(fd, REG_ALS_IR_DATA0, als_ir) != 0) return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, uint16_t prox, uint16_t als_vis, uint16_t als_ir)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "[WARN] localtime_r failed: %s\n", strerror(errno));
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Proximity=%u, ALS_VIS=%u, ALS_IR=%u\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            prox, als_vis, als_ir);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("[ERROR] sigaction");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        perror("[ERROR] open " I2C_BUS);
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SI1182_ADDR) < 0) {
        perror("[ERROR] ioctl I2C_SLAVE");
        cleanup();
        return EXIT_FAILURE;
    }

    if (init_si1182(g_i2c_fd) != 0) {
        fprintf(stderr, "[ERROR] Si1182 initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("[ERROR] fopen " LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    printf("[INFO] Logging to %s every %d ms. Press Ctrl+C to stop.\n",
           LOG_FILE, SAMPLE_MS);

    while (g_running) {
        uint16_t prox = 0, als_vis = 0, als_ir = 0;

        if (read_sensor_data(g_i2c_fd, &prox, &als_vis, &als_ir) == 0) {
            log_data(g_log_fp, prox, als_vis, als_ir);
            printf("Proximity=%u  ALS_VIS=%u  ALS_IR=%u\n", prox, als_vis, als_ir);
        } else {
            fprintf(stderr, "[ERROR] Sensor read failed — continuing.\n");
        }

        /* Sleep in 100 ms increments so SIGINT is responsive */
        for (int ms = 0; ms < SAMPLE_MS && g_running; ms += 100)
            usleep(100000);
    }

    printf("\n[INFO] Shutting down cleanly.\n");
    cleanup();
    return EXIT_SUCCESS;
}

