/*
 * ICU-20201 Ultrasonic ToF Sensor Reader for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   ICU-20201 SDA -> GPIO 2 (I2C bus 1 SDA)
 *   ICU-20201 SCL -> GPIO 3 (I2C bus 1 SCL)
 *   ICU-20201 VDD -> 3.3 V
 *   ICU-20201 GND -> GND
 *   LED anode    -> GPIO 17 (BCM) via 330 Ω resistor -> GND
 *
 * Build: gcc -O2 -Wall -o tof_reader tof_reader.c -lpigpio -lrt
 * Run:   sudo ./tof_reader [threshold_mm]
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Configuration ---- */
#define I2C_BUS            1
#define ICU20201_ADDR      0x60
#define LED_GPIO           17
#define DEFAULT_THRESHOLD  100          /* mm */
#define POLL_INTERVAL_US   50000        /* 50 ms */
#define LOG_FILE           "tof_log.txt"

/* ICU-20201 register addresses */
#define REG_WHO_AM_I       0x00
#define REG_DISTANCE_LSB   0x04
#define REG_DISTANCE_MSB   0x05
#define REG_CONFIG         0x06
#define REG_RESET          0x07
#define WHO_AM_I_EXPECTED  0x20

/* ---- Globals for cleanup ---- */
static int  g_i2c_handle = -1;
static int  g_led_state  = 0;
static volatile sig_atomic_t g_running = 1;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Helpers ---- */
static void log_message(const char *msg)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(log)");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    } else {
        fprintf(fp, "[timestamp error] %s\n", msg);
    }
    fclose(fp);
}

static void set_led(int state)
{
    if (gpioWrite(LED_GPIO, state) < 0) {
        log_message("ERROR: gpioWrite(LED) failed");
    } else {
        g_led_state = state;
    }
}

/* ---- I2C helpers ---- */
static int i2c_read_reg8(int handle, uint8_t reg, uint8_t *val)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

static int i2c_write_reg8(int handle, uint8_t reg, uint8_t val)
{
    return (i2cWriteByteData(handle, reg, val) < 0) ? -1 : 0;
}

/* ---- Sensor init ---- */
static int init_sensor(int handle)
{
