#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SENSOR_ADDR    0x62
#define CMD_LEN        4
#define RESP_LEN       15
#define HEADER_BYTE    0x02
#define THRESHOLD_MM   1000
#define SAMPLES        10
#define CYCLE_DELAY_MS 100
#define MEASURE_DELAY_MS 10

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void msleep(unsigned ms) {
    struct timespec ts = { ms / 1000, (long)(ms % 1000) * 1000000L };
    nanosleep(&ts, NULL);
}

static int i2c_write_cmd(int fd, const uint8_t *cmd, size_t len) {
    if (write(fd, cmd, len) != (ssize_t)len) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_resp(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n != (ssize_t)len) {
        fprintf(stderr, "I2C read failed: expected %zu bytes, got %zd (%s)\n",
                len, n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }
    return 0;
}

static int read_distance(int fd, uint16_t *distance_mm) {
    uint8_t cmd[CMD_LEN] = { 0x01, 0x00, 0x00, 0x00 };
    uint8_t resp[RESP_LEN];

    if (i2c_write_cmd(fd, cmd, CMD_LEN) != 0)
        return -1;

    msleep(MEASURE_DELAY_MS);

    if (i2c_read_resp(fd, resp, RESP_LEN) != 0)
        return -1;

    if (resp[0] != HEADER_BYTE) {
        fprintf(stderr, "Unexpected header byte: 0x%02X (expected 0x%02X)\n",
                resp[0], HEADER_BYTE);
        return -1;
    }

    *distance_mm = ((uint16_t)resp[11] << 8) | resp[12];
    return 0;
}

static void log_intrusion(FILE *fp, int avg_mm) {
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s, %d mm\n", ts, avg_mm) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return;
    }
    fflush(fp);
}

int main(void) {
    int fd = -1;
    FILE *log_fp = NULL;
    int rc = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, SENSOR_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X failed: %s\n",
                SENSOR_ADDR, strerror(errno));
        goto cleanup;
    }

    log_fp = fopen("intrusion_log.txt", "a");
    if (!log_fp) {
        fprintf(stderr, "Cannot open intrusion_log.txt: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("Intrusion detection started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int sum = 0;
        int valid = 0;

        for (int i = 0; i < SAMPLES && g_running; i++) {
            uint16_t d;
            if (read_distance(fd, &d) == 0) {
                sum += d;
                valid++;
            }
            msleep(CYCLE_DELAY_MS);
        }

        if (valid == 0) {
            fprintf(stderr, "No valid readings in this cycle.\n");
            continue;
        }

        int avg = sum / valid;
        if (avg < THRESHOLD_MM) {
            log_intrusion(log_fp, avg);
            printf("Intrusion detected! Average distance: %d mm\n", avg);
        }
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (log_fp) fclose(log_fp);
    if (fd >= 0) close(fd);
    return rc;
}

