/*
 * Si1182 Proximity Sensor Reader for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   Si1182 SDA  -> GPIO2 (I2C bus 1 SDA)
 *   Si1182 SCL  -> GPIO3 (I2C bus 1 SCL)
 *   Si1182 VDD  -> 3.3 V
 *   Si1182 GND  -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o si1182_prox si1182_prox.c -lpigpio -lrt
 *   (pigpio requires root or gpio group membership; run with sudo if needed.)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Si1182 I2C address ---- */
#define SI1182_ADDR 0x60

/* ---- Si1182 register addresses ---- */
#define SI1182_REG_HW_KEY      0x07
#define SI1182_REG_MEAS_RATE   0x08
#define SI1182_REG_PS_RATE     0x0A
#define SI1182_REG_PS_LED21    0x0F
#define SI1182_REG_PS1_DATA0   0x10
#define SI1182_REG_PS1_DATA1   0x11
#define SI1182_REG_COMMAND     0x18

/* ---- Si1182 command codes ---- */
#define SI1182_CMD_RESET       0x01
#define SI1182_CMD_PS_FORCE    0x05
#define SI1182_CMD_PS_AUTO     0x06

/* ---- Measurement timing ---- */
#define MEAS_DELAY_US  2000   /* 2 ms between forced measurements */
#define LOOP_DELAY_US  500000 /* 500 ms between readings */

/* ---- Globals for signal handler ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to a Si1182 register. Returns 0 on success, -1 on error. */
static int si1182_write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, value, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one byte from a Si1182 register. Returns 0 on success, -1 on error. */
static int si1182_read_reg(int handle, uint8_t reg, uint8_t *out)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(reg=0x%02X) failed: %d\n", reg, rc);
        return -1;
    }
    *out = (uint8_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read the 16-bit PS1 proximity value. Returns 0 on success, -1 on error. */
static int si1182_read_proximity(int handle, uint16_t *prox)
{
    uint8_t lo, hi;

