#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MLX75030_ADDR  0x3C
#define READ_INTERVAL  500000000LL  /* 500 ms in nanoseconds */

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int i2c_open(const char *bus, uint8_t addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", bus, strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n",
                addr, strerror(errno));
        close(fd);
        return -1;
    }

    /* Probe: a zero-length write returns 0 on success, -1 on NACK. */
    if (write(fd, NULL, 0) < 0) {
        fprintf(stderr, "MLX75030 not responding at 0x%02X: %s\n",
                addr, strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

static int read_distance(int fd, uint16_t *distance_mm)
{
    uint8_t buf[2];

    ssize_t n = read(fd, buf, sizeof(buf));
    if (n < 0) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C read short: got %zd bytes, expected %zu\n",
                n, sizeof(buf));
        return -1;
    }

    /* MLX75030 16-bit distance register (big-endian). */
    *distance_mm = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

int main(void)
{
    int fd = -1;

    if (install_signal_handlers() != 0)
        return EXIT_FAILURE;

    fd = i2c_open(I2C_BUS, MLX75030_ADDR);
    if (fd < 0)
        return EXIT_FAILURE;

    struct timespec ts = { 0, READ_INTERVAL };

    while (g_running) {
        uint16_t dist;
        if (read_distance(fd, &dist) == 0) {
            printf("Distance: %u mm\n", dist);
            fflush(stdout);
        } else {
            fprintf(stderr, "Failed to read distance.\n");
        }

        /* Interruptible sleep so SIGINT/SIGTERM break the loop promptly. */
        while (nanosleep(&ts, &ts) == -1 && errno == EINTR && g_running)
            ;
    }

    if (close(fd) < 0)
        perror("close");

    return EXIT_SUCCESS;
}

