/*
 * OPT3101 Time-of-Flight sensor reader for Raspberry Pi Zero W
 *
 * Wiring:
 *   OPT3101 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   OPT3101 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   OPT3101 VDD  -> 3.3 V
 *   OPT3101 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o opt3101_reader opt3101_reader.c -lpigpio -lrt
 * Run:    sudo ./opt3101_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- OPT3101 I2C address ---- */
#define OPT3101_I2C_ADDR 0x30

/* ---- OPT3101 register addresses ---- */
#define REG_DEVICE_ID       0x00
#define REG_RESULT_DATA     0x04
#define REG_ERROR_FLAGS     0x08
#define REG_SYSTEM_CONFIG   0x0A
#define REG_CHANNEL_CONFIG  0x0C
#define REG_AFE_CONFIG      0x0E
#define REG_GPIO_CONFIG     0x10
#define REG_ADC_CONFIG      0x12
#define REG_LASER_CONFIG    0x14
#define REG_FRAME_CONFIG    0x16
#define REG_INT_CONFIG      0x18
#define REG_INT_STATUS      0x1A
#define REG_RESULT_DATA_0   0x20
#define REG_RESULT_DATA_1   0x22
#define REG_RESULT_DATA_2   0x24
#define REG_RESULT_DATA_3   0x26
#define REG_RESULT_DATA_4   0x28
#define REG_RESULT_DATA_5   0x2A
#define REG_RESULT_DATA_6   0x2C
#define REG_RESULT_DATA_7   0x2E
#define REG_RESULT_DATA_8   0x30
#define REG_RESULT_DATA_9   0x32
#define REG_RESULT_DATA_10  0x34
#define REG_RESULT_DATA_11  0x36
#define REG_RESULT_DATA_12  0x38
#define REG_RESULT_DATA_13  0x3A
#define REG_RESULT_DATA_14  0x3C
#define REG_RESULT_DATA_15  0x3E

/* ---- Expected DEVICE_ID value ---- */
#define EXPECTED_DEVICE_ID  0x3101

/* ---- Globals for signal handling ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit value to a 16-bit-addressed register.                */
/* ------------------------------------------------------------------ */
static int opt3101_write_reg16(int handle, uint16_t reg, uint16_t value)
{
    char buf[4];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (value >> 8) & 0xFF;
    buf[3] = value & 0xFF;

    if (i2cWriteDevice(handle, buf, 4) != 4) {
        fprintf(stderr, "I2C write failed at reg 0x%04X\n", reg);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit value from a 16-bit-addressed register.               */
/* ------------------------------------------------------------------ */
static int opt3101_read_reg16(int handle, uint16_t reg, uint16_t *value)
{
    char addr_buf[2];
    char data_buf[2];

    addr_buf[0] = (reg >> 8) & 0xFF;
    addr_buf[1] = reg & 0xFF;

    if (i2cWriteDevice(handle, addr_buf, 2) != 2) {
        fprintf(stderr, "I2C write (addr) failed at reg 0x%04X\n", reg);
        return -1;
    }

    if (i2cReadDevice(handle, data_buf, 2) != 2) {
        fprintf(stderr, "I2C read failed at reg 0x%04X\n", reg);
        return -1;
    }

    *value = ((uint16_t)(uint8_t)data_buf[0] << 8) | (uint8_t)data_buf[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the OPT3101 sensor.                                     */
/* ------------------------------------------------------------------ */
static int opt3101_init(int handle)
{
    uint16_t device_id = 0;

    /* Verify device identity */
    if (opt3101_read_reg16(handle, REG_DEVICE_ID, &device_id) != 0) {
        fprintf(stderr, "Cannot read DEVICE_ID - sensor may be absent or bus error\n");
        return -1;
    }

    if (device_id != EXPECTED_DEVICE_ID) {
        fprintf(stderr, "Unexpected DEVICE_ID: 0x%04X (expected 0x%04X)\n",
                device_id, EXPECTED_DEVICE_ID);
        return -1;
    }
    printf("OPT3101 detected (DEVICE_ID = 0x%04X)\n", device_id);

    /*
     * Minimal configuration for channel 0 distance measurement.
     * The exact values below are placeholders; real production code
     * should be tuned for the specific application environment.
     */
    if (opt3101_write_reg16(handle, REG_SYSTEM_CONFIG, 0x0001) != 0) return -1;
    if (opt3101_write_reg16(handle, REG_CHANNEL_CONFIG, 0x0000) != 0) return -1;
    if (opt3101_write_reg16(handle, REG_AFE_CONFIG, 0x0000) != 0) return -1;
    if (opt3101_write_reg16(handle, REG_GPIO_CONFIG, 0x0000) != 0) return -1;
    if (opt3101_write_reg16(handle, REG_ADC_CONFIG, 0x0000) != 0) return -1;
    if (opt3101_write_reg16(handle, REG_LASER_CONFIG, 0x0000) != 0) return -1;
    if (opt3101_write_reg16(handle, REG_FRAME_CONFIG, 0x0000) != 0) return -1;
    if (opt3101_write_reg16(handle, REG_INT_CONFIG, 0x0000) != 0) return -1;

    return 0;
}

