#define REG_RESULT_DATA_1   0x22
#define REG_RESULT_DATA_2   0x24
#define REG_RESULT_DATA_3   0x26
#define REG_RESULT_DATA_4   0x28
#define REG_RESULT_DATA_5   0x2A
#define REG_RESULT_DATA_6   0x2C
#define REG_RESULT_DATA_7   0x2E
#define REG_RESULT_DATA_8   0x30
#define REG_RESULT_DATA_9   0x32
#define REG_RESULT_DATA_10  0x34
