/*
 * HC-SR04 ultrasonic distance measurement on Raspberry Pi 3 Model B+.
 *
 * Wiring:
 *   VCC  -> 5V  (pin 2 or 4)
 *   GND  -> GND (pin 6)
 *   TRIG -> GPIO17 (pin 11)
 *   ECHO -> GPIO18 (pin 12) via 1 kOhm series resistor (HC-SR04 echo
 *                  output is 5 V; the Pi GPIO is 3.3 V tolerant).
 *
 * NOTE: The HC-SR04 echo pin is 5 V and the Pi GPIO is 3.3 V tolerant.
 *       A 1 kOhm series resistor is required to prevent damage to the
 *       Pi GPIO controller.
 *
 * Build:  gcc -O2 -Wall -Wextra -o hcsr04 hcsr04.c -lpigpio -lrt
 * Run:    sudo ./hcsr04
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN      17
#define ECHO_PIN         18

#define TRIGGER_PULSE_US 10          /* 10 µs trigger pulse            */
#define ECHO_TIMEOUT_US  200000      /* 200 ms max echo wait           */
#define SAMPLE_PERIOD_S  1           /* 1 second between readings      */
#define MAX_RANGE_CM     400.0       /* HC-SR04 max range (cm)         */
#define MIN_RANGE_CM     2.0         /* HC-SR04 min range (cm)         */
#define SPEED_OF_SOUND   34300.0     /* cm/s at ~20 °C                 */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */
static void print_timestamp(void)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char buf[32];

    if (localtime_r(&now, &tm_info) != NULL &&
        strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", &tm_info) > 0) {
        printf("[%s] ", buf);
    }
}

static void log_distance(float distance_cm)
{
    print_timestamp();
    printf("Distance: %.2f cm\n", distance_cm);
    fflush(stdout);
}

static void log_error(const char *msg)
{
    print_timestamp();
    fprintf(stderr, "Error: %s\n", msg);
    fflush(stderr);
}

/* ------------------------------------------------------------------ */
/* HC-SR04 measurement                                                 */
/* ------------------------------------------------------------------ */
/*
 * Returns:
 *   > 0  distance in cm (valid)
 *   -1.0 echo timeout (no object detected / sensor absent)
 *   -2.0 invalid pulse duration (≤ 0 µs or > 38 ms)
 */
static float measure_distance(void)
{
    uint32_t start_tick = 0, end_tick = 0;
    uint32_t elapsed;
    int      rc;

    /* --- Issue 10 µs trigger pulse --- */
    rc = gpioTrigger(TRIGGER_PIN, TRIGGER_PULSE_US, 1);
    if (rc < 0) {
        log_error("gpioTrigger failed");
        return -2.0;
    }

    /* --- Wait for echo rising edge (timeout 200 ms) --- */
    elapsed = 0;
    while (elapsed < ECHO_TIMEOUT_US) {
        rc = gpioRead(ECHO_PIN);
        if (rc < 0) {
            log_error("gpioRead failed on echo pin");
            return -2.0;
        }
        if (rc == 1) {
            start_tick = gpioTick();
            break;
        }
        gpioDelay(100);          /* 100 µs granularity */
        elapsed += 100;
    }
    if (elapsed >= ECHO_TIMEOUT_US) {
        log_error("Echo rising edge timeout (no object / sensor absent)");
        return -1.0;
    }

    /* --- Wait for echo falling edge (timeout 200 ms) --- */
    elapsed = 0;
    while (elapsed < ECHO_TIMEOUT_US) {
        rc = gpioRead(ECHO_PIN);
        if (rc < 0) {
            log_error("gpioRead failed on echo pin");
            return -2.0;
        }
        if (rc == 0) {
            end_tick = gpioTick();
            break;
        }
        gpioDelay(100);
        elapsed += 100;
    }
    if (elapsed >= ECHO_TIMEOUT_US) {
        log_error("Echo falling edge timeout");
        return -1.0;
    }

    /* --- Compute pulse width --- */
    uint32_t pulse_us = end_tick - start_tick;
    if (pulse_us == 0 || pulse_us > 38000) {   /* 38 ms ≈ 400 cm */
        log_error("Invalid pulse duration (out of range)");
        return -2.0;
    }

    /* distance = (pulse_us * speed_of_sound) / 2 / 1e6 */
    return (float)pulse_us * SPEED_OF_SOUND / 2000000.0f;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO pins --- */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        log_error("Failed to set trigger pin mode");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        log_error("Failed to set echo pin mode");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts LOW */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        log_error("Failed to initialize trigger pin state");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioDelay(50000);            /* 50 ms settle */

    /* --- Install signal handlers --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 ||
        sigaction(SIGTERM, &sa, NULL) != 0) {
        log_error("Failed to install signal handlers");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance measurement started.\n");
    printf("Trigger: GPIO%d | Echo: GPIO%d | Sample period: %d s\n",
           TRIGGER_PIN, ECHO_PIN, SAMPLE_PERIOD_S);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* --- Main loop --- */
    while (g_running) {
        float distance = measure_distance();

        if (distance > 0.0f) {
            if (distance >= MIN_RANGE_CM && distance <= MAX_RANGE_CM) {
                log_distance(distance);
            } else {
                log_error("Distance out of valid range (2–400 cm)");
            }
        } else if (distance == -1.0f) {
            log_error("Sensor timeout — no object detected or sensor absent");
        } else {
            /* distance == -2.0f: invalid pulse duration */
            log_error("Invalid pulse duration");
        }

        /* Sleep for the remainder of the sample period */
        sleep(SAMPLE_PERIOD_S);
    }

    /* --- Graceful shutdown --- */
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

