#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <errno.h>
#include <sys/select.h>
#include <pigpio.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE B115200
#define GPIO_ALERT 17
#define DISTANCE_THRESHOLD 1.0f
#define MAX_RANGE_BINS 64
#define RANGE_BIN_SIZE 2
#define MAGIC_WORD_SIZE 8
#define FRAME_HEADER_SIZE 8
#define FRAME_DATA_SIZE (MAX_RANGE_BINS * RANGE_BIN_SIZE)
#define FRAME_SIZE (FRAME_HEADER_SIZE + FRAME_DATA_SIZE)
#define LOG_FILE "intrusion_log.csv"
#define POLL_TIMEOUT_SEC 1

static volatile sig_atomic_t running = 1;
static int uart_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_uart(const char *device, speed_t baud) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd < 0) {
        perror("Error opening UART");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, baud);
    cfsetispeed(&tty, baud);

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_cflag &= ~(PARENB | PARODD);
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;
    tty.c_cflag |= CREAD | CLOCAL;

    tty.c_iflag &= ~(IXON | IXOFF | IXANY);
    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL);

    tty.c_lflag = 0;
    tty.c_oflag = 0;

    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 10;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

static int read_exact(int fd, uint8_t *buf, size_t len) {
    size_t total = 0;
    while (total < len) {
        ssize_t n = read(fd, buf + total, len - total);
        if (n < 0) {
            if (errno == EINTR) continue;
            perror("Error reading from UART");
            return -1;
        }
        if (n == 0) return 0;
        total += (size_t)n;
    }
    return 1;
}

static int detect_intrusion(const uint8_t *data, size_t len) {
    if (len < FRAME_DATA_SIZE) return 0;
    for (int i = 0; i < MAX_RANGE_BINS; i++) {
        uint16_t val = (uint16_t)data[i * RANGE_BIN_SIZE] | ((uint16_t)data[i * RANGE_BIN_SIZE + 1] << 8);
        float distance = (float)val * 0.0436f;
        if (distance < DISTANCE_THRESHOLD) return 1;
    }
    return 0;
}

static void log_intrusion(float distance) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    if (log_file) {
        fprintf(log_file, "%s,%.2f\n", timestamp, distance);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file not open.\n");
    }
}

static void cleanup(void) {
    if (uart_fd >= 0) {
        close(uart_fd);
        uart_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(GPIO_ALERT, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    gpioSetMode(GPIO_ALERT, PI_OUTPUT);
    gpioWrite(GPIO_ALERT, 0);

    uart_fd = init_uart(UART_DEVICE, BAUD_RATE);
    if (uart_fd < 0) {
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        close(uart_fd);
        gpioTerminate();
        return 1;
    }

    uint8_t frame[FRAME_SIZE];
    uint8_t header[MAGIC_WORD_SIZE];

    printf("Intrusion detection system started. Press Ctrl+C to exit.\n");

    while (running) {
        fd_set readfds;
        FD_ZERO(&readfds);
        FD_SET(uart_fd, &readfds);

        struct timeval tv = { .tv_sec = POLL_TIMEOUT_SEC, .tv_usec = 0 };

        int sel = select(uart_fd + 1, &readfds, NULL, NULL, &tv);
        if (sel < 0) {
            if (errno == EINTR) continue;
            perror("select() error");
            break;
        }
        if (sel == 0) continue;

        if (!FD_ISSET(uart_fd, &readfds)) continue;

        if (read_exact(uart_fd, header, MAGIC_WORD_SIZE) <= 0) {
            fprintf(stderr, "Error reading magic word. Re-initializing UART.\n");
            close(uart_fd);
            uart_fd = init_uart(UART_DEVICE, BAUD_RATE);
            if (uart_fd < 0) {
                fprintf(stderr, "UART re-init failed. Exiting.\n");
                break;
            }
            continue;
        }

        if (read_exact(uart_fd, frame, FRAME_DATA_SIZE) <= 0) {
            fprintf(stderr, "Error reading frame data. Re-initializing UART.\n");
            close(uart_fd);
            uart_fd = init_uart(UART_DEVICE, BAUD_RATE);
            if (uart_fd < 0) {
                fprintf(stderr, "UART re-init failed. Exiting.\n");
                break;
            }
            continue;
        }

        if (detect_intrusion(frame, FRAME_DATA_SIZE)) {
            uint16_t val = (uint16_t)frame[0] | ((uint16_t)frame[1] << 8);
            float distance = (float)val * 0.0436f;
            log_intrusion(distance);
            printf("Intrusion detected! Distance: %.2f meters\n", distance);
            gpioWrite(GPIO_ALERT, 1);
            gpioDelay(2000000);
            gpioWrite(GPIO_ALERT, 0);
        }
    }

    cleanup();
    printf("Intrusion detection system stopped.\n");
    return 0;
}

