/*
 * Raspberry Pi 4 Model B – TDK Chirp ICU-20201 Ultrasonic ToF Sensor
 *
 * Reads distance from the ICU-20201 over I2C bus 1, logs each reading with
 * an ISO-8601 timestamp to distance_log.txt, and asserts a GPIO alert on
 * BCM 17 when distance falls below 10.0 cm.
 *
 * Build:  gcc -O2 -Wall -Wextra -o icu20201_monitor icu20201_monitor.c \
 *             -lpigpio -lrt
 * Run:    sudo ./icu20201_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS            1
#define I2C_ADDR           0x44          /* ICU-20201 default I2C address      */
#define GPIO_ALERT_PIN     17            /* BCM 17 – active-high alert output  */
#define DISTANCE_THRESHOLD 10.0f         /* cm                                 */
#define LOG_FILE           "distance_log.txt"
#define POLL_INTERVAL_US   100000        /* 100 ms                            */
#define MAX_RETRIES        3

/* ICU-20201 register map (16-bit registers, big-endian on the bus) */
#define REG_PRODUCT_ID     0x0000
#define REG_DISTANCE       0x0002        /* 16-bit, units = 0.01 cm            */
#define REG_ERROR_STATUS   0x0004
#define REG_MEASUREMENT_CFG 0x0006

#define EXPECTED_PRODUCT_ID 0x2020       /* ICU-20201 16-bit product ID        */

/* ----------------------------- Globals ---------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ----------------------------- Prototypes -------------------------------- */
static void signal_handler(int sig);
static int  init_i2c(void);
static int  init_gpio(void);
static int  read_register16(uint16_t reg, uint16_t *out);
static int  write_register16(uint16_t reg, uint16_t value);
static int  read_distance(float *distance_cm);
static int  log_distance(float distance_cm);
static void trigger_alert(float distance_cm);
static void cleanup(void);

/* ----------------------------- Signal handler ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- I2C init ---------------------------------- */
static int init_i2c(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        return -1;
    }

    /* Verify sensor presence by reading the product ID register */
    uint16_t product_id = 0;
    if (read_register16(REG_PRODUCT_ID, &product_id) != 0) {
        fprintf(stderr, "[ERROR] Cannot read product ID – sensor absent or bus error.\n");
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        return -1;
    }

    if (product_id != EXPECTED_PRODUCT_ID) {
        fprintf(stderr, "[ERROR] Unexpected product ID 0x%04X (expected 0x%04X).\n",
                product_id, EXPECTED_PRODUCT_ID);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        return -1;
    }

    printf("[INFO] ICU-20201 detected (product ID 0x%04X) on I2C bus %d, addr 0x%02X.\n",
           product_id, I2C_BUS, I2C_ADDR);
    return 0;
}

/* ----------------------------- GPIO init --------------------------------- */
static int init_gpio(void)
{
    if (gpioSetMode(GPIO_ALERT_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "[ERROR] gpioSetMode(%d, PI_OUTPUT) failed.\n", GPIO_ALERT_PIN);
        return -1;
    }
    if (gpioWrite(GPIO_ALERT_PIN, 0) != 0) {
        fprintf(stderr, "[ERROR] gpioWrite(%d, 0) failed.\n", GPIO_ALERT_PIN);
        return -1;
    }
    return 0;
}

/* ----------------------------- Register helpers -------------------------- */
static int read_register16(uint16_t reg, uint16_t *out)
{
    char buf[2];
    int  rc;

    rc = i2cReadI2CBlockData(g_i2c_handle, reg, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "[ERROR] i2cReadI2CBlockData(reg=0x%04X) returned %d.\n", reg, rc);
        return -1;
    }

    /* ICU-20201 sends MSB first */
    *out = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

static int write_register16(uint16_t reg, uint16_t value)
{
    char buf[2];
    buf[0] = (char)((value >> 8) & 0xFF);
    buf[1] = (char)(value & 0xFF);

    int rc = i2cWriteI2CBlockData(g_i2c_handle, reg, buf, 2);
    if (rc != 0) {
        fprintf(stderr, "[ERROR] i2cWriteI2CBlockData(reg=0x%04X) returned %d.\n", reg, rc);
        return -1;
    }
    return 0;
}

/* ----------------------------- Distance read ----------------------------- */
static int read_distance(float *distance_cm)
{
    uint16_t raw = 0;
    if (read_register16(REG_DISTANCE, &raw) != 0)
        return -1;

    /* 16-bit register, units = 0.01 cm */
    *distance_cm = (float)raw / 100.0f;
    return 0;
}

/* ----------------------------- Logging ----------------------------------- */
static int log_distance(float distance_cm)
{
    time_t     rawtime;
    struct tm  tm_info;
    char       timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &tm_info) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r() failed.\n");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "[ERROR] strftime() failed.\n");
        return -1;
    }

    if (fprintf(g_log_file, "%s,%.2f\n", timestamp, distance_cm) < 0) {
        fprintf(stderr, "[ERROR] fprintf() to log file failed.\n");
        return -1;
    }

    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "[ERROR] fflush() on log file failed.\n");
        return -1;
    }
    return 0;
}

/* ----------------------------- Alert ------------------------------------- */
static void trigger_alert(float distance_cm)
{
    printf("[ALERT] Distance %.2f cm < %.1f cm – GPIO %d HIGH\n",
           distance_cm, DISTANCE_THRESHOLD, GPIO_ALERT_PIN);
    if (gpioWrite(GPIO_ALERT_PIN, 1) != 0) {
        fprintf(stderr, "[ERROR] gpioWrite(%d, 1) failed.\n", GPIO_ALERT_PIN);
    }
}

/* ----------------------------- Cleanup ----------------------------------- */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    /* Ensure GPIO is left low before terminating pigpio */
    gpioWrite(GPIO_ALERT_PIN, 0);
    gpioTerminate();
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("[ERROR] sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[ERROR] sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "[ERROR] gpioInitialise() failed.\n");
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("[ERROR] fopen(" LOG_FILE ")");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure measurement: enable continuous mode (0x0001) */
    if (write_register16(REG_MEASUREMENT_CFG, 0x0001) != 0) {
        fprintf(stderr, "[ERROR] Failed to configure measurement mode.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("[INFO] Monitoring distance (threshold %.1f cm). Press Ctrl+C to exit.\n",
           DISTANCE_THRESHOLD);

    while (g_running) {
        float distance_cm = 0.0f;

        if (read_distance(&distance_cm) != 0) {
            fprintf(stderr, "[WARN] Distance read failed; retrying in 100 ms.\n");
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        if (log_distance(distance_cm) != 0) {
            fprintf(stderr, "[WARN] Logging failed; continuing.\n");
        }

        if (distance_cm < DISTANCE_THRESHOLD) {
            trigger_alert(distance_cm);
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\n[INFO] Shutting down cleanly.\n");
    cleanup();
    return EXIT_SUCCESS;
}

