/*
 * Parking Assistance System using VL53L1X ToF Sensor
 * Board:  Raspberry Pi 3 Model B+
 * Bus:    I2C bus 1 (GPIO2=SDA, GPIO3=SCL)
 * Sensor: STMicroelectronics VL53L1X
 *
 * Build:  gcc -O2 -Wall -Wextra -o parking_assist parking_assist.c -lpigpio -lrt
 * Run:    sudo ./parking_assist
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS          1
#define VL53L1X_ADDR     0x29
#define LOG_FILE         "distance_log.csv"
#define POLL_DELAY_US    100000   /* 100 ms */
#define MAX_DISTANCE_MM  1200     /* SLOW threshold */

/* VL53L1X 16-bit register addresses (pigpio uses 16-bit handles) */
#define VL53L1X_REG_SOFT_RESET       0x0000
#define VL53L1X_REG_VHV_CONFIG       0x0001
#define VL53L1X_REG_PHASECAL         0x0002
#define VL53L1X_REG_RANGE_CONFIG     0x0003
#define VL53L1X_REG_INTERMEASUREMENT 0x0004
#define VL53L1X_REG_SYSTEM_THRESH    0x0005
#define VL53L1X_REG_SYSTEM_CONFIG    0x0006
#define VL53L1X_REG_GPIO_HV_MUX      0x0007
#define VL53L1X_REG_GPIO_TIO_HV      0x0008
#define VL53L1X_REG_SYSTEM_INTERRUPT 0x0009
#define VL53L1X_REG_RESULT_RANGE     0x000A
#define VL53L1X_REG_RESULT_INTERRUPT 0x000B
#define VL53L1X_REG_RESULT_STATUS    0x000C
#define VL53L1X_REG_RESULT_DISTANCE  0x000D

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Low-level I2C helpers                                               */
/* ------------------------------------------------------------------ */
static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (char)value;
    return i2cWriteDevice(handle, buf, 3);
}

static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *buf, uint8_t len)
{
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;

    if (i2cWriteDevice(handle, reg_buf, 2) < 0)
        return -1;
    return i2cReadDevice(handle, (char *)buf, len);
}

/* ------------------------------------------------------------------ */
/* VL53L1X driver                                                      */
/* ------------------------------------------------------------------ */
static int vl53l1x_init(int handle)
{
    /* Soft reset */
    if (i2c_write_reg16(handle, VL53L1X_REG_SOFT_RESET, 0x00) < 0)
        return -1;
    gpioDelay(1000); /* 1 ms */
    if (i2c_write_reg16(handle, VL53L1X_REG_SOFT_RESET, 0x01) < 0)
        return -1;
    gpioDelay(1000); /* 1 ms */

    /* Minimal configuration for single-shot ranging */
    if (i2c_write_reg16(handle, VL53L1X_REG_VHV_CONFIG,     0x01) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_PHASECAL,      0x01) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_RANGE_CONFIG,   0x01) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_INTERMEASUREMENT, 0x01) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_THRESH,  0x01) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_CONFIG,  0x01) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_GPIO_HV_MUX,    0x01) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_GPIO_TIO_HV,    0x01) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_INTERRUPT, 0x01) < 0) return -1;

    return 0;
}

static int vl53l1x_read_distance(int handle, uint16_t *distance_mm)
{
    uint8_t status = 0;
    uint8_t data[2] = {0, 0};

    /* Start a single measurement */
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_CONFIG, 0x01) < 0)
        return -1;

    /* Poll for data ready (bit 0 of RESULT_STATUS) */
    for (int i = 0; i < 50; i++) {
        if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_STATUS, &status, 1) < 0)
            return -1;
        if (status & 0x01)
            break;
        gpioDelay(2000); /* 2 ms */
        if (i == 49)
            return -2; /* timeout */
    }

    /* Read 2-byte distance */
    if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_DISTANCE, data, 2) < 0)
        return -1;

    *distance_mm = ((uint16_t)data[0] << 8) | data[1];

    /* Clear interrupt */
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_INTERRUPT, 0x01) < 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_distance(FILE *fp, uint16_t distance_mm)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL)
        return -1;

    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0)
        return -1;

    if (fprintf(fp, "%s,%u\n", ts, distance_mm) < 0)
        return -1;

    if (fflush(fp) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Parking guidance                                                    */
/* ------------------------------------------------------------------ */
static void parking_assistance(uint16_t distance_mm)
{
    if (distance_mm < 300)
        printf("STOP\n");
    else if (distance_mm < 600)
        printf("APPROACH\n");
    else if (distance_mm < MAX_DISTANCE_MM)
        printf("SLOW\n");
    else
        printf("CLEAR\n");
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
