    for (int i = 0; i < 50; i++) {
        if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_STATUS, &status, 1) < 0)
            return -1;
        if (status & 0x01)
            break;
        gpioDelay(2000); /* 2 ms */
        if (i == 49)
