code:
/*
 * CH201 Ultrasonic ToF Distance Sensor - Raspberry Pi 4 Model B
 *
 * Reads distance from a TDK InvenSense CH201 sensor on I2C bus 1 (GPIO 2/3),
 * blinks an LED on GPIO 18 faster as distance decreases, and logs data.
 *
 * Wiring:
 *   CH201 SDA -> GPIO 2 (I2C bus 1 SDA)
 *   CH201 SCL -> GPIO 3 (I2C bus 1 SCL)
 *   CH201 VDD -> 3.3 V
 *   CH201 GND -> GND
 *   LED anode -> GPIO 18 (BCM) via 330 ohm resistor -> GND
 *
 * Build: gcc -O2 -Wall -o ch201_blink ch201_blink.c -lpigpio -lrt
 * Run:   sudo ./ch201_blink
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS            1
#define I2C_ADDR           0x44   /* CH201 default I2C address (7-bit) */
#define LED_GPIO           18
#define SAMPLE_PERIOD_US   100000 /* 100 ms between samples */
#define BLINK_HALF_CYCLE_US 5000 /* 5 ms half-cycle => 200 Hz blink */
#define MAX_RETRIES        3
#define RETRY_DELAY_US     10000 /* 10 ms between retries */

/* CH201 register addresses (16-bit, big-endian on the bus) */
#define CH201_REG_DIST_MSB  0x02
#define CH201_REG_DIST_LSB  0x03
#define CH201_REG_STATUS    0x04
#define CH201_REG_CONFIG    0x05

/* Status register bit 0: data ready */
#define CH201_STATUS_READY  0x01

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static bool g_pigpio_inited = false;

/* ----------------------------- Prototypes -------------------------------- */
static int  init_pigpio(void);
static int  init_i2c(void);
static int  read_distance(uint16_t *distance);
static void blink_led(uint16_t distance);
static void log_data(uint16_t distance);
static void cleanup(void);
static void signal_handler(int sig);

/* ----------------------------- Implementation ----------------------------- */

static int init_pigpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }
    g_pigpio_inited = true;
    return 0;
}

static int init_i2c(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed on bus %d addr 0x%02X (pigpio error %d).\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        return -1;
    }

    /* Quick presence check: try a zero-length write to the status register */
    if (i2cWriteByteData(g_i2c_handle, CH201_REG_STATUS, 0) < 0) {
        fprintf(stderr, "Error: CH201 not responding at 0x%02X.\n", I2C_ADDR);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        return -1;
    }

    /* Configure: enable continuous measurement (example config value) */
    if (i2cWriteByteData(g_i2c_handle, CH201_REG_CONFIG, 0x01) < 0) {
        fprintf(stderr, "Error: failed to write CH201 config register.\n");
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        return -1;
    }

    return 0;
}

/*
 * Read 16-bit distance from CH201.
 * Returns 0 on success, -1 on failure.
 */
static int read_distance(uint16_t *distance)
{
    char buf[2];
    int  rc;

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        /* Poll status register to check data-ready flag */
        rc = i2cReadByteData(g_i2c_handle, CH201_REG_STATUS);
        if (rc < 0) {
            fprintf(stderr, "Warning: status read failed (attempt %d/%d).\n",
                    attempt + 1, MAX_RETRIES);
            gpioDelay(RETRY_DELAY_US);
            continue;
        }
        if (!(rc & CH201_STATUS_READY)) {
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        /* Read 2 bytes: MSB at 0x02, LSB at 0x03 */
        rc = i2cReadI2CBlockData(g_i2c_handle, CH201_REG_DIST_MSB, buf, 2);
        if (rc == 2) {
            *distance = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
            return 0;
        }

        fprintf(stderr, "Warning: block read failed (attempt %d/%d, rc=%d).\n",
                attempt + 1, MAX_RETRIES, rc);
        gpioDelay(RETRY_DELAY_US);
    }

    fprintf(stderr, "Error: distance read failed after %d retries.\n", MAX_RETRIES);
    return -1;
}

/*
 * Blink the LED for one half-cycle proportional to distance.
 * Shorter distance => faster blink => more on-time.
 * distance 0 -> 0% on-time, distance 400 -> 100% on-time.
 */
static void blink_led(uint16_t distance)
{
    if (distance == 0) {
        gpioWrite(LED_GPIO, 1);
        gpioDelay(BLINK_HALF_CYCLE_US);
        gpioWrite(LED_GPIO, 0);
        return;
    }

    /* Map distance [0..400] to on-time [0..BLINK_HALF_CYCLE_US] */
    int on_us = (int)(((float)distance / 400.0f) * BLINK_HALF_CYCLE_US);
    if (on_us < 0)   on_us = 0;
    if (on_us > BLINK_HALF_CYCLE_US) on_us = BLINK_HALF_CYCLE_US;

    gpioWrite(LED_GPIO, 1);
    gpioDelay(on_us);
    gpioWrite(LED_GPIO, 0);
    gpioDelay(BLINK_HALF_CYCLE_US - on_us);
}

static void log_data(uint16_t distance)
{
    time_t     rawtime;
    struct tm  timeinfo;
    char       timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    float freq = (distance == 0) ? 0.0f : (400.0f / (float)distance);
    printf("[%s] Distance: %u mm  |  LED blink freq: %.1f Hz\n",
           timestamp, distance, freq);
    fflush(stdout);
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_pigpio_inited) {
        gpioWrite(LED_GPIO, 0);
        gpioTerminate();
        g_pigpio_inited = false;
    }
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (init_pigpio() != 0) {
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", LED_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    if (init_i2c() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("CH201 distance sensor running. Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (g_running) {
        uint16_t distance = 0;

        if (read_distance(&distance) == 0) {
            blink_led(distance);
            log_data(distance);
        } else {
            /* Sensor read failed: ensure LED is off for safety */
            gpioWrite(LED_GPIO, 0);
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

