#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 27
#define DEBOUNCE_DELAY_US 50000  /* 50 ms in microseconds */
#define POLL_DELAY_US 10000      /* 10 ms in microseconds */
#define LOG_FILE_NAME "proximity_log.txt"

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

/* Signal handler for graceful shutdown */
static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

/* Get current UTC time as an ISO 8601 string */
static int get_iso8601_timestamp(char *buf, size_t buf_size) {
    time_t rawtime;
    struct tm timeinfo;

    if (time(&rawtime) == (time_t)-1) {
        return -1;
    }
    if (gmtime_r(&rawtime, &timeinfo) == NULL) {
        return -1;
    }
    if (strftime(buf, buf_size, "%Y-%m-%dT%H:%M:%SZ", &timeinfo) == 0) {
        return -1;
    }
    return 0;
}

/* Log a proximity event to the file */
static int log_proximity_event(int sensor_id, const char *event_type) {
    char timestamp[32];

    if (get_iso8601_timestamp(timestamp, sizeof(timestamp)) != 0) {
        fprintf(stderr, "Error: Failed to generate timestamp.\n");
        return -1;
    }

    if (fprintf(log_file, "%s - Sensor %d - %s\n", timestamp, sensor_id, event_type) < 0) {
        fprintf(stderr, "Error: Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error: Failed to flush log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* Read a sensor value with error checking */
static int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error: Failed to read GPIO %d: %s\n", gpio_pin, pigpio_error(value));
        return -1;
    }
    return value;
}

int main(void) {
    int prev_state1 = -1, prev_state2 = -1;
    int ret;

    /* Register signal handlers for graceful shutdown */
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error: Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (signal(SIGTERM, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error: Failed to register SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    ret = gpioInitialise();
    if (ret < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed: %s\n", pigpio_error(ret));
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen(LOG_FILE_NAME, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s': %s\n", LOG_FILE_NAME, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set GPIO pins as inputs */
    if (gpioSetMode(SENSOR_1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as input\n", SENSOR_1_GPIO);
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR_2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as input\n", SENSOR_2_GPIO);
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Proximity detection started. Press Ctrl+C to exit.\n");

    /* Main polling loop */
    while (program_running) {
        int sensor1_value = read_sensor(SENSOR_1_GPIO);
        int sensor2_value = read_sensor(SENSOR_2_GPIO);

        if (sensor1_value < 0 || sensor2_value < 0) {
            fprintf(stderr, "Error: Sensor read failure, exiting.\n");
            break;
        }

        /* Sensor 1: HIGH (1) -> LOW (0) transition = obstacle detected */
        if (sensor1_value == 0 && prev_state1 == 1) {
            if (log_proximity_event(1, "DETECTED") != 0) {
                fprintf(stderr, "Error: Failed to log event for sensor 1.\n");
            }
        }
        /* Sensor 1: LOW (0) -> HIGH (1) transition = obstacle cleared */
        else if (sensor1_value == 1 && prev_state1 == 0) {
            if (log_proximity_event(1, "CLEARED") != 0) {
                fprintf(stderr, "Error: Failed to log event for sensor 1.\n");
            }
        }
        prev_state1 = sensor1_value;

        /* Sensor 2: HIGH (1) -> LOW (0) transition = obstacle detected */
        if (sensor2_value == 0 && prev_state2 == 1) {
            if (log_proximity_event(2, "DETECTED") != 0) {
                fprintf(stderr, "Error: Failed to log event for sensor 2.\n");
            }
        }
        /* Sensor 2: LOW (0) -> HIGH (1) transition = obstacle cleared */
        else if (sensor2_value == 1 && prev_state2 == 0) {
            if (log_proximity_event(2, "CLEARED") != 0) {
                fprintf(stderr, "Error: Failed to log event for sensor 2.\n");
            }
        }
        prev_state2 = sensor2_value;

        gpioDelay(DEBOUNCE_DELAY_US);
    }

    /* Clean up resources */
    printf("\nCleaning up and exiting...\n");
    if (log_file != NULL) {
        if (fclose(log_file) != 0) {
            fprintf(stderr, "Error: Failed to close log file: %s\n", strerror(errno));
        }
        log_file = NULL;
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

