    ret = gpioInitialise();
    if (ret < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed: %s\n", pigpio_error(ret));
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen(LOG_FILE_NAME, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s': %s\n", LOG_FILE_NAME, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set GPIO pins as inputs */
    if (gpioSetMode(SENSOR_1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as input\n", SENSOR_1_GPIO);
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR_2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as input\n", SENSOR_2_GPIO);
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Proximity detection started. Press Ctrl+C to exit.\n");

    /* Main polling loop */
    while (program_running) {
        int sensor1_value = read_sensor(SENSOR_1_GPIO);
        int sensor2_value = read_sensor(SENSOR_2_GPIO);

        if (sensor1_value < 0 || sensor2_value < 0) {
            fprintf(stderr, "Error: Sensor read failure, exiting.\n");
            break;
        }

        /* Sensor 1: HIGH (1) -> LOW (0) transition = obstacle detected */
        if (sensor1_value == 0 && prev_state1 == 1) {
            if (log_proximity_event(1, "DETECTED") != 0) {
                fprintf(stderr, "Error: Failed to log event for sensor 1.\n");
            }
        }
        /* Sensor 1: LOW (0) -> HIGH (1) transition = obstacle cleared */
        else if (sensor1_value == 1 && prev_state1 == 0) {
            if (log_proximity_event(1, "CLEARED") != 0) {
                fprintf(stderr, "Error: Failed to log event for sensor 1.\n");
            }
        }
        prev_state1 = sensor1_value;

        /* Sensor 2: HIGH (1) -> LOW (0) transition = obstacle detected */
        if (sensor2_value == 0 && prev_state2 == 1) {
            if (log_proximity_event(2, "DETECTED") != 0) {
                fprintf(stderr, "Error: Failed to log event for sensor 2.\n");
            }
        }
        /* Sensor 2: LOW (0) -> HIGH (1) transition = obstacle cleared */
        else if (sensor2_value == 1 && prev_state2 == 0) {
            if (log_proximity_event(2, "CLEARED") != 0) {
                fprintf(stderr, "Error: Failed to log event for sensor 2.\n");
            }
        }
        prev_state2 = sensor2_value;

        gpioDelay(DEBOUNCE_DELAY_US);
    }

    /* Clean up resources */
    printf("\nCleaning up and exiting...\n");
    if (log_file != NULL) {
        if (fclose(log_file) != 0) {
            fprintf(stderr, "Error: Failed to close log file: %s\n", strerror(errno));
        }
        log_file = NULL;
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

