/*
 * MLX75030 Time-of-Flight distance reader for Raspberry Pi Zero W
 *
 * Wiring:
 *   MLX75030 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   MLX75030 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   MLX75030 VDD  -> 3.3 V
 *   MLX75030 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o mlx75030 mlx75030.c -lpigpio -lrt
 * Run:    sudo ./mlx75030
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x50          /* MLX75030 default 7-bit I2C address */
#define SAMPLE_PERIOD  100000        /* 100 ms in microseconds */
#define MAX_RETRIES    3
#define RETRY_DELAY_US 10000         /* 10 ms between retries */

/*
 * MLX75030 register map (16-bit addresses, big-endian on the bus).
 * The distance register is typically 16-bit and holds the raw
 * ToF measurement in units of the sensor's internal clock ticks.
 */
#define REG_DISTANCE   0x0004
#define REG_STATUS     0x0002

#define STATUS_READY   0x0001        /* bit 0: new data ready */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit value to a 16-bit-addressed register.                */
static int reg_write16(int handle, uint16_t reg, uint16_t value)
{
    char buf[4];
    buf[0] = (char)(reg >> 8);
    buf[1] = (char)(reg & 0xFF);
    buf[2] = (char)(value >> 8);
    buf[3] = (char)(value & 0xFF);

    if (i2cWriteDevice(handle, buf, 4) != 4) {
        fprintf(stderr, "[ERROR] i2cWriteDevice to reg 0x%04X failed\n", reg);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit value from a 16-bit-addressed register.               */
static int reg_read16(int handle, uint16_t reg, uint16_t *out)
{
    char addr_buf[2];
    char data_buf[2];

    addr_buf[0] = (char)(reg >> 8);
    addr_buf[1] = (char)(reg & 0xFF);

    if (i2cWriteDevice(handle, addr_buf, 2) != 2) {
        fprintf(stderr, "[ERROR] i2cWriteDevice (addr) for reg 0x%04X failed\n", reg);
        return -1;
    }

    if (i2cReadDevice(handle, data_buf, 2) != 2) {
        fprintf(stderr, "[ERROR] i2cReadDevice from reg 0x%04X failed\n", reg);
        return -1;
    }

    *out = ((uint16_t)(uint8_t)data_buf[0] << 8) | (uint8_t)data_buf[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read distance with retry logic.                                     */
static int read_distance(int handle, uint16_t *distance)
{
    for (int attempt = 1; attempt <= MAX_RETRIES; ++attempt) {
        uint16_t status = 0;
        if (reg_read16(handle, REG_STATUS, &status) != 0) {
            fprintf(stderr, "[WARN] Status read failed (attempt %d/%d)\n",
                    attempt, MAX_RETRIES);
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        if ((status & STATUS_READY) == 0) {
            fprintf(stderr, "[WARN] Data not ready (status=0x%04X, attempt %d/%d)\n",
                    status, attempt, MAX_RETRIES);
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        if (reg_read16(handle, REG_DISTANCE, distance) != 0) {
            fprintf(stderr, "[WARN] Distance read failed (attempt %d/%d)\n",
                    attempt, MAX_RETRIES);
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        return 0;                 /* success */
    }

    fprintf(stderr, "[ERROR] Distance read failed after %d attempts\n", MAX_RETRIES);
    return -1;
}

/* ------------------------------------------------------------------ */
static void log_distance(uint16_t distance)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("[ERROR] clock_gettime");
        return;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char time_buf[32];
    strftime(time_buf, sizeof(time_buf), "%Y-%m-%d %H:%M:%S", &tm_info);

    printf("%s.%03ld  Distance: %u\n",
           time_buf, ts.tv_nsec / 1000000L, (unsigned)distance);
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Initialize pigpio ------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus ----------------------------------------------- */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers ----------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("[WARN] sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[WARN] sigaction(SIGTERM)");
    }

    printf("MLX75030 distance reader started (I2C bus %d, addr 0x%02X).\n",
           I2C_BUS, I2C_ADDR);
    printf("Press Ctrl-C to exit.\n");

    /* --- Main sampling loop ---------------------------------------- */
    while (g_running) {
        uint16_t distance = 0;

        if (read_distance(g_i2c_handle, &distance) == 0) {
            log_distance(distance);
        } else {
            fprintf(stderr, "[ERROR] Sensor read failed; continuing.\n");
        }

        gpioDelay(SAMPLE_PERIOD);
    }

    /* --- Graceful shutdown ----------------------------------------- */
    printf("\nShutting down...\n");

    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }

    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

