            continue;
        }

        if (reg_read16(handle, REG_DISTANCE, distance) != 0) {
            fprintf(stderr, "[WARN] Distance read failed (attempt %d/%d)\n",
                    attempt, MAX_RETRIES);
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        return 0;                 /* success */
    }

    fprintf(stderr, "[ERROR] Distance read failed after %d attempts\n", MAX_RETRIES);
    return -1;
}

/* ------------------------------------------------------------------ */
static void log_distance(uint16_t distance)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("[ERROR] clock_gettime");
        return;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char time_buf[32];
    strftime(time_buf, sizeof(time_buf), "%Y-%m-%d %H:%M:%S", &tm_info);

    printf("%s.%03ld  Distance: %u\n",
           time_buf, ts.tv_nsec / 1000000L, (unsigned)distance);
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Initialize pigpio ------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus ----------------------------------------------- */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers ----------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("[WARN] sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[WARN] sigaction(SIGTERM)");
    }

    printf("MLX75030 distance reader started (I2C bus %d, addr 0x%02X).\n",
           I2C_BUS, I2C_ADDR);
    printf("Press Ctrl-C to exit.\n");

    /* --- Main sampling loop ---------------------------------------- */
    while (g_running) {
        uint16_t distance = 0;

        if (read_distance(g_i2c_handle, &distance) == 0) {
            log_distance(distance);
        } else {
            fprintf(stderr, "[ERROR] Sensor read failed; continuing.\n");
        }

        gpioDelay(SAMPLE_PERIOD);
    }

    /* --- Graceful shutdown ----------------------------------------- */
    printf("\nShutting down...\n");

    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }

    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

