/*
 * VL53L4CX time-of-flight distance reader for Raspberry Pi Zero W.
 *
 * Wiring:
 *   VL53L4CX SDA  -> GPIO2 (pin 3, I2C bus 1 SDA)
 *   VL53L4CX SCL  -> GPIO3 (pin 5, I2C bus 1 SCL)
 *   VL53L4CX VDD  -> 3.3 V
 *   VL53L4CX GND  -> GND
 *   VL53L4CX XSHUT -> 3.3 V (active-low shutdown; tied high here for bus-free mode)
 *
 * Build:  gcc -O2 -Wall -Wextra -o vl53l4cx_reader vl53l4cx_reader.c -lvcldb
 * Run:    ./vl53l4cx_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>

#include "vl53l4cx_api.h"

#define I2C_BUS        "/dev/i2c-1"
#define VL53L4CX_ADDR  0x29

/* VL53L4CX register addresses (16-bit, big-endian on the bus). */
#define REG_SYSTEM_INTERRUPT_CLEAR  0x000B
#define REG_SYSTEM_INTERRUPT_STATUS 0x000A
#define REG_RESULT_RANGE_STATUS     0x0089
#define REG_RESULT_DISTANCE         0x0096

#define POLL_INTERVAL_MS 500
#define MAX_RETRIES      3

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int i2c_write16(int fd, uint16_t reg, uint8_t val)
{
    uint8_t buf[3];
    buf[0] = (uint8_t)(reg >> 8);
    buf[1] = (uint8_t)(reg & 0xFF);
    buf[2] = val;

    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write16 to 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read16(int fd, uint16_t reg, uint8_t *val)
{
    uint8_t reg_buf[2];
    reg_buf[0] = (uint8_t)(reg >> 8);
    reg_buf[1] = (uint8_t)(reg & 0xFF);

    if (write(fd, reg_buf, sizeof(reg_buf)) != (ssize_t)sizeof(reg_buf)) {
        fprintf(stderr, "I2C write16 (addr) to 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }

    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read16 from 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read16_16(int fd, uint16_t reg, uint16_t *val)
{
    uint8_t reg_buf[2];
    uint8_t data[2];
    reg_buf[0] = (uint8_t)(reg >> 8);
    reg_buf[1] = (uint8_t)(reg & 0xFF);

    if (write(fd, reg_buf, sizeof(reg_buf)) != (ssize_t)sizeof(reg_buf)) {
        fprintf(stderr, "I2C write16 (addr) to 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }

    if (read(fd, data, 2) != 2) {
        fprintf(stderr, "I2C read16_16 from 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *val = ((uint16_t)data[0] << 8) | data[1];
    return 0;
}

static int vl53l4cx_wait_for_data(int fd, int timeout_ms)
{
    for (int elapsed = 0; elapsed < timeout_ms && g_running; elapsed += 10) {
        uint8_t status = 0;
        if (i2c_read16(fd, REG_SYSTEM_INTERRUPT_STATUS, &status) != 0)
            return -1;
        if (status & 0x01)
            return 0;
        usleep(10000);
    }
    return g_running ? -2 : -1;
}

static int vl53l4cx_read_distance(int fd, uint16_t *distance_mm)
{
    if (i2c_write16(fd, REG_SYSTEM_INTERRUPT_CLEAR, 0x01) != 0)
        return -1;

    int rc = vl53l4cx_wait_for_data(fd, 5000);
    if (rc != 0) {
        if (rc == -2)
            fprintf(stderr, "Timeout waiting for VL53L4CX data.\n");
        return -1;
    }

    uint16_t status = 0;
    if (i2c_read16_16(fd, REG_RESULT_RANGE_STATUS, &status) != 0)
        return -1;

    if (status & 0x01) {
        uint16_t dist = 0;
        if (i2c_read16_16(fd, REG_RESULT_DISTANCE, &dist) != 0)
            return -1;
        *distance_mm = dist;
        return 0;
    }

    fprintf(stderr, "VL53L4CX range status 0x%04X indicates no valid data.\n", status);
    return -1;
}

static void print_timestamp(void)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) == 0) {
        struct tm tm_info;
        localtime_r(&ts.tv_sec, &tm_info);
        char buf[32];
        strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", &tm_info);
        printf("%s.%06ld", buf, ts.tv_nsec / 1000);
    } else {
        printf("----");
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install signal handlers: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, VL53L4CX_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n", VL53L4CX_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    if (i2c_write16(fd, REG_SYSTEM_INTERRUPT_CLEAR, 0x01) != 0) {
        fprintf(stderr, "VL53L4CX not responding at 0x%02X.\n", VL53L4CX_ADDR);
        close(fd);
        return EXIT_FAILURE;
    }

    printf("VL53L4CX initialized on %s (addr 0x%02X). Polling every %d ms.\n",
           I2C_BUS, VL53L4CX_ADDR, POLL_INTERVAL_MS);

    while (g_running) {
        uint16_t distance = 0;
        int rc = vl53l4cx_read_distance(fd, &distance);

        if (rc == 0) {
            print_timestamp();
            printf(": Distance: %u mm\n", distance);
            fflush(stdout);
        } else if (rc == -1) {
            fprintf(stderr, "Read error; continuing.\n");
        }

        for (int i = 0; i < MAX_RETRIES && g_running; i++)
            usleep(POLL_INTERVAL_MS * 1000);
    }

    printf("\nShutting down cleanly.\n");
    close(fd);
    return EXIT_SUCCESS;
}

