#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define BUZZER_GPIO 22
#define DISTANCE_THRESHOLD 100
#define POLL_INTERVAL_US 500000

#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_SYSTEM_MODE_START_STOP 0x0000
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_REG_RESULT_DISTANCE 0x0096

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *buf, uint8_t len) {
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, reg_buf, 2) < 0) return -1;
    return i2cReadDevice(handle, (char *)buf, len);
}

static int init_vl53l1x(int handle) {
    uint8_t model_id = 0;
    if (i2c_read_reg16(handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, &model_id, 1) < 0) {
        fprintf(stderr, "Error reading model ID: %s\n", strerror(errno));
        return -1;
    }
    if (model_id != 0xEA) {
        fprintf(stderr, "Invalid model ID: 0x%02X (expected 0xEA)\n", model_id);
        return -1;
    }
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_MODE_START_STOP, 0x00) < 0) {
        fprintf(stderr, "Error stopping sensor: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_distance(int handle) {
    uint8_t status = 0;
    uint8_t dist_buf[2] = {0};
    int distance = -1;

    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_MODE_START_STOP, 0x01) < 0) {
        fprintf(stderr, "Error starting measurement: %s\n", strerror(errno));
        return -1;
    }

    gpioDelay(100000);

    if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_RANGE_STATUS, &status, 1) < 0) {
        fprintf(stderr, "Error reading range status: %s\n", strerror(errno));
        return -1;
    }

    if (status & 0x01) {
        if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_DISTANCE, dist_buf, 2) < 0) {
            fprintf(stderr, "Error reading distance: %s\n", strerror(errno));
            return -1;
        }
        distance = (dist_buf[0] << 8) | dist_buf[1];
    } else {
        fprintf(stderr, "Measurement not ready\n");
    }

    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_MODE_START_STOP, 0x00) < 0) {
        fprintf(stderr, "Error stopping measurement: %s\n", strerror(errno));
        return -1;
    }

    return distance;
}

static void control_buzzer(int gpio_pin, int distance) {
    if (distance < DISTANCE_THRESHOLD) {
        gpioWrite(gpio_pin, 1);
    } else {
        gpioWrite(gpio_pin, 0);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (init_vl53l1x(i2c_handle) != 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);
    gpioWrite(BUZZER_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    while (running) {
        int distance = read_distance(i2c_handle);
        if (distance >= 0) {
            printf("Distance: %d mm\n", distance);
            control_buzzer(BUZZER_GPIO, distance);
        } else {
            fprintf(stderr, "Error reading distance, skipping iteration\n");
        }
        gpioDelay(POLL_INTERVAL_US);
    }

    gpioWrite(BUZZER_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

