#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define SERVO_PIN   17

#define MIN_DISTANCE_CM  2.0f
#define MAX_DISTANCE_CM  400.0f
#define MIN_ANGLE_DEG    -90
#define MAX_ANGLE_DEG    90

#define TIMEOUT_US       50000
#define TRIGGER_PULSE_US 10
#define LOOP_DELAY_US    200000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int init_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set trigger pin %d as output\n", TRIGGER_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set echo pin %d as input\n", ECHO_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set servo pin %d as output\n", SERVO_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Failed to initialise trigger pin low\n");
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int read_distance(float *distance_out)
{
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Failed to set trigger high\n");
        return -1;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Failed to set trigger low\n");
        return -1;
    }

    uint32_t start_tick = 0;
    uint32_t end_tick   = 0;
    uint32_t timeout    = 0;

    while (gpioRead(ECHO_PIN) == 0) {
        if (timeout++ > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo start\n");
            return -1;
        }
        gpioDelay(1);
    }
    start_tick = gpioTick();

    timeout = 0;
    while (gpioRead(ECHO_PIN) == 1) {
        if (timeout++ > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo end\n");
            return -1;
        }
        gpioDelay(1);
    }
    end_tick = gpioTick();

    uint32_t diff = end_tick - start_tick;
    *distance_out = (float)diff / 58.0f;
    return 0;
}

static int distance_to_angle(float distance)
{
    if (distance < MIN_DISTANCE_CM) distance = MIN_DISTANCE_CM;
    if (distance > MAX_DISTANCE_CM) distance = MAX_DISTANCE_CM;
    return (int)((distance - MIN_DISTANCE_CM) *
                 (MAX_ANGLE_DEG - MIN_ANGLE_DEG) /
                 (MAX_DISTANCE_CM - MIN_DISTANCE_CM) +
                 MIN_ANGLE_DEG);
}

static int log_data(float distance, int angle)
{
    FILE *fp = fopen("sensor_data.log", "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s, Distance: %.2f cm, Angle: %d degrees\n",
            timestamp, distance, angle);
    fclose(fp);
    return 0;
}

static void cleanup(void)
{
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (init_gpio() < 0) {
        return 1;
    }

    printf("Parking Assist System started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float distance = 0.0f;
        if (read_distance(&distance) == 0) {
            int angle = distance_to_angle(distance);
            if (gpioServo(SERVO_PIN, angle) < 0) {
                fprintf(stderr, "Failed to set servo angle\n");
            }
            if (log_data(distance, angle) < 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Failed to read distance\n");
        }
        gpioDelay(LOOP_DELAY_US);
    }

    cleanup();
    printf("Parking Assist System stopped.\n");
    return 0;
}

