        return -1;
    }
    uint8_t status = 0;
    int timeout = 100;
    while (timeout-- > 0) {
        if (i2c_read_reg16(fd, VL53L1X_REG_RESULT_RANGE_STATUS, &status) < 0) {
            fprintf(stderr, "Error: Failed to read range status.\n");
            return -1;
        }
        if ((status & 0x01) == 0) break;
        gpioDelay(1000);
    }
    if (timeout <= 0) {
        fprintf(stderr, "Error: Measurement timeout.\n");
        return -1;
    }
    uint16_t distance = 0;
    if (i2c_read_reg16_16(fd, VL53L1X_REG_RESULT_DISTANCE, &distance) < 0) {
        fprintf(stderr, "Error: Failed to read distance.\n");
        return -1;
    }
    return (int)distance;
}

static int send_distance(int distance) {
    char msg[MQ_MSG_SIZE];
    snprintf(msg, sizeof(msg), "%d", distance);
    if (mq_send(mq, msg, strlen(msg), 0) == -1) {
        perror("mq_send");
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (i2c_fd >= 0) {
        i2c_write_reg16(i2c_fd, VL53L1X_REG_SYSTEM_MODE_START, 0x00);
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (mq != (mqd_t)-1) {
        mq_close(mq);
        mq = (mqd_t)-1;
    }
    gpioWrite(BUZZER_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    if (gpioSetMode(BUZZER_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output.\n", BUZZER_GPIO);
        cleanup();
        return 1;
    }
    gpioWrite(BUZZER_GPIO, 0);

    i2c_fd = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X.\n", I2C_BUS, I2C_ADDR);
        cleanup();
        return 1;
    }

    if (init_vl53l1x(i2c_fd) < 0) {
        fprintf(stderr, "Error: VL53L1X initialization failed.\n");
        cleanup();
        return 1;
    }

    struct mq_attr attr;
    attr.mq_flags = 0;
    attr.mq_maxmsg = MQ_MAX_MSGS;
    attr.mq_msgsize = MQ_MSG_SIZE;
    attr.mq_curmsgs = 0;
    mq = mq_open(MQ_NAME, O_CREAT | O_RDWR, 0666, &attr);
    if (mq == (mqd_t)-1) {
        perror("mq_open");
        cleanup();
        return 1;
    }

    printf("VL53L1X distance monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int distance = read_distance(i2c_fd);
        if (distance >= 0) {
            if (send_distance(distance) == 0) {
                if (distance < DISTANCE_THRESHOLD) {
                    gpioWrite(BUZZER_GPIO, 1);
                    gpioDelay(100000);
                    gpioWrite(BUZZER_GPIO, 0);
                }
            }
        } else {
            fprintf(stderr, "Error: Failed to read distance.\n");
        }
        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

