/*
 * Parking sensor — HC-SR04 ultrasonic distance measurement on Raspberry Pi 3 B+.
 *
 * Wiring (BCM numbering):
 *   GPIO 17 -> HC-SR04 TRIG
 *   GPIO 27 -> HC-SR04 ECHO
 *   GPIO 22 -> Buzzer
 *
 * Build:  gcc -O2 -Wall -Wextra -o parking_sensor parking_sensor.c -lpigpio -lrt
 * Run:    sudo ./parking_sensor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN      17
#define ECHO_PIN         27
#define BUZZER_PIN       22

#define SPEED_OF_SOUND   34300.0          /* cm/s at ~20 °C */
#define MIN_DISTANCE     2.0              /* cm — HC-SR04 minimum  */
#define MAX_DISTANCE     400.0            /* cm — HC-SR04 maximum  */
#define THRESHOLD        30.0             /* cm — buzzer trigger   */
#define SAMPLE_PERIOD_US 100000           /* 100 ms between samples */
#define ECHO_TIMEOUT_US  30000            /* 30 ms echo timeout     */
#define TRIGGER_PULSE_US 10               /* 10 µs trigger pulse    */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Echo measurement                                                    */
/* ------------------------------------------------------------------ */
typedef struct {
    uint32_t start_tick;
    uint32_t end_tick;
    bool     got_rising;
    bool     got_falling;
} echo_state_t;

static void echo_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    echo_state_t *st = (echo_state_t *)userdata;

    if (level == 1) {
        st->start_tick  = tick;
        st->got_rising  = true;
        st->got_falling = false;
    } else if (level == 0 && st->got_rising) {
        st->end_tick    = tick;
        st->got_falling = true;
    }
}

/*
 * Returns distance in cm, or -1.0 on timeout / no echo / out-of-range.
 */
static double measure_distance(void)
{
    echo_state_t st = {0};

    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, &st) != 0) {
        fprintf(stderr, "Error: failed to register echo alert on GPIO %d.\n",
                ECHO_PIN);
        return -1.0;
    }

    /* Reset state before triggering */
    st.got_rising  = false;
    st.got_falling = false;

    /* 10 µs trigger pulse */
    if (gpioTrigger(TRIGGER_PIN, TRIGGER_PULSE_US, 1) != 0) {
        fprintf(stderr, "Error: gpioTrigger failed on GPIO %d.\n",
                TRIGGER_PIN);
        gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);
        return -1.0;
    }

    /* Wait for echo or timeout */
    uint32_t waited = 0;
    while (!st.got_falling && waited < ECHO_TIMEOUT_US) {
        gpioDelay(100);          /* 100 µs granularity */
        waited += 100;
    }

    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);   /* unregister alert */

    if (!st.got_rising) {
        fprintf(stderr, "Warning: no echo rising edge within %u µs "
                        "(sensor absent or wiring fault).\n",
                ECHO_TIMEOUT_US);
        return -1.0;
    }
    if (!st.got_falling) {
        fprintf(stderr, "Warning: echo pulse never ended within %u µs.\n",
                ECHO_TIMEOUT_US);
        return -1.0;
    }

    /* Handle 32-bit tick wraparound */
    uint32_t diff = st.end_tick - st.start_tick;

    double distance = (double)diff / 1000000.0 * SPEED_OF_SOUND / 2.0;

    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        fprintf(stderr, "Warning: distance %.2f cm out of range [%.0f–%.0f].\n",
                distance, MIN_DISTANCE, MAX_DISTANCE);
        return -1.0;
    }

    return distance;
}

/* ------------------------------------------------------------------ */
/* Buzzer control                                                      */
/* ------------------------------------------------------------------ */
static void control_buzzer(double distance)
{
    if (distance < 0.0) {
        gpioWrite(BUZZER_PIN, 0);
        return;
    }

    if (distance < THRESHOLD) {
        gpioWrite(BUZZER_PIN, 1);
    } else {
        gpioWrite(BUZZER_PIN, 0);
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO modes --- */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: cannot set GPIO %d as output.\n",
                TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: cannot set GPIO %d as input.\n",
                ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: cannot set GPIO %d as output.\n",
                BUZZER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure known initial states */
    gpioWrite(TRIGGER_PIN, 0);
    gpioWrite(BUZZER_PIN, 0);

    /* --- Install signal handlers --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        gpioWrite(BUZZER_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        gpioWrite(BUZZER_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Parking sensor started.  TRIG=GPIO%d  ECHO=GPIO%d  BUZZER=GPIO%d\n",
           TRIGGER_PIN, ECHO_PIN, BUZZER_PIN);
    printf("Threshold: %.0f cm.  Press Ctrl+C to exit.\n", THRESHOLD);

    /* --- Main loop --- */
    while (g_running) {
        double distance = measure_distance();

        if (distance < 0.0) {
            /* Sensor error — ensure buzzer is off for safety */
            gpioWrite(BUZZER_PIN, 0);
            fprintf(stderr, "Sensor read error; retrying next cycle.\n");
        } else {
            printf("Distance: %.2f cm\n", distance);
            control_buzzer(distance);
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* --- Clean shutdown --- */
    printf("\nShutting down...\n");
    gpioWrite(BUZZER_PIN, 0);
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

