#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS "/dev/i2c-1"
#define VL53L1X_ADDR 0x29
#define SERVO_PIN 18
#define DISTANCE_THRESHOLD 20
#define LOG_FILE "gate_log.txt"
#define MAX_RETRIES 3
#define POLL_DELAY_US 100000

#define VL53L1X_REG_SOFT_RESET 0x0003
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_SYSTEM_MODE_START 0x0000
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_DISTANCE 0x0096

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *event) {
    if (!log_file) return;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, event);
    fflush(log_file);
}

static int i2c_write_reg16(uint8_t reg, uint8_t value) {
    uint8_t buf[3] = { (reg >> 8) & 0xFF, reg & 0xFF, value };
    if (write(i2c_fd, buf, 3) != 3) return -1;
    return 0;
}

static int i2c_read_reg16(uint8_t reg, uint8_t *buf, uint8_t len) {
    uint8_t cmd[2] = { (reg >> 8) & 0xFF, reg & 0xFF };
    if (write(i2c_fd, cmd, 2) != 2) return -1;
    if (read(i2c_fd, buf, len) != len) return -1;
    return 0;
}

static int init_vl53l1x(void) {
    uint8_t model_id = 0;
    if (i2c_read_reg16(VL53L1X_REG_IDENTIFICATION_MODEL_ID, &model_id, 1) < 0) {
        fprintf(stderr, "Error: Failed to read model ID.\n");
        return -1;
    }
    if (model_id != 0xEA) {
        fprintf(stderr, "Error: Invalid model ID 0x%02X (expected 0xEA).\n", model_id);
        return -1;
    }
    if (i2c_write_reg16(VL53L1X_REG_SOFT_RESET, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to reset sensor.\n");
        return -1;
    }
    usleep(10000);
    if (i2c_write_reg16(VL53L1X_REG_SOFT_RESET, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to release reset.\n");
        return -1;
    }
    usleep(10000);
    if (i2c_write_reg16(VL53L1X_REG_SYSTEM_MODE_START, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to start ranging.\n");
        return -1;
    }
    return 0;
}

static int read_distance(void) {
    uint8_t status = 0;
    uint8_t dist_buf[2] = {0};
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (i2c_write_reg16(VL53L1X_REG_SYSTEM_MODE_START, 0x01) < 0) {
            retries++; usleep(10000); continue;
        }
        usleep(10000);
        if (i2c_read_reg16(VL53L1X_REG_RESULT_RANGE_STATUS, &status, 1) < 0) {
            retries++; usleep(10000); continue;
        }
        if (i2c_read_reg16(VL53L1X_REG_RESULT_DISTANCE, dist_buf, 2) < 0) {
            retries++; usleep(10000); continue;
        }
        if ((status & 0x01) == 0) {
            return (dist_buf[0] << 8) | dist_buf[1];
        }
        retries++; usleep(10000);
    }
    return -1;
}

static void control_servo(int angle) {
    if (angle < 0) angle = 0;
    if (angle > 180) angle = 180;
    int pulse_width = 500 + (angle * 2000 / 180);
    gpioServo(SERVO_PIN, pulse_width);
}

static void open_gate(void) {
    control_servo(180);
    log_event("Gate opened");
}

static void close_gate(void) {
    control_servo(0);
    log_event("Gate closed");
}

static void handle_command(const char *command) {
    if (strcmp(command, "open") == 0) {
        open_gate();
    } else if (strcmp(command, "close") == 0) {
        close_gate();
    } else if (strcmp(command, "status") == 0) {
        int dist = read_distance();
        if (dist >= 0) {
            char msg[64];
            snprintf(msg, sizeof(msg), "Distance: %d mm", dist);
            log_event(msg);
        } else {
            log_event("Error: Distance read failed");
        }
    } else {
        log_event("Invalid command");
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %s.\n", I2C_BUS);
        gpioTerminate();
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, VL53L1X_ADDR) < 0) {
        fprintf(stderr, "Error: Failed to set I2C slave address 0x%02X.\n", VL53L1X_ADDR);
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    if (init_vl53l1x() < 0) {
        fprintf(stderr, "Error: VL53L1X initialization failed.\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: Failed to open log file %s.\n", LOG_FILE);
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    log_event("System started");

    while (running) {
        int dist = read_distance();
        if (dist >= 0) {
            if (dist < DISTANCE_THRESHOLD * 10) {
                open_gate();
            } else {
                close_gate();
            }
        } else {
            log_event("Error: Distance read failed");
        }
        usleep(POLL_DELAY_US);
    }

    log_event("System shutting down");
    close(i2c_fd);
    gpioTerminate();
    fclose(log_file);
    return 0;
}

