/*
 * HC-SR04 distance measurement on Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   TRIG -> GPIO 23 (BCM 23, physical pin 16)
 *   ECHO -> GPIO 24 (BCM 24, physical pin 18) — 5 V output; use a
 *              voltage divider (e.g. 1 kΩ / 2 kΩ) to drive the Pi's
 *              3.3 V GPIO input, or a level shifter.
 *
 * NOTE: The HC-SR04 ECHO line is 5 V and must be level-shifted or
 *       divided to 3.3 V before connecting to the Pi.
 *
 * Build:  gcc -O2 -Wall -Wextra -o hcsr04 hcsr04.c -lpigpio -lrt
 * Run:    sudo ./hcsr04
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIG_PIN        23
#define ECHO_PIN        24

#define TRIG_PULSE_US   10          /* 10 µs trigger pulse            */
#define SAMPLE_PERIOD_S 0.2         /* 200 ms between triggers        */
#define ECHO_TIMEOUT_S  0.06        /* 60 ms max echo wait            */
#define MIN_PULSE_US    100         /* reject noise (< 100 µs)        */
#define MAX_PULSE_US    30000       /* reject timeout (> 30 ms)        */
#define LOG_FILE        "distance_log.txt"

static volatile sig_atomic_t g_running = 1;
static FILE                 *g_log_fp  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* pigpio alert callback — captures rising and falling edges           */
/* ------------------------------------------------------------------ */
static volatile uint32_t g_rising_tick = 0;
static volatile uint32_t g_falling_tick = 0;
static volatile bool     g_echo_seen    = false;

static void echo_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level == 1) {
        /* Rising edge — start of echo pulse */
        g_rising_tick  = tick;
        g_echo_seen    = true;
    } else if (level == 0) {
        /* Falling edge — end of echo pulse */
        g_falling_tick = tick;
    }
    /* level == 2 indicates a watchdog timeout; ignore here */
}

/* ------------------------------------------------------------------ */
/* Distance measurement                                                */
/* ------------------------------------------------------------------ */
static double measure_distance(void)
{
    /* Reset state */
    g_echo_seen    = false;
    g_rising_tick  = 0;
    g_falling_tick = 0;

    /* Fire 10 µs trigger pulse */
    if (gpioWrite(TRIG_PIN, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIG, 1) failed\n");
        return -1.0;
    }
    gpioDelay(TRIG_PULSE_US);
    if (gpioWrite(TRIG_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIG, 0) failed\n");
        return -1.0;
    }

    /* Wait for echo with timeout */
    uint32_t waited_us = 0;
    while (!g_echo_seen && waited_us < (uint32_t)(ECHO_TIMEOUT_S * 1e6)) {
        gpioDelay(100);                 /* 100 µs granularity */
        waited_us += 100;
    }

    if (!g_echo_seen) {
        fprintf(stderr, "Warning: echo timeout (no object or sensor absent)\n");
        return -1.0;
    }

    /* Compute pulse width with 32-bit tick wraparound handling */
    uint32_t pulse_us = g_falling_tick - g_rising_tick;

    if (pulse_us < MIN_PULSE_US) {
        fprintf(stderr, "Warning: pulse %u µs too short (noise)\n", pulse_us);
        return -1.0;
    }
    if (pulse_us > MAX_PULSE_US) {
        fprintf(stderr, "Warning: pulse %u µs too long (timeout)\n", pulse_us);
        return -1.0;
    }

    /* distance = (pulse_us / 1e6) * 34300 / 2  (round-trip) */
    return (double)pulse_us * 0.0343 / 2.0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_distance(double distance)
{
    time_t     rawtime;
    struct tm  tm_info;
    char       ts[32];

    time(&rawtime);
    localtime_r(&rawtime, &tm_info);
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info);

    printf("%s Distance: %.2f cm\n", ts, distance);

    if (g_log_fp) {
        fprintf(g_log_fp, "%s,%.2f\n", ts, distance);
        fflush(g_log_fp);
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    /* Release GPIO resources via pigpio */
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure TRIG pin as output, initially LOW */
    if (gpioSetMode(TRIG_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(TRIG) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioWrite(TRIG_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIG, 0) initial failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure ECHO pin as input with pull-down */
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(ECHO) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown(ECHO) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Register alert callback for both edges */
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) < 0) {
        fprintf(stderr, "Error: gpioSetAlertFuncEx(ECHO) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("Error opening log file");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance measurement started.\n");
    printf("TRIG=GPIO%d, ECHO=GPIO%d, logging to %s\n", TRIG_PIN, ECHO_PIN, LOG_FILE);
    printf("Press Ctrl+C to exit.\n");

    /* Main sampling loop */
    while (g_running) {
        double distance = measure_distance();

        if (distance >= 0.0) {
            log_distance(distance);
        } else {
            fprintf(stderr, "Measurement failed — skipping log entry.\n");
        }

        /* Sleep for the remainder of the 200 ms cycle */
        time_sleep(SAMPLE_PERIOD_S);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

