/*
 * Smart Parking Gate Controller
 * Board:  Raspberry Pi 4 Model B
 * Sensor: VL53L1X time-of-flight (I2C bus 1, addr 0x29)
 * Servo:  SG90 on GPIO18 (hardware PWM via pigpio)
 * Shutdown: GPIO23 (BCM)
 * Interrupt: GPIO24 (BCM)
 * Log:    parking_log.txt
 *
 * Build:  gcc -O2 -Wall -o parking_gate parking_gate.c -lpigpio -lrt
 * Run:    sudo ./parking_gate
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define VL53L1X_ADDR         0x29
#define SERVO_PIN            18
#define SHUTDOWN_PIN         23
#define INTERRUPT_PIN        24

#define DISTANCE_THRESHOLD_OPEN  50   /* cm  */
#define DISTANCE_THRESHOLD_CLOSE 60   /* cm  */

#define SERVO_OPEN_US          1500   /* us pulse width (180 deg) */
#define SERVO_CLOSED_US        500    /* us pulse width (0 deg)   */
#define SERVO_SETTLE_MS        500    /* ms to wait after servo move */

#define LOG_FILE               "parking_log.txt"
#define POLL_DELAY_US          100000 /* 100 ms between readings */

/* VL53L1X register addresses (16-bit, big-endian on bus) */
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID     0x010F
#define VL53L1X_REG_SYSTEM_MODE_START           0x0000
#define VL53L1X_REG_RESULT_RANGE_STATUS         0x0014
#define VL53L1X_REG_RESULT_DISTANCE             0x0096

#define VL53L1X_MODEL_ID                        0xEA
#define VL53L1X_START_STOP                      0x01
#define VL53L1X_STOP                            0x00

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ----------------------------- Prototypes -------------------------------- */
static void signal_handler(int sig);
static int  i2c_write_reg16(int handle, uint16_t reg, uint8_t value);
static int  i2c_read_reg16(int handle, uint16_t reg, uint8_t *buf, uint32_t len);
static int  vl53l1x_init(int handle);
static int  vl53l1x_read_distance(int handle, uint16_t *distance_mm);
static void log_event(const char *event, int distance_cm);
static void cleanup(void);

/* ----------------------------- Signal Handler ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- I2C helpers -------------------------------- */
static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *buf, uint32_t len)
{
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;

    if (i2cWriteDevice(handle, reg_buf, 2) < 0)
        return -1;
    if (i2cReadDevice(handle, (char *)buf, len) != (int)len)
        return -1;
    return 0;
}

/* ----------------------------- VL53L1X ------------------------------------ */
static int vl53l1x_init(int handle)
{
    uint8_t model_id = 0;

    if (i2c_read_reg16(handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, &model_id, 1) < 0) {
        fprintf(stderr, "Error: failed to read VL53L1X model ID (I2C bus error).\n");
        return -1;
    }
    if (model_id != VL53L1X_MODEL_ID) {
        fprintf(stderr, "Error: unexpected model ID 0x%02X (expected 0x%02X).\n",
                model_id, VL53L1X_MODEL_ID);
        return -1;
    }

    /* Software reset / standby */
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_MODE_START, VL53L1X_STOP) < 0) {
        fprintf(stderr, "Error: failed to stop VL53L1X during init.\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms settle */

    /* Start continuous ranging */
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_MODE_START, VL53L1X_START_STOP) < 0) {
        fprintf(stderr, "Error: failed to start VL53L1X ranging.\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms for first measurement */
    return 0;
}

static int vl53l1x_read_distance(int handle, uint16_t *distance_mm)
{
    uint8_t status = 0;
    uint8_t dist_buf[2] = {0, 0};

    if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_RANGE_STATUS, &status, 1) < 0)
        return -1;

    if (status & 0x01) { /* data ready */
        if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_DISTANCE, dist_buf, 2) < 0)
            return -1;
        *distance_mm = ((uint16_t)dist_buf[0] << 8) | dist_buf[1];
        return 0;
    }
    return 1; /* no new data yet */
}

/* ----------------------------- Logging ------------------------------------ */
static void log_event(const char *event, int distance_cm)
{
    time_t t = time(NULL);
    struct tm tm;
    char timestamp[64];

    if (localtime_r(&t, &tm) == NULL)
        return;

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (g_log_file) {
        fprintf(g_log_file, "%s - %s - Distance: %d cm\n", timestamp, event, distance_cm);
        fflush(g_log_file);
    }
    printf("%s - %s - Distance: %d cm\n", timestamp, event, distance_cm);
}

/* ----------------------------- Cleanup ------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2c_write_reg16(g_i2c_handle, VL53L1X_REG_SYSTEM_MODE_START, VL53L1X_STOP);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioServo(SERVO_PIN, 0); /* stop PWM */
    gpioTerminate();
}

/* ----------------------------- Main --------------------------------------- */
int main(void)
{
    int gate_open = 0;
    int distance_cm = 0;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        fprintf(stderr, "Error: cannot open log file '%s'.\n", LOG_FILE);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure servo pin for hardware PWM */
    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(SERVO_PIN, 50); /* 50 Hz */
    gpioServo(SERVO_PIN, SERVO_CLOSED_US);

    /* Configure shutdown pin as output, active low */
    gpioSetMode(SHUTDOWN_PIN, PI_OUTPUT);
    gpioWrite(SHUTDOWN_PIN, 1); /* power on */

    /* Configure interrupt pin as input */
    gpioSetMode(INTERRUPT_PIN, PI_INPUT);
    gpioSetPullUpDown(INTERRUPT_PIN, PI_PUD_DOWN);

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d).\n", g_i2c_handle);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (vl53l1x_init(g_i2c_handle) < 0) {
        fprintf(stderr, "Error: VL53L1X initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Smart Parking Gate Controller started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (g_running) {
        uint16_t dist_mm = 0;
        int rc = vl53l1x_read_distance(g_i2c_handle, &dist_mm);

        if (rc < 0) {
            fprintf(stderr, "Error: I2C read failure from VL53L1X.\n");
            log_event("I2C Error", -1);
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        if (rc == 1) {
            /* No new data yet — brief sleep and retry */
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        distance_cm = dist_mm / 10; /* mm -> cm */

        if (distance_cm < DISTANCE_THRESHOLD_OPEN && !gate_open) {
            gpioServo(SERVO_PIN, SERVO_OPEN_US);
            gpioDelay(SERVO_SETTLE_MS * 1000);
            gate_open = 1;
            log_event("Gate Opened", distance_cm);
        } else if (distance_cm > DISTANCE_THRESHOLD_CLOSE && gate_open) {
            gpioServo(SERVO_PIN, SERVO_CLOSED_US);
            gpioDelay(SERVO_SETTLE_MS * 1000);
            gate_open = 0;
            log_event("Gate Closed", distance_cm);
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

