/*
 * VL53L1X Time-of-Flight Gate Controller for Raspberry Pi 4 Model B
 *
 * Hardware:
 *   - VL53L1X on I2C bus 1, address 0x29
 *   - Gate control: GPIO 18 (open), GPIO 19 (close)
 *
 * Behavior:
 *   Polls the sensor every 500 ms. When distance < 200 mm, the gate is
 *   opened and an event is logged to gate_events.log. When distance >=
 *   200 mm, the gate is closed and the event is logged.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o gate_ctrl gate_ctrl.c -lpigpio -lrt
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS              1
#define VL53L1X_ADDR         0x29
#define GATE_OPEN_PIN        18
#define GATE_CLOSE_PIN       19
#define DISTANCE_THRESHOLD_MM 200
#define POLL_INTERVAL_US     500000
#define LOG_FILE             "gate_events.log"

/* VL53L1X 16-bit register addresses */
#define VL53L1X_SOFT_RESET              0x0003
#define VL53L1X_SYSTEM_MODE_START       0x0000
#define VL53L1X_RANGE_CONFIG_TIMEOUT_MAC 0x0046
#define VL53L1X_RESULT_INTERRUPT_STATUS 0x0044
#define VL53L1X_RESULT_FINAL_CROSSTALK  0x0096
#define VL53L1X_RESULT_PEAK_SIGNAL_RATE 0x0098
#define VL53L1X_RESULT_AMBIENT_RATE     0x009A
#define VL53L1X_RESULT_SIGMA            0x009C
#define VL53L1X_RESULT_DISTANCE         0x009E

static volatile sig_atomic_t g_running = 1;
static FILE *g_log = NULL;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void log_event(const char *event)
{
    if (!g_log) return;

    time_t now = time(NULL);
    struct tm tm_utc;
    char ts[32];

    if (gmtime_r(&now, &tm_utc) == NULL) {
        fprintf(stderr, "gmtime_r failed\n");
        return;
    }

    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    fprintf(g_log, "%s %s\n", ts, event);
    fflush(g_log);
}

static int vl53l1x_write16(int handle, uint16_t reg, uint16_t value)
{
    char buf[4];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (value >> 8) & 0xFF;
    buf[3] = value & 0xFF;
    return i2cWriteDevice(handle, buf, 4);
}

static int vl53l1x_read16(int handle, uint16_t reg, uint16_t *value)
{
    char reg_buf[2];
    char data[2];

    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;

    if (i2cWriteDevice(handle, reg_buf, 2) < 0) return -1;
    if (i2cReadDevice(handle, data, 2) < 0) return -1;

    *value = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

static int vl53l1x_init(int handle)
{
    /* Soft reset */
    if (vl53l1x_write16(handle, VL53L1X_SOFT_RESET, 0x0001) < 0) {
        fprintf(stderr, "VL53L1X soft reset write failed\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms */

    if (vl53l1x_write16(handle, VL53L1X_SOFT_RESET, 0x0000) < 0) {
        fprintf(stderr, "VL53L1X soft reset release failed\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms */

    /* Timing budget: 20 ms (0x00000000 = 20 ms) */
    if (vl53l1x_write16(handle, VL53L1X_RANGE_CONFIG_TIMEOUT_MAC, 0x0000) < 0) {
        fprintf(stderr, "VL53L1X timing budget write failed\n");
        return -1;
    }

    /* Start ranging */
    if (vl53l1x_write16(handle, VL53L1X_SYSTEM_MODE_START, 0x0001) < 0) {
        fprintf(stderr, "VL53L1X start ranging failed\n");
        return -1;
    }

    gpioDelay(10000); /* 10 ms for first measurement */
    return 0;
}

static int vl53l1x_read_distance(int handle, uint16_t *distance_mm)
{
    uint16_t status = 0;
    uint16_t dist = 0;

    if (vl53l1x_read16(handle, VL53L1X_RESULT_INTERRUPT_STATUS, &status) < 0) {
        fprintf(stderr, "VL53L1X status read failed\n");
        return -1;
    }

    if ((status & 0x0001) == 0) {
        return 1; /* No new data yet */
    }

    if (vl53l1x_read16(handle, VL53L1X_RESULT_DISTANCE, &dist) < 0) {
        fprintf(stderr, "VL53L1X distance read failed\n");
        return -1;
    }

    /* Clear interrupt by writing 0x0001 */
    if (vl53l1x_write16(handle, VL53L1X_RESULT_INTERRUPT_STATUS, 0x0001) < 0) {
        fprintf(stderr, "VL53L1X interrupt clear failed\n");
        return -1;
    }

    *distance_mm = dist;
    return 0;
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(GATE_OPEN_PIN, 0);
    gpioWrite(GATE_CLOSE_PIN, 0);
    if (g_log) {
        fclose(g_log);
        g_log = NULL;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        perror("fopen log");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GATE_OPEN_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(GATE_CLOSE_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    gpioWrite(GATE_OPEN_PIN, 0);
    gpioWrite(GATE_CLOSE_PIN, 0);

    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (handle=%d)\n", g_i2c_handle);
        log_event("ERROR: I2C open failed");
        cleanup();
        return EXIT_FAILURE;
    }

    if (vl53l1x_init(g_i2c_handle) < 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        log_event("ERROR: VL53L1X init failed");
        cleanup();
        return EXIT_FAILURE;
    }

    log_event("INFO: Gate controller started");

    while (g_running) {
        uint16_t distance = 0;
        int rc = vl53l1x_read_distance(g_i2c_handle, &distance);

        if (rc == 0) {
            if (distance < DISTANCE_THRESHOLD_MM) {
                gpioWrite(GATE_OPEN_PIN, 1);
                gpioWrite(GATE_CLOSE_PIN, 0);
                log_event("INFO: Gate OPENED");
            } else {
                gpioWrite(GATE_OPEN_PIN, 0);
                gpioWrite(GATE_CLOSE_PIN, 1);
                log_event("INFO: Gate CLOSED");
            }
        } else if (rc < 0) {
            log_event("ERROR: I2C read failure");
        }
        /* rc == 1: no new data yet, just wait */

        gpioDelay(POLL_INTERVAL_US);
    }

    log_event("INFO: Gate controller shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

