#include <unistd.h>
#include <pigpio.h>

#define MOTOR_FORWARD_PIN 17
#define MOTOR_BACKWARD_PIN 18
#define DISTANCE_THRESHOLD_PIN 24

#define DISTANCE_THRESHOLD_LOW 100
#define DISTANCE_THRESHOLD_HIGH 300

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29

#define VL53L1X_REG_SOFT_RESET 0x0003
#define VL53L1X_REG_SYSTEM_START 0x0000
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_DISTANCE 0x0096

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static int motor_state = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value) {
    char buf[3] = { (char)(reg >> 8), (char)(reg & 0xFF), (char)value };
    return i2cWriteDevice(handle, buf, 3);
}

static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *buf, uint8_t len) {
    char reg_buf[2] = { (char)(reg >> 8), (char)(reg & 0xFF) };
    if (i2cWriteDevice(handle, reg_buf, 2) != 0) return -1;
    return i2cReadDevice(handle, (char *)buf, len);
}

static int init_vl53l1x(int handle) {
    if (i2c_write_reg16(handle, VL53L1X_REG_SOFT_RESET, 0x00) != 0) {
        fprintf(stderr, "Error: Failed to write soft reset register.\n");
        return -1;
    }
    gpioDelay(1000);
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_START, 0x01) != 0) {
        fprintf(stderr, "Error: Failed to start measurement.\n");
        return -1;
    }
    return 0;
}

static int read_distance(int handle) {
    uint8_t status_buf[1];
    uint8_t dist_buf[2];
    int retries = 0;
    int delay_ms = 1;

    while (retries < 10) {
        if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_RANGE_STATUS, status_buf, 1) != 0) {
            fprintf(stderr, "Error: Failed to read range status (attempt %d).\n", retries + 1);
            retries++;
            gpioDelay(delay_ms * 1000);
            delay_ms *= 2;
            continue;
        }
        if ((status_buf[0] & 0x01) == 0) {
            gpioDelay(1000);
            continue;
        }
        if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_DISTANCE, dist_buf, 2) != 0) {
            fprintf(stderr, "Error: Failed to read distance (attempt %d).\n", retries + 1);
            retries++;
            gpioDelay(delay_ms * 1000);
            delay_ms *= 2;
            continue;
        }
        return (dist_buf[0] << 8) | dist_buf[1];
    }
    fprintf(stderr, "Error: Failed to read distance after multiple retries.\n");
    return -1;
}

static void control_motor(int distance) {
    if (distance < 0) {
        if (motor_state != 0) {
            gpioWrite(MOTOR_FORWARD_PIN, 0);
            gpioWrite(MOTOR_BACKWARD_PIN, 0);
            motor_state = 0;
            printf("Motor stopped (sensor error).\n");
        }
        return;
    }
    if (distance < DISTANCE_THRESHOLD_LOW) {
        if (motor_state != 1) {
            gpioWrite(MOTOR_FORWARD_PIN, 1);
            gpioWrite(MOTOR_BACKWARD_PIN, 0);
            motor_state = 1;
            printf("Motor running forward (distance: %d mm).\n", distance);
        }
    } else if (distance > DISTANCE_THRESHOLD_HIGH) {
        if (motor_state != 2) {
            gpioWrite(MOTOR_FORWARD_PIN, 0);
            gpioWrite(MOTOR_BACKWARD_PIN, 1);
            motor_state = 2;
            printf("Motor running backward (distance: %d mm).\n", distance);
        }
    } else {
        if (motor_state != 0) {
            gpioWrite(MOTOR_FORWARD_PIN, 0);
            gpioWrite(MOTOR_BACKWARD_PIN, 0);
            motor_state = 0;
            printf("Motor stopped (distance: %d mm).\n", distance);
        }
    }
}

static void distance_callback(int gpio, int level, uint32_t tick) {
    (void)gpio;
    (void)tick;
    if (level == 1) {
        int distance = read_distance(i2c_handle);
        printf("Distance: %d mm\n", distance);
        control_motor(distance);
    }
}

static void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(MOTOR_FORWARD_PIN, 0);
    gpioWrite(MOTOR_BACKWARD_PIN, 0);
    gpioTerminate();
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (handle: %d).\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_vl53l1x(i2c_handle) != 0) {
        fprintf(stderr, "Error: VL53L1X initialisation failed.\n");
        cleanup();
        return 1;
    }

    gpioSetMode(MOTOR_FORWARD_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_BACKWARD_PIN, PI_OUTPUT);
    gpioSetMode(DISTANCE_THRESHOLD_PIN, PI_INPUT);
    gpioSetPullUpDown(DISTANCE_THRESHOLD_PIN, PI_PUD_DOWN);

    if (gpioSetISRFuncEx(DISTANCE_THRESHOLD_PIN, RISING_EDGE, 0, distance_callback, NULL) != 0) {
        fprintf(stderr, "Error: Failed to set ISR function.\n");
        cleanup();
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Program running. Press Ctrl+C to exit.\n");

    while (running) {
        gpioDelay(100000);
    }

    printf("\nCleaning up...\n");
    cleanup();
    return 0;
}

