#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define MPR121_ADDR 0x5A
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "proximity_log.txt"

#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECTRODE_CONFIG 0x5E
#define MPR121_SOFTRESET 0x80

#define LED_PIN_0 17
#define LED_PIN_1 18
#define LED_PIN_2 27
#define LED_PIN_3 22

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    if (!log_file) return;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(log_file);
}

static int i2c_write_reg(uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(i2c_fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

static int i2c_read_reg(uint8_t reg, uint8_t *value) {
    if (write(i2c_fd, &reg, 1) != 1) {
        perror("I2C write (reg select) failed");
        return -1;
    }
    if (read(i2c_fd, value, 1) != 1) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

static int mpr121_init(void) {
    if (i2c_write_reg(MPR121_SOFTRESET, 0x63) < 0) return -1;
    usleep(10000);

    if (i2c_write_reg(MPR121_ELECTRODE_CONFIG, 0x0C) < 0) return -1;
    usleep(10000);

    uint8_t id = 0;
    if (i2c_read_reg(0x2B, &id) < 0) return -1;
    if (id != 0x0D) {
        fprintf(stderr, "MPR121 ID mismatch: 0x%02X (expected 0x0D)\n", id);
        return -1;
    }
    return 0;
}

