#define LED_GPIO 27
#define LOG_FILE "proximity.log"

#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECONFIG 0x5E
#define MPR121_MHD_RISING 0x2B
#define MPR121_NHD_RISING 0x2C
#define MPR121_NCL_RISING 0x2D
#define MPR121_FDL_RISING 0x2E
#define MPR121_MHD_FALLING 0x2F
#define MPR121_NHD_FALLING 0x30
#define MPR121_NCL_FALLING 0x31
#define MPR121_FDL_FALLING 0x32
#define MPR121_NHD_RISING_NHD_Falling 0x33
#define MPR121_NCL_RISING_NCL_Falling 0x34
#define MPR121_FDL_RISING_NDL_Falling 0x35
#define MPR121_E0TTH 0x41
#define MPR121_E0RTH 0x42
#define MPR121_DEBOUNCE 0x5B
#define MPR121_CONFIG1 0x5C
#define MPR121_CONFIG2 0x5D
#define MPR121_ECR 0x5E
#define MPR121_AUTO_CONFIG0 0x7B
#define MPR121_AUTO_CONFIG1 0x7C
#define MPR121_USL 0x7D
#define MPR121_LSL 0x7E
#define MPR121_TL 0x7F

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

int mpr121_write_reg(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing to register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

int mpr121_read_reg(int handle, uint8_t reg) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading from register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return result;
}

int mpr121_init(int handle) {
    if (mpr121_write_reg(handle, MPR121_ECR, 0x00) < 0) return -1;
    gpioDelay(1000);

    if (mpr121_write_reg(handle, MPR121_MHD_RISING, 0x01) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_NHD_RISING, 0x01) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_NCL_RISING, 0x00) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_FDL_RISING, 0x00) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_MHD_FALLING, 0x01) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_NHD_FALLING, 0x01) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_NCL_FALLING, 0x00) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_FDL_FALLING, 0x00) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_NHD_RISING_NHD_Falling, 0x00) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_NCL_RISING_NCL_Falling, 0x00) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_FDL_RISING_NDL_Falling, 0x00) < 0) return -1;

    if (mpr121_write_reg(handle, MPR121_E0TTH, 0x0F) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_E0RTH, 0x0A) < 0) return -1;

    if (mpr121_write_reg(handle, MPR121_DEBOUNCE, 0x00) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_CONFIG1, 0x10) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_CONFIG2, 0x20) < 0) return -1;

    if (mpr121_write_reg(handle, MPR121_AUTO_CONFIG0, 0x0B) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_AUTO_CONFIG1, 0x00) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_USL, 0xC8) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_LSL, 0x82) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_TL, 0xB4) < 0) return -1;

    if (mpr121_write_reg(handle, MPR121_ECR, 0x8F) < 0) return -1;
    gpioDelay(1000);

    return 0;
}

int mpr121_read_touch_data(int handle, uint16_t *touch_data) {
    char buf[2];
    int result = i2cReadI2CBlockData(handle, MPR121_TOUCHSTATUS_L, buf, 2);
    if (result < 0) {
        fprintf(stderr, "Error reading touch data: %d\n", result);
        return -1;
    }
    *touch_data = (uint16_t)((buf[1] << 8) | buf[0]);
    return 0;
}

int log_proximity_event(const char *filename) {
    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s - Proximity detected\n", timestamp);
    fclose(fp);
    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    int device_id = mpr121_read_reg(i2c_handle, 0x00);
    if (device_id < 0) {
        fprintf(stderr, "Error reading device ID\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (device_id != 0x0C) {
        fprintf(stderr, "Unexpected device ID: 0x%02X\n", device_id);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (mpr121_init(i2c_handle) < 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Proximity detection started. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t touch_data;
        if (mpr121_read_touch_data(i2c_handle, &touch_data) == 0) {
            if (touch_data & 0x0001) {
                printf("Proximity detected!\n");
                gpioWrite(LED_GPIO, 1);
                log_proximity_event(LOG_FILE);
                gpioDelay(1000000);
                gpioWrite(LED_GPIO, 0);
            }
        }
        gpioDelay(10000);
    }

    printf("\nCleaning up...\n");
    gpioWrite(LED_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

