#define MAX_DISTANCE_CM 400.0
#define MIN_DISTANCE_CM 2.0
#define SOUND_SPEED_CM_PER_US 0.0343

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int init_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set trigger pin %d as output\n", TRIGGER_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set echo pin %d as input\n", ECHO_PIN);
        gpioTerminate();
        return -1;
    }

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Failed to initialise trigger pin low\n");
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void trigger_pulse(void)
{
    /* 5 us low pulse to settle */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(5);

    /* 10 us trigger pulse */
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10);
    gpioWrite(TRIGGER_PIN, 0);
}

/*
 * Returns distance in cm, or -1.0 on timeout / sensor-absent / out-of-range.
 */
static float measure_distance(void)
{
    uint32_t start_tick = 0, end_tick = 0;
    uint32_t timeout_tick;

    trigger_pulse();

    /* Wait for echo rising edge */
    timeout_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - timeout_tick) >= TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo rising edge\n");
            return -1.0;
        }
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge */
    timeout_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - timeout_tick) >= TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo falling edge\n");
            return -1.0;
        }
    }
    end_tick = gpioTick();

    float pulse_us = (float)(end_tick - start_tick);
    float distance = (pulse_us * SOUND_SPEED_CM_PER_US) / 2.0f;

