/*
 * HC-SR04 ultrasonic distance measurement on Raspberry Pi Zero W.
 *
 * Wiring:
 *   TRIG -> GPIO17 (BCM 17, physical pin 11)
 *   ECHO -> GPIO18 (BCM 18, physical pin 12) via 1 k/2 k divider
 *           (HC-SR04 ECHO is 5 V; divider keeps Pi input at ~3.3 V)
 *
 * Behavior:
 *   - Triggers a 10 us pulse once per second.
 *   - Captures echo pulse width via an ISR on either edge.
 *   - Validates pulse width (58 us .. 25 ms) and converts to meters.
 *   - Appends timestamp + distance to distance_log.txt.
 *   - SIGINT/SIGTERM -> clean shutdown (ISR disabled, log closed, cleanup).
 *
 * Build:  gcc -O2 -Wall -Wextra -o hcsr04 hcsr04.c -lpigpio -lrt
 * Run:    sudo ./hcsr04
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIG_PIN        17
#define ECHO_PIN        18

#define TRIG_PULSE_US   10          /* HC-SR04 trigger pulse width   */
#define SAMPLE_PERIOD_S 1.0         /* 1 Hz sampling rate            */
#define LOG_FILE        "distance_log.txt"

/* Valid echo pulse width: 58 us (1 cm round trip) .. 25 ms (4 m round trip) */
#define MIN_PULSE_US    58
#define MAX_PULSE_US    25000

static volatile sig_atomic_t g_running = 1;
static volatile uint32_t     g_start_tick = 0;
static volatile uint32_t     g_end_tick   = 0;
static volatile bool         g_echo_seen  = false;
static FILE                 *g_log_fp     = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* ISR: capture either-edge transitions to measure echo pulse width   */
/* ------------------------------------------------------------------ */
static void echo_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level == 1) {
        /* Rising edge: echo pulse starts */
        g_start_tick = tick;
        g_echo_seen  = false;
    } else if (level == 0) {
        /* Falling edge: echo pulse ends */
        g_end_tick = tick;
        g_echo_seen = true;
    }
}

/* ------------------------------------------------------------------ */
/* pigpio tick arithmetic (handles 32-bit wrap-around)                 */
/* ------------------------------------------------------------------ */
static uint32_t tick_diff(uint32_t start, uint32_t end)
{
    return end - start;  /* unsigned subtraction wraps correctly */
}

/* ------------------------------------------------------------------ */
/* Convert pulse width (us) to distance (m)                            */
/* ------------------------------------------------------------------ */
static float pulse_to_distance_cm(uint32_t pulse_us)
{
    /* speed of sound ~343 m/s => 0.0343 cm/us; round-trip => /2 */
    return (float)pulse_us * 0.0343f / 2.0f;
}

/* ------------------------------------------------------------------ */
/* Append a reading to the log file                                    */
/* ------------------------------------------------------------------ */
static void log_reading(float distance_cm)
{
    time_t     rawtime;
    struct tm  tm_info;
    char       ts[32];

    time(&rawtime);
    localtime_r(&rawtime, &tm_info);
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);

    if (fprintf(g_log_fp, "%s, %.2f cm\n", ts, distance_cm) < 0) {
        perror("fprintf to log file");
    } else {
        fflush(g_log_fp);
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Disable ISR before tearing down */
    gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, NULL, NULL);

    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }

    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* ---- open log file ---- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- configure GPIO ---- */
    if (gpioSetMode(TRIG_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: cannot set TRIG_PIN %d as output.\n", TRIG_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: cannot set ECHO_PIN %d as input.\n", ECHO_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    gpioWrite(TRIG_PIN, 0);
    gpioDelay(50000);  /* 50 ms settle */

    /* ---- register ISR ---- */
    if (gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, echo_isr, NULL) != 0) {
        fprintf(stderr, "Error: cannot register ISR on ECHO_PIN %d.\n", ECHO_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance measurement started.\n");
    printf("TRIG=GPIO%d, ECHO=GPIO%d (via divider).\n", TRIG_PIN, ECHO_PIN);
    printf("Logging to '%s'. Press Ctrl+C to exit.\n", LOG_FILE);

    /* ---- main loop ---- */
    while (g_running) {
        /* Reset state for this sample cycle */
        g_echo_seen = false;
        g_start_tick = 0;
        g_end_tick   = 0;

        /* 10 us trigger pulse */
        gpioWrite(TRIG_PIN, 1);
        gpioDelay(TRIG_PULSE_US);
        gpioWrite(TRIG_PIN, 0);

        /* Wait up to 30 ms for the echo ISR to capture the pulse.
         * If no echo arrives, the sensor may be absent or out of range. */
        uint32_t waited_us = 0;
        while (!g_echo_seen && waited_us < 30000 && g_running) {
            gpioDelay(1000);  /* 1 ms */
            waited_us += 1000;
        }

        if (!g_echo_seen) {
            fprintf(stderr, "Warning: no echo received (sensor absent or out of range).\n");
            sleep(1);
            continue;
        }

        uint32_t pulse_us = tick_diff(g_start_tick, g_end_tick);
        if (pulse_us < MIN_PULSE_US || pulse_us > MAX_PULSE_US) {
            fprintf(stderr, "Warning: pulse width %u us out of valid range.\n", pulse_us);
            sleep(1);
            continue;
        }

        float distance_cm = pulse_to_distance_cm(pulse_us);
        log_reading(distance_cm);
        printf("Distance: %.2f cm\n", distance_cm);

        /* Sleep until next sample period (interruptible by signals) */
        sleep(1);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

