         * If no echo arrives, the sensor may be absent or out of range. */
        uint32_t waited_us = 0;
        while (!g_echo_seen && waited_us < 30000 && g_running) {
            gpioDelay(1000);  /* 1 ms */
            waited_us += 1000;
        }

        if (!g_echo_seen) {
            fprintf(stderr, "Warning: no echo received (sensor absent or out of range).\n");
            sleep(1);
            continue;
        }

        uint32_t pulse_us = tick_diff(g_start_tick, g_end_tick);
        if (pulse_us < MIN_PULSE_US || pulse_us > MAX_PULSE_US) {
            fprintf(stderr, "Warning: pulse width %u us out of valid range.\n", pulse_us);
            sleep(1);
            continue;
        }

        float distance_cm = pulse_to_distance_cm(pulse_us);
        log_reading(distance_cm);
        printf("Distance: %.2f cm\n", distance_cm);

        /* Sleep until next sample period (interruptible by signals) */
        sleep(1);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

