#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <pigpio.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <errno.h>

#include "vl53l1x_api.h"

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define XSHUT_PIN 27
#define POLL_DELAY_US 100000

static int i2c_handle = -1;
static VL53L1X_Dev_t vl53l1x_dev;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_i2c(void) {
    char filename[20];
    snprintf(filename, sizeof(filename), "/dev/i2c-%d", I2C_BUS);

    i2c_handle = open(filename, O_RDWR);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus %s: %s", filename, strerror(errno));
        return -1;
    }

    if (ioctl(i2c_handle, I2C_SLAVE, VL53L1X_ADDR) < 0) {
        syslog(LOG_ERR, "Failed to acquire I2C bus access: %s", strerror(errno));
        close(i2c_handle);
        i2c_handle = -1;
        return -1;
    }

    return 0;
}

static int init_vl53l1x(void) {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    gpioSetMode(XSHUT_PIN, PI_OUTPUT);
    gpioWrite(XSHUT_PIN, 1);

    if (init_i2c() != 0) {
        gpioTerminate();
        return -1;
    }

    if (VL53L1X_Initialize(&vl53l1x_dev) != 0) {
        syslog(LOG_ERR, "VL53L1X initialisation failed");
        close(i2c_handle);
        i2c_handle = -1;
        gpioTerminate();
        return -1;
    }

    if (VL53L1X_StartRanging(&vl53l1x_dev) != 0) {
        syslog(LOG_ERR, "VL53L1X StartRanging failed");
        VL53L1X_ShutDown(&vl53l1x_dev);
        close(i2c_handle);
        i2c_handle = -1;
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int read_distance(int *distance_mm) {
    if (VL53L1X_CheckForDataReady(&vl53l1x_dev) == 0) {
        if (VL53L1X_GetDistance(&vl53l1x_dev, distance_mm) == 0) {
            VL53L1X_ClearInterrupt(&vl53l1x_dev);
            return 0;
        }
        syslog(LOG_ERR, "Failed to read distance from VL53L1X");
        return -1;
    }
    return -1;
}

static void log_data(int distance_mm, int status) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (status == 0) {
        syslog(LOG_INFO, "%s Distance: %d mm, Status: OK", timestamp, distance_mm);
    } else {
        syslog(LOG_ERR, "%s Distance: N/A, Status: Error", timestamp);
    }
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        VL53L1X_ShutDown(&vl53l1x_dev);
        close(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
    closelog();
}

int main(void) {
    openlog("vl53l1x_monitor", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to install signal handlers: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    if (init_vl53l1x() != 0) {
        syslog(LOG_ERR, "VL53L1X initialization failed, exiting");
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "VL53L1X monitoring started");

    while (!terminate) {
        int distance_mm = 0;
        int status = read_distance(&distance_mm);

        if (status == 0) {
            log_data(distance_mm, 0);
        } else {
            log_data(0, -1);
        }

        gpioDelay(POLL_DELAY_US);
    }

    syslog(LOG_INFO, "VL53L1X monitoring stopped");
    cleanup();
    return EXIT_SUCCESS;
}

