#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <math.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define SERVO_PIN   18

#define SPEED_OF_SOUND_CM_PER_US 0.0343
#define MIN_DISTANCE_CM          2.0
#define MAX_DISTANCE_CM          400.0
#define SERVO_MIN_PULSE_US       500
#define SERVO_MAX_PULSE_US       2500
#define SERVO_CENTER_DEG         90
#define SERVO_RANGE_DEG          180
#define SERVO_CENTER_PULSE_US    1500
#define SERVO_SETTLE_MS          500
#define ECHO_TIMEOUT_US          30000
#define TRIGGER_PULSE_US         10
#define SAMPLE_PERIOD_US         100000
#define MOVING_AVG_SIZE          5

static volatile sig_atomic_t g_running = 1;
static volatile uint32_t     g_pulse_width = 0;
static volatile int          g_new_pulse = 0;
static FILE                 *g_log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void echo_callback(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio;
    (void)userdata;
    static uint32_t start_tick = 0;
    static int      echo_state = 0;

    if (level == 1) {
        start_tick = tick;
        echo_state = 1;
    } else if (level == 0 && echo_state) {
        uint32_t pulse = tick - start_tick;
        if (pulse > ECHO_TIMEOUT_US) {
            pulse = ECHO_TIMEOUT_US;
        }
        g_pulse_width = pulse;
        g_new_pulse = 1;
        echo_state = 0;
    }
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set trigger pin mode\n");
        return -1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set echo pin mode\n");
        return -1;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set servo pin mode\n");
        return -1;
    }

    if (gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Failed to set echo pull-down\n");
        return -1;
    }

    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Failed to reset trigger pin\n");
        return -1;
    }
    gpioDelay(5000);

    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) < 0) {
        fprintf(stderr, "Failed to register echo alert\n");
        return -1;
    }

    return 0;
}

static int measure_distance(float *distance_cm) {
    g_new_pulse = 0;
    g_pulse_width = 0;

    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
