        return -1;
    }

    uint32_t start_wait = gpioTick();
    while (!g_new_pulse) {
        if ((gpioTick() - start_wait) > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Echo timeout\n");
            return -1;
        }
        gpioDelay(100);
    }

    uint32_t pulse = g_pulse_width;
    float dist = (float)pulse * SPEED_OF_SOUND_CM_PER_US / 2.0f;

    if (dist < MIN_DISTANCE_CM || dist > MAX_DISTANCE_CM) {
