#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <stdbool.h>

#define VL53L1X_ADDR 0x29
#define LED_GPIO 17
#define BUFFER_SIZE 10
#define DISTANCE_THRESHOLD 200
#define POLL_DELAY_US 50000

#define VL53L1X_REG_SOFT_RESET 0x0000
#define VL53L1X_REG_I2C_SLAVE_DEVICE_ADDRESS 0x0001
#define VL53L1X_REG_SYSTEM_MODE_START 0x0002
#define VL53L1X_REG_RESULT_INTERRUPT_STATUS 0x0044
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x004D
#define VL53L1X_REG_RESULT_DISTANCE 0x0096
#define VL53L1X_REG_SYSTEM_INTERRUPT_CONFIG_GPIO 0x0046
#define VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR 0x0086
#define VL53L1X_REG_SYSTEM_SEQUENCE_CONFIG 0x0001
#define VL53L1X_REG_SYSTEM_RANGE_CONFIG 0x0002
#define VL53L1X_REG_SYSTEM_INTERMEASUREMENT 0x0004
#define VL53L1X_REG_SYSTEM_THRESHOLD_HIGH 0x0006
#define VL53L1X_REG_SYSTEM_THRESHOLD_LOW 0x0008
#define VL53L1X_REG_SYSTEM_CROSSTALK 0x000A
#define VL53L1X_REG_SYSTEM_SIGNAL_RATE 0x000C
#define VL53L1X_REG_SYSTEM_PHASECAL 0x000E
#define VL53L1X_REG_SYSTEM_RANGE_TIMING 0x0010
#define VL53L1X_REG_SYSTEM_RANGE_CONFIG_A 0x0012
#define VL53L1X_REG_SYSTEM_RANGE_CONFIG_B 0x0014
#define VL53L1X_REG_SYSTEM_RANGE_CONFIG_C 0x0016
#define VL53L1X_REG_SYSTEM_RANGE_CONFIG_D 0x0018
#define VL53L1X_REG_SYSTEM_RANGE_CONFIG_E 0x001A
#define VL53L1X_REG_SYSTEM_RANGE_CONFIG_F 0x001C
#define VL53L1X_REG_SYSTEM_RANGE_CONFIG_G 0x001E
#define VL53L1X_REG_SYSTEM_RANGE_CONFIG_H 0x0020
#define VL53L1X_REG_SYSTEM_RANGE_CONFIG_I 0x0022
#define VL53L1X_REG_SYSTEM_RANGE_CONFIG_J 0x0024
#define VL53L1X_REG_SYSTEM_RANGE_CONFIG_K 0x0026
#define VL53L1X_REG_SYSTEM_RANGE_CONFIG_L 0x0028
#define VL53L1X_REG_SYSTEM_RANGE_CONFIG_M 0x002A
#define VL53L1X_REG_SYSTEM_RANGE_CONFIG_N 0x002C
#define VL53L1X_REG_SYSTEM_RANGE_CONFIG_O 0x002E
#define VL53L1X_REG_SYSTEM_RANGE_CONFIG_P 0x0030
#define VL53L1X_REG_SYSTEM_RANGE_CONFIG_Q 0x0032
#define VL53L1X_REG_SYSTEM_RANGE_CONFIG_R 0x0034
#define VL53L1X_REG_SYSTEM_RANGE_CONFIG_S 0x0036
#define VL53L1X_REG_SYSTEM_RANGE_CONFIG_T 0x0038
#define VL53L1X_REG_SYSTEM_RANGE_CONFIG_U 0x003A
#define VL53L1X_REG_SYSTEM_RANGE_CONFIG_V 0x003C
#define VL53L1X_REG_SYSTEM_RANGE_CONFIG_W 0x003E
#define VL53L1X_REG_SYSTEM_RANGE_CONFIG_X 0x0040
#define VL53L1X_REG_SYSTEM_RANGE_CONFIG_Y 0x0042
#define VL53L1X_REG_SYSTEM_RANGE_CONFIG_Z 0x0044

static int i2c_handle = -1;
static int circular_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *buf, uint8_t len) {
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, reg_buf, 2) != 0) return -1;
    return i2cReadDevice(handle, (char *)buf, len);
}

static int vl53l1x_init(int handle) {
    if (i2c_write_reg16(handle, VL53L1X_REG_SOFT_RESET, 0x00) < 0) return -1;
    gpioDelay(1000);
    if (i2c_write_reg16(handle, VL53L1X_REG_SOFT_RESET, 0x01) < 0) return -1;
    gpioDelay(1000);

    if (i2c_write_reg16(handle, VL53L1X_REG_I2C_SLAVE_DEVICE_ADDRESS, VL53L1X_ADDR) < 0) return -1;

    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_INTERRUPT_CONFIG_GPIO, 0x04) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_RANGE_CONFIG, 0x00) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_INTERMEASUREMENT, 0x00) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_THRESHOLD_HIGH, 0x00) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_THRESHOLD_LOW, 0x00) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_CROSSTALK, 0x00) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_SIGNAL_RATE, 0x00) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_PHASECAL, 0x00) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_RANGE_TIMING, 0x00) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_RANGE_CONFIG_A, 0x00) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_RANGE_CONFIG_B, 0x00) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_RANGE_CONFIG_C, 0x00) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_RANGE_CONFIG_D, 0x00) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_RANGE_CONFIG_E, 0x00) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_RANGE_CONFIG_F, 0x00) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_RANGE_CONFIG_G, 0x00) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_RANGE_CONFIG_H, 0x00) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_RANGE_CONFIG_I, 0x00) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_RANGE_CONFIG_J, 0x00) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_RANGE_CONFIG_K, 0x00) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_RANGE_CONFIG_L, 0x00) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_RANGE_CONFIG_M, 0x00) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_RANGE_CONFIG_N, 0x00) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_RANGE_CONFIG_O, 0x00) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_RANGE_CONFIG_P, 0x00) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_RANGE_CONFIG_Q, 0x00) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_RANGE_CONFIG_R, 0x00) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_RANGE_CONFIG_S, 0x00) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_RANGE_CONFIG_T, 0x00) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_RANGE_CONFIG_U, 0x00) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_RANGE_CONFIG_V, 0x00) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_RANGE_CONFIG_W, 0x00) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_RANGE_CONFIG_X, 0x00) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_RANGE_CONFIG_Y, 0x00) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_RANGE_CONFIG_Z, 0x00) < 0) return -1;

    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_MODE_START, 0x00) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) < 0) return -1;

    return 0;
}

static int read_distance(int handle) {
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_MODE_START, 0x01) < 0) return -1;
    gpioDelay(10000);

    uint8_t status_buf[1];
    if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_INTERRUPT_STATUS, status_buf, 1) < 0) return -1;
    if ((status_buf[0] & 0x01) == 0) {
        i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01);
        return -1;
    }

    uint8_t dist_buf[2];
    if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_DISTANCE, dist_buf, 2) < 0) return -1;

    i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01);

    return (dist_buf[0] << 8) | dist_buf[1];
}

static void update_circular_buffer(int distance) {
    circular_buffer[buffer_index] = distance;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

static void control_led(int distance) {
    if (distance < DISTANCE_THRESHOLD) {
        gpioWrite(LED_GPIO, 1);
    } else {
        gpioWrite(LED_GPIO, 0);
    }
}

static void cleanup() {
    if (i2c_handle >= 0) {
        i2c_write_reg16(i2c_handle, VL53L1X_REG_SYSTEM_MODE_START, 0x00);
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    i2c_handle = i2cOpen(1, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (vl53l1x_init(i2c_handle) < 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        cleanup();
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    while (running) {
        int distance = read_distance(i2c_handle);
        if (distance >= 0) {
            update_circular_buffer(distance);
            control_led(distance);
            printf("Distance: %d mm\n", distance);
