#define VL53L1X_REG_RESULT_RANGE_STATUS 0x004D
#define VL53L1X_REG_RESULT_DISTANCE 0x0096
#define VL53L1X_REG_SYSTEM_INTERRUPT_CONFIG_GPIO 0x0046
#define VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR 0x0086
#define VL53L1X_REG_SYSTEM_SEQUENCE_CONFIG 0x0001
#define VL53L1X_REG_SYSTEM_RANGE_CONFIG 0x0002
#define VL53L1X_REG_SYSTEM_INTERMEASUREMENT 0x0004
#define VL53L1X_REG_SYSTEM_THRESHOLD_HIGH 0x0006
#define VL53L1X_REG_SYSTEM_THRESHOLD_LOW 0x0008
#define VL53L1X_REG_SYSTEM_CROSSTALK 0x000A
#define VL53L1X_REG_SYSTEM_SIGNAL_RATE 0x000C
#define VL53L1X_REG_SYSTEM_PHASECAL 0x000E
#define VL53L1X_REG_SYSTEM_RANGE_TIMING 0x0010
#define VL53L1X_REG_SYSTEM_RANGE_CONFIG_A 0x0012
#define VL53L1X_REG_SYSTEM_RANGE_CONFIG_B 0x0014
#define VL53L1X_REG_SYSTEM_RANGE_CONFIG_C 0x0016
