    if (i2c_handle >= 0) {
        i2c_write_reg16(i2c_handle, VL53L1X_REG_SYSTEM_MODE_START, 0x00);
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    i2c_handle = i2cOpen(1, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (vl53l1x_init(i2c_handle) < 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        cleanup();
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    while (running) {
        int distance = read_distance(i2c_handle);
        if (distance >= 0) {
            update_circular_buffer(distance);
            control_led(distance);
            printf("Distance: %d mm\n", distance);
        } else {
            fprintf(stderr, "Error reading distance\n");
        }
        gpioDelay(POLL_DELAY_US);
    }

    cleanup();
    return 0;
}

