#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <getopt.h>
#include <errno.h>
#include <pthread.h>
#include <pigpio.h>

#define DEFAULT_I2C_ADDRESS 0x60
#define DEFAULT_THRESHOLD 1000
#define GPIO_INTERRUPT_PIN 27
#define LOG_FILE_NAME "proximity.log"

#define SI1102_REG_PART_ID 0x00
#define SI1102_REG_HW_KEY 0x07
#define SI1102_REG_MEAS_RATE0 0x08
#define SI1102_REG_PS_LED21_SELECT 0x0F
#define SI1102_REG_PS1_ADC_GAIN 0x1B
#define SI1102_REG_PS1_ADC_COUNTER 0x1C
#define SI1102_REG_PS1_ADC_MISC 0x1D
#define SI1102_REG_PS1_DATA0 0x22
#define SI1102_REG_IRQ_ENABLE 0x03
#define SI1102_REG_IRQ_MODE1 0x04
#define SI1102_REG_IRQ_MODE2 0x05
#define SI1102_REG_IRQ_STATUS 0x06
#define SI1102_REG_COMMAND 0x18
#define SI1102_REG_RESPONSE 0x20

#define SI1102_CMD_RESET 0x01
#define SI1102_CMD_PS_FORCE 0x05
#define SI1102_CMD_PS_AUTO 0x06

static int i2c_handle = -1;
static FILE *log_file = NULL;
static int threshold = DEFAULT_THRESHOLD;
static int i2c_address = DEFAULT_I2C_ADDRESS;
static volatile sig_atomic_t program_running = 1;
static pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing 0x%02X to register 0x%02X: %s\n", value, reg, strerror(errno));
    }
    return result;
}

static int i2c_read_byte(int handle, uint8_t reg) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
    }
    return result;
}

static int i2c_read_word(int handle, uint8_t reg) {
    int result = i2cReadWordData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading word from register 0x%02X: %s\n", reg, strerror(errno));
    }
    return result;
}

static int si1102_reset(int handle) {
    if (i2c_write_byte(handle, SI1102_REG_COMMAND, SI1102_CMD_RESET) < 0) return -1;
    gpioDelay(10000);
    return 0;
}

static int si1102_init(int handle) {
    if (si1102_reset(handle) < 0) return -1;

    if (i2c_write_byte(handle, SI1102_REG_HW_KEY, 0x17) < 0) return -1;
    if (i2c_write_byte(handle, SI1102_REG_MEAS_RATE0, 0x08) < 0) return -1;
    if (i2c_write_byte(handle, SI1102_REG_PS_LED21_SELECT, 0x0F) < 0) return -1;
    if (i2c_write_byte(handle, SI1102_REG_PS1_ADC_GAIN, 0x20) < 0) return -1;
    if (i2c_write_byte(handle, SI1102_REG_PS1_ADC_COUNTER, 0x00) < 0) return -1;
    if (i2c_write_byte(handle, SI1102_REG_PS1_ADC_MISC, 0x00) < 0) return -1;

    if (i2c_write_byte(handle, SI1102_REG_IRQ_ENABLE, 0x00) < 0) return -1;
    if (i2c_write_byte(handle, SI1102_REG_IRQ_MODE1, 0x00) < 0) return -1;
    if (i2c_write_byte(handle, SI1102_REG_IRQ_MODE2, 0x00) < 0) return -1;

    if (i2c_write_byte(handle, SI1102_REG_COMMAND, SI1102_CMD_PS_AUTO) < 0) return -1;

    return 0;
}

static int read_proximity(int handle) {
    int low = i2c_read_byte(handle, SI1102_REG_PS1_DATA0);
    if (low < 0) return -1;
    int high = i2c_read_byte(handle, SI1102_REG_PS1_DATA0 + 1);
    if (high < 0) return -1;
    return (high << 8) | low;
}

static void log_data(int proximity_value, const char *status) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    pthread_mutex_lock(&log_mutex);
    if (log_file != NULL) {
        fprintf(log_file, "%s, Proximity: %d, Status: %s\n", timestamp, proximity_value, status);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
    pthread_mutex_unlock(&log_mutex);
}

static void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data) {
    (void)gpio;
    (void)level;
    (void)tick;
    (void)user_data;

    int proximity_value = read_proximity(i2c_handle);
    if (proximity_value < 0) {
        fprintf(stderr, "Error reading proximity value in interrupt handler.\n");
        return;
    }

    const char *status = (proximity_value <= threshold) ? "SAFE" : "ALERT";
    log_data(proximity_value, status);
}

static void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int opt;

    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = (int)strtol(optarg, NULL, 0);
                if (i2c_address < 0x08 || i2c_address > 0x77) {
                    fprintf(stderr, "Invalid I2C address: %s\n", optarg);
                    return 1;
                }
                break;
            case 't':
                threshold = (int)strtol(optarg, NULL, 0);
                if (threshold < 0) {
                    fprintf(stderr, "Invalid threshold: %s\n", optarg);
                    return 1;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-t threshold]\n", argv[0]);
                return 1;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, i2c_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (si1102_init(i2c_handle) < 0) {
        fprintf(stderr, "Error initializing Si1102 sensor\n");
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE_NAME, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    if (gpioSetMode(GPIO_INTERRUPT_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error setting GPIO mode: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    if (gpioSetPullUpDown(GPIO_INTERRUPT_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Error setting pull-down: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    if (gpioSetAlertFuncEx(GPIO_INTERRUPT_PIN, interrupt_handler, NULL) < 0) {
        fprintf(stderr, "Error setting alert function: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting signal handler: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    printf("Proximity sensor monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        gpioDelay(100000);
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return 0;
}

