/*
 * theremin.c — HC-SR04 ultrasonic distance sensor + PWM speaker on Raspberry Pi Zero W
 *
 * Hardware:
 *   HC-SR04  : TRIG -> GPIO23 (BCM), ECHO -> GPIO24 (BCM)
 *   Speaker : PWM0 (GPIO18, BCM) — 8 Ω, 50 % duty cycle
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o theremin theremin.c -lpigpio -lrt
 * Run:
 *   sudo ./theremin
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN      23
#define ECHO_PIN         24
#define PWM_PIN          18

#define MIN_DISTANCE_CM  2.0f
#define MAX_DISTANCE_CM  200.0f
#define MIN_FREQUENCY_HZ 200
#define MAX_FREQUENCY_HZ 2000
#define TIMEOUT_US       200000   /* 200 ms echo timeout */
#define TRIGGER_PULSE_US 10
#define LOOP_DELAY_US    50000    /* 50 ms between readings */
#define PWM_DUTY         500000   /* 50 % of 1 000 000 */

static volatile sig_atomic_t g_running = 1;
static int g_pigpio_ready = 0;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Measure distance (cm) from the HC-SR04.
 * Returns -1.0 on timeout or sensor error.
 */
static float measure_distance(void)
{
    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger, 0) failed\n");
        return -1.0f;
    }
    gpioDelay(5);

    /* 10 µs trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger, 1) failed\n");
        return -1.0f;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger, 0) failed\n");
        return -1.0f;
    }

    uint32_t start_tick = 0, end_tick = 0;
    uint32_t deadline = gpioTick() + TIMEOUT_US;

    /* Wait for echo rising edge */
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - deadline) >= 0) {
            fprintf(stderr, "Error: timeout waiting for echo rising edge\n");
            return -1.0f;
        }
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge */
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - deadline) >= 0) {
            fprintf(stderr, "Error: timeout waiting for echo falling edge\n");
            return -1.0f;
        }
    }
    end_tick = gpioTick();

    uint32_t diff = end_tick - start_tick;
    /* speed of sound ~343 m/s => 0.0343 cm/µs; round trip => /2 */
    return (float)diff * 0.0343f / 2.0f;
}

/*
 * Map distance (cm) to frequency (Hz) on a logarithmic scale.
 * Returns -1 on invalid distance.
 */
static int distance_to_frequency(float distance)
{
    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        fprintf(stderr, "Warning: distance %.2f cm out of range [%.0f, %.0f]\n",
                distance, MIN_DISTANCE_CM, MAX_DISTANCE_CM);
        return -1;
    }

    /* Logarithmic mapping: 2 cm -> 200 Hz, 200 cm -> 2000 Hz */
    float log_min = 2.0f;
    float log_max = 200.0f;
    float freq_min = MIN_FREQUENCY_HZ;
    float freq_max = MAX_FREQUENCY_HZ;

    float normalized = (distance - log_min) / (log_max - log_min);
    if (normalized < 0.0f) normalized = 0.0f;
    if (normalized > 1.0f) normalized = 1.0f;

    float freq = freq_min + normalized * (freq_max - freq_min);
    return (int)(freq + 0.5f);
}

/*
 * Set PWM frequency and duty cycle on GPIO18 (PWM0).
 * Returns 0 on success, -1 on error.
 */
static int set_pwm_frequency(int frequency)
{
    if (frequency <= 0) {
        fprintf(stderr, "Error: invalid frequency %d\n", frequency);
        return -1;
    }

    if (gpioSetPWMfrequency(PWM_PIN, frequency) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency(%d) failed\n", frequency);
        return -1;
    }

    if (gpioPWM(PWM_PIN, PWM_DUTY) < 0) {
        fprintf(stderr, "Error: gpioPWM(%d) failed\n", PWM_DUTY);
        return -1;
    }
    return 0;
}

static void cleanup(void)
{
    if (g_pigpio_ready) {
        gpioPWM(PWM_PIN, 0);
        gpioWrite(TRIGGER_PIN, 0);
        gpioTerminate();
        g_pigpio_ready = 0;
    }
}

int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }
    g_pigpio_ready = 1;

    /* Configure GPIO modes */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(TRIGGER_PIN) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(ECHO_PIN) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(PWM_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(PWM_PIN) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER_PIN, 0) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    int current_frequency = 0;

    while (g_running) {
        float distance = measure_distance();

        if (distance < 0.0f) {
            fprintf(stderr, "Warning: sensor read failed, keeping previous frequency\n");
        } else {
            int freq = distance_to_frequency(distance);
            if (freq < 0) {
                fprintf(stderr, "Warning: invalid distance, keeping previous frequency\n");
            } else {
                if (set_pwm_frequency(freq) == 0) {
                    current_frequency = freq;
                } else {
                    fprintf(stderr, "Error: failed to set PWM frequency\n");
                }
            }
        }

        gpioDelay(LOOP_DELAY_US);
    }

    fprintf(stderr, "\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

