#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define BUZZER_PIN  18

#define MIN_DISTANCE_CM 5.0
#define MAX_DISTANCE_CM 50.0
#define MIN_FREQUENCY_HZ 200
#define MAX_FREQUENCY_HZ 2000

#define ECHO_TIMEOUT_US 100000
#define LOOP_DELAY_US   10000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set trigger pin %d as output.\n", TRIGGER_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set echo pin %d as input.\n", ECHO_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error: failed to set pull-down on echo pin %d.\n", ECHO_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set buzzer pin %d as output.\n", BUZZER_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise trigger pin low.\n");
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void trigger_sensor(void) {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10);
    gpioWrite(TRIGGER_PIN, 0);
}

static long measure_echo_pulse(void) {
    uint32_t start_tick = 0;
    uint32_t end_tick   = 0;
    uint32_t timeout_start;

    timeout_start = gpioTick();

    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - timeout_start) >= ECHO_TIMEOUT_US) {
            return -1;
        }
    }

    start_tick = gpioTick();

    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - start_tick) >= ECHO_TIMEOUT_US) {
            return -1;
        }
    }

    end_tick = gpioTick();

    return (long)(end_tick - start_tick);
}

static float calculate_distance(long pulse_width_us) {
    if (pulse_width_us < 0) {
        return -1.0f;
    }
    return (pulse_width_us / 58.0f);
}

static int map_distance_to_frequency(float distance_cm) {
    if (distance_cm < MIN_DISTANCE_CM) {
        return MIN_FREQUENCY_HZ;
    }
    if (distance_cm > MAX_DISTANCE_CM) {
        return MAX_FREQUENCY_HZ;
    }
    return (int)(MIN_FREQUENCY_HZ +
                 (distance_cm - MIN_DISTANCE_CM) *
                 (MAX_FREQUENCY_HZ - MIN_FREQUENCY_HZ) /
                 (MAX_DISTANCE_CM - MIN_DISTANCE_CM));
}

static void generate_tone(int frequency_hz) {
    if (frequency_hz > 0) {
        gpioSetPWMfrequency(BUZZER_PIN, frequency_hz);
        gpioPWM(BUZZER_PIN, 128);
    } else {
        gpioPWM(BUZZER_PIN, 0);
    }
}

static void stop_tone(void) {
    gpioPWM(BUZZER_PIN, 0);
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    float last_valid_distance = 0.0f;
    int   last_valid_tone     = 0;

    while (g_running) {
        trigger_sensor();
        long pulse_width = measure_echo_pulse();

        if (pulse_width < 0) {
            fprintf(stderr, "Warning: echo timeout or sensor read failure.\n");
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

