    if (frequency_hz > 0) {
        gpioSetPWMfrequency(BUZZER_PIN, frequency_hz);
        gpioPWM(BUZZER_PIN, 128);
    } else {
        gpioPWM(BUZZER_PIN, 0);
    }
}

static void stop_tone(void) {
    gpioPWM(BUZZER_PIN, 0);
}

