        if (pulse_width < 0) {
            fprintf(stderr, "Warning: echo timeout or sensor read failure.\n");
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        float distance = calculate_distance(pulse_width);

        if (distance < 0.0f) {
            fprintf(stderr, "Warning: invalid distance calculation.\n");
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
            fprintf(stderr, "Warning: distance %.2f cm out of range. Using last valid value.\n", distance);
            distance = last_valid_distance;
        } else {
            last_valid_distance = distance;
        }

        int frequency = map_distance_to_frequency(distance);

        if (frequency != last_valid_tone) {
            generate_tone(frequency);
            last_valid_tone = frequency;
        }

        printf("Distance: %.2f cm, Frequency: %d Hz\n", distance, frequency);
        fflush(stdout);

        gpioDelay(LOOP_DELAY_US);
    }

    stop_tone();
    gpioTerminate();
    printf("\nProgram terminated gracefully.\n");
    return EXIT_SUCCESS;
}

