#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define TIMEOUT_US  50000   /* 50 ms timeout for echo */
#define MIN_DIST_CM 2.0
#define MAX_DIST_CM 400.0
#define THRESHOLD_CM 10.0
#define LOOP_DELAY_US 500000 /* 500 ms between measurements */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Measure the echo pulse width in microseconds.
 * Returns the pulse width in microseconds, or -1 on timeout / error.
 */
static long measure_echo_pulse(void)
{
    uint32_t start_tick, end_tick, timeout_tick;

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to write trigger low\n");
        return -1;
    }
    gpioDelay(5); /* settle */

    /* 10 µs trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to write trigger high\n");
        return -1;
    }
    gpioDelay(10);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to write trigger low\n");
        return -1;
    }

    /* Wait for echo rising edge */
    start_tick = gpioTick();
    timeout_tick = start_tick + TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: timeout waiting for echo rising edge\n");
            return -1;
        }
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge */
    timeout_tick = start_tick + TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: timeout waiting for echo falling edge\n");
            return -1;
        }
    }
    end_tick = gpioTick();

    return (long)(end_tick - start_tick);
}

static float calculate_distance(long pulse_width_us)
{
    /* Speed of sound ~343 m/s => 0.0343 cm/µs; round-trip halves it */
    return (float)pulse_width_us * 0.0343f / 2.0f;
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set trigger pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set echo pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Start with trigger low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialise trigger pin state\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Allow sensor to settle */
    gpioDelay(100000); /* 100 ms */

    if (signal(SIGINT, sigint_handler) == SIG_ERR) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");

    while (g_running) {
        long pulse = measure_echo_pulse();

        if (pulse < 0) {
            printf("Invalid reading\n");
        } else {
            float distance = calculate_distance(pulse);

            if (distance < MIN_DIST_CM || distance > MAX_DIST_CM) {
                printf("Invalid reading\n");
            } else {
                printf("Distance: %.2f cm\n", distance);
                if (distance < THRESHOLD_CM) {
                    printf("Too close!\n");
                }
            }
        }

        /* 500 ms delay between measurements */
        gpioDelay(LOOP_DELAY_US);
    }

    printf("\nExiting gracefully...\n");
    gpioTerminate();
    return EXIT_SUCCESS;
}

