/*
 * Raspberry Pi 4 Model B – TDK InvenSense ICU-20201 ultrasonic TOF sensor
 * SPI interface, continuous logging to distance_log.csv
 *
 * Wiring:
 *   ICU-20201 CS  -> GPIO8  (BCM, SPI0 CE0)
 *   ICU-20201 SDO -> GPIO9  (BCM, SPI0 MISO)
 *   ICU-20201 SCK -> GPIO11 (BCM, SPI0 SCLK)
 *   ICU-20201 VDD -> 3.3 V
 *   ICU-20201 GND -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o icu20201_log icu20201_log.c spi.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#include "spi.h"

/* ---- Configuration ---- */
#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U   /* 1 MHz – well within ICU-20201 limits */
#define SPI_MODE        0
#define SPI_BITS        8

#define CS_PIN          8          /* BCM GPIO8 (SPI0 CE0) */

#define LOG_FILE        "distance_log.csv"
#define SAMPLE_PERIOD_US 100000U   /* 100 ms between readings */

/* ICU-20201 register addresses (16-bit, big-endian on SPI) */
#define REG_WHO_AM_I    0x00
#define REG_DISTANCE    0x04
#define REG_CONFIG      0x06

#define WHO_AM_I_EXPECTED 0x20

/* Valid distance range: 200 mm .. 5000 mm */
#define MIN_DISTANCE_MM  200
#define MAX_DISTANCE_MM  5000

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static FILE     *g_log_fp = NULL;
static int       g_spi_fd = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_spi_fd >= 0) {
        spi_close(g_spi_fd);
        g_spi_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit register address + 8-bit value via SPI.
 * Returns 0 on success, -1 on error. */
static int spi_write_reg16(int fd, uint16_t addr, uint8_t value)
{
    uint8_t tx[3] = { (uint8_t)(addr >> 8), (uint8_t)(addr & 0xFF), value };
    uint8_t rx[3] = { 0 };

    if (spi_transfer(fd, tx, rx, sizeof(tx)) != (ssize_t)sizeof(tx)) {
        fprintf(stderr, "[ERROR] SPI write to reg 0x%04X failed: %s\n",
                addr, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit register address + 8-bit value via SPI.
 * Returns 0 on success and stores the value in *out, -1 on error. */
static int spi_read_reg16(int fd, uint16_t addr, uint8_t *out)
{
    uint8_t tx[3] = { (uint8_t)(addr >> 8), (uint8_t)(addr & 0xFF), 0x00 };
    uint8_t rx[3] = { 0 };

    if (spi_transfer(fd, tx, rx, sizeof(tx)) != (ssize_t)sizeof(tx)) {
        fprintf(stderr, "[ERROR] SPI read from reg 0x%04X failed: %s\n",
                addr, strerror(errno));
        return -1;
    }
    *out = rx[2];
    return 0;
}

/* ------------------------------------------------------------------ */
static int init_spi(void)
{
    int fd = spi_open(SPI_DEVICE, SPI_SPEED_HZ, SPI_MODE, SPI_BITS);
    if (fd < 0) {
        fprintf(stderr, "[ERROR] spi_open(%s) failed: %s\n",
                SPI_DEVICE, strerror(errno));
        return -1;
    }
    return fd;
}

/* ------------------------------------------------------------------ */
static int init_sensor(int fd)
{
    uint8_t who = 0;

    if (spi_read_reg16(fd, REG_WHO_AM_I, &who) != 0) {
        fprintf(stderr, "[ERROR] Sensor not responding on SPI (CS=GPIO%d).\n",
                CS_PIN);
        return -1;
    }
    if (who != WHO_AM_I_EXPECTED) {
        fprintf(stderr, "[ERROR] WHO_AM_I mismatch: got 0x%02X, expected 0x%02X.\n",
                who, WHO_AM_I_EXPECTED);
        return -1;
    }

    /* Minimal configuration: enable sensor, set default range. */
    if (spi_write_reg16(fd, REG_CONFIG, 0x01) != 0) {
        fprintf(stderr, "[ERROR] Failed to write CONFIG register.\n");
        return -1;
    }

    /* Allow sensor to settle after configuration. */
    usleep(100000);
    return 0;
}

/* ------------------------------------------------------------------ */
static int read_distance_mm(int fd, int *distance_mm)
{
    uint8_t dist = 0;

    if (spi_read_reg16(fd, REG_DISTANCE, &dist) != 0) {
        return -1;
    }

    /* Convert raw 8-bit value to mm (placeholder linear mapping). */
    *distance_mm = (int)dist * 10;

    if (*distance_mm < MIN_DISTANCE_MM || *distance_mm > MAX_DISTANCE_MM) {
        fprintf(stderr, "[WARN] Distance out of range: %d mm\n", *distance_mm);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static void log_distance(FILE *fp, int distance_mm)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r failed: %s\n", strerror(errno));
        return;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "[ERROR] strftime failed.\n");
        return;
    }

    if (fprintf(fp, "%s,%d\n", ts, distance_mm) < 0) {
        fprintf(stderr, "[ERROR] fprintf to log failed: %s\n", strerror(errno));
        return;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "[ERROR] fflush failed: %s\n", strerror(errno));
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;

    /* ---- Signal handling ---- */
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "[ERROR] Cannot open %s: %s\n",
                LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Initialize SPI ---- */
    g_spi_fd = init_spi();
    if (g_spi_fd < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Initialize sensor ---- */
    if (init_sensor(g_spi_fd) != 0) {
        fprintf(stderr, "[ERROR] Sensor initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("ICU-20201 initialized. Logging to %s. Press Ctrl+C to stop.\n",
           LOG_FILE);

    /* ---- Main loop ---- */
    while (g_running) {
        int distance_mm = 0;

        if (read_distance_mm(g_spi_fd, &distance_mm) == 0) {
            log_distance(g_log_fp, distance_mm);
            printf("Distance: %d mm\n", distance_mm);
        } else {
            fprintf(stderr, "[WARN] SPI read error – continuing.\n");
        }

        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

