#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define SI1175_I2C_ADDR 0x60
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "proximity_log.csv"
#define SAMPLE_INTERVAL_SEC 5

#define SI1175_REG_PART_ID 0x00
#define SI1175_REG_HW_KEY 0x07
#define SI1175_REG_MEAS_RATE 0x08
#define SI1175_REG_ALS_VIS_DATA0 0x22
#define SI1175_REG_ALS_VIS_DATA1 0x23

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_si1175(int fd) {
    uint8_t part_id = 0;
    if (i2c_read_reg8(fd, SI1175_REG_PART_ID, &part_id) != 0) {
        return -1;
    }
    if (part_id != 0x75) {
        fprintf(stderr, "Unexpected Part ID: 0x%02X (expected 0x75)\n", part_id);
        return -1;
    }

    if (i2c_write_reg8(fd, SI1175_REG_HW_KEY, 0x17) != 0) return -1;
    if (i2c_write_reg8(fd, SI1175_REG_MEAS_RATE, 0x08) != 0) return -1;

    return 0;
}

static int read_als_visible(int fd, uint16_t *als_visible) {
    uint8_t lo = 0, hi = 0;
    if (i2c_read_reg8(fd, SI1175_REG_ALS_VIS_DATA0, &lo) != 0) return -1;
    if (i2c_read_reg8(fd, SI1175_REG_ALS_VIS_DATA1, &hi) != 0) return -1;
    *als_visible = (uint16_t)((hi << 8) | lo);
    return 0;
}

static int log_data(FILE *fp, const char *timestamp, uint16_t als_visible) {
    if (fprintf(fp, "%s,%u\n", timestamp, als_visible) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp);
    return 0;
}

static void cleanup(void) {
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to set signal handlers: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SI1175_I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", SI1175_I2C_ADDR, strerror(errno));
        cleanup();
        return 1;
    }

    if (init_si1175(g_i2c_fd) != 0) {
        fprintf(stderr, "Si1175 initialization failed.\n");
        cleanup();
        return 1;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    fseek(g_log_fp, 0, SEEK_END);
    long file_size = ftell(g_log_fp);
    if (file_size == 0) {
        fprintf(g_log_fp, "timestamp,als_visible\n");
        fflush(g_log_fp);
    }

    printf("Si1175 initialized. Logging to %s every %d seconds. Press Ctrl+C to exit.\n", LOG_FILE, SAMPLE_INTERVAL_SEC);

    while (g_running) {
        uint16_t als_visible = 0;
        if (read_als_visible(g_i2c_fd, &als_visible) != 0) {
            fprintf(stderr, "Failed to read ALS visible data. Retrying in %d seconds.\n", SAMPLE_INTERVAL_SEC);
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        time_t rawtime = time(NULL);
        if (rawtime == (time_t)-1) {
            fprintf(stderr, "Failed to get current time: %s\n", strerror(errno));
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        struct tm *timeinfo = localtime(&rawtime);
        if (timeinfo == NULL) {
            fprintf(stderr, "Failed to convert time.\n");
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        char timestamp[32];
        if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo) == 0) {
            fprintf(stderr, "Failed to format timestamp.\n");
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        if (log_data(g_log_fp, timestamp, als_visible) != 0) {
            fprintf(stderr, "Failed to log data. Continuing.\n");
        }

        printf("Timestamp: %s, ALS Visible: %u\n", timestamp, als_visible);

        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return 0;
}

