#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SI1120_ADDR 0x60

#define SI1120_REG_PART_ID 0x00
#define SI1120_REG_HW_KEY 0x07
#define SI1120_REG_COMMAND 0x46
#define SI1120_REG_ALS_VIS_DATA0 0x22
#define SI1120_REG_ALS_VIS_DATA1 0x23
#define SI1120_REG_PS1_DATA0 0x24
#define SI1120_REG_PS1_DATA1 0x25

#define SI1120_PART_ID 0x01
#define SI1120_HW_KEY_VAL 0x17
#define SI1120_RESET_CMD 0x01
#define SI1120_ALS_PS_AUTO 0x07

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t value) {
    for (int attempt = 0; attempt < 3; attempt++) {
        int result = i2cWriteByteData(handle, reg, value);
        if (result == 0) return 0;
        fprintf(stderr, "I2C write attempt %d failed (reg=0x%02X, val=0x%02X, rc=%d)\n",
                attempt + 1, reg, value, result);
        gpioDelay(10000);
    }
    return -1;
}

static int i2c_read_byte(int handle, uint8_t reg, uint8_t *value) {
    for (int attempt = 0; attempt < 3; attempt++) {
        int result = i2cReadByteData(handle, reg);
        if (result >= 0) {
            *value = (uint8_t)result;
            return 0;
        }
        fprintf(stderr, "I2C read attempt %d failed (reg=0x%02X, rc=%d)\n",
                attempt + 1, reg, result);
        gpioDelay(10000);
    }
    return -1;
}

static int si1120_init(int handle) {
    uint8_t part_id = 0;
    if (i2c_read_byte(handle, SI1120_REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "Failed to read PART_ID\n");
        return -1;
    }
    if (part_id != SI1120_PART_ID) {
        fprintf(stderr, "Unexpected PART_ID: 0x%02X (expected 0x%02X)\n",
                part_id, SI1120_PART_ID);
        return -1;
    }

    if (i2c_write_byte(handle, SI1120_REG_COMMAND, SI1120_RESET_CMD) != 0) {
        fprintf(stderr, "Failed to send reset command\n");
        return -1;
    }
    gpioDelay(10000);

    if (i2c_write_byte(handle, SI1120_REG_HW_KEY, SI1120_HW_KEY_VAL) != 0) {
        fprintf(stderr, "Failed to write HW_KEY\n");
        return -1;
    }

    if (i2c_write_byte(handle, SI1120_REG_COMMAND, SI1120_ALS_PS_AUTO) != 0) {
        fprintf(stderr, "Failed to start ALS/PS auto mode\n");
        return -1;
    }

    return 0;
}

static int read_si1120_data(int handle, uint16_t *ambient_light, uint16_t *proximity) {
    uint8_t als_lo, als_hi, ps_lo, ps_hi;

    if (i2c_read_byte(handle, SI1120_REG_ALS_VIS_DATA0, &als_lo) != 0) return -1;
    if (i2c_read_byte(handle, SI1120_REG_ALS_VIS_DATA1, &als_hi) != 0) return -1;
    if (i2c_read_byte(handle, SI1120_REG_PS1_DATA0, &ps_lo) != 0) return -1;
    if (i2c_read_byte(handle, SI1120_REG_PS1_DATA1, &ps_hi) != 0) return -1;

    *ambient_light = (uint16_t)((als_hi << 8) | als_lo);
    *proximity = (uint16_t)((ps_hi << 8) | ps_lo);
    return 0;
}

static void log_data(FILE *fp, uint16_t ambient_light, uint16_t proximity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s, Ambient Light: %u, Proximity: %u\n",
            timestamp, ambient_light, proximity);
    fflush(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, SI1120_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02X: %d\n",
                SI1120_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (si1120_init(i2c_handle) != 0) {
        fprintf(stderr, "Si1120 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("si1120_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Failed to register SIGINT handler");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

