#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_DEVICE "/dev/i2c-1"
#define SI1182_ADDR 0x60

#define REG_PART_ID 0x00
#define REG_ALS_RATE 0x08
#define REG_PROX_RATE 0x09
#define REG_ALS_DATA 0x22
#define REG_PROX_DATA 0x24

#define EXPECTED_PART_ID 0x82

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read 16-bit from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int init_sensor(int fd) {
    uint8_t part_id = 0;
    if (i2c_read_reg8(fd, REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "Failed to read Part ID - sensor may be absent or bus error.\n");
        return -1;
    }
    if (part_id != EXPECTED_PART_ID) {
        fprintf(stderr, "Unexpected Part ID: 0x%02X (expected 0x%02X). Check wiring.\n", part_id, EXPECTED_PART_ID);
        return -1;
    }
    printf("Si1182 detected (Part ID: 0x%02X).\n", part_id);

    if (i2c_write_reg8(fd, REG_ALS_RATE, 0x0A) != 0) return -1;
    if (i2c_write_reg8(fd, REG_PROX_RATE, 0x0A) != 0) return -1;
    return 0;
}

static int read_sensor_data(int fd, float *lux, uint16_t *proximity) {
    uint16_t als_data = 0;
    if (i2c_read_reg16(fd, REG_ALS_DATA, &als_data) != 0) return -1;
    if (i2c_read_reg16(fd, REG_PROX_DATA, proximity) != 0) return -1;

    *lux = (float)als_data * 0.1f;
    return 0;
}

static void log_data(FILE *fp, float lux, uint16_t proximity) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(fp, "%s.%03ld,%.2f,%u\n", timestamp, ts.tv_nsec / 1000000, lux, proximity);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SI1182_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    if (init_sensor(i2c_fd) != 0) {
        fprintf(stderr, "Sensor initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    log_file = fopen("biometric_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    printf("Logging started. Press Ctrl+C to stop.\n");

    while (running) {
        float lux = 0.0f;
        uint16_t proximity = 0;
        if (read_sensor_data(i2c_fd, &lux, &proximity) == 0) {
            log_data(log_file, lux, proximity);
            printf("Lux: %.2f, Proximity: %u\n", lux, proximity);
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }
        usleep(100000);
    }

    printf("\nShutting down...\n");
    if (log_file) fclose(log_file);
    if (i2c_fd >= 0) close(i2c_fd);
    return 0;
}

