#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SI1145_ADDR 0x60
#define SI1145_REG_PART_ID 0x00
#define SI1145_REG_HW_KEY 0x07
#define SI1145_REG_MEAS_RATE0 0x08
#define SI1145_REG_PS1_DATA0 0x22
#define SI1145_REG_PS1_DATA1 0x23
#define SI1145_REG_COMMAND 0x30
#define SI1145_CMD_RESET 0x01
#define SI1145_CMD_PS_FORCE 0x05
#define SI1145_HW_KEY_VAL 0x17
#define LOG_FILE "proximity_log.txt"
#define MAX_RETRIES 3

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing to register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

static int read_register(int handle, uint8_t reg) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading from register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return result;
}

static int init_si1145(int handle) {
    if (write_register(handle, SI1145_REG_COMMAND, SI1145_CMD_RESET) < 0) {
        return -1;
    }
    gpioDelay(10000);
    if (write_register(handle, SI1145_REG_HW_KEY, SI1145_HW_KEY_VAL) < 0) {
        return -1;
    }
    if (write_register(handle, SI1145_REG_MEAS_RATE0, 0x08) < 0) {
        return -1;
    }
    return 0;
}

static int read_proximity(int handle, uint16_t *proximity) {
    int low = read_register(handle, SI1145_REG_PS1_DATA0);
    if (low < 0) {
        return -1;
    }
    int high = read_register(handle, SI1145_REG_PS1_DATA1);
    if (high < 0) {
        return -1;
    }
    *proximity = (uint16_t)((high << 8) | low);
    return 0;
}

static void log_data(FILE *fp, uint16_t proximity) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, %u\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, (unsigned)proximity);
    fflush(fp);
}

static void log_error(FILE *fp, const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, ERROR: %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_si1145(i2c_handle) < 0) {
        fprintf(stderr, "Si1145 initialisation failed\n");
        log_error(log_file, "Si1145 initialisation failed");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    uint16_t proximity;
    int retries;

    while (!terminate) {
        retries = 0;
        while (retries < MAX_RETRIES && !terminate) {
            if (read_proximity(i2c_handle, &proximity) == 0) {
                log_data(log_file, proximity);
                break;
            }
            retries++;
            if (retries < MAX_RETRIES) {
                gpioDelay(100000);
            }
        }
        if (retries == MAX_RETRIES) {
            fprintf(stderr, "Failed to read proximity after %d retries\n", MAX_RETRIES);
            log_error(log_file, "Failed to read proximity after retries");
            break;
        }
        gpioDelay(100000);
    }

    if (log_file != NULL) {
        fclose(log_file);
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

