#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define BUZZER_PIN  27
#define DISTANCE_THRESHOLD 20.0
#define SPEED_OF_SOUND 34300.0
#define TRIGGER_PULSE_US 10
#define POLL_INTERVAL_US 1000000

static volatile sig_atomic_t g_running = 1;
static volatile uint32_t g_start_tick = 0;
static volatile uint32_t g_end_tick   = 0;
static volatile int      g_echo_state = 0;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void echo_callback(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio;
    (void)userdata;

    if (level == 1) {
        g_start_tick = tick;
        g_echo_state = 1;
    } else if (level == 0 && g_echo_state == 1) {
        g_end_tick = tick;
        g_echo_state = 0;
    }
}

static double calculate_distance(uint32_t start_tick, uint32_t end_tick) {
    double pulse_width = (double)(end_tick - start_tick);
    return (pulse_width / 1000000.0) * SPEED_OF_SOUND / 2.0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set trigger pin mode.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set echo pin mode.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set buzzer pin mode.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise trigger pin low.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(BUZZER_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise buzzer pin low.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Error: failed to set echo alert callback.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to install SIGINT handler.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Ultrasonic distance measurement started. Press Ctrl+C to exit.\n");

    while (g_running) {
        g_echo_state = 0;
        g_start_tick = 0;
        g_end_tick   = 0;

        if (gpioWrite(TRIGGER_PIN, 1) != 0) {
            fprintf(stderr, "Error: failed to set trigger high.\n");
            break;
        }
        gpioDelay(TRIGGER_PULSE_US);
        if (gpioWrite(TRIGGER_PIN, 0) != 0) {
            fprintf(stderr, "Error: failed to set trigger low.\n");
            break;
        }

        uint32_t wait_start = gpioTick();
        while (g_echo_state == 1 && (gpioTick() - wait_start) < 30000) {
            gpioDelay(100);
        }

        if (g_echo_state == 1) {
            double distance = calculate_distance(g_start_tick, g_end_tick);
            printf("Distance: %.2f cm\n", distance);

            if (distance < DISTANCE_THRESHOLD) {
                if (gpioWrite(BUZZER_PIN, 1) != 0) {
                    fprintf(stderr, "Error: failed to set buzzer high.\n");
                    break;
                }
            } else {
                if (gpioWrite(BUZZER_PIN, 0) != 0) {
                    fprintf(stderr, "Error: failed to set buzzer low.\n");
                    break;
                }
            }
        } else {
            printf("Distance: out of range\n");
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    gpioWrite(BUZZER_PIN, 0);
    gpioWrite(TRIGGER_PIN, 0);
    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);
    gpioTerminate();
    printf("\nProgram terminated cleanly.\n");
    return EXIT_SUCCESS;
}

