#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 4
#define ECHO_PIN 17
#define SERVO_PIN 18

#define SPEED_OF_SOUND_CM_PER_US 0.0343
#define TIMEOUT_US 30000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static double measure_distance(void) {
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to set trigger high\n");
        return -1.0;
    }
    gpioDelay(10);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to set trigger low\n");
        return -1.0;
    }

    uint32_t start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if ((gpioTick() - start_tick) > TIMEOUT_US) {
            fprintf(stderr, "Error: echo start timeout\n");
            return -1.0;
        }
    }
    uint32_t echo_start = gpioTick();

    while (gpioRead(ECHO_PIN) == 1) {
        if ((gpioTick() - echo_start) > TIMEOUT_US) {
            fprintf(stderr, "Error: echo end timeout\n");
            return -1.0;
        }
    }
    uint32_t echo_end = gpioTick();

    uint32_t pulse_width = echo_end - echo_start;
    return (double)pulse_width * SPEED_OF_SOUND_CM_PER_US / 2.0;
}

static int calculate_servo_angle(double distance) {
    if (distance < 20.0) return 180;
    if (distance < 110.0) return 90;
    if (distance < 200.0) return 0;
    return 0;
}

static int set_servo_angle(int angle) {
    if (angle < 0 || angle > 180) {
        fprintf(stderr, "Error: invalid servo angle %d\n", angle);
        return -1;
    }
    int pulse_width = 500 + (angle * 1000 / 180);
    if (gpioServo(SERVO_PIN, pulse_width) < 0) {
        fprintf(stderr, "Error: gpioServo failed\n");
        return -1;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set trigger pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set echo pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set servo pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialise trigger low\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: failed to install signal handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Parking Assist System started. Press Ctrl+C to exit.\n");

    while (running) {
        double distance = measure_distance();
        if (distance < 0.0) {
            fprintf(stderr, "Error: sensor read failed, retrying...\n");
            gpioDelay(100000);
            continue;
        }

        int angle = calculate_servo_angle(distance);
        if (set_servo_angle(angle) < 0) {
            fprintf(stderr, "Error: failed to set servo angle\n");
        }

        printf("Distance: %.2f cm, Servo Angle: %d\n", distance, angle);
        gpioDelay(100000);
    }

    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

