/*
 * VL53L1X Gate Controller for Raspberry Pi 3 Model B+
 *
 * Hardware:
 *   - VL53L1X time-of-flight sensor on I2C bus 1, address 0x29
 *   - Servo gate on GPIO18 (BCM), 1000-2000 us PWM pulse width
 *
 * Build:
 *   gcc -O2 -Wall -o gate_ctrl gate_ctrl.c -lpigpio -lrt
 * Run:
 *   sudo ./gate_ctrl
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define VL53L1X_ADDR         0x29
#define GPIO_GATE            18          /* BCM pin for servo PWM */

#define DISTANCE_THRESHOLD_CLOSE  200   /* mm  -> pulse 2000 us */
#define DISTANCE_THRESHOLD_FAR    250   /* mm  -> pulse 1000 us */

#define SERVO_PULSE_CLOSE       1000    /* us */
#define SERVO_PULSE_FAR         2000    /* us */

#define LOG_FILE               "gate_log.txt"
#define POLL_DELAY_US          100000   /* 100 ms */
#define SERVO_SETTLE_US        500000   /* 500 ms */

/* VL53L1X register addresses (16-bit, big-endian on bus) */
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID     0x010F
#define VL53L1X_REG_SYSTEM_MODE_START           0x0000
#define VL53L1X_REG_RESULT_RANGE_STATUS         0x0089
#define VL53L1X_REG_RESULT_DISTANCE             0x0096

#define VL53L1X_MODEL_ID                        0xEA
#define VL53L1X_START_RANGING_CMD              0x01
#define VL53L1X_STOP_RANGING_CMD               0x00

/* ------------------------------- Globals --------------------------------- */
static int           i2c_handle = -1;
static FILE         *log_file   = NULL;
static volatile sig_atomic_t terminate = 0;

/* --------------------------- Function prototypes ------------------------- */
static int  i2c_read_reg16(int handle, uint16_t reg, uint8_t *buf, uint32_t len);
static int  i2c_write_reg16(int handle, uint16_t reg, uint8_t value);
static int  vl53l1x_init(int handle);
static int  vl53l1x_start_ranging(int handle);
static int  vl53l1x_stop_ranging(int handle);
static int  vl53l1x_read_distance(int handle, uint16_t *distance_mm);
static void set_servo_pulse(int gpio, int pulse_width_us);
static void log_event(const char *event);
static void signal_handler(int sig);
static void cleanup(void);

/* ------------------------------- I2C helpers ----------------------------- */
static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *buf, uint32_t len)
{
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;

    if (i2cWriteDevice(handle, reg_buf, 2) != 0)
        return -1;

    if (i2cReadDevice(handle, (char *)buf, len) != (int)len)
        return -1;

    return 0;
}

static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;

    return (i2cWriteDevice(handle, buf, 3) == 0) ? 0 : -1;
}

/* ------------------------------- VL53L1X driver -------------------------- */
static int vl53l1x_init(int handle)
{
    uint8_t model_id = 0;

    if (i2c_read_reg16(handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID,
                       &model_id, 1) != 0) {
        fprintf(stderr, "Error: Failed to read model ID register.\n");
        return -1;
    }

    if (model_id != VL53L1X_MODEL_ID) {
        fprintf(stderr,
                "Error: Unexpected model ID 0x%02X (expected 0x%02X).\n",
                model_id, VL53L1X_MODEL_ID);
        return -1;
    }

    printf("VL53L1X detected (model ID 0x%02X).\n", model_id);
    return 0;
}

static int vl53l1x_start_ranging(int handle)
{
    return i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_MODE_START,
                           VL53L1X_START_RANGING_CMD);
}

static int vl53l1x_stop_ranging(int handle)
{
    return i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_MODE_START,
                           VL53L1X_STOP_RANGING_CMD);
}

static int vl53l1x_read_distance(int handle, uint16_t *distance_mm)
{
    uint8_t status = 0;
    uint8_t dist_buf[2] = {0, 0};

    if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_RANGE_STATUS,
                       &status, 1) != 0) {
        fprintf(stderr, "Error: Failed to read range status.\n");
        return -1;
    }

    if (status & 0x01) {                       /* new sample ready */
        if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_DISTANCE,
                           dist_buf, 2) != 0) {
            fprintf(stderr, "Error: Failed to read distance register.\n");
            return -1;
        }
        *distance_mm = ((uint16_t)dist_buf[0] << 8) | dist_buf[1];
        return 0;
    }

    return 1;                                 /* no new data yet */
}

/* ------------------------------- Servo control --------------------------- */
static void set_servo_pulse(int gpio, int pulse_width_us)
{
    /* pigpio hardware PWM on GPIO18: 50 Hz, duty cycle in range 0-1M */
    gpioHardwarePWM(gpio, 50, (pulse_width_us * 1000000ULL) / 25000000ULL);
}

/* ------------------------------- Logging --------------------------------- */
static void log_event(const char *event)
{
    if (log_file == NULL)
        return;

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL)
        return;

    fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d - %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, event);
    fflush(log_file);
}

/* ------------------------------- Signal handler -------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ------------------------------- Cleanup --------------------------------- */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        vl53l1x_stop_ranging(i2c_handle);
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }

    /* Stop PWM signal and set GPIO low */
    gpioHardwarePWM(GPIO_GATE, 0, 0);
    gpioWrite(GPIO_GATE, 0);

    if (log_file != NULL) {
        log_event("Program terminated.");
        fclose(log_file);
        log_file = NULL;
    }

    gpioTerminate();
}

/* --------------------------------- Main ---------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at addr 0x%02X.\n",
                I2C_BUS, VL53L1X_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (vl53l1x_init(i2c_handle) != 0) {
        fprintf(stderr, "Error: VL53L1X initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Start ranging */
    if (vl53l1x_start_ranging(i2c_handle) != 0) {
        fprintf(stderr, "Error: Failed to start VL53L1X ranging.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure GPIO18 for hardware PWM */
    gpioSetMode(GPIO_GATE, PI_OUTPUT);
    gpioWrite(GPIO_GATE, 0);

    /* Open log file */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s'.\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Register signal handler */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Gate control running. Press Ctrl+C to exit.\n");
    log_event("Program started.");

    int gate_open = 0;
    int last_pulse = SERVO_PULSE_FAR;          /* start far */

    while (!terminate) {
        uint16_t distance = 0;
        int rc = vl53l1x_read_distance(i2c_handle, &distance);

        if (rc == 0) {
            int pulse_width;
            if (distance < DISTANCE_THRESHOLD_CLOSE) {
                pulse_width = SERVO_PULSE_CLOSE;
            } else {
                pulse_width = SERVO_PULSE_FAR;
            }

            if (pulse_width != last_pulse) {
                set_servo_pulse(GPIO_GATE, pulse_width);
                last_pulse = pulse_width;
            }

            if (distance < DISTANCE_THRESHOLD_CLOSE && !gate_open) {
                log_event("Gate opened.");
                gate_open = 1;
            } else if (distance >= DISTANCE_THRESHOLD_CLOSE && gate_open) {
                log_event("Gate closed.");
                gate_open = 0;
            }
        } else if (rc < 0) {
            fprintf(stderr, "Error: I2C communication failure.\n");
            log_event("I2C communication failure.");
        }

        gpioDelay(POLL_DELAY_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

