/*
 * HC-SR04 ultrasonic distance sensor → SG90 servo angle mapper
 * Board: Raspberry Pi 4 Model B
 * Trigger: GPIO23 (BCM)   Echo: GPIO24 (BCM)
 * Servo:   GPIO18 (BCM), 5 V, common ground with Pi
 *
 * Build:  gcc -O2 -Wall -Wextra -o hcsr04_servo hcsr04_servo.c sg90.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <errno.h>
#include <string.h>

#include "sg90.h"

/* ----------------------------- Configuration ----------------------------- */
#define TRIGGER_PIN  23          /* BCM pin for HC-SR04 trigger */
#define ECHO_PIN     24          /* BCM pin for HC-SR04 echo     */
#define SERVO_PIN    18          /* BCM pin for SG90 control     */

#define SPEED_OF_SOUND_CM_S  34300.0   /* cm/s at ~20 °C */

#define MIN_DISTANCE_CM  2.0
#define MAX_DISTANCE_CM  400.0
#define MIN_ANGLE_DEG    0.0
#define MAX_ANGLE_DEG    180.0

#define THRESHOLD_CLOSE_CM  20.0
#define THRESHOLD_FAR_CM    200.0

#define TRIGGER_PULSE_US   10
#define ECHO_TIMEOUT_US    50000      /* 50 ms */
#define LOOP_DELAY_MS      100

/* ----------------------------- Globals ---------------------------------- */
static volatile sig_atomic_t g_running = 1;

/* ----------------------------- Signal handler ---------------------------- */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ----------------------------- Timing helpers ---------------------------- */
static uint64_t now_us(void)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
        return 0;
    }
    return (uint64_t)ts.tv_sec * 1000000ULL + (uint64_t)ts.tv_nsec / 1000ULL;
}

static int wait_for_level(int pin, int level, uint64_t timeout_us)
{
    uint64_t deadline = now_us() + timeout_us;
    while (g_running) {
        int v = gpio_read(pin);
        if (v < 0) {
            return -1;
        }
        if (v == level) {
            return 0;
        }
        if (now_us() >= deadline) {
            return 1;                 /* timeout */
        }
    }
    return 1;
}

/* ----------------------------- HC-SR04 ----------------------------------- */
/*
 * Returns distance in cm, or -1.0 on timeout / error.
 */
static float measure_distance(void)
{
    if (gpio_write(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to set trigger low\n");
        return -1.0f;
    }
    usleep(2);                       /* let line settle */

    if (gpio_write(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to set trigger high\n");
        return -1.0f;
    }
    usleep(TRIGGER_PULSE_US);
    if (gpio_write(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to set trigger low\n");
        return -1.0f;
    }

    if (wait_for_level(ECHO_PIN, 1, ECHO_TIMEOUT_US) != 0) {
        fprintf(stderr, "Warning: echo rising-edge timeout\n");
        return -1.0f;
    }

    uint64_t t0 = now_us();

    if (wait_for_level(ECHO_PIN, 0, ECHO_TIMEOUT_US) != 0) {
        fprintf(stderr, "Warning: echo falling-edge timeout\n");
        return -1.0f;
    }

    uint64_t t1 = now_us();
    uint64_t elapsed_us = t1 - t0;

    float distance = (float)elapsed_us * SPEED_OF_SOUND_CM_S / 2000000.0f;

    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        fprintf(stderr, "Warning: distance %.2f cm out of range\n", distance);
        return -1.0f;
    }
    return distance;
}

/* ----------------------------- Servo mapping ----------------------------- */
static int distance_to_angle(float distance)
{
    if (distance < 0.0f) {
        return -1;
    }
    if (distance <= THRESHOLD_CLOSE_CM) {
        return 0;
    }
    if (distance >= THRESHOLD_FAR_CM) {
        return 180;
    }
    float frac = (distance - THRESHOLD_CLOSE_CM) /
                 (THRESHOLD_FAR_CM - THRESHOLD_CLOSE_CM);
    return (int)(MIN_ANGLE_DEG + frac * (MAX_ANGLE_DEG - MIN_ANGLE_DEG));
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    /* --- Signal handling --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* --- GPIO init --- */
    if (gpio_init() != 0) {
        fprintf(stderr, "Error: gpio_init() failed\n");
        return EXIT_FAILURE;
    }

    if (gpio_set_mode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: cannot set trigger pin %d as output\n", TRIGGER_PIN);
        gpio_term();
        return EXIT_FAILURE;
    }
    if (gpio_set_mode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: cannot set echo pin %d as input\n", ECHO_PIN);
        gpio_term();
        return EXIT_FAILURE;
    }
    if (gpio_set_mode(SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: cannot set servo pin %d as output\n", SERVO_PIN);
        gpio_term();
        return EXIT_FAILURE;
    }

    /* --- Servo driver init --- */
    if (sg90_init(SERVO_PIN) != 0) {
        fprintf(stderr, "Error: sg90_init() failed\n");
        gpio_term();
        return EXIT_FAILURE;
    }

    /* --- Ensure servo starts at a known position --- */
    if (sg90_set_angle(90) != 0) {
        fprintf(stderr, "Error: initial servo position failed\n");
        sg90_stop();
        gpio_term();
        return EXIT_FAILURE;
    }
    usleep(500000);                  /* allow servo to settle */

    printf("HC-SR04 → SG90 distance mapper running. Press Ctrl+C to exit.\n");

    /* --- Main loop --- */
    while (g_running) {
        float distance = measure_distance();

        if (distance < 0.0f) {
            fprintf(stderr, "Error: measurement failed; keeping current angle\n");
        } else {
            int angle = distance_to_angle(distance);
            if (angle < 0) {
                fprintf(stderr, "Error: invalid angle calculation\n");
            } else {
                if (sg90_set_angle(angle) != 0) {
                    fprintf(stderr, "Error: sg90_set_angle(%d) failed\n", angle);
                } else {
                    printf("Distance: %.2f cm  →  Angle: %d°\n", distance, angle);
                }
            }
        }

        if (g_running) {
            usleep(LOOP_DELAY_MS * 1000);
        }
    }

    /* --- Graceful shutdown --- */
    printf("\nShutting down...\n");
    sg90_set_angle(0);               /* stop servo (0°) */
    sg90_stop();
    gpio_term();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

