/*
 * MPU-6050 I2C reader for Raspberry Pi 3 Model B+
 * Bus: I2C-1 (GPIO2 = SDA, GPIO3 = SCL)
 * Sensor address: 0x68 (AD0 tied to GND)
 *
 * Build: gcc -O2 -Wall -o mpu6050 mpu6050.c -li2c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MPU6050_ADDR   0x68

/* MPU-6050 registers */
#define REG_SMPLRT_DIV   0x19
#define REG_CONFIG       0x1A
#define REG_GYRO_CONFIG  0x1B
#define REG_ACCEL_CONFIG 0x1C
#define REG_ACCEL_XOUT_H 0x3B
#define REG_GYRO_XOUT_H  0x43
#define REG_TEMP_OUT_H   0x41
#define REG_WHO_AM_I     0x75

#define WHO_AM_I_EXPECTED 0x68

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1)
        return -1;
    if (read(fd, val, 1) != 1)
        return -1;
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2)
        return -1;
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1)
        return -1;
    if (read(fd, buf, len) != (ssize_t)len)
        return -1;
    return 0;
}

static int16_t be16(const uint8_t *p)
{
    return (int16_t)((uint16_t)p[0] << 8 | (uint16_t)p[1]);
}

static void sleep_ms(unsigned ms)
{
    struct timespec ts = {
        .tv_sec  = ms / 1000,
        .tv_nsec = (long)(ms % 1000) * 1000000L
    };
    nanosleep(&ts, NULL);
}

int main(void)
{
    int fd = -1;
    int rc = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                MPU6050_ADDR, strerror(errno));
        goto cleanup;
    }

    uint8_t who = 0;
    if (i2c_read_reg8(fd, REG_WHO_AM_I, &who) < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I: %s\n", strerror(errno));
        goto cleanup;
    }
    if (who != WHO_AM_I_EXPECTED) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who, WHO_AM_I_EXPECTED);
        goto cleanup;
    }

    /* Wake up the sensor: clear sleep bit, set DLPF_CFG = 0 */
    if (i2c_write_reg8(fd, REG_SMPLRT_DIV, 0x07) < 0) {
        fprintf(stderr, "write SMPLRT_DIV: %s\n", strerror(errno));
        goto cleanup;
    }
    if (i2c_write_reg8(fd, REG_CONFIG, 0x00) < 0) {
        fprintf(stderr, "write CONFIG: %s\n", strerror(errno));
        goto cleanup;
    }
    if (i2c_write_reg8(fd, REG_GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "write GYRO_CONFIG: %s\n", strerror(errno));
        goto cleanup;
    }
    if (i2c_write_reg8(fd, REG_ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "write ACCEL_CONFIG: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("MPU-6050 initialized on %s (addr 0x%02X). Logging every 100 ms.\n",
           I2C_BUS, MPU6050_ADDR);
    fflush(stdout);

    while (g_running) {
        uint8_t buf[14];
        if (i2c_read_burst(fd, REG_ACCEL_XOUT_H, buf, sizeof(buf)) < 0) {
            fprintf(stderr, "I2C burst read failed: %s\n", strerror(errno));
            break;
        }

        int16_t ax = be16(&buf[0]);
        int16_t ay = be16(&buf[2]);
        int16_t az = be16(&buf[4]);
        int16_t t  = be16(&buf[6]);
        int16_t gx = be16(&buf[8]);
        int16_t gy = be16(&buf[10]);
        int16_t gz = be16(&buf[12]);

        printf("Accel: X=%6d Y=%6d Z=%6d  |  Gyro: X=%6d Y=%6d Z=%6d  |  Temp: %6d\n",
               ax, ay, az, gx, gy, gz, t);
        fflush(stdout);

        sleep_ms(100);
    }

    printf("\nShutting down cleanly.\n");
    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0)
        close(fd);
    return rc;
}

