code:
/*
 * SHT40 temperature & humidity reader for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   SHT40 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   SHT40 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   SHT40 VDD  -> 3.3 V
 *   SHT40 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o sht40 sht40.c -lpigpio -lrt
 * Run:    sudo ./sht40
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define SHT40_ADDR        0x61          /* SHT40 default I2C address (ADDR pin low) */
#define SHT40_CMD_MEASURE 0xFD          /* high-repeatability, clock-stretching */
#define SHT40_MEASURE_MS  10            /* max conversion time ~8.5 ms; 10 ms is safe */
#define SAMPLE_PERIOD_S   5             /* seconds between readings */
#define I2C_BUS           1             /* /dev/i2c-1 on RPi 4 */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (polynomial 0x31, init 0xFF, no final XOR) — SHT40 datasheet  */
/* ------------------------------------------------------------------ */
static bool sht40_crc_ok(const uint8_t *data, uint8_t expected)
{
    uint8_t crc = 0xFF;
    for (int i = 0; i < 2; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            crc = (crc & 0x80) ? (uint8_t)((crc << 1) ^ 0x31)
                               : (uint8_t)(crc << 1);
        }
    }
    return crc == expected;
}

/* ------------------------------------------------------------------ */
/* Read temperature (°C) and humidity (%RH) from the SHT40.            */
/* Returns 0 on success, -1 on I2C error, -2 on CRC mismatch.          */
/* ------------------------------------------------------------------ */
static int sht40_read(int handle, float *temperature, float *humidity)
{
    uint8_t cmd = SHT40_CMD_MEASURE;
    uint8_t buf[6];

    /* Send measurement command (single byte, no register address). */
    if (i2cWriteDevice(handle, (char *)&cmd, 1) != 0) {
        fprintf(stderr, "[SHT40] I2C write error (cmd 0x%02X)\n", cmd);
        return -1;
    }

    /* Wait for conversion to complete. */
    gpioDelay(SHT40_MEASURE_MS * 1000);  /* microseconds */

    /* Read 6 bytes: T_MSB, T_LSB, T_CRC, RH_MSB, RH_LSB, RH_CRC */
    if (i2cReadDevice(handle, (char *)buf, 6) != 6) {
        fprintf(stderr, "[SHT40] I2C read error (expected 6 bytes)\n");
        return -1;
    }

    /* Validate CRCs. */
    if (!sht40_crc_ok(&buf[0], buf[2])) {
        fprintf(stderr, "[SHT40] Temperature CRC mismatch\n");
        return -2;
    }
    if (!sht40_crc_ok(&buf[3], buf[5])) {
        fprintf(stderr, "[SHT40] Humidity CRC mismatch\n");
        return -2;
    }

    /* Convert raw values to physical units. */
    uint16_t t_raw = ((uint16_t)buf[0] << 8) | buf[1];
    uint16_t h_raw = ((uint16_t)buf[3] << 8) | buf[4];

    *temperature = -45.0f + 175.0f * (float)t_raw / 65535.0f;
    *humidity    = 100.0f * (float)h_raw / 65535.0f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio. */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the SHT40 default address. */
    g_i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen failed (handle=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown. */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float temperature, humidity;
    int rc;

    while (g_running) {
        rc = sht40_read(g_i2c_handle, &temperature, &humidity);

        if (rc == 0) {
            printf("Temperature: %.2f °C, Humidity: %.2f %%RH\n",
                   temperature, humidity);
