#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define MLX90614_ADDR 0x5A
#define TA_REG 0x06
#define TO_REG 0x07
#define LOG_FILE "temperature_log.csv"
#define READ_INTERVAL 5

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, float *value) {
    if (write(fd, &reg, 1) != 1) return -1;
    uint8_t buf[3] = {0};
    if (read(fd, buf, 3) != 3) return -1;
    int16_t raw = (int16_t)((buf[1] << 8) | buf[0]);
    *value = (float)raw * 0.02f - 273.15f;
    return 0;
}

static int log_temperature(float ambient, float object) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    if (fprintf(log_fp, "%s,%.2f,%.2f\n", ts, ambient, object) < 0) return -1;
    fflush(log_fp);
    return 0;
}

int main(void) {
    struct sigaction sa = {0};
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open " I2C_BUS);
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MLX90614_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(i2c_fd);
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("fopen " LOG_FILE);
        close(i2c_fd);
        return 1;
    }

    while (running) {
        float ambient, object;
        if (i2c_read_reg16(i2c_fd, TA_REG, &ambient) == 0 &&
            i2c_read_reg16(i2c_fd, TO_REG, &object) == 0) {
            if (log_temperature(ambient, object) != 0) {
                fprintf(stderr, "Error writing to log file.\n");
            }
        } else {
            fprintf(stderr, "Error reading temperature data.\n");
        }
        sleep(READ_INTERVAL);
    }

    if (log_fp) fclose(log_fp);
    if (i2c_fd >= 0) close(i2c_fd);
    return 0;
}

