static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_error(const char *message) {
    FILE *fp = fopen(ERROR_LOG_FILE, "a");
    if (!fp) {
        perror("Error opening error log file");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s: %s\n", timestamp, message);
    fclose(fp);
}

static int read_temperature(float *temperature) {
    unsigned char cmd[2] = {0x36, 0x2E};
    unsigned char data[6];
    int result;

    result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (result != 0) {
        log_error("I2C write failed");
        return -1;
    }

    gpioDelay(100000);

    result = i2cReadDevice(i2c_handle, (char *)data, 6);
    if (result != 6) {
        log_error("I2C read failed or incomplete");
        return -1;
    }

    int temp_ticks = (data[0] << 8) | data[1];
    *temperature = -45.0f + (175.0f * (float)temp_ticks / 65535.0f);
    return 0;
}

static void log_temperature(float temperature) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        log_error("Error opening log file");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s, %.2f\n", timestamp, temperature);
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, STS30_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        log_error("Error opening I2C device");
        gpioTerminate();
        return 1;
    }

    while (running) {
        float temperature;
        if (read_temperature(&temperature) == 0) {
            log_temperature(temperature);
        } else {
            log_error("Failed to read temperature from sensor");
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

