#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x21
#define LOG_FILE       "airflow.log"
#define SAMPLE_PERIOD  0.1
#define MAX_RETRIES    3
#define RETRY_DELAY_US 100000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static uint8_t crc8(const uint8_t *data, int len)
{
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int i2c_write_cmd(int handle, uint8_t msb, uint8_t lsb)
{
    char buf[2] = { (char)msb, (char)lsb };
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cWriteDevice(handle, buf, 2);
        if (rc == 0)
            return 0;
        fprintf(stderr, "I2C write failed (attempt %d/%d): rc=%d\n",
                attempt + 1, MAX_RETRIES, rc);
        if (attempt < MAX_RETRIES - 1)
            gpioDelay(RETRY_DELAY_US * (1 << attempt));
    }
    return -1;
}

static int i2c_read_bytes(int handle, uint8_t *buf, int len)
{
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cReadDevice(handle, (char *)buf, len);
        if (rc == len)
            return 0;
        fprintf(stderr, "I2C read failed (attempt %d/%d): rc=%d\n",
                attempt + 1, MAX_RETRIES, rc);
        if (attempt < MAX_RETRIES - 1)
            gpioDelay(RETRY_DELAY_US * (1 << attempt));
    }
    return -1;
}

static int read_sdp31(int handle, float *pressure_pa, float *temp_c)
{
    uint8_t buf[6];

    if (i2c_write_cmd(handle, 0x36, 0x2F) != 0)
        return -1;

    gpioDelay(1000);

    if (i2c_read_bytes(handle, buf, 6) != 0)
        return -1;

    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Pressure CRC mismatch\n");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }

    int16_t raw_pressure = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_temp     = (int16_t)((buf[3] << 8) | buf[4]);

    *pressure_pa = (float)raw_pressure;
    *temp_c      = (float)raw_temp / 200.0f;

    return 0;
}

static void log_data(FILE *fp, float pressure_pa, float temp_c)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f,%.2f\n", ts, pressure_pa, temp_c);
    fflush(fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "i2cOpen failed: %d\n", handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen");
        i2cClose(handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (g_running) {
        float pressure_pa, temp_c;
        if (read_sdp31(handle, &pressure_pa, &temp_c) == 0) {
            log_data(fp, pressure_pa, temp_c);
        } else {
            fprintf(stderr, "Sensor read failed; continuing\n");
        }
        time_sleep(SAMPLE_PERIOD);
    }

    fclose(fp);
    i2cClose(handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

