/*
 * Si7021 humidity/temperature monitor with hysteresis fan control.
 *
 * Board:  Raspberry Pi 4 Model B
 * Bus:    I2C bus 1 (GPIO2 = SDA, GPIO3 = SCL)
 * Sensor: Si7021 at 0x48
 * Fan:    GPIO18 (BCM), active-high
 *
 * Build:  gcc -O2 -Wall -Wextra -o si7021_fan si7021_fan.c -lpigpio -lrt
 * Run:    sudo ./si7021_fan
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS            1
#define SI7021_ADDR        0x48
#define FAN_GPIO           18
#define TEMP_THRESHOLD_ON  28.0f   /* °C — fan turns ON  above this */
#define TEMP_THRESHOLD_OFF 27.0f   /* °C — fan turns OFF below this */
#define BUFFER_SIZE        60
#define SAMPLE_INTERVAL_S  2
#define FAN_SETTLE_MS      10
#define MAX_RETRIES        3
#define POLL_DELAY_US      10000   /* 10 ms between retries */

/* Si7021 commands */
#define CMD_MEASURE_TEMP_HOLD  0xE3
#define CMD_READ_PREV_TEMP     0xE0
#define CMD_RESET              0xFE

/* ----------------------------- Data Structures --------------------------- */
typedef struct {
    time_t timestamp;
    float  temperature;
    float  humidity;
} SensorData;

typedef struct {
    SensorData data[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

/* ----------------------------- Globals ----------------------------------- */
static int            i2c_handle = -1;
static CircularBuffer buffer;
static volatile sig_atomic_t running = 1;

/* ----------------------------- Prototypes -------------------------------- */
static int  init_i2c(void);
static int  read_sensor(float *temperature, float *humidity);
static void control_fan(float temperature);
static void buffer_add(CircularBuffer *cb, SensorData sd);
static void buffer_print(const CircularBuffer *cb);
static void signal_handler(int sig);
static void cleanup(void);

/* ----------------------------- I2C Init ---------------------------------- */
static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %s\n",
                I2C_BUS, SI7021_ADDR, pigpio_error(i2c_handle));
        return -1;
    }
    return 0;
}

/* ----------------------------- Sensor Read -------------------------------- */
static int read_sensor(float *temperature, float *humidity) {
    char cmd = CMD_MEASURE_TEMP_HOLD;
    char buf[2];
    int  result;
    int  retries = 0;

    while (retries < MAX_RETRIES) {
        /* Trigger a measurement (hold master mode) */
        result = i2cWriteDevice(i2c_handle, &cmd, 1);
        if (result < 0) {
            fprintf(stderr, "I2C write error (cmd 0x%02X): %s\n",
                    cmd, pigpio_error(result));
            retries++;
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        /* Wait for conversion (~12.5 ms typ, 10 ms is safe) */
        gpioDelay(10000);

        /* Read the 2-byte temperature result */
        result = i2cReadDevice(i2c_handle, buf, 2);
        if (result < 0) {
            fprintf(stderr, "I2C read error: %s\n", pigpio_error(result));
            retries++;
            gpioDelay(POLL_DELAY_US);
            continue;
        }
        if (result != 2) {
            fprintf(stderr, "I2C short read: got %d bytes, expected 2\n", result);
            retries++;
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
        *temperature = (175.72f * raw / 65536.0f) - 46.85f;

        /* Read relative humidity from the previous measurement register */
        char read_cmd = CMD_READ_PREV_TEMP;
        result = i2cWriteDevice(i2c_handle, &read_cmd, 1);
        if (result < 0) {
            fprintf(stderr, "I2C write (read prev) error: %s\n",
                    pigpio_error(result));
            retries++;
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        result = i2cReadDevice(i2c_handle, buf, 2);
        if (result < 0) {
            fprintf(stderr, "I2C read (prev) error: %s\n", pigpio_error(result));
            retries++;
            gpioDelay(POLL_DELAY_US);
            continue;
        }
        if (result != 2) {
            fprintf(stderr, "I2C short read (prev): got %d bytes, expected 2\n", result);
            retries++;
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        uint16_t rh_raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
        *humidity = (125.0f * rh_raw / 65536.0f) - 6.0f;

        /* Sanity-check ranges */
        if (*temperature < -40.0f || *temperature > 125.0f ||
            *humidity   <    0.0f || *humidity   > 100.0f) {
            fprintf(stderr, "Sensor out of range: T=%.2f H=%.2f\n",
                    *temperature, *humidity);
            retries++;
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        return 0;
    }

    fprintf(stderr, "Failed to read sensor after %d retries.\n", MAX_RETRIES);
    return -1;
}

/* ----------------------------- Fan Control -------------------------------- */
static void control_fan(float temperature) {
    static bool fan_on = false;

    if (temperature > TEMP_THRESHOLD_ON && !fan_on) {
        if (gpioWrite(FAN_GPIO, 1) == 0) {
            fan_on = true;
            printf("Fan ON  (T=%.2f°C)\n", temperature);
        } else {
            fprintf(stderr, "Failed to set FAN_GPIO high.\n");
        }
        gpioDelay(FAN_SETTLE_MS * 1000);
    } else if (temperature < TEMP_THRESHOLD_OFF && fan_on) {
        if (gpioWrite(FAN_GPIO, 0) == 0) {
            fan_on = false;
            printf("Fan OFF (T=%.2f°C)\n", temperature);
        } else {
            fprintf(stderr, "Failed to set FAN_GPIO low.\n");
        }
    }
}

/* ----------------------------- Circular Buffer --------------------------- */
static void buffer_add(CircularBuffer *cb, SensorData sd) {
    cb->data[cb->head] = sd;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) cb->count++;
}

static void buffer_print(const CircularBuffer *cb) {
    printf("\n--- Circular Buffer (%d entries) ---\n", cb->count);
    for (int i = 0; i < cb->count; i++) {
        int idx = (cb->head - cb->count + i + BUFFER_SIZE) % BUFFER_SIZE;
        char ts[32];
        struct tm tm_info;
        localtime_r(&cb->data[idx].timestamp, &tm_info);
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
        printf("[%s] T=%.2f°C  H=%.2f%%\n",
               ts, cb->data[idx].temperature, cb->data[idx].humidity);
    }
    printf("-----------------------------------\n");
}

/* ----------------------------- Signal Handler ---------------------------- */
static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* ----------------------------- Cleanup ----------------------------------- */
static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(FAN_GPIO, 0);
    gpioTerminate();
}

/* ----------------------------- Main -------------------------------------- */
int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure fan GPIO */
    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set FAN_GPIO %d as output.\n", FAN_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(FAN_GPIO, 0);

    /* Initialize I2C */
    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize circular buffer */
    memset(&buffer, 0, sizeof(buffer));

    /* Signal handling */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Si7021 fan controller started. Ctrl+C to exit.\n");

    /* Main loop */
    while (running) {
        float temperature, humidity;

        if (read_sensor(&temperature, &humidity) == 0) {
            SensorData sd;
            sd.timestamp   = time(NULL);
            sd.temperature = temperature;
            sd.humidity    = humidity;
            buffer_add(&buffer, sd);
            buffer_print(&buffer);
            control_fan(temperature);
        } else {
            fprintf(stderr, "Sensor read failed; will retry next cycle.\n");
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_S * 10 && running; i++) {
            gpioDelay(100000);
        }
    }

    cleanup();
    printf("Exiting cleanly.\n");
    return EXIT_SUCCESS;
}

