/*
 * SCD40 CO2 / Temperature / Humidity logger for Raspberry Pi Zero W
 * I2C bus 1, address 0x61 (ADDR pin tied to GND)
 * Logs CSV lines to air_quality.log every 5 s while periodic measurement is active.
 *
 * Build:  gcc -O2 -Wall -Wextra -o scd40_logger scd40_logger.c -lpigpio -lrt
 * Run:    sudo ./scd40_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SCD40_I2C_ADDR        0x61
#define SCD40_BUS             1
#define LOG_FILE              "air_quality.log"
#define SAMPLE_PERIOD_US      5000000   /* 5 s between samples */
#define FIRST_READ_DELAY_US   1000000   /* 1 s after start-up */
#define SCD40_CRC8_POLY       0x31
#define SCD40_CRC8_INIT       0xFF

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (polynomial 0x31, init 0xFF, no final XOR) — SCD4x datasheet  */
/* ------------------------------------------------------------------ */
static uint8_t scd40_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = SCD40_CRC8_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (uint8_t)((crc << 1) ^ SCD40_CRC8_POLY)
                               : (uint8_t)(crc << 1);
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Low-level I2C helpers                                               */
/* ------------------------------------------------------------------ */
static int i2c_write_cmd(uint8_t msb, uint8_t lsb)
{
    uint8_t buf[2] = { msb, lsb };
    if (i2cWriteDevice(g_i2c_handle, (char *)buf, 2) != 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice(0x%02X%02X) failed\n", msb, lsb);
        return -1;
    }
    return 0;
}

static int i2c_read_block(uint8_t *buf, size_t len)
{
    if (i2cReadDevice(g_i2c_handle, (char *)buf, len) != (int)len) {
        fprintf(stderr, "[ERROR] i2cReadDevice expected %zu bytes\n", len);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* SCD40 commands (100 kHz, clock-stretching compatible)               */
/* ------------------------------------------------------------------ */
static int scd40_start_periodic_measurement(void)
{
    /* Start Periodic Measurement: 0x0010 */
    return i2c_write_cmd(0x00, 0x10);
}

static int scd40_stop_periodic_measurement(void)
{
    /* Stop Periodic Measurement: 0x0104 */
    return i2c_write_cmd(0x01, 0x04);
}

static int scd40_data_ready(uint8_t *ready)
{
    /* Read Measurement: 0x0300 */
    if (i2c_write_cmd(0x03, 0x00) != 0)
        return -1;

    /* Datasheet: max 1 ms for the command to take effect */
    gpioDelay(2000);

    uint8_t buf[3];
    if (i2c_read_block(buf, sizeof(buf)) != 0)
        return -1;

    if (scd40_crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "[ERROR] CRC mismatch on data-ready word\n");
        return -1;
    }

    *ready = (buf[0] == 0x01) ? 1 : 0;
    return 0;
}

static int scd40_read_measurement(uint16_t *co2, float *temp, float *rh)
{
    /* Read Measurement: 0x0300 (again) */
    if (i2c_write_cmd(0x03, 0x00) != 0)
        return -1;

    gpioDelay(2000);

    uint8_t buf[9];
    if (i2c_read_block(buf, sizeof(buf)) != 0)
        return -1;

    /* Verify CRC for each 2-byte word */
    for (int i = 0; i < 3; i++) {
        if (scd40_crc8(&buf[i * 3], 2) != buf[i * 3 + 2]) {
            fprintf(stderr, "[ERROR] CRC mismatch on word %d\n", i);
            return -1;
        }
    }

    uint16_t co2_raw = (uint16_t)((buf[0] << 8) | buf[1]);
    uint16_t t_raw   = (uint16_t)((buf[3] << 8) | buf[4]);
    uint16_t rh_raw  = (uint16_t)((buf[6] << 8) | buf[7]);

    *co2  = co2_raw;
    *temp = -45.0f + 175.0f * (float)t_raw / 65535.0f;
    *rh   = 100.0f * (float)rh_raw / 65535.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_data(uint16_t co2, float temp, float rh)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    fprintf(g_log_file, "%s,%u,%.2f,%.2f\n", ts, co2, temp, rh);
    fflush(g_log_file);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        if (scd40_stop_periodic_measurement() != 0)
            fprintf(stderr, "[WARN] Failed to stop periodic measurement\n");
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] gpioInitialise failed\n");
        return EXIT_FAILURE;
    }

    /* --- open I2C --- */
    g_i2c_handle = i2cOpen(SCD40_BUS, SCD40_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                SCD40_BUS, SCD40_I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- open log file --- */
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        fprintf(stderr, "[FATAL] Cannot open %s\n", LOG_FILE);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- signal handling --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* --- start periodic measurement --- */
    if (scd40_start_periodic_measurement() != 0) {
        fprintf(stderr, "[FATAL] Failed to start periodic measurement\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* First read happens after ~1 s so the sensor has time to warm up */
    gpioDelay(FIRST_READ_DELAY_US);

    /* --- main sampling loop --- */
    while (g_running) {
        uint8_t ready = 0;
        if (scd40_data_ready(&ready) != 0) {
            fprintf(stderr, "[WARN] data-ready check failed; retrying\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        if (!ready) {
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        uint16_t co2;
        float temp, rh;
        if (scd40_read_measurement(&co2, &temp, &rh) != 0) {
            fprintf(stderr, "[WARN] read_measurement failed; retrying\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        log_data(co2, temp, rh);
        printf("CO2: %u ppm | T: %.2f C | RH: %.2f %%\n", co2, temp, rh);

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* --- graceful shutdown --- */
    fprintf(stderr, "\n[INFO] Shutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

