#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#include <pigpio.h>

/* ----------------------------- Constants ------------------------------- */

#define I2C_BUS            1
#define SCD40_ADDR         0x61
#define GPIO_LED           17
#define CO2_THRESHOLD      1000
#define BUFFER_SIZE        20
#define SAMPLE_PERIOD_US   5000000   /* 5 s */
#define MAX_CONSEC_ERRORS  10

/* SCD40 commands (16-bit, big-endian on the bus) */
#define CMD_START_PERIODIC  0x21B1
#define CMD_READ_MEASUREMENT 0x2166
#define CMD_STOP_PERIODIC   0x3F86

/* --------------------------- Data structures --------------------------- */

typedef struct {
    uint16_t co2;
    float    temperature;
    float    humidity;
    time_t   timestamp;
} sensor_data_t;

typedef struct {
    sensor_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

/* --------------------------- Global state ------------------------------ */

static int               i2c_handle = -1;
static circular_buffer_t buffer;
static volatile sig_atomic_t terminate = 0;

/* --------------------------- CRC-8 (Sensirion) ------------------------- */

static uint8_t scd40_crc8(const uint8_t *data, int len)
{
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* --------------------------- Circular buffer --------------------------- */

static void buffer_init(circular_buffer_t *buf)
{
    buf->head  = 0;
    buf->count = 0;
}

static void buffer_add(circular_buffer_t *buf, sensor_data_t d)
{
    buf->data[buf->head] = d;
    buf->head = (buf->head + 1) % BUFFER_SIZE;
    if (buf->count < BUFFER_SIZE)
        buf->count++;
}

/* --------------------------- I2C helpers -------------------------------- */

static int i2c_write_cmd(uint16_t cmd)
{
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (i2cWriteDevice(i2c_handle, (char *)buf, 2) != 0) {
        fprintf(stderr, "[I2C] write cmd 0x%04X failed: %s\n",
                cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_words(uint8_t *buf, int len)
{
    if (i2cReadDevice(i2c_handle, (char *)buf, len) != len) {
        fprintf(stderr, "[I2C] read %d bytes failed: %s\n",
                len, strerror(errno));
        return -1;
    }
    return 0;
}

/* --------------------------- Sensor logic ------------------------------ */

static int scd40_start_periodic(void)
{
    if (i2c_write_cmd(CMD_START_PERIODIC) != 0)
        return -1;
    /* Datasheet: first measurement is ready after ~5 s. */
    gpioDelay(5000000);
    return 0;
}

static int scd40_stop_periodic(void)
{
    return i2c_write_cmd(CMD_STOP_PERIODIC);
}

/*
 * Read one 9-byte measurement frame from the SCD40.
 * Layout:  CO2(2)+CRC, T(2)+CRC, RH(2)+CRC
 * Returns 0 on success, -1 on I/O or CRC error.
 */
static int scd40_read_measurement(sensor_data_t *out)
{
    uint8_t buf[9];

    if (i2c_write_cmd(CMD_READ_MEASUREMENT) != 0)
        return -1;

    /* Datasheet: conversion takes ~1 ms. */
    gpioDelay(2000);

    if (i2c_read_words(buf, sizeof(buf)) != 0)
        return -1;

    /* CRC checks */
    for (int i = 0; i < 3; i++) {
        if (scd40_crc8(&buf[i * 3], 2) != buf[i * 3 + 2]) {
            fprintf(stderr, "[SCD40] CRC mismatch on word %d\n", i);
            return -1;
        }
    }

    out->co2         = (uint16_t)((buf[0] << 8) | buf[1]);
    out->temperature = ((float)((buf[3] << 8) | buf[4])) / 100.0f;
    out->humidity    = ((float)((buf[6] << 8) | buf[7])) / 100.0f;
    out->timestamp   = time(NULL);
    return 0;
}

/* --------------------------- GPIO helpers ------------------------------ */

static int gpio_init(void)
{
    if (gpioSetMode(GPIO_LED, PI_OUTPUT) != 0) {
        fprintf(stderr, "[GPIO] setMode %d failed\n", GPIO_LED);
        return -1;
    }
    if (gpioWrite(GPIO_LED, 0) != 0) {
        fprintf(stderr, "[GPIO] write %d failed\n", GPIO_LED);
        return -1;
    }
    return 0;
}

static void gpio_set_led(int on)
{
    if (gpioWrite(GPIO_LED, on ? 1 : 0) != 0)
        fprintf(stderr, "[GPIO] write %d failed\n", GPIO_LED);
}

/* --------------------------- Signal handling --------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* --------------------------- Main -------------------------------------- */

int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- I2C open --- */
    i2c_handle = i2cOpen(I2C_BUS, SCD40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "i2cOpen(bus=%d, addr=0x%02X) failed: %s\n",
                I2C_BUS, SCD40_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- GPIO init --- */
    if (gpio_init() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Buffer init --- */
    buffer_init(&buffer);

    /* --- Signals --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* --- Sensor start --- */
    if (scd40_start_periodic() != 0) {
        fprintf(stderr, "SCD40 start periodic failed (sensor absent or bus error)\n");
        gpio_set_led(0);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("SCD40 monitoring started. Sampling every 5 s. Press Ctrl+C to stop.\n");

    int consec_errors = 0;

    while (!terminate) {
        sensor_data_t d;

        if (scd40_read_measurement(&d) == 0) {
            consec_errors = 0;
            buffer_add(&buffer, d);
            printf("[%ld] CO2=%u ppm  T=%.2f C  RH=%.2f %%\n",
                   (long)d.timestamp, d.co2, d.temperature, d.humidity);

            if (d.co2 > CO2_THRESHOLD)
                gpio_set_led(1);
            else
                gpio_set_led(0);
        } else {
            consec_errors++;
            fprintf(stderr, "Read failed (%d consecutive)\n", consec_errors);
            if (consec_errors >= MAX_CONSEC_ERRORS) {
                fprintf(stderr, "Too many consecutive errors; aborting.\n");
                break;
            }
        }

        /* Sleep in 100 ms slices so signals are caught promptly. */
        for (int i = 0; i < 50 && !terminate; i++)
            gpioDelay(100000);
    }

    /* --- Cleanup --- */
    scd40_stop_periodic();
    gpio_set_led(0);
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

