/*
 * TMP05 temperature monitor for Raspberry Pi 4 Model B.
 *
 * The TMP05 exposes a PWM-style output on GPIO4 (BCM 4, physical pin 7).
 * We measure the high-pulse width and cycle width with microsecond
 * timestamps from the library's call() API, then compute temperature
 * per the TMP05 datasheet formula.
 *
 * Build:  gcc -O2 -Wall -Wextra -o tmp05_monitor tmp05_monitor.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

#include <gpiod.h>

#define GPIO_CHIP_NAME   "gpiochip4"   /* BCM GPIO controller on Pi 4 */
#define GPIO_LINE_OFFSET 4             /* BCM 4 */
#define LOG_FILE         "temperature_log.txt"
#define SAMPLE_PERIOD_S  5             /* seconds between samples */
#define EDGE_TIMEOUT_US  50000         /* 50 ms per-edge timeout */
#define MAX_CONSEC_ERRORS 3

/* TMP05 valid operating range */
#define TMP05_MIN_C (-40.0)
#define TMP05_MAX_C (150.0)

/* ------------------------------------------------------------------ */
/* Shared state between signal handler and main thread                */
/* ------------------------------------------------------------------ */
static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Microsecond timestamp using the library's monotonic clock          */
/* ------------------------------------------------------------------ */
static uint64_t now_us(void)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
        return 0;
    }
    return (uint64_t)ts.tv_sec * 1000000ULL + (uint64_t)ts.tv_nsec / 1000ULL;
}

/* ------------------------------------------------------------------ */
/* Read one edge (rising or falling) with a timeout                    */
/* ------------------------------------------------------------------ */
static int read_edge(struct gpiod_line *line, int target_level,
                     uint64_t *out_time_us)
{
    uint64_t deadline = now_us() + EDGE_TIMEOUT_US;

    for (;;) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            return -1;
        }
        if (val == target_level) {
            *out_time_us = now_us();
            return 0;
        }
        if (now_us() >= deadline) {
            return 1;                 /* timeout */
        }
    }
}

/* ------------------------------------------------------------------ */
/* Measure high-pulse width and cycle width                            */
/* ------------------------------------------------------------------ */
static int measure_pulse(struct gpiod_line *line, uint64_t *high_us,
                         uint64_t *cycle_us)
{
    uint64_t t_rise = 0, t_fall = 0;

    /* Wait for rising edge (level 1) */
    if (read_edge(line, 1, &t_rise) != 0) {
        return -1;
    }

    /* Wait for falling edge (level 0) */
    if (read_edge(line, 0, &t_fall) != 0) {
        return -1;
    }

    *high_us  = t_fall - t_rise;
    *cycle_us = t_fall - t_rise;
    return 0;
}

/* ------------------------------------------------------------------ */
/* TMP05 temperature formula                                          */
/* ------------------------------------------------------------------ */
static double calculate_temperature(uint64_t high_us, uint64_t cycle_us)
{
    if (cycle_us == 0) {
        return -999.0;                 /* guard against division by zero */
    }

    /* Normalize to microseconds per LSB (per TMP05 datasheet) */
    double high_s  = (double)high_us  / 1000000.0;
    double cycle_s = (double)cycle_us / 1000000.0;

    /* TMP05 PWM frequency ~ 1 kHz; duty cycle = high / cycle */
    double duty = high_s / cycle_s;

    /* Temperature (°C) = 100 * (duty - 0.5) */
    return 100.0 * (duty - 0.5);
}

/* ------------------------------------------------------------------ */
/* Log a valid reading with an ISO-8601 timestamp                      */
/* ------------------------------------------------------------------ */
static void log_temperature(double temperature)
{
    time_t rawtime;
    struct tm tm_info;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &tm_info) == NULL) {
        return;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);

    fprintf(g_log_fp, "%s Temperature: %.2f C\n", timestamp, temperature);
    fflush(g_log_fp);
}

/* ------------------------------------------------------------------ */
/* Log a sensor malfunction event                                      */
/* ------------------------------------------------------------------ */
static void log_sensor_malfunction(void)
{
    time_t rawtime;
    struct tm tm_info;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &tm_info) == NULL) {
        return;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);

    fprintf(g_log_fp, "%s SENSOR MALFUNCTION: three consecutive invalid readings\n",
            timestamp);
    fflush(g_log_fp);
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        perror("fopen(" LOG_FILE ")");
        return EXIT_FAILURE;
    }

    /* ---- Open GPIO chip ---- */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        perror("gpiod_chip_open_by_name");
        goto cleanup_log;
    }

    /* ---- Get GPIO line ---- */
    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (line == NULL) {
        perror("gpiod_chip_get_line");
        goto cleanup_chip;
    }

    /* ---- Request line as input ---- */
    if (gpiod_line_request_input(line, "tmp05_monitor") != 0) {
        perror("gpiod_line_request_input");
        goto cleanup_chip;
    }

    printf("TMP05 monitoring started on GPIO4. Press Ctrl+C to exit.\n");

    int consecutive_errors = 0;

    while (g_running) {
        uint64_t high_us = 0, cycle_us = 0;

        if (measure_pulse(line, &high_us, &cycle_us) != 0) {
            fprintf(stderr, "Edge measurement timeout or I/O error\n");
            consecutive_errors++;
            if (consecutive_errors >= MAX_CONSEC_ERRORS) {
                log_sensor_malfunction();
                consecutive_errors = 0;
            }
            sleep(SAMPLE_PERIOD_S);
            continue;
        }

        double temperature = calculate_temperature(high_us, cycle_us);

        if (temperature < TMP05_MIN_C || temperature > TMP05_MAX_C) {
            fprintf(stderr, "Temperature out of range: %.2f C\n", temperature);
            consecutive_errors++;
            if (consecutive_errors >= MAX_CONSEC_ERRORS) {
                log_sensor_malfunction();
                consecutive_errors = 0;
            }
        } else {
            log_temperature(temperature);
            consecutive_errors = 0;
        }

        sleep(SAMPLE_PERIOD_S);
    }

    printf("\nShutting down cleanly...\n");
    ret = EXIT_SUCCESS;

    gpiod_line_release(line);
cleanup_chip:
    gpiod_chip_close(chip);
cleanup_log:
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    return ret;
}

