/*
 * Raspberry Pi 4 Model B — SHT35‑DIS‑B greenhouse simulator logger
 *
 * Wiring:
 *   SHT35 VDD  -> 3V3 (Pin 1)
 *   SHT35 GND  -> GND (Pin 9)
 *   SHT35 SDA  -> GPIO2 / I2C bus 1 SDA (Pin 3)
 *   SHT35 SCL  -> GPIO3 / I2C bus 1 SCL (Pin 5)
 *
 * Build:  gcc -O2 -Wall -Wextra -o greenhouse greenhouse.c -lpigpio -lrt
 * Run:    sudo ./greenhouse
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x44          /* SHT35 default 7-bit address */
#define LOG_FILE       "environmental_data.txt"
#define SAMPLE_PERIOD  5             /* seconds between samples */
#define MAX_RETRIES    3
#define RETRY_DELAY    1             /* seconds between retries */
#define MEAS_DELAY_US  15000         /* 15 ms — SHT35 high-repeatability, no clock stretching */

/* High-repeatability, clock-stretching disabled measurement command */
#define CMD_MSB        0x2C
#define CMD_LSB        0x06

