/*
 * SHT35-DIS-B temperature & humidity logger for Raspberry Pi Zero W.
 *
 * Wiring:
 *   SHT35 SDA  -> GPIO2 (pin 3, I2C bus 1 SDA)
 *   SHT35 SCL  -> GPIO3 (pin 5, I2C bus 1 SCL)
 *   SHT35 VDD  -> 3.3 V
 *   SHT35 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o sht35_logger sht35_logger.c
 * Run:    ./sht35_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SHT35_ADDR     0x44
#define CSV_FILENAME   "environment.csv"
#define SAMPLE_PERIOD  5          /* seconds between samples */
#define MEAS_DELAY_MS  15         /* SHT35 high-repeatability, clock-stretching disabled */

/* SHT35 single-shot, high repeatability, clock-stretching disabled */
static const uint8_t CMD_MEASURE[2] = { 0x2C, 0x06 };

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (polynomial 0x31, init 0xFF, no final XOR) — Sensirion spec   */
/* ------------------------------------------------------------------ */
static uint8_t sht35_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_cmd(int fd, const uint8_t *cmd, size_t len)
{
    if (write(fd, cmd, len) != (ssize_t)len) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_data(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n != (ssize_t)len) {
        fprintf(stderr, "I2C read failed: expected %zu bytes, got %zd (%s)\n",
                len, n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor read                                                         */
/* ------------------------------------------------------------------ */
static int read_sht35(int fd, float *temperature, float *humidity)
{
    uint8_t data[6];

    if (i2c_write_cmd(fd, CMD_MEASURE, sizeof(CMD_MEASURE)) != 0)
        return -1;

    usleep(MEAS_DELAY_MS * 1000);

    if (i2c_read_data(fd, data, sizeof(data)) != 0)
        return -1;

    /* CRC validation */
    if (sht35_crc8(&data[0], 2) != data[2]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }
    if (sht35_crc8(&data[3], 2) != data[5]) {
        fprintf(stderr, "Humidity CRC mismatch\n");
        return -1;
    }

    uint16_t t_raw = (uint16_t)((data[0] << 8) | data[1]);
    uint16_t h_raw = (uint16_t)((data[3] << 8) | data[4]);

    *temperature = -45.0f + (175.0f * (float)t_raw / 65535.0f);
    *humidity    = 100.0f * (float)h_raw / 65535.0f;

    /* Sanity range checks */
    if (*temperature < -40.0f || *temperature > 125.0f) {
        fprintf(stderr, "Temperature out of range: %.2f C\n", *temperature);
        return -1;
    }
    if (*humidity < 0.0f || *humidity > 100.0f) {
        fprintf(stderr, "Humidity out of range: %.2f %%\n", *humidity);
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* CSV logging                                                         */
/* ------------------------------------------------------------------ */
static int log_data(const char *filename, float temperature, float humidity)
{
    int need_header = 0;
    FILE *check = fopen(filename, "r");
    if (check == NULL) {
        need_header = 1;                       /* file does not exist yet */
    } else {
        fseek(check, 0, SEEK_END);
        if (ftell(check) == 0)
            need_header = 1;                    /* empty file */
        fclose(check);
    }

    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        fprintf(stderr, "Cannot open %s: %s\n", filename, strerror(errno));
        return -1;
    }

    if (need_header)
        fprintf(fp, "Timestamp,Temperature(C),Humidity(%%)\n");

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f,%.2f\n", ts, temperature, humidity);

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing %s: %s\n", filename, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    if (install_signal_handlers() != 0)
        return EXIT_FAILURE;

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, SHT35_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                SHT35_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    printf("SHT35 logger started. Press Ctrl+C to stop.\n");

    while (g_running) {
        float temperature, humidity;

        if (read_sht35(fd, &temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n",
                   temperature, humidity);
            if (log_data(CSV_FILENAME, temperature, humidity) != 0)
                fprintf(stderr, "Logging failed.\n");
        } else {
            fprintf(stderr, "Sensor read failed.\n");
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD && g_running; i++)
            sleep(1);
    }

    printf("\nShutting down...\n");
    if (close(fd) != 0)
        fprintf(stderr, "Warning: close failed: %s\n", strerror(errno));

    return EXIT_SUCCESS;
}

