    if (i2c_write_cmd(cmd) < 0) return -1;

    uint8_t buf[3];
    for (int elapsed = 0; elapsed < POLL_TIMEOUT_MS; elapsed += 5) {
        usleep(5000);
        if (i2c_read_bytes(buf, 3) == 0) {
            if (crc8(buf, 2) != buf[2]) {
                fprintf(stderr, "CRC mismatch: calc=0x%02X recv=0x%02X\n",
                        crc8(buf, 2), buf[2]);
                return -1;
            }
            *raw = (uint16_t)((buf[0] << 8) | buf[1]);
            return 0;
        }
    }
    fprintf(stderr, "read_measurement: timeout after %d ms\n", POLL_TIMEOUT_MS);
    return -1;
}

static int read_temperature(float *temp) {
    uint16_t raw;
    if (read_measurement(SI7021_CMD_MEAS_T, &raw) < 0) return -1;
    *temp = (175.72f * raw / 65536.0f) - 46.85f;
    return 0;
}

static int read_humidity(float *rh) {
    uint16_t raw;
    if (read_measurement(SI7021_CMD_MEAS_RH, &raw) < 0) return -1;
    *rh = (125.0f * raw / 65536.0f) - 6.0f;
    if (*rh < 0.0f)   *rh = 0.0f;
    if (*rh > 100.0f) *rh = 100.0f;
    return 0;
}

static int log_data(float temp, float rh) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f,%.2f\n", ts, temp, rh);
    fclose(fp);
    return 0;
}

static void log_error(const char *msg) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log (error)");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(fp, "%s,ERROR,%s\n", ts, msg);
    }
    fclose(fp);
    fprintf(stderr, "ERROR: %s\n", msg);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        perror("open " I2C_BUS);
        return EXIT_FAILURE;
    }
    if (ioctl(g_i2c_fd, I2C_SLAVE, SI7021_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    if (i2c_write_cmd(SI7021_CMD_RESET) < 0) {
        fprintf(stderr, "Warning: sensor reset failed; continuing anyway\n");
    }
    usleep(15000);

    while (g_running) {
        float temp, rh;
        if (read_temperature(&temp) < 0 || read_humidity(&rh) < 0) {
            log_error("I2C read failure; issuing reset");
            if (i2c_write_cmd(SI7021_CMD_RESET) < 0) {
                log_error("reset command failed");
            }
            usleep(15000);
            continue;
        }
        if (log_data(temp, rh) < 0) {
            log_error("log write failure");
        }
        printf("Temperature: %.2f C, Humidity: %.2f %%\n", temp, rh);
        for (int i = 0; i < SAMPLE_INTERVAL_S && g_running; i++) {
            sleep(1);
        }
    }

    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

