/*
 * Raspberry Pi 3 Model B+ — Sensirion SDP800-500Pa differential pressure logger
 *
 * Wiring:
 *   SDP800 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   SDP800 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   SDP800 VDD  -> 3.3 V
 *   SDP800 GND  -> GND
 *
 * I2C address: 0x21 (SDP800 default, 0x22 if A0 jumper is tied high)
 * Continuous measurement command: 0x3615
 * Conversion time: 45 ms
 * Response: 9 bytes = 3 words × (2 data bytes + 1 CRC byte)
 *   word 0: differential pressure (Pa, signed 16-bit, 0.01 Pa LSB)
 *   word 1: temperature (°C, signed 16-bit, 0.01 °C LSB)
 *   word 2: scale factor (signed 16-bit, 0.01 Pa/°C LSB)
 *
 * Build: gcc -O2 -Wall -Wextra -o sdp800_logger sdp800_logger.c -lpigpio -lrt
 * Run:   sudo ./sdp800_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x21
#define LOG_FILE       "pressure_log.txt"
#define SAMPLE_PERIOD  5          /* seconds between samples */
#define CONV_TIME_US   45000      /* 45 ms conversion time   */

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;            /* let main loop exit cleanly          */
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion polynomial 0x31, init 0xFF)                        */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, int len)
{
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_cmd(int handle, uint16_t cmd)
{
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (i2cWriteDevice(handle, (char *)buf, 2) != 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice failed (cmd 0x%04X)\n", cmd);
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int handle, uint8_t *buf, int len)
{
    if (i2cReadDevice(handle, (char *)buf, len) != len) {
        fprintf(stderr, "[ERROR] i2cReadDevice failed (expected %d bytes)\n", len);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor read                                                         */
/* ------------------------------------------------------------------ */
static int read_sdp800(int handle, float *pressure)
{
    /* 1. Start continuous measurement */
    if (i2c_write_cmd(handle, 0x3615) != 0)
        return -1;

    /* 2. Wait for conversion */
    gpioDelay(CONV_TIME_US);

    /* 3. Read 9 bytes: 3 words × (2 data + 1 CRC) */
    uint8_t raw[9];
    if (i2c_read_bytes(handle, raw, sizeof(raw)) != 0)
        return -1;

    /* 4. CRC validation */
    for (int w = 0; w < 3; w++) {
        if (crc8(&raw[w * 3], 2) != raw[w * 3 + 2]) {
            fprintf(stderr, "[ERROR] CRC mismatch on word %d\n", w);
            return -1;
        }
    }

    /* 5. Parse signed 16-bit pressure (word 0) */
    int16_t raw_pressure = (int16_t)((raw[0] << 8) | raw[1]);
    *pressure = (float)raw_pressure * 0.01f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_pressure(FILE *fp, float pressure)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r failed\n");
        return;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s, %.2f Pa\n", ts, pressure);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* 1. Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* 2. Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen failed (handle %d) — sensor may be absent\n",
                g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* 3. Open log file */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[FATAL] Cannot open %s\n", LOG_FILE);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* 4. Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* 5. Main sampling loop */
    while (g_running) {
        float pressure;
        if (read_sdp800(g_i2c_handle, &pressure) == 0) {
            log_pressure(g_log_file, pressure);
            printf("Pressure: %.2f Pa\n", pressure);
        } else {
            fprintf(stderr, "[WARN] Sensor read failed — continuing\n");
        }
        sleep(SAMPLE_PERIOD);
    }

    /* 6. Clean shutdown */
    cleanup();
    return EXIT_SUCCESS;
}

