/*
 * Raspberry Pi 3 Model B+ — Honeywell Zephyr HAF airflow sensor reader
 *
 * Hardware:
 *   - I2C bus 1 (GPIO2 = SDA, GPIO3 = SCL), sensor address 0x28
 *   - PWM fan on GPIO18 (BCM), 25 kHz hardware PWM
 *
 * Build:
 *   gcc -O2 -Wall -o airflow airflow.c -lpigpio -lrt
 *   (pigpio requires root or gpio group access)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x28
#define FAN_GPIO       18
#define PWM_FREQ_HZ    25000
#define PWM_RANGE      1000
#define SAMPLE_US      100000   /* 100 ms */
#define LOG_FILE       "flow_log.txt"

/* HAFBLF0100A2AX5: 16-bit signed, 14-bit data, LSB = 0.1 Pa */
#define SCALE_FACTOR   0.1f
#define OFFSET         0.0f

static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    /* Ensure fan is off before terminating pigpio */
    gpioPWM(FAN_GPIO, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Read differential pressure (Pa) from the HAF sensor.
 * Returns 0 on success, -1 on I2C error. */
static int read_pressure(int handle, float *pressure)
{
    char buf[2];

    /* Point to the pressure register (0x00) */
    if (i2cWriteByte(handle, 0x00) < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByte (reg select) failed\n");
        return -1;
    }

    /* Read 2 bytes: MSB first, then LSB */
    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "[ERROR] i2cReadDevice failed\n");
        return -1;
    }

    int16_t raw = (int16_t)(((uint16_t)(uint8_t)buf[0] << 8) |
                            (uint16_t)(uint8_t)buf[1]);
    *pressure = (float)raw * SCALE_FACTOR + OFFSET;
    return 0;
}

/* ------------------------------------------------------------------ */
static void set_fan_speed(float pressure)
{
    int duty = (int)((pressure / 100.0f) * 1000.0f);
    if (duty < 0)       duty = 0;
    if (duty > PWM_RANGE) duty = PWM_RANGE;
    gpioPWM(FAN_GPIO, duty);
}

/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, float pressure)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r failed\n");
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%.2f\n", ts, pressure) < 0)
        fprintf(stderr, "[ERROR] fprintf to log failed\n");
    fflush(fp);
