#include <unistd.h>
#include <pigpio.h>

#define LPS33HW_ADDR 0x5D
#define CTRL_REG1 0x20
#define CTRL_REG2 0x21
#define PRESS_OUT_XL 0x28
#define TEMP_OUT_L 0x2B

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_register(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

static int write_register(int handle, uint8_t reg, uint8_t value) {
    return i2cWriteByteData(handle, reg, value);
}

static int read_pressure(int handle, float *pressure) {
    uint8_t press_xl, press_l, press_h;
    if (read_register(handle, PRESS_OUT_XL, &press_xl) < 0) return -1;
    if (read_register(handle, PRESS_OUT_XL + 1, &press_l) < 0) return -1;
    if (read_register(handle, PRESS_OUT_XL + 2, &press_h) < 0) return -1;

    int32_t press_raw = ((int32_t)press_h << 16) | ((int32_t)press_l << 8) | press_xl;
    if (press_raw & 0x00800000) {
        press_raw |= 0xFF000000;
    }
    *pressure = (float)press_raw / 4096.0f;
    return 0;
}

static int read_temperature(int handle, float *temperature) {
    uint8_t temp_l, temp_h;
    if (read_register(handle, TEMP_OUT_L, &temp_l) < 0) return -1;
    if (read_register(handle, TEMP_OUT_L + 1, &temp_h) < 0) return -1;

    int16_t temp_raw = ((int16_t)temp_h << 8) | temp_l;
    *temperature = (float)temp_raw / 100.0f;
    return 0;
}

static void log_data(FILE *fp, float pressure, float temperature) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[20];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(fp, "%s, Pressure: %.2f hPa, Temperature: %.2f °C\n", timestamp, pressure, temperature);
    fflush(fp);
}

static void log_error(FILE *fp, const char *message) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[20];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(stderr, "%s, ERROR: %s\n", timestamp, message);
    if (fp) {
        fprintf(fp, "%s, ERROR: %s\n", timestamp, message);
        fflush(fp);
    }
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
