        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, LPS33HW_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (write_register(i2c_handle, CTRL_REG1, 0x27) < 0) {
        fprintf(stderr, "Failed to write CTRL_REG1\n");
        cleanup();
        return 1;
    }
    if (write_register(i2c_handle, CTRL_REG2, 0x00) < 0) {
        fprintf(stderr, "Failed to write CTRL_REG2\n");
        cleanup();
        return 1;
    }

    log_file = fopen("environmental_data.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup();
        return 1;
    }

    signal(SIGINT, signal_handler);

    while (!terminate) {
        float pressure, temperature;

        if (read_pressure(i2c_handle, &pressure) == 0 && read_temperature(i2c_handle, &temperature) == 0) {
            log_data(log_file, pressure, temperature);
        } else {
            log_error(log_file, "Failed to read sensor data");
        }

        sleep(1);
    }

    cleanup();
    return 0;
}

