#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS        1
#define I2C_ADDR       0x48
#define GPIO_LED       17
#define TEMP_THRESHOLD 28.0f
#define BUFFER_SIZE    10
#define POLL_INTERVAL  1.0

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int read_temperature(int handle, float *out)
{
    char buf[2];
    int  rc;

    rc = i2cReadDevice(handle, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "I2C read failed (rc=%d): %s\n", rc, strerror(errno));
        return -1;
    }

    int16_t raw = (int16_t)(((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1]);
    raw >>= 5;
    if (raw & 0x0400) raw |= 0xF800;

    *out = (float)raw / 32.0f;
    return 0;
}

static void update_circular_buffer(float *buf, int *idx, int size, float val)
{
    buf[*idx] = val;
    *idx = (*idx + 1) % size;
}

static float calculate_average(const float *buf, int size, int count)
{
    if (count <= 0) return 0.0f;
    float sum = 0.0f;
    for (int i = 0; i < count; i++) sum += buf[i];
    return sum / (float)count;
}

int main(void)
{
    float temp_buffer[BUFFER_SIZE];
    int   buf_idx = 0;
    int   buf_count = 0;

    for (int i = 0; i < BUFFER_SIZE; i++) temp_buffer[i] = 0.0f;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "i2cOpen failed (handle=%d): %s\n", handle, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_LED, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for GPIO%d\n", GPIO_LED);
        i2cClose(handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(GPIO_LED, 0);

    while (g_running) {
        float temperature;
        if (read_temperature(handle, &temperature) == 0) {
            update_circular_buffer(temp_buffer, &buf_idx, BUFFER_SIZE, temperature);
            if (buf_count < BUFFER_SIZE) buf_count++;

            float avg = calculate_average(temp_buffer, BUFFER_SIZE, buf_count);
            printf("Temperature: %.2f C, Average: %.2f C\n", temperature, avg);

            if (avg > TEMP_THRESHOLD) {
                gpioWrite(GPIO_LED, 1);
            } else {
                gpioWrite(GPIO_LED, 0);
            }
        } else {
            fprintf(stderr, "Skipping iteration due to I2C read failure.\n");
        }

        time_sleep(POLL_INTERVAL);
    }

    gpioWrite(GPIO_LED, 0);
    i2cClose(handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

