/*
 * SCD30 CO2 / Temperature / Humidity monitor with ventilation control.
 * Board:  Raspberry Pi 4 Model B
 * Bus:    I2C-1 (GPIO2=SDA, GPIO3=SCL), address 0x61
 * Build:  gcc -O2 -Wall -Wextra -o scd30_monitor scd30_monitor.c \
 *             -lsensirion_scd30 -lpigpio -lrt
 * Run:    sudo ./scd30_monitor
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <sensirion_scd30.h>

#define SCD30_I2C_ADDR        0x61
#define LOG_FILE              "air_quality.log"
#define SAMPLE_INTERVAL_SEC   5
#define CO2_LOW_THRESHOLD     800
#define CO2_HIGH_THRESHOLD    1200
#define CO2_VENTILATION_OFF   0
#define CO2_VENTILATION_LOW   1
#define CO2_VENTILATION_HIGH  2

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;
static int   g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_message(const char *msg)
{
    time_t now = time(NULL);
    struct tm tm_utc;
    char ts[32];

    if (gmtime_r(&now, &tm_utc) != NULL) {
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc);
    } else {
        snprintf(ts, sizeof(ts), "1970-01-01T00:00:00Z");
    }

    if (g_log_fp) {
        fprintf(g_log_fp, "%s,%s\n", ts, msg);
        fflush(g_log_fp);
    }
    fprintf(stderr, "%s,%s\n", ts, msg);
}

/* ------------------------------------------------------------------ */
/* Ventilation control                                                 */
/* ------------------------------------------------------------------ */
static int ventilation_control(int co2_ppm)
{
    if (co2_ppm < CO2_LOW_THRESHOLD) {
        return CO2_VENTILATION_OFF;
    } else if (co2_ppm < CO2_HIGH_THRESHOLD) {
        return CO2_VENTILATION_LOW;
    } else {
        return CO2_VENTILATION_HIGH;
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        scd30_stop_periodic_measurement(g_i2c_handle);
        gpioDelay(500000); /* 500 ms settle */
        scd30_close(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int rc;

    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- open log file ---- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("fopen(" LOG_FILE ")");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- open I2C ---- */
    g_i2c_handle = scd30_open(SCD30_I2C_ADDR);
    if (g_i2c_handle < 0) {
        log_message("ERROR: SCD30 I2C open failed (sensor absent or bus error)");
        cleanup();
        return EXIT_SUCCESS; /* non-hardware environment: exit cleanly */
    }

    /* ---- install signal handlers ---- */
    if (install_signal_handlers() != 0) {
        log_message("ERROR: signal handler installation failed");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- start periodic measurement ---- */
    rc = scd30_start_periodic_measurement(g_i2c_handle);
    if (rc != 0) {
        log_message("ERROR: SCD30 start_periodic_measurement failed");
        cleanup();
        return EXIT_FAILURE;
    }

    log_message("INFO: SCD30 periodic measurement started");

    /* ---- main loop ---- */
    while (g_running) {
        time_t now = time(NULL);
        struct tm tm_utc;
        char ts[32];
        uint16_t co2, temperature, humidity;
        int co2_ppm, temp_c, rh_pct;
        int ventilation_state;
        char log_line[128];

        if (gmtime_r(&now, &tm_utc) != NULL) {
            strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc);
        } else {
            snprintf(ts, sizeof(ts), "1970-01-01T00:00:00Z");
        }

        /* Poll data-ready flag */
        rc = scd30_data_ready(g_i2c_handle);
        if (rc < 0) {
            log_message("ERROR: SCD30 data_ready query failed");
            gpioDelay(SAMPLE_INTERVAL_SEC * 1000000);
            continue;
        }
        if (rc == 0) {
            gpioDelay(500000); /* 500 ms */
            continue;
        }

        /* Read measurement (CO2, T, RH) */
        rc = scd30_read_measurement(g_i2c_handle, &co2, &temperature, &humidity);
        if (rc != 0) {
            log_message("ERROR: SCD30 read_measurement failed");
            gpioDelay(SAMPLE_INTERVAL_SEC * 1000000);
            continue;
        }

        /* CRC check on each 2-byte word (Sensirion convention) */
        if (sensirion_crc8(&co2, 2) != 0) {
            log_message("ERROR: CO2 CRC mismatch");
            gpioDelay(SAMPLE_INTERVAL_SEC * 1000000);
            continue;
        }
        if (sensirion_crc8(&temperature, 2) != 0) {
            log_message("ERROR: Temperature CRC mismatch");
            gpioDelay(SAMPLE_INTERVAL_SEC * 1000000);
            continue;
        }
        if (sensirion_crc8(&humidity, 2) != 0) {
            log_message("ERROR: Humidity CRC mismatch");
            gpioDelay(SAMPLE_INTERVAL_SEC * 1000000);
            continue;
        }

        /* Convert raw units to physical values */
        co2_ppm    = (int)co2;
        temp_c     = (int)temperature / 100;
        rh_pct     = (int)humidity / 100;

        ventilation_state = ventilation_control(co2_ppm);

        /* Build CSV line */
        snprintf(log_line, sizeof(log_line),
                 "%s,%d,%d,%d,%d",
                 ts, co2_ppm, temp_c, rh_pct, ventilation_state);

        /* Log to file and stderr */
        fprintf(g_log_fp, "%s\n", log_line);
        fflush(g_log_fp);
        fprintf(stderr, "%s\n", log_line);

        gpioDelay(SAMPLE_INTERVAL_SEC * 1000000);
    }

    /* ---- graceful shutdown ---- */
    log_message("INFO: Shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

