/*
 * SDP32 differential pressure reader for Raspberry Pi 3 Model B+
 * Bus: I2C-1 (GPIO2=SDA, GPIO3=SCL), address 0x21
 * Build: gcc -O2 -Wall -Wextra -o sdp32_reader sdp32_reader.c
 */
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SDP32_ADDR             0x21
#define SDP32_CMD_CONT_MEAS     0x3615   /* continuous measurement, no averaging */
#define SDP32_CMD_STOP_MEAS     0x3FF9   /* stop continuous measurement */
#define SDP32_READ_LEN         9        /* 3 words × 3 bytes + CRC */
#define SDP32_CRC_POLY         0x31
#define SDP32_CRC_INIT         0xFF

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static int g_interval_ms = 1000;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static uint8_t crc8(const uint8_t *data, int len)
{
    uint8_t crc = SDP32_CRC_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ SDP32_CRC_POLY);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int sdp32_write_cmd(int handle, uint16_t cmd)
{
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (i2cWriteDevice(handle, (char *)buf, 2) != 0) {
        fprintf(stderr, "I2C write failed (cmd 0x%04X)\n", cmd);
        return -1;
    }
    return 0;
}

static int sdp32_start(int handle)
{
    return sdp32_write_cmd(handle, SDP32_CMD_CONT_MEAS);
}

static int sdp32_stop(int handle)
{
    return sdp32_write_cmd(handle, SDP32_CMD_STOP_MEAS);
}

