/*
 * SDP810-125Pa differential pressure sensor reader for Raspberry Pi 4.
 *
 * Wiring:
 *   SDP810 SDA  -> GPIO2 (BCM 2, I2C bus 1 SDA)
 *   SDP810 SCL  -> GPIO3 (BCM 3, I2C bus 1 SCL)
 *   SDP810 VDD  -> 3.3 V
 *   SDP810 GND  -> GND
 *
 * I2C bus 1 on the Pi 4 exposes the user-accessible pins on the
 * 40-pin header (pins 3/5 SDA/SCL, 1/2 3V3/GND).
 *
 * Build:  gcc -O2 -Wall -Wextra -o sdp810 sdp810.c -li2c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SDP810_ADDR    0x21
#define TRIGGER_CMD    0x362F   /* single-shot, average, no clock stretching */
#define CONV_DELAY_MS  45       /* SDP810 conversion time */
#define SAMPLE_PERIOD  1        /* seconds between samples */

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* Sensirion CRC-8: polynomial 0x31, init 0xFF, no reflect, no final XOR. */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/*
 * Read one 9-byte sample from the SDP810.
 * Layout: [P_msb, P_lsb, P_crc, T_msb, T_lsb, T_crc, S_msb, S_lsb, S_crc]
 * Returns 0 on success, -1 on error.
 */
static int sdp810_read(int fd, float *pressure, float *temperature)
{
    uint8_t cmd[2] = {
        (uint8_t)((TRIGGER_CMD >> 8) & 0xFF),
        (uint8_t)(TRIGGER_CMD & 0xFF)
    };

    if (write(fd, cmd, sizeof(cmd)) != (ssize_t)sizeof(cmd)) {
        fprintf(stderr, "I2C write trigger failed: %s\n", strerror(errno));
        return -1;
    }

    usleep(CONV_DELAY_MS * 1000);

    uint8_t buf[9];
    ssize_t n = read(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        if (n < 0)
            fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        else
            fprintf(stderr, "I2C short read: %zd bytes\n", n);
        return -1;
    }

    /* CRC validation of each 3-byte word. */
    for (int i = 0; i < 3; i++) {
        if (crc8(&buf[i * 3], 2) != buf[i * 3 + 2]) {
            fprintf(stderr, "CRC mismatch on word %d\n", i);
            return -1;
        }
    }

    int16_t raw_p = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_t = (int16_t)((buf[3] << 8) | buf[4]);
    int16_t raw_s = (int16_t)((buf[6] << 8) | buf[7]);

    *pressure    = (float)raw_p / (float)raw_s;
    *temperature = (float)raw_t / 200.0f;

    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, SDP810_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                SDP810_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /* Quick presence check: a zero-length write returns 0 on success. */
    if (write(fd, NULL, 0) < 0) {
        fprintf(stderr, "Sensor not responding at 0x%02X: %s\n",
                SDP810_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    printf("SDP810-125Pa reader started (I2C bus 1, addr 0x%02X). Ctrl+C to exit.\n",
           SDP810_ADDR);

    while (g_running) {
        float pressure, temperature;

        if (sdp810_read(fd, &pressure, &temperature) == 0) {
            printf("Pressure: %.2f Pa, Temperature: %.2f °C\n",
                   pressure, temperature);
        } else {
            fprintf(stderr, "Read failed; continuing.\n");
        }

        sleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down.\n");
    close(fd);
    return EXIT_SUCCESS;
}

