#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define HDC1000_ADDR        0x40
#define HDC1000_TEMP_REG    0x00
#define HDC1000_CONFIG_REG  0x02
#define HDC1000_MANUF_ID    0x0A81
#define HDC1000_DEV_ID      0x0105

static volatile sig_atomic_t g_running = 1;
static int g_fd = -1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg16(int fd, uint8_t reg, uint16_t val) {
    uint8_t buf[3] = { reg, (uint8_t)(val >> 8), (uint8_t)(val & 0xFF) };
    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int verify_sensor(int fd) {
    uint16_t manuf_id = 0, dev_id = 0;
    if (i2c_read_reg16(fd, 0xFF, &manuf_id) < 0) return -1;
    if (manuf_id != HDC1000_MANUF_ID) {
        fprintf(stderr, "Unexpected manufacturer ID: 0x%04X (expected 0x%04X)\n", manuf_id, HDC1000_MANUF_ID);
        return -1;
    }
    if (i2c_read_reg16(fd, 0xFE, &dev_id) < 0) return -1;
    if (dev_id != HDC1000_DEV_ID) {
        fprintf(stderr, "Unexpected device ID: 0x%04X (expected 0x%04X)\n", dev_id, HDC1000_DEV_ID);
        return -1;
    }
    printf("HDC1000 verified (manuf=0x%04X, dev=0x%04X)\n", manuf_id, dev_id);
    return 0;
}

static int read_hdc1000(int fd, float *temperature, float *humidity) {
    /* Config: 14-bit temp + 14-bit humidity, heater off, mode = T+RH */
    uint16_t config = 0x1000;
    if (i2c_write_reg16(fd, HDC1000_CONFIG_REG, config) < 0) return -1;

    /* 14-bit conversion takes ~6.5 ms; wait 20 ms for safety */
    usleep(20000);

    uint16_t raw_t = 0, raw_h = 0;
    if (i2c_read_reg16(fd, HDC1000_TEMP_REG, &raw_t) < 0) return -1;
    if (i2c_read_reg16(fd, HDC1000_TEMP_REG, &raw_h) < 0) return -1;

    *temperature = ((float)raw_t / 65536.0f) * 165.0f - 40.0f;
    *humidity    = ((float)raw_h / 65536.0f) * 100.0f;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
