/*
 * MLX90833 Absolute Pressure Sensor Reader for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   MLX90833 SDA  -> GPIO2 (I2C1 SDA, pin 3)
 *   MLX90833 SCL  -> GPIO3 (I2C1 SCL, pin 5)
 *   MLX90833 VDD  -> 3.3 V
 *   MLX90833 GND  -> GND
 *
 * I2C address: 0x77 (7-bit, default for MLX90833)
 *
 * Build: gcc -O2 -Wall -Wextra -o mlx90833_reader mlx90833_reader.c -lpigpio -lrt
 * Run:   sudo ./mlx90833_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x77
#define SAMPLE_PERIOD  0.5   /* seconds */
#define MAX_RETRIES    3

/* MLX90833 register addresses (16-bit, big-endian on the bus) */
#define REG_PRESSURE   0x0000  /* Absolute pressure, 16-bit signed, 0.1 Pa LSB */
#define REG_TEMP       0x0002  /* Temperature, 16-bit signed, 0.1 °C LSB */
#define REG_STATUS     0x0004  /* Status register */

#define STATUS_READY   0x0001  /* Bit 0: data ready */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0)
        perror("warning: sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) != 0)
        perror("warning: sigaction(SIGTERM)");
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg16(int handle, uint16_t reg)
{
    char buf[2] = { (char)(reg >> 8), (char)(reg & 0xFF) };
    return i2cWriteDevice(handle, buf, 2);
}

static int i2c_read_reg16(int handle, uint16_t reg, int16_t *out)
{
    char wbuf[2] = { (char)(reg >> 8), (char)(reg & 0xFF) };
    char rbuf[2] = {0, 0};

    if (i2cWriteDevice(handle, wbuf, 2) != 0)
        return -1;

    /* Small delay so the sensor can clock out the data */
    gpioDelay(2000); /* 2 ms */

    if (i2cReadDevice(handle, rbuf, 2) != 2)
        return -1;

    *out = (int16_t)(((uint16_t)(uint8_t)rbuf[0] << 8) | (uint8_t)rbuf[1]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor operations                                                   */
/* ------------------------------------------------------------------ */
static int wait_for_data_ready(int handle, uint32_t timeout_ms)
{
    int16_t status;
    uint32_t elapsed = 0;

    while (elapsed < timeout_ms) {
        if (i2c_read_reg16(handle, REG_STATUS, &status) != 0) {
            fprintf(stderr, "Error: failed to read status register\n");
            return -1;
        }
        if (status & STATUS_READY)
            return 0;
        gpioDelay(10000); /* 10 ms */
        elapsed += 10;
    }

    fprintf(stderr, "Error: data not ready within %u ms\n", timeout_ms);
    return -1;
}

static int read_pressure(int handle, float *pressure)
{
    int16_t raw;

    if (wait_for_data_ready(handle, 500) != 0)
        return -1;

    if (i2c_read_reg16(handle, REG_PRESSURE, &raw) != 0) {
        fprintf(stderr, "Error: failed to read pressure register\n");
        return -1;
    }

    /* 0.1 Pa LSB */
    *pressure = (float)raw / 10.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    float pressure;
    time_t now;
    struct tm tm_info;
    char ts[32];

    install_signal_handlers();

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("MLX90833 pressure reader started. Press Ctrl+C to exit.\n");

    while (g_running) {
        if (read_pressure(g_i2c_handle, &pressure) == 0) {
            time(&now);
            localtime_r(&now, &tm_info);
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
            printf("[%s] Pressure: %.2f Pa\n", ts, pressure);
            fflush(stdout);
        } else {
            fprintf(stderr, "Warning: read failed, retrying next cycle\n");
        }

        /* Sleep in small increments so signals are caught promptly */
        for (int i = 0; i < 50 && g_running; i++)
            gpioDelay(10000); /* 10 ms */
    }

    /* Clean shutdown */
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

