#include <fcntl.h>

#define I2C_BUS        "/dev/i2c-1"
#define ICP10101_ADDR  0x77

/* ICP-10101 register addresses (16-bit, big-endian on the bus) */
#define REG_MEAS_CMD   0x00
#define REG_TEMP_MSB   0x01
#define REG_TEMP_LSB   0x02
#define REG_PRES_MSB   0x03
#define REG_PRES_LSB   0x04

/* Measurement command: bit 0 = 1 → start one-shot conversion */
#define MEAS_CMD_START 0x01

/* Conversion time: 7 ms (typical) */
#define MEAS_DELAY_MS  7

/* Sampling interval: 5 s */
#define SAMPLE_INTERVAL_S 5

/* Default values returned when the sensor is absent or unresponsive */
#define DEFAULT_TEMP 25.0f
#define DEFAULT_PRES 101325.0f

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *out)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    uint8_t val;
    if (read(fd, &val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = val;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor abstraction                                                  */
/* ------------------------------------------------------------------ */

typedef struct {
    int fd;
} sensor_t;

static int sensor_init(sensor_t *s)
{
    s->fd = open(I2C_BUS, O_RDWR);
    if (s->fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(s->fd, I2C_SLAVE, ICP10101_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                ICP10101_ADDR, strerror(errno));
        close(s->fd);
        s->fd = -1;
        return -1;
    }
    return 0;
}

static void sensor_close(sensor_t *s)
{
    if (s->fd >= 0) {
        close(s->fd);
        s->fd = -1;
    }
}

/*
 * Trigger a one-shot measurement and read the 3-byte result.
 * Returns 0 on success, -1 on any I2C error.
 */
static int sensor_read(sensor_t *s, float *temperature, float *pressure)
{
    /* Trigger measurement */
    if (i2c_write_reg8(s->fd, REG_MEAS_CMD, MEAS_CMD_START) < 0)
        return -1;

    /* Wait for conversion to complete */
    usleep(MEAS_DELAY_MS * 1000);

    /* Read temperature (2 bytes) and pressure (2 bytes) */
    uint8_t t_msb, t_lsb, p_msb, p_lsb;
    if (i2c_read_reg8(s->fd, REG_TEMP_MSB, &t_msb) < 0) return -1;
    if (i2c_read_reg8(s->fd, REG_TEMP_LSB, &t_lsb) < 0) return -1;
    if (i2c_read_reg8(s->fd, REG_PRES_MSB, &p_msb) < 0) return -1;
    if (i2c_read_reg8(s->fd, REG_PRES_LSB, &p_lsb) < 0) return -1;

    /* Assemble 16-bit big-endian values */
    int16_t raw_temp = (int16_t)((t_msb << 8) | t_lsb);
    int16_t raw_pres = (int16_t)((p_msb << 8) | p_lsb);

    /* Convert to physical units (per datasheet) */
    *temperature = (float)raw_temp / 100.0f;
    *pressure    = (float)raw_pres / 100.0f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */

static void log_data(float temperature, float pressure)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    printf("%s - Temperature: %.2f C, Pressure: %.2f Pa\n",
           ts, temperature, pressure);
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    sensor_t sensor;
    memset(&sensor, 0, sizeof(sensor));

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (sensor_init(&sensor) < 0) {
        return EXIT_FAILURE;
    }

    printf("ICP-10101 sensor reader started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float temperature, pressure;

        if (sensor_read(&sensor, &temperature, &pressure) == 0) {
            log_data(temperature, pressure);
        } else {
            fprintf(stderr, "Sensor read failed; using default values.\n");
            log_data(DEFAULT_TEMP, DEFAULT_PRES);
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_S * 10 && g_running; i++) {
            usleep(100 * 1000);
        }
    }

    sensor_close(&sensor);
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

