#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MLX90819_ADDR  0x3C
#define PRESSURE_REG   0x00
#define SAMPLE_PERIOD  1

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo) {
    (void)signo;
    g_running = 0;
}

static void install_signal_handlers(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
    }
}

static void print_timestamp(void) {
    time_t now = time(NULL);
    struct tm tm_info;
    char buf[32];
    if (localtime_r(&now, &tm_info) != NULL &&
        strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", &tm_info) > 0) {
        printf("[%s] ", buf);
    }
}

int main(void) {
    int fd = -1;
    int ret = EXIT_FAILURE;

    install_signal_handlers();

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, MLX90819_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n",
                MLX90819_ADDR, strerror(errno));
        goto cleanup;
    }

    printf("MLX90819 Pressure Sensor Reader\n");
    printf("Bus: %s, Address: 0x%02X, Register: 0x%02X\n",
           I2C_BUS, MLX90819_ADDR, PRESSURE_REG);
    printf("Press Ctrl+C to exit.\n\n");

    while (g_running) {
        uint8_t reg = PRESSURE_REG;
        uint8_t buf[2] = {0};
        ssize_t wret, rret;

        wret = write(fd, &reg, 1);
        if (wret < 0) {
            print_timestamp();
            fprintf(stderr, "I2C write error: %s\n", strerror(errno));
            goto sleep_and_continue;
        }
        if (wret != 1) {
            print_timestamp();
            fprintf(stderr, "I2C write short write: %zd bytes\n", wret);
            goto sleep_and_continue;
        }

        /* Small delay to let the sensor prepare the response */
        usleep(10000);

        rret = read(fd, buf, 2);
        if (rret < 0) {
            print_timestamp();
            fprintf(stderr, "I2C read error: %s\n", strerror(errno));
            goto sleep_and_continue;
        }
        if (rret != 2) {
            print_timestamp();
            fprintf(stderr, "I2C read short read: %zd bytes\n", rret);
            goto sleep_and_continue;
        }

        uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
        float pressure = (float)raw / 10.0f;

        print_timestamp();
        printf("Pressure: %.2f bar\n", pressure);

    sleep_and_continue:
        for (int i = 0; i < SAMPLE_PERIOD && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nExiting cleanly.\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    return ret;
}

