#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define SDP800_ADDR 0x21
#define TRIGGER_CMD 0x362F
#define LOG_FILE "airflow_log.csv"
#define READ_INTERVAL_MS 100
#define TRIGGER_DELAY_MS 8

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int i2c_write_cmd(int fd, uint16_t cmd) {
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, int len) {
    int total = 0;
    while (total < len) {
        int n = read(fd, buf + total, len - total);
        if (n < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
            return -1;
        }
        if (n == 0) {
            fprintf(stderr, "I2C read: unexpected EOF (sensor absent?)\n");
            return -1;
        }
        total += n;
    }
    return 0;
}

static int read_pressure(int fd, float *pressure) {
    if (i2c_write_cmd(fd, TRIGGER_CMD) < 0) return -1;

    usleep(TRIGGER_DELAY_MS * 1000);

    uint8_t data[3];
    if (i2c_read_bytes(fd, data, 3) < 0) return -1;

    if (crc8(data, 2) != data[2]) {
        fprintf(stderr, "CRC mismatch: computed 0x%02X, received 0x%02X\n",
                crc8(data, 2), data[2]);
        return -1;
    }

    int16_t raw = (int16_t)((data[0] << 8) | data[1]);
    *pressure = (float)raw / 100.0f;
    return 0;
}

static int log_data(const char *filename, float pressure) {
    int write_header = 0;
    if (access(filename, F_OK) != 0) {
        if (errno == ENOENT) {
            write_header = 1;
        } else {
            fprintf(stderr, "access() failed: %s\n", strerror(errno));
            return -1;
        }
    }

    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", filename, strerror(errno));
        return -1;
    }

    if (write_header) {
        fprintf(fp, "Timestamp,Pressure (Pa)\n");
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f\n", timestamp, pressure);

    if (fclose(fp) != 0) {
        fprintf(stderr, "fclose failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, SDP800_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                SDP800_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    printf("SDP800 airflow monitor started. Logging to %s\n", LOG_FILE);

    while (running) {
        float pressure;
        if (read_pressure(fd, &pressure) < 0) {
            fprintf(stderr, "Read failed; continuing after delay.\n");
            usleep(READ_INTERVAL_MS * 1000);
            continue;
        }

        if (log_data(LOG_FILE, pressure) < 0) {
            fprintf(stderr, "Logging failed; continuing.\n");
        }

        usleep(READ_INTERVAL_MS * 1000);
    }

    printf("\nShutting down cleanly.\n");
    close(fd);
    return 0;
}

