code:
/*
 * MLX90821 relative pressure logger for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   MLX90821 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   MLX90821 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   MLX90821 VDD  -> 3.3 V
 *   MLX90821 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o mlx90821_log mlx90821_log.c -lm
 * Run:    ./mlx90821_log
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <math.h>

#include <pigpio.h>

/* ---- Configuration ---- */
#define I2C_BUS            1
#define I2C_ADDR           0x0E          /* MLX90821 7-bit I2C address */
#define LOG_FILE           "pressure_log.csv"
#define SAMPLE_PERIOD_US   1000000       /* 1 second */
#define SAFE_MIN_KPA       200.0
#define SAFE_MAX_KPA       250.0

/*
 * MLX90821 pressure conversion (example).
 * The exact formula depends on the specific sensor variant and
 * calibration coefficients.  This is a placeholder that yields
 * physically plausible results over the 200-250 kPa range.
 */
#define PRESSURE_SCALE     0.001
#define PRESSURE_OFFSET    200.0

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- I2C helpers ---- */
static int i2c_open_if_closed(void)
{
    if (g_i2c_handle >= 0)
        return 0;

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen failed (pigpio code %d): %s\n",
                g_i2c_handle, strerror(errno));
        g_i2c_handle = -1;
        return -1;
    }
    return 0;
}

static void i2c_close(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
}

/*
 * Read the MLX90821 pressure register (0x00) and convert to kPa.
 * Returns 0 on success, -1 on failure.
 */
static int read_pressure_kPa(double *out_kPa)
{
    if (i2c_open_if_closed() != 0)
        return -1;

    int raw = i2cReadWordData(g_i2c_handle, 0x00);
    if (raw < 0) {
        fprintf(stderr, "[ERROR] i2cReadWordData failed (pigpio code %d): %s\n",
                raw, strerror(errno));
        i2c_close();
        return -1;
    }

    /* pigpio returns the word as (msb << 8) | lsb, which matches the
     * MLX90821 16-bit register layout. */
    double pressure = (double)raw * PRESSURE_SCALE + PRESSURE_OFFSET;
    *out_kPa = pressure;
    return 0;
}

/* ---- Logging ---- */
static int log_open(void)
{
    long sz = 0;
    FILE *f = fopen(LOG_FILE, "r");
    if (f) {
        fseek(f, 0, SEEK_END);
        sz = ftell(f);
        fclose(f);
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        fprintf(stderr, "[ERROR] Cannot open %s: %s\n",
                LOG_FILE, strerror(errno));
        return -1;
    }

    if (sz == 0) {
        fprintf(g_log_file, "timestamp,pressure_kPa\n");
        fflush(g_log_file);
    }
    return 0;
}

static void log_close(void)
{
    if (g_log_file) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
}

static void log_data(double pressure_kPa)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    fprintf(g_log_file, "%s,%.2f\n", ts, pressure_kPa);
    fflush(g_log_file);
}

/* ---- Safe-range check ---- */
static void check_safe_range(double pressure_kPa)
{
    if (pressure_kPa < SAFE_MIN_KPA || pressure_kPa > SAFE_MAX_KPA) {
        fprintf(stderr,
                "[WARN] Pressure %.2f kPa outside safe range [%.0f-%.0f] kPa\n",
                pressure_kPa, SAFE_MIN_KPA, SAFE_MAX_KPA);
    }
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    i2c_close();
    log_close();
    gpioTerminate();
}

/* ---- Main ---- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C once so we can retry on transient failures */
    if (i2c_open_if_closed() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file */
    if (log_open() != 0) {
        i2c_close();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MLX90821 pressure logger started.  Logging to %s every 1 s.\n",
           LOG_FILE);
    printf("Press Ctrl+C to stop.\n");

    while (g_running) {
        double pressure_kPa = 0.0;

        if (read_pressure_kPa(&pressure_kPa) == 0) {
            log_data(pressure_kPa);
            check_safe_range(pressure_kPa);
        } else {
            fprintf(stderr, "[WARN] I2C read failed; re-opening bus and retrying.\n");
            i2c_close();
            if (i2c_open_if_closed() != 0) {
                fprintf(stderr, "[FATAL] Re-open failed; exiting.\n");
                break;
            }
            if (read_pressure_kPa(&pressure_kPa) == 0) {
                log_data(pressure_kPa);
                check_safe_range(pressure_kPa);
            } else {
                fprintf(stderr, "[FATAL] Retry failed; exiting.\n");
                break;
            }
        }

        /* Sleep 1 s, but wake early on signal */
        for (int i = 0; i < 10 && g_running; i++)
            usleep(100000);
    }

    cleanup();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

