#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define HIH6130_ADDR 0x27
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "environmental_data.log"
#define LOG_SIZE_LIMIT (1024 * 1024)
#define MEASUREMENT_INTERVAL 5
#define CONVERSION_DELAY_MS 40

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len) {
    if (read(fd, buf, len) != (ssize_t)len) {
        return -1;
    }
    return 0;
}

static int read_hih6130(int fd, float *temperature, float *humidity) {
    uint8_t buf[5];

    if (ioctl(fd, I2C_SLAVE, HIH6130_ADDR) < 0) {
        return -1;
    }

    if (i2c_read_bytes(fd, buf, 5) < 0) {
        return -1;
    }

    uint8_t status = buf[0] & 0x0F;

    if (status != 0x00) {
        return -2;
    }

    uint16_t raw_humidity = ((uint16_t)(buf[0] & 0x30) << 8) | buf[1];
    uint16_t raw_temperature = ((uint16_t)buf[2] << 6) | (buf[3] >> 2);

    *humidity = ((float)raw_humidity / 16383.0f) * 100.0f;
    *temperature = ((float)raw_temperature / 16383.0f) * 165.0f - 40.0f;

    return 0;
}

static int log_data(const char *filename, float temperature, float humidity) {
    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fclose(fp);
        return -1;
    }

    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);

    fprintf(fp, "%s, Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, temperature, humidity);
    fclose(fp);
    return 0;
}

static int check_log_size(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        return 0;
    }

    fseek(fp, 0, SEEK_END);
    long size = ftell(fp);
    fclose(fp);

    if (size > LOG_SIZE_LIMIT) {
        fp = fopen(filename, "w");
        if (fp == NULL) {
            return -1;
        }
        fclose(fp);
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open " I2C_BUS);
        return 1;
    }

    while (running) {
        if (ioctl(fd, I2C_SLAVE, HIH6130_ADDR) < 0) {
            fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
            sleep(1);
            continue;
        }

        uint8_t trigger = 0x00;
        if (write(fd, &trigger, 1) < 0) {
            fprintf(stderr, "Error triggering measurement: %s\n", strerror(errno));
            sleep(1);
            continue;
        }

        usleep(CONVERSION_DELAY_MS * 1000);

        float temperature, humidity;
        int ret = read_hih6130(fd, &temperature, &humidity);

        if (ret == 0) {
            if (log_data(LOG_FILE, temperature, humidity) < 0) {
                fprintf(stderr, "Error logging data: %s\n", strerror(errno));
            }
            if (check_log_size(LOG_FILE) < 0) {
                fprintf(stderr, "Error checking log size: %s\n", strerror(errno));
            }
        } else if (ret == -1) {
            fprintf(stderr, "Error reading from I2C bus: %s\n", strerror(errno));
        } else {
            fprintf(stderr, "Sensor status error (non-zero status).\n");
        }

        for (int i = 0; i < MEASUREMENT_INTERVAL && running; i++) {
            sleep(1);
        }
    }

    close(fd);
    return 0;
}

