#define MAX_PSI          1000.0f
#define MIN_PSI          0.0f

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read one SENT frame from the single-wire line.
 * Returns 0 on success and fills *pressure_kPa.
 * Returns -1 on timeout, -2 on checksum error, -3 on out-of-range pulse.
 */
static int read_sent_frame(float *pressure_kPa)
{
    uint32_t start_tick, now_tick;
    uint32_t pulse_width;
    uint32_t ticks;
    int nibble;
    uint8_t data_nibbles[4] = {0};
    uint8_t status_nibble = 0;
    uint8_t checksum_nibble = 0;
    int valid = 0;

    /* --- Wait for the falling edge of the sync pulse (line goes low) --- */
    start_tick = gpioTick();
    while (gpioRead(SENT_GPIO) == 1) {
        if (gpioTick() - start_tick > 1000000) /* 1 s timeout */
            return -1;
    }
    start_tick = gpioTick();

    /* --- Measure the sync pulse width (ticks since line went low) --- */
    while (gpioRead(SENT_GPIO) == 0) {
        if (gpioTick() - start_tick > 1000000)
            return -1;
    }
    now_tick = gpioTick();
    pulse_width = now_tick - start_tick;

    if (pulse_width < (SYNC_TICKS * 2) || pulse_width > (SYNC_TICKS * 4))
        return -3;

    /* --- Read the 4 data nibbles --- */
    for (nibble = 0; nibble < 4; nibble++) {
        start_tick = now_tick;
        while (gpioRead(SENT_GPIO) == 1) {
            if (gpioTick() - start_tick > 1000000)
                return -1;
        }
        start_tick = gpioTick();
        while (gpioRead(SENT_GPIO) == 0) {
            if (gpioTick() - start_tick > 1000000)
                return -1;
        }
        now_tick = gpioTick();
        pulse_width = now_tick - start_tick;

        if (pulse_width < MIN_TICKS || pulse_width > MAX_TICKS)
            return -3;

        data_nibbles[nibble] = (uint8_t)(pulse_width - MIN_TICKS);
    }

    /* --- Read status nibble --- */
    start_tick = now_tick;
    while (gpioRead(SENT_GPIO) == 1) {
        if (gpioTick() - start_tick > 1000000)
            return -1;
    }
    start_tick = gpioTick();
    while (gpioRead(SENT_GPIO) == 0) {
        if (gpioTick() - start_tick > 1000000)
            return -1;
    }
    now_tick = gpioTick();
    pulse_width = now_tick - start_tick;

    if (pulse_width < MIN_TICKS || pulse_width > MAX_TICKS)
        return -3;
    status_nibble = (uint8_t)(pulse_width - MIN_TICKS);

    /* --- Read checksum nibble --- */
    start_tick = now_tick;
    while (gpioRead(SENT_GPIO) == 1) {
        if (gpioTick() - start_tick > 1000000)
            return -1;
    }
    start_tick = gpioTick();
    while (gpioRead(SENT_GPIO) == 0) {
        if (gpioTick() - start_tick > 1000000)
            return -1;
    }
    now_tick = gpioTick();
    pulse_width = now_tick - start_tick;

    if (pulse_width < MIN_TICKS || pulse_width > MAX_TICKS)
        return -3;
    checksum_nibble = (uint8_t)(pulse_width - MIN_TICKS);

    /* --- Validate checksum (sum of nibbles modulo 16) --- */
    uint8_t calc = (uint8_t)((data_nibbles[0] + data_nibbles[1] +
                              data_nibbles[2] + data_nibbles[3] +
                              status_nibble) % 16);
    if (calc != checksum_nibble)
        return -2;

    /* --- Assemble 16-bit raw value and convert to kPa --- */
    uint16_t raw = ((uint16_t)data_nibbles[0] << 12) |
                   ((uint16_t)data_nibbles[1] << 8)  |
                   ((uint16_t)data_nibbles[2] << 4)  |
                   ((uint16_t)data_nibbles[3]);

    /* Example conversion: raw 0–65535 maps to 0–MAX_PSI kPa */
    float kPa = (float)raw / 65535.0f * MAX_PSI;
    if (kPa < MIN_PSI || kPa > MAX_PSI) {
        fprintf(stderr, "Warning: pressure %.2f kPa out of range\n", kPa);
        return -4;
    }

    *pressure_kPa = kPa;
    return 0;
}

static void log_pressure(float pressure_kPa)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Pressure: %.2f kPa\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, pressure_kPa);
    } else {
        fprintf(fp, "Timestamp error, Pressure: %.2f kPa\n", pressure_kPa);
    }

    fclose(fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(SENT_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENT_GPIO, PI_PUD_UP); /* SENT bus idles high */

    printf("MLX90824 SENT Pressure Sensor Reader\n");
    printf("Logging to %s. Press Ctrl+C to exit.\n", LOG_FILE);

    while (g_running) {
        float pressure_kPa;
        int rc = read_sent_frame(&pressure_kPa);

        if (rc == 0) {
            log_pressure(pressure_kPa);
            printf("Pressure: %.2f kPa\n", pressure_kPa);
        } else if (rc == -1) {
            fprintf(stderr, "Error: SENT frame timeout (sensor absent or bus error)\n");
        } else if (rc == -2) {
            fprintf(stderr, "Error: SENT checksum mismatch\n");
        } else if (rc == -3) {
            fprintf(stderr, "Error: SENT out-of-range pulse width\n");
        } else if (rc == -4) {
            fprintf(stderr, "Warning: pressure out of valid range\n");
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

