/*
 * greenhouse_monitor.c
 *
 * Raspberry Pi Zero W – TMP117 Greenhouse Temperature Monitor
 *
 * Hardware:
 *   TMP117 SDA  -> GPIO2 (pin 3)
 *   TMP117 SCL  -> GPIO3 (pin 5)
 *   TMP117 VDD  -> 3.3 V
 *   TMP117 GND  -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o greenhouse_monitor greenhouse_monitor.c \
 *       -li2c -lm
 *
 * Run:
 *   ./greenhouse_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#include <linux/i2c.h>

/* ---- TMP117 constants (per datasheet) ---- */
#define TMP117_I2C_ADDR        0x48
#define TMP117_REG_TEMP_RESULT 0x00
#define TMP117_REG_CONFIG      0x01
#define TMP117_REG_DEVICE_ID   0x0F

#define TMP117_DEVICE_ID       0x0117  /* bits [15:8] of device ID register */
#define TMP117_CONFIG_DEFAULT  0x1000 /* 12-bit resolution, continuous mode */

#define LOG_FILE_NAME          "greenhouse_temps.dat"
#define SAMPLE_INTERVAL_SEC    60

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit value to a TMP117 register (big-endian on the wire). */
static int tmp117_write_reg16(int fd, uint8_t reg, uint16_t value)
{
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (uint8_t)((value >> 8) & 0xFF);
    buf[2] = (uint8_t)(value & 0xFF);

    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit value from a TMP117 register (big-endian on the wire). */
static int tmp117_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t buf[2];

    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    if (read(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read the TMP117 device ID to verify the sensor is present.         */
static int tmp117_verify_device_id(int fd)
{
    uint16_t id = 0;

    if (tmp117_read_reg16(fd, TMP117_REG_DEVICE_ID, &id) != 0)
        return -1;

    /* Bits [15:8] of the device ID register hold the manufacturer ID. */
    uint16_t manufacturer_id = (id >> 8) & 0xFF;
    if (manufacturer_id != 0x55) {
        fprintf(stderr,
                "Unexpected manufacturer ID 0x%02X (expected 0x55). "
                "Sensor not present or wrong device.\n", manufacturer_id);
        return -1;
    }

    /* Bits [7:0] are the device ID; the TMP117 reports 0x17. */
    uint16_t device_id = id & 0xFF;
    if (device_id != TMP117_DEVICE_ID) {
        fprintf(stderr,
                "Unexpected device ID 0x%02X (expected 0x%02X).\n",
                device_id, TMP117_DEVICE_ID);
        return -1;
    }

    printf("TMP117 verified: device ID 0x%02X, manufacturer ID 0x%02X\n",
           device_id, manufacturer_id);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Configure the TMP117 for continuous 12-bit conversion mode.        */
static int tmp117_configure(int fd)
{
    return tmp117_write_reg16(fd, TMP117_REG_CONFIG, TMP117_CONFIG_DEFAULT);
}

/* ------------------------------------------------------------------ */
/* Read the current temperature in degrees Celsius.                    */
static int tmp117_read_temperature(int fd, float *temperature)
{
    uint16_t raw = 0;

    if (tmp117_read_reg16(fd, TMP117_REG_TEMP_RESULT, &raw) != 0)
        return -1;

    /*
     * TMP117 12-bit mode: bits [15:4] hold the signed temperature.
     * Resolution is 0.0078125 °C per LSB (1/128).
     */
    int16_t signed_raw = (int16_t)(raw << 4) >> 4;  /* sign-extend */
    *temperature = (float)signed_raw * 0.0078125f;
    return 0;
}

/* ------------------------------------------------------------------ */
static int log_temperature(float temperature)
{
    if (g_log_fp == NULL) {
        fprintf(stderr, "Log file not open.\n");
        return -1;
    }

    /* Write as a 4-byte little-endian float. */
    uint8_t bytes[4];
    uint32_t raw = (uint32_t)(temperature * 100.0f); /* centi-degrees */
    bytes[0] = (uint8_t)(raw & 0xFF);
    bytes[1] = (uint8_t)((raw >> 8) & 0xFF);
    bytes[2] = (uint8_t)((raw >> 16) & 0xFF);
    bytes[3] = (uint8_t)((raw >> 24) & 0xFF);

    if (fwrite(bytes, sizeof(bytes), 1, g_log_fp) != 1) {
        fprintf(stderr, "Failed to write temperature to log: %s\n",
                strerror(errno));
        return -1;
    }

    fflush(g_log_fp);
    return 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus ---- */
    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open /dev/i2c-1: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, TMP117_I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                TMP117_I2C_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Verify sensor identity ---- */
    if (tmp117_verify_device_id(g_i2c_fd) != 0) {
        fprintf(stderr, "TMP117 not detected on bus.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Configure sensor ---- */
    if (tmp117_configure(g_i2c_fd) != 0) {
        fprintf(stderr, "Failed to configure TMP117.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_fp = fopen(LOG_FILE_NAME, "wb");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n",
                LOG_FILE_NAME, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Greenhouse temperature monitoring started.\n");
    printf("Logging to '%s' every %d seconds. Press Ctrl+C to exit.\n",
           LOG_FILE_NAME, SAMPLE_INTERVAL_SEC);

    /* ---- Main sampling loop ---- */
    while (g_running) {
        float temperature = 0.0f;

        if (tmp117_read_temperature(g_i2c_fd, &temperature) == 0) {
            printf("Temperature: %.2f °C\n", temperature);
            if (log_temperature(temperature) != 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            }
        } else {
            fprintf(stderr, "Failed to read temperature from TMP117.\n");
        }

        /* Sleep in 1-second increments so signals are caught promptly. */
        for (int i = 0; i < SAMPLE_INTERVAL_SEC && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down gracefully.\n");
    cleanup();
    return EXIT_SUCCESS;
}

