#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define TEMP_REG 0x00
#define CONFIG_REG 0x01
#define CONFIG_DEFAULT 0x1000
#define BUFFER_SIZE 10
#define LOG_FILE "temperature_log.dat"
#define SAMPLE_INTERVAL_SEC 5

typedef struct {
    time_t timestamp;
    float temperature;
} TemperatureReading;

typedef struct {
    TemperatureReading readings[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

static int i2c_handle = -1;
static CircularBuffer buffer;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %s\n",
                I2C_BUS, TMP117_ADDR, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_tmp117(void) {
    if (i2cWriteWordData(i2c_handle, CONFIG_REG, CONFIG_DEFAULT) < 0) {
        fprintf(stderr, "Error writing config register: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_temperature(float *temp) {
    int raw = i2cReadWordData(i2c_handle, TEMP_REG);
    if (raw < 0) {
        fprintf(stderr, "Error reading temperature register: %s\n", strerror(errno));
        return -1;
    }
    int16_t val = (int16_t)raw;
    *temp = (float)val * 0.0078125f;
    return 0;
}

static void add_reading(CircularBuffer *buf, float temp) {
    time(&buf->readings[buf->head].timestamp);
    buf->readings[buf->head].temperature = temp;
    buf->head = (buf->head + 1) % BUFFER_SIZE;
    if (buf->count < BUFFER_SIZE) buf->count++;
}

static void flush_buffer_to_file(const CircularBuffer *buf) {
    FILE *fp = fopen(LOG_FILE, "wb");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return;
    }
    int start = (buf->count == BUFFER_SIZE) ? buf->head : 0;
    for (int i = 0; i < buf->count; i++) {
        int idx = (start + i) % BUFFER_SIZE;
        if (fwrite(&buf->readings[idx], sizeof(TemperatureReading), 1, fp) != 1) {
            fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
            break;
        }
    }
    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
    }
}

static void cleanup(void) {
    flush_buffer_to_file(&buffer);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_tmp117() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    buffer.head = 0;
    buffer.count = 0;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting up signal handlers: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("TMP117 temperature logger started. Sampling every %d seconds. Press Ctrl+C to exit.\n",
           SAMPLE_INTERVAL_SEC);

    while (!terminate) {
        float temp;
        if (read_temperature(&temp) == 0) {
            add_reading(&buffer, temp);
            printf("Temperature: %.2f C\n", temp);
        } else {
            fprintf(stderr, "Skipping sample due to read error.\n");
        }
        time_sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    cleanup();
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

