        if (shtc3_measure(g_i2c_fd, &temperature, &humidity) < 0) {
            fprintf(stderr, "Measurement failed; continuing.\n");
        } else if (temperature < -40.0f || temperature > 125.0f ||
                   humidity < 0.0f   || humidity > 100.0f) {
            fprintf(stderr, "Out-of-range reading: T=%.2f C, RH=%.2f %%\n",
