/*
 * SHTC3 Temperature & Humidity Logger for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   SHTC3 VDD  -> Pi Pin 1  (3.3 V)
 *   SHTC3 VSS  -> Pi Pin 2  (GND)
 *   SHTC3 SDA  -> Pi Pin 3  (GPIO2 / I2C1 SDA)
 *   SHTC3 SCL  -> Pi Pin 4  (GPIO3 / I2C1 SCL)
 *
 * Build:  gcc -O2 -Wall -Wextra -o shtc3_logger shtc3_logger.c -li2c
 * Run:    sudo ./shtc3_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SHTC3_ADDR     0x70
#define LOG_FILE       "shtc3_environment.log"
#define SAMPLE_PERIOD  5          /* seconds between samples */
#define CONV_DELAY_MS  12         /* SHTC3 max conversion time ~12.4 ms */

/* SHTC3 commands (16-bit, MSB-first on the bus) */
static const uint8_t CMD_SLEEP[2]      = {0xB0, 0x98};
static const uint8_t CMD_WAKEUP[2]     = {0x35, 0x17};
static const uint8_t CMD_MEASURE[2]    = {0x24, 0x0B}; /* clock stretching disabled */
static const uint8_t CMD_SOFT_RESET[2] = {0x80, 0x5D};

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (polynomial 0x31, init 0xFF, no final XOR) — SHTC3 datasheet  */
/* ------------------------------------------------------------------ */
static uint8_t shtc3_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Low-level I2C helpers                                               */
/* ------------------------------------------------------------------ */
static int i2c_write_cmd(int fd, const uint8_t *cmd, size_t len)
{
    if (write(fd, cmd, len) != (ssize_t)len) {
        perror("i2c_write_cmd: write");
        return -1;
    }
    return 0;
}

static int i2c_read_data(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n != (ssize_t)len) {
        perror("i2c_read_data: read");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor operations                                                   */
/* ------------------------------------------------------------------ */
static int shtc3_soft_reset(int fd)
{
    return i2c_write_cmd(fd, CMD_SOFT_RESET, sizeof(CMD_SOFT_RESET));
}

static int shtc3_wakeup(int fd)
{
    return i2c_write_cmd(fd, CMD_WAKEUP, sizeof(CMD_WAKEUP));
}

static int shtc3_sleep(int fd)
{
    return i2c_write_cmd(fd, CMD_SLEEP, sizeof(CMD_SLEEP));
}

/*
 * Trigger a single measurement and read 6 bytes:
 *   [T_msb, T_lsb, T_crc, RH_msb, RH_lsb, RH_crc]
 */
static int shtc3_measure(int fd, float *temperature, float *humidity)
{
    if (i2c_write_cmd(fd, CMD_MEASURE, sizeof(CMD_MEASURE)) < 0)
        return -1;

    usleep(CONV_DELAY_MS * 1000);

    uint8_t data[6];
    if (i2c_read_data(fd, data, sizeof(data)) < 0)
        return -1;

    /* CRC checks */
    if (shtc3_crc8(&data[0], 2) != data[2]) {
        fprintf(stderr, "CRC error on temperature data\n");
        return -1;
    }
    if (shtc3_crc8(&data[3], 2) != data[5]) {
        fprintf(stderr, "CRC error on humidity data\n");
        return -1;
    }

    uint16_t t_raw = ((uint16_t)data[0] << 8) | data[1];
    uint16_t h_raw = ((uint16_t)data[3] << 8) | data[4];

    *temperature = -45.0f + 175.0f * (float)t_raw / 65535.0f;
    *humidity    = 100.0f * (float)h_raw / 65535.0f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_data(float temperature, float humidity)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("log_data: fopen");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("log_data: localtime_r");
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            temperature, humidity);

    if (fclose(fp) != 0) {
        perror("log_data: fclose");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        shtc3_sleep(g_i2c_fd);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        perror("open " I2C_BUS);
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SHTC3_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Wake up the sensor (SHTC3 powers down when idle) */
    if (shtc3_wakeup(g_i2c_fd) < 0) {
        fprintf(stderr, "Failed to wake up SHTC3\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Soft reset to ensure a known state */
    if (shtc3_soft_reset(g_i2c_fd) < 0) {
        fprintf(stderr, "Failed to reset SHTC3\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("SHTC3 logger started. Logging to %s every %d s. Press Ctrl+C to exit.\n",
           LOG_FILE, SAMPLE_PERIOD);

    while (g_running) {
        float temperature, humidity;

        if (shtc3_measure(g_i2c_fd, &temperature, &humidity) < 0) {
            fprintf(stderr, "Measurement failed; continuing.\n");
        } else if (temperature < -40.0f || temperature > 125.0f ||
                   humidity < 0.0f   || humidity > 100.0f) {
            fprintf(stderr, "Out-of-range reading: T=%.2f C, RH=%.2f %%\n",
                    temperature, humidity);
        } else {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n",
                   temperature, humidity);
            if (log_data(temperature, humidity) < 0)
                fprintf(stderr, "Failed to log data.\n");
        }

        /* Sleep SAMPLE_PERIOD seconds, but wake early on SIGINT */
        for (int i = 0; i < SAMPLE_PERIOD && g_running; i++)
            sleep(1);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

