/*
 * Si7202 I2C Hall-Effect Sensor - Rotational Speed & Temperature Logger
 * Board: Raspberry Pi 3 Model B+
 * Bus: I2C-1 (GPIO2=SDA, GPIO3=SCL), Address: 0x38
 *
 * Build: gcc -O2 -Wall -o si7202_logger si7202_logger.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x38
#define LOG_FILE       "mag_temp_log.csv"
#define SAMPLE_PERIOD  1.0   /* seconds between samples */

/* Si7202 register addresses */
#define REG_MAG_X_LSB  0x00
#define REG_MAG_X_MSB  0x01
#define REG_MAG_Y_LSB  0x02
#define REG_MAG_Y_MSB  0x03
#define REG_MAG_Z_LSB  0x04
#define REG_MAG_Z_MSB  0x05
#define REG_TEMP_LSB   0x06
#define REG_TEMP_MSB   0x07
#define REG_CTRL       0x08
#define REG_STATUS     0x09

/* CTRL register bits */
#define CTRL_MODE_HR   0x00  /* High-resolution mode */
#define CTRL_MODE_LP   0x01  /* Low-power mode */
#define CTRL_MODE_HR_LP 0x02 /* High-resolution + low-power */
#define CTRL_MODE_HR_LP_EN 0x03 /* High-resolution + low-power + enable */

/* Status register bits */
#define STATUS_DATA_READY 0x01

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_read_reg(int handle, uint8_t reg, uint8_t *val)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(reg=0x%02X) failed: %d\n",
                reg, rc);
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

static int i2c_write_reg(int handle, uint8_t reg, uint8_t val)
{
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, val, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor initialization                                               */
/* ------------------------------------------------------------------ */
static int init_sensor(int handle)
{
    uint8_t status;

    /* Read current CTRL value to preserve any user settings */
    if (i2c_read_reg(handle, REG_CTRL, &status) != 0)
        return -1;

    /* Set high-resolution mode (bit 0 = 0) and enable (bit 1 = 1) */
    status = (status & ~0x01) | 0x02;

    if (i2c_write_reg(handle, REG_CTRL, status) != 0)
        return -1;

    /* Allow time for the first measurement to be ready */
    time_sleep(0.05);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read magnetic data (X, Y, Z) and temperature                       */
/* ------------------------------------------------------------------ */
static int read_sensor_data(int handle, float *speed, float *temp)
{
    uint8_t x_l, x_h, y_l, y_h, z_l, z_h, t_l, t_h;
    int16_t x, y, z;
    int16_t raw_temp;
    uint8_t status;

    /* Check data-ready flag */
    if (i2c_read_reg(handle, REG_STATUS, &status) != 0)
        return -1;

    if ((status & STATUS_DATA_READY) == 0) {
        fprintf(stderr, "[WARN] Data not ready (status=0x%02X)\n", status);
        return -1;
    }

    /* Read X, Y, Z axes (6 bytes) */
    if (i2c_read_reg(handle, REG_MAG_X_LSB, &x_l) != 0) return -1;
    if (i2c_read_reg(handle, REG_MAG_X_MSB, &x_h) != 0) return -1;
    if (i2c_read_reg(handle, REG_MAG_Y_LSB, &y_l) != 0) return -1;
    if (i2c_read_reg(handle, REG_MAG_Y_MSB, &y_h) != 0) return -1;
    if (i2c_read_reg(handle, REG_MAG_Z_LSB, &z_l) != 0) return -1;
    if (i2c_read_reg(handle, REG_MAG_Z_MSB, &z_h) != 0) return -1;

    x = (int16_t)((x_h << 8) | x_l);
    y = (int16_t)((y_h << 8) | y_l);
    z = (int16_t)((z_h << 8) | z_l);

    /* Read temperature (2 bytes) */
    if (i2c_read_reg(handle, REG_TEMP_LSB, &t_l) != 0) return -1;
    if (i2c_read_reg(handle, REG_TEMP_MSB, &t_h) != 0) return -1;

    raw_temp = (int16_t)((t_h << 8) | t_l);

    /* Convert raw values to physical units
     * Speed: 1 LSB = 0.001 G (Gauss)
     * Temperature: 1 LSB = 0.1 °C
     */
    *speed = (float)x * 0.001f;
    *temp  = (float)raw_temp * 0.1f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Log data to CSV                                                     */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, float speed, float temp)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r failed\n");
        return -1;
    }

    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "[ERROR] strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%.3f,%.2f\n", ts, speed, temp) < 0) {
        fprintf(stderr, "[ERROR] fprintf to log failed\n");
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "[ERROR] fflush failed\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    float speed, temp;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (init_sensor(g_i2c_handle) != 0) {
        fprintf(stderr, "[FATAL] Sensor initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file (append); create with header if new */
    g_log_file = fopen(LOG_FILE, "a+");
    if (g_log_file == NULL) {
        fprintf(stderr, "[FATAL] Cannot open log file '%s'\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    if (fseek(g_log_file, 0, SEEK_END) != 0) {
        fprintf(stderr, "[WARN] fseek failed; header may be missing\n");
    } else {
        long sz = ftell(g_log_file);
        if (sz == 0) {
            if (fprintf(g_log_file, "Timestamp,Speed(G),Temperature(C)\n") < 0) {
                fprintf(stderr, "[WARN] Cannot write header\n");
            }
            fflush(g_log_file);
        }
    }

    /* Install signal handler */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGINT) failed\n");
    }

    printf("Si7202 logger started. Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (g_running) {
        if (read_sensor_data(g_i2c_handle, &speed, &temp) == 0) {
            if (log_data(g_log_file, speed, temp) != 0) {
                fprintf(stderr, "[ERROR] Logging failed; continuing\n");
            }
        } else {
            fprintf(stderr, "[ERROR] Sensor read failed; logging NaN\n");
            if (log_data(g_log_file, NAN, NAN) != 0) {
                fprintf(stderr, "[ERROR] Logging NaN failed\n");
            }
        }

        time_sleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

