#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define TMP117_ADDR 0x48
#define TMP117_TEMP_REG 0x00
#define I2C_BUS 1
#define LOG_FILE "temperature_log.txt"
#define MAX_RETRIES 3
#define SAMPLE_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_temperature(int handle, float *temperature) {
    char buf[2];
    int result = i2cReadI2CBlockData(handle, TMP117_TEMP_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature register: %s (pigpio error %d)\n",
                strerror(errno), result);
        return -1;
    }

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *temperature = (float)raw * 0.0078125f;
    return 0;
}

static int log_temperature(float temperature) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s, Temperature: %.2f C\n", timestamp, temperature) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
        if (i2c_handle >= 0) {
            break;
        }
        fprintf(stderr, "I2C open attempt %d/%d failed: %s\n",
                attempt + 1, MAX_RETRIES, strerror(errno));
        if (attempt < MAX_RETRIES - 1) {
            gpioDelay(1000000);
        }
    }

    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device after %d attempts. Exiting.\n", MAX_RETRIES);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("TMP117 temperature logger started. Press Ctrl+C to exit.\n");

    while (running) {
        float temperature;
        if (read_temperature(i2c_handle, &temperature) == 0) {
            if (log_temperature(temperature) != 0) {
                fprintf(stderr, "Logging failed, continuing...\n");
            }
        } else {
            fprintf(stderr, "Temperature read failed, attempting to re-initialize I2C...\n");
            i2cClose(i2c_handle);
            i2c_handle = -1;
            for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
                i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
                if (i2c_handle >= 0) {
                    break;
                }
                fprintf(stderr, "I2C re-open attempt %d/%d failed: %s\n",
                        attempt + 1, MAX_RETRIES, strerror(errno));
                if (attempt < MAX_RETRIES - 1) {
                    gpioDelay(1000000);
                }
            }
            if (i2c_handle < 0) {
                fprintf(stderr, "Failed to re-initialize I2C after %d attempts. Exiting.\n", MAX_RETRIES);
                break;
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

