/*
 * Raspberry Pi Zero W – Honeywell HAFUHH0025PA3 airflow sensor reader
 *
 * Wiring:
 *   VCC  -> 3.3 V (Pin 1)
 *   GND  -> GND  (Pin 9)
 *   SDA  -> GPIO2 / I2C bus 1 SDA (Pin 3)
 *   SCL  -> GPIO3 / I2C bus 1 SCL (Pin 5)
 *
 * The HAF series supports a single 4-byte API read (no register pointer
 * write) that returns a 14-bit flow value and a 12-bit temperature value.
 * The first two reads after power-up may return stale data; we discard them.
 *
 * Build:  gcc -O2 -Wall -Wextra -o flow_monitor flow_monitor.c -lpigpio -lrt
 * Run:    sudo ./flow_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x28
#define LOG_FILE       "flow_log.txt"
#define SAMPLE_PERIOD  1.0          /* seconds between samples */
#define WARMUP_SAMPLES 2            /* discard first two reads after power-up */

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int init_i2c(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen failed (bus=%d addr=0x%02X): %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        return -1;
    }
    return 0;
}

/*
 * Read a 4-byte API frame from the HAF sensor.
 * Returns 0 on success, -1 on I2C error.
 */
static int read_sensor_data(uint16_t *flow_raw, uint16_t *temp_raw)
{
    char buf[4];

    if (i2cReadDevice(g_i2c_handle, buf, 4) != 4) {
        fprintf(stderr, "[ERROR] i2cReadDevice failed\n");
        return -1;
    }

    /*
     * 4-byte frame (Honeywell HAF API):
     *   Byte 0: 14-bit flow MSB (bits 7..0) + 2-bit status (bits 6..5)
     *   Byte 1: 14-bit flow LSB (bits 7..2) + 6-bit temperature MSB (bits 1..0)
     *   Byte 2: 8-bit temperature LSB
     *   Byte 3: 12-bit temperature LSB (bits 7..0) + 4-bit status (bits 3..0)
     *
     * Flow:   14 bits  -> * 0.001 SLPM
     * Temp:   12 bits  -> * 0.1 °C
     */
    uint16_t flow_msb = (uint16_t)(buf[0] & 0xFF);
    uint16_t flow_lsb = (uint16_t)(buf[1] & 0xFF);
    uint16_t temp_msb = (uint16_t)(buf[1] & 0xFF);
    uint16_t temp_lsb = (uint16_t)(buf[2] & 0xFF);

    *flow_raw = ((uint16_t)(flow_msb & 0x3F) << 8) | (uint16_t)(flow_lsb >> 2);
    *temp_raw = ((uint16_t)(temp_msb << 8) | (uint16_t)(temp_lsb & 0xFF)) >> 4;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_data(float flow_slpm, float temp_c)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];

    if (t == NULL) {
        strncpy(ts, "UNKNOWN", sizeof(ts) - 1);
        ts[sizeof(ts) - 1] = '\0';
    } else {
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    }

    fprintf(g_log_file, "%s, Flow: %.3f SLPM, Temperature: %.2f C\n",
            ts, flow_slpm, temp_c);
    fflush(g_log_file);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "[ERROR] gpioInitialise failed\n");
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("fopen(" LOG_FILE ")");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /*
     * First two reads after power-up may return stale data.
     * Discard them and treat the third read as the first valid sample.
     */
    for (int i = 0; i < WARMUP_SAMPLES && g_running; i++) {
        (void)read_sensor_data(NULL, NULL);
        time_sleep(0.1);
    }

    uint16_t flow_raw = 0, temp_raw = 0;

    while (g_running) {
        if (read_sensor_data(&flow_raw, &temp_raw) == 0) {
            float flow_slpm = (float)flow_raw * 0.001f;
            float temp_c    = (float)temp_raw * 0.1f;
            log_data(flow_slpm, temp_c);
        } else {
            fprintf(stderr, "[WARN] Read failed; attempting I2C re-init.\n");
            if (init_i2c() != 0) {
                fprintf(stderr, "[ERROR] Re-init failed; exiting.\n");
                break;
            }
        }

        time_sleep(SAMPLE_PERIOD);
    }

    cleanup();
    return EXIT_SUCCESS;
}

