/*
 * DHT11 single-wire temperature/humidity reader for Raspberry Pi Zero W.
 * Uses bit-banged GPIO via pigpio API calls (no wiringPi).
 *
 * Wiring:
 *   DHT11 VCC  -> 3V3 (pin 1)
 *   DHT11 GND  -> GND (pin 6)
 *   DHT11 DATA -> GPIO4 (BCM 4, physical pin 7)
 *
 * Build:  gcc -O2 -Wall -o dht11 dht11.c -lpigpio -lrt
 * Run:    sudo ./dht11
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define DHT11_GPIO        4
#define DHT11_START_LOW_US  18000   /* > 18 ms  */
#define DHT11_START_HIGH_US 40      /* 20–40 µs */
#define DHT11_RESP_LOW_US   80      /* 80 µs    */
#define DHT11_RESP_HIGH_US  80      /* 80 µs    */
#define DHT11_BIT_LOW_US    50      /* 50 µs    */
#define DHT11_BIT_HIGH_0_US 26      /* 26–28 µs */
#define DHT11_BIT_HIGH_1_US 70      /* 70 µs    */
#define DHT11_TIMEOUT_US    100     /* per-phase timeout */
#define DHT11_MAX_RETRIES   5
#define READ_INTERVAL_S     2
#define LOG_FILE            "dht11_readings.txt"
#define ERROR_LOG_FILE      "dht11_errors.log"

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                    */
/* ------------------------------------------------------------------ */
static void iso_timestamp(char *buf, size_t len)
{
    time_t t = time(NULL);
    struct tm tmv;
    if (localtime_r(&t, &tmv) != NULL)
        strftime(buf, len, "%Y-%m-%dT%H:%M:%S%z", &tmv);
    else
        snprintf(buf, len, "1970-01-01T00:00:00+0000");
}

/* ------------------------------------------------------------------ */
/* Error logger                                                        */
/* ------------------------------------------------------------------ */
static void log_error(const char *msg, int code)
{
    char ts[32];
    iso_timestamp(ts, sizeof(ts));

    FILE *fp = fopen(ERROR_LOG_FILE, "a");
    if (fp) {
        fprintf(fp, "%s - ERROR: %s (code %d)\n", ts, msg, code);
        fclose(fp);
    } else {
        fprintf(stderr, "%s - ERROR: %s (code %d)\n", ts, msg, code);
    }
}

/* ------------------------------------------------------------------ */
/* Success logger                                                      */
/* ------------------------------------------------------------------ */
static void log_reading(int hum_int, int temp_int)
{
    char ts[32];
    iso_timestamp(ts, sizeof(ts));

    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        log_error("Failed to open log file", 1);
        return;
    }
    fprintf(fp, "%s - Humidity: %d.%d%%, Temperature: %d.%d°C\n",
            ts, hum_int, 0, temp_int, 0);
    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Wait for a pin level with timeout                                   */
/* ------------------------------------------------------------------ */
static int wait_level(int gpio, int level, uint32_t timeout_us)
{
    uint32_t start = gpioTick();
    while (gpioRead(gpio) != level) {
        if ((gpioTick() - start) > timeout_us)
            return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read 40 bits from DHT11                                             */
/* ------------------------------------------------------------------ */
static int read_dht11(int gpio, uint8_t data[5])
{
    memset(data, 0, 5);

    /* --- Start signal: pull low >= 18 ms, then release -------------- */
    if (gpioSetMode(gpio, PI_OUTPUT) < 0) return -2;
    if (gpioWrite(gpio, 0) < 0) return -3;
    gpioDelay(DHT11_START_LOW_US);

    /* Switch to input (pull-up) and release the line */
    if (gpioSetMode(gpio, PI_INPUT) < 0) return -4;
    if (gpioSetPullUpDown(gpio, PI_PUD_UP) < 0) return -5;
    gpioDelay(DHT11_START_HIGH_US);

    /* --- Sensor response: 80 µs low + 80 µs high ------------------- */
    if (wait_level(gpio, 0, DHT11_TIMEOUT_US) < 0) return -6; /* resp low */
    if (wait_level(gpio, 1, DHT11_TIMEOUT_US) < 0) return -7; /* resp high */
    if (wait_level(gpio, 0, DHT11_TIMEOUT_US) < 0) return -8; /* end resp */

    /* --- Read 40 data bits ------------------------------------------ */
    for (int i = 0; i < 40; i++) {
        /* Low phase (~50 µs) */
        if (wait_level(gpio, 1, DHT11_TIMEOUT_US) < 0) return -9;

        /* High phase: ~26–28 µs = '0', ~70 µs = '1' */
        uint32_t t0 = gpioTick();
        if (wait_level(gpio, 0, DHT11_TIMEOUT_US) < 0) return -10;

        uint32_t high_us = gpioTick() - t0;
        if (high_us > DHT11_BIT_HIGH_1_US)
            data[i / 8] |= (1 << (7 - (i % 8)));
    }

    /* --- Checksum --------------------------------------------------- */
    uint8_t checksum = (uint8_t)(data[0] + data[1] + data[2] + data[3]);
    if (checksum != data[4]) return -11;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Install signal handlers ----------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio ----------------------------------------- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* --- Main loop -------------------------------------------------- */
    while (g_running) {
        uint8_t data[5];
        int rc = read_dht11(DHT11_GPIO, data);

        if (rc == 0) {
            int hum_int   = data[0];
            int temp_int  = data[2];
            log_reading(hum_int, temp_int);
        } else {
            log_error("DHT11 read failed", rc);
        }

        /* Sleep READ_INTERVAL_S, but wake early on signal */
        for (int s = 0; s < READ_INTERVAL_S && g_running; s++)
            sleep(1);
    }

    /* --- Cleanup ---------------------------------------------------- */
    gpioSetPullUpDown(DHT11_GPIO, PI_PUD_OFF);
    gpioTerminate();
    return EXIT_SUCCESS;
}

