            fprintf(stderr, "Error: Temperature CRC mismatch (attempt %d/%d)\n", retries + 1, MAX_RETRIES);
            retries++;
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        if (crc8(data + 3, 2) != data[5]) {
            fprintf(stderr, "Error: Humidity CRC mismatch (attempt %d/%d)\n", retries + 1, MAX_RETRIES);
            retries++;
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        uint16_t temp_raw = (data[0] << 8) | data[1];
        uint16_t hum_raw  = (data[3] << 8) | data[4];

        *temperature = -45.0f + (175.0f * (float)temp_raw / 65535.0f);
        *humidity    = 100.0f * (float)hum_raw / 65535.0f;

        if (*humidity > 100.0f) *humidity = 100.0f;
        if (*humidity < 0.0f)   *humidity = 0.0f;

        return 0;
    }

    fprintf(stderr, "Error: SHT31-D read failed after %d retries\n", MAX_RETRIES);
    return -1;
}

static void log_data(float temperature, float humidity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fflush(log_file);
}

static void log_error(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,ERROR,%s\n", timestamp, message);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    float temperature, humidity;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, SHT31_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (handle=%d)\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s'\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (!terminate) {
        if (read_sht31d(&temperature, &humidity) == 0) {
            log_data(temperature, humidity);
        } else {
            log_error("SHT31-D read failed");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return 0;
}

