#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SENSOR1_ADDR 0x48
#define SENSOR2_ADDR 0x49

#define REG_RED 0x00
#define REG_GREEN 0x01
#define REG_BLUE 0x02
#define REG_CCT 0x03

#define LOG_FILE "cct_log.csv"
#define SAMPLE_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_register(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

static int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

static int read_sensor_data(int handle, uint8_t *red, uint8_t *green, uint8_t *blue, uint8_t *cct) {
    if (read_register(handle, REG_RED, red) < 0) return -1;
    if (read_register(handle, REG_GREEN, green) < 0) return -1;
    if (read_register(handle, REG_BLUE, blue) < 0) return -1;
    if (read_register(handle, REG_CCT, cct) < 0) return -1;
    return 0;
}

static float calculate_cct(uint8_t red, uint8_t green, uint8_t blue) {
    float r = (float)red;
    float g = (float)green;
    float b = (float)blue;
    float n = (r + g + b) / 3.0f;
    if (n == 0.0f) return 0.0f;
    float r_norm = r / n;
    float g_norm = g / n;
    float b_norm = b / n;
    float x = (r_norm * 0.437f + g_norm * 0.368f + b_norm * 0.185f) / (r_norm * 0.0725f + g_norm * 0.9154f + b_norm * 0.0180f);
    float y = 1.0f;
    float z = (1.0f - x - y) / y;
    float u = x / (x + y + z);
    float v = y / (x + y + z);
    float u_ref = 0.3127f;
    float v_ref = 0.3290f;
    float cct = 449.0f * (u - u_ref) / (v - v_ref) + 3525.0f;
    return cct;
}

static int log_cct(float cct) {
    FILE *fp = fopen(LOG_FILE, "a+");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }
    fseek(fp, 0, SEEK_END);
    long fsize = ftell(fp);
    if (fsize == 0) {
        fprintf(fp, "Timestamp,Average_CCT\n");
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f\n", timestamp, cct);
    fclose(fp);
    return 0;
}

