    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    int handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (handle1 < 0) {
        fprintf(stderr, "Error opening I2C device 1: %d\n", handle1);
        gpioTerminate();
        return 1;
    }

    int handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (handle2 < 0) {
        fprintf(stderr, "Error opening I2C device 2: %d\n", handle2);
        i2cClose(handle1);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    uint8_t red1, green1, blue1, cct1;
    uint8_t red2, green2, blue2, cct2;
    float cct_sum = 0.0f;
    int valid_count = 0;

    while (running) {
        if (read_sensor_data(handle1, &red1, &green1, &blue1, &cct1) < 0) {
            fprintf(stderr, "Error reading sensor 1 data\n");
        } else {
            cct_sum += calculate_cct(red1, green1, blue1);
            valid_count++;
        }

        if (read_sensor_data(handle2, &red2, &green2, &blue2, &cct2) < 0) {
            fprintf(stderr, "Error reading sensor 2 data\n");
        } else {
            cct_sum += calculate_cct(red2, green2, blue2);
            valid_count++;
        }

        if (valid_count > 0) {
            float avg_cct = cct_sum / valid_count;
            if (log_cct(avg_cct) < 0) {
                fprintf(stderr, "Error logging CCT\n");
            }
        } else {
            fprintf(stderr, "No valid sensor data this cycle\n");
        }

        cct_sum = 0.0f;
        valid_count = 0;
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    i2cClose(handle1);
    i2cClose(handle2);
    gpioTerminate();
    return 0;
}

