/*
 * MLX90824 Absolute Pressure Sensor Logger for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   MLX90824 SDA -> GPIO2 (I2C1 SDA, pin 3)
 *   MLX90824 SCL -> GPIO3 (I2C1 SCL, pin 5)
 *   MLX90824 VDD -> 3.3 V (pin 1)
 *   MLX90824 GND -> GND  (pin 6)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o mlx90824_logger mlx90824_logger.c \
 *       -lm -lpigpio -lrt
 *   (pigpio requires root or gpio group membership; run with sudo if needed.)
 *
 * Run:
 *   sudo ./mlx90824_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Configuration ---- */
#define I2C_BUS        1          /* /dev/i2c-1 on Raspberry Pi 4 */
#define I2C_ADDR       0x48       /* MLX90824 default 7-bit I2C address */
#define LOG_FILE       "pressure_log.txt"
#define SAMPLE_PERIOD  2          /* seconds between readings */
#define MAX_RETRIES    3          /* retries per read cycle */

/* ---- MLX90824 register map (16-bit, big-endian on the bus) ---- */
#define REG_PRESSURE   0x00       /* Absolute pressure, 16-bit signed */
#define REG_TEMPERATURE 0x02     /* Temperature, 16-bit signed */
#define REG_STATUS     0x04       /* Status / error register */

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag only; defer heavy work to main loop       */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* ISO-8601 timestamp helper                                          */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    time_t now = time(NULL);
    struct tm tmv;
    if (localtime_r(&now, &tmv) != NULL) {
        strftime(buf, len, "%Y-%m-%dT%H:%M:%S%z", &tmv);
    } else {
        snprintf(buf, len, "1970-01-01T00:00:00+0000");
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup — safe to call multiple times                               */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit big-endian register from the MLX90824                */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int read_register16(int handle, uint8_t reg, int16_t *out)
{
    char buf[2];
    int  rc;

    rc = i2cWriteByte(handle, reg);
    if (rc < 0) {
        return -1;
    }

    /* Small delay so the sensor has time to clock out the data */
    gpioDelay(2000);  /* 2 ms */

    rc = i2cReadDevice(handle, buf, 2);
    if (rc != 2) {
        return -1;
    }

    *out = (int16_t)(((uint16_t)(uint8_t)buf[0] << 8) |
                     (uint16_t)(uint8_t)buf[1]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read pressure and temperature with retry                           */
/* Returns 0 on success, -1 on persistent failure.                     */
/* ------------------------------------------------------------------ */
static int read_sensor(int handle, float *pressure, float *temperature)
{
    int16_t raw_p = 0, raw_t = 0;
    int     ok = 0;

    for (int attempt = 0; attempt < MAX_RETRIES; ++attempt) {
        if (read_register16(handle, REG_PRESSURE, &raw_p) == 0 &&
            read_register16(handle, REG_TEMPERATURE, &raw_t) == 0) {
            ok = 1;
            break;
        }
        gpioDelay(100000);  /* 100 ms backoff */
    }

    if (!ok) {
        return -1;
    }

    /* Convert raw 16-bit signed values to physical units.
     * The MLX90824 transmits pressure in bar and temperature in °C.
     * Resolution is typically 0.01 bar and 0.1 °C per LSB. */
    *pressure    = (float)raw_p / 100.0f;
    *temperature = (float)raw_t / 10.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Append a measurement or error line to the log file                  */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, const char *timestamp,
                     float pressure, float temperature)
{
    fprintf(fp, "%s, Pressure: %.2f bar, Temperature: %.1f C\n",
            timestamp, pressure, temperature);
    fflush(fp);
}

static void log_error(FILE *fp, const char *timestamp, const char *msg)
{
    fprintf(fp, "%s, ERROR: %s\n", timestamp, msg);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    char timestamp[32];

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus ---- */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (code %d). "
                        "Sensor may be absent or bus unavailable.\n",
                        g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s'.\n", LOG_FILE);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MLX90824 logger started. Logging to '%s' every %d s.\n",
           LOG_FILE, SAMPLE_PERIOD);
    printf("Press Ctrl+C to stop.\n");

    /* ---- Main sampling loop ---- */
    while (g_running) {
        get_timestamp(timestamp, sizeof(timestamp));

        float pressure, temperature;

        if (read_sensor(g_i2c_handle, &pressure, &temperature) == 0) {
            log_data(g_log_file, timestamp, pressure, temperature);
            printf("%s  P=%.2f bar  T=%.1f C\n",
                   timestamp, pressure, temperature);
        } else {
            log_error(g_log_file, timestamp,
                      "I2C read failure — sensor may be disconnected");
            fprintf(stderr, "%s  I2C read failure\n", timestamp);
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD * 10 && g_running; ++i) {
            gpioDelay(100000);  /* 100 ms */
        }
    }

    /* ---- Graceful cleanup ---- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

