        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit big-endian register from the MLX90824                */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int read_register16(int handle, uint8_t reg, int16_t *out)
{
    char buf[2];
    int  rc;

    rc = i2cWriteByte(handle, reg);
    if (rc < 0) {
        return -1;
    }

    /* Small delay so the sensor has time to clock out the data */
    gpioDelay(2000);  /* 2 ms */

    rc = i2cReadDevice(handle, buf, 2);
    if (rc != 2) {
        return -1;
    }

    *out = (int16_t)(((uint16_t)(uint8_t)buf[0] << 8) |
                     (uint16_t)(uint8_t)buf[1]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read pressure and temperature with retry                           */
/* Returns 0 on success, -1 on persistent failure.                     */
/* ------------------------------------------------------------------ */
static int read_sensor(int handle, float *pressure, float *temperature)
{
    int16_t raw_p = 0, raw_t = 0;
    int     ok = 0;

    for (int attempt = 0; attempt < MAX_RETRIES; ++attempt) {
        if (read_register16(handle, REG_PRESSURE, &raw_p) == 0 &&
            read_register16(handle, REG_TEMPERATURE, &raw_t) == 0) {
            ok = 1;
            break;
        }
        gpioDelay(100000);  /* 100 ms backoff */
    }

    if (!ok) {
        return -1;
    }

    /* Convert raw 16-bit signed values to physical units.
     * The MLX90824 transmits pressure in bar and temperature in °C.
     * Resolution is typically 0.01 bar and 0.1 °C per LSB. */
    *pressure    = (float)raw_p / 100.0f;
    *temperature = (float)raw_t / 10.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Append a measurement or error line to the log file                  */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, const char *timestamp,
                     float pressure, float temperature)
{
    fprintf(fp, "%s, Pressure: %.2f bar, Temperature: %.1f C\n",
            timestamp, pressure, temperature);
    fflush(fp);
}

static void log_error(FILE *fp, const char *timestamp, const char *msg)
{
    fprintf(fp, "%s, ERROR: %s\n", timestamp, msg);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    char timestamp[32];

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus ---- */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (code %d). "
                        "Sensor may be absent or bus unavailable.\n",
                        g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s'.\n", LOG_FILE);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MLX90824 logger started. Logging to '%s' every %d s.\n",
           LOG_FILE, SAMPLE_PERIOD);
    printf("Press Ctrl+C to stop.\n");

    /* ---- Main sampling loop ---- */
    while (g_running) {
        get_timestamp(timestamp, sizeof(timestamp));

        float pressure, temperature;

        if (read_sensor(g_i2c_handle, &pressure, &temperature) == 0) {
            log_data(g_log_file, timestamp, pressure, temperature);
            printf("%s  P=%.2f bar  T=%.1f C\n",
                   timestamp, pressure, temperature);
        } else {
            log_error(g_log_file, timestamp,
                      "I2C read failure — sensor may be disconnected");
            fprintf(stderr, "%s  I2C read failure\n", timestamp);
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD * 10 && g_running; ++i) {
            gpioDelay(100000);  /* 100 ms */
        }
    }

    /* ---- Graceful cleanup ---- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

