#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <string.h>

#define I2C_BUS 1
#define LM75B_ADDR 0x48
#define FAN_GPIO 18
#define TEMP_THRESHOLD_HIGH 28.0
#define TEMP_THRESHOLD_LOW 26.0
#define BUFFER_SIZE 60
#define POLL_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_temperature(int handle, float *temperature) {
    char data[2];
    int result = i2cReadDevice(handle, data, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature from I2C: %d\n", result);
        return -1;
    }
    int16_t raw = (int16_t)((data[0] << 8) | data[1]);
    *temperature = (float)raw / 256.0;
    return 0;
}

static void add_to_buffer(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) cb->count++;
}

static float calculate_average(const CircularBuffer *cb) {
    if (cb->count == 0) return 0.0;
    float sum = 0.0;
    for (int i = 0; i < cb->count; i++) sum += cb->buffer[i];
    return sum / cb->count;
}

static int control_fan(float average_temp) {
    static int fan_on = 0;
    if (average_temp > TEMP_THRESHOLD_HIGH && !fan_on) {
        if (gpioWrite(FAN_GPIO, 1) != 0) {
            fprintf(stderr, "Error turning fan ON\n");
            return -1;
        }
        fan_on = 1;
        printf("Fan ON (avg: %.2f°C)\n", average_temp);
    } else if (average_temp < TEMP_THRESHOLD_LOW && fan_on) {
        if (gpioWrite(FAN_GPIO, 0) != 0) {
            fprintf(stderr, "Error turning fan OFF\n");
            return -1;
        }
        fan_on = 0;
        printf("Fan OFF (avg: %.2f°C)\n", average_temp);
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, LM75B_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO mode\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioWrite(FAN_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    CircularBuffer temp_buffer = {0};
    float temperature;
    int consecutive_errors = 0;

    while (running) {
        if (read_temperature(i2c_handle, &temperature) == 0) {
            consecutive_errors = 0;
            add_to_buffer(&temp_buffer, temperature);
            float avg = calculate_average(&temp_buffer);
            if (control_fan(avg) != 0) {
                fprintf(stderr, "Fan control error\n");
            }
            printf("Temp: %.2f°C, Avg: %.2f°C\n", temperature, avg);
        } else {
            consecutive_errors++;
            fprintf(stderr, "Temperature read error (consecutive: %d)\n", consecutive_errors);
            if (consecutive_errors >= 10) {
                fprintf(stderr, "Too many consecutive errors, aborting\n");
                break;
            }
        }
        usleep(POLL_INTERVAL_US);
    }

    gpioWrite(FAN_GPIO, 0);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    printf("Shutdown complete.\n");
    return 0;
}

