/*
 * SDP810-500Pa differential pressure monitor for Raspberry Pi Zero W.
 *
 * Wiring:
 *   SDP810 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   SDP810 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   SDP810 VDD  -> 3.3 V
 *   SDP810 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o airflow airflow.c -lpigpio -lrt
 * Run:    sudo ./airflow
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x21
#define LOG_FILE       "airflow.log"
#define SAMPLE_PERIOD  1.0          /* seconds between samples */
#define MEASURE_DELAY  0.045        /* 45 ms measurement wait   */
#define PRESSURE_THRESH 5.0         /* Pa — warn above this      */

static volatile sig_atomic_t g_running = 1;
static int  g_i2c  = -1;
static FILE *g_log = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void on_signal(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Sensirion CRC-8 (polynomial 0x31, init 0xFF, no final XOR)          */
/* ------------------------------------------------------------------ */
static uint8_t sensirion_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Cleanup — safe to call multiple times                               */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log) {
        fflush(g_log);
        fclose(g_log);
        g_log = NULL;
    }
    if (g_i2c >= 0) {
        i2cClose(g_i2c);
        g_i2c = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Initialise pigpio, I2C, and log file                                */
/* ------------------------------------------------------------------ */
static int init(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    g_i2c = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c < 0) {
        fprintf(stderr, "Error: i2cOpen failed (code %d). "
                        "Sensor may be absent or bus unavailable.\n",
                g_i2c);
        gpioTerminate();
        return -1;
    }

    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        perror("Error: cannot open " LOG_FILE);
        i2cClose(g_i2c);
        g_i2c = -1;
        gpioTerminate();
        return -1;
    }

    /* Write a CSV header only if the file is empty */
    if (ftell(g_log) == 0)
        fprintf(g_log, "timestamp,differential_pressure_Pa,temperature_C\n");

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one 9-byte measurement frame from the SDP810                   */
/* ------------------------------------------------------------------ */
static int read_measurement(float *pressure, float *temperature)
{
    uint8_t cmd[2] = { 0x36, 0x2F };   /* continuous measurement, no clock stretching */
    uint8_t buf[9];

    /* Issue measurement command */
    if (i2cWriteDevice(g_i2c, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error: I2C write failed (sensor may be absent).\n");
        return -1;
    }

    time_sleep(MEASURE_DELAY);

    /* Read 9 bytes: pressure_msb, pressure_lsb, pressure_crc,
                      temp_msb,    temp_lsb,    temp_crc,
                      scale_msb,   scale_lsb,   scale_crc */
    int n = i2cReadDevice(g_i2c, (char *)buf, 9);
    if (n != 9) {
        fprintf(stderr, "Error: I2C read returned %d bytes (expected 9).\n", n);
        return -1;
    }

    /* CRC validation */
    if (sensirion_crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Warning: pressure CRC mismatch.\n");
        return -1;
    }
    if (sensirion_crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Warning: temperature CRC mismatch.\n");
        return -1;
    }
    /* buf[6..8] are the scale factor; their CRC is not checked here. */

    int16_t raw_pressure = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_temp     = (int16_t)((buf[3] << 8) | buf[4]);

    /* SDP810 conversion: 1 LSB = 0.007 Pa, 1 LSB = 0.01 °C */
    *pressure    = (float)raw_pressure * 0.007f;
    *temperature = (float)raw_temp     * 0.01f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = on_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (init() != 0)
        return EXIT_FAILURE;

    float pressure, temperature;

    while (g_running) {
        if (read_measurement(&pressure, &temperature) == 0) {
            time_t now = time(NULL);
            struct tm tmv;
            char ts[32];
            localtime_r(&now, &tmv);
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tmv);

            fprintf(g_log, "%s,%.2f,%.2f\n", ts, pressure, temperature);
            fflush(g_log);

            printf("%s  Pressure: %.2f Pa  Temperature: %.2f C\n",
                   ts, pressure, temperature);

            if (pressure > PRESSURE_THRESH)
                fprintf(stderr,
                        "Warning: pressure %.2f Pa exceeds threshold %.1f Pa\n",
                        pressure, PRESSURE_THRESH);
        } else {
            fprintf(stderr, "Warning: measurement failed; will retry next cycle.\n");
        }

        time_sleep(SAMPLE_PERIOD);
    }

    cleanup();
    return EXIT_SUCCESS;
}

