#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS        "/dev/i2c-1"
#define STTS2004_ADDR  0x48
#define TEMP_REG       0x00
#define LED_GPIO       17
#define TEMP_HIGH      28.0f
#define TEMP_LOW       27.0f
#define POLL_DELAY_US  1000000

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read (reg 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_temperature(int fd, float *temp_c)
{
    uint8_t raw;
    if (i2c_read_reg8(fd, TEMP_REG, &raw) != 0)
        return -1;

    int16_t signed_val = (int16_t)raw;
    *temp_c = (float)signed_val / 100.0f;
    return 0;
}

static int control_led(int state)
{
    if (gpioWrite(LED_GPIO, state) != 0) {
        fprintf(stderr, "gpioWrite(%d) failed: %s\n",
                state, strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, STTS2004_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                STTS2004_ADDR, strerror(errno));
        close(fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_OUTPUT) failed: %s\n",
                LED_GPIO, strerror(errno));
        close(fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (control_led(0) != 0) {
        close(fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    bool led_on = false;

    while (g_running) {
        float temp;
        if (read_temperature(fd, &temp) != 0) {
            fprintf(stderr, "Temperature read failed; exiting.\n");
            break;
        }

        printf("Temperature: %.2f C\n", temp);
        fflush(stdout);

        if (temp > TEMP_HIGH && !led_on) {
            if (control_led(1) == 0) {
                led_on = true;
            }
        } else if (temp < TEMP_LOW && led_on) {
            if (control_led(0) == 0) {
                led_on = false;
            }
        }

        usleep(POLL_DELAY_US);
    }

    control_led(0);
    close(fd);
    gpioTerminate();
    return EXIT_SUCCESS;
}

