/*
 * Si7021 temperature & humidity logger for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   Si7021 SDA  -> GPIO2 (BCM 2, I2C bus 1 SDA)
 *   Si7021 SCL  -> GPIO3 (BCM 3, I2C bus 1 SCL)
 *   Si7021 VDD  -> 3.3 V
 *   Si7021 GND  -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o si7021_logger si7021_logger.c -lpigpio -lrt
 *   (pigpio must be installed and the daemon must be running.)
 *
 * Run:
 *   ./si7021_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS          1
#define SI7021_ADDR      0x48
#define LOG_FILE         "environment.log"
#define SAMPLE_INTERVAL  60          /* seconds between readings */
#define MAX_RETRIES      3
#define MEASURE_DELAY_US 20000       /* 20 ms no-hold conversion time */

/* Si7021 command codes (MSB first) */
#define CMD_MEASURE_RH_NO_HOLD   0xE5
#define CMD_MEASURE_TEMP_NO_HOLD 0xE0
#define CMD_READ_TEMP_PREV_RH    0xE0  /* same opcode; bit 7 of first byte selects RH or T */
#define CMD_READ_ID_1            0xFA0F /* Electronic ID, part 1 */
#define CMD_READ_ID_2            0xFCC9 /* Electronic ID, part 2 */

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */
static void timestamp_str(char *buf, size_t len)
{
    time_t t = time(NULL);
    struct tm tmv;
    if (localtime_r(&t, &tmv) != NULL)
        strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tmv);
    else
        snprintf(buf, len, "1970-01-01 00:00:00");
}

static void log_line(const char *msg)
{
    char ts[32];
    timestamp_str(ts, sizeof ts);
    if (g_log_file) {
        fprintf(g_log_file, "%s,%s\n", ts, msg);
        fflush(g_log_file);
    }
    fprintf(stderr, "%s,%s\n", ts, msg);
}

/* ------------------------------------------------------------------ */
/* I2C helpers with retry                                              */
/* ------------------------------------------------------------------ */
static int i2c_write_cmd(int handle, uint8_t msb, uint8_t lsb)
{
    char buf[2] = { (char)msb, (char)lsb };
    for (int attempt = 0; attempt < MAX_RETRIES; ++attempt) {
        int rc = i2cWriteDevice(handle, buf, 2);
        if (rc == 0) return 0;
        fprintf(stderr, "I2C write attempt %d failed (rc=%d)\n", attempt + 1, rc);
        gpioDelay(100000); /* 100 ms back-off */
    }
    return -1;
}

static int i2c_read_bytes(int handle, uint8_t *buf, int len)
{
    for (int attempt = 0; attempt < MAX_RETRIES; ++attempt) {
        int rc = i2cReadDevice(handle, (char *)buf, len);
        if (rc == len) return 0;
        fprintf(stderr, "I2C read attempt %d failed (rc=%d)\n", attempt + 1, rc);
        gpioDelay(100000);
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* Sensor presence check via Electronic ID                            */
/* ------------------------------------------------------------------ */
static int si7021_present(int handle)
{
    /* Read ID part 1: write 0xFA 0x0F, then read 8 bytes */
    if (i2c_write_cmd(handle, 0xFA, 0x0F) != 0) return 0;
    gpioDelay(10000); /* 10 ms */
    uint8_t id1[8];
    if (i2c_read_bytes(handle, id1, 8) != 0) return 0;

    /* Read ID part 2: write 0xFC 0xC9, then read 8 bytes */
    if (i2c_write_cmd(handle, 0xFC, 0xC9) != 0) return 0;
    gpioDelay(10000);
    uint8_t id2[8];
    if (i2c_read_bytes(handle, id2, 8) != 0) return 0;

    /* The Si7021 returns 0x0D 0xE3 0x01 0x00 in the lower 4 bytes of each
     * part when the device is present and responding. */
    if (id1[0] != 0x0D || id1[1] != 0xE3 || id1[2] != 0x01 || id1[3] != 0x00)
        return 0;
    if (id2[0] != 0x0D || id2[1] != 0xE3 || id2[2] != 0x01 || id2[3] != 0x00)
        return 0;

    return 1;
}

/* ------------------------------------------------------------------ */
/* Read temperature (from previous RH measurement)                     */
/* ------------------------------------------------------------------ */
static int read_temperature(int handle, float *temp_c)
{
    /* Issue the "Read Temperature from Previous RH Measurement" command
     * (0xE0) with MSB=0x00 to select the temperature register. */
    if (i2c_write_cmd(handle, 0x00, CMD_READ_TEMP_PREV_RH) != 0)
        return -1;

    gpioDelay(MEASURE_DELAY_US);

    uint8_t buf[2];
    if (i2c_read_bytes(handle, buf, 2) != 0)
        return -1;

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *temp_c = (175.72f * raw / 65536.0f) - 46.85f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read humidity (no-hold conversion)                                  */
/* ------------------------------------------------------------------ */
static int read_humidity(int handle, float *rh_pct)
{
    if (i2c_write_cmd(handle, CMD_MEASURE_RH_NO_HOLD, 0x00) != 0)
        return -1;

    gpioDelay(MEASURE_DELAY_US);

    uint8_t buf[2];
    if (i2c_read_bytes(handle, buf, 2) != 0)
        return -1;

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *rh_pct = (125.0f * raw / 65536.0f) - 6.0f;
    if (*rh_pct < 0.0f)   *rh_pct = 0.0f;
