#define HDC1080_ADDR 0x40
#define HDC1080_TEMP 0x00
#define HDC1080_HUMID 0x01
#define HDC1080_CONFIG 0x02
#define HDC1080_RESET 0x06

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int hdc1080_reset(void) {
    if (i2cWriteByteData(i2c_handle, HDC1080_RESET, 0x80) < 0) {
        fprintf(stderr, "Error: Failed to reset HDC1080.\n");
        return -1;
    }
    gpioDelay(15000);
    return 0;
}

static int hdc1080_init(void) {
    if (hdc1080_reset() < 0) {
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, HDC1080_CONFIG, 0x10) < 0) {
        fprintf(stderr, "Error: Failed to configure HDC1080.\n");
        return -1;
    }
    return 0;
}

static int hdc1080_read_temperature(float *temperature) {
    if (i2cWriteByte(i2c_handle, HDC1080_TEMP) < 0) {
        fprintf(stderr, "Error: Failed to trigger temperature measurement.\n");
        return -1;
    }
    gpioDelay(20000);
    char buf[2];
    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read temperature data.\n");
        return -1;
    }
    uint16_t raw_temp = ((uint16_t)(buf[0] & 0xFF) << 8) | (uint8_t)buf[1];
    *temperature = ((float)raw_temp / 65536.0f) * 165.0f - 40.0f;
    return 0;
}

static int hdc1080_read_humidity(float *humidity) {
    if (i2cWriteByte(i2c_handle, HDC1080_HUMID) < 0) {
        fprintf(stderr, "Error: Failed to trigger humidity measurement.\n");
        return -1;
    }
    gpioDelay(20000);
    char buf[2];
    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read humidity data.\n");
        return -1;
    }
    uint16_t raw_hum = ((uint16_t)(buf[0] & 0xFF) << 8) | (uint8_t)buf[1];
    *humidity = ((float)raw_hum / 65536.0f) * 100.0f;
    return 0;
}

static void log_data(float temperature, float humidity) {
    FILE *fp = fopen("enviro_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to open log file.\n");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }
    i2c_handle = i2cOpen(1, HDC1080_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus.\n");
        gpioTerminate();
        return 1;
    }
    if (hdc1080_init() < 0) {
        fprintf(stderr, "Error: HDC1080 initialisation failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);
    while (!terminate) {
        float temperature, humidity;
        if (hdc1080_read_temperature(&temperature) == 0 &&
            hdc1080_read_humidity(&humidity) == 0) {
            log_data(temperature, humidity);
        } else {
            fprintf(stderr, "Warning: Sensor read failed, skipping log entry.\n");
        }
        gpioDelay(5000000);
    }
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

