#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_DEVICE "/dev/i2c-1"
#define STS40_ADDR 0x44
#define LOG_FILE "temperature_log.txt"
#define SAMPLE_INTERVAL_SEC 5
#define CONVERSION_DELAY_MS 10

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int read_temperature(int fd, float *temperature) {
    uint8_t cmd = 0x36;
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "Error: Failed to write trigger command to I2C device.\n");
        return -1;
    }

    usleep(CONVERSION_DELAY_MS * 1000);

    uint8_t buf[3];
    ssize_t n = read(fd, buf, 3);
    if (n != 3) {
        fprintf(stderr, "Error: Failed to read 3 bytes from I2C device (got %zd bytes).\n", n);
        return -1;
    }

    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "Error: CRC mismatch on temperature data.\n");
        return -1;
    }

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *temperature = -45.0f + (175.0f * (float)raw / 65535.0f);
    return 0;
}

static int log_temperature(FILE *fp, float temperature) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r failed.\n");
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "Error: strftime failed.\n");
        return -1;
    }

    if (fprintf(fp, "%s, %.2f\n", timestamp, temperature) < 0) {
        fprintf(stderr, "Error: Failed to write to log file.\n");
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "Error: Failed to flush log file.\n");
        return -1;
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (g_i2c_fd < 0) {
        perror("Error opening I2C device");
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, STS40_ADDR) < 0) {
