/*
 * SCD40 CO2 sensor reader for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   SCD40 SDA  -> GPIO2 (pin 3, I2C1 SDA)
 *   SCD40 SCL  -> GPIO3 (pin 5, I2C1 SCL)
 *   SCD40 VDD  -> 3.3 V
 *   SCD40 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o scd40_logger scd40_logger.c -lpigpio -lpthread
 * Run:    sudo ./scd40_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pthread.h>
#include <pigpio.h>

#define SCD40_I2C_ADDR          0x61
#define SCD40_CMD_START_PERIODIC 0x21B1
#define SCD40_CMD_STOP_PERIODIC  0x3F86
#define SCD40_CMD_READ_MEAS      0xEC05
#define SCD40_CMD_GET_SERIAL     0x3682
#define SCD40_CMD_GET_FIRMWARE   0x211F

#define BUFFER_SIZE             100
#define LOG_DIR                 "/var/log/scd40_data"
#define ERROR_LOG_FILE          "/var/log/scd40_error.log"
#define CSV_FILE_NAME           "scd40_data.csv"
#define READ_INTERVAL_SEC       5
#define FIRST_READ_DELAY_SEC    1
#define LOG_FLUSH_INTERVAL_SEC  60

#define CRC8_POLY               0x31
#define CRC8_INIT               0xFF

typedef struct {
    uint16_t co2;
    float    temperature;
    float    humidity;
    time_t   timestamp;
} sensor_data_t;

typedef struct {
    sensor_data_t buffer[BUFFER_SIZE];
    int head;
    int tail;
    int count;
    pthread_mutex_t mutex;
} circular_buffer_t;

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static circular_buffer_t g_buffer;
static pthread_t g_log_thread;

/* ---- CRC-8 (Sensirion polynomial 0x31, init 0xFF) ---- */
static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC8_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ CRC8_POLY);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ---- Logging thread: flush buffered data to CSV every 60 s ---- */
static void *log_thread_fn(void *arg) {
    (void)arg;
    while (g_running) {
        sleep(LOG_FLUSH_INTERVAL_SEC);
        if (!g_running)
            break;

        pthread_mutex_lock(&g_buffer.mutex);
        int count = g_buffer.count;
        int tail  = g_buffer.tail;
        pthread_mutex_unlock(&g_buffer.mutex);

        if (count == 0)
            continue;

        char filepath[512];
        time_t now = time(NULL);
        struct tm tm_info;
        localtime_r(&now, &tm_info);
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%d_%H-%M-%S", &tm_info);
        snprintf(filepath, sizeof(filepath), "%s/%s_%s.csv", LOG_DIR, CSV_FILE_NAME, ts);

        FILE *fp = fopen(filepath, "w");
        if (!fp) {
            fprintf(stderr, "log_thread: cannot open %s\n", filepath);
            continue;
        }

        pthread_mutex_lock(&g_buffer.mutex);
        for (int i = 0; i < count; i++) {
            int idx = (tail + i) % BUFFER_SIZE;
            fprintf(fp, "%ld,%u,%.2f,%.2f\n",
                    (long)g_buffer.buffer[idx].timestamp,
                    g_buffer.buffer[idx].co2,
                    g_buffer.buffer[idx].temperature,
                    g_buffer.buffer[idx].humidity);
        }
        pthread_mutex_unlock(&g_buffer.mutex);

        fclose(fp);
        printf("Data flushed to %s (%d records)\n", filepath, count);
    }
    return NULL;
}

/* ---- Signal handler ---- */
static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* ---- Error logger ---- */
static void log_error(const char *msg) {
    FILE *fp = fopen(ERROR_LOG_FILE, "a");
    if (!fp) {
        perror("fopen error log");
        return;
    }
    time_t now = time(NULL);
    struct tm tm_info;
    localtime_r(&now, &tm_info);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(fp, "%s: %s\n", ts, msg);
    fclose(fp);
}

/* ---- I2C write helper ---- */
static int i2c_write_cmd(uint16_t cmd) {
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    int rc = i2cWriteDevice(g_i2c_handle, (char *)buf, 2);
    if (rc < 0) {
        char msg[128];
        snprintf(msg, sizeof(msg), "i2cWriteDevice failed: %d", rc);
        log_error(msg);
    }
    return rc;
}

/* ---- I2C read helper ---- */
static int i2c_read_data(uint8_t *buf, int len) {
    int rc = i2cReadDevice(g_i2c_handle, (char *)buf, len);
    if (rc != len) {
        char msg[128];
        snprintf(msg, sizeof(msg), "i2cReadDevice failed: got %d, expected %d", rc, len);
        log_error(msg);
        return -1;
    }
    return 0;
}

/* ---- Read sensor data ---- */
static int read_sensor_data(sensor_data_t *data) {
    if (i2c_write_cmd(SCD40_CMD_READ_MEAS) < 0)
        return -1;
    gpioDelay(10000); /* 10 ms conversion delay */

    uint8_t buf[9];
    if (i2c_read_data(buf, 9) < 0)
        return -1;

    /* Validate CRC for each 3-byte word */
    if (crc8(&buf[0], 2) != buf[2]) {
        log_error("CRC mismatch on CO2 word");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        log_error("CRC mismatch on temperature word");
        return -1;
    }
    if (crc8(&buf[6], 2) != buf[8]) {
        log_error("CRC mismatch on humidity word");
        return -1;
    }

    data->co2         = (uint16_t)((buf[0] << 8) | buf[1]);
    data->temperature = ((float)((buf[3] << 8) | buf[4])) / 100.0f;
    data->humidity    = ((float)((buf[6] << 8) | buf[7])) / 100.0f;
    data->timestamp   = time(NULL);
    return 0;
}

/* ---- Circular buffer ---- */
static void buffer_init(circular_buffer_t *cb) {
    cb->head  = 0;
    cb->tail  = 0;
    cb->count = 0;
    pthread_mutex_init(&cb->mutex, NULL);
}

static void buffer_add(circular_buffer_t *cb, sensor_data_t data) {
    pthread_mutex_lock(&cb->mutex);
    cb->buffer[cb->head] = data;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count == BUFFER_SIZE)
        cb->tail = (cb->tail + 1) % BUFFER_SIZE;
    else
        cb->count++;
    pthread_mutex_unlock(&cb->mutex);
}

static void buffer_destroy(circular_buffer_t *cb) {
    pthread_mutex_destroy(&cb->mutex);
}

/* ---- Cleanup ---- */
static void cleanup(void) {
    if (g_i2c_handle >= 0) {
        i2c_write_cmd(SCD40_CMD_STOP_PERIODIC);
        gpioDelay(500000); /* 500 ms stop delay */
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    buffer_destroy(&g_buffer);
    gpioTerminate();
}

/* ---- Main ---- */
int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(1, SCD40_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %d\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    buffer_init(&g_buffer);

    if (pthread_create(&g_log_thread, NULL, log_thread_fn, NULL) != 0) {
        perror("pthread_create");
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* Start periodic measurement */
    if (i2c_write_cmd(SCD40_CMD_START_PERIODIC) < 0) {
        fprintf(stderr, "Failed to start periodic measurement\n");
        g_running = 0;
        pthread_join(g_log_thread, NULL);
        cleanup();
        return EXIT_FAILURE;
    }
    sleep(FIRST_READ_DELAY_SEC);

    printf("SCD40 logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        sensor_data_t data;
        if (read_sensor_data(&data) == 0) {
            buffer_add(&g_buffer, data);
            printf("CO2: %u ppm, Temp: %.2f C, RH: %.2f %%\n",
                   data.co2, data.temperature, data.humidity);
        } else {
            log_error("Sensor read failed; skipping sample");
        }
        sleep(READ_INTERVAL_SEC);
    }

    /* Final flush */
    pthread_mutex_lock(&g_buffer.mutex);
    int count = g_buffer.count;
    int tail  = g_buffer.tail;
    pthread_mutex_unlock(&g_buffer.mutex);

    if (count > 0) {
        char filepath[512];
        time_t now = time(NULL);
        struct tm tm_info;
        localtime_r(&now, &tm_info);
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%d_%H-%M-%S", &tm_info);
        snprintf(filepath, sizeof(filepath), "%s/%s_%s.csv", LOG_DIR, CSV_FILE_NAME, ts);

        FILE *fp = fopen(filepath, "w");
        if (fp) {
            pthread_mutex_lock(&g_buffer.mutex);
            for (int i = 0; i < count; i++) {
                int idx = (tail + i) % BUFFER_SIZE;
                fprintf(fp, "%ld,%u,%.2f,%.2f\n",
                        (long)g_buffer.buffer[idx].timestamp,
                        g_buffer.buffer[idx].co2,
                        g_buffer.buffer[idx].temperature,
                        g_buffer.buffer[idx].humidity);
            }
            pthread_mutex_unlock(&g_buffer.mutex);
            fclose(fp);
            printf("Final data flushed to %s (%d records)\n", filepath, count);
        } else {
            log_error("Failed to create final CSV file");
        }
    }

    g_running = 0;
    pthread_join(g_log_thread, NULL);
    cleanup();
    printf("Program terminated cleanly.\n");
    return EXIT_SUCCESS;
}

