/*
 * SDP810-500Pa differential pressure sensor reader for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   SDP810 SDA  -> GPIO2 (I2C1 SDA, pin 3)
 *   SDP810 SCL  -> GPIO3 (I2C1 SCL, pin 5)
 *   SDP810 VDD  -> 3.3 V (pin 1)
 *   SDP810 GND  -> GND  (pin 6)
 *
 * Build:  gcc -O2 -Wall -Wextra -o sdp810 sdp810.c
 * Run:    ./sdp810   (requires i2c group access or root)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x21
#define LOG_FILE       "sdp810_log.txt"
#define SAMPLE_PERIOD  1.0          /* seconds between samples */
#define MEASURE_DELAY  0.045        /* seconds — SDP810 conversion time */
#define TRIGGER_CMD    0x362F       /* trigger measurement, no averaging */

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (polynomial 0x31, init 0xFF, no final XOR) — Sensirion spec   */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, int len)
{
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_cmd(int handle, uint16_t cmd)
{
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (i2cWriteDevice(handle, (char *)buf, 2) != 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice failed (cmd 0x%04X)\n", cmd);
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int handle, uint8_t *buf, int len)
{
    if (i2cReadDevice(handle, (char *)buf, len) != len) {
        fprintf(stderr, "[ERROR] i2cReadDevice failed (expected %d bytes)\n", len);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor read                                                         */
/* ------------------------------------------------------------------ */
static int read_sdp810(int handle, float *pressure, float *temperature)
{
    uint8_t data[9];

    if (i2c_write_cmd(handle, TRIGGER_CMD) != 0)
        return -1;

    time_sleep(MEASURE_DELAY);

    if (i2c_read_bytes(handle, data, sizeof(data)) != 0)
        return -1;

    /* CRC checks: bytes 0-1 + CRC, 3-4 + CRC, 6-7 + CRC */
    if (crc8(&data[0], 2) != data[2]) {
        fprintf(stderr, "[ERROR] pressure CRC mismatch\n");
        return -1;
    }
    if (crc8(&data[3], 2) != data[5]) {
        fprintf(stderr, "[ERROR] temperature CRC mismatch\n");
        return -1;
    }
    if (crc8(&data[6], 2) != data[8]) {
        fprintf(stderr, "[ERROR] scale-factor CRC mismatch\n");
        return -1;
    }

    int16_t dp_raw = (int16_t)((data[0] << 8) | data[1]);
    int16_t t_raw  = (int16_t)((data[3] << 8) | data[4]);
    int16_t sc_raw = (int16_t)((data[6] << 8) | data[7]);

    if (sc_raw == 0) {
        fprintf(stderr, "[ERROR] scale factor is zero — invalid data\n");
        return -1;
    }

    *pressure    = (float)dp_raw / (float)sc_raw;
    *temperature = (float)t_raw  / 200.0f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_sample(float pressure, float temperature)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    fprintf(g_log_file, "%s,%.2f,%.2f\n", ts, pressure, temperature);
    fflush(g_log_file);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "[ERROR] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("fopen(" LOG_FILE ")");
        cleanup();
        return EXIT_FAILURE;
    }

    fprintf(g_log_file, "# SDP810-500Pa log started — timestamp,pressure_Pa,temperature_C\n");
    fflush(g_log_file);

    printf("SDP810 logging to %s. Press Ctrl+C to stop.\n", LOG_FILE);

    while (g_running) {
        float pressure, temperature;

        if (read_sdp810(g_i2c_handle, &pressure, &temperature) == 0) {
            log_sample(pressure, temperature);
            printf("Pressure: %.2f Pa | Temperature: %.2f °C\n",
                   pressure, temperature);
        } else {
            fprintf(stderr, "[WARN] read failed — will retry next cycle\n");
        }

        time_sleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

