#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS        "/dev/i2c-1"
#define ICP10125_ADDR  0x77
#define LED_GPIO       17
#define PRESSURE_THRESHOLD 95000.0f
#define POLL_DELAY_US  1000000
#define TRIGGER_DELAY_US 20000
#define NORMAL_ON_US   500000
#define NORMAL_OFF_US  500000
#define WARN_ON_US     100000
#define WARN_OFF_US    100000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static uint8_t crc4(const uint8_t *data, int len) {
    uint8_t crc = 0x0F;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 4; j++) {
            if (crc & 0x08) crc = (crc << 1) ^ 0x0B;
            else           crc <<= 1;
        }
    }
    return crc;
}

static int i2c_write_byte(int fd, uint8_t reg) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, int len) {
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "I2C read %d bytes failed: %s\n", len, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_sensor(int fd, float *pressure, float *temperature) {
    uint8_t buf[6];

    if (i2c_write_byte(fd, 0x36) < 0) return -1;
    usleep(TRIGGER_DELAY_US);

    if (i2c_read_bytes(fd, buf, 6) < 0) return -1;

    if (crc4(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Pressure CRC mismatch\n");
        return -1;
    }
    if (crc4(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }

    uint16_t p_raw = ((uint16_t)buf[0] << 8) | buf[1];
    uint16_t t_raw = ((uint16_t)buf[3] << 8) | buf[4];

    *pressure    = (float)p_raw / 100.0f;
    *temperature = (float)t_raw / 100.0f;
    return 0;
}

static void control_led(float pressure) {
    if (pressure < PRESSURE_THRESHOLD) {
        gpioWrite(LED_GPIO, 1);
        usleep(WARN_ON_US);
        gpioWrite(LED_GPIO, 0);
        usleep(WARN_OFF_US);
    } else {
        gpioWrite(LED_GPIO, 1);
        usleep(NORMAL_ON_US);
        gpioWrite(LED_GPIO, 0);
        usleep(NORMAL_OFF_US);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, ICP10125_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave 0x%02X: %s\n", ICP10125_ADDR, strerror(errno));
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    while (g_running) {
        float pressure, temperature;
        if (read_sensor(g_i2c_fd, &pressure, &temperature) == 0) {
            printf("Pressure: %.2f Pa, Temperature: %.2f C\n", pressure, temperature);
            control_led(pressure);
        } else {
            fprintf(stderr, "Sensor read failed; continuing.\n");
        }
        usleep(POLL_DELAY_US);
    }

    gpioWrite(LED_GPIO, 0);
    if (g_i2c_fd >= 0) close(g_i2c_fd);
    gpioTerminate();
    return EXIT_SUCCESS;
}

