#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define MLX90614_ADDR 0x5A
#define MLX90614_TA 0x06
#define MLX90614_TOBJ1 0x07
#define FAN_GPIO 18
#define TEMP_THRESHOLD_HIGH 30.0
#define TEMP_THRESHOLD_LOW 28.0
#define LOG_FILE "temperature_log.txt"
#define I2C_BUS 1
#define MAX_RETRIES 3
#define RETRY_DELAY_US 10000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_temperature(float *ambient, float *object) {
    int raw_ambient, raw_object;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        raw_ambient = i2cReadWordData(i2c_handle, MLX90614_TA);
        if (raw_ambient < 0) {
            fprintf(stderr, "Error reading ambient temperature (attempt %d): %d\n", retries + 1, raw_ambient);
            retries++;
            if (retries < MAX_RETRIES) gpioDelay(RETRY_DELAY_US);
            continue;
        }

        raw_object = i2cReadWordData(i2c_handle, MLX90614_TOBJ1);
        if (raw_object < 0) {
            fprintf(stderr, "Error reading object temperature (attempt %d): %d\n", retries + 1, raw_object);
            retries++;
            if (retries < MAX_RETRIES) gpioDelay(RETRY_DELAY_US);
            continue;
        }

        *ambient = (float)raw_ambient * 0.02 - 273.15;
        *object = (float)raw_object * 0.02 - 273.15;
        return 0;
    }

    fprintf(stderr, "Failed to read temperatures after %d attempts.\n", MAX_RETRIES);
    return -1;
}

static void log_temperature(float ambient, float object) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, Ambient: %.2f C, Object: %.2f C\n", timestamp, ambient, object);
    fclose(fp);
}

static void control_fan(float object_temp) {
    static int fan_on = 0;

    if (object_temp > TEMP_THRESHOLD_HIGH && !fan_on) {
        gpioWrite(FAN_GPIO, 1);
        fan_on = 1;
        printf("Fan turned ON (Object: %.2f C)\n", object_temp);
    } else if (object_temp < TEMP_THRESHOLD_LOW && fan_on) {
        gpioWrite(FAN_GPIO, 0);
        fan_on = 0;
        printf("Fan turned OFF (Object: %.2f C)\n", object_temp);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, MLX90614_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioWrite(FAN_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
