#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x60
#define SERVER_PORT 8080
#define MAX_RETRIES 3
#define MEASUREMENT_DELAY_US 10000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sht40(int i2c_handle, float *temperature, float *humidity) {
    unsigned char cmd[1] = {0x24};
    unsigned char data[6];
    int result;

    for (int i = 0; i < MAX_RETRIES; i++) {
        result = i2cWriteDevice(i2c_handle, (char *)cmd, 1);
        if (result != 0) {
            fprintf(stderr, "I2C write error (attempt %d): %s\n", i + 1, strerror(errno));
            gpioDelay(100000);
            continue;
        }

        gpioDelay(MEASUREMENT_DELAY_US);

        result = i2cReadDevice(i2c_handle, (char *)data, 6);
        if (result != 6) {
            fprintf(stderr, "I2C read error (attempt %d): expected 6 bytes, got %d\n", i + 1, result);
            gpioDelay(100000);
            continue;
        }

        unsigned short t_ticks = (data[0] << 8) | data[1];
        unsigned short h_ticks = (data[3] << 8) | data[4];

        *temperature = -45.0f + 175.0f * (float)t_ticks / 65535.0f;
        *humidity = 100.0f * (float)h_ticks / 65535.0f;

        if (*humidity > 100.0f) *humidity = 100.0f;
        if (*humidity < 0.0f) *humidity = 0.0f;

        return 0;
    }

    return -1;
}

static void send_http_response(int client_socket, float temperature, float humidity) {
    char response[512];
    int len = snprintf(response, sizeof(response),
        "HTTP/1.1 200 OK\r\n"
        "Content-Type: text/html\r\n"
        "Connection: close\r\n"
        "\r\n"
        "<!DOCTYPE html><html><head><title>SHT40 Sensor</title>"
        "<meta http-equiv=\"refresh\" content=\"5\"></head><body>"
        "<h1>SHT40 Sensor Data</h1>"
        "<p>Temperature: %.2f &deg;C</p>"
        "<p>Humidity: %.2f %%</p>"
        "</body></html>",
        temperature, humidity);

    if (len > 0) {
        send(client_socket, response, (size_t)len, 0);
    }
}

int main(void) {
    int i2c_handle = -1;
    int server_socket = -1;
    struct sockaddr_in server_addr;
    struct sockaddr_in client_addr;
    socklen_t client_len = sizeof(client_addr);
    float temperature, humidity;
    int opt = 1;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at bus %d, addr 0x%02X: %s\n",
                I2C_BUS, I2C_ADDR, strerror(errno));
        gpioTerminate();
        return 1;
    }

    server_socket = socket(AF_INET, SOCK_STREAM, 0);
    if (server_socket < 0) {
        perror("socket");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (setsockopt(server_socket, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        perror("setsockopt");
        close(server_socket);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;
    server_addr.sin_port = htons(SERVER_PORT);

    if (bind(server_socket, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("bind");
        close(server_socket);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (listen(server_socket, 5) < 0) {
        perror("listen");
        close(server_socket);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("SHT40 HTTP server listening on port %d (Ctrl+C to exit)\n", SERVER_PORT);

    while (running) {
        int client_socket = accept(server_socket, (struct sockaddr *)&client_addr, &client_len);
        if (client_socket < 0) {
            if (errno == EINTR) continue;
            perror("accept");
            break;
        }

        if (read_sht40(i2c_handle, &temperature, &humidity) == 0) {
            send_http_response(client_socket, temperature, humidity);
        } else {
            const char *err = "HTTP/1.1 500 Internal Server Error\r\n"
                              "Content-Type: text/plain\r\n"
                              "Connection: close\r\n"
                              "\r\n"
                              "Sensor read failed after retries.\r\n";
            send(client_socket, err, strlen(err), 0);
        }

        close(client_socket);
    }

    if (server_socket >= 0) close(server_socket);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();

    printf("\nServer shut down cleanly.\n");
    return 0;
}

