/*
 * Raspberry Pi Zero W – TI HDC2010 temperature & humidity reader
 * I2C bus 1, address 0x44 (ADDR pin tied to GND).
 *
 * Build:  gcc -O2 -Wall -Wextra -o hdc2010 hdc2010.c -li2c
 * Run:    sudo ./hdc2010
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define HDC2010_ADDR   0x44

/* HDC2010 register addresses */
#define REG_TEMP_LOW    0x00
#define REG_HUM_LOW     0x02
#define REG_MEAS_CFG    0x0E
#define REG_INT_CFG    0x0F
#define REG_INT_STATUS 0x0F

/* MEASUREMENT_CONFIG bits */
#define MEAS_CFG_MEAS_TRIG 0x01
#define MEAS_CFG_HUM_EN    0x02
#define MEAS_CFG_TEMP_EN   0x04
#define MEAS_CFG_MODE      0x0C  /* 00 = Humidity, 01 = Temp, 10 = Both */

/* INT_CFG / INT_STATUS bits */
#define INT_CFG_HUM_INT_EN 0x02
#define INT_CFG_TEMP_INT_EN 0x04

#define POLL_TIMEOUT_MS   500
#define SAMPLE_PERIOD_S   5
#define MAX_RETRIES       3

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */

static int i2c_write_byte(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_write_byte(0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *dst, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_burst write(0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, dst, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "i2c_read_burst read(0x%02X, %zu): got %zd (%s)\n",
                reg, len, n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* HDC2010                                                             */
/* ------------------------------------------------------------------ */

static int hdc2010_init(int fd)
{
    /* Software reset: write 0x80 to MEAS_CFG (bit 7 = RESET) */
    if (i2c_write_byte(fd, REG_MEAS_CFG, 0x80) < 0)
        return -1;
    usleep(15000);  /* 15 ms reset settling */

    /* Clear any latched interrupts by reading INT_STATUS */
    uint8_t status;
    if (i2c_read_burst(fd, REG_INT_STATUS, &status, 1) < 0)
        return -1;

    /* Configure: enable both humidity and temperature interrupts */
    if (i2c_write_byte(fd, REG_INT_CFG, INT_CFG_HUM_INT_EN | INT_CFG_TEMP_INT_EN) < 0)
        return -1;

    return 0;
}

/*
 * Trigger a measurement and wait for completion.
 * Returns 0 on success, -1 on timeout or I2C error.
 */
static int hdc2010_trigger_and_wait(int fd)
{
    uint8_t cfg = MEAS_CFG_HUM_EN | MEAS_CFG_TEMP_EN | MEAS_CFG_MODE | MEAS_CFG_MEAS_TRIG;

    if (i2c_write_byte(fd, REG_MEAS_CFG, cfg) < 0)
        return -1;

    /* Poll MEAS_CFG bit 0 (MEAS_TRIG) until it clears */
    for (int elapsed = 0; elapsed < POLL_TIMEOUT_MS; elapsed += 10) {
        uint8_t cfg_val;
        if (i2c_read_burst(fd, REG_MEAS_CFG, &cfg_val, 1) < 0)
            return -1;
        if ((cfg_val & MEAS_CFG_MEAS_TRIG) == 0)
            return 0;
        usleep(10000);  /* 10 ms */
    }

    fprintf(stderr, "HDC2010 measurement timeout\n");
    return -1;
}

static int hdc2010_read(int fd, float *temperature, float *humidity)
{
    uint8_t data[4];

    if (hdc2010_trigger_and_wait(fd) < 0)
        return -1;

    if (i2c_read_burst(fd, REG_TEMP_LOW, data, 4) < 0)
        return -1;

    uint16_t raw_temp = ((uint16_t)data[1] << 8) | data[0];
    uint16_t raw_hum  = ((uint16_t)data[3] << 8) | data[2];

    *temperature = ((float)raw_temp / 65535.0f) * 165.0f - 40.0f;
    *humidity    = ((float)raw_hum  / 65535.0f) * 100.0f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, HDC2010_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                HDC2010_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /* Probe: a zero-length write returns NAK if the sensor is absent */
    if (i2c_write_byte(fd, 0x00, 0x00) < 0) {
        fprintf(stderr, "HDC2010 not detected at 0x%02X on %s\n",
                HDC2010_ADDR, I2C_BUS);
        close(fd);
        return EXIT_FAILURE;
    }

    if (hdc2010_init(fd) < 0) {
        fprintf(stderr, "HDC2010 initialization failed\n");
        close(fd);
        return EXIT_FAILURE;
    }

    printf("HDC2010 initialized. Sampling every %d s. Press Ctrl+C to exit.\n",
           SAMPLE_PERIOD_S);

    while (g_running) {
        float temperature = 0.0f, humidity = 0.0f;
        int ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; ++attempt) {
            if (hdc2010_read(fd, &temperature, &humidity) == 0) {
                ok = 1;
                break;
            }
            fprintf(stderr, "Read attempt %d/%d failed\n", attempt + 1, MAX_RETRIES);
            usleep(100000);  /* 100 ms back-off */
        }

        if (ok) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n",
                   temperature, humidity);
            fflush(stdout);
        } else {
            fprintf(stderr, "Sensor read failed after %d attempts; continuing.\n",
                    MAX_RETRIES);
        }

        /* Sleep in 100 ms increments so SIGINT is caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD_S * 10 && g_running; ++i)
            usleep(100000);
    }

    /* Clean shutdown */
    if (ioctl(fd, I2C_SLAVE, 0) < 0)
        perror("ioctl(I2C_SLAVE, 0)");
    close(fd);
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

