/*
 * Raspberry Pi 3 Model B+ — Sensirion SDP800-500Pa differential pressure reader
 *
 * Wiring:
 *   SDP800 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   SDP800 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   SDP800 VDD  -> 3.3 V
 *   SDP800 GND  -> GND
 *
 * I2C address: 0x21 (SDP800 default, 7-bit)
 * Measurement command: 0x362F (continuous measurement, no averaging)
 *   — 2 bytes command, 6 bytes response (2 pressure + 1 CRC + 2 temp + 1 CRC)
 *   — 45 ms max conversion time
 *
 * Build: gcc -O2 -Wall -Wextra -o sdp800 sdp800.c -lpigpio -lrt
 * Run:   sudo ./sdp800
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SDP800_ADDR    0x21
#define CMD_CONT_MEAS  0x362F   /* continuous measurement, no averaging */
#define MEAS_DELAY_US  45000    /* 45 ms max conversion time */
#define LOOP_DELAY_US  500000   /* 500 ms between samples */
#define BYTES_PER_READ 6        /* 2 pressure + 1 CRC + 2 temp + 1 CRC */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Sensirion CRC-8: polynomial 0x31, init 0xFF, no final XOR */
static bool crc8_ok(const uint8_t *data, uint8_t len, uint8_t expected)
{
    uint8_t crc = 0xFF;
    for (uint8_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (uint8_t b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc == expected;
}

/*
 * Read one 6-byte measurement frame from the SDP800.
 * Returns 0 on success, -1 on I/O error, -2 on CRC mismatch.
 */
static int read_sdp800(int handle, int16_t *pressure, int16_t *temperature)
{
    uint8_t cmd[2] = {
        (uint8_t)((CMD_CONT_MEAS >> 8) & 0xFF),
        (uint8_t)(CMD_CONT_MEAS & 0xFF)
    };
    uint8_t buf[BYTES_PER_READ];

    /* Send continuous-measurement command */
    if (i2cWriteDevice(handle, (char *)cmd, 2) != 2) {
        fprintf(stderr, "[ERROR] i2cWriteDevice failed (cmd 0x%04X)\n",
                CMD_CONT_MEAS);
        return -1;
    }

    /* Wait for conversion to complete */
    gpioDelay(MEAS_DELAY_US);

    /* Read 6 bytes: [P_hi P_lo P_crc T_hi T_lo T_crc] */
    int n = i2cReadDevice(handle, (char *)buf, BYTES_PER_READ);
    if (n != BYTES_PER_READ) {
        fprintf(stderr, "[ERROR] i2cReadDevice returned %d (expected %d)\n",
                n, BYTES_PER_READ);
        return -1;
    }

    /* Validate CRCs */
    if (!crc8_ok(&buf[0], 2, buf[2])) {
        fprintf(stderr, "[ERROR] Pressure CRC mismatch\n");
        return -2;
    }
    if (!crc8_ok(&buf[3], 2, buf[5])) {
        fprintf(stderr, "[ERROR] Temperature CRC mismatch\n");
        return -2;
    }

    *pressure    = (int16_t)((buf[0] << 8) | buf[1]);
    *temperature = (int16_t)((buf[3] << 8) | buf[4]);
    return 0;
}

int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open I2C handle --- */
    int handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen failed (bus %d, addr 0x%02X): %d\n",
                I2C_BUS, SDP800_ADDR, handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handler for clean shutdown --- */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGINT) failed; Ctrl+C will not exit cleanly\n");
    }

    printf("SDP800-500Pa reader started (I2C bus %d, addr 0x%02X).\n",
           I2C_BUS, SDP800_ADDR);
    printf("Press Ctrl+C to stop.\n\n");

    /* --- Main sampling loop --- */
    while (g_running) {
        int16_t pressure = 0, temperature = 0;
        int rc = read_sdp800(handle, &pressure, &temperature);

        if (rc == 0) {
            printf("Pressure: %d Pa, Temperature: %d C\n",
                   pressure, temperature);
        } else if (rc == -2) {
            fprintf(stderr, "[WARN] CRC error — skipping sample\n");
        } else {
            fprintf(stderr, "[WARN] I/O error — skipping sample\n");
        }

        /* Sleep 500 ms, but wake early on signal */
        for (int i = 0; i < 50 && g_running; i++)
            gpioDelay(10000); /* 10 ms × 50 = 500 ms */
    }

    /* --- Clean shutdown --- */
    printf("\nShutting down...\n");
    if (i2cClose(handle) != 0)
        fprintf(stderr, "[WARN] i2cClose failed\n");
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

