#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define GPIO_RELAY 17
#define LOG_FILE "reflow_log.csv"
#define PROFILE_FILE "profile.txt"
#define SAMPLE_INTERVAL_US 1000000
#define DUTY_CYCLE_PERIOD_US 1000000

typedef struct {
    float kp;
    float ki;
    float kd;
    float setpoint;
    float integral;
    float previous_error;
} PIDController;

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;
static FILE *profile_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_max6675(float *temperature) {
    char buf[2] = {0, 0};
    int ret = spiRead(spi_handle, buf, 2);
    if (ret != 2) {
        fprintf(stderr, "SPI read error: %d\n", ret);
        return -1;
    }
    int raw = ((buf[0] << 8) | buf[1]) & 0xFFF;
    if (raw & 0x04) {
        fprintf(stderr, "Thermocouple fault detected\n");
        return -1;
    }
    *temperature = (raw >> 3) * 0.25f;
    return 0;
}

static float pid_calculate(PIDController *pid, float current) {
    float error = pid->setpoint - current;
    pid->integral += error;
    if (pid->integral > 100.0f) pid->integral = 100.0f;
    if (pid->integral < -100.0f) pid->integral = -100.0f;
    float derivative = error - pid->previous_error;
    float output = pid->kp * error + pid->ki * pid->integral + pid->kd * derivative;
    pid->previous_error = error;
    return output;
}

static void set_relay_duty_cycle(float duty_cycle) {
    if (duty_cycle < 0.0f) duty_cycle = 0.0f;
    if (duty_cycle > 1.0f) duty_cycle = 1.0f;
    int on_us = (int)(duty_cycle * DUTY_CYCLE_PERIOD_US);
    int off_us = DUTY_CYCLE_PERIOD_US - on_us;
    gpioWrite(GPIO_RELAY, 1);
    gpioDelay(on_us);
    gpioWrite(GPIO_RELAY, 0);
    gpioDelay(off_us);
}

static int load_profile(float *times, float *temps, int max_points) {
    int count = 0;
    char line[256];
    while (fgets(line, sizeof(line), profile_file) && count < max_points) {
        float t, temp;
        if (sscanf(line, "%f,%f", &t, &temp) == 2) {
            times[count] = t;
            temps[count] = temp;
            count++;
        }
    }
    return count;
}

static void log_data(float temp, float duty) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(log_file, "%s,%.2f,%.2f\n", ts, temp, duty);
    fflush(log_file);
}

int main(void) {
    struct sigaction sa = {0};
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(GPIO_RELAY, PI_OUTPUT);
    gpioWrite(GPIO_RELAY, 0);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen log");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    profile_file = fopen(PROFILE_FILE, "r");
    if (!profile_file) {
        perror("fopen profile");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    float times[100], temps[100];
    int num_points = load_profile(times, temps, 100);
    if (num_points <= 0) {
        fprintf(stderr, "Invalid profile\n");
        fclose(profile_file);
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    PIDController pid = {1.0f, 0.1f, 0.01f, 0.0f, 0.0f, 0.0f};
    float current_time = 0.0f;
    float last_profile_time = times[0];

    while (running) {
        float temp;
        if (read_max6675(&temp) != 0) {
            fprintf(stderr, "Sensor read error\n");
            gpioWrite(GPIO_RELAY, 0);
            gpioDelay(SAMPLE_INTERVAL_US);
            current_time += 1.0f;
            continue;
        }

        current_time += 1.0f;
        float pid_out = pid_calculate(&pid, temp);
        float duty = pid_out / 100.0f;
        set_relay_duty_cycle(duty);
        log_data(temp, duty);

        if (current_time >= last_profile_time && (int)current_time >= (int)last_profile_time) {
            int idx = (int)current_time;
            if (idx < num_points) {
                pid.setpoint = temps[idx];
                last_profile_time = times[idx];
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    gpioWrite(GPIO_RELAY, 0);
    fclose(log_file);
    fclose(profile_file);
    spiClose(spi_handle);
    gpioTerminate();
    return 0;
}

