/*
 * Greenhouse PID heater controller for Raspberry Pi 3 Model B+
 *
 * Hardware:
 *   - DS18B20 temperature sensor  -> GPIO4  (physical pin 7)  [1-Wire]
 *   - Relay (12 V heater control) -> GPIO17 (physical pin 11)
 *   - PWM duty control            -> GPIO18 (physical pin 12) [hardware PWM]
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o greenhouse greenhouse.c -lm
 *
 * Run:
 *   ./greenhouse --setpoint 25.0 --kp 1.0 --ki 0.1 --kd 0.01
 */

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <math.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>

#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define W1_DEVICES_DIR      "/sys/bus/w1/devices"
#define W1_SLAVE_PREFIX     "28-"
#define W1_SLAVE_SUFFIX     "-temperature"

#define RELAY_GPIO          17
#define PWM_GPIO            18
#define PWM_RANGE           1000000   /* 1 MHz range */
#define PWM_FREQ_HZ         1000      /* 1 kHz */

#define LOG_FILE            "greenhouse.log"
#define LOG_INTERVAL_SEC    5
#define MAX_SENSORS         4
#define MAX_TEMP_READINGS   10
#define MAX_TEMP_ERROR      100.0f
#define TEMP_ERROR          (-1000.0f)

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static FILE                 *g_log_fp  = NULL;

/* ----------------------------- Data Structures --------------------------- */
typedef struct {
    char  id[32];
    char  path[256];
} w1_sensor_t;

typedef struct {
    float kp;
    float ki;
    float kd;
} pid_t;

/* ----------------------------- Prototypes -------------------------------- */
static void  signal_handler(int sig);
static int   init_gpio(void);
static int   init_log(void);
static int   read_sensors(float temps[], int max, int *n);
static float pid_compute(float setpoint, float pv, float *integ, float *prev,
                         float kp, float ki, float kd);
static void  set_heater(float duty);
static void  log_data(float temps[], int n, float setpoint, float pid_out,
                      float duty);
static void  cleanup(void);

/* ----------------------------- Signal Handler ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- GPIO Init --------------------------------- */
static int init_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set relay GPIO %d as output\n", RELAY_GPIO);
        return -1;
    }
    if (gpioWrite(RELAY_GPIO, 0) < 0) {
        fprintf(stderr, "Failed to initialise relay GPIO %d low\n", RELAY_GPIO);
        return -1;
    }

    if (gpioSetMode(PWM_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set PWM GPIO %d as output\n", PWM_GPIO);
        return -1;
    }
    if (gpioSetPWMfrequency(PWM_GPIO, PWM_FREQ_HZ) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", PWM_GPIO);
        return -1;
    }
    if (gpioSetPWMrange(PWM_GPIO, PWM_RANGE) < 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO %d\n", PWM_GPIO);
        return -1;
    }
    if (gpioPWM(PWM_GPIO, 0) < 0) {
        fprintf(stderr, "Failed to initialise PWM GPIO %d to 0\n", PWM_GPIO);
        return -1;
    }

    return 0;
}

/* ----------------------------- Log Init ---------------------------------- */
static int init_log(void)
{
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        return -1;
    }
    return 0;
}

/* ----------------------------- Sensor Scan ------------------------------- */
static int scan_sensors(w1_sensor_t sensors[], int max)
{
    DIR           *dir = opendir(W1_DEVICES_DIR);
    if (!dir) {
        fprintf(stderr, "Cannot open %s: %s\n", W1_DEVICES_DIR, strerror(errno));
        return -1;
    }

    int count = 0;
    struct dirent *ent;
    while ((ent = readdir(dir)) != NULL && count < max) {
        if (strncmp(ent->d_name, W1_SLAVE_PREFIX, strlen(W1_SLAVE_PREFIX)) == 0) {
            size_t n = strlen(ent->d_name);
            if (n > sizeof(sensors[0].id) - 1) n = sizeof(sensors[0].id) - 1;
            memcpy(sensors[count].id, ent->d_name, n);
            sensors[count].id[n] = '\0';

            snprintf(sensors[count].path, sizeof(sensors[count].path),
                     "%s/%s/%s",
                     W1_DEVICES_DIR, ent->d_name, W1_SLAVE_SUFFIX);
            count++;
        }
    }
    closedir(dir);
    return count;
}

/* ----------------------------- DS18B20 Read ------------------------------ */
static float read_ds18b20(const char *path)
{
    int fd = open(path, O_RDONLY);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", path, strerror(errno));
        return TEMP_ERROR;
    }

    char buf[128];
    ssize_t n = read(fd, buf, sizeof(buf) - 1);
    close(fd);

    if (n <= 0) {
        fprintf(stderr, "read(%s): %s\n", path, strerror(errno));
        return TEMP_ERROR;
    }
    buf[n] = '\0';

    /* Strip trailing newline */
    while (n > 0 && (buf[n - 1] == '\n' || buf[n - 1] == '\r')) {
        buf[--n] = '\0';
    }

    /* DS18B20 returns "YES" on the first line, then the temperature */
    if (strncmp(buf, "YES", 3) != 0) {
        fprintf(stderr, "DS18B20 CRC check failed: %s\n", buf);
        return TEMP_ERROR;
    }

    char *val = strstr(buf, "t=");
    if (!val) {
        fprintf(stderr, "DS18B20 temperature marker not found\n");
        return TEMP_ERROR;
    }

    errno = 0;
    char *end = NULL;
    long raw = strtol(val + 2, &end, 10);
    if (errno != 0 || end == val + 2) {
        fprintf(stderr, "DS18B20 temperature parse error\n");
        return TEMP_ERROR;
    }

    return (float)raw / 1000.0f;
}

/* ----------------------------- Read Sensors ------------------------------ */
static int read_sensors(float temps[], int max, int *n)
{
    w1_sensor_t sensors[MAX_SENSORS];
    int count = scan_sensors(sensors, MAX_SENSORS);
    if (count <= 0) {
        fprintf(stderr, "No DS18B20 sensors found\n");
        return -1;
    }

    for (int i = 0; i < count && i < max; i++) {
        temps[i] = read_ds18b20(sensors[i].path);
        if (temps[i] <= TEMP_ERROR + 0.001f) {
            fprintf(stderr, "Sensor %s read error\n", sensors[i].id);
        }
    }

    *n = count;
    return 0;
}

/* ----------------------------- PID Compute ------------------------------- */
static float pid_compute(float setpoint, float pv, float *integ, float *prev,
                         float kp, float ki, float kd)
{
    float error   = setpoint - pv;
    float deriv   = error - *prev;
    *integ       += error;
    *prev        = error;

    float out = kp * error + ki * (*integ) + kd * deriv;
    if (out < 0.0f)   out = 0.0f;
    if (out > 100.0f) out = 100.0f;
    return out;
}

/* ----------------------------- Heater Control ---------------------------- */
static void set_heater(float duty)
{
    if (duty < 0.0f)   duty = 0.0f;
    if (duty > 100.0f) duty = 100.0f;

    int pwm_val = (int)((duty / 100.0f) * (float)PWM_RANGE);
    if (gpioPWM(PWM_GPIO, pwm_val) < 0) {
        fprintf(stderr, "gpioPWM failed: %s\n", strerror(errno));
    }

    int relay = (duty > 0.0f) ? 1 : 0;
    if (gpioWrite(RELAY_GPIO, relay) < 0) {
        fprintf(stderr, "gpioWrite(relay) failed: %s\n", strerror(errno));
    }
}

/* ----------------------------- Logging ----------------------------------- */
static void log_data(float temps[], int n, float setpoint, float pid_out,
                     float duty)
{
    time_t     t  = time(NULL);
    struct tm  tm;
    char       ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    float avg = 0.0f;
    int   ok  = 0;
    for (int i = 0; i < n; i++) {
        if (temps[i] > TEMP_ERROR + 0.001f) {
            avg += temps[i];
            ok++;
        }
    }
    avg /= ok;

    fprintf(g_log_fp, "%s,%.2f,%.2f,%.2f,%.2f\n",
            ts, avg, setpoint, pid_out, duty);
    fflush(g_log_fp);
}

/* ----------------------------- Cleanup ----------------------------------- */
static void cleanup(void)
{
    /* Turn off heater first for safety */
    gpioPWM(PWM_GPIO, 0);
    gpioWrite(RELAY_GPIO, 0);

    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioTerminate();
}

/* ----------------------------- Main -------------------------------------- */
int main(int argc, char *argv[])
{
    float setpoint = 25.0f;
    pid_t pid      = {1.0f, 0.1f, 0.01f};

    int opt;
    while ((opt = getopt(argc, argv, "s:k:i:d:")) != -1) {
        switch (opt) {
            case 's': setpoint = strtof(optarg, NULL); break;
            case 'k': pid.kp   = strtof(optarg, NULL); break;
            case 'i': pid.ki   = strtof(optarg, NULL); break;
            case 'd': pid.kd   = strtof(optarg, NULL); break;
            default:
                fprintf(stderr,
                        "Usage: %s [--setpoint <T>] [--kp <Kp>] [--ki <Ki>] [--kd <Kd>]\n",
                        argv[0]);
                return EXIT_FAILURE;
        }
    }

    if (setpoint < -40.0f || setpoint > 100.0f) {
        fprintf(stderr, "Setpoint %.2f out of range [-40, 100]\n", setpoint);
        return EXIT_FAILURE;
    }
    if (pid.kp < 0.0f || pid.ki < 0.0f || pid.kd < 0.0f) {
        fprintf(stderr, "Gains must be non-negative\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (init_gpio() < 0) {
        return EXIT_FAILURE;
    }
    if (init_log() < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    float temps[MAX_TEMP_READINGS];
    float integ = 0.0f, prev = 0.0f;
    int   n;

    while (g_running) {
        if (read_sensors(temps, MAX_TEMP_READINGS, &n) < 0) {
            fprintf(stderr, "Sensor read failed; retrying in %d s\n",
                    LOG_INTERVAL_SEC);
            sleep(LOG_INTERVAL_SEC);
            continue;
        }

        float avg = 0.0f;
        int   ok  = 0;
        for (int i = 0; i < n; i++) {
            if (temps[i] > TEMP_ERROR + 0.001f) {
                avg += temps[i];
                ok++;
            }
        }
        if (ok == 0) {
            fprintf(stderr, "No valid temperature readings; skipping cycle\n");
            sleep(LOG_INTERVAL_SEC);
            continue;
        }
        avg /= ok;

        float pid_out = pid_compute(setpoint, avg, &integ, &prev,
                                    pid.kp, pid.ki, pid.kd);
        set_heater(pid_out);

        log_data(temps, n, setpoint, pid_out, pid_out);
        sleep(LOG_INTERVAL_SEC);
    }

    cleanup();
    return EXIT_SUCCESS;
}

