#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define AHT20_ADDR             0x38
#define AHT20_CMD_TRIGGER      0xAC
#define AHT20_CMD_SOFTRESET    0xBA
#define AHT20_CMD_CALIBRATE    0xE1
#define AHT20_CMD_MEASURE      0x33
#define AHT20_CMD_READ         0x77
#define AHT20_CMD_RESET        0xBA
#define AHT20_CMD_CALIBRATE_OK 0x08
#define AHT20_CMD_CALIBRATE_ERR 0xFF
#define AHT20_CALIBRATE_RETRIES 3
#define AHT20_MEASURE_RETRIES  3
#define AHT20_MEASURE_DELAY_US 80000
#define DEHUMIDIFIER_GPIO      17
#define HUMIDITY_HIGH          60.0f
#define HUMIDITY_LOW           55.0f
#define POLL_INTERVAL_US       5000000
#define I2C_RETRY_DELAY_US     10000
#define I2C_BUS                "/dev/i2c-1"

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static int g_gpio_initialized = 0;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_cmd(uint8_t cmd) {
    if (g_i2c_fd < 0) return -1;
    if (write(g_i2c_fd, &cmd, 1) != 1) return -1;
    return 0;
}

static int i2c_read_bytes(uint8_t *buf, int len) {
    if (g_i2c_fd < 0) return -1;
    if (read(g_i2c_fd, buf, len) != len) return -1;
    return 0;
}

static int aht20_soft_reset(void) {
    if (i2c_write_cmd(AHT20_CMD_SOFTRESET) < 0) return -1;
    gpioDelay(2000);
    return 0;
}

static int aht20_calibrate(void) {
    if (i2c_write_cmd(AHT20_CMD_CALIBRATE) < 0) return -1;
    gpioDelay(10000);

    uint8_t status = 0;
    if (i2c_read_bytes(&status, 1) < 0) return -1;

    if (status == AHT20_CMD_CALIBRATE_OK) {
        return 0;
    } else if (status == AHT20_CMD_CALIBRATE_ERR) {
        fprintf(stderr, "AHT20 calibration failed (status=0xFF)\n");
        return -1;
    } else {
        fprintf(stderr, "AHT20 calibration status unknown (0x%02X)\n", status);
        return -1;
    }
}

static int aht20_read_humidity(float *humidity) {
    if (i2c_write_cmd(AHT20_CMD_MEASURE) < 0) return -1;
    gpioDelay(AHT20_MEASURE_DELAY_US);

    uint8_t buf[6];
    for (int attempt = 0; attempt < AHT20_MEASURE_RETRIES; attempt++) {
        if (i2c_read_bytes(buf, 6) == 0) {
            uint8_t status = buf[0];
            if ((status & 0x80) == 0) {
                uint32_t raw = ((uint32_t)buf[1] << 12) |
                               ((uint32_t)buf[2] << 4)  |
                               ((uint32_t)buf[3] >> 4);
                *humidity = (float)raw / 1048576.0f * 100.0f;
                return 0;
            } else {
                fprintf(stderr, "AHT20 busy (status=0x%02X), retry %d\n", status, attempt + 1);
                gpioDelay(I2C_RETRY_DELAY_US);
            }
        } else {
            fprintf(stderr, "AHT20 read failed, retry %d\n", attempt + 1);
            gpioDelay(I2C_RETRY_DELAY_US);
        }
    }
    return -1;
}

static void log_humidity(float humidity) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm_info);
    printf("[%s] Humidity: %.2f%%\n", ts, humidity);
    fflush(stdout);
}

static void control_dehumidifier(float humidity) {
    if (humidity > HUMIDITY_HIGH) {
        gpioWrite(DEHUMIDIFIER_GPIO, 1);
        printf("Dehumidifier ON (humidity %.2f%% > %.1f%%)\n", humidity, HUMIDITY_HIGH);
    } else if (humidity < HUMIDITY_LOW) {
        gpioWrite(DEHUMIDIFIER_GPIO, 0);
        printf("Dehumidifier OFF (humidity %.2f%% < %.1f%%)\n", humidity, HUMIDITY_LOW);
    }
}

static void cleanup(void) {
    if (g_gpio_initialized) {
        gpioWrite(DEHUMIDIFIER_GPIO, 0);
        gpioTerminate();
        g_gpio_initialized = 0;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    g_gpio_initialized = 1;

    gpioSetMode(DEHUMIDIFIER_GPIO, PI_OUTPUT);
    gpioWrite(DEHUMIDIFIER_GPIO, 0);

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        cleanup();
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, AHT20_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", AHT20_ADDR, strerror(errno));
        cleanup();
        return 1;
    }

    if (aht20_soft_reset() < 0) {
        fprintf(stderr, "AHT20 soft reset failed\n");
        cleanup();
        return 1;
    }

    if (aht20_calibrate() < 0) {
        fprintf(stderr, "AHT20 calibration failed\n");
        cleanup();
        return 1;
    }

    printf("AHT20 initialised and calibrated. Starting humidity monitoring...\n");

    while (g_running) {
        float humidity = 0.0f;
        if (aht20_read_humidity(&humidity) == 0) {
            log_humidity(humidity);
            control_dehumidifier(humidity);
        } else {
            fprintf(stderr, "Failed to read humidity after retries\n");
        }
        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

