#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <syslog.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <errno.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>

#define I2C_BUS "/dev/i2c-1"
#define HTU21D_ADDR 0x40
#define HTU21D_CMD_MEASURE_RH 0xE5
#define API_ENDPOINT "http://api.example.com/humidity"
#define API_KEY "your_api_key_here"
#define POLL_INTERVAL_SEC 60
#define MAX_RETRIES 3

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static int g_socket_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0x00;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int i2c_write_cmd(int fd, uint8_t cmd) {
    if (write(fd, &cmd, 1) != 1) {
        syslog(LOG_ERR, "I2C write failed: %s", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, int len) {
    int total = 0;
    while (total < len) {
        int n = read(fd, buf + total, len - total);
        if (n < 0) {
            if (errno == EINTR) continue;
            syslog(LOG_ERR, "I2C read failed: %s", strerror(errno));
            return -1;
        }
        if (n == 0) {
            syslog(LOG_ERR, "I2C read: unexpected EOF");
            return -1;
        }
        total += n;
    }
    return 0;
}

static int read_humidity(int fd, float *humidity) {
    uint8_t buf[3];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2c_write_cmd(fd, HTU21D_CMD_MEASURE_RH) < 0) {
            retries++;
            usleep(100000);
            continue;
        }

        usleep(10000);

        if (i2c_read_bytes(fd, buf, 3) < 0) {
            retries++;
            usleep(100000);
            continue;
        }

        if (crc8(buf, 2) != buf[2]) {
            syslog(LOG_ERR, "CRC mismatch on humidity data");
            retries++;
            usleep(100000);
            continue;
        }

        uint16_t raw = (buf[0] << 8) | buf[1];
        raw &= 0xFFFC;
        *humidity = -6.0f + 125.0f * (float)raw / 65536.0f;
        return 0;
    }

    syslog(LOG_ERR, "Failed to read humidity after %d retries", MAX_RETRIES);
    return -1;
}

static int create_socket(void) {
    int fd = socket(AF_INET, SOCK_STREAM, 0);
    if (fd < 0) {
        syslog(LOG_ERR, "Socket creation failed: %s", strerror(errno));
        return -1;
    }
    return fd;
}

static int connect_to_server(int fd, const char *host, int port) {
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_port = htons(port);

    if (inet_pton(AF_INET, host, &addr.sin_addr) <= 0) {
        syslog(LOG_ERR, "Invalid address: %s", host);
        return -1;
    }

    if (connect(fd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        syslog(LOG_ERR, "Connect failed: %s", strerror(errno));
        return -1;
    }
    return 0;
}

static int send_http_request(int fd, const char *json_data) {
    char request[512];
    int len = snprintf(request, sizeof(request),
        "POST /humidity HTTP/1.1\r\n"
        "Host: api.example.com\r\n"
        "Content-Type: application/json\r\n"
        "Content-Length: %zu\r\n"
        "Authorization: Bearer %s\r\n"
        "Connection: close\r\n"
        "\r\n"
        "%s",
        strlen(json_data), API_KEY, json_data);

    if (len < 0 || (size_t)len >= sizeof(request)) {
        syslog(LOG_ERR, "HTTP request buffer too small");
        return -1;
    }

    if (write(fd, request, len) != len) {
        syslog(LOG_ERR, "Failed to send HTTP request: %s", strerror(errno));
        return -1;
    }

    char response[1024];
    ssize_t bytes = read(fd, response, sizeof(response) - 1);
    if (bytes < 0) {
        syslog(LOG_ERR, "Failed to read HTTP response: %s", strerror(errno));
        return -1;
    }
    response[bytes] = '\0';

    if (strstr(response, "200 OK") == NULL) {
        syslog(LOG_ERR, "HTTP request failed: %s", response);
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    if (g_socket_fd >= 0) {
        close(g_socket_fd);
        g_socket_fd = -1;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    closelog();
}

int main(void) {
    openlog("humidity_monitor", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to set signal handlers: %s", strerror(errno));
        cleanup();
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus %s: %s", I2C_BUS, strerror(errno));
        cleanup();
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, HTU21D_ADDR) < 0) {
        syslog(LOG_ERR, "Failed to set I2C slave address 0x%02X: %s", HTU21D_ADDR, strerror(errno));
        cleanup();
        return 1;
    }

    syslog(LOG_INFO, "Humidity monitor started");

    while (g_running) {
        float humidity;
        if (read_humidity(g_i2c_fd, &humidity) == 0) {
            char json_data[128];
            snprintf(json_data, sizeof(json_data), "{\"humidity\": %.2f}", humidity);

            g_socket_fd = create_socket();
            if (g_socket_fd < 0) {
                syslog(LOG_ERR, "Failed to create socket");
            } else if (connect_to_server(g_socket_fd, "api.example.com", 80) < 0) {
                syslog(LOG_ERR, "Failed to connect to server");
            } else if (send_http_request(g_socket_fd, json_data) < 0) {
                syslog(LOG_ERR, "Failed to send HTTP request");
            } else {
                syslog(LOG_INFO, "Humidity: %.2f%%", humidity);
            }

            close(g_socket_fd);
            g_socket_fd = -1;
        } else {
            syslog(LOG_ERR, "Failed to read humidity from sensor");
        }

        for (int i = 0; i < POLL_INTERVAL_SEC && g_running; i++) {
            sleep(1);
        }
    }

    syslog(LOG_INFO, "Humidity monitor shutting down");
    cleanup();
    return 0;
}

