/*
 * BMP280 pressure monitor for Raspberry Pi 4 Model B
 * Uses pigpio for I2C communication.
 *
 * Build:  gcc -O2 -Wall -o bmp280_monitor bmp280_monitor.c -lpigpio -lrt
 * Run:    sudo ./bmp280_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- BMP280 constants (from datasheet) ---- */
#define BMP280_I2C_ADDR        0x76
#define BMP280_CHIP_ID_REG     0xD0
#define BMP280_CHIP_ID         0x58
#define BMP280_RESET_REG       0xE0
#define BMP280_RESET_CMD       0xB6
#define BMP280_CTRL_MEAS_REG   0xF4
#define BMP280_CONFIG_REG      0xF5
#define BMP280_PRESS_MSB_REG   0xF7
#define BMP280_TEMP_MSB_REG    0xFA
#define BMP280_CALIB_START     0x88
#define BMP280_CALIB_LEN       26

#define LOG_FILE               "pressure_log.txt"
#define PRESSURE_HIGH_HPA      1020.0f
#define PRESSURE_LOW_HPA       980.0f
#define SAMPLE_INTERVAL_US     2000000   /* 2 s */
#define CONVERSION_DELAY_US    10000     /* 10 ms */
#define MAX_RETRIES            3

/* ---- Calibration coefficients ---- */
typedef struct {
    uint16_t dig_T1;
    int16_t  dig_T2;
    int16_t  dig_T3;
    uint16_t dig_P1;
    int16_t  dig_P2;
    int16_t  dig_P3;
    int16_t  dig_P4;
    int16_t  dig_P5;
    int16_t  dig_P6;
    int16_t  dig_P7;
    int16_t  dig_P8;
    int16_t  dig_P9;
} bmp280_calib_t;

/* ---- Globals for cleanup ---- */
static int g_i2c_handle = -1;
static volatile sig_atomic_t g_running = 1;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Read calibration data from EEPROM ---- */
static int read_calibration(int handle, bmp280_calib_t *cal)
{
    uint8_t buf[BMP280_CALIB_LEN];
    if (i2cReadI2CBlockData(handle, BMP280_CALIB_START, (char *)buf, BMP280_CALIB_LEN) != BMP280_CALIB_LEN) {
        fprintf(stderr, "Error: failed to read calibration block\n");
        return -1;
    }

    cal->dig_T1 = (uint16_t)(buf[0]  | (buf[1]  << 8));
    cal->dig_T2 = (int16_t)(buf[2]  | (buf[3]  << 8));
    cal->dig_T3 = (int16_t)(buf[4]  | (buf[5]  << 8));
    cal->dig_P1 = (uint16_t)(buf[6]  | (buf[7]  << 8));
    cal->dig_P2 = (int16_t)(buf[8]  | (buf[9]  << 8));
    cal->dig_P3 = (int16_t)(buf[10] | (buf[11] << 8));
    cal->dig_P4 = (int16_t)(buf[12] | (buf[13] << 8));
    cal->dig_P5 = (int16_t)(buf[14] | (buf[15] << 8));
    cal->dig_P6 = (int16_t)(buf[16] | (buf[17] << 8));
    cal->dig_P7 = (int16_t)(buf[18] | (buf[19] << 8));
    cal->dig_P8 = (int16_t)(buf[20] | (buf[21] << 8));
    cal->dig_P9 = (int16_t)(buf[22] | (buf[23] << 8));
    return 0;
}

/* ---- Read raw temperature and pressure ---- */
static int read_raw(int handle, int32_t *raw_t, int32_t *raw_p)
{
    uint8_t buf[6];
    if (i2cReadI2CBlockData(handle, BMP280_PRESS_MSB_REG, (char *)buf, 6) != 6) {
        fprintf(stderr, "Error: failed to read pressure/temperature data\n");
        return -1;
    }
    *raw_p = (int32_t)(((uint32_t)buf[0] << 12) | ((uint32_t)buf[1] << 4) | ((uint32_t)buf[2] >> 4));
    *raw_t = (int32_t)(((uint32_t)buf[3] << 12) | ((uint32_t)buf[4] << 4) | ((uint32_t)buf[5] >> 4));
    return 0;
}

/* ---- Bosch compensation (32-bit integer math, per datasheet) ---- */
static int32_t compensate_temperature(int32_t raw_t, const bmp280_calib_t *cal, int32_t *t_fine)
{
    int32_t var1, var2;
    var1 = ((((raw_t >> 3) - ((int32_t)cal->dig_T1 << 1))) * ((int32_t)cal->dig_T2)) >> 11;
    var2 = (((((raw_t >> 4) - ((int32_t)cal->dig_T1)) * ((raw_t >> 4) - ((int32_t)cal->dig_T1))) >> 12) * ((int32_t)cal->dig_T3)) >> 14;
    *t_fine = var1 + var2;
    return (*t_fine * 5 + 128) >> 8;  /* centi-degrees Celsius */
}

static uint32_t compensate_pressure(int32_t raw_p, const bmp280_calib_t *cal, int32_t t_fine)
{
    int64_t var1, var2, p;
    var1 = ((int64_t)t_fine) - 128000;
    var2 = var1 * var1 * (int64_t)cal->dig_P6;
    var2 = var2 + ((var1 * (int64_t)cal->dig_P5) << 17);
    var2 = var2 + (((int64_t)cal->dig_P4) << 35);
    var1 = ((var1 * var1 * (int64_t)cal->dig_P3) >> 8) + ((var1 * (int64_t)cal->dig_P2) << 12);
    var1 = (((((int64_t)1) << 47) + var1)) * ((int64_t)cal->dig_P1) >> 33;
    if (var1 == 0) return 0;
    p = 1048576 - raw_p;
    p = (((p << 31) - var2) * 3125) / var1;
    var1 = (((int64_t)cal->dig_P9) * (p >> 13) * (p >> 13)) >> 25;
    var2 = (((int64_t)cal->dig_P8) * p) >> 19;
    p = ((p + var1 + var2) >> 8) + (((int64_t)cal->dig_P7) << 4);
    return (uint32_t)(p >> 8);  /* Pa */
}

/* ---- Log pressure to file ---- */
static void log_pressure(float pressure_hpa)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, %.2f hPa\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, pressure_hpa);
    fclose(fp);
}

/* ---- Cleanup helper ---- */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ---- Main ---- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at BMP280 address */
    g_i2c_handle = i2cOpen(1, BMP280_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (code %d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Verify chip ID */
    int chip_id = i2cReadByteData(g_i2c_handle, BMP280_CHIP_ID_REG);
    if (chip_id != BMP280_CHIP_ID) {
        fprintf(stderr, "Error: chip ID mismatch (got 0x%02X, expected 0x%02X)\n",
                chip_id & 0xFF, BMP280_CHIP_ID);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Soft reset */
    if (i2cWriteByteData(g_i2c_handle, BMP280_RESET_REG, BMP280_RESET_CMD) < 0) {
        fprintf(stderr, "Error: soft reset failed\n");
        cleanup();
        return EXIT_FAILURE;
