    }

    /* Configure: oversampling x1 for both, normal mode */
    if (i2cWriteByteData(g_i2c_handle, BMP280_CTRL_MEAS_REG, 0x27) < 0) {
        fprintf(stderr, "Error: writing CTRL_MEAS failed\n");
        cleanup();
