        int ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (read_raw(g_i2c_handle, &raw_t, &raw_p) == 0) {
                ok = 1;
                break;
            }
            fprintf(stderr, "Retry %d/%d...\n", attempt + 1, MAX_RETRIES);
            gpioDelay(100000);  /* 100 ms */
            if (attempt < MAX_RETRIES - 1) {
