code:
/*
 * Raspberry Pi 4B - TMP117 (Temperature), AHT20 (Humidity), PIR (Motion)
 * I2C: /dev/i2c-1 (TMP117 @ 0x48, AHT20 @ 0x38)
 * PIR: GPIO17 (gpiochip4 line 17, input)
 *
 * Build: gcc -o logger logger.c -lgpiod -lrt
 */
#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define TMP117_ADDR    0x48
#define AHT20_ADDR     0x38
#define PIR_CHIP       "gpiochip4"
#define PIR_LINE       17
#define LOG_DIR        "/var/log"
#define LOG_FILE_PREFIX "sensor_data"
#define SAMPLE_INTERVAL 1
#define I2C_RETRIES    3
#define I2C_RETRY_DELAY_MS 10

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void msleep(unsigned ms) {
    struct timespec ts = { ms / 1000, (long)(ms % 1000) * 1000000L };
    nanosleep(&ts, NULL);
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *out) {
    for (int attempt = 0; attempt < I2C_RETRIES; attempt++) {
        if (write(fd, &reg, 1) != 1) {
            fprintf(stderr, "I2C write reg 0x%02X failed (attempt %d): %s\n",
                    reg, attempt + 1, strerror(errno));
            msleep(I2C_RETRY_DELAY_MS);
            continue;
        }
        uint8_t buf[2];
        ssize_t n = read(fd, buf, 2);
        if (n != 2) {
            fprintf(stderr, "I2C read reg 0x%02X failed (attempt %d): got %zd bytes: %s\n",
                    reg, attempt + 1, n, n < 0 ? strerror(errno) : "short read");
            msleep(I2C_RETRY_DELAY_MS);
            continue;
        }
        *out = (int16_t)((buf[0] << 8) | buf[1]);
        return 0;
    }
    return -1;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    for (int attempt = 0; attempt < I2C_RETRIES; attempt++) {
        if (write(fd, buf, 2) == 2) return 0;
        fprintf(stderr, "I2C write reg 0x%02X val 0x%02X failed (attempt %d): %s\n",
                reg, val, attempt + 1, strerror(errno));
        msleep(I2C_RETRY_DELAY_MS);
    }
    return -1;
}

static int tmp117_read_temp(int fd, float *temp_c) {
    int16_t raw;
    if (i2c_read_reg16(fd, 0x00, &raw) != 0) return -1;
    *temp_c = (float)raw * 0.0078125f;
    return 0;
}

static int aht20_read_humidity(int fd, float *hum_pct) {
    uint8_t cmd = 0xAC;
    for (int attempt = 0; attempt < I2C_RETRIES; attempt++) {
        if (write(fd, &cmd, 1) != 1) {
            fprintf(stderr, "AHT20 trigger failed (attempt %d): %s\n",
                    attempt + 1, strerror(errno));
            msleep(I2C_RETRY_DELAY_MS);
            continue;
        }
        msleep(80);
        uint8_t status;
        if (read(fd, &status, 1) != 1) {
            fprintf(stderr, "AHT20 status read failed (attempt %d): %s\n",
                    attempt + 1, strerror(errno));
            msleep(I2C_RETRY_DELAY_MS);
            continue;
        }
        if ((status & 0x80) != 0) {
            fprintf(stderr, "AHT20 busy (attempt %d)\n", attempt + 1);
            msleep(100);
            continue;
        }
        uint8_t buf[8];
        if (read(fd, buf, 8) != 8) {
            fprintf(stderr, "AHT20 data read failed (attempt %d): %s\n",
                    attempt + 1, strerror(errno));
            msleep(I2C_RETRY_DELAY_MS);
            continue;
        }
        uint32_t raw = ((uint32_t)buf[3] << 12) | ((uint32_t)buf[4] << 4) | (buf[5] >> 4);
        *hum_pct = (float)raw / 1048576.0f * 100.0f;
        return 0;
    }
    return -1;
}

static void get_timestamp(char *buf, size_t len) {
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tm);
}

static void get_date_string(char *buf, size_t len) {
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    strftime(buf, len, "%Y-%m-%d", &tm);
}

static void get_log_filename(char *buf, size_t len, const char *date) {
    snprintf(buf, len, "%s/%s_%s.csv", LOG_DIR, LOG_FILE_PREFIX, date);
}

static int file_exists(const char *path) {
    return access(path, F_OK) == 0;
}

static int write_header_if_new(const char *filename) {
    if (file_exists(filename)) return 0;
    FILE *fp = fopen(filename, "w");
    if (!fp) {
        fprintf(stderr, "Cannot create %s: %s\n", filename, strerror(errno));
        return -1;
    }
    fprintf(fp, "Timestamp,Temperature(C),Humidity(%%),MotionDetected\n");
    fclose(fp);
    return 0;
}

static int log_data(const char *filename, float temp, float hum, int motion) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Cannot open %s: %s\n", filename, strerror(errno));
        return -1;
    }
    char ts[32];
    get_timestamp(ts, sizeof(ts));
    fprintf(fp, "%s,%.2f,%.2f,%d\n", ts, temp, hum, motion);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name(PIR_CHIP);
    if (!chip) {
        fprintf(stderr, "Cannot open %s: %s\n", PIR_CHIP, strerror(errno));
        return 1;
    }
    struct gpiod_line *pir_line = gpiod_chip_get_line(chip, PIR_LINE);
    if (!pir_line) {
        fprintf(stderr, "Cannot get line %d: %s\n", PIR_LINE, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_input(pir_line, "pir_logger") < 0) {
        fprintf(stderr, "Cannot request PIR line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        gpiod_line_release(pir_line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, TMP117_ADDR) < 0) {
        fprintf(stderr, "Cannot set TMP117 slave 0x%02X: %s\n", TMP117_ADDR, strerror(errno));
    }
    if (ioctl(i2c_fd, I2C_SLAVE, AHT20_ADDR) < 0) {
        fprintf(stderr, "Cannot set AHT20 slave 0x%02X: %s\n", AHT20_ADDR, strerror(errno));
    }

    char date_str[16];
    get_date_string(date_str, sizeof(date_str));
    char filename[256];
    get_log_filename(filename, sizeof(filename), date_str);

    if (write_header_if_new(filename) != 0) {
        close(i2c_fd);
        gpiod_line_release(pir_line);
        gpiod_chip_close(chip);
        return 1;
    }

    printf("Logging started. Press Ctrl+C to stop.\n");

    while (running) {
        float temp = 0.0f, hum = 0.0f;
        int motion = 0;
        int tmp_ok = 0, hum_ok = 0;

        if (ioctl(i2c_fd, I2C_SLAVE, TMP117_ADDR) >= 0) {
            if (tmp117_read_temp(i2c_fd, &temp) == 0) tmp_ok = 1;
            else fprintf(stderr, "TMP117 read failed\n");
        } else {
            fprintf(stderr, "Cannot set TMP117 slave: %s\n", strerror(errno));
        }

        if (ioctl(i2c_fd, I2C_SLAVE, AHT20_ADDR) >= 0) {
            if (aht20_read_humidity(i2c_fd, &hum) == 0) hum_ok = 1;
            else fprintf(stderr, "AHT20 read failed\n");
        } else {
            fprintf(stderr, "Cannot set AHT20 slave: %s\n", strerror(errno));
        }

        motion = gpiod_line_get_value(pir_line);
        if (motion < 0) {
            fprintf(stderr, "PIR read failed: %s\n", strerror(errno));
            motion = 0;
        }

        if (tmp_ok && hum_ok) {
            if (log_data(filename, temp, hum, motion) != 0) {
                fprintf(stderr, "Logging failed\n");
            }
        } else {
            fprintf(stderr, "Sensor read error; skipping log entry\n");
        }

        msleep(SAMPLE_INTERVAL * 1000);
    }

    printf("\nShutting down...\n");
    close(i2c_fd);
    gpiod_line_release(pir_line);
    gpiod_chip_close(chip);
    return 0;
}

