        return 1;
    }

    printf("Logging started. Press Ctrl+C to stop.\n");

    while (running) {
        float temp = 0.0f, hum = 0.0f;
        int motion = 0;
        int tmp_ok = 0, hum_ok = 0;

        if (ioctl(i2c_fd, I2C_SLAVE, TMP117_ADDR) >= 0) {
            if (tmp117_read_temp(i2c_fd, &temp) == 0) tmp_ok = 1;
            else fprintf(stderr, "TMP117 read failed\n");
        } else {
            fprintf(stderr, "Cannot set TMP117 slave: %s\n", strerror(errno));
        }

        if (ioctl(i2c_fd, I2C_SLAVE, AHT20_ADDR) >= 0) {
            if (aht20_read_humidity(i2c_fd, &hum) == 0) hum_ok = 1;
            else fprintf(stderr, "AHT20 read failed\n");
        } else {
            fprintf(stderr, "Cannot set AHT20 slave: %s\n", strerror(errno));
        }

        motion = gpiod_line_get_value(pir_line);
        if (motion < 0) {
            fprintf(stderr, "PIR read failed: %s\n", strerror(errno));
            motion = 0;
        }

        if (tmp_ok && hum_ok) {
            if (log_data(filename, temp, hum, motion) != 0) {
                fprintf(stderr, "Logging failed\n");
            }
        } else {
            fprintf(stderr, "Sensor read error; skipping log entry\n");
        }

        msleep(SAMPLE_INTERVAL * 1000);
