#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RAIN_SENSOR_GPIO 17
#define MOTOR_ENABLE_GPIO 22
#define MOTOR_INPUT_1_GPIO 23
#define MOTOR_INPUT_2_GPIO 24

#define MOTOR_RUN_TIME_SEC 5
#define POLL_INTERVAL_SEC 2

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] %s\n", timestamp, message);
    fflush(stdout);
}

static int safe_set_mode(unsigned gpio, unsigned mode) {
    if (gpioSetMode(gpio, mode) != 0) {
        char msg[128];
        snprintf(msg, sizeof(msg), "Error: gpioSetMode failed for GPIO %u", gpio);
        log_event(msg);
        return -1;
    }
    return 0;
}

static int safe_write(unsigned gpio, unsigned level) {
    if (gpioWrite(gpio, level) != 0) {
        char msg[128];
        snprintf(msg, sizeof(msg), "Error: gpioWrite failed for GPIO %u", gpio);
        log_event(msg);
        return -1;
    }
    return 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        log_event("Error: pigpio initialisation failed");
        return -1;
    }

    if (safe_set_mode(RAIN_SENSOR_GPIO, PI_INPUT) != 0) return -1;
    if (safe_set_mode(MOTOR_ENABLE_GPIO, PI_OUTPUT) != 0) return -1;
    if (safe_set_mode(MOTOR_INPUT_1_GPIO, PI_OUTPUT) != 0) return -1;
    if (safe_set_mode(MOTOR_INPUT_2_GPIO, PI_OUTPUT) != 0) return -1;

    if (safe_write(MOTOR_ENABLE_GPIO, 0) != 0) return -1;
    if (safe_write(MOTOR_INPUT_1_GPIO, 0) != 0) return -1;
    if (safe_write(MOTOR_INPUT_2_GPIO, 0) != 0) return -1;

    log_event("GPIO initialization complete");
    return 0;
}

static void cleanup_gpio(void) {
    safe_write(MOTOR_INPUT_1_GPIO, 0);
    safe_write(MOTOR_INPUT_2_GPIO, 0);
    safe_write(MOTOR_ENABLE_GPIO, 0);
    gpioTerminate();
    log_event("GPIO cleanup complete");
}

static int read_rain_sensor(void) {
    int value = gpioRead(RAIN_SENSOR_GPIO);
    if (value < 0) {
        log_event("Error: gpioRead failed for rain sensor");
        return -1;
    }
    return value;
}

static int close_window(void) {
    log_event("Closing window...");

    if (safe_write(MOTOR_INPUT_1_GPIO, 1) != 0) return -1;
    if (safe_write(MOTOR_INPUT_2_GPIO, 0) != 0) return -1;
    if (safe_write(MOTOR_ENABLE_GPIO, 1) != 0) return -1;

    for (int elapsed = 0; elapsed < MOTOR_RUN_TIME_SEC && g_running; elapsed++) {
        sleep(1);
    }

    if (safe_write(MOTOR_ENABLE_GPIO, 0) != 0) return -1;
    if (safe_write(MOTOR_INPUT_1_GPIO, 0) != 0) return -1;
    if (safe_write(MOTOR_INPUT_2_GPIO, 0) != 0) return -1;

    log_event("Window closed");
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    log_event("Program started");

    while (g_running) {
        int rain_detected = read_rain_sensor();
        if (rain_detected < 0) {
            log_event("Error reading rain sensor, retrying...");
        } else if (rain_detected == 0) {
            log_event("Rain detected, closing window...");
            if (close_window() != 0) {
                log_event("Error closing window");
            }
        }
        sleep(POLL_INTERVAL_SEC);
    }

    log_event("Program terminating...");
    cleanup_gpio();
    return EXIT_SUCCESS;
}

