#include <errno.h>
#include <pigpio.h>

#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27
#define SAMPLE_INTERVAL_US 500000  /* 500 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int read_cpu_load(float *load)
{
    FILE *fp = fopen("/proc/stat", "r");
    if (!fp) {
        fprintf(stderr, "Error opening /proc/stat: %s\n", strerror(errno));
        return -1;
    }

    unsigned long long user, nice, system, idle, iowait, irq, softirq, steal, guest, guest_nice;
    unsigned long long prev_user, prev_nice, prev_system, prev_idle, prev_iowait,
                       prev_irq, prev_softirq, prev_steal, prev_guest, prev_guest_nice;

    if (fscanf(fp, "cpu  %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
               &prev_user, &prev_nice, &prev_system, &prev_idle, &prev_iowait,
               &prev_irq, &prev_softirq, &prev_steal, &prev_guest, &prev_guest_nice) != 10) {
        fprintf(stderr, "Error reading /proc/stat\n");
        fclose(fp);
        return -1;
    }
    fclose(fp);

    usleep(100000); /* 100 ms */

    fp = fopen("/proc/stat", "r");
    if (!fp) {
        fprintf(stderr, "Error opening /proc/stat: %s\n", strerror(errno));
        return -1;
    }

    if (fscanf(fp, "cpu  %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
               &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal, &guest, &guest_nice) != 10) {
        fprintf(stderr, "Error reading /proc/stat\n");
        fclose(fp);
        return -1;
    }
    fclose(fp);

    unsigned long long prev_total = prev_user + prev_nice + prev_system + prev_idle + prev_iowait + prev_irq + prev_softirq + prev_steal + prev_guest + prev_guest_nice;
    unsigned long long total = user + nice + system + idle + iowait + irq + softirq + steal + guest + guest_nice;

    if (prev_total == 0 || total == 0) {
        *load = 0.0f;
    } else {
        unsigned long long prev_non_idle = prev_user + prev_nice + prev_system + prev_irq + prev_softirq;
        unsigned long long prev_total_non_idle = prev_user + prev_nice + prev_system + prev_irq + prev_softirq;
        unsigned long long total_non_idle = user + nice + system + irq + softirq;
        unsigned long long total_idle = idle + iowait;

        unsigned long long prev_idle_total = prev_idle + prev_iowait;
        unsigned long long idle_total = idle + iowait;

        unsigned long long total_diff = total - prev_total;
        unsigned long long idle_diff = idle_total - prev_idle_total;

        if (total_diff > 0) {
            *load = (float)(total_diff - idle_diff) / (float)total_diff * 100.0f;
        } else {
            *load = 0.0f;
        }
    }

    if (*load < 0.0f) *load = 0.0f;
    if (*load > 100.0f) *load = 100.0f;

    return 0;
}

static void map_load_to_color(float load, int *r, int *g, int *b)
{
    if (load <= 50.0f) {
        *r = (int)(255.0f * (load / 50.0f));
        *g = 255;
        *b = 0;
    } else {
        *r = 255;
        *g = (int)(255.0f * (1.0f - (load - 50.0f) / 50.0f));
        *b = 0;
    }
}

static int set_led_color(int r, int g, int b)
{
    int ret = 0;
    if (gpioPWM(RED_PIN, r) < 0) {
        fprintf(stderr, "Error setting red PWM: %s\n", pigpio_error(gpioGetMode(RED_PIN)));
        ret = -1;
    }
    if (gpioPWM(GREEN_PIN, g) < 0) {
        fprintf(stderr, "Error setting green PWM: %s\n", pigpio_error(gpioGetMode(GREEN_PIN)));
        ret = -1;
    }
    if (gpioPWM(BLUE_PIN, b) < 0) {
        fprintf(stderr, "Error setting blue PWM: %s\n", pigpio_error(gpioGetMode(BLUE_PIN)));
        ret = -1;
    }
    return ret;
}

static void led_off(void)
{
    gpioPWM(RED_PIN, 0);
    gpioPWM(GREEN_PIN, 0);
    gpioPWM(BLUE_PIN, 0);
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(RED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting red pin mode: %s\n", pigpio_error(gpioGetMode(RED_PIN)));
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(GREEN_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting green pin mode: %s\n", pigpio_error(gpioGetMode(GREEN_PIN)));
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(BLUE_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting blue pin mode: %s\n", pigpio_error(gpioGetMode(BLUE_PIN)));
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    while (g_running) {
        float load;
        if (read_cpu_load(&load) == 0) {
            int r, g, b;
            map_load_to_color(load, &r, &g, &b);
            if (set_led_color(r, g, b) < 0) {
                fprintf(stderr, "Error setting LED color\n");
            }
        } else {
            fprintf(stderr, "Error reading CPU load\n");
        }
        usleep(SAMPLE_INTERVAL_US);
    }

    led_off();
    gpioTerminate();
    return 0;
}

