/*
 * BMP280 I2C reader + UDP transmitter for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   BMP280 SDA  -> GPIO2 (pin 3, I2C1 SDA)
 *   BMP280 SCL  -> GPIO3 (pin 5, I2C1 SCL)
 *   BMP280 VDD  -> 3.3 V
 *   BMP280 GND  -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o bmp280_udp bmp280_udp.c -lpigpio -lrt
 *   (pigpio requires root or gpio group membership.)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

/* ---- BMP280 constants (datasheet) ---- */
#define BMP280_I2C_ADDR        0x76
#define BMP280_REG_ID          0xD0
#define BMP280_REG_RESET       0xE0
#define BMP280_REG_CTRL_MEAS   0xF4
#define BMP280_REG_CONFIG      0xF5
#define BMP280_REG_PRESS_MSB   0xF7
#define BMP280_REG_TEMP_MSB    0xFA
#define BMP280_REG_CALIB_00    0x88
#define BMP280_CHIP_ID         0x58
#define BMP280_RESET_CMD       0xB6

/* ---- Configuration ---- */
#define I2C_BUS               1
#define UDP_IP                "192.168.1.100"
#define UDP_PORT              5000
#define SAMPLE_INTERVAL_S     5
#define MAX_RETRIES           10

/* ---- Calibration coefficients ---- */
typedef struct {
    uint16_t dig_T1;
    int16_t  dig_T2;
    int16_t  dig_T3;
    uint16_t dig_P1;
    int16_t  dig_P2;
    int16_t  dig_P3;
    int16_t  dig_P4;
    int16_t  dig_P5;
    int16_t  dig_P6;
    int16_t  dig_P7;
    int16_t  dig_P8;
    int16_t  dig_P9;
} bmp280_calib_t;

/* ---- Globals for cleanup ---- */
static int      g_i2c_handle = -1;
static int      g_udp_socket = -1;
static volatile sig_atomic_t g_running = 1;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Read a block of bytes from the BMP280 ---- */
static int bmp280_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len)
{
    if (i2cWriteByte(handle, reg) < 0)
        return -1;
    if (i2cReadDevice(handle, (char *)buf, len) != (int)len)
        return -1;
    return 0;
}

/* ---- Write a single byte to the BMP280 ---- */
static int bmp280_write_byte(int handle, uint8_t reg, uint8_t val)
{
    if (i2cWriteByteData(handle, reg, val) < 0)
        return -1;
    return 0;
}

/* ---- Read the BMP280 calibration coefficients ---- */
static int bmp280_read_calibration(int handle, bmp280_calib_t *cal)
{
    uint8_t buf[24];
    if (bmp280_read_block(handle, BMP280_REG_CALIB_00, buf, sizeof(buf)) != 0)
        return -1;

    cal->dig_T1 = (uint16_t)((buf[1]  << 8) | buf[0]);
    cal->dig_T2 = (int16_t) ((buf[3]  << 8) | buf[2]);
    cal->dig_T3 = (int16_t) ((buf[5]  << 8) | buf[4]);
    cal->dig_P1 = (uint16_t)((buf[7]  << 8) | buf[6]);
    cal->dig_P2 = (int16_t) ((buf[9]  << 8) | buf[8]);
    cal->dig_P3 = (int16_t) ((buf[11] << 8) | buf[10]);
    cal->dig_P4 = (int16_t) ((buf[13] << 8) | buf[12]);
    cal->dig_P5 = (int16_t) ((buf[15] << 8) | buf[14]);
    cal->dig_P6 = (int16_t) ((buf[17] << 8) | buf[16]);
    cal->dig_P7 = (int16_t) ((buf[19] << 8) | buf[18]);
    cal->dig_P8 = (int16_t) ((buf[21] << 8) | buf[20]);
    cal->dig_P9 = (int16_t) ((buf[23] << 8) | buf[22]);
    return 0;
}

/* ---- Initialize the BMP280 ---- */
static int bmp280_init(int handle, bmp280_calib_t *cal)
{
    uint8_t chip_id;
    if (bmp280_read_block(handle, BMP280_REG_ID, &chip_id, 1) != 0) {
        fprintf(stderr, "Error: cannot read chip ID (sensor absent or bus error).\n");
        return -1;
    }
    if (chip_id != BMP280_CHIP_ID) {
        fprintf(stderr, "Error: chip ID 0x%02X does not match expected 0x%02X (BMP280).\n",
                chip_id, BMP280_CHIP_ID);
        return -1;
    }

    if (bmp280_write_byte(handle, BMP280_REG_RESET, BMP280_RESET_CMD) != 0) {
        fprintf(stderr, "Error: failed to reset BMP280.\n");
        return -1;
    }
    gpioDelay(2000); /* 2 ms reset wait */

    if (bmp280_read_calibration(handle, cal) != 0) {
        fprintf(stderr, "Error: failed to read calibration data.\n");
        return -1;
    }

    /* config: t_sb=500ms(0x05<<5), filter=4(0x02<<2), spi3w_en=0 */
    if (bmp280_write_byte(handle, BMP280_REG_CONFIG, (0x05 << 5) | (0x02 << 2)) != 0) {
        fprintf(stderr, "Error: failed to write config register.\n");
        return -1;
    }

    /* ctrl_meas: osrs_t=x1(0x01<<5), osrs_p=x1(0x01<<2), mode=normal(0x03) */
    if (bmp280_write_byte(handle, BMP280_REG_CTRL_MEAS, (0x01 << 5) | (0x01 << 2) | 0x03) != 0) {
        fprintf(stderr, "Error: failed to write ctrl_meas register.\n");
        return -1;
    }

    return 0;
}

/* ---- Read raw temperature and pressure (MSB, LSB, XLSB) ---- */
static int bmp280_read_raw(int handle, int32_t *raw_t, int32_t *raw_p)
{
    uint8_t buf[6];
    if (bmp280_read_block(handle, BMP280_REG_PRESS_MSB, buf, 6) != 0)
        return -1;

    *raw_p = ((int32_t)buf[0] << 12) | ((int32_t)buf[1] << 4) | (buf[2] >> 4);
    *raw_t = ((int32_t)buf[3] << 12) | ((int32_t)buf[4] << 4) | (buf[5] >> 4);
    return 0;
}

/* ---- Compensate temperature (datasheet formula) ---- */
static double bmp280_compensate_temp(int32_t raw_t, const bmp280_calib_t *cal, int32_t *t_fine)
{
    int32_t var1, var2;
    var1 = ((((raw_t >> 3) - ((int32_t)cal->dig_T1 << 1))) * ((int32_t)cal->dig_T2)) >> 11;
    var2 = (((((raw_t >> 4) - ((int32_t)cal->dig_T1)) * ((raw_t >> 4) - ((int32_t)cal->dig_T1))) >> 12) *
            ((int32_t)cal->dig_T3)) >> 14;
    *t_fine = var1 + var2;
    return (*t_fine * 5 + 128) >> 8; /* centi-degrees Celsius */
}

/* ---- Compensate pressure (datasheet formula) ---- */
static double bmp280_compensate_press(int32_t raw_p, int32_t t_fine, const bmp280_calib_t *cal)
{
    int64_t var1, var2, p;
    var1 = ((int64_t)t_fine) - 128000;
    var2 = var1 * var1 * (int64_t)cal->dig_P6;
    var2 = var2 + ((var1 * (int64_t)cal->dig_P5) << 17);
    var2 = var2 + (((int64_t)cal->dig_P4) << 35);
    var1 = ((var1 * var1 * (int64_t)cal->dig_P3) >> 8) + ((var1 * (int64_t)cal->dig_P2) << 12);
    var1 = (((((int64_t)1) << 47) + var1)) * ((int64_t)cal->dig_P1) >> 33;

    if (var1 == 0) return 0.0; /* avoid division-by-zero */

    p = 1048576 - raw_p;
    p = (((p << 31) - var2) * 3125) / var1;
    var1 = (((int64_t)cal->dig_P9) * (p >> 13) * (p >> 13)) >> 25;
    var2 = (((int64_t)cal->dig_P8) * p) >> 19;
    p = ((p + var1 + var2) >> 8) + (((int64_t)cal->dig_P7) << 4);
    return (double)p / 256.0; /* Pa */
}

/* ---- Format data into a JSON string ---- */
static void format_json(double temp_c, double press_pa, char *out, size_t out_len)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S%z", t);
    snprintf(out, out_len,
             "{\"timestamp\":\"%s\",\"temperature\":%.2f,\"pressure\":%.2f}",
             ts, temp_c, press_pa);
}

/* ---- Send JSON via UDP ---- */
static int send_udp(const char *json, const char *ip, int port)
{
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_port = htons(port);
    if (inet_pton(AF_INET, ip, &addr.sin_addr) <= 0) {
        fprintf(stderr, "Error: invalid UDP address '%s'.\n", ip);
        return -1;
    }

    if (sendto(g_udp_socket, json, strlen(json), 0,
               (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        fprintf(stderr, "Error: UDP sendto failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- Cleanup helper ---- */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_udp_socket >= 0) {
        close(g_udp_socket);
        g_udp_socket = -1;
    }
    gpioTerminate();
}

int main(void)
{
    bmp280_calib_t cal;
    int32_t raw_t, raw_p, t_fine;
    double temp_c, press_pa;
    char json[256];

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, BMP280_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d).\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize BMP280 */
    if (bmp280_init(g_i2c_handle, &cal) != 0) {
        fprintf(stderr, "Error: BMP280 initialisation failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Create UDP socket */
    g_udp_socket = socket(AF_INET, SOCK_DGRAM, 0);
    if (g_udp_socket < 0) {
        fprintf(stderr, "Error: socket creation failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("BMP280 ready. Sampling every %d s. Press Ctrl+C to stop.\n",
           SAMPLE_INTERVAL_S);

    while (g_running) {
        int ok = 0;
        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (bmp280_read_raw(g_i2c_handle, &raw_t, &raw_p) == 0) {
                ok = 1;
                break;
            }
            gpioDelay(200000); /* 200 ms between retries */
        }

        if (!ok) {
            fprintf(stderr, "Error: failed to read BMP280 after %d attempts.\n",
                    MAX_RETRIES);
            break;
        }

        temp_c = bmp280_compensate_temp(raw_t, &cal, &t_fine) / 100.0;
        press_pa = bmp280_compensate_press(raw_p, t_fine, &cal);

        format_json(temp_c, press_pa, json, sizeof(json));

        if (send_udp(json, UDP_IP, UDP_PORT) != 0) {
            fprintf(stderr, "Warning: UDP send failed (continuing).\n");
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_S * 10 && g_running; i++)
            gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

