#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define SPI_FLAGS 0
#define FAN_GPIO 18
#define PWM_FREQUENCY 1000
#define PWM_RANGE 255
#define BUFFER_SIZE 20
#define READ_INTERVAL_US 1000000

#define TEMP_THRESHOLD_1 25.0
#define TEMP_THRESHOLD_2 40.0
#define TEMP_THRESHOLD_3 60.0

#define DUTY_CYCLE_1 0
#define DUTY_CYCLE_2 128
#define DUTY_CYCLE_3 200
#define DUTY_CYCLE_4 255

#define MAX31855_FAULT_BIT 0x01
#define MAX31855_SCV_BIT 0x02
#define MAX31855_SCC_BIT 0x04
#define MAX31855_OC_BIT 0x08
#define MAX31855_REF_JUNCTION_FAULT_BIT 0x10

typedef struct {
    time_t timestamp;
    float temperature;
    int duty_cycle;
} DataPoint;

typedef struct {
    DataPoint buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static CircularBuffer data_buffer;

static void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

static void init_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

static void add_to_buffer(CircularBuffer *cb, time_t timestamp, float temperature, int duty_cycle) {
    cb->buffer[cb->head].timestamp = timestamp;
    cb->buffer[cb->head].temperature = temperature;
    cb->buffer[cb->head].duty_cycle = duty_cycle;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

static void print_buffer(const CircularBuffer *cb) {
    printf("\n--- Data Buffer Contents ---\n");
    int start = (cb->count == BUFFER_SIZE) ? cb->head : 0;
    for (int i = 0; i < cb->count; i++) {
        int index = (start + i) % BUFFER_SIZE;
        char time_str[32];
        struct tm *tm_info = localtime(&cb->buffer[index].timestamp);
        if (tm_info != NULL) {
            strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);
        } else {
            strncpy(time_str, "UNKNOWN", sizeof(time_str));
        }
        printf("Timestamp: %s, Temperature: %.2f C, Duty Cycle: %d\n",
               time_str, cb->buffer[index].temperature, cb->buffer[index].duty_cycle);
    }
    printf("--- End of Data Buffer ---\n\n");
}

static int read_max31855(float *temperature) {
    char tx_buf[4] = {0, 0, 0, 0};
    char rx_buf[4] = {0, 0, 0, 0};

    if (spiXfer(spi_handle, tx_buf, rx_buf, 4) != 4) {
        fprintf(stderr, "Error: SPI transfer failed.\n");
        return -1;
    }

    uint32_t raw = ((uint32_t)(uint8_t)rx_buf[0] << 24) |
                   ((uint32_t)(uint8_t)rx_buf[1] << 16) |
                   ((uint32_t)(uint8_t)rx_buf[2] << 8)  |
                   ((uint32_t)(uint8_t)rx_buf[3]);

    if (raw & MAX31855_FAULT_BIT) {
        fprintf(stderr, "Error: MAX31855 fault detected (raw=0x%08X).\n", raw);
        if (raw & MAX31855_SCV_BIT) fprintf(stderr, "  Short to VCC\n");
        if (raw & MAX31855_SCC_BIT) fprintf(stderr, "  Short to GND\n");
        if (raw & MAX31855_OC_BIT)  fprintf(stderr, "  Open circuit\n");
        if (raw & MAX31855_REF_JUNCTION_FAULT_BIT) fprintf(stderr, "  Reference junction fault\n");
        return -1;
    }

    int16_t thermocouple_data = (int16_t)((raw >> 18) & 0x3FFF);
    if (thermocouple_data & 0x2000) {
        thermocouple_data |= 0xC000;
    }

    *temperature = thermocouple_data * 0.25f;
    return 0;
}

static int calculate_duty_cycle(float temperature) {
    if (temperature < TEMP_THRESHOLD_1) {
        return DUTY_CYCLE_1;
    } else if (temperature < TEMP_THRESHOLD_2) {
        return DUTY_CYCLE_2;
    } else if (temperature < TEMP_THRESHOLD_3) {
        return DUTY_CYCLE_3;
    } else {
        return DUTY_CYCLE_4;
    }
}

static void control_fan(int duty_cycle) {
    if (gpioPWM(FAN_GPIO, duty_cycle) != 0) {
        fprintf(stderr, "Error: Failed to set PWM duty cycle to %d.\n", duty_cycle);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle=%d).\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output.\n", FAN_GPIO);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: Failed to set PWM frequency on GPIO %d.\n", FAN_GPIO);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(FAN_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: Failed to set PWM range on GPIO %d.\n", FAN_GPIO);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioPWM(FAN_GPIO, 0) != 0) {
        fprintf(stderr, "Error: Failed to initialize PWM to 0 on GPIO %d.\n", FAN_GPIO);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    init_circular_buffer(&data_buffer);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to register SIGINT handler.\n");
    }

    printf("Temperature monitoring and fan control started. Press Ctrl+C to exit.\n");

    while (running) {
        float temperature;
        if (read_max31855(&temperature) == 0) {
            int duty_cycle = calculate_duty_cycle(temperature);
            control_fan(duty_cycle);
            add_to_buffer(&data_buffer, time(NULL), temperature, duty_cycle);
            printf("Temperature: %.2f C, Duty Cycle: %d\n", temperature, duty_cycle);
        } else {
            fprintf(stderr, "Error: Failed to read temperature. Skipping fan update.\n");
        }
        gpioDelay(READ_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    gpioPWM(FAN_GPIO, 0);
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    print_buffer(&data_buffer);
    return EXIT_SUCCESS;
}

