#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define LOG_FILE "rtd_log.csv"
#define READ_INTERVAL 5

#define MAX31865_CONFIG_REG 0x00
#define MAX31865_RTD_MSB_REG 0x01
#define MAX31865_RTD_LSB_REG 0x02
#define MAX31865_FAULT_REG 0x03

#define RTD_A 0.0039083
#define RTD_B -0.0000005775
#define RTD_R0 1000.0
#define RTD_RREF 4300.0

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_transfer(uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0
    };
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        return -1;
    }
    return 0;
}

static int read_register(uint8_t reg, uint8_t *value) {
    uint8_t tx[2] = { (uint8_t)(reg | 0x80), 0x00 };
    uint8_t rx[2] = { 0 };
    if (spi_transfer(tx, rx, 2) < 0) {
        return -1;
    }
    *value = rx[1];
    return 0;
}

static int write_register(uint8_t reg, uint8_t value) {
    uint8_t tx[2] = { (uint8_t)(reg & 0x7F), value };
    uint8_t rx[2] = { 0 };
    return spi_transfer(tx, rx, 2);
}

static int read_rtd_data(uint16_t *rtd_data) {
    uint8_t msb, lsb;
    if (read_register(MAX31865_RTD_MSB_REG, &msb) < 0) return -1;
    if (read_register(MAX31865_RTD_LSB_REG, &lsb) < 0) return -1;
    *rtd_data = ((uint16_t)msb << 8) | lsb;
    return 0;
}

static int check_fault() {
    uint8_t fault;
    if (read_register(MAX31865_FAULT_REG, &fault) < 0) return -1;
    if (fault & 0x01) {
        fprintf(stderr, "MAX31865 fault detected: 0x%02X\n", fault);
        return -1;
    }
    return 0;
}

static double calculate_temperature(uint16_t rtd_data) {
    if (rtd_data & 0x6000) {
        return -999.0;
    }
    uint16_t rtd_value = rtd_data & 0x0FFF;
    double rtd_resistance = (double)rtd_value * RTD_RREF / 32768.0;
    double temp = -45.0 + (rtd_resistance / RTD_R0) * (1.0 + RTD_A + RTD_B * (rtd_resistance / RTD_R0));
    return temp;
}

static void log_temperature(double temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s,%.2f\n", timestamp, temperature);
    fflush(log_file);
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    uint8_t mode = SPI_MODE_0;
    uint8_t bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return 1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        return 1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &(uint32_t){SPI_SPEED}) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        return 1;
    }

    if (write_register(MAX31865_CONFIG_REG, 0x40) < 0) {
        fprintf(stderr, "Failed to configure MAX31865\n");
        close(spi_fd);
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(spi_fd);
        return 1;
    }

    while (running) {
        uint16_t rtd_data;
        if (read_rtd_data(&rtd_data) < 0) {
