        perror("Failed to set SPI bits per word");
        close(spi_fd);
        return 1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &(uint32_t){SPI_SPEED}) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        return 1;
    }

    if (write_register(MAX31865_CONFIG_REG, 0x40) < 0) {
        fprintf(stderr, "Failed to configure MAX31865\n");
        close(spi_fd);
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(spi_fd);
        return 1;
    }

    while (running) {
        uint16_t rtd_data;
        if (read_rtd_data(&rtd_data) < 0) {
