    if (i2c_read_reg(fd, BME280_REG_ID, &id, 1) < 0 || id != BME280_CHIP_ID) {
        fprintf(stderr, "BME280 not found (id=0x%02X)\n", id); close(fd); return 1;
    }

    if (i2c_write_reg(fd, BME280_REG_RESET, BME280_RESET_CMD) < 0) {
        perror("reset"); close(fd); return 1;
    }
    usleep(2000);

    uint8_t status;
    for (int i = 0; i < 10; i++) {
        if (i2c_read_reg(fd, BME280_REG_STATUS, &status, 1) < 0) { close(fd); return 1; }
        if (!(status & 0x01)) break;
        usleep(2000);
    }

    bme280_calib_t cal;
    if (read_calibration(fd, &cal) < 0) {
        perror("calibration"); close(fd); return 1;
    }

    if (i2c_write_reg(fd, BME280_REG_CTRL_HUM, 0x01) < 0) {
        perror("ctrl_hum"); close(fd); return 1;
    }
    if (i2c_write_reg(fd, BME280_REG_CONFIG, 0xA0) < 0) {
        perror("config"); close(fd); return 1;
    }
    if (i2c_write_reg(fd, BME280_REG_CTRL_MEAS, 0x27) < 0) {
        perror("ctrl_meas"); close(fd); return 1;
    }

    while (running) {
        double t, h, p;
        if (read_bme280(fd, &cal, &t, &h, &p) == 0) {
            time_t now = time(NULL);
            struct tm *tm = localtime(&now);
            char ts[20];
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
            if (log_data(ts, t, h, p) == 0) {
                printf("%s, T=%.2f C, H=%.2f %%, P=%.2f hPa\n", ts, t, h, p);
            } else {
                perror("log");
            }
        } else {
            perror("read_bme280");
        }
        for (int i = 0; i < 5 && running; i++) sleep(1);
    }

    close(fd);
    return 0;
}

