#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>

#define BMP180_ADDR 0x77
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE
#define BMP180_OSS 3
#define ALERT_GPIO 24
#define BUFFER_SIZE 120
#define SAMPLE_INTERVAL_MS 50
#define DEVIATION_THRESHOLD 5.0

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

typedef struct {
    time_t timestamp;
    float pressure;
} PressureReading;

static PressureReading pressure_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;

static int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
static uint16_t ac4, ac5, ac6;

static int read_calibration_data() {
    char data[22];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_CAL_AC1, data, 22) != 22) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }
    ac1 = (data[0] << 8) | data[1];
    ac2 = (data[2] << 8) | data[3];
    ac3 = (data[4] << 8) | data[5];
    ac4 = (data[6] << 8) | data[7];
    ac5 = (data[8] << 8) | data[9];
    ac6 = (data[10] << 8) | data[11];
    b1 = (data[12] << 8) | data[13];
    b2 = (data[14] << 8) | data[15];
    mb = (data[16] << 8) | data[17];
    mc = (data[18] << 8) | data[19];
    md = (data[20] << 8) | data[21];
    return 0;
}

static int read_raw_temperature() {
    char data[2];
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, 0x2E) < 0) {
        fprintf(stderr, "Error writing temperature request\n");
        return -1;
    }
    gpioDelay(5000);
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, data, 2) != 2) {
        fprintf(stderr, "Error reading raw temperature\n");
        return -1;
    }
    return (data[0] << 8) | data[1];
}

static int read_raw_pressure() {
    char data[3];
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, 0x34 + (BMP180_OSS << 6)) < 0) {
        fprintf(stderr, "Error writing pressure request\n");
        return -1;
    }
    gpioDelay(2000 + (3000 << BMP180_OSS));
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, data, 3) != 3) {
        fprintf(stderr, "Error reading raw pressure\n");
        return -1;
    }
    return ((data[0] << 16) | (data[1] << 8) | data[2]) >> (8 - BMP180_OSS);
}

static float calculate_pressure(int ut, int up) {
    long x1, x2, x3, b3, b5, b6, p;
    unsigned long b4, b7;
    x1 = ((long)ut - ac6) * ac5 >> 15;
    x2 = ((long)mc << 11) / (x1 + md);
    b5 = x1 + x2;
    b6 = b5 - 4000;
    x1 = (b2 * (b6 * b6 >> 12)) >> 11;
    x2 = (ac2 * b6) >> 11;
    x3 = x1 + x2;
    b3 = (((((long)ac1) * 4 + x3) << BMP180_OSS) + 2) >> 2;
    x1 = (ac3 * b6) >> 13;
    x2 = (b1 * (b6 * b6 >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    b4 = (ac4 * (unsigned long)(x3 + 32768)) >> 15;
    b7 = ((unsigned long)up - b3) * (50000 >> BMP180_OSS);
    if (b7 < 0x80000000) {
        p = (b7 * 2) / b4;
    } else {
        p = (b7 / b4) * 2;
    }
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p = p + ((x1 + x2 + 3791) >> 4);
    return (float)p / 100.0;
}

static void add_reading(float pressure) {
    time_t now = time(NULL);
    pressure_buffer[buffer_index].timestamp = now;
    pressure_buffer[buffer_index].pressure = pressure;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) buffer_count++;
}

static float calculate_average_pressure() {
    if (buffer_count == 0) return 0.0;
    float sum = 0.0;
    for (int i = 0; i < buffer_count; i++) sum += pressure_buffer[i].pressure;
    return sum / buffer_count;
}

static void check_pressure_deviation(float current_pressure) {
    float average_pressure = calculate_average_pressure();
    if (fabs(current_pressure - average_pressure) > DEVIATION_THRESHOLD) {
        fprintf(stderr, "Pressure deviation detected: %.2f hPa (avg: %.2f hPa)\n", current_pressure, average_pressure);
        gpioWrite(ALERT_GPIO, 1);
        gpioDelay(1000000);
        gpioWrite(ALERT_GPIO, 0);
    }
}

static void timer_callback(void *userdata) {
    (void)userdata;
    int ut = read_raw_temperature();
    if (ut < 0) {
        fprintf(stderr, "Error reading temperature\n");
        return;
    }
    int up = read_raw_pressure();
    if (up < 0) {
        fprintf(stderr, "Error reading pressure\n");
        return;
    }
    float pressure = calculate_pressure(ut, up);
    add_reading(pressure);
    check_pressure_deviation(pressure);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (read_calibration_data() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioSetMode(ALERT_GPIO, PI_OUTPUT);
    gpioWrite(ALERT_GPIO, 0);
    if (gpioSetTimerFuncEx(0, SAMPLE_INTERVAL_MS, timer_callback, NULL) < 0) {
        fprintf(stderr, "Error setting timer\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    signal(SIGINT, signal_handler);
    while (running) {
        gpioDelay(100000);
    }
    gpioSetTimerFuncEx(0, SAMPLE_INTERVAL_MS, NULL, NULL);
    gpioWrite(ALERT_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

