/*
 * BMP280 weather logger for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   BMP280 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   BMP280 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   BMP280 VDD  -> 3.3 V
 *   BMP280 GND  -> GND
 *   BMP280 SDO  -> GND  (I2C address 0x76)
 *   BMP280 SDO  -> VDD (I2C address 0x77)
 *
 * Build:  gcc -O2 -Wall -Wextra -o bmp280_logger bmp280_logger.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define BMP280_ADDR_1  0x76
#define BMP280_ADDR_2  0x77

#define BMP280_REG_ID          0xD0
#define BMP280_REG_RESET       0xE0
#define BMP280_REG_STATUS      0xF3
#define BMP280_REG_CTRL_MEAS   0xF4
#define BMP280_REG_CONFIG      0xF5
#define BMP280_REG_PRESS_MSB   0xF7
#define BMP280_REG_TEMP_MSB    0xFA
#define BMP280_REG_CALIB_00    0x88
#define BMP280_REG_CALIB_26    0xE1

#define BMP280_CHIP_ID         0x58
#define BMP280_RESET_CMD       0xB6

#define LOG_FILE "weather_data.txt"
#define SAMPLE_INTERVAL_S 5

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

struct bmp280_calib {
    uint16_t dig_T1;
    int16_t  dig_T2;
    int16_t  dig_T3;
    uint16_t dig_P1;
    int16_t  dig_P2;
    int16_t  dig_P3;
    int16_t  dig_P4;
    int16_t  dig_P5;
    int16_t  dig_P6;
    int16_t  dig_P7;
    int16_t  dig_P8;
    int16_t  dig_P9;
};

struct bmp280_calib g_calib;

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_write_reg(0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "i2c_read_reg(0x%02X, %zu): got %zd (%s)\n",
                reg, len, n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }
    return 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_write_reg(0x%02X, 0x%02X): %s\n",
                reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int bmp280_read_calibration(int fd)
{
    uint8_t c1[24];
    if (i2c_read_reg(fd, BMP280_REG_CALIB_00, c1, sizeof(c1)) != 0)
        return -1;

    g_calib.dig_T1 = (uint16_t)(c1[0]  | (c1[1]  << 8));
    g_calib.dig_T2 = (int16_t)(c1[2]  | (c1[3]  << 8));
    g_calib.dig_T3 = (int16_t)(c1[4]  | (c1[5]  << 8));
    g_calib.dig_P1 = (uint16_t)(c1[6]  | (c1[7]  << 8));
    g_calib.dig_P2 = (int16_t)(c1[8]  | (c1[9]  << 8));
    g_calib.dig_P3 = (int16_t)(c1[10] | (c1[11] << 8));
    g_calib.dig_P4 = (int16_t)(c1[12] | (c1[13] << 8));
    g_calib.dig_P5 = (int16_t)(c1[14] | (c1[15] << 8));
    g_calib.dig_P6 = (int16_t)(c1[16] | (c1[17] << 8));
    g_calib.dig_P7 = (int16_t)(c1[18] | (c1[19] << 8));
    g_calib.dig_P8 = (int16_t)(c1[20] | (c1[21] << 8));
    g_calib.dig_P9 = (int16_t)(c1[22] | (c1[23] << 8));

    return 0;
}

static int bmp280_init(int fd)
{
    uint8_t id;
    if (i2c_read_reg(fd, BMP280_REG_ID, &id, 1) != 0)
        return -1;
    if (id != BMP280_CHIP_ID) {
        fprintf(stderr, "BMP280 chip ID mismatch: got 0x%02X, expected 0x%02X\n",
                id, BMP280_CHIP_ID);
        return -1;
    }

    if (i2c_write_reg(fd, BMP280_REG_RESET, BMP280_RESET_CMD) != 0)
        return -1;
    usleep(2000);

    uint8_t status;
    for (int i = 0; i < 10; i++) {
        if (i2c_read_reg(fd, BMP280_REG_STATUS, &status, 1) != 0)
            return -1;
        if ((status & 0x01) == 0)
            break;
        usleep(2000);
    }
    if (status & 0x01) {
        fprintf(stderr, "BMP280 reset timeout\n");
        return -1;
    }

    if (bmp280_read_calibration(fd) != 0)
        return -1;

