/*
 * LM75 Temperature Monitor with Alert LED
 * Board:  Raspberry Pi 4 Model B
 * Bus:    I2C bus 1 (GPIO2=SDA, GPIO3=SCL)
 * Sensor: LM75 at 0x48 (ADDR pin tied to GND)
 * LED:    GPIO18 (BCM), active-high
 *
 * Build:  gcc -O2 -Wall -Wextra -o lm75_monitor lm75_monitor.c -lpigpio -lpthread
 * Run:    sudo ./lm75_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

