#define I2C_BUS              1
#define LM75_ADDR            0x48          /* ADDR pin tied to GND */
#define LM75_TEMP_REG        0x00          /* Temperature result register */
#define LM75_TEMP_REG_SIZE   2             /* 16-bit big-endian two's-complement */
#define LM75_TEMP_SCALE      0.0625f       /* 1 LSB = 1/16 °C */

#define ALERT_GPIO           18            /* BCM 18 */
#define ALERT_THRESHOLD      28.0f         /* °C */
#define BUFFER_SIZE          60
#define SAMPLE_PERIOD_US     1000000       /* 1 second */
#define INIT_RETRIES         3
#define INIT_RETRY_DELAY_US  500000        /* 0.5 s */

/* ----------------------------- Data Structures --------------------------- */
typedef struct {
    float buffer[BUFFER_SIZE];
    int   head;
    int   count;
    pthread_mutex_t mutex;
} CircularBuffer;

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd = -1;
static CircularBuffer g_temp_buf;

/* ----------------------------- Prototypes -------------------------------- */
static int  init_i2c(void);
static int  read_temperature(float *out_temp);
static void buffer_add(CircularBuffer *cb, float temp);
static float buffer_average(const CircularBuffer *cb);
static void *alert_thread_fn(void *arg);
static void signal_handler(int sig);
static void cleanup(void);

/* ----------------------------- I2C Init ---------------------------------- */
static int init_i2c(void) {
    if (g_i2c_fd >= 0) {
        i2cClose(g_i2c_fd);
        g_i2c_fd = -1;
    }

    for (int attempt = 1; attempt <= INIT_RETRIES; ++attempt) {
        g_i2c_fd = i2cOpen(I2C_BUS, LM75_ADDR, 0);
        if (g_i2c_fd >= 0) {
            fprintf(stderr, "[I2C] Bus %d, addr 0x%02X opened (fd=%d).\n",
                    I2C_BUS, LM75_ADDR, g_i2c_fd);
            return 0;
        }

        fprintf(stderr, "[I2C] i2cOpen failed (attempt %d/%d): %s\n",
                attempt, INIT_RETRIES, strerror(errno));

        if (attempt < INIT_RETRIES) {
            usleep(INIT_RETRY_DELAY_US);
        }
    }

    fprintf(stderr, "[I2C] Failed to open I2C after %d attempts.\n", INIT_RETRIES);
    return -1;
}

/* ----------------------------- Temperature Read --------------------------- */
static int read_temperature(float *out_temp) {
    if (g_i2c_fd < 0) {
        return -1;
    }

    char reg = (char)LM75_TEMP_REG;
    if (i2cWriteDevice(g_i2c_fd, &reg, 1) != 0) {
        fprintf(stderr, "[I2C] Write pointer to 0x%02X failed: %s\n",
