    if (n != LM75_TEMP_REG_SIZE) {
        fprintf(stderr, "[I2C] Read from 0x%02X failed: got %d bytes, expected %d: %s\n",
                LM75_TEMP_REG, n, LM75_TEMP_REG_SIZE, strerror(errno));
        return -1;
    }

    /* LM75: 16-bit big-endian two's-complement, 1/16 °C resolution */
    int16_t raw = (int16_t)(((uint8_t)data[0] << 8) | (uint8_t)data[1]);
    *out_temp = (float)raw * LM75_TEMP_SCALE;
    return 0;
}

