    if (n > 0) {
        for (int i = 0; i < n; ++i) {
            sum += cb->buffer[i];
        }
        pthread_mutex_unlock(&cb->mutex);
        return sum / (float)n;
    }
    pthread_mutex_unlock(&cb->mutex);
    return 0.0f;
}

