static void *alert_thread_fn(void *arg) {
    (void)arg;
    while (g_running) {
        float avg = buffer_average(&g_temp_buf);
        int level = (avg > ALERT_THRESHOLD) ? 1 : 0;

        if (gpioWrite(ALERT_GPIO, level) != 0) {
            fprintf(stderr, "[GPIO] gpioWrite(%d, %d) failed: %s\n",
                    ALERT_GPIO, level, strerror(errno));
        }

        usleep(SAMPLE_PERIOD_US);
    }
    return NULL;
}

/* ----------------------------- Signal Handler ----------------------------- */
static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* ----------------------------- Cleanup ------------------------------------ */
static void cleanup(void) {
    if (g_i2c_fd >= 0) {
        i2cClose(g_i2c_fd);
        g_i2c_fd = -1;
    }
    gpioWrite(ALERT_GPIO, 0);
    gpioSetMode(ALERT_GPIO, PI_INPUT);
    pthread_mutex_destroy(&g_temp_buf.mutex);
    gpioTerminate();
}

/* ----------------------------- Main --------------------------------------- */
int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Configure alert GPIO */
    if (gpioSetMode(ALERT_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "[FATAL] gpioSetMode(%d, OUTPUT) failed: %s\n",
                ALERT_GPIO, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(ALERT_GPIO, 0);

    /* Initialize I2C */
    if (init_i2c() != 0) {
        fprintf(stderr, "[FATAL] I2C initialization failed.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize circular buffer */
    memset(&g_temp_buf, 0, sizeof(g_temp_buf));
    if (pthread_mutex_init(&g_temp_buf.mutex, NULL) != 0) {
        fprintf(stderr, "[FATAL] pthread_mutex_init failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* Launch alert thread */
    pthread_t alert_thread;
    if (pthread_create(&alert_thread, NULL, alert_thread_fn, NULL) != 0) {
        fprintf(stderr, "[FATAL] pthread_create failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    fprintf(stderr, "[INFO] LM75 monitor running. Ctrl+C to exit.\n");

    /* Main sampling loop */
    while (g_running) {
        float temp;
        if (read_temperature(&temp) == 0) {
            buffer_add(&g_temp_buf, temp);
            printf("Temperature: %.2f °C | Avg: %.2f °C\n",
