#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <math.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define SPI_FLAGS 0
#define PWM_GPIO 18
#define PWM_FREQUENCY 1000
#define PWM_RANGE 1000
#define MAX_TEMP 80.0
#define SAMPLE_INTERVAL_MS 100
#define RTD_A 0.0039083
#define RTD_R0 100.0
#define RTD_R_REF 430.0
#define CONFIG_FILE "config.json"

typedef struct {
    double kp;
    double ki;
    double kd;
    double target_temp;
} Config;

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static Config config = {1.0, 0.1, 0.01, 25.0};
static double integral = 0.0;
static double previous_error = 0.0;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

double read_rtd(void) {
    char tx[4] = {0x01, 0x00, 0x00, 0x00};
    char rx[4] = {0};
    if (spiXfer(spi_handle, tx, rx, 4) != 4) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1.0;
    }
    if (rx[3] & 0x01) {
        fprintf(stderr, "MAX31865 fault detected\n");
        return -1.0;
    }
    int32_t raw = ((int32_t)(rx[0] & 0xFF) << 24) |
                  ((int32_t)(rx[1] & 0xFF) << 16) |
                  ((int32_t)(rx[2] & 0xFF) << 8) |
                  ((int32_t)(rx[3] & 0xFF));
    if (raw & 0x00010000) {
        fprintf(stderr, "RTD open circuit or short to GND\n");
        return -1.0;
    }
    int16_t rtd_raw = (int16_t)(raw >> 16);
    double rtd_resistance = (double)rtd_raw * RTD_R_REF / 32768.0;
    if (rtd_resistance < 0.0) return -1.0;
    double temp = (rtd_resistance / RTD_R0 - 1.0) / RTD_A;
    return temp;
}

double pid_control(double current_temp) {
    double error = config.target_temp - current_temp;
    integral += error * (SAMPLE_INTERVAL_MS / 1000.0);
    double derivative = (error - previous_error) / (SAMPLE_INTERVAL_MS / 1000.0);
    double output = config.kp * error + config.ki * integral + config.kd * derivative;
    previous_error = error;
    if (output < 0.0) output = 0.0;
    if (output > 100.0) output = 100.0;
    return output;
}

void set_pwm(double duty_cycle) {
    if (duty_cycle < 0.0) duty_cycle = 0.0;
    if (duty_cycle > 100.0) duty_cycle = 100.0;
    int pwm_value = (int)(duty_cycle * PWM_RANGE / 100.0);
    gpioPWM(PWM_GPIO, pwm_value);
}

void load_config(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Warning: Could not open config file %s, using defaults\n", filename);
        return;
    }
    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        char *key = strtok(line, ":");
        char *value = strtok(NULL, "\n");
        if (!key || !value) continue;
        key[strcspn(key, " \t")] = 0;
        value[strcspn(value, " \t")] = 0;
        if (strcmp(key, "kp") == 0) config.kp = atof(value);
        else if (strcmp(key, "ki") == 0) config.ki = atof(value);
        else if (strcmp(key, "kd") == 0) config.kd = atof(value);
        else if (strcmp(key, "target_temp") == 0) config.target_temp = atof(value);
    }
    fclose(fp);
    printf("Config loaded: Kp=%.3f, Ki=%.3f, Kd=%.3f, Target=%.1f\n",
           config.kp, config.ki, config.kd, config.target_temp);
}

void cleanup(void) {
    set_pwm(0.0);
    if (spi_handle >= 0) spiClose(spi_handle);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }
    gpioSetMode(PWM_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(PWM_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(PWM_GPIO, PWM_RANGE);
    load_config(CONFIG_FILE);
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    printf("Starting PID loop. Press Ctrl+C to exit.\n");
    while (running) {
        double temp = read_rtd();
        if (temp < 0.0) {
            fprintf(stderr, "Error reading temperature, exiting\n");
            break;
        }
        if (temp > MAX_TEMP) {
            fprintf(stderr, "Over-temperature fault: %.2f > %.2f, exiting\n", temp, MAX_TEMP);
            break;
        }
        double pid_output = pid_control(temp);
        set_pwm(pid_output);
        printf("Temp: %.2f C, PID: %.2f, Duty: %.1f%%\n", temp, pid_output, pid_output);
        gpioDelay(SAMPLE_INTERVAL_MS * 1000);
    }
    cleanup();
    return 0;
}

