#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define BMP180_ADDR 0x77
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "breach_log.txt"
#define SAMPLE_INTERVAL_SEC 1
#define MAX_RETRIES 3

#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

#define BMP180_OSS 3

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, 2) != 2) return -1;
    *val = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int i2c_read_reg24(int fd, uint8_t reg, int32_t *val) {
    uint8_t buf[3];
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, 3) != 3) return -1;
    *val = ((int32_t)buf[0] << 16) | ((int32_t)buf[1] << 8) | buf[2];
    return 0;
}

static int read_calibration_data(int fd, int16_t *ac1, int16_t *ac2, int16_t *ac3,
                                 uint16_t *ac4, uint16_t *ac5, uint16_t *ac6,
                                 int16_t *b1, int16_t *b2, int16_t *mb,
                                 int16_t *mc, int16_t *md) {
    if (i2c_read_reg16(fd, BMP180_REG_CAL_AC1, ac1) < 0) return -1;
    if (i2c_read_reg16(fd, BMP180_REG_CAL_AC2, ac2) < 0) return -1;
    if (i2c_read_reg16(fd, BMP180_REG_CAL_AC3, ac3) < 0) return -1;
    if (i2c_read_reg16(fd, BMP180_REG_CAL_AC4, (int16_t *)ac4) < 0) return -1;
    if (i2c_read_reg16(fd, BMP180_REG_CAL_AC5, (int16_t *)ac5) < 0) return -1;
    if (i2c_read_reg16(fd, BMP180_REG_CAL_AC6, (int16_t *)ac6) < 0) return -1;
    if (i2c_read_reg16(fd, BMP180_REG_CAL_B1, b1) < 0) return -1;
    if (i2c_read_reg16(fd, BMP180_REG_CAL_B2, b2) < 0) return -1;
    if (i2c_read_reg16(fd, BMP180_REG_CAL_MB, mb) < 0) return -1;
    if (i2c_read_reg16(fd, BMP180_REG_CAL_MC, mc) < 0) return -1;
    if (i2c_read_reg16(fd, BMP180_REG_CAL_MD, md) < 0) return -1;
    return 0;
}

static int read_raw_temperature(int fd, int32_t *ut) {
    if (i2c_write_reg8(fd, BMP180_REG_CONTROL, 0x2E) < 0) return -1;
    usleep(5000);
    return i2c_read_reg16(fd, BMP180_REG_MSB, (int16_t *)ut);
}

static int read_raw_pressure(int fd, int32_t *up) {
    if (i2c_write_reg8(fd, BMP180_REG_CONTROL, 0x34 + (BMP180_OSS << 6)) < 0) return -1;
    usleep(2000 + (3000 << BMP180_OSS));
    return i2c_read_reg24(fd, BMP180_REG_MSB, up);
}

static int32_t compute_b5(int32_t ut, int16_t ac6, int16_t ac5, int16_t mc, int16_t md) {
    int32_t x1 = ((ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + (int32_t)md);
    return x1 + x2;
}

static int32_t compute_temperature(int32_t b5) {
    return (b5 + 8) >> 4;
}

static uint32_t compute_pressure(int32_t up, int32_t b5, int16_t ac1, int16_t ac2,
                                 int16_t ac3, uint16_t ac4, uint16_t ac5,
                                 uint16_t ac6, int16_t b1, int16_t b2,
                                 int16_t mb, int16_t mc, int16_t md) {
    int32_t b6 = b5 - 4000;
    int32_t x1 = ((int32_t)b2 * ((b6 * b6) >> 12)) >> 11;
    int32_t x2 = ((int32_t)ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)ac1) * 4 + x3) << BMP180_OSS) + 2) >> 2;
    x1 = ((int32_t)ac3 * b6) >> 13;
    x2 = ((int32_t)b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = ((uint32_t)ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> BMP180_OSS);
    int32_t p;
    if (b7 < 0x80000000) {
        p = (b7 * 2) / b4;
    } else {
        p = (b7 / b4) * 2;
    }
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p = p + ((x1 + x2 + 3791) >> 4);
    return p;
}

static void log_breach(float temperature, float pressure) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s - Temperature: %.2f C, Pressure: %.2f hPa\n", timestamp, temperature, pressure);
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to set up signal handlers");
        return 1;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, BMP180_ADDR) < 0) {
        perror("Failed to acquire I2C bus access");
        close(fd);
        return 1;
    }

    int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
    uint16_t ac4, ac5, ac6;
    if (read_calibration_data(fd, &ac1, &ac2, &ac3, &ac4, &ac5, &ac6, &b1, &b2, &mb, &mc, &md) < 0) {
        fprintf(stderr, "Failed to read BMP180 calibration data\n");
        close(fd);
        return 1;
    }

    printf("Monitoring BMP180 sensor on %s (addr 0x%02X)...\n", I2C_BUS, BMP180_ADDR);

    while (running) {
        int32_t ut, up;
        int retries = 0;
        int success = 0;

        while (retries < MAX_RETRIES && running) {
            if (read_raw_temperature(fd, &ut) == 0 && read_raw_pressure(fd, &up) == 0) {
                success = 1;
                break;
            }
            retries++;
            if (retries < MAX_RETRIES) {
                fprintf(stderr, "I2C read failed (attempt %d/%d), retrying...\n", retries, MAX_RETRIES);
                usleep(100000);
            }
        }

        if (!success) {
            fprintf(stderr, "Failed to read sensor data after %d attempts\n", MAX_RETRIES);
            close(fd);
            fd = open(I2C_BUS, O_RDWR);
            if (fd < 0) {
                perror("Failed to reopen I2C bus");
                return 1;
            }
            if (ioctl(fd, I2C_SLAVE, BMP180_ADDR) < 0) {
                perror("Failed to re-acquire I2C bus access");
                close(fd);
                return 1;
            }
            continue;
        }

        int32_t b5 = compute_b5(ut, ac6, ac5, mc, md);
        int32_t temperature = compute_temperature(b5);
        uint32_t pressure = compute_pressure(up, b5, ac1, ac2, ac3, ac4, ac5, ac6, b1, b2, mb, mc, md);

        float temp_c = temperature / 10.0f;
        float press_hpa = pressure / 100.0f;

        printf("Temperature: %.2f C, Pressure: %.2f hPa\n", temp_c, press_hpa);

        if (temp_c > 30.0f || press_hpa < 950.0f) {
            log_breach(temp_c, press_hpa);
        }

        for (int i = 0; i < SAMPLE_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    printf("\nExiting gracefully...\n");
    close(fd);
    return 0;
}

