/*
 * BMP180 temperature & pressure logger with fan control.
 *
 * Board:  Raspberry Pi 4 Model B
 * Bus:    I2C bus 1 (GPIO2 = SDA, GPIO3 = SCL)
 * Sensor: BMP180 at 0x77
 * Fan:    GPIO18 (active-high)
 *
 * Build:  gcc -O2 -Wall -Wextra -o bmp180_fan bmp180_fan.c -lpigpio -lrt
 * Run:    sudo ./bmp180_fan
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- BMP180 constants (datasheet) ---- */
#define BMP180_ADDR             0x77
#define BMP180_REG_CAL_START    0xAA   /* 22 bytes: AC1..MD */
#define BMP180_REG_CONTROL      0xF4
#define BMP180_REG_DATA         0xF6
#define BMP180_CMD_TEMP         0x2E
#define BMP180_CMD_PRESS_OSS0   0x34   /* OSS = 0 */
#define BMP180_TEMP_CONV_US    4500   /* max conversion time */
#define BMP180_PRESS_CONV_US   4500   /* OSS=0: 4.5 ms; rounded */
#define BMP180_OSS             0

/* ---- Application constants ---- */
#define FAN_GPIO                18
#define TEMP_THRESHOLD_C        30.0f
#define BUFFER_SIZE             60
#define SAMPLE_PERIOD_US        500000 /* 500 ms */
#define I2C_BUS                 1

/* ---- Data structures ---- */
typedef struct {
    int16_t  ac1, ac2, ac3, b1, b2, mb, mc, md;
    uint16_t ac4, ac5, ac6;
} bmp180_cal_t;

typedef struct {
    time_t timestamp;
    float  temperature;
    float  pressure;
} sensor_data_t;

typedef struct {
    sensor_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

/* ---- Globals ---- */
static int            g_i2c_handle = -1;
static bmp180_cal_t   g_cal;
static volatile sig_atomic_t g_running = 1;

/* ---- Prototypes ---- */
static int  bmp180_read_calibration(int handle, bmp180_cal_t *cal);
static int  bmp180_read_raw_temp(int handle, int32_t *ut);
static int  bmp180_read_raw_press(int handle, int32_t *up);
static int  bmp180_read_temp(int handle, const bmp180_cal_t *cal, float *temp);
static int  bmp180_read_pressure(int handle, const bmp180_cal_t *cal, float *press);
static void timer_callback(void *user_data);
static void add_to_buffer(circular_buffer_t *buf, float temp, float press);
static void print_buffer(const circular_buffer_t *buf);
static void control_fan(float temp);
static void cleanup(void);
static void signal_handler(int sig);

/* ---- BMP180 helpers ---- */

/* Read the 22-byte calibration table from the BMP180. */
static int bmp180_read_calibration(int handle, bmp180_cal_t *cal)
{
    uint8_t buf[22];
    if (i2cReadI2CBlockData(handle, BMP180_REG_CAL_START, (char *)buf, 22) != 22) {
        fprintf(stderr, "Error: failed to read BMP180 calibration block\n");
        return -1;
    }

    cal->ac1 = (int16_t)((buf[0]  << 8) | buf[1]);
    cal->ac2 = (int16_t)((buf[2]  << 8) | buf[3]);
    cal->ac3 = (int16_t)((buf[4]  << 8) | buf[5]);
    cal->ac4 = (uint16_t)((buf[6]  << 8) | buf[7]);
    cal->ac5 = (uint16_t)((buf[8]  << 8) | buf[9]);
    cal->ac6 = (uint16_t)((buf[10] << 8) | buf[11]);
    cal->b1  = (int16_t)((buf[12] << 8) | buf[13]);
    cal->b2  = (int16_t)((buf[14] << 8) | buf[15]);
    cal->mb  = (int16_t)((buf[16] << 8) | buf[17]);
    cal->mc  = (int16_t)((buf[18] << 8) | buf[19]);
    cal->md  = (int16_t)((buf[20] << 8) | buf[21]);

    /* Sanity-check: AC1 should never be 0 or 0xFFFF on a real BMP180. */
    if (cal->ac1 == 0 || cal->ac1 == (int16_t)0xFFFF) {
        fprintf(stderr, "Error: BMP180 calibration data invalid (AC1=0x%04X)\n",
                (uint16_t)cal->ac1);
        return -1;
    }
    return 0;
}

/* Read uncompensated temperature (UT). */
static int bmp180_read_raw_temp(int handle, int32_t *ut)
{
    uint8_t cmd = BMP180_CMD_TEMP;
    if (i2cWriteI2CBlockData(handle, BMP180_REG_CONTROL, (char *)&cmd, 1) != 1) {
        fprintf(stderr, "Error: failed to write temp command\n");
        return -1;
    }
    gpioDelay(BMP180_TEMP_CONV_US);

    uint8_t buf[2];
    if (i2cReadI2CBlockData(handle, BMP180_REG_DATA, (char *)buf, 2) != 2) {
        fprintf(stderr, "Error: failed to read raw temperature\n");
        return -1;
    }
    *ut = (int32_t)((buf[0] << 8) | buf[1]);
    return 0;
}

/* Read uncompensated pressure (UP) for OSS=0. */
static int bmp180_read_raw_press(int handle, int32_t *up)
{
    uint8_t cmd = BMP180_CMD_PRESS_OSS0;
    if (i2cWriteI2CBlockData(handle, BMP180_REG_CONTROL, (char *)&cmd, 1) != 1) {
        fprintf(stderr, "Error: failed to write pressure command\n");
        return -1;
    }
    gpioDelay(BMP180_PRESS_CONV_US);

    uint8_t buf[3];
    if (i2cReadI2CBlockData(handle, BMP180_REG_DATA, (char *)buf, 3) != 3) {
        fprintf(stderr, "Error: failed to read raw pressure\n");
        return -1;
    }
    *up = ((int32_t)buf[0] << 16 | (int32_t)buf[1] << 8 | buf[2]) >> (8 - BMP180_OSS);
    return 0;
}

/* Compute compensated temperature (°C). */
static int bmp180_read_temp(int handle, const bmp180_cal_t *cal, float *temp)
{
    int32_t ut;
    if (bmp180_read_raw_temp(handle, &ut) != 0)
        return -1;

    int32_t x1 = ((ut - (int32_t)cal->ac6) * (int32_t)cal->ac5) >> 15;
    int32_t x2 = ((int32_t)cal->mc << 11) / (x1 + (int32_t)cal->md);
    int32_t b5 = x1 + x2;
    *temp = ((b5 + 8) >> 4) / 10.0f;
    return 0;
}

/* Compute compensated pressure (Pa). */
static int bmp180_read_pressure(int handle, const bmp180_cal_t *cal, float *press)
{
    int32_t ut, up;
    if (bmp180_read_raw_temp(handle, &ut) != 0)
        return -1;
    if (bmp180_read_raw_press(handle, &up) != 0)
        return -1;

    int32_t x1 = ((ut - (int32_t)cal->ac6) * (int32_t)cal->ac5) >> 15;
    int32_t x2 = ((int32_t)cal->mc << 11) / (x1 + (int32_t)cal->md);
    int32_t b5 = x1 + x2;

    int32_t b6 = b5 - 4000;
    x1 = ((int32_t)cal->b2 * ((b6 * b6) >> 12)) >> 11;
    x2 = ((int32_t)cal->ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)cal->ac1 * 4 + x3) << BMP180_OSS) + 2) >> 2);

    x1 = ((int32_t)cal->ac3 * b6) >> 13;
    x2 = ((int32_t)cal->b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = ((uint32_t)cal->ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> BMP180_OSS);

    int32_t p;
    if (b7 < 0x80000000UL)
        p = (b7 * 2) / b4;
    else
        p = (b7 / b4) * 2;

    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p += (x1 + x2 + 3791) >> 4;

    *press = (float)p;
    return 0;
}

/* ---- Application helpers ---- */

static void add_to_buffer(circular_buffer_t *buf, float temp, float press)
{
    buf->data[buf->head].timestamp  = time(NULL);
    buf->data[buf->head].temperature = temp;
    buf->data[buf->head].pressure   = press;
    buf->head = (buf->head + 1) % BUFFER_SIZE;
    if (buf->count < BUFFER_SIZE)
        buf->count++;
}

static void print_buffer(const circular_buffer_t *buf)
{
    printf("\n--- Circular Buffer Contents (%d entries) ---\n", buf->count);
    int start = (buf->count == BUFFER_SIZE) ? buf->head : 0;
    for (int i = 0; i < buf->count; i++) {
        int idx = (start + i) % BUFFER_SIZE;
        struct tm *tm = localtime(&buf->data[idx].timestamp);
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
        printf("[%s] Temp: %.2f C, Pressure: %.2f Pa\n",
               ts, buf->data[idx].temperature, buf->data[idx].pressure);
    }
    printf("---------------------------------------------\n");
}

static void control_fan(float temp)
{
    if (temp > TEMP_THRESHOLD_C) {
        gpioWrite(FAN_GPIO, 1);
        printf("Fan ON  (Temp: %.2f C > %.1f C)\n", temp, TEMP_THRESHOLD_C);
    } else {
        gpioWrite(FAN_GPIO, 0);
        printf("Fan OFF (Temp: %.2f C <= %.1f C)\n", temp, TEMP_THRESHOLD_C);
    }
}

static void timer_callback(void *user_data)
{
    (void)user_data;
    float temp = 0.0f, press = 0.0f;

    if (bmp180_read_temp(g_i2c_handle, &g_cal, &temp) != 0) {
        fprintf(stderr, "Timer: temperature read failed\n");
        return;
    }
    if (bmp180_read_pressure(g_i2c_handle, &g_cal, &press) != 0) {
        fprintf(stderr, "Timer: pressure read failed\n");
        return;
    }

    add_to_buffer((circular_buffer_t *)user_data, temp, press);
    control_fan(temp);
    printf("Temp: %.2f C, Pressure: %.2f Pa\n", temp, press);
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(FAN_GPIO, 0);
    gpioTerminate();
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Main ---- */
int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, BMP180_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (bmp180_read_calibration(g_i2c_handle, &g_cal) != 0) {
        fprintf(stderr, "Error: BMP180 calibration read failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output\n", FAN_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(FAN_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    circular_buffer_t buf = {0};
    if (gpioSetTimerFuncEx(0, SAMPLE_PERIOD_US, timer_callback, &buf) != 0) {
        fprintf(stderr, "Error: failed to set timer callback\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("BMP180 fan controller running. Press Ctrl+C to exit.\n");

    while (g_running)
        gpioDelay(100000); /* 100 ms */

    gpioSetTimerFuncEx(0, 0, NULL, NULL); /* cancel timer */
    cleanup();
    return EXIT_SUCCESS;
}

