/* Read uncompensated pressure (UP) for OSS=0. */
static int bmp180_read_raw_press(int handle, int32_t *up)
{
    uint8_t cmd = BMP180_CMD_PRESS_OSS0;
    if (i2cWriteI2CBlockData(handle, BMP180_REG_CONTROL, (char *)&cmd, 1) != 1) {
        fprintf(stderr, "Error: failed to write pressure command\n");
        return -1;
    }
    gpioDelay(BMP180_PRESS_CONV_US);

    uint8_t buf[3];
    if (i2cReadI2CBlockData(handle, BMP180_REG_DATA, (char *)buf, 3) != 3) {
        fprintf(stderr, "Error: failed to read raw pressure\n");
        return -1;
    }
    *up = ((int32_t)buf[0] << 16 | (int32_t)buf[1] << 8 | buf[2]) >> (8 - BMP180_OSS);
    return 0;
}

/* Compute compensated temperature (°C). */
static int bmp180_read_temp(int handle, const bmp180_cal_t *cal, float *temp)
{
    int32_t ut;
    if (bmp180_read_raw_temp(handle, &ut) != 0)
        return -1;

    int32_t x1 = ((ut - (int32_t)cal->ac6) * (int32_t)cal->ac5) >> 15;
    int32_t x2 = ((int32_t)cal->mc << 11) / (x1 + (int32_t)cal->md);
    int32_t b5 = x1 + x2;
    *temp = ((b5 + 8) >> 4) / 10.0f;
    return 0;
}

/* Compute compensated pressure (Pa). */
static int bmp180_read_pressure(int handle, const bmp180_cal_t *cal, float *press)
{
    int32_t ut, up;
    if (bmp180_read_raw_temp(handle, &ut) != 0)
        return -1;
    if (bmp180_read_raw_press(handle, &up) != 0)
        return -1;

    int32_t x1 = ((ut - (int32_t)cal->ac6) * (int32_t)cal->ac5) >> 15;
    int32_t x2 = ((int32_t)cal->mc << 11) / (x1 + (int32_t)cal->md);
    int32_t b5 = x1 + x2;

    int32_t b6 = b5 - 4000;
    x1 = ((int32_t)cal->b2 * ((b6 * b6) >> 12)) >> 11;
    x2 = ((int32_t)cal->ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)cal->ac1 * 4 + x3) << BMP180_OSS) + 2) >> 2);

    x1 = ((int32_t)cal->ac3 * b6) >> 13;
    x2 = ((int32_t)cal->b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = ((uint32_t)cal->ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> BMP180_OSS);

    int32_t p;
    if (b7 < 0x80000000UL)
        p = (b7 * 2) / b4;
    else
        p = (b7 / b4) * 2;

    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p += (x1 + x2 + 3791) >> 4;

    *press = (float)p;
    return 0;
}

/* ---- Application helpers ---- */

static void add_to_buffer(circular_buffer_t *buf, float temp, float press)
{
    buf->data[buf->head].timestamp  = time(NULL);
    buf->data[buf->head].temperature = temp;
    buf->data[buf->head].pressure   = press;
    buf->head = (buf->head + 1) % BUFFER_SIZE;
    if (buf->count < BUFFER_SIZE)
