        struct tm *tm = localtime(&buf->data[idx].timestamp);
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
        printf("[%s] Temp: %.2f C, Pressure: %.2f Pa\n",
