#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 2000000
#define HEATER_GPIO 17
#define PWM_RANGE 1000
#define PWM_FREQUENCY 1000
#define MAX_DUTY_CYCLE 80.0
#define DEFAULT_TARGET_TEMPERATURE 25.0
#define LOG_FILE "heater_log.csv"

#define MAX31855_FAULT_OPEN_CIRCUIT 0x01
#define MAX31855_FAULT_SHORT_GND 0x02
#define MAX31855_FAULT_SHORT_VCC 0x04

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_data(float temperature, float duty_cycle) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);

    if (log_file) {
        fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, duty_cycle);
        fflush(log_file);
    }
}

static int read_max31855(float *temperature) {
    char tx[4] = {0, 0, 0, 0};
    char rx[4] = {0, 0, 0, 0};

    if (spiXfer(spi_handle, tx, rx, 4) != 4) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    uint32_t raw = ((uint32_t)(uint8_t)rx[0] << 24) |
                   ((uint32_t)(uint8_t)rx[1] << 16) |
                   ((uint32_t)(uint8_t)rx[2] << 8)  |
                   ((uint32_t)(uint8_t)rx[3]);

    if (raw & 0x00010000) {
        fprintf(stderr, "MAX31855 fault detected: ");
        if (raw & MAX31855_FAULT_OPEN_CIRCUIT) fprintf(stderr, "open circuit ");
        if (raw & MAX31855_FAULT_SHORT_GND)    fprintf(stderr, "short to GND ");
        if (raw & MAX31855_FAULT_SHORT_VCC)    fprintf(stderr, "short to VCC ");
        fprintf(stderr, "\n");
        return -1;
    }

    int16_t thermocouple_data = (int16_t)(raw >> 18);
    *temperature = thermocouple_data * 0.25f;
    return 0;
}

static float calculate_duty_cycle(float current_temp, float target_temp) {
    float error = target_temp - current_temp;
    float integral = 0.0f;
    static float previous_error = 0.0f;
    static float integral_sum = 0.0f;
    float Kp = 10.0f;
    float Ki = 0.1f;
    float dt = 1.0f;

    float proportional = Kp * error;
    integral_sum += error * dt;
    float integral_clamped = integral_sum;

    float derivative = (error - previous_error) / dt;
    float output = proportional + Ki * integral_clamped + 0.1f * derivative;

    if (output < 0.0f) output = 0.0f;
    if (output > MAX_DUTY_CYCLE) output = MAX_DUTY_CYCLE;

    previous_error = error;
    return output;
}

static void set_heater_duty_cycle(float duty_cycle) {
    if (duty_cycle < 0.0f) duty_cycle = 0.0f;
    if (duty_cycle > MAX_DUTY_CYCLE) duty_cycle = MAX_DUTY_CYCLE;

    int pwm_value = (int)((duty_cycle / MAX_DUTY_CYCLE) * PWM_RANGE);
    gpioPWM(HEATER_GPIO, pwm_value);
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioWrite(HEATER_GPIO, 0);
    gpioPWM(HEATER_GPIO, 0);
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    float target_temperature = DEFAULT_TARGET_TEMPERATURE;

    if (argc > 1) {
        target_temperature = atof(argv[1]);
        if (target_temperature < -50.0f || target_temperature > 150.0f) {
            fprintf(stderr, "Invalid target temperature. Using default: %.2f\n", DEFAULT_TARGET_TEMPERATURE);
            target_temperature = DEFAULT_TARGET_TEMPERATURE;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    gpioSetMode(HEATER_GPIO, PI_OUTPUT);
    gpioSetPWMrange(HEATER_GPIO, PWM_RANGE);
    gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQUENCY);
    gpioPWM(HEATER_GPIO, 0);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Temperature (C),Duty Cycle (%)\n");
        fflush(log_file);
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float current_temperature = 0.0f;
    float duty_cycle = 0.0f;

    while (running) {
        if (read_max31855(&current_temperature) == 0) {
            duty_cycle = calculate_duty_cycle(current_temperature, target_temperature);
            set_heater_duty_cycle(duty_cycle);
            log_data(current_temperature, duty_cycle);
        } else {
            set_heater_duty_cycle(0.0f);
            log_data(-999.0f, -1.0f);
        }
        time_sleep(1.0);
    }

    cleanup();
    return 0;
}

