    float target_temperature = DEFAULT_TARGET_TEMPERATURE;

    if (argc > 1) {
        target_temperature = atof(argv[1]);
        if (target_temperature < -50.0f || target_temperature > 150.0f) {
            fprintf(stderr, "Invalid target temperature. Using default: %.2f\n", DEFAULT_TARGET_TEMPERATURE);
            target_temperature = DEFAULT_TARGET_TEMPERATURE;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    gpioSetMode(HEATER_GPIO, PI_OUTPUT);
    gpioSetPWMrange(HEATER_GPIO, PWM_RANGE);
    gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQUENCY);
    gpioPWM(HEATER_GPIO, 0);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Temperature (C),Duty Cycle (%)\n");
        fflush(log_file);
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float current_temperature = 0.0f;
    float duty_cycle = 0.0f;

    while (running) {
        if (read_max31855(&current_temperature) == 0) {
