#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define POLL_INTERVAL_US 500000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int set_pwm(int pin, int duty) {
    if (gpioPWM(pin, duty) < 0) {
        fprintf(stderr, "Error: gpioPWM failed on pin %d\n", pin);
        return -1;
    }
    return 0;
}

static int read_temperature(const char *filename, int *temp_out) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Error opening temperature file");
        return -1;
    }

    int temperature;
    if (fscanf(fp, "%d", &temperature) != 1) {
        fprintf(stderr, "Error: Failed to read temperature from file\n");
        fclose(fp);
        return -1;
    }

    if (ferror(fp)) {
        fprintf(stderr, "Error: I/O error reading temperature file\n");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("Warning: error closing temperature file");
        return -1;
    }

    *temp_out = temperature;
    return 0;
}

