#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <sys/select.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/file.h>

#define DHT22_GPIO 4
#define SERVER_URL "http://yourserver.com/api/humidity"
#define MAX_RETRIES 3
#define MAX_BUFFER_SIZE 4096

volatile sig_atomic_t program_running = 1;

void signal_handler(int signum) {
    (void)signum;
    program_running = 0;
}

int read_dht22_data(float *temperature, float *humidity) {
    int data[5] = {0, 0, 0, 0, 0};
    int bit_count = 0;
    int last_state = 1;
    int i;

    // Send start signal
    if (gpioSetMode(DHT22_GPIO, PI_OUTPUT) < 0) return -1;
    if (gpioWrite(DHT22_GPIO, 0) < 0) return -1;
    gpioDelay(2000); // 2ms low
    if (gpioWrite(DHT22_GPIO, 1) < 0) return -1;
    gpioDelay(30);   // 30us high

    // Switch to input
    if (gpioSetMode(DHT22_GPIO, PI_INPUT) < 0) return -1;

    // Wait for sensor response
    int timeout = 0;
    while (gpioRead(DHT22_GPIO) == 1) {
        gpioDelay(1);
        if (++timeout > 100) return -1; // 100us timeout
    }

    timeout = 0;
    while (gpioRead(DHT22_GPIO) == 0) {
        gpioDelay(1);
        if (++timeout > 100) return -1; // 100us timeout
    }

    timeout = 0;
    while (gpioRead(DHT22_GPIO) == 1) {
        gpioDelay(1);
        if (++timeout > 100) return -1; // 100us timeout
    }

    // Read 40 bits
    for (i = 0; i < 40; i++) {
        timeout = 0;
        while (gpioRead(DHT22_GPIO) == 0) {
            gpioDelay(1);
            if (++timeout > 100) return -1; // 100us timeout
        }

        gpioDelay(40); // Wait for bit to finish

        timeout = 0;
        while (gpioRead(DHT22_GPIO) == 1) {
            gpioDelay(1);
            if (++timeout > 100) return -1; // 100us timeout
        }

        data[i / 8] <<= 1;
        if (timeout > 40) {
            data[i / 8] |= 1;
        }
    }

    // Checksum validation
    if (data[4] != ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) {
        return -1;
    }

    *humidity = (float)((data[0] << 8) + data[1]) / 10.0;
    *temperature = (float)(((data[2] & 0x7F) << 8) + data[3]) / 10.0;
    if (data[2] & 0x80) {
        *temperature *= -1.0;
    }

    return 0;
}

int send_http_request(const char *url, const char *json_data) {
    char host[256];
    char path[256];
    int port = 80;
    struct hostent *server;
    struct sockaddr_in serv_addr;
    int sockfd;
    char request[1024];
    int request_len;
    int retries = 0;
    int result = -1;

    while (retries < MAX_RETRIES && program_running) {
        // Parse URL
        if (sscanf(url, "http://%255[^/]/%255s", host, path) != 2) {
            fprintf(stderr, "Error: Invalid URL format.\n");
            retries++;
            sleep(1);
            continue;
        }

        // Get port from host if specified
        char *port_str = strchr(host, ':');
        if (port_str) {
            *port_str = '\0';
            port = atoi(port_str + 1);
        }

        // Create socket
        sockfd = socket(AF_INET, SOCK_STREAM, 0);
        if (sockfd < 0) {
            perror("Error opening socket");
            retries++;
            sleep(1);
            continue;
        }

        // Set socket options for non-blocking connect
        int flags = fcntl(sockfd, F_GETFL, 0);
        if (flags < 0) {
            perror("Error getting socket flags");
            close(sockfd);
            retries++;
            sleep(1);
            continue;
        }
        fcntl(sockfd, F_SETFL, flags | O_NONBLOCK);

        // Connect to server
        server = gethostbyname(host);
        if (server == NULL) {
            perror("Error resolving host");
            close(sockfd);
            retries++;
            sleep(1);
            continue;
        }

        memset(&serv_addr, 0, sizeof(serv_addr));
        serv_addr.sin_family = AF_INET;
        serv_addr.sin_port = htons(port);
        memcpy(&serv_addr.sin_addr.s_addr, server->h_addr, server->h_length);

        if (connect(sockfd, (struct sockaddr *)&serv_addr, sizeof(serv_addr)) < 0) {
            if (errno == EINPROGRESS) {
                fd_set fdset;
                struct timeval tv;
                int valopt;
                int error = 0;

                FD_ZERO(&fdset);
                FD_SET(sockfd, &fdset);
                tv.tv_sec = 10;
                tv.tv_usec = 0;

                int select_result = select(sockfd + 1, NULL, &fdset, NULL, &tv);
                if (select_result < 0) {
                    perror("select error");
                    close(sockfd);
                    retries++;
                    sleep(1);
                    continue;
                } else if (select_result == 0) {
                    fprintf(stderr, "Connection timeout.\n");
                    close(sockfd);
                    retries++;
                    sleep(1);
                    continue;
                }

                if (getsockopt(sockfd, SOL_SOCKET, SO_ERROR, &valopt, sizeof(valopt)) < 0) {
                    perror("getsockopt error");
                    close(sockfd);
                    retries++;
                    sleep(1);
                    continue;
                }

                if (valopt == 0) {
                    // Connection successful
                    break;
                } else {
                    fprintf(stderr, "Connection failed: %d\n", valopt);
                    close(sockfd);
                    retries++;
                    sleep(1);
                    continue;
                }
            } else {
                perror("Error connecting to server");
                close(sockfd);
                retries++;
                sleep(1);
                continue;
            }
        }

        // Set socket to blocking mode
        fcntl(sockfd, F_SETFL, flags);

        // Build HTTP request
        request_len = snprintf(request, sizeof(request),
            "POST /%s HTTP/1.1\r\n"
            "Host: %s\r\n"
            "Content-Type: application/json\r\n"
            "Content-Length: %zu\r\n"
            "Connection: close\r\n"
            "\r\n"
            "%s",
            path, host, strlen(json_data), json_data);

        if (request_len < 0 || (size_t)request_len >= sizeof(request)) {
            fprintf(stderr, "Error: Request buffer too small.\n");
            close(sockfd);
            retries++;
            sleep(1);
            continue;
        }

        // Send HTTP request
        ssize_t bytes_sent = 0;
        while (bytes_sent < request_len) {
            ssize_t sent = send(sockfd, request + bytes_sent, request_len - bytes_sent, 0);
            if (sent < 0) {
                if (errno == EINTR) continue;
                perror("Error sending data");
                close(sockfd);
                retries++;
                sleep(1);
                goto cleanup;
            }
            bytes_sent += sent;
        }

        // Receive HTTP response
        char response[4096];
        ssize_t bytes_received = recv(sockfd, response, sizeof(response) - 1, 0);
        if (bytes_received > 0) {
            response[bytes_received] = '\0';
            printf("Response: %s\n", response);
            result = 0;
            break;
        } else if (bytes_received == 0) {
            fprintf(stderr, "Server closed connection.\n");
        } else {
            perror("Error receiving data");
        }

        close(sockfd);
        retries++;
        sleep(1);
    }

cleanup:
    return result;
}

int main() {
    float temperature, humidity;
    char json_data[256];
    int retries = 0;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (program_running) {
        if (read_dht22_data(&temperature, &humidity) == 0) {
            printf("Temperature: %.1f C, Humidity: %.1f %%\n", temperature, humidity);

            snprintf(json_data, sizeof(json_data),
                "{\"temperature\": %.1f, \"humidity\": %.1f}",
                temperature, humidity);

            if (send_http_request(SERVER_URL, json_data) != 0) {
                fprintf(stderr, "Error sending data to server.\n");
            }
        } else {
            fprintf(stderr, "Error reading DHT22 data.\n");
        }

        sleep(5);
    }

    printf("Exiting program.\n");
    return 0;
}

