/*
 * BMP180 pressure logger for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   BMP180 SDA  -> GPIO 2 (I2C bus 1 SDA)
 *   BMP180 SCL  -> GPIO 3 (I2C bus 1 SCL)
 *   BMP180 VCC  -> 3.3 V
 *   BMP180 GND  -> GND
 *   Button      -> GPIO 4 (internal pull-up; active-low)
 *
 * Build:  gcc -O2 -Wall -Wextra -o bmp180_logger bmp180_logger.c -lpigpio -lrt
 * Run:    sudo ./bmp180_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS            1
#define BMP180_ADDR        0x77
#define GPIO_BUTTON        4
#define OSS                3
#define LOG_FILE           "pressure_log.txt"
#define CONV_DELAY_US      26000   /* 26 ms max conversion time for OSS=3 */
#define DEBOUNCE_US        200000  /* 200 ms debounce window */
#define SAMPLE_PERIOD_US   2000000 /* 2 s between samples when logging */

/* BMP180 registers */
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_DATA    0xF6

/* Control commands */
#define BMP180_CMD_TEMP    0x2E
#define BMP180_CMD_PRESS   0x34

typedef struct {
    int16_t  ac1, ac2, ac3, b1, b2, mb, mc, md;
    uint16_t ac4, ac5, ac6;
} bmp180_cal_t;

static volatile sig_atomic_t g_running = 1;
static volatile sig_atomic_t g_logging = 0;
static volatile uint32_t     g_last_tick = 0;
static int                   g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len)
{
    if (i2cWriteByte(handle, reg) < 0)
        return -1;
    int n = i2cReadDevice(handle, (char *)buf, len);
    return (n == (int)len) ? 0 : -1;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t val)
{
    if (i2cWriteByte(handle, reg) < 0)
        return -1;
    return (i2cWriteByte(handle, val) == 0) ? 0 : -1;
}

/* ------------------------------------------------------------------ */
/* BMP180 calibration                                                  */
/* ------------------------------------------------------------------ */
static int bmp180_read_calibration(int handle, bmp180_cal_t *cal)
{
    uint8_t d[22];
    if (i2c_read_block(handle, BMP180_REG_CAL_AC1, d, sizeof(d)) != 0) {
        fprintf(stderr, "Error: failed to read BMP180 calibration data\n");
        return -1;
    }

    cal->ac1 = (int16_t)((d[0]  << 8) | d[1]);
    cal->ac2 = (int16_t)((d[2]  << 8) | d[3]);
    cal->ac3 = (int16_t)((d[4]  << 8) | d[5]);
    cal->ac4 = (uint16_t)((d[6]  << 8) | d[7]);
    cal->ac5 = (uint16_t)((d[8]  << 8) | d[9]);
    cal->ac6 = (uint16_t)((d[10] << 8) | d[11]);
    cal->b1  = (int16_t)((d[12] << 8) | d[13]);
    cal->b2  = (int16_t)((d[14] << 8) | d[15]);
    cal->mb  = (int16_t)((d[16] << 8) | d[17]);
    cal->mc  = (int16_t)((d[18] << 8) | d[19]);
    cal->md  = (int16_t)((d[20] << 8) | d[21]);

    /* Sanity-check: AC1 should never be 0 or 0xFFFF on a real BMP180 */
    if (cal->ac1 == 0 || cal->ac1 == (int16_t)0xFFFF) {
        fprintf(stderr, "Error: BMP180 calibration data invalid (AC1=0x%04X)\n",
                (uint16_t)cal->ac1);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* BMP180 integer compensation (Bosch BMP180 datasheet, OSS=3)         */
/* ------------------------------------------------------------------ */
static int32_t bmp180_compute_b5(const bmp180_cal_t *cal, int32_t ut)
{
    int32_t x1 = ((ut - (int32_t)cal->ac6) * (int32_t)cal->ac5) >> 15;
    int32_t x2 = ((int32_t)cal->mc << 11) / (x1 + (int32_t)cal->md);
    return x1 + x2;
}

static int32_t bmp180_read_raw_temperature(int handle)
{
    if (i2c_write_byte(handle, BMP180_REG_CONTROL, BMP180_CMD_TEMP) != 0)
        return -1;
    gpioDelay(5000); /* 4.5 ms max conversion time */

    uint8_t d[2];
    if (i2c_read_block(handle, BMP180_REG_DATA, d, 2) != 0)
        return -1;
    return (int32_t)((d[0] << 8) | d[1]);
}

static int32_t bmp180_read_raw_pressure(int handle, int oss)
{
    if (i2c_write_byte(handle, BMP180_REG_CONTROL, BMP180_CMD_PRESS | (oss << 6)) != 0)
        return -1;
    gpioDelay(CONV_DELAY_US);

    uint8_t d[3];
    if (i2c_read_block(handle, BMP180_REG_DATA, d, 3) != 0)
        return -1;
    int32_t up = ((int32_t)d[0] << 16) | ((int32_t)d[1] << 8) | d[2];
    up >>= (8 - oss);
    return up;
}

static double bmp180_compute_pressure(const bmp180_cal_t *cal, int32_t up, int32_t b5)
{
    int32_t b6 = b5 - 4000;
    int32_t x1 = ((int32_t)cal->b2 * ((b6 * b6) >> 12)) >> 11;
    int32_t x2 = ((int32_t)cal->ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)cal->ac1 * 4 + x3) << OSS) + 2) / 4);

    x1 = ((int32_t)cal->ac3 * b6) >> 13;
    x2 = ((int32_t)cal->b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = ((uint32_t)cal->ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> OSS);

    int32_t p;
    if (b7 < 0x80000000UL)
        p = (b7 * 2) / b4;
    else
        p = (b7 / b4) * 2;

    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p += (x1 + x2 + 3791) >> 4;

    return (double)p / 100.0; /* Pa -> hPa */
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_pressure(double pressure)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s, %.2f hPa\n", ts, pressure);
    fclose(fp);
    printf("Logged: %s, %.2f hPa\n", ts, pressure);
}

/* ------------------------------------------------------------------ */
/* Button interrupt (falling edge)                                     */
/* ------------------------------------------------------------------ */
static void button_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level != 0) /* only falling edge */
        return;

    uint32_t last = g_last_tick;
    if (tick - last < DEBOUNCE_US)
        return;
    g_last_tick = tick;

    g_logging = !g_logging;
    printf("Logging %s\n", g_logging ? "enabled" : "disabled");
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- I2C open --- */
    g_i2c_handle = i2cOpen(I2C_BUS, BMP180_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d) — sensor absent or bus error\n",
                g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Calibration --- */
    bmp180_cal_t cal;
    if (bmp180_read_calibration(g_i2c_handle, &cal) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Button GPIO --- */
    gpioSetMode(GPIO_BUTTON, PI_INPUT);
    gpioSetPullUpDown(GPIO_BUTTON, PI_PUD_UP);
    if (gpioSetISRFuncEx(GPIO_BUTTON, FALLING_EDGE, 0, button_isr, NULL) != 0) {
        fprintf(stderr, "Error: failed to register ISR on GPIO %d\n", GPIO_BUTTON);
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Signals --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("BMP180 logger ready. Press button on GPIO %d to toggle logging.\n",
           GPIO_BUTTON);
    printf("Press Ctrl+C to exit.\n");

    /* --- Main loop --- */
    while (g_running) {
        if (g_logging) {
            int32_t ut = bmp180_read_raw_temperature(g_i2c_handle);
            if (ut < 0) {
                fprintf(stderr, "Warning: temperature read failed\n");
            } else {
                int32_t b5 = bmp180_compute_b5(&cal, ut);
                int32_t up = bmp180_read_raw_pressure(g_i2c_handle, OSS);
                if (up < 0) {
                    fprintf(stderr, "Warning: pressure read failed\n");
                } else {
                    double pressure = bmp180_compute_pressure(&cal, up, b5);
                    log_pressure(pressure);
                }
            }
        } else {
            printf("Logging disabled — pressure readings not logged.\n");
        }
        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

