#include <sys/time.h>

#include <curl/curl.h>
#include <jansson.h>

#define DHT22_GPIO 4
#define MAX_RETRIES 3
#define DHT22_READ_INTERVAL 10
#define DHT22_START_LOW_US 1000
#define DHT22_START_HIGH_US 30
#define DHT22_TIMEOUT_US 200
#define DHT22_BIT_THRESHOLD_US 50

static volatile sig_atomic_t running = 1;
static char *api_url = "http://your-the-librarys-api-call.com/api/humidity";

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_message(int priority, const char *message) {
    syslog(priority, "%s", message);
}

static void cleanup_resources(void) {
    curl_global_cleanup();
    json_decref(json_true);
    json_decref(json_false);
}

static int read_dht22(float *humidity) {
    int data[5] = {0, 0, 0, 0, 0};
    int bit_count = 0;
    struct timeval tv;
    uint32_t start_time, current_time;

    if (gpioSetMode(DHT22_GPIO, PI_OUTPUT) < 0) return -1;
    gpioWrite(DHT22_GPIO, 0);
    gpioDelay(DHT22_START_LOW_US);
    gpioWrite(DHT22_GPIO, 1);
    gpioDelay(DHT22_START_HIGH_US);
    if (gpioSetMode(DHT22_GPIO, PI_INPUT) < 0) return -1;

    for (int i = 0; i < 85; i++) {
        int val = gpioRead(DHT22_GPIO);
        if (val < 0) return -1;
        gpioDelay(1);
    }

    for (int i = 0; i < 40; i++) {
        int timeout = 0;
        while (gpioRead(DHT22_GPIO) == 1) {
            gpioDelay(1);
            if (++timeout > DHT22_TIMEOUT_US) return -1;
        }
        start_time = gpioTick();
        timeout = 0;
        while (gpioRead(DHT22_GPIO) == 0) {
            gpioDelay(1);
            if (++timeout > DHT22_TIMEOUT_US) return -1;
        }
        current_time = gpioTick();
        uint32_t duration = current_time - start_time;
        if (duration > DHT22_BIT_THRESHOLD_US) {
            data[bit_count / 8] |= (1 << (7 - (bit_count % 8)));
        }
        bit_count++;
    }

    if (data[4] != ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) {
        return -1;
    }

    *humidity = (float)(((data[0] & 0x7F) << 8) + data[1]) / 10.0;
    return 0;
}

static int post_data(const char *url, float humidity) {
    CURL *curl = curl_easy_init();
    if (!curl) {
        log_message(LOG_ERR, "curl_easy_init() failed");
        return -1;
    }

    json_t *root = json_object();
    if (!root) {
        log_message(LOG_ERR, "Failed to create JSON object");
        curl_easy_cleanup(curl);
        return -1;
    }

    json_object_set_new(root, "humidity", json_real(humidity));

    char *json_string = json_dumps(root, JSON_REAL_PRECISION(1));
    if (!json_string) {
        log_message(LOG_ERR, "Failed to serialize JSON");
        json_decref(root);
        curl_easy_cleanup(curl);
        return -1;
    }

    struct curl_slist *headers = NULL;
    headers = curl_slist_append(headers, "Content-Type: application/json");
    if (!headers) {
        log_message(LOG_ERR, "Failed to create HTTP headers");
        free(json_string);
        json_decref(root);
        curl_easy_cleanup(curl);
        return -1;
    }

    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_POST, 1L);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_string);
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
    curl_easy_setopt(curl, CURLOPT_TIMEOUT, 10L);
    curl_easy_setopt(curl, CURLOPT_CONNECTTIMEOUT, 5L);
    curl_easy_setopt(curl, CURLOPT_NOSIGNAL, 1L);

    CURLcode res = curl_easy_perform(curl);
    int ret = 0;
    if (res != CURLE_OK) {
        log_message(LOG_ERR, curl_easy_strerror(res));
        ret = -1;
    } else {
        long http_code = 0;
        curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &http_code);
        if (http_code < 200 || http_code >= 300) {
            log_message(LOG_ERR, "HTTP request failed with code: ");
            char buf[32];
            snprintf(buf, sizeof(buf), "%ld", http_code);
            log_message(LOG_ERR, buf);
            ret = -1;
        }
    }

    curl_slist_free_all(headers);
    free(json_string);
    json_decref(root);
    curl_easy_cleanup(curl);
    return ret;
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "s:")) != -1) {
        switch (opt) {
            case 's':
                api_url = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-s <api_url>]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    openlog("dht22_humidity", LOG_PID | LOG_CONS, LOG_USER);

    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "Failed to initialize pigpio");
        closelog();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (curl_global_init(CURL_GLOBAL_ALL) != CURLE_OK) {
        log_message(LOG_ERR, "curl_global_init() failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    while (running) {
        float humidity = 0.0;
        int retries = 0;
        int read_success = 0;

        while (retries < MAX_RETRIES && running) {
            if (read_dht22(&humidity) == 0) {
                read_success = 1;
                break;
            }
            retries++;
            if (retries < MAX_RETRIES) {
                char log_buf[128];
                snprintf(log_buf, sizeof(log_buf), "DHT22 read failed (attempt %d/%d)", retries, MAX_RETRIES);
                log_message(LOG_ERR, log_buf);
                sleep(2);
            }
        }

        if (read_success) {
            int post_retries = 0;
            int post_success = 0;
            while (post_retries < MAX_RETRIES && running) {
                if (post_data(api_url, humidity) == 0) {
                    post_success = 1;
                    break;
                }
                post_retries++;
                if (post_retries < MAX_RETRIES) {
                    char log_buf[128];
                    snprintf(log_buf, sizeof(log_buf), "POST failed (attempt %d/%d)", post_retries, MAX_RETRIES);
                    log_message(LOG_ERR, log_buf);
                    sleep(2);
                }
            }
            if (!post_success) {
                log_message(LOG_ERR, "Failed to post data after multiple retries");
            }
        } else {
            log_message(LOG_ERR, "Failed to read humidity after multiple retries");
        }

        for (int i = 0; i < DHT22_READ_INTERVAL && running; i++) {
            sleep(1);
        }
    }

    gpioTerminate();
    cleanup_resources();
    closelog();
    return EXIT_SUCCESS;
}

