#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#define CPU_TEMP_PATH "/sys/class/thermal/thermal_zone0/temp"
#define FAN_STATE_PATH "/sys/class/thermal/cooling_device0/cur_state"
#define FAN_MAX_STATE_PATH "/sys/class/thermal/cooling_device0/max_state"
#define LOG_FILE_PATH "/var/log/fan_control.log"
#define POLL_INTERVAL_SEC 5

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int read_cpu_temp(void) {
    FILE *fp = fopen(CPU_TEMP_PATH, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", CPU_TEMP_PATH, strerror(errno));
        return -1;
    }
    int temp;
    if (fscanf(fp, "%d", &temp) != 1) {
        fprintf(stderr, "Error reading CPU temperature from %s\n", CPU_TEMP_PATH);
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return temp;
}

static int read_fan_state(void) {
    FILE *fp = fopen(FAN_STATE_PATH, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", FAN_STATE_PATH, strerror(errno));
        return -1;
    }
    int state;
    if (fscanf(fp, "%d", &state) != 1) {
        fprintf(stderr, "Error reading fan state from %s\n", FAN_STATE_PATH);
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return state;
}

static int read_fan_max_state(void) {
    FILE *fp = fopen(FAN_MAX_STATE_PATH, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", FAN_MAX_STATE_PATH, strerror(errno));
        return -1;
    }
    int max_state;
    if (fscanf(fp, "%d", &max_state) != 1) {
        fprintf(stderr, "Error reading fan max state from %s\n", FAN_MAX_STATE_PATH);
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return max_state;
}

static int set_fan_state(int state) {
    if (state < 0) {
        fprintf(stderr, "Invalid fan state: %d\n", state);
        return -1;
    }
    int max_state = read_fan_max_state();
    if (max_state < 0) {
        return -1;
    }
    if (state > max_state) {
        fprintf(stderr, "Warning: requested fan state %d exceeds max state %d\n", state, max_state);
        state = max_state;
    }
    FILE *fp = fopen(FAN_STATE_PATH, "w");
    if (!fp) {
        fprintf(stderr, "Error opening %s for writing: %s\n", FAN_STATE_PATH, strerror(errno));
        return -1;
    }
    if (fprintf(fp, "%d", state) < 0) {
        fprintf(stderr, "Error writing fan state to %s\n", FAN_STATE_PATH);
        fclose(fp);
        return -1;
    }
    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing %s: %s\n", FAN_STATE_PATH, strerror(errno));
        return -1;
    }
    return 0;
}

static int log_fan_speed_change(int new_state) {
    FILE *fp = fopen(LOG_FILE_PATH, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE_PATH, strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time\n");
        fclose(fp);
        return -1;
    }
    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }
    if (fprintf(fp, "%s - Fan speed changed to state: %d\n", timestamp, new_state) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        fclose(fp);
        return -1;
    }
    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int control_fan_speed(int cpu_temp) {
    int fan_state;
    if (cpu_temp < 45000) {
        fan_state = 0;
    } else if (cpu_temp < 55000) {
        fan_state = 1;
    } else if (cpu_temp < 65000) {
        fan_state = 2;
    } else {
        fan_state = 3;
    }
    return fan_state;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }
    printf("Fan control program started. Press Ctrl+C to exit.\n");
    while (g_running) {
        int cpu_temp = read_cpu_temp();
        if (cpu_temp < 0) {
            fprintf(stderr, "Error reading CPU temperature, retrying in %d seconds...\n", POLL_INTERVAL_SEC);
            sleep(POLL_INTERVAL_SEC);
            continue;
        }
        int current_fan_state = read_fan_state();
        if (current_fan_state < 0) {
            fprintf(stderr, "Error reading current fan state, retrying in %d seconds...\n", POLL_INTERVAL_SEC);
            sleep(POLL_INTERVAL_SEC);
            continue;
        }
        int target_fan_state = control_fan_speed(cpu_temp);
        if (target_fan_state != current_fan_state) {
            if (set_fan_state(target_fan_state) == 0) {
                if (log_fan_speed_change(target_fan_state) != 0) {
                    fprintf(stderr, "Warning: failed to log fan speed change\n");
                }
            } else {
                fprintf(stderr, "Error setting fan state to %d\n", target_fan_state);
            }
        }
        sleep(POLL_INTERVAL_SEC);
    }
    printf("\nShutting down...\n");
    if (set_fan_state(0) != 0) {
        fprintf(stderr, "Error setting fan state to 0 during shutdown\n");
    }
    if (log_fan_speed_change(0) != 0) {
        fprintf(stderr, "Warning: failed to log shutdown event\n");
    }
    printf("Fan control program stopped.\n");
    return 0;
}

