#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>

#define HEATER_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define TARGET_TEMP 50.0
#define MAX_TEMP 100.0
#define MIN_TEMP 0.0
#define PWM_FREQUENCY 1000
#define PWM_RANGE 100
#define LOG_FILE "heater_log.txt"
#define SAMPLE_INTERVAL_US 1000000

#define MAX31855_FAULT_OPEN_CIRCUIT 0x01
#define MAX31855_FAULT_SHORT_GND 0x02
#define MAX31855_FAULT_SHORT_VCC 0x04

typedef struct {
    double Kp;
    double Ki;
    double Kd;
    double integral;
    double previous_error;
} PIDController;

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static double read_temperature(void) {
    char buffer[4];
    int bytes_read = spiRead(spi_handle, buffer, 4);
    if (bytes_read != 4) {
        fprintf(stderr, "SPI read failed: %s\n", strerror(errno));
        return -1000.0;
    }

    uint32_t raw = ((uint32_t)(uint8_t)buffer[0] << 24) |
                   ((uint32_t)(uint8_t)buffer[1] << 16) |
                   ((uint32_t)(uint8_t)buffer[2] << 8)  |
                   ((uint32_t)(uint8_t)buffer[3]);

    if (raw & 0x00010000) {
        fprintf(stderr, "MAX31855 fault detected: ");
        if (raw & MAX31855_FAULT_OPEN_CIRCUIT) fprintf(stderr, "open circuit ");
        if (raw & MAX31855_FAULT_SHORT_GND)    fprintf(stderr, "short to GND ");
        if (raw & MAX31855_FAULT_SHORT_VCC)    fprintf(stderr, "short to VCC ");
        fprintf(stderr, "\n");
        return -1000.0;
    }

    int16_t thermocouple_temp = (int16_t)(raw >> 18);
    return thermocouple_temp * 0.25;
}

static double calculate_pid(PIDController *pid, double setpoint, double actual) {
    double error = setpoint - actual;
    pid->integral += error;
    double derivative = error - pid->previous_error;
    double output = pid->Kp * error + pid->Ki * pid->integral + pid->Kd * derivative;
    pid->previous_error = error;
    return output;
}

static void set_heater_pwm(double duty_cycle) {
    if (duty_cycle < 0.0) duty_cycle = 0.0;
    if (duty_cycle > 100.0) duty_cycle = 100.0;
    gpioPWM(HEATER_GPIO, (int)(duty_cycle * 10000.0 / PWM_RANGE));
}

static void log_data(double temp, double duty, double pid_out) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s, Temp: %.2f, Duty: %.2f, PID: %.2f\n", timestamp, temp, duty, pid_out);
    fflush(log_file);
}

static void cleanup(void) {
    gpioWrite(HEATER_GPIO, 0);
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    gpioSetMode(HEATER_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(HEATER_GPIO, PWM_RANGE);
    gpioPWM(HEATER_GPIO, 0);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    PIDController pid = {1.0, 0.1, 0.01, 0.0, 0.0};

    while (running) {
        double temp = read_temperature();
        if (temp < -999.0) {
            set_heater_pwm(0.0);
            pid.integral = 0.0;
            pid.previous_error = 0.0;
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        if (temp > MAX_TEMP || temp < MIN_TEMP) {
            fprintf(stderr, "Temperature out of range: %.2f\n", temp);
            set_heater_pwm(0.0);
            pid.integral = 0.0;
            pid.previous_error = 0.0;
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        double pid_out = calculate_pid(&pid, TARGET_TEMP, temp);
        double duty = pid_out;
        if (duty < 0.0) duty = 0.0;
        if (duty > 100.0) duty = 100.0;

        set_heater_pwm(duty);
        log_data(temp, duty, pid_out);
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return 0;
}

