#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FAN_GPIO 18
#define LOG_FILE "cooling_log.csv"
#define PWM_FREQUENCY 25000
#define MIN_TEMP 40.0
#define MAX_TEMP 70.0
#define SAMPLE_INTERVAL 5

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_data(float temperature, int duty_cycle) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%d\n", timestamp, temperature, duty_cycle);
    fclose(fp);
    return 0;
}

static int set_fan_speed(float temperature) {
    int duty_cycle;

    if (temperature <= MIN_TEMP) {
        duty_cycle = 0;
    } else if (temperature >= MAX_TEMP) {
        duty_cycle = 100;
    } else {
        duty_cycle = (int)(((temperature - MIN_TEMP) / (MAX_TEMP - MIN_TEMP)) * 100.0);
    }

    if (gpioPWM(FAN_GPIO, duty_cycle) != 0) {
        fprintf(stderr, "Error setting PWM duty cycle to %d\n", duty_cycle);
        return -1;
    }

    if (log_data(temperature, duty_cycle) != 0) {
        fprintf(stderr, "Error logging data\n");
        return -1;
    }

    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", FAN_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY) != PWM_FREQUENCY) {
        fprintf(stderr, "Error setting PWM frequency to %d Hz\n", PWM_FREQUENCY);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioPWM(FAN_GPIO, 0) != 0) {
        fprintf(stderr, "Error initializing PWM duty cycle to 0\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Error setting SIGINT handler");
        gpioPWM(FAN_GPIO, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error setting SIGTERM handler");
        gpioPWM(FAN_GPIO, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *fp = fopen(LOG_FILE, "r");
    if (fp == NULL) {
        fp = fopen(LOG_FILE, "w");
        if (fp != NULL) {
            fprintf(fp, "Timestamp,Temperature (C),Duty Cycle (%%)\n");
            fclose(fp);
        } else {
            perror("Error creating log file");
            gpioPWM(FAN_GPIO, 0);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    } else {
        fclose(fp);
    }

    while (running) {
        FILE *fp = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
        if (fp == NULL) {
            perror("Error opening temperature file");
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        int temp_milli_celsius;
        if (fscanf(fp, "%d", &temp_milli_celsius) != 1) {
            fprintf(stderr, "Error reading temperature from file\n");
            fclose(fp);
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        fclose(fp);

        float temperature = (float)temp_milli_celsius / 1000.0;

        if (set_fan_speed(temperature) != 0) {
            fprintf(stderr, "Error setting fan speed\n");
        }

        sleep(SAMPLE_INTERVAL);
    }

    gpioPWM(FAN_GPIO, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

