/*
 * Raspberry Pi Zero W – Dual SLF3S-1300F liquid-flow logger
 *
 * Wiring:
 *   Sensor 1 SDA -> GPIO2 (pin 3), SCL -> GPIO3 (pin 5), VDD 3V3, GND
 *   Sensor 2 SDA -> GPIO2 (pin 3), SCL -> GPIO3 (pin 5), VDD 3V3, GND
 *   (Sensors are addressed 0x6B and 0x6C on the I2C bus.)
 *
 * Build:  gcc -O2 -Wall -Wextra -o flow_logger flow_logger.c -lpigpio -lrt
 * Run:    sudo ./flow_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SENSOR1_ADDR   0x6B
#define SENSOR2_ADDR   0x6C
#define LOG_FILE       "flow_log.txt"
#define POLL_INTERVAL  1.0          /* seconds between samples */
#define MAX_RETRIES    3
#define READ_LEN       3            /* 2 data bytes + 1 CRC byte */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion polynomial 0x31, init 0xFF)                        */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, int len)
{
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Read one 3-byte flow sample from a sensor                           */
/* Returns 0 on success (flow_rate set), -1 on persistent failure.    */
/* ------------------------------------------------------------------ */
static int read_flow_rate(int handle, float *flow_rate)
{
    uint8_t buf[READ_LEN];
    int rc;

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        rc = i2cReadDevice(handle, (char *)buf, READ_LEN);
        if (rc == READ_LEN) {
            if (crc8(buf, 2) != buf[2]) {
                fprintf(stderr, "[warn] CRC mismatch on handle %d (attempt %d)\n",
                        handle, attempt + 1);
                continue;
            }
            /* SLF3S-1300F: 16-bit big-endian flow, LSB first, 0.001 counts/s */
            int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
            *flow_rate = (float)raw * 0.001f;
            return 0;
        }
        /* rc < 0: pigpio returns negative error code */
        fprintf(stderr, "[warn] I2C read failed on handle %d (rc=%d, attempt %d)\n",
                handle, rc, attempt + 1);
        if (attempt < MAX_RETRIES - 1)
            time_sleep(0.05);   /* brief back-off before retry */
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* Append a timestamped flow-rate pair to the log file                 */
/* ------------------------------------------------------------------ */
static void log_flow_rates(float f1, float f2)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        fclose(fp);
        return;
    }

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.3f,%.3f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, f1, f2);
    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- open I2C handles ---- */
    int h1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (h1 < 0) {
        fprintf(stderr, "i2cOpen(sensor1 0x%02X) failed: %d\n", SENSOR1_ADDR, h1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int h2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (h2 < 0) {
        fprintf(stderr, "i2cOpen(sensor2 0x%02X) failed: %d\n", SENSOR2_ADDR, h2);
        i2cClose(h1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("SLF3S-1300F dual logger started.  Ctrl+C to exit.\n");

    /* ---- main loop ---- */
    while (g_running) {
        float f1 = 0.0f, f2 = 0.0f;
        int ok1 = read_flow_rate(h1, &f1);
        int ok2 = read_flow_rate(h2, &f2);

        if (ok1 == 0 && ok2 == 0)
            log_flow_rates(f1, f2);
        else
            fprintf(stderr, "[warn] Sensor read failure – entry skipped.\n");

        time_sleep(POLL_INTERVAL);
    }

    /* ---- clean shutdown ---- */
    i2cClose(h1);
    i2cClose(h2);
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

