#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define GPIO_A 17
#define GPIO_B 18
#define LOG_FILE "encoder_log.txt"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int setup_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(GPIO_A, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", GPIO_A);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(GPIO_B, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", GPIO_B);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPullUpDown(GPIO_A, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", GPIO_A);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPullUpDown(GPIO_B, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", GPIO_B);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int read_encoder(int *a, int *b) {
    *a = gpioRead(GPIO_A);
    *b = gpioRead(GPIO_B);
    if (*a < 0 || *b < 0) {
        fprintf(stderr, "GPIO read error: a=%d b=%d\n", *a, *b);
        return -1;
    }
    return 0;
}

static double calculate_angle(int a, int b) {
    static int last_state = 0;
    int current_state = (a << 1) | b;

    int delta = current_state - last_state;
    if (delta == 0) {
        return -1.0;
    }

    double angle;
    if (delta == 3 || delta == -5) {
        angle = 270.0;
    } else if (delta == -3 || delta == 5) {
        angle = 90.0;
    } else if (delta == 1 || delta == -7) {
        angle = 0.0;
    } else if (delta == -1 || delta == 7) {
        angle = 180.0;
    } else {
        angle = -1.0;
    }

    last_state = current_state;
    return angle;
}

static int log_data(double angle) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "Error getting time: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error converting time\n");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s, %.2f\n", timestamp, angle) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (setup_gpio() != 0) {
        return 1;
    }

    int a, b;
    if (read_encoder(&a, &b) != 0) {
        gpioTerminate();
        return 1;
    }

    double angle = calculate_angle(a, b);
    if (angle < 0.0) {
        fprintf(stderr, "Initial angle calculation failed\n");
        gpioTerminate();
        return 1;
    }

    if (log_data(angle) != 0) {
        gpioTerminate();
        return 1;
    }

    printf("Encoder monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        if (read_encoder(&a, &b) != 0) {
            break;
        }

        double new_angle = calculate_angle(a, b);
        if (new_angle >= 0.0) {
            if (new_angle != angle) {
                if (log_data(new_angle) != 0) {
                    break;
                }
                angle = new_angle;
            }
        }
    }

    gpioTerminate();
    printf("\nEncoder monitoring stopped.\n");
    return 0;
}

