/*
 * ADPD144RI Red/IR Photometric Sensor Logger for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   ADPD144RI SDA  -> GPIO2  (I2C bus 1 SDA)
 *   ADPD144RI SCL  -> GPIO3  (I2C bus 1 SCL)
 *   ADPD144RI VDD  -> 3.3 V
 *   ADPD144RI GND  -> GND
 *   LED anode     -> GPIO17 (with ~330 Ω series resistor to GND)
 *
 * Build: gcc -O2 -Wall -o adpd144ri_logger adpd144ri_logger.c -lpigpio -lrt
 * Run:   sudo ./adpd144ri_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- ADPD144RI I2C ---- */
#define ADPD144RI_ADDR 0x50

/* ---- ADPD144RI Register Map (16-bit registers, big-endian on bus) ---- */
#define REG_RED_DATA   0x04
#define REG_IR_DATA    0x06
#define REG_DEVICE_ID  0x00
#define REG_MODE       0x01
#define REG_INT_EN     0x02
#define REG_INT_CLR    0x03

#define EXPECTED_DEVICE_ID 0x144

/* ---- GPIO ---- */
#define LED_GPIO 17

/* ---- Threshold ---- */
#define IR_THRESHOLD 2000

/* ---- Sampling ---- */
#define SAMPLE_INTERVAL_US 100000  /* 100 ms */

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd = -1;
static FILE    *g_log_fp = NULL;
static int      g_pigpio_inited = 0;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit big-endian register from the ADPD144RI.              */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int adpd_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    char buf[2];

    if (i2cWriteByte(fd, reg) < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByte(reg=0x%02X) failed\n", reg);
        return -1;
    }
    if (i2cReadDevice(fd, buf, 2) != 2) {
        fprintf(stderr, "[ERROR] i2cReadDevice(reg=0x%02X) failed\n", reg);
        return -1;
    }
    *out = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit big-endian value to a 16-bit ADPD144RI register.     */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int adpd_write_reg16(int fd, uint8_t reg, uint16_t val)
{
    char buf[3];
    buf[0] = (char)reg;
    buf[1] = (char)(val >> 8);
    buf[2] = (char)(val & 0xFF);

    if (i2cWriteDevice(fd, buf, 3) != 3) {
        fprintf(stderr, "[ERROR] i2cWriteDevice(reg=0x%02X, val=0x%04X) failed\n",
                reg, val);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialise the ADPD144RI: verify device ID, put into standby mode.  */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int adpd144ri_init(int fd)
{
    uint16_t device_id = 0;

    if (adpd_read_reg16(fd, REG_DEVICE_ID, &device_id) != 0) {
        fprintf(stderr, "[ERROR] Cannot read DEVICE_ID — sensor absent or bus error.\n");
        return -1;
    }

    if (device_id != EXPECTED_DEVICE_ID) {
        fprintf(stderr, "[ERROR] Unexpected DEVICE_ID: 0x%04X (expected 0x%04X).\n",
                device_id, EXPECTED_DEVICE_ID);
        return -1;
    }

    /* Put sensor into standby mode (MODE = 0x00) so we can read data. */
    if (adpd_write_reg16(fd, REG_MODE, 0x0000) != 0) {
        fprintf(stderr, "[ERROR] Failed to set MODE register.\n");
        return -1;
    }

    /* Clear any pending interrupts. */
    if (adpd_write_reg16(fd, REG_INT_CLR, 0x0001) != 0) {
        fprintf(stderr, "[WARN] Failed to clear interrupts.\n");
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one sample: red and IR.                                        */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int adpd144ri_read_sample(int fd, uint16_t *red, uint16_t *ir)
{
    if (adpd_read_reg16(fd, REG_RED_DATA, red) != 0)
        return -1;
    if (adpd_read_reg16(fd, REG_IR_DATA, ir) != 0)
        return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
static void log_sample(FILE *fp, uint16_t red, uint16_t ir)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    localtime_r(&t, &tm);
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%u,%u\n", ts, red, ir);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        i2cClose(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_pigpio_inited) {
        gpioWrite(LED_GPIO, 0);
        gpioTerminate();
        g_pigpio_inited = 0;
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;

    /* ---- Signal handling ---- */
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
