/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int adpd_write_reg16(int fd, uint8_t reg, uint16_t val)
{
    char buf[3];
    buf[0] = (char)reg;
    buf[1] = (char)(val >> 8);
    buf[2] = (char)(val & 0xFF);

