#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>

#define SENSOR_GPIO 18
#define LOG_FILE "rpm_log.txt"
#define SAMPLE_INTERVAL_SEC 1

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;
static volatile int pulse_count = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void isr_callback(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio;
    (void)tick;
    (void)userdata;
    if (level == 1) {
        pthread_mutex_lock(&pulse_mutex);
        pulse_count++;
        pthread_mutex_unlock(&pulse_mutex);
    }
}

static int log_rpm(double rpm) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (fprintf(log_file, "%s, %.2f RPM\n", timestamp, rpm) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_GPIO);
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_GPIO, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down on GPIO %d\n", SENSOR_GPIO);
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetISRFuncEx(SENSOR_GPIO, RISING_EDGE, 0, isr_callback, NULL) != 0) {
        fprintf(stderr, "Failed to register ISR on GPIO %d\n", SENSOR_GPIO);
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Failed to install signal handler");
        gpioSetISRFuncEx(SENSOR_GPIO, RISING_EDGE, 0, NULL, NULL);
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("RPM monitoring started on GPIO %d. Press Ctrl+C to exit.\n", SENSOR_GPIO);

    while (running) {
        sleep(SAMPLE_INTERVAL_SEC);

        pthread_mutex_lock(&pulse_mutex);
        int pulses = pulse_count;
        pulse_count = 0;
        pthread_mutex_unlock(&pulse_mutex);

        double rpm = (double)pulses * 60.0;
        if (log_rpm(rpm) != 0) {
            fprintf(stderr, "Logging failed, continuing...\n");
        }
    }

    printf("\nShutting down...\n");

    gpioSetISRFuncEx(SENSOR_GPIO, RISING_EDGE, 0, NULL, NULL);
    fclose(log_file);
    gpioTerminate();
    pthread_mutex_destroy(&pulse_mutex);

    return EXIT_SUCCESS;
}

