#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define ADPD144RI_I2C_ADDR 0x50
#define I2C_BUS "/dev/i2c-1"
#define GPIO_LED 17
#define IR_THRESHOLD 2000
#define LOG_FILE "adpd144ri_log.txt"
#define SAMPLE_INTERVAL_US 100000

#define REG_RED_DATA 0x04
#define REG_IR_DATA 0x05
#define REG_MODE 0x00
#define REG_RESET 0x01

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *value) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        return -1;
    }
    *value = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int adpd144ri_init(int fd) {
    if (i2c_write_reg8(fd, REG_RESET, 0x01) < 0) {
        return -1;
    }
    gpioDelay(10000);
    if (i2c_write_reg8(fd, REG_MODE, 0x01) < 0) {
        return -1;
    }
    return 0;
}

static int read_adpd144ri_data(int fd, uint16_t *red, uint16_t *ir) {
    if (i2c_read_reg16(fd, REG_RED_DATA, red) < 0) {
        return -1;
    }
    if (i2c_read_reg16(fd, REG_IR_DATA, ir) < 0) {
        return -1;
    }
    return 0;
}

static void log_data(FILE *fp, uint16_t red, uint16_t ir) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%u,%u\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, red, ir);
    fflush(fp);
}

static void cleanup(void) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(GPIO_LED, 0);
    gpioTerminate();
}

