/*
 * Raspberry Pi Zero W – Honeywell MICS-VZ-89TE VOC sensor monitor
 *
 * Wiring:
 *   VDD  -> 3.3 V (Pin 1)
 *   GND  -> GND  (Pin 9)
 *   SDA  -> GPIO2 / I2C bus 1 SDA (Pin 3)
 *   SCL  -> GPIO3 / I2C bus 1 SCL (Pin 5)
 *
 * I2C address: 0x10 (7-bit, as per datasheet)
 *
 * Build:  gcc -O2 -Wall -Wextra -o air_quality air_quality.c -lpigpio -lrt
 * Run:    sudo ./air_quality
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x10
#define LOG_FILE       "air_quality_log.csv"
#define SAMPLE_PERIOD  5          /* seconds between samples */
#define MAX_RETRIES    3

/* MICS-VZ-89TE register map (datasheet) */
#define REG_CMD        0x00
#define REG_DATA       0x01
#define REG_STATUS     0x02

/* Status register bits */
#define STATUS_READY   0x01
#define STATUS_ERROR   0x02

/* Command register values */
#define CMD_READ       0x01

/* Expected data length: 2 bytes TVOC + 2 bytes eCO2 + 2 bytes status */
#define DATA_LEN       6

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_cmd(uint8_t cmd)
{
    char buf[1] = { (char)cmd };
    return i2cWriteDevice(g_i2c_handle, buf, 1);
}

static int i2c_read_block(uint8_t *buf, uint8_t len)
{
    char tmp[DATA_LEN];
    int  n = i2cReadDevice(g_i2c_handle, tmp, len);
    if (n != len) {
        fprintf(stderr, "I2C read failed: expected %u bytes, got %d\n",
                len, n);
        return -1;
    }
    memcpy(buf, tmp, len);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor read                                                         */
/* ------------------------------------------------------------------ */
static int read_sensor_data(uint16_t *tvoc, uint16_t *eco2)
{
    uint8_t status = 0;
    uint8_t data[DATA_LEN];
    int     attempt;

    /* --- Issue a read command --- */
    for (attempt = 0; attempt < MAX_RETRIES; ++attempt) {
        if (i2c_write_cmd(CMD_READ) == 0)
            break;
        gpioDelay(10000); /* 10 ms back-off */
    }
    if (attempt >= MAX_RETRIES) {
        fprintf(stderr, "Failed to send read command\n");
        return -1;
    }

    /* --- Wait for data-ready status (poll up to ~1 s) --- */
    for (attempt = 0; attempt < 20; ++attempt) {
        if (i2c_read_block(&status, 1) != 0)
            return -1;
        if (status & STATUS_READY)
            break;
        gpioDelay(50000); /* 50 ms */
    }
    if (attempt >= 20) {
        fprintf(stderr, "Sensor not ready (status=0x%02X)\n", status);
        return -1;
    }
    if (status & STATUS_ERROR) {
        fprintf(stderr, "Sensor reports error status\n");
        return -1;
    }

    /* --- Read 6-byte data block --- */
    if (i2c_read_block(data, DATA_LEN) != 0)
        return -1;

    /* --- Parse big-endian 16-bit values --- */
    *tvoc = ((uint16_t)data[0] << 8) | data[1];
    *eco2 = ((uint16_t)data[2] << 8) | data[3];

    return 0;
}

/* ------------------------------------------------------------------ */
/* IAQ computation                                                     */
/* ------------------------------------------------------------------ */
static int calculate_iaq(uint16_t tvoc, uint16_t eco2)
{
    /*
     * Placeholder linear mapping – replace with calibrated curve
     * from the sensor datasheet for production use.
     */
    int iaq = (int)((tvoc * 0.1) + (eco2 * 0.05));
    if (iaq < 0)   iaq = 0;
    if (iaq > 100) iaq = 100;
    return iaq;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, int iaq, uint16_t tvoc, uint16_t eco2)
{
    time_t     t  = time(NULL);
    struct tm  tm;
    char       ts[32];

    if (localtime_r(&t, &tm) == NULL)
        return;
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0)
        return;

    fprintf(fp, "%s,%d,%u,%u\n", ts, iaq, tvoc, eco2);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    uint16_t tvoc = 0, eco2 = 0;

    /* --- Initialise pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus --- */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (handle=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open log file (append) --- */
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("fopen(" LOG_FILE ")");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_file) == 0)
        fprintf(g_log_file, "Timestamp,IAQ,TVOC_ppb,eCO2_ppm\n");

    /* --- Signal handling --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MICS-VZ-89TE air quality monitor started.\n");
    printf("Logging to %s every %d s. Press Ctrl+C to exit.\n",
           LOG_FILE, SAMPLE_PERIOD);

    /* --- Main sampling loop --- */
    while (g_running) {
        if (read_sensor_data(&tvoc, &eco2) == 0) {
            int iaq = calculate_iaq(tvoc, eco2);
            log_data(g_log_file, iaq, tvoc, eco2);
            printf("TVOC=%u ppb  eCO2=%u ppm  IAQ=%d\n", tvoc, eco2, iaq);
        } else {
            fprintf(stderr, "Sensor read failed – skipping sample.\n");
        }
        sleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

