/*
 * INMP441 I2S MEMS Microphone Capture for Raspberry Pi 4 Model B
 *
 * Hardware Connections:
 *   INMP441 SCK  -> GPIO 18 (PCM_CLK)
 *   INMP441 WS   -> GPIO 17 (PCM_FS)  -> Left/Right select
 *   INMP441 SD   -> GPIO 20 (PCM_DIN)
 *   INMP441 VDD  -> 3.3V
 *   INMP441 GND  -> GND
 *
 * Build: gcc -O2 -Wall -o audio_capture audio_capture.c -lpigpio -lm
 * Run:   sudo ./audio_capture
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/soundcard.h>
#include <pigpio.h>

#define I2S_WS_PIN      17
#define I2S_FS_PIN      18
#define I2S_DIN_PIN     20

#define AUDIO_FILE      "audio_capture.pcm"
#define SAMPLE_RATE     44100
#define BITS_PER_SAMPLE 16
#define NUM_CHANNELS    2
#define BUFFER_SIZE     4096

static volatile sig_atomic_t g_terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    g_terminate = 1;
}

static int init_i2s(void) {
    int fd = open("/dev/snd/pcmC0D0c", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening ALSA capture device: %s\n", strerror(errno));
        return -1;
    }

    int format = AFMT_S16_LE;
    if (ioctl(fd, SNDCTL_DSP_SETFMT, &format) < 0) {
        fprintf(stderr, "Error setting audio format: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    int channels = NUM_CHANNELS;
    if (ioctl(fd, SNDCTL_DSP_CHANNELS, &channels) < 0) {
        fprintf(stderr, "Error setting audio channels: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    int rate = SAMPLE_RATE;
    if (ioctl(fd, SNDCTL_DSP_SPEED, &rate) < 0) {
        fprintf(stderr, "Error setting audio sample rate: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

static int write_audio_data(FILE *fp, const int16_t *data, int num_samples) {
    size_t written = fwrite(data, sizeof(int16_t), (size_t)num_samples, fp);
    if (written != (size_t)num_samples) {
        fprintf(stderr, "Error writing audio data to file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

