/*
 * INMP441 I2S MEMS Microphone Capture for Raspberry Pi 4 Model B
 *
 * Hardware Connections:
 *   INMP441 SCK  -> GPIO 18 (PCM_CLK)
 *   INMP441 WS   -> GPIO 17 (PCM_FS)  -> Left/Right select
 *   INMP441 SD   -> GPIO 20 (PCM_DIN)
 *   INMP441 VDD  -> 3.3V
 *   INMP441 GND  -> GND
 *
 * Build: gcc -O2 -Wall -o audio_capture audio_capture.c -lpigpio -lm
 * Run:   sudo ./audio_capture
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/soundcard.h>
#include <pigpio.h>

#define I2S_WS_PIN      17
#define I2S_FS_PIN      18
#define I2S_DIN_PIN     20

#define AUDIO_FILE      "audio_capture.pcm"
#define SAMPLE_RATE     44100
#define BITS_PER_SAMPLE 16
#define NUM_CHANNELS    2
#define BUFFER_SIZE     4096

static volatile sig_atomic_t g_terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    g_terminate = 1;
}

static int init_i2s(void) {
    int fd = open("/dev/snd/pcmC0D0c", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening ALSA capture device: %s\n", strerror(errno));
        return -1;
    }

    int format = AFMT_S16_LE;
    if (ioctl(fd, SNDCTL_DSP_SETFMT, &format) < 0) {
        fprintf(stderr, "Error setting audio format: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    int channels = NUM_CHANNELS;
    if (ioctl(fd, SNDCTL_DSP_CHANNELS, &channels) < 0) {
        fprintf(stderr, "Error setting audio channels: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    int rate = SAMPLE_RATE;
    if (ioctl(fd, SNDCTL_DSP_SPEED, &rate) < 0) {
        fprintf(stderr, "Error setting audio sample rate: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

static int write_audio_data(FILE *fp, const int16_t *data, int num_samples) {
    size_t written = fwrite(data, sizeof(int16_t), (size_t)num_samples, fp);
    if (written != (size_t)num_samples) {
        fprintf(stderr, "Error writing audio data to file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    int i2s_fd = -1;
    FILE *audio_fp = NULL;
    int16_t *buffer = NULL;
    int ret = 1;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting up signal handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(I2S_WS_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", I2S_WS_PIN);
        goto cleanup;
    }
    if (gpioSetMode(I2S_FS_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", I2S_FS_PIN);
        goto cleanup;
    }
    if (gpioSetMode(I2S_DIN_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", I2S_DIN_PIN);
        goto cleanup;
    }

    i2s_fd = init_i2s();
    if (i2s_fd < 0) {
        goto cleanup;
    }

    audio_fp = fopen(AUDIO_FILE, "wb");
    if (audio_fp == NULL) {
        fprintf(stderr, "Error opening audio file '%s': %s\n", AUDIO_FILE, strerror(errno));
        goto cleanup;
    }

    buffer = (int16_t *)malloc(BUFFER_SIZE * sizeof(int16_t));
    if (buffer == NULL) {
        fprintf(stderr, "Error allocating memory for audio buffer\n");
        goto cleanup;
    }

    printf("Audio capture started. Press Ctrl+C to stop.\n");

    while (!g_terminate) {
        int bytes_read = read(i2s_fd, buffer, BUFFER_SIZE * sizeof(int16_t));
        if (bytes_read < 0) {
            if (errno == EINTR) {
                continue;
            }
            fprintf(stderr, "Error reading audio data: %s\n", strerror(errno));
            break;
        }

        if (bytes_read == 0) {
            continue;
        }

        int num_samples = bytes_read / sizeof(int16_t);
        if (write_audio_data(audio_fp, buffer, num_samples) < 0) {
            break;
        }
    }

    printf("\nAudio capture stopped.\n");
    ret = 0;

cleanup:
    if (audio_fp != NULL) {
        fclose(audio_fp);
    }
    if (i2s_fd >= 0) {
        close(i2s_fd);
    }
    if (buffer != NULL) {
        free(buffer);
    }
    gpioTerminate();
