#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define FLAME_SENSOR_PIN 4
#define FAN_PWM_PIN 18
#define PWM_FREQUENCY 100
#define PWM_RANGE 100
#define DEBOUNCE_DELAY_US 50000
#define POLL_DELAY_US 50000
#define SENSOR_TIMEOUT_US 1000000

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static void log_event(const char *event_type) {
    if (log_file == NULL) return;
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }
    fprintf(log_file, "%s - %s\n", timestamp, event_type);
    fflush(log_file);
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set flame sensor pin mode\n");
        return -1;
    }
    if (gpioSetMode(FAN_PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set fan PWM pin mode\n");
        return -1;
    }
    if (gpioSetPWMfrequency(FAN_PWM_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        return -1;
    }
    if (gpioSetPWMrange(FAN_PWM_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        return -1;
    }
    if (gpioPWM(FAN_PWM_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialize PWM to 0\n");
        return -1;
    }
    return 0;
}

static void cleanup_gpio(void) {
    gpioPWM(FAN_PWM_PIN, 0);
    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetMode(FAN_PWM_PIN, PI_INPUT);
    gpioTerminate();
}

static int read_flame_sensor(void) {
    int value = gpioRead(FLAME_SENSOR_PIN);
    if (value < 0) {
        fprintf(stderr, "Failed to read flame sensor pin\n");
        return -1;
    }
    return value;
}

static void control_fan(int flame_detected) {
    if (flame_detected) {
        if (gpioPWM(FAN_PWM_PIN, 100) != 0) {
            fprintf(stderr, "Failed to set PWM duty cycle\n");
        }
    } else {
        if (gpioPWM(FAN_PWM_PIN, 0) != 0) {
            fprintf(stderr, "Failed to set PWM duty cycle\n");
        }
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (initialize_gpio() != 0) {
        return 1;
    }

    log_file = fopen("flame_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup_gpio();
        return 1;
    }

    log_event("System started");

    int last_stable_state = 1;
    int debounce_counter = 0;
    int flame_detected = 0;
    uint32_t last_valid_read_tick = gpioTick();

    while (program_running) {
        int sensor_value = read_flame_sensor();
        if (sensor_value < 0) {
            fprintf(stderr, "Sensor read error, continuing...\n");
            gpioDelay(POLL_DELAY_US);
            continue;
        }
        last_valid_read_tick = gpioTick();

        if (sensor_value != last_stable_state) {
            debounce_counter++;
            if (debounce_counter >= 2) {
                last_stable_state = sensor_value;
                debounce_counter = 0;
            }
        } else {
            debounce_counter = 0;
        }

        if (last_stable_state == 0 && !flame_detected) {
            flame_detected = 1;
            log_event("Flame detected");
            control_fan(1);
        } else if (last_stable_state == 1 && flame_detected) {
            flame_detected = 0;
            log_event("Flame ended");
            control_fan(0);
        }

        gpioDelay(POLL_DELAY_US);
    }

    log_event("Program shutdown");
    cleanup_gpio();
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    return 0;
}

