#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define FRAME_TRIGGER_PIN 23
#define DATA_READY_PIN 24
#define SPI_BYTES_PER_FRAME 32768
#define LOG_FILE_NAME "radar_data.log"
#define MAGIC_NUMBER 4144
#define CONFIG_MAGIC 0x12345678

typedef struct {
    float start_freq;
    float end_freq;
    int num_chirps;
    int num_samples;
} RadarConfig;

typedef struct {
    uint32_t magic;
    uint32_t config_magic;
    RadarConfig config;
    uint8_t reserved[24];
} LogHeader;

typedef struct {
    uint32_t timestamp_sec;
    uint32_t timestamp_nsec;
    uint32_t frame_number;
} FrameData;

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_spi(void) {
    spi_fd = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI channel %d: %s\n", SPI_CHANNEL, pigpio_error(spi_fd));
        return -1;
    }
    return 0;
}

static int init_gpio(void) {
    if (gpioSetMode(FRAME_TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", FRAME_TRIGGER_PIN);
        return -1;
    }
    if (gpioSetMode(DATA_READY_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error setting GPIO %d as input\n", DATA_READY_PIN);
        return -1;
    }
    if (gpioSetPullUpDown(DATA_READY_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Error setting pull-down on GPIO %d\n", DATA_READY_PIN);
        return -1;
    }
    return 0;
}

static int init_log_file(void) {
    log_file = fopen(LOG_FILE_NAME, "wb");
    if (!log_file) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE_NAME, strerror(errno));
        return -1;
    }
    return 0;
}

static int write_log_header(const RadarConfig *config) {
    LogHeader header;
    header.magic = MAGIC_NUMBER;
    header.config_magic = CONFIG_MAGIC;
    header.config = *config;
    memset(header.reserved, 0, sizeof(header.reserved));
    if (fwrite(&header, sizeof(header), 1, log_file) != 1) {
        fprintf(stderr, "Error writing log header: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int write_frame_data(const FrameData *frame) {
    if (fwrite(frame, sizeof(*frame), 1, log_file) != 1) {
        fprintf(stderr, "Error writing frame data: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_spi_frame(uint8_t *buffer, int len) {
    int bytes_read = spiRead(spi_fd, (char *)buffer, len);
    if (bytes_read != len) {
        fprintf(stderr, "Error reading SPI frame: expected %d bytes, got %d\n", len, bytes_read);
        return -1;
    }
    return 0;
}

static int capture_and_log_frame(const RadarConfig *config) {
    uint8_t *frame_data = malloc(SPI_BYTES_PER_FRAME);
    if (!frame_data) {
        fprintf(stderr, "Error allocating memory for frame data\n");
        return -1;
    }

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    FrameData frame = {
        .timestamp_sec = (uint32_t)ts.tv_sec,
        .timestamp_nsec = (uint32_t)ts.tv_nsec,
        .frame_number = 0
    };

    if (write_frame_data(&frame) != 0) {
        free(frame_data);
        return -1;
    }

    if (read_spi_frame(frame_data, SPI_BYTES_PER_FRAME) != 0) {
        free(frame_data);
        return -1;
    }

    if (fwrite(frame_data, SPI_BYTES_PER_FRAME, 1, log_file) != 1) {
        fprintf(stderr, "Error writing frame data to log: %s\n", strerror(errno));
        free(frame_data);
        return -1;
    }

    free(frame_data);
    return 0;
}

static void cleanup(void) {
    if (spi_fd >= 0) {
        spiClose(spi_fd);
        spi_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting up signal handlers: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (init_spi() != 0) {
        cleanup();
        return 1;
    }

    if (init_gpio() != 0) {
        cleanup();
        return 1;
    }

    if (init_log_file() != 0) {
        cleanup();
        return 1;
    }

    RadarConfig config = {
        .start_freq = 77.0f,
        .end_freq = 79.0f,
        .num_chirps = 64,
        .num_samples = 256
    };

    if (write_log_header(&config) != 0) {
        cleanup();
        return 1;
    }

    printf("Radar data acquisition started. Press Ctrl+C to stop.\n");

