/*
 * KY-026 Flame Sensor - State Change Logger
 * Board:  Raspberry Pi Zero W
 * Library: pigpio (modern, actively maintained)
 *
 * Wiring:
 *   KY-026 VCC -> 3.3 V (Pin 1)
 *   KY-026 GND -> GND   (Pin 6)
 *   KY-026 D0  -> GPIO20 (BCM 20, Pin 38)
 *
 * Build:
 *   gcc -Wall -Wextra -O2 -o flame_logger flame_logger.c -lpigpio -lrt
 * Run:
 *   sudo ./flame_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FLAME_SENSOR_GPIO 20
#define LOG_FILE          "flame_log.txt"
#define POLL_DELAY_US     100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_state_change(int flame_detected)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    time_t rawtime = time(NULL);
    if (rawtime == (time_t)-1) {
        perror("time()");
        fclose(fp);
        return -1;
    }

    struct tm tm_utc;
    if (gmtime_r(&rawtime, &tm_utc) == NULL) {
        fprintf(stderr, "gmtime_r() failed\n");
        fclose(fp);
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ",
                 &tm_utc) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s - Flame %s\n", timestamp,
                flame_detected ? "Detected" : "Cleared") < 0) {
        perror("fprintf()");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose()");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure GPIO20 as input ---- */
    if (gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_INPUT) failed\n",
                FLAME_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Read initial state ---- */
    int last_state = gpioRead(FLAME_SENSOR_GPIO);
    if (last_state < 0) {
        fprintf(stderr, "gpioRead(%d) failed\n", FLAME_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Monitoring KY-026 flame sensor on GPIO%d. "
           "Press Ctrl+C to exit.\n", FLAME_SENSOR_GPIO);

    /* ---- Main polling loop ---- */
    while (g_running) {
        int current_state = gpioRead(FLAME_SENSOR_GPIO);
        if (current_state < 0) {
            fprintf(stderr, "gpioRead(%d) failed\n", FLAME_SENSOR_GPIO);
            break;
        }

        if (current_state != last_state) {
            if (log_state_change(current_state) != 0) {
                fprintf(stderr, "Failed to log state change\n");
            } else {
                printf("State change logged: %s\n",
                       current_state ? "Detected" : "Cleared");
            }
            last_state = current_state;
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* ---- Cleanup ---- */
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

