code:
/*
 * OPT3001 Ambient Light Sensor Logger for Raspberry Pi Zero W
 *
 * Wiring:
 *   OPT3001 SDA -> GPIO2 (I2C bus 1 SDA, pin 3)
 *   OPT3001 SCL -> GPIO3 (I2C bus 1 SCL, pin 5)
 *   OPT3001 VDD -> 3.3 V (pin 1)
 *   OPT3001 GND -> GND  (pin 6)
 *
 * Build: gcc -O2 -Wall -o opt3001_logger opt3001_logger.c -lpigpio -lrt
 * Run:   sudo ./opt3001_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define OPT3001_ADDR   0x44

/* OPT3001 register addresses */
#define REG_RESULT     0x00
#define REG_CONFIG     0x01

/*
 * Configuration word (0x8410):
 *   Bits 15-12  RN[3:0] = 0x00  -> automatic full-scale range
 *   Bits 11-10  CT[1:0] = 0x01  -> continuous conversion
 *   Bit  9      FC    = 0       -> fault count = 1
 *   Bit  8      M[1:0] = 0x00  -> continuous mode
 *   Bits 7-4    L[3:0] = 0x00  -> no fault flag
 *   Bit  3      POL   = 0
 *   Bit  2      ME    = 0
 *   Bit  1      FC    = 0
 *   Bit  0      CR    = 1       -> active
 */
#define CONFIG_WORD    0x8410

#define DATA_FILE      "light_data.txt"
#define SAMPLE_US     100000   /* 100 ms conversion time */
#define MAX_RETRIES    3

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit value to a 16-bit register (pigpio i2cWriteWordData
 * sends the register address as the first byte, then the data, which
 * matches the OPT3001 register protocol). */
static int write_reg16(int handle, uint8_t reg, uint16_t value)
{
    int rc = i2cWriteWordData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteWordData(reg=0x%02X, val=0x%04X) failed: %d\n",
                reg, value, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit value from a 16-bit register. */
static int read_reg16(int handle, uint8_t reg, uint16_t *out)
{
    int rc = i2cReadWordData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadWordData(reg=0x%02X) failed: %d\n", reg, rc);
        return -1;
    }
    *out = (uint16_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
static int init_opt3001(int handle)
{
    if (write_reg16(handle, REG_CONFIG, CONFIG_WORD) != 0) {
        fprintf(stderr, "[ERROR] Failed to write OPT3001 configuration.\n");
        return -1;
    }

    /* Allow the first conversion to complete before sampling. */
    gpioDelay(100000); /* 100 ms */
    return 0;
}

/* ------------------------------------------------------------------ */
static int read_lux(int handle, float *lux_out)
{
    uint16_t raw;
    if (read_reg16(handle, REG_RESULT, &raw) != 0)
        return -1;

    uint16_t exponent = (raw >> 12) & 0x0F;
    uint16_t mantissa = raw & 0x0FFF;

    if (exponent == 0x0F) {
        fprintf(stderr, "[WARN] OPT3001 exponent field saturated (0x%02X).\n", exponent);
        return -1;
    }

    float value = (float)mantissa * (0.01f * (float)(1u << exponent));
    *lux_out = value;
    return 0;
}

/* ------------------------------------------------------------------ */
static void log_data(float lux)
{
    FILE *fp = fopen(DATA_FILE, "a");
    if (!fp) {
        perror("[ERROR] fopen(" DATA_FILE ")");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("[ERROR] localtime_r");
        fclose(fp);
        return;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s, %.2f\n", ts, lux);
    fclose(fp);
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("[ERROR] sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[ERROR] sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "[ERROR] pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, OPT3001_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, OPT3001_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_opt3001(g_i2c_handle) != 0) {
        fprintf(stderr, "[ERROR] OPT3001 initialization failed (sensor may be absent).\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("OPT3001 logger started. Logging to %s every 100 ms. Press Ctrl+C to stop.\n",
           DATA_FILE);

    while (g_running) {
        float lux = 0.0f;
        int ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (read_lux(g_i2c_handle, &lux) == 0) {
                ok = 1;
                break;
            }
            gpioDelay(10000); /* 10 ms backoff before retry */
        }

        if (ok) {
            log_data(lux);
            printf("Lux: %.2f\n", lux);
        } else {
            fprintf(stderr, "[WARN] Sensor read failed after %d attempts.\n", MAX_RETRIES);
        }

        gpioDelay(SAMPLE_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

