/*
 * SainSmart IR Flame Detection Sensor Module reader for Raspberry Pi 3 B+
 * Library: libgpiod (v2 API)
 *
 * Wiring:
 *   Sensor VCC  -> Pi 3.3 V (pin 1)
 *   Sensor GND  -> Pi GND   (pin 9)
 *   Sensor DOUT -> Pi GPIO17 (BCM 17, pin 11, active-low)
 *
 * Build:
 *   gcc -Wall -Wextra -O2 -o flame_detect flame_detect.c -lgpiod
 *
 * Run:
 *   ./flame_detect
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME  "gpiochip0"
#define GPIO_LINE_OFFSET 17
#define POLL_INTERVAL_SEC 1

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handler(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    return 0;
}

static void format_timestamp(char *buf, size_t len)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        snprintf(buf, len, "UNKNOWN");
        return;
    }
    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        snprintf(buf, len, "UNKNOWN");
        return;
    }
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tm_info);
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line_request *request = NULL;
    struct gpiod_line_settings *settings = NULL;
    struct gpiod_line_config *line_cfg = NULL;
    struct gpiod_request_config *req_cfg = NULL;
    char ts_buf[32];
    int ret = EXIT_FAILURE;

    if (install_signal_handler() != 0) {
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Configure the line as input with pull-up bias (active-low sensor) */
    settings = gpiod_line_settings_new();
    if (settings == NULL) {
        fprintf(stderr, "Failed to allocate line settings: %s\n", strerror(errno));
        goto cleanup;
    }

    gpiod_line_settings_set_direction(settings, GPIOD_LINE_DIRECTION_INPUT);
    gpiod_line_settings_set_bias(settings, GPIOD_LINE_BIAS_PULL_UP);

    /* Build a line config for the single offset */
    line_cfg = gpiod_line_config_new();
    if (line_cfg == NULL) {
        fprintf(stderr, "Failed to allocate line config: %s\n", strerror(errno));
        goto cleanup;
    }

    unsigned int offsets[1] = { GPIO_LINE_OFFSET };
    if (gpiod_line_config_add_line_settings(line_cfg, offsets, 1, settings) != 0) {
        fprintf(stderr, "Failed to add line settings: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Build a request config with consumer label */
    req_cfg = gpiod_request_config_new();
    if (req_cfg == NULL) {
        fprintf(stderr, "Failed to allocate request config: %s\n", strerror(errno));
        goto cleanup;
    }
    gpiod_request_config_set_consumer(req_cfg, "flame-sensor");

    /* Request the line */
    request = gpiod_chip_request_lines(chip, req_cfg, line_cfg);
    if (request == NULL) {
        fprintf(stderr, "Failed to request GPIO line %u: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    printf("Flame sensor monitoring started on GPIO %u. Press Ctrl+C to exit.\n",
           GPIO_LINE_OFFSET);
    fflush(stdout);

    /* Main polling loop */
    while (g_running) {
        int value = gpiod_line_request_get_value(request, GPIO_LINE_OFFSET);
        if (value < 0) {
            fprintf(stderr, "Failed to read GPIO line %u: %s\n",
                    GPIO_LINE_OFFSET, strerror(errno));
            break;
        }

        /* SainSmart IR flame sensor is active-low: 0 = flame detected, 1 = no flame */
        format_timestamp(ts_buf, sizeof(ts_buf));
        printf("%s Flame Detected: %s\n", ts_buf, (value == 0) ? "YES" : "NO");
        fflush(stdout);

        sleep(POLL_INTERVAL_SEC);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (request != NULL) {
        gpiod_line_request_release(request);
    }
    if (req_cfg != NULL) {
        gpiod_request_config_free(req_cfg);
    }
    if (line_cfg != NULL) {
        gpiod_line_config_free(line_cfg);
    }
    if (settings != NULL) {
        gpiod_line_settings_free(settings);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    if (ret == EXIT_SUCCESS) {
        printf("\nExiting gracefully.\n");
    }
    return ret;
}

