#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_MS 100

static const unsigned int channel_pins[NUM_CHANNELS] = {2, 3, 4, 5, 6, 7, 8, 9};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void print_timestamp(void) {
    time_t rawtime;
    struct tm *timeinfo;
    char buffer[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo != NULL) {
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);
        printf("[%s] ", buffer);
    }
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_CHANNELS];
    int values[NUM_CHANNELS];
    int ret = EXIT_FAILURE;

    for (int i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = NULL;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Failed to register SIGINT handler");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        perror("Failed to open gpiochip0");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = gpiod_chip_get_line(chip, channel_pins[i]);
        if (lines[i] == NULL) {
            fprintf(stderr, "Failed to get GPIO line %u\n", channel_pins[i]);
            goto cleanup;
        }
    }

    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (gpiod_line_request_input(lines[i], "ttp226-touch") < 0) {
            fprintf(stderr, "Failed to request GPIO line %u as input\n", channel_pins[i]);
            goto cleanup;
        }
    }

    printf("TTP226 Touch Sensor Reader started. Press Ctrl+C to exit.\n");

    while (program_running) {
        print_timestamp();

        for (int i = 0; i < NUM_CHANNELS; i++) {
            int val = gpiod_line_get_value(lines[i]);
            if (val < 0) {
                fprintf(stderr, "Failed to read GPIO line %u\n", channel_pins[i]);
                goto cleanup;
            }
            values[i] = val;
        }

        printf("OUT1: %d, OUT2: %d, OUT3: %d, OUT4: %d, OUT5: %d, OUT6: %d, OUT7: %d, OUT8: %d\n",
               values[0], values[1], values[2], values[3],
               values[4], values[5], values[6], values[7]);

        fflush(stdout);
        usleep(POLL_INTERVAL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (lines[i] != NULL) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    return ret;
}

