#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_1_GPIO 4
#define SENSOR_2_GPIO 5
#define POLL_DELAY_US 500000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Warning: could not register SIGINT handler.\n");
    }

    if (gpioSetMode(SENSOR_1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input.\n", SENSOR_1_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input.\n", SENSOR_2_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("TMAG5110 Hall-Effect Latch Sensor Monitor\n");
    printf("Sensor 1: BCM GPIO%d | Sensor 2: BCM GPIO%d\n", SENSOR_1_GPIO, SENSOR_2_GPIO);
    printf("Press Ctrl+C to exit.\n\n");

    while (running) {
        int s1 = gpioRead(SENSOR_1_GPIO);
        int s2 = gpioRead(SENSOR_2_GPIO);

        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "Error: GPIO read failed (s1=%d, s2=%d).\n", s1, s2);
            break;
        }

        printf("Sensor 1: %s | Sensor 2: %s\n",
               s1 == 0 ? "HIGH (magnet detected)" : "LOW (no magnet)",
               s2 == 0 ? "HIGH (magnet detected)" : "LOW (no magnet)");

        usleep(POLL_DELAY_US);
    }

    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

