code:
/*
 * TTP226 8-channel capacitive touch sensor reader for Raspberry Pi 4 Model B.
 *
 * Wiring (TTP226 module, 3.3 V logic):
 *   VCC  -> 3.3 V (pin 1)
 *   GND  -> GND  (pin 9)
 *   A0   -> GPIO2  (BCM 2, physical pin 3)
 *   A1   -> GPIO3  (BCM 3, physical pin 5)
 *   A2   -> GPIO4  (BCM 4, physical pin 7)
 *   A3   -> GPIO17 (BCM 17, physical pin 11)
 *   A4   -> GPIO27 (BCM 27, physical pin 13)
 *   A5   -> GPIO22 (BCM 22, physical pin 15)
 *   A6   -> GPIO10 (BCM 10, physical pin 19)
 *   A7   -> GPIO9  (BCM 9,  physical pin 21)
 *
 * Build:  gcc -O2 -Wall -Wextra -o ttp226_reader ttp226_reader.c -lpigpio -lrt
 * Run:    sudo ./ttp226_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define NUM_CHANNELS 8
#define POLL_DELAY_US 50000          /* 50 ms */
#define TIMESTAMP_LEN 32

static const int sensor_pins[NUM_CHANNELS] = {2, 3, 4, 17, 27, 22, 10, 9};

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        snprintf(buf, len, "1970-01-01T00:00:00Z");
        return;
    }
    struct tm tmv;
    if (localtime_r(&now, &tmv) == NULL) {
        snprintf(buf, len, "1970-01-01T00:00:00Z");
        return;
    }
    strftime(buf, len, "%Y-%m-%dT%H:%M:%SZ", &tmv);
}

static void log_error(const char *msg)
{
    char ts[TIMESTAMP_LEN];
    get_timestamp(ts, sizeof(ts));
    fprintf(stderr, "%s ERROR: %s\n", ts, msg);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Install signal handlers for graceful shutdown ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        return EXIT_FAILURE;
    }

    /* ---- Configure each sensor pin as input ---- */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        int pin = sensor_pins[i];
        if (gpioSetMode(pin, PI_INPUT) != 0) {
            char msg[128];
            snprintf(msg, sizeof(msg),
                     "gpioSetMode failed for BCM pin %d", pin);
            log_error(msg);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        /* Disable internal pull-up/pull-down so the sensor drives the line. */
        if (gpioSetPullUpDown(pin, PI_PUD_OFF) != 0) {
            char msg[128];
            snprintf(msg, sizeof(msg),
                     "gpioSetPullUpDown failed for BCM pin %d", pin);
            log_error(msg);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    printf("TTP226 touch sensor reader started. Press Ctrl-C to exit.\n");
    printf("Timestamp,Channel0,Channel1,Channel2,Channel3,Channel4,Channel5,Channel6,Channel7\n");
    fflush(stdout);

    /* ---- Main polling loop ---- */
    while (g_running) {
        char ts[TIMESTAMP_LEN];
        get_timestamp(ts, sizeof(ts));

        int values[NUM_CHANNELS];
        bool read_failed = false;

        for (int i = 0; i < NUM_CHANNELS; i++) {
            int v = gpioRead(sensor_pins[i]);
            if (v < 0) {
                char msg[128];
                snprintf(msg, sizeof(msg),
                         "gpioRead failed for BCM pin %d", sensor_pins[i]);
                log_error(msg);
                read_failed = true;
                values[i] = 0;   /* report 0 on error so CSV stays valid */
            } else {
                values[i] = v;
            }
        }

        if (read_failed) {
            /* Continue running; transient read errors are logged. */
        } else {
            printf("%s,%d,%d,%d,%d,%d,%d,%d,%d\n",
                   ts,
                   values[0], values[1], values[2], values[3],
                   values[4], values[5], values[6], values[7]);
            fflush(stdout);
        }

        /* Sleep 50 ms; gpioDelay is a busy-wait but acceptable here. */
        gpioDelay(POLL_DELAY_US);
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down...\n");
    gpioTerminate();
    return EXIT_SUCCESS;
}

