#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TILT_SENSOR_GPIO 4
#define POLL_DELAY_US    100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

int main(void)
{
    int last_state = -1;
    int rc;

    /* Install SIGINT handler for clean shutdown on Ctrl-C */
    if (signal(SIGINT, sigint_handler) == SIG_ERR) {
        perror("signal");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO4 as input with internal pull-up */
    if (gpioSetMode(TILT_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", TILT_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(TILT_SENSOR_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to enable pull-up on GPIO%d.\n", TILT_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Tilt sensor monitoring started on GPIO%d. Press Ctrl-C to exit.\n",
           TILT_SENSOR_GPIO);
    fflush(stdout);

    while (g_running) {
        rc = gpioRead(TILT_SENSOR_GPIO);

        if (rc < 0) {
            fprintf(stderr, "Error: gpioRead failed on GPIO%d (rc=%d).\n",
                    TILT_SENSOR_GPIO, rc);
            gpioTerminate();
            return EXIT_FAILURE;
        }

        if (rc != last_state) {
            if (rc == 0) {
                printf("Tilted\n");
            } else if (rc == 1) {
                printf("Not Tilted\n");
            } else {
                fprintf(stderr, "Error: unexpected GPIO value %d.\n", rc);
            }
            fflush(stdout);
            last_state = rc;
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* Clean shutdown */
    printf("\nExiting gracefully...\n");
    fflush(stdout);
    gpioTerminate();
    return EXIT_SUCCESS;
}

