#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define SI1145_I2C_ADDR 0x60
#define SI1145_REG_PART_ID 0x00
#define SI1145_REG_HW_KEY 0x07
#define SI1145_REG_UCOEF0 0x1B
#define SI1145_REG_UCOEF1 0x1C
#define SI1145_REG_UCOEF2 0x1D
#define SI1145_REG_UCOEF3 0x1E
#define SI1145_REG_ALS_VIS_DATA0 0x22
#define SI1145_REG_ALS_VIS_DATA1 0x23
#define SI1145_REG_UV_INDEX0 0x2C
#define SI1145_REG_UV_INDEX1 0x2D
#define SI1145_REG_COMMAND 0x30
#define SI1145_CMD_RESET 0x01
#define SI1145_CMD_ALS_FORCE 0x06
#define SI1145_CMD_UV_FORCE 0x05
#define SI1145_CMD_ALS_UV_FORCE 0x07
#define SI1145_EXPECTED_PART_ID 0x45

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        return -1;
    }
    *value = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int si1145_init(int fd) {
    uint8_t part_id;
    if (i2c_read_reg8(fd, SI1145_REG_PART_ID, &part_id) < 0) {
        fprintf(stderr, "Error: Failed to read Part ID (I2C bus error).\n");
        return -1;
    }
    if (part_id != SI1145_EXPECTED_PART_ID) {
        fprintf(stderr, "Error: Unexpected Part ID 0x%02X (expected 0x%02X). Sensor not present?\n", part_id, SI1145_EXPECTED_PART_ID);
        return -1;
    }
    if (i2c_write_reg8(fd, SI1145_REG_COMMAND, SI1145_CMD_RESET) < 0) {
        fprintf(stderr, "Error: Failed to reset Si1145.\n");
        return -1;
    }
    usleep(10000);
    if (i2c_write_reg8(fd, SI1145_REG_HW_KEY, 0x17) < 0) {
        fprintf(stderr, "Error: Failed to write HW_KEY.\n");
        return -1;
    }
    if (i2c_write_reg8(fd, SI1145_REG_UCOEF0, 0x7B) < 0 ||
        i2c_write_reg8(fd, SI1145_REG_UCOEF1, 0x62) < 0 ||
        i2c_write_reg8(fd, SI1145_REG_UCOEF2, 0x01) < 0 ||
        i2c_write_reg8(fd, SI1145_REG_UCOEF3, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write UV coefficients.\n");
        return -1;
    }
    return 0;
}

static int si1145_read_uv_index(int fd, float *uv_index) {
    uint8_t uv0, uv1;
    if (i2c_write_reg8(fd, SI1145_REG_COMMAND, SI1145_CMD_UV_FORCE) < 0) {
        return -1;
    }
    usleep(10000);
    if (i2c_read_reg8(fd, SI1145_REG_UV_INDEX0, &uv0) < 0) {
        return -1;
    }
    if (i2c_read_reg8(fd, SI1145_REG_UV_INDEX1, &uv1) < 0) {
        return -1;
    }
    *uv_index = (float)((uv1 << 8) | uv0) / 100.0f;
    return 0;
}

static int si1145_read_als_visible(int fd, uint16_t *als_visible) {
    if (i2c_write_reg8(fd, SI1145_REG_COMMAND, SI1145_CMD_ALS_FORCE) < 0) {
        return -1;
    }
    usleep(10000);
    if (i2c_read_reg16(fd, SI1145_REG_ALS_VIS_DATA0, als_visible) < 0) {
        return -1;
    }
    return 0;
}

static void log_data(float uv_index, uint16_t als_visible) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s,%.2f,%u\n", timestamp, uv_index, als_visible);
    fflush(log_file);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open /dev/i2c-1");
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, SI1145_I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }
    if (si1145_init(i2c_fd) < 0) {
        fprintf(stderr, "Si1145 initialization failed.\n");
        close(i2c_fd);
        return 1;
    }
    log_file = fopen("uv_als_log.csv", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,uv_index,als_visible\n");
        fflush(log_file);
    }
    printf("Si1145 initialized. Logging to uv_als_log.csv. Press Ctrl+C to stop.\n");
    while (running) {
        float uv_index;
        uint16_t als_visible;
        if (si1145_read_uv_index(i2c_fd, &uv_index) < 0) {
            fprintf(stderr, "Error reading UV index.\n");
        } else if (si1145_read_als_visible(i2c_fd, &als_visible) < 0) {
            fprintf(stderr, "Error reading ALS visible.\n");
        } else {
            printf("UV Index: %.2f, Visible ALS: %u\n", uv_index, als_visible);
            log_data(uv_index, als_visible);
        }
        sleep(1);
    }
    printf("\nShutting down...\n");
    if (log_file) fclose(log_file);
    if (i2c_fd >= 0) close(i2c_fd);
    return 0;
}

