#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS        "/dev/i2c-1"
#define SENSOR1_ADDR   0x60
#define SENSOR2_ADDR   0x61
#define ALARM_GPIO     17
#define FLOW_THRESHOLD 0.5f
#define LOG_FILE       "flow_log.txt"
#define MEAS_DELAY_US  100000   /* 100 ms start-up delay */
#define SAMPLE_PERIOD  1        /* seconds between samples */

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* Sensirion 8-bit CRC: poly 0x31, init 0xFF */
static uint8_t sensirion_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_cmd(int fd, uint8_t addr, uint8_t cmd)
{
    if (ioctl(fd, I2C_SLAVE, addr) < 0) return -1;
    if (write(fd, &cmd, 1) != 1) return -1;
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t addr, uint8_t *buf, size_t len)
{
    if (ioctl(fd, I2C_SLAVE, addr) < 0) return -1;
    ssize_t n = read(fd, buf, len);
    return (n == (ssize_t)len) ? 0 : -1;
}

static int read_flow_rate(int fd, uint8_t addr, float *flow_out)
{
    uint8_t cmd = 0x3615;          /* continuous measurement, clock stretching */
    uint8_t buf[3];

    if (i2c_write_cmd(fd, addr, cmd) < 0) return -1;
    usleep(MEAS_DELAY_US);

    if (i2c_read_bytes(fd, addr, buf, 3) < 0) return -1;

    if (sensirion_crc8(&buf[0], 2) != buf[2]) return -1;

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *flow_out = (float)raw / 60.0f;   /* SLF3S-0600F: 1 LSB = 0.01667 ml/min */
    return 0;
}

static void log_flow_rate(float avg)
{
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(g_log_fp, "%s, Average Flow Rate: %.2f ml/min\n", ts, avg);
    fflush(g_log_fp);
}

static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioWrite(ALARM_GPIO, 0);
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        perror("open " I2C_BUS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(ALARM_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", ALARM_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(ALARM_GPIO, 0);

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("fopen " LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Start continuous measurement on both sensors */
    if (i2c_write_cmd(g_i2c_fd, SENSOR1_ADDR, 0x3615) < 0) {
        fprintf(stderr, "Failed to start sensor 1\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (i2c_write_cmd(g_i2c_fd, SENSOR2_ADDR, 0x3615) < 0) {
        fprintf(stderr, "Failed to start sensor 2\n");
        cleanup();
        return EXIT_FAILURE;
    }
    usleep(MEAS_DELAY_US);

    while (g_running) {
        float f1 = 0.0f, f2 = 0.0f;
        int   ok1 = read_flow_rate(g_i2c_fd, SENSOR1_ADDR, &f1);
        int   ok2 = read_flow_rate(g_i2c_fd, SENSOR2_ADDR, &f2);

        if (ok1 < 0) {
            fprintf(stderr, "Sensor 1 read error\n");
            fprintf(g_log_fp, "Sensor 1 read error\n");
            fflush(g_log_fp);
        }
        if (ok2 < 0) {
            fprintf(stderr, "Sensor 2 read error\n");
            fprintf(g_log_fp, "Sensor 2 read error\n");
            fflush(g_log_fp);
        }

        float avg = 0.0f;
        int   count = 0;
        if (ok1 == 0) { avg += f1; count++; }
        if (ok2 == 0) { avg += f2; count++; }
        if (count > 0) avg /= (float)count;

        log_flow_rate(avg);

        if (count > 0 && avg < FLOW_THRESHOLD)
            gpioWrite(ALARM_GPIO, 1);
        else
            gpioWrite(ALARM_GPIO, 0);

        sleep(SAMPLE_PERIOD);
    }

    cleanup();
    return EXIT_SUCCESS;
}

