#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SENSOR_PIN 4
#define BUFFER_SIZE 100
#define POLL_DELAY_US 50000

typedef struct {
    time_t timestamp;
    int obstacle_detected;
} SensorData;

static SensorData circular_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static void add_to_buffer(int obstacle_detected) {
    circular_buffer[buffer_index].timestamp = time(NULL);
    circular_buffer[buffer_index].obstacle_detected = obstacle_detected;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
}

static void print_buffer(void) {
    printf("\n--- Sensor Data Log ---\n");
    for (int i = 0; i < buffer_count; i++) {
        int idx = (buffer_index - buffer_count + i + BUFFER_SIZE) % BUFFER_SIZE;
        char time_str[32];
        struct tm *tm_info = localtime(&circular_buffer[idx].timestamp);
        if (tm_info != NULL) {
            strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);
        } else {
            strncpy(time_str, "UNKNOWN", sizeof(time_str));
            time_str[sizeof(time_str) - 1] = '\0';
        }
        printf("[%s] Obstacle Detected: %s\n", time_str,
               circular_buffer[idx].obstacle_detected ? "YES" : "NO");
    }
    printf("--- End of Log ---\n\n");
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to enable pull-up on GPIO%d.\n", SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to register SIGINT handler.\n");
    }

    printf("Obstacle avoidance sensor monitoring started on GPIO%d.\n", SENSOR_PIN);
    printf("Press Ctrl+C to exit and view the log.\n");

    while (program_running) {
        int sensor_value = gpioRead(SENSOR_PIN);
        if (sensor_value < 0) {
            fprintf(stderr, "Error: failed to read GPIO%d.\n", SENSOR_PIN);
            break;
        }

        int obstacle_detected = (sensor_value == 0) ? 1 : 0;
        add_to_buffer(obstacle_detected);

        if (obstacle_detected) {
            printf("Obstacle detected!\n");
        }

        gpioDelay(POLL_DELAY_US);
    }

    gpioTerminate();
    print_buffer();
    return EXIT_SUCCESS;
}

