#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define CSV_FILE       "fan_health.csv"
#define D7S_ADDR       0x32
#define D7S_REG_MODE   0x00
#define D7S_REG_X_LSB  0x02
#define D7S_REG_X_MSB  0x03
#define D7S_REG_Y_LSB  0x04
#define D7S_REG_Y_MSB  0x05
#define D7S_REG_Z_LSB  0x06
#define D7S_REG_Z_MSB  0x07
#define D7S_MODE_CONT  0x01
#define POLL_INTERVAL  500000
#define ACTIVATION_TIMEOUT 1000000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_csv = NULL;

static void sighandler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_acceleration(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t xl, xh, yl, yh, zl, zh;
    if (i2c_read_reg8(fd, D7S_REG_X_LSB, &xl) ||
        i2c_read_reg8(fd, D7S_REG_X_MSB, &xh) ||
        i2c_read_reg8(fd, D7S_REG_Y_LSB, &yl) ||
        i2c_read_reg8(fd, D7S_REG_Y_MSB, &yh) ||
        i2c_read_reg8(fd, D7S_REG_Z_LSB, &zl) ||
        i2c_read_reg8(fd, D7S_REG_Z_MSB, &zh)) {
        return -1;
    }
    *x = (int16_t)((xh << 8) | xl);
    *y = (int16_t)((yh << 8) | yl);
    *z = (int16_t)((zh << 8) | zl);
    return 0;
}

static int log_data(FILE *fp, int16_t x, int16_t y, int16_t z) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }
    if (fprintf(fp, "%s,%d,%d,%d\n", ts, x, y, z) < 0) {
        fprintf(stderr, "fprintf to CSV failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int ensure_csv_header(FILE *fp) {
    long pos = ftell(fp);
    if (pos < 0) {
        fprintf(stderr, "ftell failed: %s\n", strerror(errno));
        return -1;
    }
    if (pos == 0) {
        if (fprintf(fp, "timestamp,x,y,z\n") < 0) {
            fprintf(stderr, "fprintf header failed: %s\n", strerror(errno));
            return -1;
        }
        if (fflush(fp) != 0) {
            fprintf(stderr, "fflush header failed: %s\n", strerror(errno));
            return -1;
        }
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, D7S_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n", D7S_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return 1;
    }

    if (i2c_write_reg8(g_i2c_fd, D7S_REG_MODE, D7S_MODE_CONT) != 0) {
        fprintf(stderr, "Failed to set D7S mode\n");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return 1;
    }

    g_csv = fopen(CSV_FILE, "a+");
    if (!g_csv) {
        fprintf(stderr, "fopen(%s) failed: %s\n", CSV_FILE, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return 1;
    }

    if (ensure_csv_header(g_csv) != 0) {
        fclose(g_csv);
        g_csv = NULL;
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return 1;
    }

    printf("D7S vibration sensor logging started. Press Ctrl+C to stop.\n");

    struct timespec start, now;
    clock_gettime(CLOCK_MONOTONIC, &start);

    while (g_running) {
        clock_gettime(CLOCK_MONOTONIC, &now);
        long elapsed_us = (now.tv_sec - start.tv_sec) * 1000000L +
                          (now.tv_nsec - start.tv_nsec) / 1000L;

        if (elapsed_us >= ACTIVATION_TIMEOUT) {
            fprintf(stderr, "Error: D7S sensor did not become active within %d ms\n",
                    ACTIVATION_TIMEOUT / 1000);
            break;
        }

        int16_t x, y, z;
        if (read_acceleration(g_i2c_fd, &x, &y, &z) == 0) {
            if (log_data(g_csv, x, y, z) != 0) {
                fprintf(stderr, "Warning: failed to log data\n");
            }
        } else {
            fprintf(stderr, "Warning: failed to read acceleration data\n");
        }

        usleep(POLL_INTERVAL);
    }

    printf("\nShutting down...\n");

    if (g_csv) {
        if (fclose(g_csv) != 0) {
            fprintf(stderr, "fclose failed: %s\n", strerror(errno));
        }
        g_csv = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }

    printf("Resources released. Goodbye.\n");
    return 0;
}

