        if (fflush(fp) != 0) {
            fprintf(stderr, "fflush header failed: %s\n", strerror(errno));
            return -1;
        }
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, D7S_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n", D7S_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return 1;
    }

    if (i2c_write_reg8(g_i2c_fd, D7S_REG_MODE, D7S_MODE_CONT) != 0) {
        fprintf(stderr, "Failed to set D7S mode\n");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return 1;
    }

    g_csv = fopen(CSV_FILE, "a+");
    if (!g_csv) {
        fprintf(stderr, "fopen(%s) failed: %s\n", CSV_FILE, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return 1;
    }

    if (ensure_csv_header(g_csv) != 0) {
        fclose(g_csv);
        g_csv = NULL;
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return 1;
    }

    printf("D7S vibration sensor logging started. Press Ctrl+C to stop.\n");

    struct timespec start, now;
    clock_gettime(CLOCK_MONOTONIC, &start);

    while (g_running) {
        clock_gettime(CLOCK_MONOTONIC, &now);
        long elapsed_us = (now.tv_sec - start.tv_sec) * 1000000L +
                          (now.tv_nsec - start.tv_nsec) / 1000L;

        if (elapsed_us >= ACTIVATION_TIMEOUT) {
            fprintf(stderr, "Error: D7S sensor did not become active within %d ms\n",
                    ACTIVATION_TIMEOUT / 1000);
            break;
        }

        int16_t x, y, z;
        if (read_acceleration(g_i2c_fd, &x, &y, &z) == 0) {
            if (log_data(g_csv, x, y, z) != 0) {
                fprintf(stderr, "Warning: failed to log data\n");
            }
        } else {
            fprintf(stderr, "Warning: failed to read acceleration data\n");
        }

        usleep(POLL_INTERVAL);
    }

    printf("\nShutting down...\n");

    if (g_csv) {
        if (fclose(g_csv) != 0) {
            fprintf(stderr, "fclose failed: %s\n", strerror(errno));
        }
        g_csv = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }

    printf("Resources released. Goodbye.\n");
    return 0;
}

