        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_2_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Conveyor belt monitoring started. Press Ctrl+C to exit.\n");

    int stall_active = 0;
    time_t stall_start = 0;

    while (running) {
        int v1 = read_sensor(SENSOR_1_GPIO);
        int v2 = read_sensor(SENSOR_2_GPIO);

        if (v1 < 0 || v2 < 0) {
            fprintf(stderr, "Sensor read error, exiting.\n");
            break;
        }

        if (is_stall(v1, v2)) {
            if (!stall_active) {
                stall_active = 1;
                stall_start = time(NULL);
                printf("Stall detected!\n");
