/*
 * TMAG5170-Q1 3D Hall-Effect Sensor Logger for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   TMAG5170 SDA  -> GPIO2 (I2C bus 1 SDA, pin 3)
 *   TMAG5170 SCL  -> GPIO3 (I2C bus 1 SCL, pin 5)
 *   TMAG5170 VDD  -> 3.3 V (pin 1)
 *   TMAG5170 GND  -> GND  (pin 9)
 *
 * Build:  gcc -O2 -Wall -Wextra -o mag_logger mag_logger.c -lpigpio -lrt
 * Run:    sudo ./mag_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- TMAG5170 I2C address ---- */
#define TMAG5170_ADDR 0x0C

/* ---- TMAG5170 register addresses ---- */
#define REG_DEVICE_CONFIG_1 0x00
#define REG_DEVICE_CONFIG_2 0x01
#define REG_SENSOR_CONFIG_1 0x02
#define REG_SENSOR_CONFIG_2 0x03
#define REG_X_MSB           0x04
#define REG_X_LSB           0x05
#define REG_Y_MSB           0x06
#define REG_Y_LSB           0x07
#define REG_Z_MSB           0x08
#define REG_Z_LSB           0x09

/* ---- Device Config 1 (0x00) ---- */
#define DEV_CFG1_MODE_CONTINUOUS 0x00  /* bits[1:0] = 00 -> continuous */
#define DEV_CFG1_RANGE_50MT      0x00  /* bits[3:2] = 00 -> 50 mT range */
#define DEV_CFG1_OS              0x00  /* bits[5:4] = 00 -> no one-shot */
#define DEV_CFG1_AFE             0x00  /* bits[7:6] = 00 -> default AFE */

/* ---- Sensor Config 1 (0x02) ---- */
#define SENS_CFG1_AXIS_XYZ_EN    0x07  /* bits[2:0] = 111 -> X/Y/Z enabled */
#define SENS_CFG1_OSR_16         0x00  /* bits[5:4] = 00 -> 16x oversampling */
#define SENS_CFG1_MAG_GAIN_50MT  0x00  /* bits[7:6] = 00 -> 50 mT range */

/* ---- Conversion constants ---- */
#define I2C_BUS          1
#define LOG_FILE         "magnetic_log.csv"
#define SAMPLE_PERIOD_US 100000  /* 100 ms */

/* ---- Globals for cleanup ---- */
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;
static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static int i2c_write_reg(uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(g_i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, value, rc);
    }
    return rc;
}

/* ------------------------------------------------------------------ */
static int i2c_read_reg(uint8_t reg, uint8_t *value)
{
    int rc = i2cReadByteData(g_i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(reg=0x%02X) failed: %d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
static int read_axis(int16_t *out, uint8_t msb_reg, uint8_t lsb_reg)
{
    uint8_t msb, lsb;
    if (i2c_read_reg(msb_reg, &msb) < 0) return -1;
    if (i2c_read_reg(lsb_reg, &lsb) < 0) return -1;
    *out = (int16_t)(((uint16_t)msb << 8) | (uint16_t)lsb);
    return 0;
}

/* ------------------------------------------------------------------ */
static int read_sensor_data(int16_t *x, int16_t *y, int16_t *z)
{
    if (read_axis(x, REG_X_MSB, REG_X_LSB) < 0) return -1;
    if (read_axis(y, REG_Y_MSB, REG_Y_LSB) < 0) return -1;
    if (read_axis(z, REG_Z_MSB, REG_Z_LSB) < 0) return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, int16_t x, int16_t y, int16_t z)
{
    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "[ERROR] time() failed\n");
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r() failed\n");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "[ERROR] strftime() failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%d,%d,%d\n", ts, x, y, z) < 0) {
        fprintf(stderr, "[ERROR] fprintf() to log file failed\n");
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "[ERROR] fflush() failed\n");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
