    /* ---- Open I2C bus 1 at TMAG5170 address ---- */
    g_i2c_handle = i2cOpen(I2C_BUS, TMAG5170_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, TMAG5170_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Configure sensor: continuous mode, 50 mT range, XYZ enabled ---- */
    uint8_t dev_cfg1 = DEV_CFG1_MODE_CONTINUOUS | DEV_CFG1_RANGE_50MT |
                       DEV_CFG1_OS | DEV_CFG1_AFE;
    if (i2c_write_reg(REG_DEVICE_CONFIG_1, dev_cfg1) < 0) {
        fprintf(stderr, "[FATAL] Failed to configure DEVICE_CONFIG_1\n");
        cleanup();
        return EXIT_FAILURE;
    }

    uint8_t sens_cfg1 = SENS_CFG1_AXIS_XYZ_EN | SENS_CFG1_OSR_16 |
                        SENS_CFG1_MAG_GAIN_50MT;
    if (i2c_write_reg(REG_SENSOR_CONFIG_1, sens_cfg1) < 0) {
        fprintf(stderr, "[FATAL] Failed to configure SENSOR_CONFIG_1\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Open log file (append); write header if new/empty ---- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[FATAL] Cannot open log file '%s'\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    long file_size = 0;
    if (fseek(g_log_file, 0, SEEK_END) == 0) {
        file_size = ftell(g_log_file);
    }
    if (file_size == 0) {
        fprintf(g_log_file, "timestamp,x_mT,y_mT,z_mT\n");
        fflush(g_log_file);
    }

    /* ---- Register signal handlers for graceful shutdown ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("[WARN] sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[WARN] sigaction(SIGTERM)");
    }

    printf("TMAG5170 logging started. Press Ctrl-C to stop.\n");

    /* ---- Main sampling loop ---- */
    while (g_running) {
        int16_t x, y, z;

