#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>

#define SENSOR_PIN 23
#define LOG_FILE "flood_log.txt"
#define POLL_INTERVAL_SEC 2
#define REINIT_DELAY_SEC 60

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) != NULL) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    } else {
        fprintf(fp, "<timestamp-error> %s\n", message);
    }

    fclose(fp);
}

static void generate_alert(void) {
    printf("ALERT: Water detected!\n");
    fflush(stdout);
    log_event("ALERT: Water detected");
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPullUpDown(SENSOR_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down on GPIO %d\n", SENSOR_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Failed to register SIGINT handler");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Failed to register SIGTERM handler");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        log_event("ERROR: GPIO initialization failed");
        return EXIT_FAILURE;
    }

    printf("Water level monitoring started on GPIO%d. Press Ctrl+C to exit.\n", SENSOR_PIN);
    fflush(stdout);

    time_t last_reinit_attempt = 0;

    while (running) {
        int sensor_value = gpioRead(SENSOR_PIN);

        if (sensor_value == PI_BAD_GPIO) {
            fprintf(stderr, "Error reading GPIO %d\n", SENSOR_PIN);
            log_event("ERROR: GPIO read failed");
            time_t now = time(NULL);
            if (now - last_reinit_attempt >= REINIT_DELAY_SEC) {
                if (initialize_gpio() == 0) {
                    log_event("INFO: GPIO re-initialized successfully");
                    last_reinit_attempt = now;
                } else {
                    log_event("ERROR: GPIO re-initialization failed");
                    last_reinit_attempt = now;
                }
            }
        } else if (sensor_value == 1) {
            generate_alert();
        }

        sleep(POLL_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    gpioTerminate();
    return EXIT_SUCCESS;
}

