/*
 * MLX90217 Hall-effect RPM monitor for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   MLX90217 VCC  -> 3.3 V (pin 1)
 *   MLX90217 GND  -> GND    (pin 9)
 *   MLX90217 OUT  -> GPIO4  (BCM 4, physical pin 7)
 *
 * The internal pull-up on GPIO4 is enabled so the line is defined
 * when the sensor is absent or disconnected.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o rpm_monitor rpm_monitor.c -lpigpio -lrt
 * Run:
 *   sudo ./rpm_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN        4
#define LOG_FILE        "rpm_log.txt"
#define SAMPLE_PERIOD_S 1

static volatile sig_atomic_t g_running = 1;
static volatile uint32_t     g_pulse_count = 0;
static FILE                 *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* pigpio alert callback (runs in pigpio's thread)                      */
/* ------------------------------------------------------------------ */
static void pulse_alert_cb(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)tick;
    (void)userdata;

    if (level == 1) {                 /* rising edge */
        __sync_fetch_and_add(&g_pulse_count, 1);
    }
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */
static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int open_log_file(void)
{
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }
    return 0;
}

static void log_rpm(FILE *fp, double rpm)
{
    time_t     rawtime;
    struct tm  tm_info;
    char       ts[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (fprintf(fp, "%s %.2f\n", ts, rpm) < 0) {
        perror("fprintf(log)");
        return;
    }
    if (fflush(fp) != 0) {
        perror("fflush(log)");
    }
    printf("%s %.2f\n", ts, rpm);
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int rc = EXIT_FAILURE;

    /* --- pigpio init ------------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- GPIO configuration ----------------------------------------- */
    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_INPUT) failed\n", GPIO_PIN);
        goto cleanup_gpio;
    }
    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "gpioSetPullUpDown(%d, PI_PUD_UP) failed\n", GPIO_PIN);
        goto cleanup_gpio;
    }

    /* --- signal handlers -------------------------------------------- */
    if (install_signal_handlers() != 0) {
        goto cleanup_gpio;
    }

    /* --- log file --------------------------------------------------- */
    if (open_log_file() != 0) {
        goto cleanup_gpio;
    }

    /* --- register alert callback ------------------------------------ */
    if (gpioSetAlertFuncEx(GPIO_PIN, pulse_alert_cb, NULL) != 0) {
        fprintf(stderr, "gpioSetAlertFuncEx(%d) failed\n", GPIO_PIN);
        goto cleanup_log;
    }

    printf("RPM monitoring started on GPIO%d. Press Ctrl+C to exit.\n",
           GPIO_PIN);

    /* --- main sampling loop ----------------------------------------- */
    while (g_running) {
        sleep(SAMPLE_PERIOD_S);

        uint32_t pulses = g_pulse_count;
        g_pulse_count = 0;            /* reset for next window */

        /* pulses per second -> RPM */
        double rpm = (double)pulses * 60.0;

        log_rpm(g_log_fp, rpm);
    }

    rc = EXIT_SUCCESS;

    /* --- cleanup ---------------------------------------------------- */
    gpioSetAlertFuncEx(GPIO_PIN, NULL, NULL);   /* disable callback */
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioTerminate();
    return rc;

cleanup_log:
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
cleanup_gpio:
    gpioTerminate();
    return rc;
}

