#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

#define SENSOR_A_PIN 17
#define SENSOR_B_PIN 27
#define LOG_FILE "rotation_log.txt"

static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;
static pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static void get_timestamp(char *buf, size_t len) {
    struct timespec ts;
    struct tm tm_info;
    clock_gettime(CLOCK_REALTIME, &ts);
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tm_info);
    size_t pos = strlen(buf);
    snprintf(buf + pos, len - pos, ".%03ld", ts.tv_nsec / 1000000);
}

static void log_rotation(const char *direction) {
    char timestamp[32];
    get_timestamp(timestamp, sizeof(timestamp));
    pthread_mutex_lock(&log_mutex);
    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, direction);
        fflush(log_file);
    }
    pthread_mutex_unlock(&log_mutex);
}

static void handle_rotation(int a_state, int b_state) {
    static int last_a = 0, last_b = 0;
    int direction = 0;

    if (a_state != last_a || b_state != last_b) {
        if (last_a == 0 && last_b == 0) {
            direction = (a_state == 1) ? 1 : -1;
        } else if (last_a == 1 && last_b == 0) {
            direction = (a_state == 0) ? 1 : -1;
        } else if (last_a == 1 && last_b == 1) {
            direction = (a_state == 0) ? -1 : 1;
        } else if (last_a == 0 && last_b == 1) {
            direction = (a_state == 1) ? -1 : 1;
        }
        last_a = a_state;
        last_b = b_state;
        if (direction > 0) {
            log_rotation("Clockwise");
        } else if (direction < 0) {
            log_rotation("Counter-clockwise");
        }
    }
}

static void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data) {
    (void)tick;
    (void)user_data;
    if (gpio == SENSOR_A_PIN) {
        int b_state = gpioRead(SENSOR_B_PIN);
        handle_rotation(level, b_state);
    } else if (gpio == SENSOR_B_PIN) {
        int a_state = gpioRead(SENSOR_A_PIN);
        handle_rotation(a_state, level);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_A_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_A_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR_B_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_B_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_A_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", SENSOR_A_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(SENSOR_B_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", SENSOR_B_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Failed to register SIGINT handler");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Failed to register SIGTERM handler");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFuncEx(SENSOR_A_PIN, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function for GPIO %d\n", SENSOR_A_PIN);
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetAlertFuncEx(SENSOR_B_PIN, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function for GPIO %d\n", SENSOR_B_PIN);
        gpioSetAlertFuncEx(SENSOR_A_PIN, NULL, NULL);
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Monitoring rotation on GPIO %d and %d. Press Ctrl+C to exit.\n",
           SENSOR_A_PIN, SENSOR_B_PIN);

    while (program_running) {
        gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    gpioSetAlertFuncEx(SENSOR_A_PIN, NULL, NULL);
    gpioSetAlertFuncEx(SENSOR_B_PIN, NULL, NULL);
    pthread_mutex_lock(&log_mutex);
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
    pthread_mutex_unlock(&log_mutex);
    gpioTerminate();
    return EXIT_SUCCESS;
}

