#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <errno.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 23
#define LED_PIN          18
#define POLL_DELAY_US    50000  /* 50 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to install SIGINT handler: %s", strerror(errno));
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to install SIGTERM handler: %s", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    openlog("touch_led", LOG_PID | LOG_CONS, LOG_USER);

    if (install_signal_handlers() != 0) {
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "pigpio initialised successfully");

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO%d as input: %s",
               TOUCH_SENSOR_PIN, strerror(errno));
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO%d as output: %s",
               LED_PIN, strerror(errno));
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioWrite(LED_PIN, 0) != 0) {
        syslog(LOG_ERR, "Failed to initialise LED state on GPIO%d: %s",
               LED_PIN, strerror(errno));
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Touch sensor monitoring started (GPIO%d) -> LED (GPIO%d)",
           TOUCH_SENSOR_PIN, LED_PIN);

    while (g_running) {
        int touch = gpioRead(TOUCH_SENSOR_PIN);
        if (touch < 0) {
            syslog(LOG_ERR, "Failed to read touch sensor on GPIO%d: %s",
                   TOUCH_SENSOR_PIN, strerror(errno));
            break;
        }

        if (gpioWrite(LED_PIN, touch) != 0) {
            syslog(LOG_ERR, "Failed to write LED on GPIO%d: %s",
                   LED_PIN, strerror(errno));
            break;
        }

        if (touch) {
            syslog(LOG_INFO, "Touch detected on GPIO%d", TOUCH_SENSOR_PIN);
        }

        usleep(POLL_DELAY_US);
    }

    syslog(LOG_INFO, "Shutting down: turning LED off and releasing resources");
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

