/*
 * Raspberry Pi 3 Model B+ — TTP223B capacitive touch sensor toggler
 *
 * Wiring:
 *   SainSmart TTP223B OUT  -> GPIO17 (physical pin 11)
 *   LED anode (via ~330 Ω) -> GPIO18 (physical pin 12)
 *   LED cathode             -> GND
 *   TTP223B VCC             -> 3.3 V
 *   TTP223B GND             -> GND
 *
 * Behaviour:
 *   On each rising edge of the TTP223B OUT line, the LED on GPIO18 is
 *   toggled.  A 50 ms software debounce is applied after each edge.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o touch_toggle touch_toggle.c -lgpiod
 */

#include <errno.h>
#include <gpiod.h>
#include <signal.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

#define TOUCH_LINE_OFFSET 17   /* GPIO17 — TTP223B OUT */
#define LED_LINE_OFFSET   18   /* GPIO18 — LED anode  */
#define DEBOUNCE_MS       50   /* software debounce window */

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static void sleep_ms(unsigned int ms)
{
    struct timespec ts = {
        .tv_sec  = ms / 1000U,
        .tv_nsec = (long)(ms % 1000U) * 1000000L
    };
    while (nanosleep(&ts, &ts) != 0) {
        if (errno != EINTR) {
            perror("nanosleep");
            break;
        }
        /* Retry with the remaining time after EINTR. */
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *touch_line = NULL;
    struct gpiod_line *led_line = NULL;
    int ret = EXIT_FAILURE;

    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    touch_line = gpiod_chip_get_line(chip, TOUCH_LINE_OFFSET);
    if (touch_line == NULL) {
        fprintf(stderr, "Failed to get line %d: %s\n",
                TOUCH_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    led_line = gpiod_chip_get_line(chip, LED_LINE_OFFSET);
    if (led_line == NULL) {
        fprintf(stderr, "Failed to get line %d: %s\n",
                LED_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_rising_edge_events(touch_line, "ttp223b-touch") < 0) {
        fprintf(stderr, "Failed to request rising-edge events on line %d: %s\n",
                TOUCH_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(led_line, "ttp223b-led", 0) < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n",
                LED_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    printf("Touch sensor ready.  Touch GPIO%d to toggle GPIO%d.  Ctrl+C to exit.\n",
           TOUCH_LINE_OFFSET, LED_LINE_OFFSET);
    fflush(stdout);

    int led_state = 0;

    while (g_running) {
        /*
         * Block up to 1 s waiting for a rising-edge event so that we can
         * periodically check g_running and exit promptly on signal.
         */
        int ev = gpiod_line_event_wait(touch_line, &(struct timespec){ .tv_sec = 1, .tv_nsec = 0 });
        if (ev < 0) {
            if (errno == EINTR) {
                continue;
            }
            fprintf(stderr, "Error waiting for touch event: %s\n", strerror(errno));
            goto cleanup;
        }
        if (ev == 0) {
            /* Timeout — loop back and re-check g_running. */
            continue;
        }

        /* Drain any queued events so we do not miss a rising edge. */
        while (gpiod_line_event_wait(touch_line, &(struct timespec){ .tv_sec = 0, .tv_nsec = 0 }) > 0) {
            /* discard */
        }

        if (gpiod_line_event_read(touch_line, NULL) < 0) {
            if (errno == EINTR) {
                continue;
            }
            fprintf(stderr, "Error reading touch event: %s\n", strerror(errno));
            goto cleanup;
        }

        led_state = !led_state;
        if (gpiod_line_set_value(led_line, led_state) < 0) {
            fprintf(stderr, "Error writing LED state: %s\n", strerror(errno));
            goto cleanup;
        }

        printf("Touch detected — LED %s\n", led_state ? "ON" : "OFF");
        fflush(stdout);

        sleep_ms(DEBOUNCE_MS);
    }

    printf("\nExiting...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (led_line != NULL) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    if (touch_line != NULL) {
        gpiod_line_release(touch_line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    return ret;
}

