#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SENSOR_1_PIN 4
#define SENSOR_2_PIN 17
#define LED_1_PIN 27
#define LED_2_PIN 22

#define BUFFER_SIZE 100

typedef struct {
    int sensor_pin;
    time_t timestamp;
    int state;
} LogEntry;

static LogEntry log_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_overflow_count = 0;

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static void add_to_log(int sensor_pin, time_t timestamp, int state) {
    log_buffer[buffer_index].sensor_pin = sensor_pin;
    log_buffer[buffer_index].timestamp = timestamp;
    log_buffer[buffer_index].state = state;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_index == 0) {
        buffer_overflow_count++;
    }
}

static void print_log_buffer(void) {
    printf("\n--- Log Buffer Contents ---\n");
    printf("Overflow count: %d\n", buffer_overflow_count);
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int idx = (buffer_index + i) % BUFFER_SIZE;
        if (log_buffer[idx].sensor_pin != 0 || log_buffer[idx].timestamp != 0) {
            char time_str[32];
            struct tm *tm_info = localtime(&log_buffer[idx].timestamp);
            if (tm_info != NULL) {
                strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);
            } else {
                strncpy(time_str, "UNKNOWN", sizeof(time_str));
            }
            printf("[%d] Sensor: %d, Timestamp: %s, State: %d\n",
                   idx, log_buffer[idx].sensor_pin, time_str, log_buffer[idx].state);
        }
    }
    printf("--- End of Log Buffer ---\n");
}

static void cleanup(void) {
    gpioWrite(LED_1_PIN, 0);
    gpioWrite(LED_2_PIN, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set SENSOR_1_PIN (GPIO%d) as input\n", SENSOR_1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set SENSOR_2_PIN (GPIO%d) as input\n", SENSOR_2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(LED_1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set LED_1_PIN (GPIO%d) as output\n", LED_1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(LED_2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set LED_2_PIN (GPIO%d) as output\n", LED_2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(LED_1_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise LED_1_PIN (GPIO%d) to LOW\n", LED_1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(LED_2_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise LED_2_PIN (GPIO%d) to LOW\n", LED_2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    int prev_sensor1 = gpioRead(SENSOR_1_PIN);
    int prev_sensor2 = gpioRead(SENSOR_2_PIN);
    if (prev_sensor1 < 0 || prev_sensor2 < 0) {
        fprintf(stderr, "Error: failed to read initial sensor states\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int sensor1_value = gpioRead(SENSOR_1_PIN);
        int sensor2_value = gpioRead(SENSOR_2_PIN);

        if (sensor1_value < 0 || sensor2_value < 0) {
            fprintf(stderr, "Error: failed to read sensor values\n");
            break;
        }

        if (sensor1_value != prev_sensor1) {
            if (gpioWrite(LED_1_PIN, sensor1_value) != 0) {
                fprintf(stderr, "Error: failed to write LED_1_PIN (GPIO%d)\n", LED_1_PIN);
                break;
            }
            time_t now = time(NULL);
            if (now == (time_t)-1) {
                perror("time");
                break;
            }
            add_to_log(SENSOR_1_PIN, now, sensor1_value);
            prev_sensor1 = sensor1_value;
        }

        if (sensor2_value != prev_sensor2) {
            if (gpioWrite(LED_2_PIN, sensor2_value) != 0) {
                fprintf(stderr, "Error: failed to write LED_2_PIN (GPIO%d)\n", LED_2_PIN);
                break;
            }
            time_t now = time(NULL);
            if (now == (time_t)-1) {
                perror("time");
                break;
            }
            add_to_log(SENSOR_2_PIN, now, sensor2_value);
            prev_sensor2 = sensor2_value;
        }

        gpioDelay(50000);
    }

    print_log_buffer();
    cleanup();
    return EXIT_SUCCESS;
}

