/*
 * Raindrop Sensor Monitor — Raspberry Pi 4 Model B
 *
 * Wiring:
 *   Raindrop Module  ->  Raspberry Pi 4
 *   VCC              ->  3.3 V (Pin 1)
 *   GND              ->  GND   (Pin 9)
 *   D0 (Digital Out) ->  GPIO17 (BCM 17, Pin 11)
 *
 * The module's internal pull-up resistor is enabled so the input is
 * defined when the sensor is disconnected.  The module is active-low:
 *   D0 = 0  -> rain detected
 *   D0 = 1  -> no rain
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o rain_monitor rain_monitor.c -lpigpio -lrt
 * Run:
 *   sudo ./rain_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RAIN_PIN        17          /* BCM 17, GPIO17 */
#define LOG_FILE        "/var/log/rain_events.log"
#define POLL_DELAY_US   500000      /* 500 ms */
#define TIMESTAMP_LEN   32

static volatile sig_atomic_t g_running = 1;
static FILE                 *g_log_fp  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;                 /* tell main loop to exit cleanly  */
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_event(const char *message)
{
    time_t     rawtime;
    struct tm  timeinfo;
    char       timestamp[TIMESTAMP_LEN];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        return -1;
    }

    if (fprintf(g_log_fp, "%s: %s\n", timestamp, message) < 0) {
        return -1;
    }

    if (fflush(g_log_fp) != 0) {
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
