    while (g_running) {
        int level = gpioRead(RAIN_PIN);

        if (level < 0) {
            fprintf(stderr, "Error: gpioRead failed for pin %d.\n", RAIN_PIN);
            break;
        }

        /* Active-low: LOW (0) = rain, HIGH (1) = no rain */
        int rain = (level == 0) ? 1 : 0;

        if (rain != last_state) {
            const char *msg = rain ? "Rain Detected" : "No Rain";
            if (log_event(msg) != 0) {
