#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 18
#define DEBOUNCE_US 5000
#define LOG_FILE "shaft_log.txt"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_data(FILE *fp, int s1, int s2) {
    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return -1;
    }
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return -1;
    }
    char ts[64];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }
    if (fprintf(fp, "%s,%d,%d\n", ts, s1, s2) < 0) {
        fprintf(stderr, "fprintf() failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush() failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(SENSOR_1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_1_GPIO);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SENSOR_2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_2_GPIO);
        gpioTerminate();
        return 1;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening %s: %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return 1;
    }

    int s1_prev = gpioRead(SENSOR_1_GPIO);
    int s2_prev = gpioRead(SENSOR_2_GPIO);
    if (s1_prev < 0 || s2_prev < 0) {
        fprintf(stderr, "Initial GPIO read failed\n");
        fclose(fp);
        gpioTerminate();
        return 1;
    }

    int s1_debounced = s1_prev;
    int s2_debounced = s2_prev;

    printf("Monitoring shaft RPM. Press Ctrl+C to exit.\n");

    while (running) {
        int s1 = gpioRead(SENSOR_1_GPIO);
        int s2 = gpioRead(SENSOR_2_GPIO);

        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "GPIO read error\n");
            break;
        }

        if (s1 != s1_prev) {
            gpioDelay(DEBOUNCE_US);
            s1 = gpioRead(SENSOR_1_GPIO);
            if (s1 == s1_prev) {
                s1_debounced = s1;
            }
            s1_prev = s1;
        }

        if (s2 != s2_prev) {
            gpioDelay(DEBOUNCE_US);
            s2 = gpioRead(SENSOR_2_GPIO);
            if (s2 == s2_prev) {
                s2_debounced = s2;
            }
            s2_prev = s2;
        }

        if (s1_debounced != s1_prev || s2_debounced != s2_prev) {
            if (log_data(fp, s1_debounced, s2_debounced) != 0) {
                fprintf(stderr, "Logging failed, exiting.\n");
                break;
            }
        }

        if (s1_debounced != s2_debounced) {
            double rpm = 60.0;
            printf("RPM: %.2f\n", rpm);
        }

        gpioDelay(10000);
    }

    printf("\nShutting down...\n");
    if (fclose(fp) != 0) {
        fprintf(stderr, "fclose() failed: %s\n", strerror(errno));
    }
    gpioTerminate();
    return 0;
}

