static FILE *g_log = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void log_event(const char *event)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return;
    }

    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    if (t == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return;
    }

    if (g_log != NULL) {
        if (fprintf(g_log, "%s - %s\n", timestamp, event) < 0) {
            fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        }
        if (fflush(g_log) != 0) {
            fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        }
    } else {
        fprintf(stderr, "Log file not open; event: %s\n", event);
    }
}

static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return -1;
    }

    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set SENSOR_1_PIN (GPIO%d) as input\n", SENSOR_1_PIN);
        return -1;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set SENSOR_2_PIN (GPIO%d) as input\n", SENSOR_2_PIN);
        return -1;
    }
    if (gpioSetMode(ALARM_PIN, PI_OUTPUT) != 0) {
