        return -1;
    }

    if (gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down on SENSOR_1_PIN (GPIO%d)\n", SENSOR_1_PIN);
        return -1;
    }
    if (gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down on SENSOR_2_PIN (GPIO%d)\n", SENSOR_2_PIN);
        return -1;
    }

    if (gpioWrite(ALARM_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialize ALARM_PIN (GPIO%d) LOW\n", ALARM_PIN);
        return -1;
    }

    return 0;
}

static void cleanup_gpio(void)
{
    /* Ensure alarm is off before terminating */
    if (gpioWrite(ALARM_PIN, 0) != 0) {
        fprintf(stderr, "Warning: failed to turn off alarm during cleanup\n");
    }
    gpioTerminate();
}

