    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    g_log = fopen(LOG_FILE, "a");
    if (g_log == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        cleanup_gpio();
        return EXIT_FAILURE;
    }

    log_event("Monitoring started");

    int alarm_active = 0;
    int tilt_active = 0;
    time_t tilt_start_time = 0;

    while (g_running) {
        int s1 = gpioRead(SENSOR_1_PIN);
        int s2 = gpioRead(SENSOR_2_PIN);

        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "gpioRead failed (s1=%d, s2=%d)\n", s1, s2);
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        if (s1 == 1 || s2 == 1) {
            if (!tilt_active) {
                tilt_active = 1;
                tilt_start_time = time(NULL);
                log_event("Tilt detected");
            } else {
                time_t now = time(NULL);
                if (now != (time_t)-1 && (now - tilt_start_time) >= ALARM_THRESHOLD_SEC) {
                    if (!alarm_active) {
                        alarm_active = 1;
                        if (gpioWrite(ALARM_PIN, 1) != 0) {
                            fprintf(stderr, "Failed to activate alarm\n");
                        } else {
                            log_event("Alarm activated");
                        }
                    }
                }
            }
        } else {
            if (tilt_active) {
                tilt_active = 0;
                log_event("Tilt ended");
            }
            if (alarm_active) {
                alarm_active = 0;
                if (gpioWrite(ALARM_PIN, 0) != 0) {
                    fprintf(stderr, "Failed to deactivate alarm\n");
                } else {
                    log_event("Alarm deactivated");
                }
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    log_event("Monitoring stopped");
    cleanup_gpio();
    if (g_log != NULL) {
        fclose(g_log);
        g_log = NULL;
    }

    return EXIT_SUCCESS;
}

