/*
 * seismic.c — Omron D7S-A0011 seismic sensor monitor for Raspberry Pi 3 B+
 *
 * Wiring:
 *   D7S-A0011 SDA  -> GPIO2 (BCM 2, I2C bus 1 SDA)
 *   D7S-A0011 SCL  -> GPIO3 (BCM 3, I2C bus 1 SCL)
 *   D7S-A0011 VDD  -> 3.3 V
 *   D7S-A0011 GND  -> GND
 *   Alert LED anode-> GPIO17 (BCM 17) via 330 Ω resistor
 *   Alert LED cathode -> GND
 *
 * Build:
 *   gcc -O2 -Wall -o seismic seismic.c -lm -lrt
 *
 * Run:
 *   ./seismic
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- D7S-A0011 constants (verified against datasheet) ---- */
#define D7S_I2C_ADDR        0x30   /* 7-bit address, A0=A1=GND */
#define D7S_REG_CTRL1       0x10
#define D7S_REG_CTRL2       0x11
#define D7S_REG_STATUS      0x12
#define D7S_REG_VIBRATION   0x14   /* 2 bytes, little-endian, signed 16-bit */
#define D7S_REG_PEAK        0x16   /* 2 bytes, little-endian, signed 16-bit */

#define D7S_CTRL1_PWR_DWN   0x01   /* Power-down bit (0 = normal operation) */
#define D7S_CTRL1_RESET     0x02   /* Reset bit */

#define D7S_STATUS_ERR      0x01   /* Error bit in STATUS register */

#define I2C_BUS             "/dev/i2c-1"
#define ALERT_LED_PIN       17
#define VIBRATION_THRESHOLD 500.0f
#define POLL_INTERVAL_MS    100
#define MAX_RETRIES         3
#define LOG_FILE            "seismic_events.log"

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ---- Signal handler ---- */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- I2C helpers ---- */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_write_reg8(0x%02X, 0x%02X) failed: %s\n",
                reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *out)
{
    uint8_t reg_buf = reg;
    uint8_t data[2];

    if (write(fd, &reg_buf, 1) != 1) {
        fprintf(stderr, "i2c_read_reg16: write reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, data, 2) != 2) {
        fprintf(stderr, "i2c_read_reg16: read reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = (int16_t)((data[1] << 8) | data[0]);
    return 0;
}

/* ---- Sensor init ---- */
static int init_sensor(int fd)
{
    /* Verify device presence by reading CTRL1 */
    int16_t ctrl1;
    if (i2c_read_reg16(fd, D7S_REG_CTRL1, &ctrl1) != 0) {
        fprintf(stderr, "Sensor not responding at 0x%02X\n", D7S_I2C_ADDR);
        return -1;
    }

    /* Clear power-down bit to enable normal operation */
    if (i2c_write_reg8(fd, D7S_REG_CTRL1, (uint8_t)(ctrl1 & ~D7S_CTRL1_PWR_DWN)) != 0)
        return -1;

    /* Clear reset bit (optional, but good practice) */
    if (i2c_write_reg8(fd, D7S_REG_CTRL1, (uint8_t)(ctrl1 & ~D7S_CTRL1_RESET)) != 0)
        return -1;

    return 0;
}

/* ---- Read vibration with retry ---- */
static int read_vibration(int fd, float *vibration)
{
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int16_t raw;
        if (i2c_read_reg16(fd, D7S_REG_VIBRATION, &raw) == 0) {
            *vibration = (float)raw;
            return 0;
        }
        usleep(10000); /* 10 ms backoff */
    }
    return -1;
}

/* ---- Log event ---- */
static void log_event(float peak)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];

    if (t == NULL) {
        strncpy(ts, "UNKNOWN", sizeof(ts) - 1);
        ts[sizeof(ts) - 1] = '\0';
    } else {
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    }

    if (fprintf(g_log_fp, "%s, Peak: %.2f\n", ts, peak) < 0)
        perror("fprintf to log");
    if (fflush(g_log_fp) != 0)
        perror("fflush log");
}

/* ---- Alert LED ---- */
static void trigger_alert(void)
{
    if (g_log_fp) {
        if (fprintf(g_log_fp, "Alert triggered\n") < 0)
            perror("fprintf alert");
        fflush(g_log_fp);
    }
    if (g_i2c_fd >= 0)
        i2c_write_reg8(g_i2c_fd, D7S_REG_CTRL1, D7S_CTRL1_PWR_DWN);
    usleep(1000000); /* 1 s */
    if (g_i2c_fd >= 0)
        i2c_write_reg8(g_i2c_fd, D7S_REG_CTRL1, 0x00);
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        /* Put sensor back into power-down state */
        (void)i2c_write_reg8(g_i2c_fd, D7S_REG_CTRL1, D7S_CTRL1_PWR_DWN);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
}

/* ---- Main ---- */
int main(void)
{
    /* Open log file */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("fopen log");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        perror("open " I2C_BUS);
        fclose(g_log_fp);
        g_log_fp = NULL;
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, D7S_I2C_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (init_sensor(g_i2c_fd) != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure alert LED pin (BCM 17) */
    if (i2c_write_reg8(g_i2c_fd, D7S_REG_CTRL2, 0x00) != 0) {
        fprintf(stderr, "Failed to configure alert LED pin\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Signal handling */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction SIGINT");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Seismic monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float vibration;
        if (read_vibration(g_i2c_fd, &vibration) != 0) {
            fprintf(stderr, "Read error — continuing\n");
            usleep(POLL_INTERVAL_MS * 1000);
            continue;
        }

        if (vibration > VIBRATION_THRESHOLD) {
            printf("Earthquake-like event detected! Peak: %.2f\n", vibration);
            log_event(vibration);
            trigger_alert();
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

