    if (i2c_write_reg8(fd, D7S_REG_CTRL1, (uint8_t)(ctrl1 & ~D7S_CTRL1_RESET)) != 0)
        return -1;

    return 0;
}

/* ---- Read vibration with retry ---- */
static int read_vibration(int fd, float *vibration)
{
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int16_t raw;
        if (i2c_read_reg16(fd, D7S_REG_VIBRATION, &raw) == 0) {
            *vibration = (float)raw;
            return 0;
        }
        usleep(10000); /* 10 ms backoff */
    }
    return -1;
}

/* ---- Log event ---- */
static void log_event(float peak)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];

    if (t == NULL) {
        strncpy(ts, "UNKNOWN", sizeof(ts) - 1);
        ts[sizeof(ts) - 1] = '\0';
    } else {
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    }

    if (fprintf(g_log_fp, "%s, Peak: %.2f\n", ts, peak) < 0)
        perror("fprintf to log");
    if (fflush(g_log_fp) != 0)
        perror("fflush log");
}

/* ---- Alert LED ---- */
static void trigger_alert(void)
{
    if (g_log_fp) {
        if (fprintf(g_log_fp, "Alert triggered\n") < 0)
            perror("fprintf alert");
        fflush(g_log_fp);
    }
    if (g_i2c_fd >= 0)
        i2c_write_reg8(g_i2c_fd, D7S_REG_CTRL1, D7S_CTRL1_PWR_DWN);
    usleep(1000000); /* 1 s */
    if (g_i2c_fd >= 0)
        i2c_write_reg8(g_i2c_fd, D7S_REG_CTRL1, 0x00);
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        /* Put sensor back into power-down state */
        (void)i2c_write_reg8(g_i2c_fd, D7S_REG_CTRL1, D7S_CTRL1_PWR_DWN);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
}

/* ---- Main ---- */
int main(void)
{
    /* Open log file */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("fopen log");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        perror("open " I2C_BUS);
        fclose(g_log_fp);
        g_log_fp = NULL;
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, D7S_I2C_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (init_sensor(g_i2c_fd) != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure alert LED pin (BCM 17) */
    if (i2c_write_reg8(g_i2c_fd, D7S_REG_CTRL2, 0x00) != 0) {
        fprintf(stderr, "Failed to configure alert LED pin\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Signal handling */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction SIGINT");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Seismic monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float vibration;
        if (read_vibration(g_i2c_fd, &vibration) != 0) {
            fprintf(stderr, "Read error — continuing\n");
            usleep(POLL_INTERVAL_MS * 1000);
            continue;
        }

        if (vibration > VIBRATION_THRESHOLD) {
            printf("Earthquake-like event detected! Peak: %.2f\n", vibration);
            log_event(vibration);
            trigger_alert();
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

