#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR1_PIN 4
#define SENSOR2_PIN 17
#define SENSOR3_PIN 27
#define SENSOR4_PIN 22
#define LED_PIN     18
#define POLL_DELAY_US 50000  /* 50 ms */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

static int read_sensor(int pin)
{
    int v = gpioRead(pin);
    if (v < 0) {
        fprintf(stderr, "Error reading GPIO %d\n", pin);
        return -1;
    }
    /* KY-032 is active-low: 0 => object detected */
    return (v == 0) ? 1 : 0;
}

static int control_led(int pin, int state)
{
    if (gpioWrite(pin, state) < 0) {
        fprintf(stderr, "Error writing GPIO %d\n", pin);
        return -1;
    }
    return 0;
}

int main(void)
{
    int pins[] = {SENSOR1_PIN, SENSOR2_PIN, SENSOR3_PIN, SENSOR4_PIN};
    int num_pins = sizeof(pins) / sizeof(pins[0]);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < num_pins; i++) {
        if (gpioSetMode(pins[i], PI_INPUT) < 0) {
            fprintf(stderr, "Failed to set GPIO %d as input\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (control_led(LED_PIN, 0) < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int prev_led_state = -1;

    while (running) {
        int obstacle = 0;
        int read_error = 0;

        for (int i = 0; i < num_pins; i++) {
            int val = read_sensor(pins[i]);
            if (val < 0) {
                read_error = 1;
                break;
            }
            obstacle |= val;
        }

        if (read_error) {
            /* Brief pause to avoid tight error loop, then continue */
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        int desired = (obstacle > 0) ? 1 : 0;

        if (desired != prev_led_state) {
            if (control_led(LED_PIN, desired) < 0) {
                break;
            }
            prev_led_state = desired;
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* Clean shutdown */
    control_led(LED_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

