/*
 * flame_monitor.c — KY-026 flame sensor monitor for Raspberry Pi 3 B+
 *
 * Build:  gcc -O2 -Wall -Wextra -o flame_monitor flame_monitor.c -lgpiod
 * Run:    sudo ./flame_monitor   (root needed for /var/log access)
 *
 * Sensors: five KY-026 digital-out lines on BCM GPIO 2, 3, 4, 17, 27.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <syslog.h>
#include <fcntl.h>
#include <sys/file.h>
#include <gpiod.h>

#define NUM_SENSORS   5
#define LOG_FILE      "/var/log/flame_events.log"
#define DEBOUNCE_MS   50
#define POLL_MS       1000
#define TIMESTAMP_LEN 32

static const unsigned int sensor_pins[NUM_SENSORS] = {2, 3, 4, 17, 27};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static int get_timestamp(char *buf, size_t len)
{
    time_t rawtime;
    struct tm tm_info;

    if (time(&rawtime) == (time_t)-1)
        return -1;

    if (gmtime_r(&rawtime, &tm_info) == NULL)
        return -1;

    if (strftime(buf, len, "%Y-%m-%dT%H:%M:%SZ", &tm_info) == 0)
        return -1;

    return 0;
}

static int log_event(int sensor_id, unsigned int pin)
{
    char ts[TIMESTAMP_LEN];
    FILE *fp = NULL;
    int ret = -1;

    if (get_timestamp(ts, sizeof(ts)) != 0) {
        syslog(LOG_ERR, "Failed to generate timestamp: %s", strerror(errno));
        return -1;
    }

    fp = fopen(LOG_FILE, "a");
    if (!fp) {
        syslog(LOG_ERR, "Failed to open log file %s: %s", LOG_FILE, strerror(errno));
        return -1;
    }

    if (flock(fileno(fp), LOCK_EX) == -1) {
        syslog(LOG_ERR, "Failed to lock log file: %s", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s - Sensor ID: %d (GPIO %u) - Flame Detected\n",
                ts, sensor_id, pin) < 0) {
        syslog(LOG_ERR, "Failed to write to log file: %s", strerror(errno));
        flock(fileno(fp), LOCK_UN);
        fclose(fp);
        return -1;
    }

    if (fflush(fp) == EOF) {
        syslog(LOG_ERR, "Failed to flush log file: %s", strerror(errno));
        flock(fileno(fp), LOCK_UN);
        fclose(fp);
        return -1;
    }

    if (flock(fileno(fp), LOCK_UN) == -1) {
        syslog(LOG_ERR, "Failed to unlock log file: %s", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) == EOF) {
        syslog(LOG_ERR, "Failed to close log file: %s", strerror(errno));
        return -1;
    }

    syslog(LOG_INFO, "Flame detected on Sensor ID: %d (GPIO %u)", sensor_id, pin);
    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_SENSORS];
    int prev_state[NUM_SENSORS];
    int ret = EXIT_FAILURE;

    memset(lines, 0, sizeof(lines));

    openlog("flame_monitor", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Flame monitor starting");

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        syslog(LOG_ERR, "Failed to install SIGINT handler: %s", strerror(errno));
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        syslog(LOG_ERR, "Failed to install SIGTERM handler: %s", strerror(errno));
        goto cleanup;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open gpiochip0: %s", strerror(errno));
        goto cleanup;
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        lines[i] = gpiod_chip_get_line(chip, sensor_pins[i]);
        if (!lines[i]) {
            syslog(LOG_ERR, "Failed to get line %u: %s", sensor_pins[i], strerror(errno));
            goto cleanup;
        }

        if (gpiod_line_request_input(lines[i], "flame_monitor") < 0) {
            syslog(LOG_ERR, "Failed to request line %u as input: %s", sensor_pins[i], strerror(errno));
            goto cleanup;
        }

        int val = gpiod_line_get_value(lines[i]);
        if (val < 0) {
            syslog(LOG_ERR, "Failed to read initial value on line %u: %s", sensor_pins[i], strerror(errno));
            goto cleanup;
        }
        prev_state[i] = val;
    }

    syslog(LOG_INFO, "Monitoring %d sensors on BCM GPIO %s", NUM_SENSORS,
           "2, 3, 4, 17, 27");

    while (program_running) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            int val = gpiod_line_get_value(lines[i]);
            if (val < 0) {
                syslog(LOG_ERR, "Failed to read sensor %d (GPIO %u): %s",
                       i, sensor_pins[i], strerror(errno));
                continue;
            }

            if (val == 0 && prev_state[i] == 1) {
                usleep(DEBOUNCE_MS * 1000);
                int confirm = gpiod_line_get_value(lines[i]);
                if (confirm == 0) {
                    if (log_event(i, sensor_pins[i]) != 0) {
                        syslog(LOG_ERR, "Failed to log event for sensor %d (GPIO %u)",
                               i, sensor_pins[i]);
                    }
                }
            }
            prev_state[i] = val;
        }
        usleep(POLL_MS * 1000);
    }

    syslog(LOG_INFO, "Shutting down");
    ret = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (lines[i])
            gpiod_line_release(lines[i]);
    }
    if (chip)
        gpiod_chip_close(chip);
    closelog();
    return ret;
}

