 * TTP226 8-channel capacitive touch sensor reader for Raspberry Pi 3 Model B+.
 *
 * Wiring (TTP226 OUT0..OUT7 -> BCM GPIO):
 *   OUT0 -> GPIO5   OUT1 -> GPIO6   OUT2 -> GPIO13  OUT3 -> GPIO19
 *   OUT4 -> GPIO26  OUT5 -> GPIO12  OUT6 -> GPIO16  OUT7 -> GPIO20
 *
 * Build:  gcc -Wall -Wextra -o ttp226 ttp226.c -lgpiod
 * Run:    ./ttp226
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_MS 50

static const unsigned int gpio_pins[NUM_CHANNELS] = {5, 6, 13, 19, 26, 12, 16, 20};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static void print_timestamp(void)
{
    time_t rawtime;
    struct tm timeinfo;
    char buffer[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) != NULL &&
        strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%S", &timeinfo) > 0) {
        printf("[%s] ", buffer);
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line_bulk lines;
    struct gpiod_line *line;
    int prev_states[NUM_CHANNELS];
    int ret = EXIT_FAILURE;

    /* Initialize previous states to -1 so every first reading is reported. */
    for (int i = 0; i < NUM_CHANNELS; i++)
        prev_states[i] = -1;

    /* Install signal handlers for graceful shutdown. */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on RPi 3B+). */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Failed to open gpiochip0: %s (errno: %d)\n",
                strerror(errno), errno);
        return EXIT_FAILURE;
    }

    gpiod_line_bulk_init(&lines);

    /* Acquire all eight GPIO lines for input. */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        line = gpiod_chip_get_line(chip, gpio_pins[i]);
        if (line == NULL) {
            fprintf(stderr, "Failed to get GPIO line %u: %s (errno: %d)\n",
                    gpio_pins[i], strerror(errno), errno);
            goto cleanup;
        }
        gpiod_line_bulk_add(&lines, line);
    }

    /* Request all lines as inputs. */
    if (gpiod_line_request_bulk_input(&lines, "ttp226-touch") < 0) {
        fprintf(stderr, "Failed to request GPIO lines as inputs: %s (errno: %d)\n",
                strerror(errno), errno);
        goto cleanup;
    }

    printf("TTP226 touch sensor reader started. Press Ctrl+C to exit.\n");

    /* Main polling loop. */
    while (program_running) {
        int values[NUM_CHANNELS];
        int read_ok = 1;

        for (int i = 0; i < NUM_CHANNELS; i++) {
            int val = gpiod_line_get_value(gpiod_line_bulk_get_line(&lines, i));
            if (val < 0) {
                fprintf(stderr, "Failed to read GPIO line %u: %s (errno: %d)\n",
                        gpio_pins[i], strerror(errno), errno);
                read_ok = 0;
                break;
            }
            values[i] = val;
        }

        if (!read_ok) {
            break;
        }

        for (int i = 0; i < NUM_CHANNELS; i++) {
            if (values[i] != prev_states[i]) {
                print_timestamp();
                printf("Channel %d (GPIO %u): %s\n",
                       i, gpio_pins[i],
                       values[i] ? "Touched" : "Released");
                fflush(stdout);
                prev_states[i] = values[i];
            }
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    return ret;
}

