/*
 * Adaptive Grow Light System — Raspberry Pi 4 Model B
 *
 * Hardware:
 *   - VEML7700 ambient light sensor on I2C bus 1, address 0x29
 *   - Grow-light LED on GPIO18 (BCM), hardware PWM at 1000 Hz
 *
 * Behavior:
 *   Samples lux every 1 s, maps lux → PWM duty (0–100), logs to grow_log.txt.
 *   Handles SIGINT/SIGTERM for graceful shutdown.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS          "/dev/i2c-1"
#define VEML7700_ADDR    0x29

#define GROW_LIGHT_GPIO  18          /* BCM 18 — hardware PWM capable */
#define PWM_FREQ_HZ      1000        /* 1 kHz hardware PWM */
#define PWM_RANGE        100         /* 0–100 duty steps */

#define SAMPLE_PERIOD_S  1           /* seconds between samples */
#define LOG_FILE         "grow_log.txt"

/* VEML7700 register addresses */
#define VEML7700_REG_CONF  0x00
#define VEML7700_REG_ALS   0x04

/* VEML7700 config: ALS_EN=1, ALS_IT=50 ms (0x0000), no shutdown */
#define VEML7700_CONF_VAL  0x0000

/* Lux thresholds (linear mapping) */
#define LUX_THRESHOLD_1  100
#define LUX_THRESHOLD_2  500
#define LUX_THRESHOLD_3  1000

#define LUX_THRESHOLD_1_DUTY  100
#define LUX_THRESHOLD_2_DUTY  75
#define LUX_THRESHOLD_3_DUTY  50
#define LUX_THRESHOLD_4_DUTY  25

/* ----------------------------- Globals ---------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd = -1;
static FILE    *g_log_fp = NULL;

/* ----------------------------- Prototypes -------------------------------- */
static void signal_handler(int sig);
static int  veml7700_init(int fd);
static int  veml7700_read_lux(int fd, uint16_t *lux_out);
static int  set_led_brightness(int gpio, int duty);
static void log_data(FILE *fp, int lux, int brightness, int error_code);
static void cleanup(void);

/* ----------------------------- Signal handler ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- VEML7700 helpers -------------------------- */
static int veml7700_init(int fd)
{
    /* Write config: ALS_EN=1, ALS_IT=50 ms, no shutdown */
    uint8_t buf[3];
    buf[0] = VEML7700_REG_CONF;
    buf[1] = (VEML7700_CONF_VAL >> 8) & 0xFF;
    buf[2] = VEML7700_CONF_VAL & 0xFF;

    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "VEML7700 config write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int veml7700_read_lux(int fd, uint16_t *lux_out)
{
    uint8_t reg = VEML7700_REG_ALS;
    uint8_t data[2];

    /* Point to the ALS register */
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "VEML7700 register select failed: %s\n", strerror(errno));
        return -1;
    }

    /* Read 2 bytes (big-endian) */
    ssize_t n = read(fd, data, sizeof(data));
    if (n != (ssize_t)sizeof(data)) {
        fprintf(stderr, "VEML7700 read failed (got %zd bytes): %s\n",
                n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }

    *lux_out = ((uint16_t)data[0] << 8) | data[1];
    return 0;
}

/* ----------------------------- PWM helpers ------------------------------- */
static int set_led_brightness(int gpio, int duty)
{
    if (gpioPWM(gpio, duty) < 0) {
        fprintf(stderr, "gpioPWM failed on GPIO %d: %s\n",
                gpio, pigpio_error(gpioPWM(gpio, duty)));
        return -1;
    }
    return 0;
}

/* ----------------------------- Logging ----------------------------------- */
static void log_data(FILE *fp, int lux, int brightness, int error_code)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);

    fprintf(fp, "%s,lux=%d,brightness=%d,error=%d\n",
            ts, lux, brightness, error_code);
    fflush(fp);
}

/* ----------------------------- Cleanup ----------------------------------- */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    /* Ensure LED is off before terminating pigpio */
    gpioPWM(GROW_LIGHT_GPIO, 0);
    gpioTerminate();
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- I2C bus open --- */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, VEML7700_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                VEML7700_ADDR, strerror(errno));
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- VEML7700 sensor init --- */
    if (veml7700_init(g_i2c_fd) < 0) {
        fprintf(stderr, "VEML7700 initialization failed — sensor may be absent\n");
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- GPIO setup --- */
    if (gpioSetMode(GROW_LIGHT_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed for GPIO %d\n", GROW_LIGHT_GPIO);
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(GROW_LIGHT_GPIO, PWM_FREQ_HZ) < 0) {
        fprintf(stderr, "gpioSetPWMfrequency failed for GPIO %d\n", GROW_LIGHT_GPIO);
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(GROW_LIGHT_GPIO, PWM_RANGE) < 0) {
        fprintf(stderr, "gpioSetPWMrange failed for GPIO %d\n", GROW_LIGHT_GPIO);
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Log file --- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Failed to open log file %s: %s\n",
                LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signals --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Adaptive grow light system started. Sampling every %d s. "
           "Press Ctrl+C to exit.\n", SAMPLE_PERIOD_S);

    /* --- Main loop --- */
    while (g_running) {
        uint16_t lux = 0;
        int error_code = 0;

        if (veml7700_read_lux(g_i2c_fd, &lux) < 0) {
            error_code = 1;
            lux = 0;
        }

        int brightness;
        if (lux < LUX_THRESHOLD_1) {
            brightness = LUX_THRESHOLD_1_DUTY;
        } else if (lux < LUX_THRESHOLD_2) {
            brightness = LUX_THRESHOLD_2_DUTY;
        } else if (lux < LUX_THRESHOLD_3) {
            brightness = LUX_THRESHOLD_3_DUTY;
        } else {
            brightness = LUX_THRESHOLD_4_DUTY;
        }

        if (set_led_brightness(GROW_LIGHT_GPIO, brightness) < 0) {
            error_code = 2;
        }

        log_data(g_log_fp, (int)lux, brightness, error_code);

        sleep(SAMPLE_PERIOD_S);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

