        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Log file --- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Failed to open log file %s: %s\n",
                LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signals --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Adaptive grow light system started. Sampling every %d s. "
           "Press Ctrl+C to exit.\n", SAMPLE_PERIOD_S);

    /* --- Main loop --- */
    while (g_running) {
        uint16_t lux = 0;
        int error_code = 0;

        if (veml7700_read_lux(g_i2c_fd, &lux) < 0) {
            error_code = 1;
            lux = 0;
        }

        int brightness;
        if (lux < LUX_THRESHOLD_1) {
            brightness = LUX_THRESHOLD_1_DUTY;
        } else if (lux < LUX_THRESHOLD_2) {
            brightness = LUX_THRESHOLD_2_DUTY;
        } else if (lux < LUX_THRESHOLD_3) {
            brightness = LUX_THRESHOLD_3_DUTY;
        } else {
            brightness = LUX_THRESHOLD_4_DUTY;
        }

        if (set_led_brightness(GROW_LIGHT_GPIO, brightness) < 0) {
            error_code = 2;
        }

        log_data(g_log_fp, (int)lux, brightness, error_code);

        sleep(SAMPLE_PERIOD_S);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

