                fprintf(stderr, "Error: Failed to set alert pin HIGH.\n");
                log_event("Error: Failed to set alert pin HIGH.");
            } else {
                gpioDelay(ALERT_DURATION_US);
                if (gpioWrite(ALERT_PIN, 0) != 0) {
                    fprintf(stderr, "Error: Failed to set alert pin LOW.\n");
                    log_event("Error: Failed to set alert pin LOW.");
                }
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nExiting gracefully...\n");
    log_event("Program exiting.");
    cleanup_resources();
    return EXIT_SUCCESS;
}

