/*
 * Raspberry Pi Zero W – Sensirion SLF3S-1300F Liquid Flow Sensor monitor
 *
 * Wiring:
 *   SLF3S-1300F SDA  -> GPIO2 (pin 3, I2C bus 1 SDA)
 *   SLF3S-1300F SCL  -> GPIO3 (pin 5, I2C bus 1 SCL)
 *   SLF3S-1300F VDD  -> 3.3 V
 *   SLF3S-1300F GND  -> GND
 *
 * I2C address: 0x00 (7-bit, default)
 * Command:     0x36 0x08  (continuous measurement, mass flow, no averaging)
 * Response:    2 bytes signed 16-bit flow (big-endian), 1 byte CRC-8
 * CRC-8:       polynomial 0x31, init 0xFF, no final XOR
 *
 * Build:  gcc -O2 -Wall -Wextra -o cooling_monitor cooling_monitor.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SLF3S_ADDR     0x00
#define CMD_CONT_MEAS  0x3608
#define LOG_FILE       "cooling_log.csv"
#define SAMPLE_PERIOD  1          /* seconds */
#define FIRST_READ_DELAY 2        /* seconds after power-up / reset */

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion: poly 0x31, init 0xFF, no final XOR)               */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_cmd(int fd, uint16_t cmd)
{
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        perror("i2c_write_cmd: write");
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n != (ssize_t)len) {
        perror("i2c_read_bytes: read");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor read                                                         */
/* ------------------------------------------------------------------ */
/*
 * Returns 0 on success, -1 on I/O error, -2 on CRC mismatch.
 * On success, *flow_rate holds the signed 16-bit value (ml/min).
 */
static int read_flow_rate(int fd, int16_t *flow_rate, uint8_t *flags)
{
    uint8_t buf[3];

    if (i2c_read_bytes(fd, buf, sizeof(buf)) != 0)
        return -1;

    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch: calc=0x%02X recv=0x%02X\n",
                crc8(buf, 2), buf[2]);
        return -2;
    }

    *flow_rate = (int16_t)((buf[0] << 8) | buf[1]);
    *flags     = buf[2];
    return 0;
}

/* ------------------------------------------------------------------ */
/* CSV logging                                                         */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, int16_t flow_rate, uint8_t flags,
                     const char *status)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%d,%s\n", ts, flow_rate, status);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* ---- open I2C bus ---- */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        perror("open " I2C_BUS);
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SLF3S_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- open CSV (create + header) ---- */
    int file_exists = (access(LOG_FILE, F_OK) == 0);
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("fopen " LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }
    if (!file_exists)
        fprintf(g_log_fp, "Timestamp,Flow Rate (ml/min),Status\n");

    /* ---- start continuous measurement ---- */
    if (i2c_write_cmd(g_i2c_fd, CMD_CONT_MEAS) != 0) {
        fprintf(stderr, "Failed to start continuous measurement\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Allow first conversion to complete */
    sleep(FIRST_READ_DELAY);

    printf("Monitoring coolant flow. Press Ctrl+C to stop.\n");

    /* ---- main loop ---- */
    while (g_running) {
        int16_t flow_rate;
        uint8_t flags;
        int rc = read_flow_rate(g_i2c_fd, &flow_rate, &flags);

        if (rc == 0) {
            /* Plausibility check: 0–100 ml/min */
            if (flow_rate < 0 || flow_rate > 100) {
                fprintf(stderr, "Out-of-range flow rate: %d\n", flow_rate);
                log_data(g_log_fp, flow_rate, flags, "INVALID");
            } else {
                log_data(g_log_fp, flow_rate, flags, "OK");
            }
        } else if (rc == -2) {
            fprintf(stderr, "CRC error – logging and recovering\n");
            log_data(g_log_fp, 0, 0, "ERROR");
            /* Attempt recovery: close and reopen bus */
            close(g_i2c_fd);
            g_i2c_fd = -1;
            sleep(1);
            g_i2c_fd = open(I2C_BUS, O_RDWR);
            if (g_i2c_fd < 0) {
                perror("recovery open " I2C_BUS);
                break;
            }
            if (ioctl(g_i2c_fd, I2C_SLAVE, SLF3S_ADDR) < 0) {
                perror("recovery ioctl I2C_SLAVE");
                break;
            }
            if (i2c_write_cmd(g_i2c_fd, CMD_CONT_MEAS) != 0) {
                fprintf(stderr, "Recovery measurement start failed\n");
                break;
            }
            sleep(FIRST_READ_DELAY);
        } else {
            fprintf(stderr, "I2C read error – logging and recovering\n");
            log_data(g_log_fp, 0, 0, "ERROR");
            close(g_i2c_fd);
            g_i2c_fd = -1;
            sleep(1);
            g_i2c_fd = open(I2C_BUS, O_RDWR);
            if (g_i2c_fd < 0) {
                perror("recovery open " I2C_BUS);
                break;
            }
            if (ioctl(g_i2c_fd, I2C_SLAVE, SLF3S_ADDR) < 0) {
                perror("recovery ioctl I2C_SLAVE");
                break;
            }
            if (i2c_write_cmd(g_i2c_fd, CMD_CONT_MEAS) != 0) {
                fprintf(stderr, "Recovery measurement start failed\n");
                break;
            }
            sleep(FIRST_READ_DELAY);
        }

        sleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

