#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <stdbool.h>
#include <pigpio.h>

#define LEFT_SENSOR_PIN   17
#define MIDDLE_SENSOR_PIN 27
#define RIGHT_SENSOR_PIN  22
#define LOG_FILE_NAME     "path_log.csv"
#define SAMPLE_DELAY_US   50000  /* 50 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handler(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int get_timestamp(char *buf, size_t len)
{
    time_t rawtime;
    struct tm tm_info;

    if (time(&rawtime) == (time_t)-1) {
        perror("time()");
        return -1;
    }
    if (localtime_r(&rawtime, &tm_info) == NULL) {
        perror("localtime_r()");
        return -1;
    }
    if (strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }
    return 0;
}

static int log_data(FILE *fp, const char *timestamp, int left, int middle, int right)
{
    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, left, middle, right) < 0) {
        perror("fprintf()");
        return -1;
    }
    if (fflush(fp) != 0) {
        perror("fflush()");
        return -1;
    }
    return 0;
}

int main(void)
{
    FILE *fp = NULL;
    int left_value, middle_value, right_value;
    char timestamp[32];
    int ret = EXIT_FAILURE;

    if (install_signal_handler() != 0) {
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", LEFT_SENSOR_PIN);
        goto cleanup;
    }
