#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>
#include <linux/gpio_event.h>

#define GPIO_CHIP_NAME "/dev/gpiochip4"
#define TOUCH_SENSOR_PIN 23
#define LED_PIN 24
#define LOG_FILE "touch_log.txt"
#define POLL_TIMEOUT_MS 1000

static volatile sig_atomic_t running = 1;
static int log_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_event(int led_state) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (dprintf(log_fd, "%s - Touch detected, LED %s\n", timestamp, led_state ? "ON" : "OFF") < 0) {
        fprintf(stderr, "dprintf failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(log_fd) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }

    int chip_fd = open(GPIO_CHIP_NAME, O_RDWR);
    if (chip_fd < 0) {
        fprintf(stderr, "Failed to open GPIO chip '%s': %s\n", GPIO_CHIP_NAME, strerror(errno));
        close(log_fd);
        log_fd = -1;
        return EXIT_FAILURE;
    }

    struct gpio_line_request touch_req;
    memset(&touch_req, 0, sizeof(touch_req));
    touch_req.line_offset = TOUCH_SENSOR_PIN;
    touch_req.request_type = GPIO_LINE_REQUEST_EVENT_RISING_EDGE;
    touch_req.flags = 0;
    strncpy(touch_req.consumer_label, "touch_lamp", sizeof(touch_req.consumer_label) - 1);

    if (ioctl(chip_fd, GPIO_GET_LINE_REQUEST_IOCTL, &touch_req) < 0) {
        fprintf(stderr, "Failed to request touch sensor line %d: %s\n", TOUCH_SENSOR_PIN, strerror(errno));
        close(chip_fd);
        close(log_fd);
        log_fd = -1;
        return EXIT_FAILURE;
    }

    struct gpio_line_request led_req;
    memset(&led_req, 0, sizeof(led_req));
    led_req.line_offset = LED_PIN;
    led_req.request_type = GPIO_LINE_REQUEST_DIRECTION_OUTPUT;
    led_req.flags = 0;
    strncpy(led_req.consumer_label, "touch_lamp", sizeof(led_req.consumer_label) - 1);

    if (ioctl(chip_fd, GPIO_GET_LINE_REQUEST_IOCTL, &led_req) < 0) {
        fprintf(stderr, "Failed to request LED line %d: %s\n", LED_PIN, strerror(errno));
        close(chip_fd);
        close(log_fd);
        log_fd = -1;
        return EXIT_FAILURE;
    }

    int led_state = 0;
    if (ioctl(led_req.fd, GPIO_SET_LINE_VALUE_IOCTL, &led_state) < 0) {
        fprintf(stderr, "Failed to initialize LED state: %s\n", strerror(errno));
        close(chip_fd);
        close(log_fd);
        log_fd = -1;
        return EXIT_FAILURE;
    }

    printf("Touch-activated lamp started. Press Ctrl+C to exit.\n");

    while (running) {
        struct gpio_event event;
        ssize_t ret = read(touch_req.fd, &event, sizeof(event));

        if (ret < 0) {
            if (errno == EINTR) {
                continue;
            }
            fprintf(stderr, "Error reading touch sensor: %s\n", strerror(errno));
            break;
        }

        if (ret == 0) {
            continue;
        }

        if (event.event_type == GPIO_EVENT_RISING_EDGE) {
            led_state = !led_state;
            if (ioctl(led_req.fd, GPIO_SET_LINE_VALUE_IOCTL, &led_state) < 0) {
                fprintf(stderr, "Failed to set LED state: %s\n", strerror(errno));
                break;
            }
            if (log_event(led_state) < 0) {
                fprintf(stderr, "Logging failed, continuing...\n");
            }
        }
    }

    printf("\nShutting down...\n");

    if (led_req.fd >= 0) {
        led_state = 0;
        ioctl(led_req.fd, GPIO_SET_LINE_VALUE_IOCTL, &led_state);
        close(led_req.fd);
    }
    if (touch_req.fd >= 0) {
        close(touch_req.fd);
    }
    if (chip_fd >= 0) {
        close(chip_fd);
    }
    if (log_fd >= 0) {
        close(log_fd);
        log_fd = -1;
    }

    printf("Touch-activated lamp stopped.\n");
    return EXIT_SUCCESS;
}

