#include <errno.h>
#include <signal.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

#include <gpiod.h>

/* ----------------------------- Configuration ----------------------------- */
#define FLAME_SENSOR_PIN  17          /* BCM GPIO17 — KY-026 DO  */
#define BUZZER_PIN        18          /* BCM GPIO18 — buzzer ctrl */
#define CHIP_NAME         "gpiochip0" /* main GPIO controller on Pi 3B+ */

#define POLL_INTERVAL_US  500000      /* 500 ms between polls          */
#define BUZZER_DURATION_S 2           /* buzzer on for 2 s             */
#define LOG_FILE          "alert_log.txt"

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static FILE                 *g_log_fp  = NULL;

/* --------------------------- Signal handling ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;          /* tell main loop to exit cleanly          */
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------- Logging --------------------------------- */
static int log_event(const char *message)
{
    time_t     rawtime;
    struct tm  timeinfo;
    char       timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        perror("localtime_r");
        return -1;
    }
    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(g_log_fp, "%s: %s\n", timestamp, message) < 0) {
        perror("fprintf");
        return -1;
    }
    if (fflush(g_log_fp) != 0) {
        perror("fflush");
        return -1;
    }
    return 0;
}

/* ------------------------------ Buzzer control --------------------------- */
static int buzzer_on(struct gpiod_line *buzzer)
{
    if (gpiod_line_set_value(buzzer, 1) < 0) {
        perror("gpiod_line_set_value(buzzer, 1)");
        return -1;
    }
    return 0;
}

static int buzzer_off(struct gpiod_line *buzzer)
{
    if (gpiod_line_set_value(buzzer, 0) < 0) {
        perror("gpiod_line_set_value(buzzer, 0)");
        return -1;
    }
    return 0;
}

/* ------------------------------- Main ------------------------------------ */
int main(void)
{
    struct gpiod_chip  *chip     = NULL;
    struct gpiod_line  *flame    = NULL;
    struct gpiod_line  *buzzer   = NULL;
    int                 ret      = EXIT_FAILURE;
    int                 prev_flame = 1;   /* assume no flame at startup */

    /* ---- Open log file --------------------------------------------------- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        perror("fopen(" LOG_FILE ")");
        return EXIT_FAILURE;
    }

    /* ---- Install signal handlers ---------------------------------------- */
    if (install_signal_handlers() != 0) {
        goto cleanup_log;
    }

    /* ---- Open GPIO chip -------------------------------------------------- */
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (chip == NULL) {
        perror("gpiod_chip_open_by_name");
        goto cleanup_log;
    }

    /* ---- Get lines ------------------------------------------------------- */
    flame = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    if (flame == NULL) {
        perror("gpiod_chip_get_line(flame)");
        goto cleanup_chip;
    }

    buzzer = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (buzzer == NULL) {
        perror("gpiod_chip_get_line(buzzer)");
        goto cleanup_chip;
    }

    /* ---- Request lines --------------------------------------------------- */
    if (gpiod_line_request_input(flame, "flame_sensor") < 0) {
        perror("gpiod_line_request_input(flame)");
        goto cleanup_chip;
    }

    if (gpiod_line_request_output(buzzer, "buzzer", 0) < 0) {
        perror("gpiod_line_request_output(buzzer)");
        goto cleanup_chip;
    }

    /* ---- Log startup ----------------------------------------------------- */
    if (log_event("System started") != 0) {
        goto cleanup_chip;
    }

    /* ---- Main polling loop ---------------------------------------------- */
    while (g_running) {
        int val = gpiod_line_get_value(flame);
        if (val < 0) {
            perror("gpiod_line_get_value(flame)");
            break;
        }

        /* LOW (0) means flame detected (active-low sensor) */
        if (val == 0 && prev_flame == 1) {
            printf("Flame detected!\n");
            fflush(stdout);

            if (log_event("FLAME DETECTED") != 0) {
                break;
            }

            if (buzzer_on(buzzer) != 0) {
                break;
            }

            /* 2 s buzzer on — break into 100 ms slices so we can exit promptly */
            for (int elapsed = 0; elapsed < BUZZER_DURATION_S * 1000 &&
                          g_running; elapsed += 100) {
                usleep(100000);
            }

            if (buzzer_off(buzzer) != 0) {
                break;
            }
        }

        prev_flame = val;
        usleep(POLL_INTERVAL_US);
    }

    /* ---- Clean shutdown -------------------------------------------------- */
    if (buzzer_off(buzzer) != 0) {
        goto cleanup_chip;
    }
    if (log_event("System stopped") != 0) {
        goto cleanup_chip;
    }
    ret = EXIT_SUCCESS;

cleanup_chip:
    if (flame != NULL) {
        gpiod_line_release(flame);
    }
    if (buzzer != NULL) {
        gpiod_line_release(buzzer);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

cleanup_log:
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }

    return ret;
}

