/*
 * TMAG5110A1 Hall-Effect Latch Sensor Monitor
 * Board:  Raspberry Pi 4 Model B
 * Library: pigpio (modern, actively maintained)
 *
 * Wiring (BCM numbering):
 *   Sensor 1 OUT -> GPIO4
 *   Sensor 2 OUT -> GPIO17
 *   Sensor 3 OUT -> GPIO27
 *
 * The TMAG5110A1 output is open-drain: it pulls the line LOW when a south
 * pole is present (magnet detected) and releases it HIGH when the magnet
 * is removed.  Internal pull-ups are enabled on each GPIO so the line
 * reads HIGH when no magnet is present.
 *
 * Build:  gcc -Wall -Wextra -O2 -o magnet_monitor magnet_monitor.c -lpigpio -lrt
 * Run:    sudo ./magnet_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_1_PIN 4
#define SENSOR_2_PIN 17
#define SENSOR_3_PIN 27

#define LOG_FILE_NAME "magnet_log.txt"
#define POLL_DELAY_US 100000  /* 100 ms */

/* ------------------------------------------------------------------ */
/* Global state for signal handler                                     */
/* ------------------------------------------------------------------ */
static volatile sig_atomic_t g_running = 1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits and cleanup runs       */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read a sensor pin.  Returns 0 or 1 on success, -1 on error.         */
/* ------------------------------------------------------------------ */
static int read_sensor(int pin)
{
    int level = gpioRead(pin);
    if (level < 0) {
        fprintf(stderr, "Error: gpioRead(%d) failed (pigpio error %d).\n",
                pin, level);
        return -1;
    }
    return level;
}

/* ------------------------------------------------------------------ */
/* Log a state change with an ISO-8601 timestamp                       */
/* ------------------------------------------------------------------ */
static void log_state_change(int sensor_id, int state)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "Error: time() failed.\n");
        return;
    }

    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "Error: localtime_r() failed.\n");
        return;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%dT%H:%M:%S%z", &tm_info) == 0) {
