/*
 * touch_counter.c — Raspberry Pi Zero W
 *
 * Reads 8-channel TTP226 capacitive touch sensors on BCM pins 5..12
 * and drives an 8-bit binary counter on BCM pins 17..24.
 *
 * Build:  gcc -O2 -Wall -Wextra -o touch_counter touch_counter.c -lgpiod
 * Run:    sudo ./touch_counter   (root needed for /dev/gpiochip0 access)
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define CHIP_NAME    "gpiochip0"

/* TTP226 OUT1..OUT8 -> BCM 5..12 */
static const unsigned int sensor_pins[NUM_CHANNELS] = {5, 6, 7, 8, 9, 10, 11, 12};
/* Binary counter bit outputs -> BCM 17..24 */
static const unsigned int counter_pins[NUM_CHANNELS] = {17, 18, 19, 20, 21, 22, 23, 24};

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static void log_event(FILE *log, int channel, int counter_value)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        perror("time");
        return;
    }

    struct tm tm_utc;
    if (gmtime_r(&now, &tm_utc) == NULL) {
        perror("gmtime_r");
        return;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (fprintf(log, "%s, Channel: %d, Counter: %d\n", ts, channel, counter_value) < 0) {
        perror("fprintf(log)");
    }
    if (fflush(log) != 0) {
        perror("fflush(log)");
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *sensor_lines[NUM_CHANNELS];
    struct gpiod_line *counter_lines[NUM_CHANNELS];
    int counter_value = 0;
    FILE *log_file = NULL;
    int ret = EXIT_FAILURE;

    for (int i = 0; i < NUM_CHANNELS; i++) {
        sensor_lines[i] = NULL;
        counter_lines[i] = NULL;
    }

    if (install_signal_handlers() != 0) {
        goto cleanup;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (chip == NULL) {
        perror("gpiod_chip_open_by_name");
        goto cleanup;
    }

    /* Request sensor lines as inputs */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        sensor_lines[i] = gpiod_chip_get_line(chip, sensor_pins[i]);
        if (sensor_lines[i] == NULL) {
            fprintf(stderr, "gpiod_chip_get_line(sensor, BCM %u): %s\n",
                    sensor_pins[i], strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_request_input(sensor_lines[i], "ttp226-sensor") != 0) {
            fprintf(stderr, "gpiod_line_request_input(sensor, BCM %u): %s\n",
                    sensor_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    /* Request counter lines as outputs, initial value 0 */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        counter_lines[i] = gpiod_chip_get_line(chip, counter_pins[i]);
        if (counter_lines[i] == NULL) {
            fprintf(stderr, "gpiod_chip_get_line(counter, BCM %u): %s\n",
                    counter_pins[i], strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_request_output(counter_lines[i], "ttp226-counter", 0) != 0) {
            fprintf(stderr, "gpiod_line_request_output(counter, BCM %u): %s\n",
                    counter_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    log_file = fopen("touch_log.txt", "a");
    if (log_file == NULL) {
        perror("fopen(touch_log.txt)");
        /* Continue without file logging */
    }

    /* 200 ms stabilization delay for TTP226 module */
    usleep(200000);

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int prev_counter = counter_value;

        for (int i = 0; i < NUM_CHANNELS; i++) {
            int val = gpiod_line_get_value(sensor_lines[i]);
            if (val < 0) {
                fprintf(stderr, "gpiod_line_get_value(sensor, BCM %u): %s\n",
                        sensor_pins[i], strerror(errno));
                continue;
            }

            /* Rising edge: idle 0 V -> touched 1 V */
            if (val == 1 && (prev_counter & (1 << i)) == 0) {
                counter_value = (counter_value + 1) & 0xFF;

                for (int j = 0; j < NUM_CHANNELS; j++) {
                    int bit = (counter_value >> j) & 1;
                    if (gpiod_line_set_value(counter_lines[j], bit) != 0) {
                        fprintf(stderr, "gpiod_line_set_value(counter, BCM %u): %s\n",
                                counter_pins[j], strerror(errno));
                    }
                }

                log_event(log_file, i + 1, counter_value);
                printf("Touch on channel %d | Counter: %d\n", i + 1, counter_value);
            }
        }

        usleep(10000); /* 10 ms poll interval */
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Reset counter outputs to 0 before release */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (counter_lines[i] != NULL) {
            if (gpiod_line_set_value(counter_lines[i], 0) != 0) {
                fprintf(stderr, "gpiod_line_set_value(reset, BCM %u): %s\n",
                        counter_pins[i], strerror(errno));
            }
            gpiod_line_release(counter_lines[i]);
        }
    }

    /* Release sensor lines */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (sensor_lines[i] != NULL) {
            gpiod_line_release(sensor_lines[i]);
        }
    }

    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    if (log_file != NULL) {
        if (fclose(log_file) != 0) {
            perror("fclose(log_file)");
        }
    }

    return ret;
}

