#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR1_PIN 17
#define SENSOR2_PIN 18
#define SENSOR3_PIN 27
#define SENSOR4_PIN 22
#define LOG_FILE "tracking_log.csv"
#define POLL_DELAY_US 100000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor(int pin) {
    int value = gpioRead(pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %s\n", pin, pigpio_error(value));
        return -1;
    }
    return value;
}

static void log_data(FILE *fp, int s1, int s2, int s3, int s4) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%d,%d,%d,%d\n", timestamp, s1, s2, s3, s4) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
    }
}

int main(void) {
    int pins[] = {SENSOR1_PIN, SENSOR2_PIN, SENSOR3_PIN, SENSOR4_PIN};
    int num_pins = sizeof(pins) / sizeof(pins[0]);
    int init_failed = 0;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error registering SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error registering SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    for (int i = 0; i < num_pins; i++) {
        if (gpioSetMode(pins[i], PI_INPUT) != 0) {
            fprintf(stderr, "Error setting GPIO %d as input\n", pins[i]);
            init_failed = 1;
        }
    }

    if (init_failed) {
        gpioTerminate();
        return 1;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return 1;
    }

    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        if (fprintf(fp, "timestamp,sensor1,sensor2,sensor3,sensor4\n") < 0) {
            fprintf(stderr, "Error writing header: %s\n", strerror(errno));
        }
        if (fflush(fp) != 0) {
            fprintf(stderr, "Error flushing header: %s\n", strerror(errno));
        }
    }

    while (running) {
        int s1 = read_sensor(SENSOR1_PIN);
        int s2 = read_sensor(SENSOR2_PIN);
        int s3 = read_sensor(SENSOR3_PIN);
        int s4 = read_sensor(SENSOR4_PIN);

        if (s1 >= 0 && s2 >= 0 && s3 >= 0 && s4 >= 0) {
            log_data(fp, s1, s2, s3, s4);
        } else {
            fprintf(stderr, "Error reading one or more sensors, skipping log entry\n");
        }

        gpioDelay(POLL_DELAY_US);
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
    }

    gpioTerminate();
    return 0;
}

