#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 18
#define LOG_FILE "/var/log/tilt_events.log"
#define POLL_DELAY_US 100000   /* 100 ms */
#define DEBOUNCE_DELAY_US 50000 /* 50 ms */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void log_event(int sensor_number)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (fprintf(g_log_fp, "%s, Sensor %d tilted\n", timestamp, sensor_number) < 0) {
        fprintf(stderr, "fprintf to log failed\n");
        return;
    }

    if (fflush(g_log_fp) != 0) {
        fprintf(stderr, "fflush failed\n");
    }
}

int main(void)
{
    int ret;
    int prev1 = 1, prev2 = 1;
    int active1 = 0, active2 = 0;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        perror("fopen log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    ret = gpioSetMode(SENSOR_1_GPIO, PI_INPUT);
    if (ret != 0) {
        fprintf(stderr, "gpioSetMode(SENSOR_1_GPIO) failed: %d\n", ret);
        goto cleanup;
    }
    ret = gpioSetMode(SENSOR_2_GPIO, PI_INPUT);
    if (ret != 0) {
        fprintf(stderr, "gpioSetMode(SENSOR_2_GPIO) failed: %d\n", ret);
        goto cleanup;
    }

    /* Active-low sensors: pull-up so an unconnected line reads high. */
    ret = gpioSetPullUpDown(SENSOR_1_GPIO, PI_PUD_UP);
    if (ret != 0) {
        fprintf(stderr, "gpioSetPullUpDown(SENSOR_1_GPIO) failed: %d\n", ret);
        goto cleanup;
    }
    ret = gpioSetPullUpDown(SENSOR_2_GPIO, PI_PUD_UP);
    if (ret != 0) {
        fprintf(stderr, "gpioSetPullUpDown(SENSOR_2_GPIO) failed: %d\n", ret);
        goto cleanup;
    }

    /* Allow pull-up to settle. */
    gpioDelay(10000);

    printf("Tilt sensor monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int s1 = gpioRead(SENSOR_1_GPIO);
        int s2 = gpioRead(SENSOR_2_GPIO);

        if (s1 < 0) {
            fprintf(stderr, "gpioRead(SENSOR_1_GPIO) failed: %d\n", s1);
            break;
        }
        if (s2 < 0) {
            fprintf(stderr, "gpioRead(SENSOR_2_GPIO) failed: %d\n", s2);
            break;
        }

        /* Detect transition from inactive (1) to active (0) with debounce. */
        if (s1 == 0 && prev1 == 1) {
            gpioDelay(DEBOUNCE_DELAY_US);
            int confirm = gpioRead(SENSOR_1_GPIO);
            if (confirm == 0) {
                log_event(1);
                active1 = 1;
            }
        } else if (s1 == 1 && prev1 == 0) {
            active1 = 0;
        }

        if (s2 == 0 && prev2 == 1) {
            gpioDelay(DEBOUNCE_DELAY_US);
            int confirm = gpioRead(SENSOR_2_GPIO);
            if (confirm == 0) {
                log_event(2);
                active2 = 1;
            }
        } else if (s2 == 1 && prev2 == 0) {
            active2 = 0;
        }

        prev1 = s1;
        prev2 = s2;

        gpioDelay(POLL_DELAY_US);
    }

cleanup:
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

