 *
 * Reads two TCRT5000 IR obstacle-avoidance sensors on GPIO17 and GPIO27
 * (active-low: 0 = obstacle detected, 1 = clear) and lights an LED on
 * GPIO22 when both sensors detect an obstacle.  Samples every 100 ms
 * and logs to obstacle_log.csv.
 *
 * Build:  gcc -O2 -Wall -Wextra -o obstacle_avoidance obstacle_avoidance.c -lpigpio -lrt
 * Run:    sudo ./obstacle_avoidance
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_1_PIN 17
#define SENSOR_2_PIN 27
#define LED_PIN      22
#define LOG_FILE     "obstacle_log.csv"
#define POLL_US      100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log = NULL;

/* ------------------------------------------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(int chip)
{
    if (chip >= 0) {
        gpioWrite(LED_PIN, 0);
        gpioSetMode(LED_PIN, PI_INPUT);
        gpioSetMode(SENSOR_1_PIN, PI_INPUT);
        gpioSetMode(SENSOR_2_PIN, PI_INPUT);
        gpioTerminate();
    }
    if (g_log) {
        fclose(g_log);
        g_log = NULL;
    }
}

/* ------------------------------------------------------------------ */
static int log_sample(FILE *fp, int s1, int s2, int led)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (!localtime_r(&t, &tm)) {
        perror("localtime_r");
        return -1;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%d,%d,%d\n", ts, s1, s2, led) < 0) {
        perror("fprintf");
        return -1;
    }
    if (fflush(fp) != 0) {
        perror("fflush");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    int chip = -1;
    int rc = EXIT_FAILURE;

    /* ---- signal handling ------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* ---- pigpio init ----------------------------------------------- */
    chip = gpioInitialise();
    if (chip < 0) {
        fprintf(stderr, "gpioInitialise failed (pigpio error %d)\n", chip);
        return EXIT_FAILURE;
    }

    /* ---- GPIO configuration ---------------------------------------- */
    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(SENSOR_1_PIN) failed\n");
        goto out;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(SENSOR_2_PIN) failed\n");
        goto out;
    }
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(LED_PIN) failed\n");
        goto out;
    }
    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "gpioWrite(LED_PIN, 0) failed\n");
        goto out;
    }

    /* ---- open log file --------------------------------------------- */
    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        perror("fopen(" LOG_FILE ")");
        goto out;
    }

    /* ---- main loop ------------------------------------------------- */
    while (g_running) {
        int s1 = gpioRead(SENSOR_1_PIN);
        int s2 = gpioRead(SENSOR_2_PIN);

        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "gpioRead failed (s1=%d, s2=%d)\n", s1, s2);
            break;
        }

        /* Both sensors active-low: 0 = obstacle detected */
        int led = (s1 == 0 && s2 == 0) ? 1 : 0;
        if (gpioWrite(LED_PIN, led) != 0) {
            fprintf(stderr, "gpioWrite(LED_PIN) failed\n");
            break;
        }

        if (log_sample(g_log, s1, s2, led) != 0) {
            fprintf(stderr, "log_sample failed\n");
            break;
        }

        gpioDelay(POLL_US);
    }

    rc = EXIT_SUCCESS;

out:
    cleanup(chip);
    return rc;
}

