#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS 1
#define SI1175_ADDR 0x60

#define REG_ALS_VIS_DATA0 0x22
#define REG_ALS_VIS_DATA1 0x23

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_si1175_als(int handle, uint16_t *als_value) {
    int lsb = i2cReadByteData(handle, REG_ALS_VIS_DATA0);
    if (lsb < 0) {
        fprintf(stderr, "Error reading ALS_VIS_DATA0: %s\n", strerror(errno));
        return -1;
    }

    int msb = i2cReadByteData(handle, REG_ALS_VIS_DATA1);
    if (msb < 0) {
        fprintf(stderr, "Error reading ALS_VIS_DATA1: %s\n", strerror(errno));
        return -1;
    }

    *als_value = (uint16_t)((msb << 8) | lsb);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    int handle = i2cOpen(I2C_BUS, SI1175_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %s\n", SI1175_ADDR, strerror(errno));
        gpioTerminate();
        return 1;
    }

    printf("Si1175 ALS sensor reading started. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t als_value = 0;
        if (read_si1175_als(handle, &als_value) == 0) {
            printf("ALS VIS: %u\n", als_value);
        } else {
            fprintf(stderr, "Failed to read ALS data. Retrying...\n");
        }
        usleep(100000);
    }

    printf("\nExiting gracefully...\n");
    i2cClose(handle);
    gpioTerminate();
    return 0;
}

