#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LEFT_SENSOR_PIN   2
#define MIDDLE_SENSOR_PIN 3
#define RIGHT_SENSOR_PIN  4
#define POLL_DELAY_US     100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handler(void)
{
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    return sigaction(SIGINT, &sa, NULL);
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (code %d).\n", gpioInitialise());
        return EXIT_FAILURE;
    }

    if (install_signal_handler() != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler.\n");
    }

    int left_ok   = gpioSetMode(LEFT_SENSOR_PIN,   PI_INPUT);
    int middle_ok = gpioSetMode(MIDDLE_SENSOR_PIN, PI_INPUT);
    int right_ok  = gpioSetMode(RIGHT_SENSOR_PIN,  PI_INPUT);

    if (left_ok != 0 || middle_ok != 0 || right_ok != 0) {
        fprintf(stderr, "Error: failed to set GPIO modes (L=%d M=%d R=%d).\n",
                left_ok, middle_ok, right_ok);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int exit_code = EXIT_SUCCESS;

    while (g_running) {
        int left   = gpioRead(LEFT_SENSOR_PIN);
        int middle = gpioRead(MIDDLE_SENSOR_PIN);
        int right  = gpioRead(RIGHT_SENSOR_PIN);

        if (left < 0 || middle < 0 || right < 0) {
            fprintf(stderr, "Error: GPIO read failed (L=%d M=%d R=%d).\n",
                    left, middle, right);
            exit_code = EXIT_FAILURE;
            break;
        }

        printf("L:%d M:%d R:%d\n", left, middle, right);
        fflush(stdout);

        gpioDelay(POLL_DELAY_US);
    }

    gpioTerminate();
    return exit_code;
}

