/*
 * TTP226 8-channel capacitive touch sensor reader for Raspberry Pi 3 Model B+.
 *
 * Wiring (TTP226 breakout, 3.3 V logic):
 *   VCC  -> 3.3 V (pin 1)
 *   GND  -> GND  (pin 6)
 *   A0   -> GPIO5  (BCM 5,  pin 29)
 *   A1   -> GPIO6  (BCM 6,  pin 31)
 *   A2   -> GPIO13 (BCM 13, pin 33)
 *   A3   -> GPIO19 (BCM 19, pin 35)
 *   A4   -> GPIO26 (BCM 26, pin 37)
 *   A5   -> GPIO12 (BCM 12, pin 32)
 *   A6   -> GPIO16 (BCM 16, pin 36)
 *   A7   -> GPIO20 (BCM 20, pin 38)
 *
 * Build: gcc -o touch_poll touch_poll.c -lrt
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_MS 200

static const unsigned int channel_pins[NUM_CHANNELS] = {5, 6, 13, 19, 26, 12, 16, 20};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static void print_timestamp(void)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) == -1) {
        perror("clock_gettime");
        return;
    }
    double elapsed = (double)ts.tv_sec + (double)ts.tv_nsec / 1e9;
    printf("[%.3fs] ", elapsed);
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_CHANNELS];
    int values[NUM_CHANNELS];
    int ret = EXIT_FAILURE;

    for (int i = 0; i < NUM_CHANNELS; i++)
        lines[i] = NULL;

    if (install_signal_handlers() != 0)
        goto cleanup;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        perror("gpiod_chip_open_by_name(\"gpiochip0\")");
        goto cleanup;
    }

    for (int i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = gpiod_chip_get_line(chip, channel_pins[i]);
        if (lines[i] == NULL) {
            fprintf(stderr, "gpiod_chip_get_line failed for GPIO%u: %s\n",
                    channel_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (gpiod_line_request_input(lines[i], "ttp226-touch") < 0) {
            fprintf(stderr, "gpiod_line_request_input failed for GPIO%u: %s\n",
                    channel_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    printf("TTP226 touch sensor reader started. Press Ctrl+C to exit.\n");

    while (program_running) {
        for (int i = 0; i < NUM_CHANNELS; i++) {
            int v = gpiod_line_get_value(lines[i]);
            if (v < 0) {
                fprintf(stderr, "gpiod_line_get_value failed for GPIO%u: %s\n",
                        channel_pins[i], strerror(errno));
                goto cleanup;
            }
            values[i] = v;
        }

        print_timestamp();
        printf("CH1=%d CH2=%d CH3=%d CH4=%d CH5=%d CH6=%d CH7=%d CH8=%d\n",
               values[0], values[1], values[2], values[3],
               values[4], values[5], values[6], values[7]);
        fflush(stdout);

        struct timespec delay = {0, POLL_INTERVAL_MS * 1000000L};
        nanosleep(&delay, NULL);
    }

    ret = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (lines[i] != NULL)
            gpiod_line_release(lines[i]);
    }
    if (chip != NULL)
        gpiod_chip_close(chip);

    if (ret == EXIT_SUCCESS)
        printf("\nExiting gracefully.\n");
    return ret;
}

