static void set_led_color(int red, int green, int blue) {
    if (gpioPWM(RED_PIN, red) < 0)
        syslog(LOG_ERR, "gpioPWM failed on RED_PIN: %s", pigpio_error(red));
    if (gpioPWM(GREEN_PIN, green) < 0)
        syslog(LOG_ERR, "gpioPWM failed on GREEN_PIN: %s", pigpio_error(green));
    if (gpioPWM(BLUE_PIN, blue) < 0)
        syslog(LOG_ERR, "gpioPWM failed on BLUE_PIN: %s", pigpio_error(blue));
}

static void fade_to_color(int red, int green, int blue) {
    int r_step = (red   - 0) / STEP_COUNT;
    int g_step = (green - 0) / STEP_COUNT;
    int b_step = (blue  - 0) / STEP_COUNT;

    for (int i = 0; i < STEP_COUNT && g_running; i++) {
        int r = r_step * i;
        int g = g_step * i;
        int b = b_step * i;
        set_led_color(r, g, b);
        usleep(STEP_DELAY_US);
    }
    set_led_color(red, green, blue);
}

static void generate_random_color(int *red, int *green, int *blue) {
    *red   = rand() % 256;
    *green = rand() % 256;
    *blue  = rand() % 256;
}

int main(void) {
    openlog("rgb_fader", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to install signal handlers");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RED_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(GREEN_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(BLUE_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "gpioSetMode failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(RED_PIN, PWM_FREQ) < 0 ||
        gpioSetPWMfrequency(GREEN_PIN, PWM_FREQ) < 0 ||
        gpioSetPWMfrequency(BLUE_PIN, PWM_FREQ) < 0) {
        syslog(LOG_ERR, "gpioSetPWMfrequency failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(RED_PIN, PWM_RANGE) < 0 ||
        gpioSetPWMrange(GREEN_PIN, PWM_RANGE) < 0 ||
        gpioSetPWMrange(BLUE_PIN, PWM_RANGE) < 0) {
        syslog(LOG_ERR, "gpioSetPWMrange failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    srand((unsigned int)time(NULL));

    int red, green, blue;
    generate_random_color(&red, &green, &blue);
    set_led_color(red, green, blue);

    while (g_running) {
        generate_random_color(&red, &green, &blue);
        fade_to_color(red, green, blue);
    }

    set_led_color(0, 0, 0);
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

