/*
 * TCS34725 Color Sensor Reader with Red Threshold LED Control
 * Board:  Raspberry Pi 4 Model B
 * I2C:    /dev/i2c-1  (BCM pins 2/3)
 * LED:    GPIO 17 (BCM)
 *
 * Build:  gcc -O2 -Wall -Wextra -o tcs34725 tcs34725.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#include <gpiod.h>

/* ---- TCS34725 register definitions (command bit 0x80 required) ---- */
#define TCS34725_I2C_ADDR        0x29
#define TCS34725_CMD_BIT         0x80
#define TCS34725_ENABLE          0x00
#define TCS34725_ATIME           0x01
#define TCS34725_ID              0x12
#define TCS34725_CDATAL          0x14
#define TCS34725_RDATAL          0x16
#define TCS34725_GDATAL          0x18
#define TCS34725_BDATAL          0x1A

#define TCS34725_ENABLE_PON      0x01
#define TCS34725_ENABLE_AEN      0x02
#define TCS34725_ID_VALUE        0x44

#define I2C_BUS                 "/dev/i2c-1"
#define LED_GPIO_LINE           17
#define RED_THRESHOLD           200
#define POLL_INTERVAL_MS        200
#define INTEGRATION_TIME_MS     154   /* ATIME = 0xFF -> 2.4 ms × 256 ≈ 614.4 ms;
                                        rounded to 154 ms for typical use */

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd = -1;
static struct gpiod_chip  *g_chip = NULL;
static struct gpiod_line  *g_led  = NULL;

/* ------------------------------------------------------------------ */
static void handle_signal(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void msleep(unsigned ms)
{
    struct timespec ts = { ms / 1000, (long)(ms % 1000) * 1000000L };
    nanosleep(&ts, NULL);
}

/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { (uint8_t)(reg | TCS34725_CMD_BIT), val };
    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t cmd = (uint8_t)(reg | TCS34725_CMD_BIT);
    uint8_t buf[2];

    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

/* ------------------------------------------------------------------ */
static int sensor_init(int fd)
{
    uint16_t id = 0;
    if (i2c_read_reg16(fd, TCS34725_ID, &id) != 0)
        return -1;
    if (id != TCS34725_ID_VALUE) {
        fprintf(stderr, "Unexpected sensor ID 0x%04X (expected 0x%02X)\n",
                id, TCS34725_ID_VALUE);
        return -1;
    }

    /* Power on, then enable RGBC */
    if (i2c_write_reg8(fd, TCS34725_ENABLE, TCS34725_ENABLE_PON) != 0)
        return -1;
    msleep(3);  /* power-on delay */

    if (i2c_write_reg8(fd, TCS34725_ENABLE,
                        TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN) != 0)
        return -1;

    /* Integration time ≈ 154 ms (ATIME = 0xFF) */
    if (i2c_write_reg8(fd, TCS34725_ATIME, 0xFF) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
static int sensor_read(int fd, uint16_t *r, uint16_t *g,
                       uint16_t *b, uint16_t *c)
{
    if (i2c_read_reg16(fd, TCS34725_CDATAL, c) != 0) return -1;
    if (i2c_read_reg16(fd, TCS34725_RDATAL, r) != 0) return -1;
    if (i2c_read_reg16(fd, TCS34725_GDATAL, g) != 0) return -1;
    if (i2c_read_reg16(fd, TCS34725_BDATAL, b) != 0) return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_led) {
        gpiod_line_set_value(g_led, 0);
        gpiod_line_release(g_led);
        g_led = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
    if (g_i2c_fd >= 0) {
        /* Power down the sensor */
        (void)i2c_write_reg8(g_i2c_fd, TCS34725_ENABLE, 0x00);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, TCS34725_I2C_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                TCS34725_I2C_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (sensor_init(g_i2c_fd) != 0) {
        fprintf(stderr, "Sensor initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open GPIO chip and request LED line */
    g_chip = gpiod_chip_open_by_name("gpiochip4");
    if (!g_chip) {
        /* Fall back to gpiochip0 on older kernels */
        g_chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (!g_chip) {
        fprintf(stderr, "Cannot open GPIO chip: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    g_led = gpiod_chip_get_line(g_chip, LED_GPIO_LINE);
    if (!g_led) {
        fprintf(stderr, "Cannot get GPIO line %d: %s\n",
                LED_GPIO_LINE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(g_led, "tcs34725-led", 0) < 0) {
        fprintf(stderr, "Cannot request GPIO line %d as output: %s\n",
                LED_GPIO_LINE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("TCS34725 ready. Polling every %d ms. Press Ctrl+C to exit.\n",
           POLL_INTERVAL_MS);

    while (g_running) {
        uint16_t r, g, b, c;

        if (sensor_read(g_i2c_fd, &r, &g, &b, &c) != 0) {
            fprintf(stderr, "Read failure — re-initializing sensor.\n");
            if (sensor_init(g_i2c_fd) != 0) {
                fprintf(stderr, "Re-init failed; retrying in 500 ms.\n");
                msleep(500);
                continue;
            }
            msleep(500);
            continue;
        }

        printf("R: %5u  G: %5u  B: %5u  C: %5u\n", r, g, b, c);

        if (gpiod_line_set_value(g_led, (r > RED_THRESHOLD) ? 1 : 0) < 0) {
            fprintf(stderr, "Warning: failed to set LED: %s\n",
                    strerror(errno));
        }

        msleep(POLL_INTERVAL_MS);
    }

    printf("\nShutting down cleanly.\n");
    cleanup();
    return EXIT_SUCCESS;
}

