/*
 * Raspberry Pi 4 Model B – BH1750 ambient light sensor → WS2812B LED strip
 *
 * Hardware:
 *   - BH1750FVI on I2C bus 1 (GPIO2 = SDA, GPIO3 = SCL), address 0x23
 *   - WS2812B strip data line on GPIO18 (BCM 18, PCM_CLK)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o light_led light_led.c -lpigpio -lrt
 *   (pigpio provides the hardware-PWM-based WS2812B driver.)
 *
 * Run:
 *   sudo ./light_led
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS            1
#define BH1750_ADDR        0x23
#define BH1750_CMD_CONT_H  0x10   /* Continuous high-resolution mode (~120 ms) */
#define BH1750_MEASURE_MS  180    /* Max conversion time for high-res mode */

#define LED_GPIO           18     /* BCM 18 – PCM_CLK, WS2812B data line */
#define NUM_LEDS           10
#define PWM_DUTY_MAX       1000000 /* pigpio PWM range (0–1 000 000) */
#define PWM_FREQ_HZ        800000  /* WS2812B: 800 kHz */
#define PWM_DUTY_ON        400000  /* ~50 % duty cycle for a white-ish LED */
#define PWM_DUTY_OFF       0
#define LOOP_DELAY_US      100000  /* 100 ms between readings */

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* --------------------------- Signal handling ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- BH1750 helpers ------------------------------ */
static int bh1750_init(int handle)
{
    if (i2cWriteByte(handle, BH1750_CMD_CONT_H) < 0) {
        fprintf(stderr, "BH1750: failed to set continuous high-res mode\n");
        return -1;
    }
    return 0;
}

static int bh1750_read_lux(int handle, uint16_t *lux_out)
{
    if (i2cWriteByte(handle, BH1750_CMD_CONT_H) < 0) {
        fprintf(stderr, "BH1750: failed to re-issue measurement command\n");
        return -1;
    }

    gpioDelay(BH1750_MEASURE_MS * 1000); /* pigpio microseconds */

    int raw = i2cReadWordData(handle, 0);
    if (raw < 0) {
        fprintf(stderr, "BH1750: I2C read error (code %d)\n", raw);
        return -1;
    }

    /* pigpio returns (high_byte << 8) | low_byte for i2cReadWordData */
    uint16_t value = (uint16_t)raw;
    *lux_out = value;
    return 0;
}

/* --------------------------- WS2812B helpers ----------------------------- */
/*
 * pigpio's hardware PWM on GPIO18 (PCM_CLK) produces a clean 800 kHz square
 * wave, which is sufficient for driving WS2812B LEDs.  We use a 256-level
 * PWM range and drive the line high for 1 duty count and low for 255-duty
 * counts per bit (bit-banging-free approach).
 */
static void ws2812b_send_frame(const uint8_t *colors, int num)
{
    /*
     * WS2812B timing (800 kHz, 256-level PWM):
     *   T0H ~ 1.2 µs  (duty ~  31)
     *   T0L ~ 1.6 µs  (duty ~  40)
     *   T1H ~ 5.4 µs  (duty ~ 135)
     *   T1L ~ 5.4 µs  (duty ~ 135)
     *   Reset: ~50 µs low
     */
    const int t0h_duty = 31;
    const int t0l_duty = 40;
    const int t1h_duty = 135;
    const int t1l_duty = 135;

