        uint8_t byte = colors[i];
        for (int bit = 7; bit >= 0; bit--) {
            int duty_high, duty_low;
            if ((byte >> bit) & 1) {
                duty_high = t1h_duty;
                duty_low  = t1l_duty;
            } else {
                duty_high = t0h_duty;
                duty_low  = t0l_duty;
            }
            gpioPWM(LED_GPIO, duty_high);
            gpioDelay(duty_high * 1000 / PWM_FREQ_HZ); /* pigpio µs */
            gpioPWM(LED_GPIO, duty_low);
            gpioDelay(duty_low * 1000 / PWM_FREQ_HZ);
        }
    }
    /* Latch / reset: hold line low for > 50 µs */
    gpioPWM(LED_GPIO, PWM_DUTY_OFF);
    gpioDelay(60 * 1000 / PWM_FREQ_HZ);
}

static void ws2812b_set_brightness(uint8_t brightness)
{
    uint8_t colors[NUM_LEDS];
    for (int i = 0; i < NUM_LEDS; i++) {
        colors[i] = (uint8_t)(brightness * 255 / 10);
    }
    ws2812b_send_frame(colors, NUM_LEDS);
}

/* ------------------------------- Main ------------------------------------ */
int main(void)
{
    /* --- Signal handlers --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- I2C open --- */
    g_i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "I2C open failed on bus %d addr 0x%02X (code %d)\n",
                I2C_BUS, BH1750_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- BH1750 init --- */
    if (bh1750_init(g_i2c_handle) != 0) {
        fprintf(stderr, "BH1750 not detected or init failed – check wiring\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- WS2812B PWM setup --- */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", LED_GPIO);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioSetPWMfrequency(LED_GPIO, PWM_FREQ_HZ);
    gpioSetPWMrange(LED_GPIO, 256); /* 256-level range for bit-banging */

    /* --- Main loop --- */
    while (g_running) {
        uint16_t lux = 0;
        if (bh1750_read_lux(g_i2c_handle, &lux) != 0) {
            fprintf(stderr, "BH1750 read failed – retrying next cycle\n");
            gpioDelay(LOOP_DELAY_US);
