        float brightness = 10.0f * (float)log(log10f(log_lux));
        if (brightness > 10.0f) brightness = 10.0f;
        if (brightness < 0.0f) brightness = 0.0f;

        ws2812b_set_brightness((uint8_t)brightness);

        gpioDelay(LOOP_DELAY_US);
    }

    /* --- Cleanup --- */
    ws2812b_set_brightness(0);
    gpioPWM(LED_GPIO, PWM_DUTY_OFF);
    if (g_i2c_handle >= 0) {
