#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>

#define BH1750_ADDR 0x23
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x10
#define BH1750_MEASUREMENT_DELAY_MS 120

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED_HZ 1000000
#define NUM_LEDS 10
#define LED_BRIGHTNESS 31

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static int i2c_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    uint8_t mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint8_t bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI max speed");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

static int spi_write(const uint8_t *data, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)data,
        .rx_buf = 0,
        .len = len,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
        .tx_nbits = 0,
        .rx_nbits = 0,
        .pad = 0
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }
    return 0;
}

static int bh1750_init(int fd) {
    if (ioctl(fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        return -1;
    }

    uint8_t cmd = BH1750_CONTINUOUS_HIGH_RES_MODE;
    if (write(fd, &cmd, 1) != 1) {
        perror("Failed to write BH1750 mode");
        return -1;
    }
    return 0;
}

static int bh1750_read_light_level(int fd, float *light_level) {
    if (ioctl(fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Failed to set I2C slave address for read");
        return -1;
    }

    usleep(BH1750_MEASUREMENT_DELAY_MS * 1000);

    uint8_t buf[2];
    ssize_t bytes = read(fd, buf, 2);
    if (bytes != 2) {
        if (bytes < 0) {
            perror("Failed to read BH1750 data");
        } else {
            fprintf(stderr, "Short read from BH1750 (got %zd bytes)\n", bytes);
        }
        return -1;
    }

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *light_level = (float)raw / 1.2f;
    return 0;
}

static int apa102_send_frame(void) {
    uint32_t start_frame[1] = {0x00000000};
    uint32_t end_frame[1] = {0xFFFFFFFF};

    for (int i = 0; i < NUM_LEDS; i++) {
        uint32_t led_frame = 0xE0000000 | (LED_BRIGHTNESS << 16) | (0x0000FF) | (0x0000FF << 8);
        if (spi_write((uint8_t *)&led_frame, 4) < 0) {
            return -1;
        }
    }

    if (spi_write((uint8_t *)end_frame, 4) < 0) {
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    if (spi_fd >= 0) {
        uint32_t off_frame[1] = {0xE0000000};
        for (int i = 0; i < NUM_LEDS; i++) {
            if (spi_write((uint8_t *)off_frame, 4) < 0) {
                break;
            }
        }
        uint32_t end_frame[1] = {0xFFFFFFFF};
        spi_write((uint8_t *)end_frame, 4);
        close(spi_fd);
        spi_fd = -1;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to register signal handler");
        return 1;
    }

    if (spi_init() < 0) {
        return 1;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        cleanup();
        return 1;
    }

    if (bh1750_init(i2c_fd) < 0) {
        fprintf(stderr, "BH1750 initialization failed. Sensor may be absent or bus error.\n");
        cleanup();
        return 1;
    }

    while (running) {
        float light_level;
        if (bh1750_read_light_level(i2c_fd, &light_level) < 0) {
            fprintf(stderr, "Error reading light level. Retrying...\n");
            usleep(100000);
            continue;
        }

        int brightness = (int)(light_level / 100.0f * LED_BRIGHTNESS);
        if (brightness > LED_BRIGHTNESS) brightness = LED_BRIGHTNESS;
        if (brightness < 0) brightness = 0;

        uint32_t led_frame = 0xE0000000 | (brightness << 16) | (0x0000FF) | (0x0000FF << 8);
        if (spi_write((uint8_t *)&led_frame, 4) < 0) {
            fprintf(stderr, "SPI write failed. Retrying...\n");
            usleep(100000);
            continue;
        }

        usleep(100000);
    }

    cleanup();
    return 0;
}

