/*
 * Raspberry Pi 3 Model B+ — BH1750 light sensors → APA102 LED strip brightness
 *
 * Hardware:
 *   - 3x BH1750FVI on I2C bus 1, addresses 0x23 (continuous high-res mode)
 *   - APA102 LED strip: MOSI = GPIO10 (BCM), SCLK = GPIO11 (BCM)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o light_strip light_strip.c \
 *       -lbcm2835 -lpigpio -lm
 *
 * Run:
 *   sudo ./light_strip
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */

#define I2C_BUS              1
#define BH1750_ADDR_1        0x23
#define BH1750_ADDR_2        0x5C
#define BH1750_CONV_MS       180          /* conversion time for high-res mode */
#define NUM_SENSORS          3
#define NUM_LEDS             16
#define SPI_BAUD             1000000      /* 1 MHz — well within APA102 spec */
#define SPI_FLAGS            0            /* mode 0, active-high CS handled by pigpio */
#define FADE_MS              500
#define LOOP_DELAY_MS        100
#define MAX_LIGHT_LEVEL      65535.0f     /* BH1750 16-bit full-scale */

/* ----------------------------- Globals ----------------------------------- */

static volatile sig_atomic_t g_running = 1;

/* ----------------------------- BH1750 ------------------------------------ */

typedef struct {
    int  handle;
    bool present;
} bh1750_t;

static bh1750_t g_sensors[NUM_SENSORS];

/*
 * Initialise a single BH1750 at the given address.
 * Returns 0 on success, -1 on failure (handle is -1 on failure).
 */
static int bh1750_init(int addr)
{
    int h = i2cOpen(I2C_BUS, addr, 0);
    if (h < 0) {
        fprintf(stderr, "[BH1750 @0x%02X] i2cOpen failed: %s\n",
                addr, pigpio_error(h));
        return -1;
    }

    /* Power on, then set continuous high-resolution mode (0x10). */
    if (i2cWriteByte(h, 0x01) < 0) {
        fprintf(stderr, "[BH1750 @0x%02X] power-on write failed\n", addr);
        i2cClose(h);
        return -1;
    }
    if (i2cWriteByte(h, 0x10) < 0) {
        fprintf(stderr, "[BH1750 @0x%02X] mode write failed\n", addr);
        i2cClose(h);
        return -1;
    }

    return h;
}

/*
 * Read a 16-bit light-level sample from a BH1750.
 * Returns 0 on success, -1 on I2C error.
 */
static int bh1750_read(int handle, uint16_t *out)
{
    char buf[2];

    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "[BH1750] i2cReadDevice failed\n");
        return -1;
    }

    *out = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

/* ----------------------------- APA102 ------------------------------------ */

/*
 * Build a 4-byte start frame + 4-byte end frame + NUM_LEDS × 4-byte LED frames.
 * Each LED frame: [0xE0 | brightness, G, R, B].
 */
static void apa102_build_frame(uint8_t *buf, uint8_t brightness)
{
    const uint8_t start[4] = {0x00, 0x00, 0x00, 0x00};
    const uint8_t end[4]   = {0xFF, 0xFF, 0xFF, 0xFF};

    for (int i = 0; i < 4; i++) {
        buf[i]            = start[i];
        buf[(NUM_LEDS + 1) * 4 - 4 + i] = end[i];
    }

    for (int i = 0; i < NUM_LEDS; i++) {
        int idx = (i + 1) * 4;
        buf[idx]     = 0xE0 | (brightness & 0xE0);  /* bit7 = 1 → LED on */
        buf[idx + 1] = 0x00;                         /* green */
        buf[idx + 2] = 0x00;                         /* red   */
        buf[idx + 3] = 0x00;                         /* blue  */
    }
}

/*
 * Send the APA102 frame over SPI.
 * pigpio's spiWrite asserts/de-asserts the CS line automatically.
 */
static void apa102_send(int handle, const uint8_t *buf, int len)
{
    spiWrite(handle, (char *)buf, len);
}

/* ----------------------------- Fade -------------------------------------- */

/*
 * Fade the LED strip from `current` to `target` over `duration_ms`.
 * brightness is a 5-bit value (0–31).
 */
static void apa102_fade(int handle, uint8_t target, int duration_ms)
{
    if (duration_ms <= 0) {
        apa102_build_frame(NULL, target);
        apa102_send(handle, NULL, 0);
        return;
    }

    int steps = duration_ms / 10;   /* 10 ms per step → 50 steps */
    if (steps < 1) steps = 1;

    uint8_t step_inc = (target > 0) ? (uint8_t)((target - 1) / steps)
                                    : 0;
    uint8_t current  = 0;

    for (int i = 0; i <= steps; i++) {
        if (g_running == 0)
            break;

        uint8_t next = (i < steps) ? (current + step_inc) : target;

        uint8_t frame[NUM_LEDS * 4 + 8];
        apa102_build_frame(frame, next);
        apa102_send(handle, frame, sizeof(frame));

        current = next;
        if (i < steps)
            gpioDelay(10000);  /* 10 ms → 100 Hz */
    }
}

/* ----------------------------- Signal ------------------------------------- */

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- Main --------------------------------------- */

int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- SPI init --- */
    int spi_handle = spiOpen(0, SPI_BAUD, SPI_FLAGS);  /* channel 0 = MOSI/GPIO10, SCLK/GPIO11 */
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed: %s\n", pigpio_error(spi_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Sensor init --- */
    int sensor_addresses[NUM_SENSORS] = {BH1750_ADDR_1, BH1750_ADDR_2};
    for (int i = 0; i < NUM_SENSORS; i++) {
        g_sensors[i].handle  = -1;
        g_sensors[i].present = false;

        int h = bh1750_init(sensor_addresses[i]);
        if (h >= 0) {
            g_sensors[i].handle  = h;
            g_sensors[i].present = true;
            printf("[BH1750 @0x%02X] initialised (handle %d)\n",
                   sensor_addresses[i], h);
        } else {
            fprintf(stderr, "[BH1750 @0x%02X] not present or init failed\n",
                    sensor_addresses[i]);
        }
    }

    /* --- Signal handler --- */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    /* --- Main loop --- */
    uint8_t current_brightness = 0;
    uint8_t target_brightness  = 0;

    while (g_running) {
        uint32_t sum = 0;
        int      count = 0;
        int      valid = 0;

        for (int i = 0; i < NUM_SENSORS; i++) {
            if (!g_sensors[i].present)
                continue;

            gpioDelay(BH1750_CONV_MS * 1000);  /* wait for conversion */

            uint16_t raw;
            if (bh1750_read(g_sensors[i].handle, &raw) == 0) {
                sum += raw;
                valid++;
            } else {
                fprintf(stderr, "[BH1750 @0x%02X] read error — skipping\n",
                        sensor_addresses[i]);
            }
        }

        if (valid > 0) {
            float avg = (float)sum / (float)valid;
            target_brightness = (uint8_t)(current_brightness +
                (int)((avg / MAX_LIGHT_LEVEL) * 31.0f));
            if (target_brightness > 31)
                target_brightness = 31;
            if (target_brightness < 0)
                target_brightness = 0;
        } else {
            fprintf(stderr, "No valid sensor readings — keeping current brightness\n");
        }

        apa102_fade(spi_handle, target_brightness, FADE_MS);
        current_brightness = target_brightness;

        gpioDelay(LOOP_DELAY_MS * 1000);
    }

    /* --- Cleanup --- */
    printf("\nShutting down...\n");
    apa102_fade(spi_handle, 0, 0);  /* immediate off */

    for (int i = 0; i < NUM_SENSORS; i++) {
        if (g_sensors[i].handle >= 0)
            i2cClose(g_sensors[i].handle);
    }
    spiClose(spi_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

