#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define VEML7700_ADDR 0x48
#define VEML7700_ALS_CONF 0x00
#define VEML7700_ALS_DATA 0x04
#define VEML7700_ALS_WH 0x06
#define VEML7700_ALS_WL 0x08

#define GPIO_CHIP "gpiochip4"
#define GPIO_LINE 18
#define I2C_BUS "/dev/i2c-1"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100
#define LOOP_DELAY_MS 200

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static struct gpiod_line *led_line = NULL;
static struct gpiod_chip *chip = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
        led_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

static int i2c_write_reg16(int fd, uint8_t reg, uint16_t val) {
    uint8_t buf[3] = {reg, (uint8_t)(val >> 8), (uint8_t)(val & 0xFF)};
    if (write(fd, buf, 3) != 3) return -1;
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) return -1;
    *val = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int veml7700_init(int fd) {
    uint16_t conf = 0x0000;
    if (i2c_write_reg16(fd, VEML7700_ALS_CONF, conf) < 0) return -1;
    usleep(10000);
    return 0;
}

static int veml7700_read_lux(int fd, float *lux) {
    uint16_t als_data;
    if (i2c_read_reg16(fd, VEML7700_ALS_DATA, &als_data) < 0) return -1;
    uint16_t als = als_data & 0x3FFF;
    *lux = (float)als * 0.001f;
    return 0;
}

static int gpio_init(void) {
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return -1;
    }
    led_line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!led_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }
    if (gpiod_line_request_output(led_line, "ws2812b", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", GPIO_LINE, strerror(errno));
        gpiod_line_release(led_line);
        led_line = NULL;
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }
    return 0;
}

static void ws2812b_write_bit(int bit) {
    gpiod_line_set_value(led_line, 1);
    if (bit) {
        usleep(1);
        gpiod_line_set_value(led_line, 0);
        usleep(1);
    } else {
        usleep(3);
        gpiod_line_set_value(led_line, 0);
        usleep(1);
    }
}

static void ws2812b_write_byte(uint8_t byte) {
    for (int i = 7; i >= 0; i--) {
        ws2812b_write_bit((byte >> i) & 1);
    }
}

static void ws2812b_set_brightness(uint8_t brightness) {
    uint8_t buf[24] = {0};
    for (int i = 0; i < 24; i++) {
        ws2812b_write_byte(buf[i]);
    }
}

static void ws2812b_off(void) {
    ws2812b_set_brightness(0);
}

static void delay_ms(int ms) {
    usleep(ms * 1000);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, VEML7700_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", VEML7700_ADDR, strerror(errno));
        cleanup();
        return 1;
    }
    if (veml7700_init(i2c_fd) < 0) {
        fprintf(stderr, "Failed to initialize VEML7700\n");
        cleanup();
        return 1;
    }
    if (gpio_init() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        cleanup();
        return 1;
    }

    while (running) {
        float lux = 0.0f;
        int retries = 0;
        int success = 0;
        while (retries < MAX_RETRIES && !success) {
            if (veml7700_read_lux(i2c_fd, &lux) == 0) {
                success = 1;
            } else {
                retries++;
                if (retries < MAX_RETRIES) {
                    fprintf(stderr, "I2C read failed (attempt %d/%d), retrying in %d ms...\n", retries, MAX_RETRIES, RETRY_DELAY_MS);
                    delay_ms(RETRY_DELAY_MS);
                }
            }
        }
        if (!success) {
            fprintf(stderr, "Failed to read lux after %d retries\n", MAX_RETRIES);
            delay_ms(LOOP_DELAY_MS);
            continue;
        }

        uint8_t brightness = (uint8_t)(lux * 10.0f);
        if (brightness > 255) brightness = 255;
        if (brightness < 0) brightness = 0;

        printf("Lux: %.2f, Brightness: %u\n", lux, brightness);
        ws2812b_set_brightness(brightness);
        delay_ms(LOOP_DELAY_MS);
    }

    ws2812b_off();
    cleanup();
    return 0;
}

