#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN 17
#define LED_PIN 18

#define BLINK_INTERVAL_MS 500
#define RAPID_BLINK_INTERVAL_MS 100
#define POLL_INTERVAL_MS 50
#define SHORT_PULSE_MS 200
#define LONG_PULSE_MS 600
#define BUZZER_PATTERN_REPS 3

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] %s\n", timestamp, message);
    fflush(stdout);
}

static int read_flame_sensor(void) {
    int value = gpioRead(FLAME_SENSOR_PIN);
    if (value < 0) {
        log_event("Error reading flame sensor");
        return -1;
    }
    return value;
}

static int blink_led(int interval_ms) {
    if (gpioWrite(LED_PIN, 1) < 0) {
        log_event("Error turning LED on");
        return -1;
    }
    gpioDelay(interval_ms * 1000);
    if (gpioWrite(LED_PIN, 0) < 0) {
        log_event("Error turning LED off");
        return -1;
    }
    gpioDelay(interval_ms * 1000);
    return 0;
}

static int rapid_blink_led(void) {
    for (int i = 0; i < 5; i++) {
        if (blink_led(RAPID_BLINK_INTERVAL_MS) != 0) return -1;
    }
    return 0;
}

static int buzzer_pattern(void) {
    for (int rep = 0; rep < BUZZER_PATTERN_REPS; rep++) {
        if (gpioWrite(BUZZER_PIN, 1) < 0) {
            log_event("Error turning buzzer on");
            return -1;
        }
        gpioDelay(SHORT_PULSE_MS * 1000);
        if (gpioWrite(BUZZER_PIN, 0) < 0) {
            log_event("Error turning buzzer off");
            return -1;
        }
        gpioDelay(SHORT_PULSE_MS * 1000);
        if (gpioWrite(BUZZER_PIN, 1) < 0) {
            log_event("Error turning buzzer on");
            return -1;
        }
        gpioDelay(SHORT_PULSE_MS * 1000);
        if (gpioWrite(BUZZER_PIN, 0) < 0) {
            log_event("Error turning buzzer off");
            return -1;
        }
        gpioDelay(LONG_PULSE_MS * 1000);
    }
    return 0;
}

static int self_test(void) {
    log_event("Starting self-test...");

    if (gpioWrite(LED_PIN, 1) < 0) {
        log_event("Error initializing LED state");
        return -1;
    }
    gpioDelay(BLINK_INTERVAL_MS * 1000);
    if (gpioWrite(LED_PIN, 0) < 0) {
        log_event("Error initializing LED state");
        return -1;
    }
    gpioDelay(BLINK_INTERVAL_MS * 1000);

    int flame_detected = 1;
    for (int i = 0; i < 5; i++) {
        int sensor_value = read_flame_sensor();
        if (sensor_value < 0) {
            log_event("Error reading flame sensor during self-test");
            return -1;
        }
        if (sensor_value == 1) {
            flame_detected = 0;
        }
        gpioDelay(100 * 1000);
    }

    if (flame_detected) {
        log_event("Self-test failed: flame sensor not consistently LOW");
        if (rapid_blink_led() != 0) return -1;
        if (buzzer_pattern() != 0) return -1;
        return -1;
    }

    log_event("Self-test passed!");
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set flame sensor pin mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set buzzer pin mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set LED pin mode\n");
        gpioTerminate();
        return 1;
    }

    if (self_test() != 0) {
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        log_event("Warning: could not install SIGINT handler");
    }

    log_event("Entering main loop...");

    while (program_running) {
        int sensor_value = read_flame_sensor();
        if (sensor_value < 0) {
            log_event("Error reading flame sensor in main loop");
            gpioDelay(POLL_INTERVAL_MS * 1000);
            continue;
        }

        if (sensor_value == 1) {
            log_event("Flame detected!");
            if (gpioWrite(BUZZER_PIN, 1) < 0) {
                log_event("Error turning buzzer on");
            }
            if (gpioWrite(LED_PIN, 1) < 0) {
                log_event("Error turning LED on");
            }
            while (program_running) {
                int s = read_flame_sensor();
                if (s < 0) {
                    log_event("Error reading flame sensor during flame event");
                    break;
                }
                if (s == 0) {
                    break;
                }
                gpioDelay(POLL_INTERVAL_MS * 1000);
            }
            if (gpioWrite(BUZZER_PIN, 0) < 0) {
                log_event("Error turning buzzer off");
            }
            if (gpioWrite(LED_PIN, 0) < 0) {
                log_event("Error turning LED off");
            }
            log_event("Flame cleared.");
        }

        gpioDelay(POLL_INTERVAL_MS * 1000);
    }

    log_event("Shutting down...");
    gpioWrite(BUZZER_PIN, 0);
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    return 0;
}

