#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

#define I2C_BUS        "/dev/i2c-1"
#define BH1750_ADDR    0x23
#define LED_GPIO       17
#define BUFFER_SIZE    60
#define MIN_HZ         0.5f
#define MAX_HZ         5.0f
#define MAX_LUX        1000.0f
#define SAMPLE_DELAY_S 1

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int bh1750_init(int fd)
{
    /* Power on, then set continuous high-resolution mode (0x10). */
    if (i2c_write(fd, 0x00, 0x01) < 0) return -1;
    usleep(10000);
    if (i2c_write(fd, 0x01, 0x10) < 0) return -1;
    usleep(180000);
    return 0;
}

static int bh1750_read_lux(int fd, float *lux_out)
{
    uint8_t buf[2];
    if (i2c_read(fd, 0x00, buf, sizeof(buf)) < 0) return -1;
    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static void led_pulse(int gpio, float lux)
{
    float freq = MIN_HZ + (lux / MAX_LUX) * (MAX_HZ - MIN_HZ);
    if (freq < MIN_HZ) freq = MIN_HZ;
    if (freq > MAX_HZ) freq = MAX_HZ;

    float half_period = 1.0f / (2.0f * freq);
    int half_us = (int)(half_period * 1e6f);
    if (half_us < 1) half_us = 1;

    int on_us  = half_us;
    int off_us = half_us;

    /* Square wave: 50 % duty cycle */
    if (gpio == 17) {
        /* Use sysfs GPIO export / value for LED on GPIO17 */
        FILE *export_f = fopen("/sys/class/gpio/export", "w");
        if (!export_f) {
            fprintf(stderr, "Warning: cannot export GPIO17: %s\n", strerror(errno));
            return;
        }
        fprintf(export_f, "17");
        fclose(export_f);
        usleep(100000);

        FILE *dir_f = fopen("/sys/class/gpio/gpio17/direction", "w");
        if (!dir_f) {
            fprintf(stderr, "Warning: cannot set direction: %s\n", strerror(errno));
            return;
        }
        fprintf(dir_f, "out");
        fclose(dir_f);

        FILE *val_f = fopen("/sys/class/gpio/gpio17/value", "w");
        if (!val_f) {
            fprintf(stderr, "Warning: cannot open value: %s\n", strerror(errno));
            return;
        }

        for (int i = 0; i < 10 && g_running; i++) {
            if (fputs("1", val_f) == EOF) break;
            usleep(on_us);
            if (fputs("0", val_f) == EOF) break;
            usleep(off_us);
        }

        val_f = fopen("/sys/class/gpio/gpio17/value", "w");
        if (val_f) {
            fputs("0", val_f);
            fclose(val_f);
        }
        fclose(val_f);
        /* Unexport GPIO17 */
        FILE *unexport_f = fopen("/sys/class/gpio/unexport", "w");
        if (unexport_f) {
            fprintf(unexport_f, "17");
            fclose(unexport_f);
        }
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open " I2C_BUS);
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(fd);
        return EXIT_FAILURE;
    }

    if (bh1750_init(fd) < 0) {
        fprintf(stderr, "BH1750 initialization failed.\n");
        close(fd);
        return EXIT_FAILURE;
    }

    float buffer[BUFFER_SIZE];
    memset(buffer, 0, sizeof(buffer));
    int head = 0;
    int count = 0;

    while (g_running) {
        float lux;
        if (bh1750_read_lux(fd, &lux) < 0) {
            fprintf(stderr, "Sensor read failed; skipping sample.\n");
        } else {
            buffer[head] = lux;
            head = (head + 1) % BUFFER_SIZE;
            if (count < BUFFER_SIZE) count++;

            float sum = 0.0f;
            for (int i = 0; i < count; i++) sum += buffer[i];
            float avg = (count > 0) ? (sum / count) : 0.0f;

            printf("Lux: %.2f  Avg: %.2f\n", lux, avg);
            led_pulse(LED_GPIO, avg);
        }

        sleep(SAMPLE_DELAY_S);
    }

    /* Clean up GPIO17 export if sysfs was used */
    FILE *unexport_f = fopen("/sys/class/gpio/unexport", "w");
    if (unexport_f) {
        fprintf(unexport_f, "17");
        fclose(unexport_f);
    }

    close(fd);
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

