#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define DATA_PIN  17
#define CLOCK_PIN 18
#define LATCH_PIN 27

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    gpioWrite(DATA_PIN, 0);
    gpioWrite(CLOCK_PIN, 0);
    gpioWrite(LATCH_PIN, 0);
    gpioTerminate();
}

static int setup(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(DATA_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set DATA_PIN mode\n");
        cleanup();
        return -1;
    }
    if (gpioSetMode(CLOCK_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set CLOCK_PIN mode\n");
        cleanup();
        return -1;
    }
    if (gpioSetMode(LATCH_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LATCH_PIN mode\n");
        cleanup();
        return -1;
    }

    gpioWrite(DATA_PIN, 0);
    gpioWrite(CLOCK_PIN, 0);
    gpioWrite(LATCH_PIN, 0);

    return 0;
}

static void shift_out(unsigned char data) {
    gpioWrite(LATCH_PIN, 0);

    for (int i = 7; i >= 0; i--) {
        gpioWrite(DATA_PIN, (data >> i) & 0x01);
        gpioWrite(CLOCK_PIN, 1);
        gpioDelay(1);
        gpioWrite(CLOCK_PIN, 0);
        gpioDelay(1);
    }

    gpioWrite(LATCH_PIN, 1);
    gpioDelay(1);
    gpioWrite(LATCH_PIN, 0);
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (setup() != 0) {
        return EXIT_FAILURE;
    }

    const unsigned char digit5 = 0b01100110; /* segments a,b,c,d,e,f,g,dp */

    while (running) {
        shift_out(digit5);
        gpioDelay(500000); /* 500 ms on */

        shift_out(0x00);
        gpioDelay(500000); /* 500 ms off */
    }

    cleanup();
    return EXIT_SUCCESS;
}

