/*
 * blink_button.c — Blink an LED on GPIO17 and halt on a falling-edge
 * button press on GPIO18 using libgpiod.
 *
 * Build:  gcc -O2 -Wall -Wextra -o blink_button blink_button.c -lgpiod
 * Run:    sudo ./blink_button   (or ensure gpio group access)
 */

#include <errno.h>
#include <gpiod.h>
#include <signal.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

#define GPIO_CHIP       "gpiochip0"
#define LED_LINE_OFFSET 17          /* BCM 17, physical pin 11 */
#define BUTTON_LINE_OFFSET 18       /* BCM 18, physical pin 12 */
#define BLINK_PERIOD_S   1           /* 1 s on, 1 s off → 2 s period */
#define POLL_TIMEOUT_MS  1000        /* 1 s poll timeout for events */

static volatile sig_atomic_t g_stop = 0;

static void sigint_handler(int signo)
{
    (void)signo;
    g_stop = 1;
}

static int install_sigint(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    return sigaction(SIGINT, &sa, NULL);
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *led_line = NULL;
    struct gpiod_line *button_line = NULL;
    int ret = EXIT_FAILURE;

    if (install_sigint() != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP, strerror(errno));
        return EXIT_FAILURE;
    }

    led_line = gpiod_chip_get_line(chip, LED_LINE_OFFSET);
    if (!led_line) {
        fprintf(stderr, "Failed to get LED line %d: %s\n",
                LED_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    button_line = gpiod_chip_get_line(chip, BUTTON_LINE_OFFSET);
    if (!button_line) {
        fprintf(stderr, "Failed to get button line %d: %s\n",
                BUTTON_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    /* Request LED as output, initial value LOW. */
    if (gpiod_line_request_output(led_line, "blink_button", 0) < 0) {
        fprintf(stderr, "Failed to request LED line as output: %s\n",
                strerror(errno));
        goto cleanup;
    }

    /* Request button as input with pull-up and falling-edge event detection. */
    if (gpiod_line_request_falling_edge_events_flags(
            button_line, "blink_button",
            GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        fprintf(stderr, "Failed to request button line for falling-edge events: %s\n",
                strerror(errno));
        goto cleanup;
    }

    printf("Blinking LED on BCM %d, button on BCM %d. Press Ctrl-C or the button to exit.\n",
           LED_LINE_OFFSET, BUTTON_LINE_OFFSET);
    fflush(stdout);

    while (!g_stop) {
        int rv = gpiod_line_event_wait(button_line,
                                       &(struct timespec){0, POLL_TIMEOUT_MS * 1000000L});
        if (rv < 0) {
            if (errno == EINTR) {
                continue;            /* interrupted by signal — check g_stop */
            }
            fprintf(stderr, "Error waiting for button event: %s\n",
                    strerror(errno));
            goto cleanup;
        }
        if (rv == 0) {
            /* Timeout — no event; toggle LED for one blink period. */
            if (gpiod_line_set_value(led_line, 1) < 0) {
                fprintf(stderr, "Failed to set LED high: %s\n", strerror(errno));
                goto cleanup;
            }
            sleep(BLINK_PERIOD_S);
            if (gpiod_line_set_value(led_line, 0) < 0) {
                fprintf(stderr, "Failed to set LED low: %s\n", strerror(errno));
                goto cleanup;
            }
            sleep(BLINK_PERIOD_S);
            continue;
        }

        /* Event detected — consume it. */
        struct gpiod_line_event event;
        if (gpiod_line_event_read(button_line, &event) < 0) {
            fprintf(stderr, "Failed to read button event: %s\n", strerror(errno));
            goto cleanup;
        }

        printf("Button pressed! Stopping blink.\n");
        fflush(stdout);

        if (gpiod_line_set_value(led_line, 0) < 0) {
            fprintf(stderr, "Failed to turn LED off: %s\n", strerror(errno));
            goto cleanup;
        }

        ret = EXIT_SUCCESS;
        break;
    }

cleanup:
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (button_line) {
        gpiod_line_release(button_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

