#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RED_PIN   24
#define GREEN_PIN 23
#define BLUE_PIN  18

#define PWM_PERIOD_US 10000  /* 10 ms = 100 Hz */
#define PWM_DUTY_MAX  100
#define COLOUR_CHANGE_MS 100

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Software PWM: drive the line high for 'on_us' microseconds, then low for
 * the remainder of the period, using clock_nanosleep for sub-millisecond
 * precision.  Returns 0 on success, -1 on error.
 */
static int pwm_pulse(int pin, int on_us)
{
    if (gpioWrite(pin, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite(%d, 1) failed\n", pin);
        return -1;
    }
    if (on_us > 0) {
        struct timespec req = { .tv_sec = 0, .tv_nsec = on_us * 1000L };
        while (nanosleep(&req, &req) == -1 && errno == EINTR) {
            /* retry on signal interruption */
        }
    }
    if (gpioWrite(pin, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(%d, 0) failed\n", pin);
        return -1;
    }
    if (on_us < PWM_PERIOD_US) {
        struct timespec req = { .tv_sec = 0,
                                .tv_nsec = (PWM_PERIOD_US - on_us) * 1000L };
        while (nanosleep(&req, &req) == -1 && errno == EINTR) {
            /* retry on signal interruption */
        }
    }
    return 0;
}

static int set_led_colour(int red, int green, int blue)
{
    if (red < 0 || red > PWM_DUTY_MAX ||
        green < 0 || green > PWM_DUTY_MAX ||
        blue < 0 || blue > PWM_DUTY_MAX) {
        fprintf(stderr, "Error: invalid colour values (R=%d G=%d B=%d)\n",
                red, green, blue);
        return -1;
    }

    int r_on = (red * PWM_PERIOD_US) / PWM_DUTY_MAX;
    int g_on = (green * PWM_PERIOD_US) / PWM_DUTY_MAX;
    int b_on = (blue * PWM_PERIOD_US) / PWM_DUTY_MAX;

    if (pwm_pulse(RED_PIN,   r_on) < 0) return -1;
    if (pwm_pulse(GREEN_PIN, g_on) < 0) return -1;
    if (pwm_pulse(BLUE_PIN,  b_on) < 0) return -1;

    return 0;
}

static int generate_random_colour(int *red, int *green, int *blue)
{
    *red   = rand() % (PWM_DUTY_MAX + 1);
    *green = rand() % (PWM_DUTY_MAX + 1);
    *blue  = rand() % (PWM_DUTY_MAX + 1);
    return 0;
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_OUTPUT) failed\n", RED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(GREEN_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_OUTPUT) failed\n", GREEN_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BLUE_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_OUTPUT) failed\n", BLUE_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(RED_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(%d, 0) failed\n", RED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(GREEN_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(%d, 0) failed\n", GREEN_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(BLUE_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(%d, 0) failed\n", BLUE_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    srand((unsigned int)time(NULL));

    int red, green, blue;
    if (generate_random_colour(&red, &green, &blue) < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (g_running) {
        if (set_led_colour(red, green, blue) < 0) {
            gpioTerminate();
            return EXIT_FAILURE;
        }

        struct timespec delay = { .tv_sec = 0,
                                  .tv_nsec = COLOUR_CHANGE_MS * 1000000L };
        while (nanosleep(&delay, &delay) == -1 && errno == EINTR) {
            if (!g_running) break;
        }

        if (!g_running) break;

        if (generate_random_colour(&red, &green, &blue) < 0) {
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    /* Ensure LEDs are off before cleanup */
    gpioWrite(RED_PIN, 0);
    gpioWrite(GREEN_PIN, 0);
    gpioWrite(BLUE_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

