/*
 * impact_monitor.c — Raspberry Pi Zero W
 *
 * Polls an Adafruit LSM303DLHC accelerometer on I2C bus 1 at 10 Hz.
 * When the total G-force magnitude exceeds a configurable threshold,
 * pulses GPIO17 HIGH for 50 ms and logs the data to impact_log.txt.
 *
 * Build:  gcc -O2 -Wall -Wextra -o impact_monitor impact_monitor.c \
 *            -li2c -lpigpio -lrt
 * Run:    sudo ./impact_monitor [-t threshold_g]
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <getopt.h>

#include <pigpio.h>

/* ---- LSM303DLHC I2C addresses ---- */
#define LSM303_ACCEL_ADDR 0x19   /* SA0 tied high on Adafruit breakout */

/* ---- LSM303DLHC register addresses ---- */
#define LSM303_ACCEL_CTRL_REG1_A 0x20
#define LSM303_ACCEL_CTRL_REG4_A 0x23
#define LSM303_ACCEL_OUT_X_L_A   0x28
#define LSM303_ACCEL_OUT_X_H_A   0x29
#define LSM303_ACCEL_OUT_Y_L_A   0x2A
#define LSM303_ACCEL_OUT_Y_H_A   0x2B
#define LSM303_ACCEL_OUT_Z_L_A   0x2C
#define LSM303_ACCEL_OUT_Z_H_A   0x2D

/* ---- GPIO ---- */
#define GPIO_PIN 17

/* ---- Sampling ---- */
#define SAMPLE_PERIOD_US 100000   /* 10 Hz */

/* ---- Impact pulse ---- */
#define PULSE_DURATION_US 50000   /* 50 ms */

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    /* gpioTerminate is safe to call even if gpioInitialise failed */
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Read 6 bytes of accelerometer data (X, Y, Z, each 16-bit, little-endian). */
/* Returns 0 on success, -1 on I2C error. */
static int read_accel_data(int16_t *x, int16_t *y, int16_t *z)
{
    char buffer[6];

    if (i2cReadI2CBlockData(g_i2c_handle, LSM303_ACCEL_OUT_X_L_A | 0x80,
                            buffer, 6) != 6) {
        return -1;
    }

    *x = (int16_t)((uint16_t)buffer[1] << 8 | (uint8_t)buffer[0]);
    *y = (int16_t)((uint16_t)buffer[3] << 8 | (uint8_t)buffer[2]);
    *z = (int16_t)((uint16_t)buffer[5] << 8 | (uint8_t)buffer[4]);
    return 0;
}

/* ------------------------------------------------------------------ */
static double calculate_g_force(int16_t x, int16_t y, int16_t z)
{
    const double sensitivity = 0.000244f;   /* +/- 2 g, 12-bit -> 0.244 mg/LSB */
    return sqrt((double)x * x + (double)y * y + (double)z * z) * sensitivity;
}

/* ------------------------------------------------------------------ */
static void log_data(int16_t x, int16_t y, int16_t z, double g_force)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(g_log_file, "%s, X: %d, Y: %d, Z: %d, G-Force: %.3f\n",
            timestamp, x, y, z, g_force);
    fflush(g_log_file);
}

/* ------------------------------------------------------------------ */
static void trigger_impact(void)
{
    if (gpioWrite(GPIO_PIN, 1) < 0) {
        fprintf(stderr, "Warning: failed to set GPIO %d HIGH\n", GPIO_PIN);
        return;
    }
    gpioDelay(PULSE_DURATION_US);
    if (gpioWrite(GPIO_PIN, 0) < 0) {
        fprintf(stderr, "Warning: failed to set GPIO %d LOW\n", GPIO_PIN);
    }
}

/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    double threshold_g = 2.0;
    int opt;

    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
        case 't':
            threshold_g = atof(optarg);
            if (threshold_g <= 0.0) {
                fprintf(stderr, "Error: threshold must be positive.\n");
                return EXIT_FAILURE;
            }
            break;
        default:
            fprintf(stderr, "Usage: %s [-t threshold_g]\n", argv[0]);
            return EXIT_FAILURE;
        }
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus 1 ---- */
    g_i2c_handle = i2cOpen(1, LSM303_ACCEL_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C bus 1 at 0x%02X (err=%d).\n",
                LSM303_ACCEL_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Configure accelerometer: 10 Hz, +/- 2 g, continuous mode ---- */
    if (i2cWriteByteData(g_i2c_handle, LSM303_ACCEL_CTRL_REG1_A, 0x27) < 0) {
        fprintf(stderr, "Error: failed to write CTRL_REG1_A.\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (i2cWriteByteData(g_i2c_handle, LSM303_ACCEL_CTRL_REG4_A, 0x00) < 0) {
        fprintf(stderr, "Error: failed to write CTRL_REG4_A.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Configure GPIO17 as output, initially LOW ---- */
    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", GPIO_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(GPIO_PIN, 0);

    /* ---- Open log file ---- */
    g_log_file = fopen("impact_log.txt", "a");
    if (g_log_file == NULL) {
        perror("Error: failed to open impact_log.txt");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Impact monitoring started. Threshold: %.2f G. Press Ctrl+C to exit.\n",
           threshold_g);

    /* ---- Main loop ---- */
    while (g_running) {
        int16_t x, y, z;

        if (read_accel_data(&x, &y, &z) != 0) {
            fprintf(stderr, "Warning: I2C read error — skipping sample.\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        double g_force = calculate_g_force(x, y, z);

        if (g_force > threshold_g) {
            trigger_impact();
            log_data(x, y, z, g_force);
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

