#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS 1
#define I2C_ADDR 0x48
#define LED_GPIO 18
#define PWM_RANGE 255
#define PWM_FREQ 1000
#define SAMPLE_INTERVAL_US 500000
#define RETRY_DELAY_US 100000

#define REG_ALS_LSB 0x00
#define REG_ALS_MSB 0x01
#define REG_RED_LSB 0x02
#define REG_RED_MSB 0x03
#define REG_GREEN_LSB 0x04
#define REG_GREEN_MSB 0x05
#define REG_BLUE_LSB 0x06
#define REG_BLUE_MSB 0x07

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_register(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

static int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_sensor_data(int handle, uint16_t *als, uint16_t *red, uint16_t *green, uint16_t *blue) {
    uint8_t als_lsb, als_msb, red_lsb, red_msb, green_lsb, green_msb, blue_lsb, blue_msb;

    if (read_register(handle, REG_ALS_LSB, &als_lsb) < 0) return -1;
    if (read_register(handle, REG_ALS_MSB, &als_msb) < 0) return -1;
    if (read_register(handle, REG_RED_LSB, &red_lsb) < 0) return -1;
    if (read_register(handle, REG_RED_MSB, &red_msb) < 0) return -1;
    if (read_register(handle, REG_GREEN_LSB, &green_lsb) < 0) return -1;
    if (read_register(handle, REG_GREEN_MSB, &green_msb) < 0) return -1;
    if (read_register(handle, REG_BLUE_LSB, &blue_lsb) < 0) return -1;
    if (read_register(handle, REG_BLUE_MSB, &blue_msb) < 0) return -1;

    *als = ((uint16_t)als_msb << 8) | als_lsb;
    *red = ((uint16_t)red_msb << 8) | red_lsb;
    *green = ((uint16_t)green_msb << 8) | green_lsb;
    *blue = ((uint16_t)blue_msb << 8) | blue_lsb;

    return 0;
}

static void set_led_brightness(int gpio, int brightness) {
    if (brightness < 0) brightness = 0;
    if (brightness > PWM_RANGE) brightness = PWM_RANGE;
    gpioPWM(gpio, brightness);
}

static void log_data(FILE *fp, uint16_t als, uint16_t red, uint16_t green, uint16_t blue) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%u,%u,%u,%u\n", timestamp, als, red, green, blue);
    fflush(fp);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioPWM(LED_GPIO, 0);
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    uint16_t als, red, green, blue;
    int brightness;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", LED_GPIO);
        cleanup();
        return 1;
    }
    gpioSetPWMrange(LED_GPIO, PWM_RANGE);
    gpioSetPWMfrequency(LED_GPIO, PWM_FREQ);

    log_file = fopen("color_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,ALS,Red,Green,Blue\n");
        fflush(log_file);
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (running) {
        if (read_sensor_data(i2c_handle, &als, &red, &green, &blue) == 0) {
            brightness = (int)als;
            set_led_brightness(LED_GPIO, brightness);
            log_data(log_file, als, red, green, blue);
        } else {
            fprintf(stderr, "Error reading sensor data. Retrying in 100ms...\n");
            gpioDelay(RETRY_DELAY_US);
            continue;
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return 0;
}

