/*
 * FXOS8700CQ Impact Logger for Raspberry Pi Zero W
 *
 * Wiring:
 *   FXOS8700 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   FXOS8700 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   FXOS8700 VDD  -> 3.3 V
 *   FXOS8700 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o impact_logger impact_logger.c -lpigpio -lrt
 * Run:    sudo ./impact_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- FXOS8700CQ register definitions ---- */
#define FXOS8700_I2C_ADDR        0x1D   /* SA0 tied high on Adafruit breakout */
#define FXOS8700_WHO_AM_I        0x0D
#define FXOS8700_WHO_AM_I_VAL    0xC7
#define FXOS8700_CTRL_REG1       0x2A
#define FXOS8700_CTRL_REG2       0x2B
#define FXOS8700_XYZ_DATA_CFG    0x0E
#define FXOS8700_OUT_X_MSB       0x01

/* ---- Application constants ---- */
#define I2C_BUS                 1
#define SAMPLE_PERIOD_US        50000   /* 50 ms  */
#define ODR_HZ                  200     /* 200 Hz ODR => 50 ms period */
#define IMPACT_THRESHOLD        2.0     /* g  */
#define LOG_FILE                "impact_log.txt"

/* ---- Globals for signal handler ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;            /* tell main loop to exit cleanly        */
}

/* ------------------------------------------------------------------ */
/* Write one byte to a register; returns 0 on success, -1 on error.    */
static int reg_write(int handle, uint8_t reg, uint8_t val)
{
    if (i2cWriteByteData(handle, reg, val) < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed\n",
                reg, val);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one byte from a register; returns 0 on success, -1 on error.   */
static int reg_read(int handle, uint8_t reg, uint8_t *out)
{
    int v = i2cReadByteData(handle, reg);
    if (v < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(reg=0x%02X) failed\n", reg);
        return -1;
    }
    *out = (uint8_t)v;
    return 0;
}

/* ------------------------------------------------------------------ */
