    if (i2cReadI2CBlockData(handle, FXOS8700_OUT_X_MSB, buf, 6) != 6) {
        fprintf(stderr, "[ERROR] i2cReadI2CBlockData(accel) failed\n");
        return -1;
    }

    *x = (int16_t)(((uint16_t)buf[0] << 8) | (uint8_t)buf[1]);
    *y = (int16_t)(((uint16_t)buf[2] << 8) | (uint8_t)buf[3]);
    *z = (int16_t)(((uint16_t)buf[4] << 8) | (uint8_t)buf[5]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Append a timestamped impact record to LOG_FILE.                     */
static void log_impact(int16_t x, int16_t y, int16_t z, double mag)
