#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define GYRO_ADDR      0x68
#define WHO_AM_I       0x0F
#define WHO_AM_I_VAL   0xD3
#define CTRL_REG1      0x20
#define OUT_X_L        0x28
#define OUT_X_H        0x29
#define OUT_Y_L        0x2A
#define OUT_Y_H        0x2B
#define OUT_Z_L        0x2C
#define OUT_Z_H        0x2D
#define ALERT_THRESHOLD 50.0f
#define SAMPLE_PERIOD_US 50000
#define NUM_CALIBRATION_SAMPLES 100

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg_l, int16_t *out) {
    uint8_t lo, hi;
    if (i2c_read_reg8(fd, reg_l, &lo) < 0) return -1;
    if (i2c_read_reg8(fd, reg_l + 1, &hi) < 0) return -1;
    *out = (int16_t)((hi << 8) | lo);
    return 0;
}

static int read_gyro(int fd, float *x, float *y, float *z) {
    int16_t raw_x, raw_y, raw_z;
    if (i2c_read_reg16(fd, OUT_X_L, &raw_x) < 0) return -1;
    if (i2c_read_reg16(fd, OUT_Y_L, &raw_y) < 0) return -1;
    if (i2c_read_reg16(fd, OUT_Z_L, &raw_z) < 0) return -1;
    *x = (float)raw_x / 32768.0f * 2000.0f;
    *y = (float)raw_y / 32768.0f * 2000.0f;
    *z = (float)raw_z / 32768.0f * 2000.0f;
    return 0;
}

static int calibrate_gyro(int fd, float *x_off, float *y_off, float *z_off) {
    float x_sum = 0.0f, y_sum = 0.0f, z_sum = 0.0f;
    float x, y, z;
    printf("Calibrating gyroscope (keep sensor stationary)...\n");
    for (int i = 0; i < NUM_CALIBRATION_SAMPLES; i++) {
        if (read_gyro(fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Calibration read error: %s\n", strerror(errno));
            return -1;
        }
        x_sum += x;
        y_sum += y;
        z_sum += z;
        usleep(10000);
    }
    *x_off = x_sum / NUM_CALIBRATION_SAMPLES;
    *y_off = y_sum / NUM_CALIBRATION_SAMPLES;
    *z_off = z_sum / NUM_CALIBRATION_SAMPLES;
    printf("Calibration complete. Offsets: X=%.2f, Y=%.2f, Z=%.2f\n", *x_off, *y_off, *z_off);
    return 0;
}

static void log_data(FILE *fp, float x, float y, float z, const char *alert) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) return;
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f,%.2f,%.2f,%s\n", ts, x, y, z, alert);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        perror("open " I2C_BUS);
        return EXIT_FAILURE;
    }
    if (ioctl(g_i2c_fd, I2C_SLAVE, GYRO_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    uint8_t who;
    if (i2c_read_reg8(g_i2c_fd, WHO_AM_I, &who) < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I: %s\n", strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", who, WHO_AM_I_VAL);
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    if (i2c_write_reg8(g_i2c_fd, CTRL_REG1, 0x0F) < 0) {
        fprintf(stderr, "Failed to write CTRL_REG1: %s\n", strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    float x_off = 0.0f, y_off = 0.0f, z_off = 0.0f;
    if (calibrate_gyro(g_i2c_fd, &x_off, &y_off, &z_off) < 0) {
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    g_log_file = fopen("gyro_log.txt", "a");
    if (!g_log_file) {
        perror("fopen gyro_log.txt");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    printf("Logging to gyro_log.txt at 20 Hz. Press Ctrl+C to stop.\n");

    while (g_running) {
        float x, y, z;
        if (read_gyro(g_i2c_fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Read error: %s\n", strerror(errno));
            break;
        }
        x -= x_off; y -= y_off; z -= z_off;

        const char *alert = "";
        if (fabsf(x) > ALERT_THRESHOLD || fabsf(y) > ALERT_THRESHOLD || fabsf(z) > ALERT_THRESHOLD) {
            alert = "ALERT";
            fprintf(stderr, "Alert: |X|=%.2f |Y|=%.2f |Z|=%.2f\n", fabsf(x), fabsf(y), fabsf(z));
        }

        log_data(g_log_file, x, y, z, alert);
        usleep(SAMPLE_PERIOD_US);
    }

    if (g_log_file) fclose(g_log_file);
    if (g_i2c_fd >= 0) close(g_i2c_fd);
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

