/*
 * ADXL345 accelerometer reader for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   ADXL345 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   ADXL345 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   ADXL345 VCC  -> 3.3 V
 *   ADXL345 GND  -> GND
 *   LED anode    -> GPIO17 (pin 11, BCM) via 330 Ω resistor -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o accel_log accel_log.c -li2c -lpigpio -lrt
 * Run:    sudo ./accel_log
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* ---- ADXL345 constants (verified against datasheet) ---- */
#define ADXL345_I2C_BUS        1
#define ADXL345_I2C_ADDR       0x53   /* AD0 tied high on Pi 4B */

#define ADXL345_REG_DEVID      0x00
#define ADXL345_REG_POWER_CTL  0x2D
#define ADXL345_REG_DATAX0     0x32
#define ADXL345_REG_BW_RATE    0x2C
#define ADXL345_REG_DATA_FORMAT 0x31

#define ADXL345_DEVID_EXPECTED 0xE5
#define ADXL345_RANGE_2G       0x00   /* ±2 g, full-resolution mode */
#define ADXL345_ODR_100HZ      0x0A   /* 100 Hz data rate */
#define ADXL345_POWER_ON       0x08   /* measure bit */

/* ---- Application constants ---- */
#define LED_GPIO               17
#define ACCEL_THRESHOLD_G      2.0f
#define SAMPLE_PERIOD_US       100000  /* 100 ms -> 10 Hz */
#define LOG_FILE_NAME          "accel_log.txt"

/* ---- Globals for cleanup ---- */
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;
static volatile sig_atomic_t g_running = 1;

/* ---- Prototypes ---- */
static int  adxl345_init(void);
static int  adxl345_read_accel(float *x, float *y, float *z);
static void log_data(float x, float y, float z);
static void check_threshold(float x, float y, float z);
static void cleanup(void);
static void signal_handler(int sig);

/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Initialize ADXL345 */
    if (adxl345_init() != 0) {
        fprintf(stderr, "Error: ADXL345 initialisation failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure LED GPIO */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", LED_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    /* Open log file in append mode */
    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (g_log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("ADXL345 logging started. Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (g_running) {
        float x, y, z;

        if (adxl345_read_accel(&x, &y, &z) == 0) {
            log_data(x, y, z);
            check_threshold(x, y, z);
        } else {
            fprintf(stderr, "Warning: I2C read error, skipping sample.\n");
        }

        gpioDelay(SAMPLE_PERIOD_US);  /* 100 ms */
    }

    cleanup();
    return EXIT_SUCCESS;
}

/* ------------------------------------------------------------------ */
/* Initialize the ADXL345: verify device ID, configure data format,   */
/* data rate, and enter measurement mode.                              */
/* ------------------------------------------------------------------ */
static int adxl345_init(void)
{
    g_i2c_handle = i2cOpen(ADXL345_I2C_BUS, ADXL345_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d).\n", g_i2c_handle);
        return -1;
    }

    /* Verify device ID */
    int devid = i2cReadByteData(g_i2c_handle, ADXL345_REG_DEVID);
    if (devid < 0) {
        fprintf(stderr, "Error: failed to read DEVID register (rc=%d).\n", devid);
        return -1;
    }
    if (devid != ADXL345_DEVID_EXPECTED) {
        fprintf(stderr, "Error: DEVID mismatch (got 0x%02X, expected 0x%02X).\n",
                devid, ADXL345_DEVID_EXPECTED);
        return -1;
    }

    /* Data format: full-resolution, ±2 g, right-justified */
    if (i2cWriteByteData(g_i2c_handle, ADXL345_REG_DATA_FORMAT,
                         ADXL345_RANGE_2G) < 0) {
        fprintf(stderr, "Error: failed to write DATA_FORMAT register.\n");
        return -1;
    }

    /* Data rate: 100 Hz */
    if (i2cWriteByteData(g_i2c_handle, ADXL345_REG_BW_RATE,
                         ADXL345_ODR_100HZ) < 0) {
        fprintf(stderr, "Error: failed to write BW_RATE register.\n");
        return -1;
    }

    /* Enter measurement mode */
    if (i2cWriteByteData(g_i2c_handle, ADXL345_REG_POWER_CTL,
                         ADXL345_POWER_ON) < 0) {
        fprintf(stderr, "Error: failed to write POWER_CTL register.\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read 6 bytes of acceleration data (X0, X1, Y0, Y1, Z0, Z1) and     */
/* convert to g units (full-resolution mode: 4 mg/LSB).                */
/* ------------------------------------------------------------------ */
static int adxl345_read_accel(float *x, float *y, float *z)
{
    char buf[6];

    if (i2cReadI2CBlockData(g_i2c_handle, ADXL345_REG_DATAX0, buf, 6) != 6) {
        return -1;
    }

    int16_t raw_x = (int16_t)((uint16_t)buf[1] << 8 | (uint8_t)buf[0]);
    int16_t raw_y = (int16_t)((uint16_t)buf[3] << 8 | (uint8_t)buf[2]);
    int16_t raw_z = (int16_t)((uint16_t)buf[5] << 8 | (uint8_t)buf[4]);

    /* Full-resolution mode: 4 mg/LSB = 0.004 g/LSB */
    *x = (float)raw_x * 0.004f;
    *y = (float)raw_y * 0.004f;
    *z = (float)raw_z * 0.004f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Log one sample to the file with a timestamp.                        */
/* ------------------------------------------------------------------ */
static void log_data(float x, float y, float z)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(g_log_file, "%s,%.3f,%.3f,%.3f\n", timestamp, x, y, z);
    fflush(g_log_file);
}

/* ------------------------------------------------------------------ */
/* Turn LED on if any axis exceeds threshold, off otherwise.           */
/* ------------------------------------------------------------------ */
static void check_threshold(float x, float y, float z)
{
    bool exceed = (fabsf(x) > ACCEL_THRESHOLD_G ||
                   fabsf(y) > ACCEL_THRESHOLD_G ||
                   fabsf(z) > ACCEL_THRESHOLD_G);

    gpioWrite(LED_GPIO, exceed ? 1 : 0);
}

/* ------------------------------------------------------------------ */
/* Release all resources.                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
}

/* ------------------------------------------------------------------ */
/* Signal handler: set flag so main loop exits and cleanup runs.       */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

