/*
 * GY-51 LSM303DLHC Compass Logger for Raspberry Pi Zero W
 *
 * Wiring:
 *   LSM303DLHC SDA -> GPIO2 (pin 3, I2C bus 1)
 *   LSM303DLHC SCL -> GPIO3 (pin 5, I2C bus 1)
 *   LSM303DLHC VCC -> 3.3 V
 *   LSM303DLHC GND -> GND
 *
 * Build: gcc -O2 -Wall -o compass compass.c -lpigpio -lm
 * Run:   sudo ./compass
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- LSM303DLHC I2C addresses ---- */
#define LSM303_ACCEL_ADDR 0x19
#define LSM303_MAG_ADDR   0x1E

/* ---- LSM303DLHC register addresses ---- */
#define LSM303_ACCEL_CTRL_REG1_A 0x20
#define LSM303_ACCEL_OUT_X_L_A   0x28
#define LSM303_MAG_MR_REG_M      0x02
#define LSM303_MAG_OUT_X_H_M     0x03

/* ---- Scaling factors ---- */
#define ACCEL_SCALE 0.0000610f   /* +/- 2g  -> 1 mg/LSB  -> 0.0001 g/LSB */
#define MAG_SCALE   0.00018f     /* +/- 4 gauss -> 0.14 µT/LSB -> 0.00018 G/LSB */

#define LOG_FILE "compass_log.txt"
#define SAMPLE_PERIOD_US 100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */

static int i2c_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len)
{
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc != (int)len) {
        fprintf(stderr, "I2C read block failed (reg 0x%02X, rc=%d)\n", reg, rc);
        return -1;
    }
    return 0;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t val)
{
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write byte failed (reg 0x%02X, rc=%d)\n", reg, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor init                                                         */
/* ------------------------------------------------------------------ */

static int init_accelerometer(int handle)
{
    /*
     * CTRL_REG1_A = 0x27
     *   bit 7-5 ODR = 100  -> 50 Hz output data rate
     *   bit 4-2 FS  = 001  -> +/- 2 g full scale
     *   bit 1-0     = 00   -> normal mode
     */
    if (i2c_write_byte(handle, LSM303_ACCEL_CTRL_REG1_A, 0x27) < 0)
        return -1;
    return 0;
}

static int init_magnetometer(int handle)
{
    /*
     * MR_REG_M = 0x00
     *   bit 7-6 MD = 00  -> continuous conversion mode
     *   bit 5-4 DO = 00  -> 800 Hz ODR
     *   bit 3-0     = 0000
     */
    if (i2c_write_byte(handle, LSM303_MAG_MR_REG_M, 0x00) < 0)
        return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Data acquisition                                                    */
/* ------------------------------------------------------------------ */

typedef struct {
    float x, y, z;
} sensor_data_t;

static int read_accelerometer(int handle, sensor_data_t *out)
{
    uint8_t buf[6];
    if (i2c_read_block(handle, LSM303_ACCEL_OUT_X_L_A | 0x80, buf, sizeof(buf)) < 0)
        return -1;

    int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);

    out->x = (float)raw_x * ACCEL_SCALE;
    out->y = (float)raw_y * ACCEL_SCALE;
    out->z = (float)raw_z * ACCEL_SCALE;
    return 0;
}

static int read_magnetometer(int handle, sensor_data_t *out)
{
    uint8_t buf[6];
    if (i2c_read_block(handle, LSM303_MAG_OUT_X_H_M, buf, sizeof(buf)) < 0)
        return -1;

    int16_t raw_x = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_z = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t raw_y = (int16_t)((buf[4] << 8) | buf[5]);

    out->x = (float)raw_x * MAG_SCALE;
    out->y = (float)raw_y * MAG_SCALE;
    out->z = (float)raw_z * MAG_SCALE;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Tilt-compensated heading                                            */
/* ------------------------------------------------------------------ */

static float calculate_heading(const sensor_data_t *accel,
                               const sensor_data_t *mag)
{
    float roll  = atan2f(accel->y, accel->z);
    float pitch = atan2f(-accel->x, sqrtf(accel->y * accel->y + accel->z * accel->z));

    float x_h = mag->x * cosf(pitch) + mag->z * sinf(pitch);
    float y_h = mag->y * cosf(roll) * cosf(pitch) -
                mag->x * sinf(roll) - mag->z * cosf(roll) * sinf(pitch);

    float heading = atan2f(y_h, x_h) * 180.0f / (float)M_PI;
    if (heading < 0.0f)
        heading += 360.0f;
    return heading;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */

static void log_data(FILE *fp, float heading,
                     const sensor_data_t *accel,
                     const sensor_data_t *mag)
{
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            heading,
            accel->x, accel->y, accel->z,
            mag->x, mag->y, mag->z);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Open I2C handles ---- */
    int accel_handle = i2cOpen(1, LSM303_ACCEL_ADDR, 0);
    if (accel_handle < 0) {
        fprintf(stderr, "Failed to open accelerometer (rc=%d)\n", accel_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int mag_handle = i2cOpen(1, LSM303_MAG_ADDR, 0);
    if (mag_handle < 0) {
        fprintf(stderr, "Failed to open magnetometer (rc=%d)\n", mag_handle);
        i2cClose(accel_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Sensor init ---- */
    if (init_accelerometer(accel_handle) < 0) {
        fprintf(stderr, "Accelerometer init failed\n");
        goto cleanup;
    }
    if (init_magnetometer(mag_handle) < 0) {
        fprintf(stderr, "Magnetometer init failed\n");
        goto cleanup;
    }

    /* ---- Open log file ---- */
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen");
        goto cleanup;
    }

    /* Write CSV header if file is empty */
    fseek(fp, 0, SEEK_END);
    if (ftell(fp) == 0) {
        fprintf(fp, "Timestamp,Heading,Accel_X,Accel_Y,Accel_Z,Mag_X,Mag_Y,Mag_Z\n");
        fflush(fp);
    }

    printf("Logging to %s. Press Ctrl+C to stop.\n", LOG_FILE);

    /* ---- Main loop ---- */
    while (g_running) {
        sensor_data_t accel, mag;

        if (read_accelerometer(accel_handle, &accel) < 0) {
            fprintf(stderr, "Accelerometer read error; skipping sample\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }
        if (read_magnetometer(mag_handle, &mag) < 0) {
            fprintf(stderr, "Magnetometer read error; skipping sample\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        float heading = calculate_heading(&accel, &mag);
        log_data(fp, heading, &accel, &mag);

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down gracefully...\n");

    fclose(fp);

cleanup:
    i2cClose(accel_handle);
    i2cClose(mag_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

