/*
 * VL6180X Time-of-Flight distance logger for Raspberry Pi 3 Model B+
 * Bus: I2C bus 1 (GPIO2=SDA, GPIO3=SCL), sensor address 0x29
 * Logs distance (mm) and door status to distance_log.txt every 100 ms.
 * Build: gcc -O2 -Wall -o vl6180x_log vl6180x_log.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define VL6180X_ADDR   0x29
#define LOG_FILE       "distance_log.txt"
#define SAMPLE_US      100000   /* 100 ms */
#define MAX_RETRIES    3

/* VL6180X register addresses */
#define REG_IDENTIFICATION_MODEL_ID     0x000
#define REG_SYSTEM_FRESH_OUT_OF_RESET   0x016
#define REG_SYSRANGE_START              0x018
#define REG_RESULT_RANGE_STATUS         0x04D
#define REG_RESULT_RANGE_VAL            0x062

#define EXPECTED_MODEL_ID               0xB4
#define DOOR_OPEN_THRESHOLD             100   /* mm */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ---------- signal handler ---------- */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---------- I2C helpers ---------- */
static int i2c_write_reg8(int handle, uint16_t reg, uint8_t val)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = val;
    return i2cWriteDevice(handle, buf, 3);
}

static int i2c_read_reg8(int handle, uint16_t reg, uint8_t *val)
{
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, buf, 2) < 0)
        return -1;
    if (i2cReadDevice(handle, buf, 1) != 1)
        return -1;
    *val = (uint8_t)buf[0];
    return 0;
}

static int i2c_read_reg16(int handle, uint16_t reg, uint16_t *val)
{
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, buf, 2) < 0)
        return -1;
    if (i2cReadDevice(handle, buf, 2) != 2)
        return -1;
    *val = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

/* ---------- VL6180X initialization ---------- */
static int vl6180x_init(int handle)
{
    uint8_t model_id = 0;

    if (i2c_read_reg8(handle, REG_IDENTIFICATION_MODEL_ID, &model_id) < 0) {
        fprintf(stderr, "Error: cannot read model ID (sensor absent or bus error)\n");
        return -1;
    }
    if (model_id != EXPECTED_MODEL_ID) {
        fprintf(stderr, "Error: unexpected model ID 0x%02X (expected 0x%02X)\n",
                model_id, EXPECTED_MODEL_ID);
        return -1;
    }

    uint8_t fresh = 0;
    if (i2c_read_reg8(handle, REG_SYSTEM_FRESH_OUT_OF_RESET, &fresh) < 0)
        return -1;

    if (fresh != 0x01) {
        /* Not fresh out of reset: clear the reset bit and re-apply defaults. */
        if (i2c_write_reg8(handle, 0x0207, 0x01) < 0) return -1;
        if (i2c_write_reg8(handle, 0x0208, 0x01) < 0) return -1;
        if (i2c_write_reg8(handle, 0x0096, 0x00) < 0) return -1;
        if (i2c_write_reg8(handle, 0x0097, 0xfd) < 0) return -1;
        if (i2c_write_reg8(handle, 0x00e3, 0x00) < 0) return -1;
        if (i2c_write_reg8(handle, 0x00e4, 0x04) < 0) return -1;
        if (i2c_write_reg8(handle, 0x00e5, 0x02) < 0) return -1;
        if (i2c_write_reg8(handle, 0x00e6, 0x01) < 0) return -1;
        if (i2c_write_reg8(handle, 0x00e7, 0x03) < 0) return -1;
        if (i2c_write_reg8(handle, 0x00f5, 0x02) < 0) return -1;
        if (i2c_write_reg8(handle, 0x00d9, 0x05) < 0) return -1;
        if (i2c_write_reg8(handle, 0x00db, 0xce) < 0) return -1;
        if (i2c_write_reg8(handle, 0x00dc, 0x03) < 0) return -1;
        if (i2c_write_reg8(handle, 0x00dd, 0xf8) < 0) return -1;
        if (i2c_write_reg8(handle, 0x009f, 0x00) < 0) return -1;
        if (i2c_write_reg8(handle, 0x00a3, 0x3c) < 0) return -1;
        if (i2c_write_reg8(handle, 0x00b7, 0x00) < 0) return -1;
        if (i2c_write_reg8(handle, 0x00bb, 0x3c) < 0) return -1;
        if (i2c_write_reg8(handle, 0x00b2, 0x09) < 0) return -1;
        if (i2c_write_reg8(handle, 0x00ca, 0x09) < 0) return -1;
        if (i2c_write_reg8(handle, 0x0198, 0x01) < 0) return -1;
        if (i2c_write_reg8(handle, 0x01b0, 0x17) < 0) return -1;
        if (i2c_write_reg8(handle, 0x01ad, 0x00) < 0) return -1;
        if (i2c_write_reg8(handle, 0x00ff, 0x05) < 0) return -1;
        if (i2c_write_reg8(handle, 0x0100, 0x05) < 0) return -1;
        if (i2c_write_reg8(handle, 0x0199, 0x05) < 0) return -1;
        if (i2c_write_reg8(handle, 0x01a6, 0x1b) < 0) return -1;
        if (i2c_write_reg8(handle, 0x01ac, 0x3e) < 0) return -1;
        if (i2c_write_reg8(handle, 0x01a7, 0x1f) < 0) return -1;
        if (i2c_write_reg8(handle, 0x0030, 0x00) < 0) return -1;
    }

    /* Recommended default settings from ST/Adafruit datasheets. */
    if (i2c_write_reg8(handle, 0x0011, 0x10) < 0) return -1;
    if (i2c_write_reg8(handle, 0x010a, 0x30) < 0) return -1;
    if (i2c_write_reg8(handle, 0x003f, 0x46) < 0) return -1;
    if (i2c_write_reg8(handle, 0x0031, 0xFF) < 0) return -1;
    if (i2c_write_reg8(handle, 0x0040, 0x63) < 0) return -1;
    if (i2c_write_reg8(handle, 0x002e, 0x01) < 0) return -1;
    if (i2c_write_reg8(handle, 0x001b, 0x09) < 0) return -1;
    if (i2c_write_reg8(handle, 0x003e, 0x31) < 0) return -1;
    if (i2c_write_reg8(handle, 0x0014, 0x24) < 0) return -1;
    if (i2c_write_reg8(handle, 0x0029, 0x02) < 0) return -1;
    if (i2c_write_reg8(handle, 0x0015, 0x00) < 0) return -1;
    if (i2c_write_reg8(handle, 0x0024, 0x01) < 0) return -1;
    if (i2c_write_reg8(handle, 0x0025, 0xdc) < 0) return -1;
    if (i2c_write_reg8(handle, 0x001c, 0x13) < 0) return -1;
    if (i2c_write_reg8(handle, 0x0032, 0x00) < 0) return -1;
    if (i2c_write_reg8(handle, 0x004b, 0x09) < 0) return -1;
    if (i2c_write_reg8(handle, 0x004c, 0x05) < 0) return -1;
    if (i2c_write_reg8(handle, 0x0046, 0x00) < 0) return -1;
    if (i2c_write_reg8(handle, 0x0047, 0x00) < 0) return -1;
    if (i2c_write_reg8(handle, 0x0009, 0x00) < 0) return -1;
