}

/* ---------- read distance ---------- */
static int vl6180x_read_distance(int handle, uint16_t *distance_mm)
{
    uint8_t status = 0;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2c_read_reg8(handle, REG_RESULT_RANGE_STATUS, &status) < 0) {
            retries++;
            gpioDelay(1000);
            continue;
        }
        if (status & 0x01) {
            uint16_t dist = 0;
            if (i2c_read_reg16(handle, REG_RESULT_RANGE_VAL, &dist) < 0) {
                retries++;
                gpioDelay(1000);
                continue;
            }
            *distance_mm = dist;
            return 0;
        }
        gpioDelay(1000);
        retries++;
    }
    return -1;
}

/* ---------- log data ---------- */
static void log_data(uint16_t distance_mm, int door_open)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Distance: %u mm, Door: %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec,
                (unsigned)distance_mm, door_open ? "OPEN" : "CLOSED");
    } else {
        fprintf(fp, "<unknown-time>, Distance: %u mm, Door: %s\n",
                (unsigned)distance_mm, door_open ? "OPEN" : "CLOSED");
    }

