        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, VL6180X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (vl6180x_init(g_i2c_handle) < 0) {
        fprintf(stderr, "Error: VL6180X initialization failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("VL6180X initialized. Logging to %s every 100 ms. Press Ctrl+C to exit.\n",
           LOG_FILE);

    while (g_running) {
        uint16_t distance = 0;
        int door_open = 0;

        if (vl6180x_read_distance(g_i2c_handle, &distance) == 0) {
            door_open = (distance < DOOR_OPEN_THRESHOLD) ? 1 : 0;
            log_data(distance, door_open);
            printf("Distance: %u mm, Door: %s\n", (unsigned)distance,
                   door_open ? "OPEN" : "CLOSED");
        } else {
            fprintf(stderr, "Warning: read failed, re-initializing sensor...\n");
            i2cClose(g_i2c_handle);
            g_i2c_handle = -1;
            gpioDelay(500000); /* 500 ms back-off */
            g_i2c_handle = i2cOpen(I2C_BUS, VL6180X_ADDR, 0);
            if (g_i2c_handle < 0) {
                fprintf(stderr, "Error: i2cOpen failed after re-init (handle=%d)\n",
                        g_i2c_handle);
                break;
            }
            if (vl6180x_init(g_i2c_handle) < 0) {
                fprintf(stderr, "Error: VL6180X re-initialization failed\n");
                break;
            }
        }

        gpioDelay(SAMPLE_US);
    }

    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
