#define SENSOR2_ADDR 0x02
#define SAMPLE_INTERVAL_US 10000
#define LOG_FILE "audio_log.dat"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static int i2c_handle1 = -1;
static int i2c_handle2 = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_audio_sample(int handle, int16_t *sample) {
    char buf[2];
    int bytes_read = i2cReadDevice(handle, buf, 2);
    if (bytes_read != 2) {
        fprintf(stderr, "Error reading audio sample (handle %d): %s\n", handle, strerror(errno));
        return -1;
    }
    *sample = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static double calculate_tdoa(int16_t s1, int16_t s2) {
    return (double)(s1 - s2) / 1000000.0;
}

static void log_data(struct timespec ts, int16_t s1, int16_t s2, double tdoa) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file not open\n");
        return;
    }
    fprintf(log_file, "%ld,%ld,%d,%d,%.6f\n", ts.tv_sec, ts.tv_nsec, s1, s2, tdoa);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
        i2c_handle1 = -1;
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
        i2c_handle2 = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
