/*
 * ADIS16488A IMU reader for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   ADIS16488A CS  -> GPIO8  (SPI0 CE0, BCM 8)
 *   ADIS16488A SCLK-> GPIO11 (SPI0 SCLK, BCM 11)
 *   ADIS16488A DOUT-> GPIO9  (SPI0 MISO, BCM 9)
 *   ADIS16488A DIN -> GPIO10 (SPI0 MOSI, BCM 10)
 *   ADIS16488A VDD -> 3.3 V
 *   ADIS16488A GND -> GND
 *
 * SPI: 1 MHz, mode 3 (CPOL=1, CPHA=1), 16-bit words.
 * Stall between command and data transfer: >= 40 us.
 * Sample period: 100 ms.
 *
 * Build: gcc -O2 -Wall -Wextra -o imu_reader imu_reader.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

/* ---- ADIS16488A register map (16-bit addresses) ---- */
#define ADIS16488_REG_GLOB_CMD   0x00
#define ADIS16488_REG_SUPPLY     0x02
#define ADIS16488_REG_X_GYRO_OUT 0x04
#define ADIS16488_REG_Y_GYRO_OUT 0x06
#define ADIS16488_REG_Z_GYRO_OUT 0x08
#define ADIS16488_REG_X_ACCL_OUT 0x0A
#define ADIS16488_REG_Y_ACCL_OUT 0x0C
#define ADIS16488_REG_Z_ACCL_OUT 0x0E
#define ADIS16488_REG_TEMP_OUT   0x10
#define ADIS16488_REG_SMPL_PRD   0x12
#define ADIS16488_REG_GLOB_CMD2  0x14

/* ---- SPI configuration ---- */
#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U   /* 1 MHz */
#define SPI_MODE        3          /* CPOL=1, CPHA=1 */
#define SPI_BITS        8          /* 8-bit words (16-bit registers) */

/* ---- ADIS16488A constants ---- */
#define ADIS16488_STALL_US      40U   /* min stall between command and data */
#define ADIS16488_SAMPLE_MS    100U  /* sample period */
#define ADIS16488_GYRO_SENS    0.005f  /* deg/sec/LSB */
#define ADIS16488_ACCEL_SENS   0.00025f /* g/LSB */

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static FILE    *g_csv = NULL;
static int      g_spi_fd = -1;
static struct gpiod_chip  *g_chip = NULL;
static struct gpiod_line  *g_cs_line = NULL;

/* ---- Signal handler ---- */
static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ---- Non-blocking delay (checks g_running every ~1 ms) ---- */
static void delay_ms(unsigned int ms)
{
    unsigned int elapsed = 0;
    while (elapsed < ms && g_running) {
        usleep(1000);
        elapsed++;
    }
}

/* ---- Read a 16-bit register from the ADIS16488A ----
 * Returns 0 on success, -1 on SPI error.
 * The 16-bit command word has bit 15 = 0, bits 14:8 = 0 (reserved),
 * bit 7 = 0 (read), and bits 6:0 = the 7-bit register address.
 */
static int adis16488_read_reg16(int fd, uint8_t reg, int16_t *out)
{
    uint8_t tx_cmd[2] = { 0x00, reg };
    uint8_t tx_data[2] = { 0x00, 0x00 };
    uint8_t rx_cmd[2]  = { 0 };
    uint8_t rx_data[2] = { 0 };

    /* Send read command (mode 3: MSB first, CPOL=1, CPHA=1) */
    struct spi_ioc_transfer cmd_xfer = {
        .tx_buf        = (unsigned long)tx_cmd,
        .rx_buf        = (unsigned long)rx_cmd,
        .len           = 2,
        .speed_hz      = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs   = 0,
        .cs_change     = 0,
        .tx_nbits      = 0,
        .rx_nbits      = 0,
        .pad           = 0
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &cmd_xfer) < 0) {
        fprintf(stderr, "SPI command transfer failed: %s\n", strerror(errno));
        return -1;
    }

    /* Stall to allow the sensor to prepare the data */
    usleep(ADIS16488_STALL_US);

    /* Read the 16-bit data word */
    struct spi_ioc_transfer data_xfer = {
        .tx_buf        = (unsigned long)tx_data,
        .rx_buf        = (unsigned long)rx_data,
        .len           = 2,
        .speed_hz      = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs   = 0,
        .cs_change     = 0,
        .tx_nbits      = 0,
        .rx_nbits      = 0,
        .pad           = 0
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &data_xfer) < 0) {
        fprintf(stderr, "SPI data transfer failed: %s\n", strerror(errno));
        return -1;
    }

    *out = (int16_t)((rx_data[0] << 8) | rx_data[1]);
    return 0;
}

/* ---- Cleanup helper ---- */
static void cleanup(void)
{
    if (g_cs_line) {
        gpiod_line_release(g_cs_line);
        g_cs_line = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    if (g_csv) {
        fclose(g_csv);
        g_csv = NULL;
    }
}

/* ---- Main ---- */
int main(void)
{
    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* ---- Open CSV file ---- */
    g_csv = fopen("imu_data.csv", "w");
    if (!g_csv) {
        fprintf(stderr, "Failed to open imu_data.csv: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    fprintf(g_csv, "timestamp,gyro_x,gyro_y,gyro_z,accel_x,accel_y,accel_z\n");

    /* ---- Open SPI device ---- */
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", SPI_DEVICE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Configure SPI ---- */
    uint8_t mode = SPI_MODE;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to set SPI speed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Open GPIO chip and request CS line (active low) ---- */
    g_chip = gpiod_chip_open_by_name("gpiochip4");
    if (!g_chip) {
        /* Fallback: try gpiochip0 (older kernels) */
        g_chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (!g_chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    g_cs_line = gpiod_chip_get_line(g_chip, 8); /* BCM 8 = SPI0 CE0 */
    if (!g_cs_line) {
        fprintf(stderr, "Failed to get GPIO line 8: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(g_cs_line, "adis16488_spi_cs", 1) < 0) {
        fprintf(stderr, "Failed to request CS line as output: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Verify sensor presence by reading SUPPLY register ---- */
    int16_t supply;
    if (adis16488_read_reg16(g_spi_fd, ADIS16488_REG_SUPPLY, &supply) < 0) {
        fprintf(stderr, "Sensor not responding on %s\n", SPI_DEVICE);
        cleanup();
        return EXIT_FAILURE;
    }
    printf("ADIS16488A detected (SUPPLY=0x%04X). Starting data acquisition...\n",
           (unsigned int)supply);

    /* ---- Main sampling loop ---- */
    while (g_running) {
        int16_t gx, gy, gz, ax, ay, az;

        if (adis16488_read_reg16(g_spi_fd, ADIS16488_REG_X_GYRO_OUT, &gx) < 0 ||
            adis16488_read_reg16(g_spi_fd, ADIS16488_REG_Y_GYRO_OUT, &gy) < 0 ||
            adis16488_read_reg16(g_spi_fd, ADIS16488_REG_Z_GYRO_OUT, &gz) < 0 ||
            adis16488_read_reg16(g_spi_fd, ADIS16488_REG_X_ACCL_OUT, &ax) < 0 ||
            adis16488_read_reg16(g_spi_fd, ADIS16488_REG_Y_ACCL_OUT, &ay) < 0 ||
            adis16488_read_reg16(g_spi_fd, ADIS16488_REG_Z_ACCL_OUT, &az) < 0) {
            fprintf(stderr, "SPI read error; skipping sample.\n");
            delay_ms(ADIS16488_SAMPLE_MS);
            continue;
        }

        /* Convert raw values to physical units */
        float gyro_x = (float)gx * ADIS16488_GYRO_SENS;
        float gyro_y = (float)gy * ADIS16488_GYRO_SENS;
        float gyro_z = (float)gz * ADIS16488_GYRO_SENS;
        float accel_x = (float)ax * ADIS16488_ACCEL_SENS;
        float accel_y = (float)ay * ADIS16488_ACCEL_SENS;
        float accel_z = (float)az * ADIS16488_ACCEL_SENS;

        /* Timestamp with millisecond precision */
        struct timespec ts;
        if (clock_gettime(CLOCK_REALTIME, &ts) < 0) {
            fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
            delay_ms(ADIS16488_SAMPLE_MS);
            continue;
        }
        struct tm tm_info;
        localtime_r(&ts.tv_sec, &tm_info);
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
        size_t len = strlen(timestamp);
        snprintf(timestamp + len, sizeof(timestamp) - len, ".%03ld",
                 ts.tv_nsec / 1000000L);

        fprintf(g_csv, "%s,%.4f,%.4f,%.4f,%.6f,%.6f,%.6f\n",
                timestamp, gyro_x, gyro_y, gyro_z,
                accel_x, accel_y, accel_z);
        fflush(g_csv);

        delay_ms(ADIS16488_SAMPLE_MS);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

