    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", SPI_DEVICE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Configure SPI ---- */
    uint8_t mode = SPI_MODE;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to set SPI speed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Open GPIO chip and request CS line (active low) ---- */
    g_chip = gpiod_chip_open_by_name("gpiochip4");
    if (!g_chip) {
        /* Fallback: try gpiochip0 (older kernels) */
        g_chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (!g_chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    g_cs_line = gpiod_chip_get_line(g_chip, 8); /* BCM 8 = SPI0 CE0 */
    if (!g_cs_line) {
        fprintf(stderr, "Failed to get GPIO line 8: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(g_cs_line, "adis16488_spi_cs", 1) < 0) {
        fprintf(stderr, "Failed to request CS line as output: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Verify sensor presence by reading SUPPLY register ---- */
    int16_t supply;
    if (adis16488_read_reg16(g_spi_fd, ADIS16488_REG_SUPPLY, &supply) < 0) {
        fprintf(stderr, "Sensor not responding on %s\n", SPI_DEVICE);
        cleanup();
        return EXIT_FAILURE;
    }
    printf("ADIS16488A detected (SUPPLY=0x%04X). Starting data acquisition...\n",
           (unsigned int)supply);

    /* ---- Main sampling loop ---- */
    while (g_running) {
        int16_t gx, gy, gz, ax, ay, az;

        if (adis16488_read_reg16(g_spi_fd, ADIS16488_REG_X_GYRO_OUT, &gx) < 0 ||
            adis16488_read_reg16(g_spi_fd, ADIS16488_REG_Y_GYRO_OUT, &gy) < 0 ||
            adis16488_read_reg16(g_spi_fd, ADIS16488_REG_Z_GYRO_OUT, &gz) < 0 ||
            adis16488_read_reg16(g_spi_fd, ADIS16488_REG_X_ACCL_OUT, &ax) < 0 ||
            adis16488_read_reg16(g_spi_fd, ADIS16488_REG_Y_ACCL_OUT, &ay) < 0 ||
            adis16488_read_reg16(g_spi_fd, ADIS16488_REG_Z_ACCL_OUT, &az) < 0) {
            fprintf(stderr, "SPI read error; skipping sample.\n");
            delay_ms(ADIS16488_SAMPLE_MS);
            continue;
        }

        /* Convert raw values to physical units */
        float gyro_x = (float)gx * ADIS16488_GYRO_SENS;
        float gyro_y = (float)gy * ADIS16488_GYRO_SENS;
        float gyro_z = (float)gz * ADIS16488_GYRO_SENS;
        float accel_x = (float)ax * ADIS16488_ACCEL_SENS;
        float accel_y = (float)ay * ADIS16488_ACCEL_SENS;
        float accel_z = (float)az * ADIS16488_ACCEL_SENS;

        /* Timestamp with millisecond precision */
        struct timespec ts;
        if (clock_gettime(CLOCK_REALTIME, &ts) < 0) {
            fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
            delay_ms(ADIS16488_SAMPLE_MS);
            continue;
        }
        struct tm tm_info;
        localtime_r(&ts.tv_sec, &tm_info);
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
        size_t len = strlen(timestamp);
        snprintf(timestamp + len, sizeof(timestamp) - len, ".%03ld",
                 ts.tv_nsec / 1000000L);

        fprintf(g_csv, "%s,%.4f,%.4f,%.4f,%.6f,%.6f,%.6f\n",
                timestamp, gyro_x, gyro_y, gyro_z,
                accel_x, accel_y, accel_z);
        fflush(g_csv);

        delay_ms(ADIS16488_SAMPLE_MS);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

