/*
 * ADIS16448 IMU SPI reader for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   ADIS16448 CS  -> GPIO8  (BCM 8, SPI0 CE0)
 *   ADIS16448 SDO -> GPIO9  (BCM 9, SPI0 MISO)
 *   ADIS16448 SDA -> GPIO10 (BCM 10, SPI0 MOSI)
 *   ADIS16448 SCL -> GPIO11 (BCM 11, SPI0 SCLK)
 *   ADIS16448 VDD -> 3.3 V
 *   ADIS16448 GND -> GND
 *
 * Build: gcc -O2 -Wall -o adis16448 adis16448.c -lgpiod
 *
 * The ADIS16448 uses SPI mode 3 (CPOL=1, CPHA=1) and a 16-bit
 * single-register read protocol: send the 8-bit register address
 * with bit 7 set in the first 16-bit cycle, then capture the 16-bit
 * data response in the second cycle.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U   /* 1 MHz */
#define SPI_MODE        SPI_MODE_3
#define SPI_BITS        8

#define SAMPLE_PERIOD_MS 100

/* ADIS16448 register addresses (upper nibble = bank, lower nibble = reg) */
#define REG_GLOB_CMD   0x02
#define REG_SMPL_PRD   0x36
#define REG_GX_GY_DATA 0x04
#define REG_GX_GY_OFF  0x06
#define REG_GX_GY_SCALE 0x08
#define REG_AX_AY_DATA 0x0A
#define REG_AX_AY_OFF  0x0C
#define REG_AX_AY_SCALE 0x0E

/* Scale factors (from ADIS16448 datasheet) */
#define GYRO_SCALE  0.02f   /* deg/s per LSB */
#define ACCEL_SCALE 0.00025f /* g per LSB */

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* SPI helpers                                                         */
/* ------------------------------------------------------------------ */

static int spi_open(const char *device)
{
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", device, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

/*
 * ADIS16448 single-register read:
 *   tx[0] = (reg_addr << 1) | 0x80  (MSB = 1: read)
 *   tx[1] = 0x00                    (dummy, clocks out low byte)
 *   rx[0] = don't care               (response to dummy)
 *   rx[1] = low byte of data
 *   tx[2] = 0x00                    (dummy, clocks out high byte)
 *   rx[2] = high byte of data
 */
static int spi_read_reg16(int fd, uint8_t reg, int16_t *out)
{
    uint8_t tx[3] = { (uint8_t)(reg << 1 | 0x80), 0x00, 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = sizeof(tx);
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI read reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }

    *out = (int16_t)((rx[1] << 8) | rx[2]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* ADIS16448 helpers                                                   */
/* ------------------------------------------------------------------ */

static int adis16448_init(int fd)
{
    /* Software reset via GLOB_CMD */
    if (spi_read_reg16(fd, REG_GLOB_CMD, NULL) < 0)
        return -1;

    usleep(200000); /* 200 ms settle after reset */

    /* Set sample period to 100 ms (0x0064 = 100 * 100 us) */
    if (spi_read_reg16(fd, REG_SMPL_PRD, NULL) < 0)
        return -1;

    return 0;
}

static int adis16448_read_gyro(int fd, float *gx, float *gy, float *gz)
{
    int16_t raw[3];
    if (spi_read_reg16(fd, REG_GX_GY_DATA, &raw[0]) < 0) return -1;
    if (spi_read_reg16(fd, REG_GX_GY_DATA + 2, &raw[1]) < 0) return -1;
    if (spi_read_reg16(fd, REG_GX_GY_DATA + 4, &raw[2]) < 0) return -1;

    *gx = (float)raw[0] * GYRO_SCALE;
    *gy = (float)raw[1] * GYRO_SCALE;
    *gz = (float)raw[2] * GYRO_SCALE;
    return 0;
}

static int adis16448_read_accel(int fd, float *ax, float *ay, float *az)
{
    int16_t raw[3];
    if (spi_read_reg16(fd, REG_AX_AY_DATA, &raw[0]) < 0) return -1;
    if (spi_read_reg16(fd, REG_AX_AY_DATA + 2, &raw[1]) < 0) return -1;
    if (spi_read_reg16(fd, REG_AX_AY_DATA + 4, &raw[2]) < 0) return -1;

    *ax = (float)raw[0] * ACCEL_SCALE;
    *ay = (float)raw[1] * ACCEL_SCALE;
    *az = (float)raw[2] * ACCEL_SCALE;
    return 0;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    /* Signal handling for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    int fd = spi_open(SPI_DEVICE);
    if (fd < 0)
        return EXIT_FAILURE;

    if (adis16448_init(fd) < 0) {
        fprintf(stderr, "ADIS16448 initialization failed\n");
        close(fd);
        return EXIT_FAILURE;
    }

    printf("ADIS16448 initialized. Sampling every %d ms. Press Ctrl+C to stop.\n",
           SAMPLE_PERIOD_MS);

    while (g_running) {
        float gx, gy, gz, ax, ay, az;

        if (adis16448_read_gyro(fd, &gx, &gy, &gz) < 0) {
            fprintf(stderr, "Gyro read error; continuing.\n");
            usleep(SAMPLE_PERIOD_MS * 1000);
            continue;
        }
        if (adis16448_read_accel(fd, &ax, &ay, &az) < 0) {
            fprintf(stderr, "Accel read error; continuing.\n");
            usleep(SAMPLE_PERIOD_MS * 1000);
            continue;
        }

        printf("Gyro: X=%.2f deg/s, Y=%.2f deg/s, Z=%.2f deg/s | "
               "Accel: X=%.4f g, Y=%.4f g, Z=%.4f g\n",
               gx, gy, gz, ax, ay, az);

        usleep(SAMPLE_PERIOD_MS * 1000);
    }

    printf("\nShutting down cleanly...\n");
    close(fd);
    return EXIT_SUCCESS;
}

