code:
/*
 * ADIS16448 IMU reader for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   ADIS16448 CS  -> GPIO8  (BCM 8, SPI0 CE0)
 *   ADIS16448 SCLK-> GPIO11 (BCM 11, SPI0 SCLK)
 *   ADIS16448 DOUT-> GPIO9  (BCM 9,  SPI0 MISO)
 *   ADIS16448 DIN -> GPIO10 (BCM 10, SPI0 MOSI)
 *   ADIS16448 VDD -> 3.3 V
 *   ADIS16448 GND -> GND
 *
 * SPI: channel 0, CE0, 1 MHz, Mode 0 (CPOL=0, CPHA=0)
 *
 * Build: gcc -O2 -Wall -o adis16448 adis16448.c -lpigpio -lrt
 * Run:   sudo ./adis16448
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- ADIS16448 register map (16-bit addresses, 16-bit data) ---- */
#define ADIS16448_REG_GLOB_CMD   0x00
#define ADIS16448_REG_SUPPLY     0x02
#define ADIS16448_REG_X_GYRO_OUT 0x04
#define ADIS16448_REG_Y_GYRO_OUT 0x06
#define ADIS16448_REG_Z_GYRO_OUT 0x08
#define ADIS16448_REG_X_ACCL_OUT 0x0A
#define ADIS16448_REG_Y_ACCL_OUT 0x0C
#define ADIS16448_REG_Z_ACCL_OUT 0x0E

/* ---- SPI configuration ---- */
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000          /* 1 MHz */
#define SPI_FLAGS   0                /* Mode 0, active-low CE */

/* ---- Timing ---- */
#define STALL_TIME_US  40            /* ADIS16448 needs >= 40 us between cmds */
#define SAMPLE_PERIOD_US 100000      /* 100 ms */

/* ---- Scaling factors (from datasheet) ---- */
#define GYRO_SCALE  0.05f            /* deg/sec per LSB */
#define ACCEL_SCALE 0.00025f         /* g per LSB */

/* ---- Globals for cleanup ---- */
static int spi_handle = -1;
static volatile sig_atomic_t terminate = 0;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ---- Write a 16-bit command to a 16-bit register ---- */
static int adis_write_reg(uint8_t reg, uint16_t val)
{
    char tx[2], rx[2];
    tx[0] = (char)reg;
    tx[1] = (char)(val & 0xFF);

    if (spiXfer(spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI write failed for reg 0x%02X\n", reg);
