    *gz = (float)((int16_t)raw) * GYRO_SCALE;

    if (adis_read_reg(ADIS16448_REG_X_ACCL_OUT, &raw) != 0) return -1;
    *ax = (float)((int16_t)raw) * ACCEL_SCALE;

    if (adis_read_reg(ADIS16448_REG_Y_ACCL_OUT, &raw) != 0) return -1;
    *ay = (float)((int16_t)raw) * ACCEL_SCALE;

    if (adis_read_reg(ADIS16448_REG_Z_ACCL_OUT, &raw) != 0) return -1;
    *az = (float)((int16_t)raw) * ACCEL_SCALE;

