/*
 * MPU-6886 6-axis IMU reader for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   MPU-6886 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   MPU-6886 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   MPU-6886 VDD  -> 3.3 V
 *   MPU-6886 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o mpu6886 mpu6886.c
 * Run:    ./mpu6886   (I2C bus 1, address 0x68)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- MPU-6886 constants (verified against datasheet) ---- */
#define MPU6886_ADDR        0x68
#define MPU6886_WHO_AM_I    0x75
#define MPU6886_WHO_AM_I_VAL 0x14

#define PWR_MGMT_1          0x6B
#define PWR_MGMT_2          0x6C
#define ACCEL_XOUT_H        0x3B
#define GYRO_XOUT_H         0x43

#define I2C_BUS             "/dev/i2c-1"
#define SAMPLE_PERIOD_MS    50
#define MAX_RETRIES         3

/* ---- Globals for signal handling ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Low-level I2C helpers ---- */

static int i2c_write_byte(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_write_byte(0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *dst, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_burst write(0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, dst, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "i2c_read_burst read(0x%02X, %zu): got %zd (%s)\n",
                reg, len, n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }
    return 0;
}

/* ---- Sensor abstraction ---- */

typedef struct {
    int16_t accel_x, accel_y, accel_z;
    int16_t gyro_x,  gyro_y,  gyro_z;
} sensor_data_t;

static int sensor_init(int fd)
{
    uint8_t who;
    if (i2c_read_burst(fd, MPU6886_WHO_AM_I, &who, 1) != 0)
        return -1;
    if (who != MPU6886_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who, MPU6886_WHO_AM_I_VAL);
        return -1;
    }

    /* Wake up: clear SLEEP bit, use internal 8 MHz clock */
    if (i2c_write_byte(fd, PWR_MGMT_1, 0x00) != 0)
        return -1;
    usleep(100000); /* allow oscillator to stabilize */

    /* Disable all internal sensors (accel + temp + gyro) */
    if (i2c_write_byte(fd, PWR_MGMT_2, 0x00) != 0)
        return -1;

    return 0;
}

static int sensor_read(int fd, sensor_data_t *out)
{
    uint8_t raw[12];
    if (i2c_read_burst(fd, ACCEL_XOUT_H, raw, sizeof(raw)) != 0)
        return -1;

    out->accel_x = (int16_t)((raw[0]  << 8) | raw[1]);
    out->accel_y = (int16_t)((raw[2]  << 8) | raw[3]);
    out->accel_z = (int16_t)((raw[4]  << 8) | raw[5]);
    out->gyro_x  = (int16_t)((raw[6]  << 8) | raw[7]);
    out->gyro_y  = (int16_t)((raw[8]  << 8) | raw[9]);
    out->gyro_z  = (int16_t)((raw[10] << 8) | raw[11]);
    return 0;
}

/* ---- Main ---- */

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, MPU6886_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                MPU6886_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    if (sensor_init(g_i2c_fd) != 0) {
        fprintf(stderr, "Sensor initialization failed.\n");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    printf("MPU-6886 initialized on %s (addr 0x%02X). Press Ctrl-C to stop.\n",
           I2C_BUS, MPU6886_ADDR);

    while (g_running) {
        sensor_data_t data;
        int ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; ++attempt) {
            if (sensor_read(g_i2c_fd, &data) == 0) {
                ok = 1;
                break;
            }
            usleep(10000); /* 10 ms backoff before retry */
        }

        if (!ok) {
            fprintf(stderr, "Persistent I2C read failure; aborting.\n");
            break;
        }

        printf("Accel: X=%6d Y=%6d Z=%6d  |  Gyro: X=%6d Y=%6d Z=%6d\n",
               data.accel_x, data.accel_y, data.accel_z,
               data.gyro_x,  data.gyro_y,  data.gyro_z);

        usleep(SAMPLE_PERIOD_MS * 1000);
    }

    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

