/*
 * ADXL345 impact monitor for Raspberry Pi Zero W
 *
 * Wiring:
 *   ADXL345 SDA  -> GPIO2  (I2C bus 1)
 *   ADXL345 SCL  -> GPIO3  (I2C bus 1)
 *   ADXL345 VDD  -> 3.3 V
 *   ADXL345 GND  -> GND
 *   Red LED anode-> GPIO17 (BCM) via 330 Ω resistor
 *   Red LED cathode-> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o impact_monitor impact_monitor.c -lpigpio -lrt
 * Run:    sudo ./impact_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- ADXL345 constants (verified against datasheet) ---- */
#define ADXL345_I2C_BUS        1
#define ADXL345_I2C_ADDR       0x53   /* AD0 tied high on Adafruit breakout */

#define ADXL345_REG_DEVID      0x00
#define ADXL345_REG_POWER_CTL  0x2D
#define ADXL345_REG_DATAX0     0x32
#define ADXL345_REG_BW_RATE    0x2C
#define ADXL345_REG_DATA_FORMAT 0x31

#define ADXL345_DEVID_EXPECTED 0xE5
#define ADXL345_SCALE_FACTOR   256.0f   /* LSB per g in full-resolution mode */

/* ---- Application constants ---- */
#define GPIO_LED               17
#define IMPACT_THRESHOLD_G     2.5f
#define POLL_INTERVAL_US       10000    /* 10 ms */
#define LED_ON_DURATION_US     500000   /* 500 ms */
#define LOG_FILE_NAME          "impact_log.txt"

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    /* gpioTerminate is safe to call even if gpioInitialise failed */
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Write one byte to a register; returns 0 on success, -1 on error.   */
static int adxl_write_reg(uint8_t reg, uint8_t value)
{
    if (i2cWriteByteData(g_i2c_handle, reg, value) < 0) {
        fprintf(stderr, "[ERROR] I2C write failed (reg=0x%02X, val=0x%02X)\n",
                reg, value);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one byte from a register; returns 0 on success, -1 on error.  */
static int adxl_read_reg(uint8_t reg, uint8_t *out)
{
    int v = i2cReadByteData(g_i2c_handle, reg);
    if (v < 0) {
        fprintf(stderr, "[ERROR] I2C read failed (reg=0x%02X)\n", reg);
        return -1;
    }
    *out = (uint8_t)v;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read 6 bytes of acceleration data (X, Y, Z) little-endian.         */
static int adxl_read_xyz(int16_t *x, int16_t *y, int16_t *z)
{
    char buf[6];
    int n = i2cReadI2CBlockData(g_i2c_handle, ADXL345_REG_DATAX0, buf, 6);
    if (n != 6) {
        fprintf(stderr, "[ERROR] I2C block read failed (got %d bytes)\n", n);
        return -1;
    }
    *x = (int16_t)((uint16_t)buf[0] | ((uint16_t)buf[1] << 8));
    *y = (int16_t)((uint16_t)buf[2] | ((uint16_t)buf[3] << 8));
    *z = (int16_t)((uint16_t)buf[4] | ((uint16_t)buf[5] << 8));
    return 0;
}

/* ------------------------------------------------------------------ */
static void log_impact(float magnitude, int16_t x, int16_t y, int16_t z)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r failed\n");
        return;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(g_log_file, "%s, Magnitude: %.2f g, X: %d, Y: %d, Z: %d\n",
            ts, magnitude, x, y, z);
    fflush(g_log_file);
}

/* ------------------------------------------------------------------ */
static void trigger_led(void)
{
    if (gpioWrite(GPIO_LED, 1) < 0) {
        fprintf(stderr, "[ERROR] Failed to set LED high\n");
        return;
    }
    gpioDelay(LED_ON_DURATION_US);
    if (gpioWrite(GPIO_LED, 0) < 0) {
        fprintf(stderr, "[ERROR] Failed to set LED low\n");
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[ERROR] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus ---- */
    g_i2c_handle = i2cOpen(ADXL345_I2C_BUS, ADXL345_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen failed (handle=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Verify device ID ---- */
    uint8_t devid = 0;
    if (adxl_read_reg(ADXL345_REG_DEVID, &devid) != 0) {
        fprintf(stderr, "[ERROR] Cannot read DEVID — sensor absent or bus error\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (devid != ADXL345_DEVID_EXPECTED) {
        fprintf(stderr, "[ERROR] DEVID mismatch: got 0x%02X, expected 0x%02X\n",
                devid, ADXL345_DEVID_EXPECTED);
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Configure ADXL345 ---- */
    /* Standby first so configuration changes take effect */
    if (adxl_write_reg(ADXL345_REG_POWER_CTL, 0x00) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }
    /* 100 Hz output data rate (0x0A) */
    if (adxl_write_reg(ADXL345_REG_BW_RATE, 0x0A) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }
    /* Full-resolution mode, ±2 g range (0x08) */
    if (adxl_write_reg(ADXL345_REG_DATA_FORMAT, 0x08) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }
    /* Clear the standby bit to start measurements */
    if (adxl_write_reg(ADXL345_REG_POWER_CTL, 0x08) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Configure LED GPIO ---- */
    if (gpioSetMode(GPIO_LED, PI_OUTPUT) < 0) {
        fprintf(stderr, "[ERROR] gpioSetMode failed for GPIO%d\n", GPIO_LED);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(GPIO_LED, 0);

    /* ---- Open log file ---- */
    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (g_log_file == NULL) {
        perror("fopen");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("ADXL345 impact monitor running. Threshold: %.2f g. Press Ctrl+C to exit.\n",
           IMPACT_THRESHOLD_G);

    /* ---- Main polling loop ---- */
    while (g_running) {
        int16_t x, y, z;
        if (adxl_read_xyz(&x, &y, &z) != 0) {
            /* Bus error — keep running but do not log */
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        float x_g = (float)x / ADXL345_SCALE_FACTOR;
        float y_g = (float)y / ADXL345_SCALE_FACTOR;
        float z_g = (float)z / ADXL345_SCALE_FACTOR;
        float magnitude = sqrtf(x_g * x_g + y_g * y_g + z_g * z_g);

        if (magnitude > IMPACT_THRESHOLD_G) {
            printf("Impact detected: %.2f g (X: %.2f, Y: %.2f, Z: %.2f)\n",
                   magnitude, x_g, y_g, z_g);
            log_impact(magnitude, x, y, z);
            trigger_led();
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

