#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <pigpio.h>

#define I2C_BUS 1
#define MMA8451Q_ADDR 0x1D
#define LED_GPIO 17
#define ACCEL_THRESHOLD 2.0f
#define POLL_DELAY_US 100000
#define LED_ON_DELAY_US 500000

#define REG_STATUS 0x00
#define REG_OUT_X_MSB 0x01
#define REG_SYSMOD 0x0B
#define REG_WHO_AM_I 0x0D
#define REG_XYZ_DATA_CFG 0x0E
#define REG_CTRL_REG1 0x2A

#define WHO_AM_I_VAL 0x2A

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_register(int handle, uint8_t reg, uint8_t *val) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) return -1;
    *val = (uint8_t)rc;
    return 0;
}

static int write_register(int handle, uint8_t reg, uint8_t val) {
    return i2cWriteByteData(handle, reg, val);
}

static int read_acceleration(int handle, int16_t *x, int16_t *y, int16_t *z) {
    char buf[6];
    if (i2cReadI2CBlockData(handle, REG_OUT_X_MSB, buf, 6) != 6) return -1;
    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    *z = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

static int init_mma8451q(int handle) {
    uint8_t who;
    if (read_register(handle, REG_WHO_AM_I, &who) < 0) {
        fprintf(stderr, "Error: Failed to read WHO_AM_I register.\n");
        return -1;
    }
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (0x%02X, expected 0x%02X).\n", who, WHO_AM_I_VAL);
        return -1;
    }
    if (write_register(handle, REG_XYZ_DATA_CFG, 0x00) < 0) return -1;
    if (write_register(handle, REG_CTRL_REG1, 0x01) < 0) return -1;
    return 0;
}

static void log_data(FILE *f, int16_t x, int16_t y, int16_t z) {
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    fprintf(f, "%04d-%02d-%02d %02d:%02d:%02d, X: %d, Y: %d, Z: %d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, x, y, z);
    fflush(f);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MMA8451Q_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device (code %d).\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_mma8451q(i2c_handle) < 0) {
        fprintf(stderr, "Error: MMA8451Q initialisation failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    log_file = fopen("impact_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error: Could not open log file.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("MMA8451Q impact monitor running. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int16_t x, y, z;
        if (read_acceleration(i2c_handle, &x, &y, &z) < 0) {
            fprintf(stderr, "Warning: I2C read error.\n");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        float xg = (float)x / 1024.0f;
        float yg = (float)y / 1024.0f;
        float zg = (float)z / 1024.0f;

        if (fabsf(xg) > ACCEL_THRESHOLD || fabsf(yg) > ACCEL_THRESHOLD || fabsf(zg) > ACCEL_THRESHOLD) {
            gpioWrite(LED_GPIO, 1);
            log_data(log_file, x, y, z);
            gpioDelay(LED_ON_DELAY_US);
            gpioWrite(LED_GPIO, 0);
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    gpioWrite(LED_GPIO, 0);
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

