#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define TMAG5273_ADDR 0x0C
#define REG_X_CH_RESULT 0x00
#define REG_Y_CH_RESULT 0x02
#define REG_Z_CH_RESULT 0x04
#define REG_DEVICE_ID 0x0D
#define EXPECTED_DEVICE_ID 0x5273
#define SAMPLE_INTERVAL_SEC 1

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *out) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        return -1;
    }
    *out = (int16_t)((buf[1] << 8) | buf[0]);
    return 0;
}

static int read_sensor_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    if (i2c_read_reg16(fd, REG_X_CH_RESULT, x) < 0) return -1;
    if (i2c_read_reg16(fd, REG_Y_CH_RESULT, y) < 0) return -1;
    if (i2c_read_reg16(fd, REG_Z_CH_RESULT, z) < 0) return -1;
    return 0;
}

static int log_data(FILE *fp, int16_t x, int16_t y, int16_t z) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        return -1;
    }
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, x, y, z) < 0) {
        return -1;
    }
    fflush(fp);
    return 0;
}

static int ensure_log_header(FILE *fp) {
    long pos = ftell(fp);
    if (pos < 0) return -1;
    if (pos == 0) {
        if (fprintf(fp, "Timestamp,X,Y,Z\n") < 0) return -1;
        fflush(fp);
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        perror("open " I2C_BUS);
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, TMAG5273_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    int16_t device_id = 0;
    if (i2c_read_reg16(g_i2c_fd, REG_DEVICE_ID, &device_id) < 0) {
        fprintf(stderr, "Failed to read device ID from TMAG5273\n");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }
    if (device_id != EXPECTED_DEVICE_ID) {
        fprintf(stderr, "Unexpected device ID: 0x%04X (expected 0x%04X)\n", device_id, EXPECTED_DEVICE_ID);
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    g_log_file = fopen("magnetic_field_log.csv", "a+");
    if (g_log_file == NULL) {
        perror("fopen magnetic_field_log.csv");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    if (ensure_log_header(g_log_file) < 0) {
        perror("ensure_log_header");
        fclose(g_log_file);
        g_log_file = NULL;
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    printf("TMAG5273 initialized. Logging to magnetic_field_log.csv (Ctrl+C to stop)\n");

    while (g_running) {
        int16_t x, y, z;
        if (read_sensor_data(g_i2c_fd, &x, &y, &z) < 0) {
            fprintf(stderr, "I2C read error, continuing...\n");
        } else {
            if (log_data(g_log_file, x, y, z) < 0) {
                fprintf(stderr, "Failed to write to log file\n");
            }
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down cleanly...\n");
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    return EXIT_SUCCESS;
}

