/*
 * ADXL345 Free-Fall Detector for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   ADXL345 SDA  -> GPIO2  (physical pin 3, I2C bus 1)
 *   ADXL345 SCL  -> GPIO3  (physical pin 5, I2C bus 1)
 *   ADXL345 INT1 -> GPIO17 (physical pin 11)
 *   ADXL345 VCC  -> 3.3 V
 *   ADXL345 GND  -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o freefall freefall.c -lpigpio -lrt
 *   (pigpio must be installed and the daemon must be running)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

/* ---- ADXL345 constants (verified against SparkFun datasheet) ---- */
#define ADXL345_I2C_BUS        "/dev/i2c-1"
#define ADXL345_ADDR           0x53   /* AD0 tied high on SparkFun breakout */

#define ADXL345_REG_DEVID      0x00
#define ADXL345_REG_POWER_CTL  0x2D
#define ADXL345_REG_INT_ENABLE 0x2E
#define ADXL345_REG_INT_MAP    0x2F
#define ADXL345_REG_INT_SOURCE 0x30
#define ADXL345_REG_DATAX0     0x32
#define ADXL345_REG_BW_RATE    0x2C
#define ADXL345_REG_DATA_FORMAT 0x31

#define ADXL345_DEVID_EXPECTED 0xE5
#define ADXL345_BW_100HZ       0x0A   /* 100 Hz data rate */
#define ADXL345_RANGE_2G       0x00   /* ±2 g full-resolution */
#define ADXL345_INT_FREE_FALL  0x01   /* Free-fall bit in INT_SOURCE */

#define GPIO_INTERRUPT_PIN     17
#define LOG_FILE_NAME          "freefall_log.csv"

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd   = -1;
static FILE    *g_log_file = NULL;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- I2C helpers ---- */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- ADXL345 helpers ---- */
static int adxl345_init(int fd)
{
    uint8_t devid = 0;

    if (i2c_read_reg8(fd, ADXL345_REG_DEVID, &devid) != 0)
        return -1;

    if (devid != ADXL345_DEVID_EXPECTED) {
        fprintf(stderr, "ADXL345 not found (DEVID=0x%02X, expected 0x%02X)\n",
                devid, ADXL345_DEVID_EXPECTED);
        return -1;
    }

    /* Standby before configuration */
    if (i2c_write_reg8(fd, ADXL345_REG_POWER_CTL, 0x00) != 0)
        return -1;

    /* 100 Hz data rate */
    if (i2c_write_reg8(fd, ADXL345_REG_BW_RATE, ADXL345_BW_100HZ) != 0)
        return -1;

    /* ±2 g full-resolution, right-justified, 10-bit */
    if (i2c_write_reg8(fd, ADXL345_REG_DATA_FORMAT,
                       ADXL345_RANGE_2G | 0x08) != 0)
        return -1;

    /* Free-fall interrupt on INT1 */
    if (i2c_write_reg8(fd, ADXL345_REG_INT_MAP, 0x00) != 0)
        return -1;

    /* Enable free-fall interrupt */
    if (i2c_write_reg8(fd, ADXL345_REG_INT_ENABLE, ADXL345_INT_FREE_FALL) != 0)
        return -1;

    /* Clear any latched interrupt */
    (void)i2c_read_reg8(fd, ADXL345_REG_INT_SOURCE, &devid);

    return 0;
}

static int adxl345_read_xyz(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t buf[6];

    if (write(fd, (uint8_t[]){ ADXL345_REG_DATAX0 }, 1) != 1) {
        fprintf(stderr, "Failed to set data register pointer: %s\n",
                strerror(errno));
        return -1;
    }
    if (read(fd, buf, 6) != 6) {
        fprintf(stderr, "Failed to read 6-byte acceleration block: %s\n",
                strerror(errno));
        return -1;
    }

    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);
    return 0;
}

static void adxl345_disable_interrupts(int fd)
{
    (void)i2c_write_reg8(fd, ADXL345_REG_INT_ENABLE, 0x00);
}

/* ---- Logging ---- */
static void log_data(FILE *fp, int16_t x, int16_t y, int16_t z)
{
    struct timespec ts;
    struct tm tm_info;
    char timestamp[32];

    clock_gettime(CLOCK_REALTIME, &ts);
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(fp, "%s.%03ld,%d,%d,%d\n",
            timestamp, ts.tv_nsec / 1000000L, x, y, z);
    fflush(fp);
}

/* ---- Main ---- */
int main(void)
{
    int ret = EXIT_FAILURE;

    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- I2C open ---- */
    g_i2c_fd = open(ADXL345_I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", ADXL345_I2C_BUS, strerror(errno));
        goto cleanup_gpio;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, ADXL345_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                ADXL345_ADDR, strerror(errno));
        goto cleanup_i2c;
    }

    /* ---- ADXL345 init ---- */
    if (adxl345_init(g_i2c_fd) != 0) {
        fprintf(stderr, "ADXL345 initialisation failed\n");
        goto cleanup_i2c;
    }

    /* ---- GPIO interrupt setup ---- */
    if (gpioSetMode(GPIO_INTERRUPT_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", GPIO_INTERRUPT_PIN);
        goto cleanup_i2c;
    }
    if (gpioSetPullUpDown(GPIO_INTERRUPT_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down on GPIO %d\n", GPIO_INTERRUPT_PIN);
        goto cleanup_i2c;
    }

    /* ---- Open log file ---- */
    g_log_file = fopen(LOG_FILE_NAME, "w");
    if (g_log_file == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE_NAME, strerror(errno));
        goto cleanup_i2c;
    }
    fprintf(g_log_file, "timestamp,X,Y,Z\n");
    fflush(g_log_file);

    printf("Free-fall detection started. Logging to %s\n", LOG_FILE_NAME);
    printf("Press Ctrl+C to exit.\n");

    /* ---- Main poll loop ---- */
    while (g_running) {
        int level = gpioRead(GPIO_INTERRUPT_PIN);
        if (level < 0) {
            fprintf(stderr, "GPIO read error on pin %d: %s\n",
                    GPIO_INTERRUPT_PIN, pigpio_error(level));
            break;
        }

        if (level == 1) {
            uint8_t int_source = 0;
            if (i2c_read_reg8(g_i2c_fd, ADXL345_REG_INT_SOURCE, &int_source) == 0) {
                if (int_source & ADXL345_INT_FREE_FALL) {
                    int16_t x, y, z;
                    if (adxl345_read_xyz(g_i2c_fd, &x, &y, &z) == 0) {
                        log_data(g_log_file, x, y, z);
                    } else {
                        fprintf(stderr, "Failed to read acceleration data\n");
                    }
                }
            } else {
                fprintf(stderr, "Failed to read interrupt source\n");
            }
        }

        gpioDelay(10000); /* 10 ms poll interval */
    }

    /* ---- Cleanup ---- */
    printf("\nShutting down...\n");
    adxl345_disable_interrupts(g_i2c_fd);
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    gpioTerminate();
    ret = EXIT_SUCCESS;

    return ret;

cleanup_i2c:
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
cleanup_gpio:
    gpioTerminate();
    return ret;
}

