/*
 * LSM6DSR Fall Detection Logger for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   LSM6DSR SDA  -> GPIO2 (BCM 2, I2C bus 1 SDA)
 *   LSM6DSR SCL  -> GPIO3 (BCM 3, I2C bus 1 SCL)
 *   LSM6DSR VDD  -> 3.3 V
 *   LSM6DSR GND  -> GND
 *
 * Build: gcc -O2 -Wall -o fall_detect fall_detect.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- LSM6DSR I2C ---- */
#define LSM6DSR_ADDR 0x6A   /* SA0 tied to VDD (0x6A) or GND (0x6B) per datasheet */

/* ---- LSM6DSR register addresses ---- */
#define WHO_AM_I   0x0F
#define CTRL1_XL   0x10
#define CTRL2_G    0x11
#define OUTX_L_G   0x22
#define OUTX_L_XL  0x28

#define WHO_AM_I_VAL 0x6C

/* ---- Configuration ---- */
#define I2C_BUS        1
#define SAMPLE_HZ      104
#define SAMPLE_US      (1000000 / SAMPLE_HZ)
#define LOG_FILE       "motion_log.txt"

/* ---- Fall detection thresholds (1 g = 9.80665 m/s^2) ---- */
#define ACCEL_THRESH_G  0.2f   /* Free-fall trigger: below this magnitude */
#define IMPACT_THRESH_G 2.5f   /* Impact confirm: above this magnitude */
#define IMPACT_WIN_S   1.0f   /* Window after free-fall to confirm impact */

/* ---- State machine ---- */
typedef enum {
    STATE_IDLE,
    STATE_FREEFALL,
    STATE_IMPACT
} State;

/* ---- Globals ---- */
static int      i2c_handle = -1;
static FILE    *log_file   = NULL;
static volatile sig_atomic_t terminate = 0;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ---- I2C helpers ---- */
static int reg_write(uint8_t reg, uint8_t val)
{
    char buf[2] = { (char)reg, (char)val };
    return i2cWriteDevice(i2c_handle, buf, 2);
}

static int reg_read(uint8_t reg, uint8_t *buf, uint8_t len)
{
    char cmd[1] = { (char)reg };
    if (i2cWriteDevice(i2c_handle, cmd, 1) != 0)
        return -1;
    return i2cReadDevice(i2c_handle, (char *)buf, len);
}

/* ---- Sensor init ---- */
static int init_lsm6dsr(void)
{
    uint8_t who;
    if (reg_read(WHO_AM_I, &who, 1) != 1) {
        fprintf(stderr, "Error: cannot read WHO_AM_I (sensor absent or bus error)\n");
        return -1;
    }
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (0x%02X, expected 0x%02X)\n",
                who, WHO_AM_I_VAL);
        return -1;
    }

    /* CTRL1_XL: ODR=104 Hz (0x40), FS_XL=±2 g (0x00) -> 0x40 */
    if (reg_write(CTRL1_XL, 0x40) != 0) {
        fprintf(stderr, "Error: writing CTRL1_XL\n");
        return -1;
    }

    /* CTRL2_G: ODR=104 Hz (0x40), FS_G=±250 dps (0x00) -> 0x40 */
    if (reg_write(CTRL2_G, 0x40) != 0) {
        fprintf(stderr, "Error: writing CTRL2_G\n");
        return -1;
    }

    return 0;
}

/* ---- Read accel + gyro ---- */
static int read_sensor(float *ax, float *ay, float *az,
                       float *gx, float *gy, float *gz)
{
    uint8_t buf[12];
    if (reg_read(OUTX_L_XL, buf, 12) != 12)
        return -1;

    int16_t raw_ax = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_ay = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_az = (int16_t)((buf[5] << 8) | buf[4]);
    int16_t raw_gx = (int16_t)((buf[7] << 8) | buf[6]);
    int16_t raw_gy = (int16_t)((buf[9] << 8) | buf[8]);
    int16_t raw_gz = (int16_t)((buf[11] << 8) | buf[10]);

    /* ±2 g  -> 16384 LSB/g  |  ±250 dps -> 16384 LSB/dps */
    *ax = (float)raw_ax / 16384.0f;
    *ay = (float)raw_ay / 16384.0f;
    *az = (float)raw_az / 16384.0f;
    *gx = (float)raw_gx / 16384.0f;
    *gy = (float)raw_gy / 16384.0f;
    *gz = (float)raw_gz / 16384.0f;

    return 0;
}

/* ---- Fall detection state machine ---- */
static State detect_fall(float ax, float ay, float az, State *prev_state,
                         double *ff_time, double t)
{
    float mag = sqrtf(ax * ax + ay * ay + az * az);

    switch (*prev_state) {
    case STATE_IDLE:
        if (mag < ACCEL_THRESH_G) {
            *ff_time = t;
            *prev_state = STATE_FREEFALL;
        }
        break;

    case STATE_FREEFALL:
        if (mag > IMPACT_THRESH_G && (t - *ff_time) < IMPACT_WIN_S) {
            *prev_state = STATE_IMPACT;
        } else if (mag >= ACCEL_THRESH_G) {
            /* Still in free-fall, reset timer */
            *ff_time = t;
        } else {
            *prev_state = STATE_IDLE;
        }
        break;

    case STATE_IMPACT:
        *prev_state = STATE_IDLE;
        break;
    }

    return *prev_state;
}

/* ---- CSV logging ---- */
static void log_data(float ax, float ay, float az,
                     float gx, float gy, float gz, State state)
{
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm;
    localtime_r(&ts.tv_sec, &tm);

    char ts_str[32];
    strftime(ts_str, sizeof(ts_str), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s.%03ld,%.4f,%.4f,%.4f,%.4f,%.4f,%.4f,%s\n",
            ts_str, ts.tv_nsec / 1000000,
            ax, ay, az, gx, gy, gz,
            state == STATE_IDLE ? "IDLE" :
            state == STATE_FREEFALL ? "FREEFALL" : "IMPACT");
    fflush(log_file);
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, LSM6DSR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (code %d)\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_lsm6dsr() != 0) {
        fprintf(stderr, "Error: LSM6DSR init failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error: opening log file");
        cleanup();
        return EXIT_FAILURE;
    }

    fprintf(log_file, "# LSM6DSR fall-detection log started\n");
    fprintf(log_file, "# timestamp,ax_g,ay_g,az_g,gx_dps,gy_dps,gz_dps,state\n");
    fflush(log_file);

    State state = STATE_IDLE;
    double ff_time = 0.0;
    uint32_t next_tick = gpioTick();

    while (!terminate) {
        float ax, ay, az, gx, gy, gz;

        if (read_sensor(&ax, &ay, &az, &gx, &gy, &gz) != 0) {
            fprintf(stderr, "Warning: I2C read error, skipping sample\n");
            next_tick += SAMPLE_US;
            gpioDelay(SAMPLE_US);
            continue;
        }

        double now = (double)gpioTick() / 1e6;
        state = detect_fall(ax, ay, az, &state, &ff_time, now);

        log_data(ax, ay, az, gx, gy, gz, state);

        next_tick += SAMPLE_US;
        uint32_t now_tick = gpioTick();
        if (next_tick > now_tick)
            gpioDelay(next_tick - now_tick);
        else
            next_tick = now_tick; /* fell behind */
    }

    cleanup();
    return EXIT_SUCCESS;
}

