static int spi_read_register(uint8_t reg, uint16_t *value) {
    char tx[2], rx[2];
    tx[0] = (char)(reg | 0x80);
    tx[1] = 0x00;
    if (spiXfer(spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI read failed for register 0x%02X\n", reg);
        return -1;
    }
    *value = ((uint16_t)(uint8_t)rx[0] << 8) | (uint8_t)rx[1];
    return 0;
}

static int spi_write_register(uint8_t reg, uint16_t value) {
    char tx[2], rx[2];
    tx[0] = (char)(reg & 0x7F);
    tx[1] = (char)(value & 0xFF);
    if (spiXfer(spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI write failed for register 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

static int initialize_gyro(void) {
    uint16_t who_am_i;
    if (spi_read_register(ADIS16266_WHO_AM_I, &who_am_i) != 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        return -1;
    }
    if (who_am_i != ADIS16266_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%04X, expected 0x%04X\n",
                who_am_i, ADIS16266_WHO_AM_I_VAL);
        return -1;
    }
    if (spi_write_register(ADIS16266_GLOB_CMD, 0x0001) != 0) {
        fprintf(stderr, "Failed to reset device\n");
        return -1;
    }
    gpioDelay(100000);
    if (spi_write_register(ADIS16266_SMPL_PRD, 0x000A) != 0) {
        fprintf(stderr, "Failed to set sample period\n");
        return -1;
    }
    if (spi_write_register(ADIS16266_GYROSRC, 0x0001) != 0) {
        fprintf(stderr, "Failed to set gyro source\n");
        return -1;
    }
    return 0;
