    uint16_t raw_x, raw_y, raw_z;
    if (spi_read_register(ADIS16266_GYRXOUT, &raw_x) != 0) return -1;
    if (spi_read_register(ADIS16266_GYRYOUT, &raw_y) != 0) return -1;
