/*
 * GY-50 L3G4200D Gyroscope Logger for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   L3G4200D VCC  -> Pi 3V3 (Pin 1)
 *   L3G4200D GND  -> Pi GND (Pin 9)
 *   L3G4200D SDA  -> Pi GPIO2 / I2C1 SDA (Pin 3)
 *   L3G4200D SCL  -> Pi GPIO3 / I2C1 SCL (Pin 5)
 *
 * Build: gcc -O2 -Wall -o gyro_logger gyro_logger.c -lpigpio -lrt
 * Run:   sudo ./gyro_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- L3G4200D I2C ---- */
#define I2C_BUS        1
#define L3G4200D_ADDR  0x6B   /* SA0 tied to GND on GY-50 */

/* ---- L3G4200D Registers ---- */
#define WHO_AM_I       0x0F
#define CTRL_REG1      0x20
#define CTRL_REG4      0x23
#define OUT_X_L        0x28
#define OUT_X_H        0x29
#define OUT_Y_L        0x2A
#define OUT_Y_H        0x2B
#define OUT_Z_L        0x2C
#define OUT_Z_H        0x2D

#define WHO_AM_I_VAL   0xD3   /* Documented for L3G4200D */

/* ---- Sensitivity: 8.75 mdps/LSB => 114.285 LSB/mdps ---- */
#define MDPS_PER_LSB   114.285f

/* ---- Sampling ---- */
#define SAMPLE_PERIOD_US 10000  /* 10 ms */

/* ---- Globals for cleanup ---- */
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;
static volatile sig_atomic_t g_terminate = 0;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_terminate = 1;
}

/* ---- I2C helpers ---- */
static int i2c_write_reg(uint8_t reg, uint8_t val)
{
    int rc = i2cWriteByteData(g_i2c_handle, reg, val);
    if (rc < 0)
        fprintf(stderr, "[WARN] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, val, rc);
    return rc;
}

static int i2c_read_block(uint8_t reg, uint8_t *buf, uint32_t len)
{
    int rc = i2cReadI2CBlockData(g_i2c_handle, reg, (char *)buf, len);
    if (rc < 0)
        fprintf(stderr, "[WARN] i2cReadI2CBlockData(reg=0x%02X, len=%u) failed: %d\n",
                reg, len, rc);
    return rc;
}

/* ---- Sensor init ---- */
static int init_l3g4200d(void)
{
    int rc;

    /* Verify device identity */
    rc = i2cReadByteData(g_i2c_handle, WHO_AM_I);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] WHO_AM_I read failed: %d\n", rc);
        return -1;
    }
    if (rc != WHO_AM_I_VAL) {
        fprintf(stderr, "[ERROR] WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                rc, WHO_AM_I_VAL);
        return -1;
    }

    /* CTRL_REG1: ODR=1000 (800 Hz), LPen=0, Zen=1, Yen=1, Xen=1 */
    if (i2c_write_reg(CTRL_REG1, 0x0F) < 0)
        return -1;

    /* CTRL_REG4: FS=00 (220 mdps), HR=0, BLE=0, SIM=0 */
    if (i2c_write_reg(CTRL_REG4, 0x00) < 0)
        return -1;

    return 0;
}

/* ---- Read gyroscope ---- */
static int read_gyro(float *x, float *y, float *z)
{
    uint8_t buf[6];

    if (i2c_read_block(OUT_X_L, buf, sizeof(buf)) != (int)sizeof(buf))
        return -1;

    int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);

    *x = (float)raw_x / MDPS_PER_LSB;
    *y = (float)raw_y / MDPS_PER_LSB;
    *z = (float)raw_z / MDPS_PER_LSB;

    return 0;
}

/* ---- Timestamp with nanosecond precision ---- */
static void get_timestamp(char *buf, size_t len)
{
    struct timespec ts;
    struct tm tm_info;

    clock_gettime(CLOCK_REALTIME, &ts);
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tm_info);
    size_t pos = strlen(buf);
    snprintf(buf + pos, len - pos, ".%09ld", ts.tv_nsec);
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_log_file) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void)
{
    float x, y, z;
    char timestamp[40];

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, L3G4200D_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, L3G4200D_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor with retries */
    int init_ok = 0;
    for (int attempt = 1; attempt <= 3; ++attempt) {
        if (init_l3g4200d() == 0) {
            init_ok = 1;
            break;
        }
        fprintf(stderr, "[WARN] init attempt %d/3 failed, retrying...\n", attempt);
        gpioDelay(100000); /* 100 ms */
    }
    if (!init_ok) {
        fprintf(stderr, "[FATAL] L3G4200D initialization failed after 3 attempts\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_file = fopen("gyro_log.csv", "a");
    if (!g_log_file) {
        perror("[FATAL] fopen(gyro_log.csv)");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0)
        fprintf(g_log_file, "Timestamp,X,Y,Z\n");

    /* Register signal handler */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("[WARN] sigaction(SIGINT)");
    }

    printf("L3G4200D logging started. Press Ctrl+C to stop.\n");

    /* Main loop */
    while (!g_terminate) {
        if (read_gyro(&x, &y, &z) == 0) {
            get_timestamp(timestamp, sizeof(timestamp));
            fprintf(g_log_file, "%s,%.3f,%.3f,%.3f\n", timestamp, x, y, z);
            fflush(g_log_file);
        } else {
            fprintf(stderr, "[ERROR] Failed to read gyroscope data\n");
        }
        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

