#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define D7S_ADDR       0x08
#define LOG_FILE       "vibration_log.csv"
#define SAMPLE_MS      100

/* D7S-0001 register map (16-bit big-endian data, 2 bytes per axis) */
#define REG_X_LSB      0x00
#define REG_X_MSB      0x01
#define REG_Y_LSB      0x02
#define REG_Y_MSB      0x03
#define REG_Z_LSB      0x04
#define REG_Z_MSB      0x05

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *out)
{
    uint8_t buf[2];
    ssize_t n;

    if (ioctl(fd, I2C_SLAVE, D7S_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE) failed: %s\n", strerror(errno));
        return -1;
    }

    /* Write the register pointer */
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }

    /* Read 2 bytes (LSB first, then MSB) */
    n = read(fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "I2C read reg 0x%02X failed: got %zd bytes (%s)\n",
                reg, n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }

    *out = (int16_t)((buf[1] << 8) | buf[0]);
    return 0;
}

static int read_d7s(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    if (i2c_read_reg16(fd, REG_X_LSB, x) < 0) return -1;
    if (i2c_read_reg16(fd, REG_Y_LSB, y) < 0) return -1;
    if (i2c_read_reg16(fd, REG_Z_LSB, z) < 0) return -1;
    return 0;
}

static void get_iso8601_utc(char *buf, size_t len)
{
    time_t t = time(NULL);
    struct tm tm_utc;
    gmtime_r(&t, &tm_utc);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%SZ", &tm_utc);
}

static int log_data(FILE *fp, const char *ts, int16_t x, int16_t y, int16_t z)
{
    if (fprintf(fp, "%s,%d,%d,%d\n", ts, x, y, z) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    int fd = -1;
    FILE *fp = NULL;
    int rc = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        goto cleanup;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        goto cleanup;
    }

    fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    /* Write header only if file is empty */
    if (ftell(fp) == 0) {
        if (fprintf(fp, "Timestamp,X,Y,Z\n") < 0 || fflush(fp) != 0) {
            fprintf(stderr, "Failed to write header: %s\n", strerror(errno));
            goto cleanup;
        }
    }

    printf("D7S vibration logger started. Press Ctrl+C to stop.\n");

    while (g_running) {
        int16_t x, y, z;
        char ts[32];

        if (read_d7s(fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Sensor read error; skipping sample.\n");
            usleep(SAMPLE_MS * 1000);
            continue;
        }

        get_iso8601_utc(ts, sizeof(ts));

        if (log_data(fp, ts, x, y, z) < 0) {
            fprintf(stderr, "Logging failed; continuing.\n");
        }

        usleep(SAMPLE_MS * 1000);
    }

    printf("\nExiting cleanly.\n");
    rc = EXIT_SUCCESS;

cleanup:
    if (fp) fclose(fp);
    if (fd >= 0) close(fd);
    return rc;
}

