        if (read_d7s(fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Sensor read error; skipping sample.\n");
            usleep(SAMPLE_MS * 1000);
            continue;
        }

        get_iso8601_utc(ts, sizeof(ts));

        if (log_data(fp, ts, x, y, z) < 0) {
            fprintf(stderr, "Logging failed; continuing.\n");
        }

        usleep(SAMPLE_MS * 1000);
    }

    printf("\nExiting cleanly.\n");
    rc = EXIT_SUCCESS;

cleanup:
    if (fp) fclose(fp);
    if (fd >= 0) close(fd);
    return rc;
}

