#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MMA8452Q_ADDR  0x1D
#define WHO_AM_I       0x0D
#define WHO_AM_I_VAL   0x2A
#define CTRL_REG1      0x2A
#define OUT_X_MSB      0x01
#define FALL_THRESHOLD 45.0
#define LOG_FILE       "fall_log.txt"
#define LOOP_DELAY_MS  10

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_mma8452q(int fd) {
    uint8_t whoami;
    if (i2c_read_block(fd, WHO_AM_I, &whoami, 1) < 0) return -1;
    if (whoami != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", whoami, WHO_AM_I_VAL);
        return -1;
    }
    if (i2c_write_reg(fd, CTRL_REG1, 0x00) < 0) return -1;
    if (i2c_write_reg(fd, CTRL_REG1, 0x01) < 0) return -1;
    return 0;
}

static int read_accel(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (i2c_read_block(fd, OUT_X_MSB, buf, 6) < 0) return -1;
    *x = (int16_t)(((buf[0] << 8) | buf[1]) >> 4);
    *y = (int16_t)(((buf[2] << 8) | buf[3]) >> 4);
    *z = (int16_t)(((buf[4] << 8) | buf[5]) >> 4);
    return 0;
}

static double calc_tilt(int16_t x, int16_t y, int16_t z) {
    double x_r = (double)x / 4096.0;
    double y_r = (double)y / 4096.0;
    double z_r = (double)z / 4096.0;
    return atan2(sqrt(x_r * x_r + y_r * y_r), z_r) * 180.0 / M_PI;
}

static void log_fall(int16_t x, int16_t y, int16_t z) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) return;
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    if (fprintf(g_log_fp, "%s, X: %d, Y: %d, Z: %d\n", ts, x, y, z) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
    } else {
        fflush(g_log_fp);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }
    if (ioctl(g_i2c_fd, I2C_SLAVE, MMA8452Q_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", MMA8452Q_ADDR, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }
    if (init_mma8452q(g_i2c_fd) < 0) {
        fprintf(stderr, "MMA8452Q initialization failed\n");
        close(g_i2c_fd);
        return 1;
    }
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }
    printf("MMA8452Q initialized. Logging falls to %s. Press Ctrl+C to exit.\n", LOG_FILE);

    while (g_running) {
        int16_t x, y, z;
        if (read_accel(g_i2c_fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Read error, skipping iteration\n");
            usleep(LOOP_DELAY_MS * 1000);
            continue;
        }
        double tilt = calc_tilt(x, y, z);
        if (tilt > FALL_THRESHOLD) {
            log_fall(x, y, z);
        }
        usleep(LOOP_DELAY_MS * 1000);
    }

    printf("\nShutting down...\n");
    if (g_log_fp) fclose(g_log_fp);
    if (g_i2c_fd >= 0) close(g_i2c_fd);
    return 0;
}

