#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED   1000000
#define SPI_FLAGS   0

#define ADXL354_REG_RESET          0x1F
#define ADXL354_REG_POWER_CTL      0x2D
#define ADXL354_REG_STATUS         0x04
#define ADXL354_REG_XDATA_H        0x08
#define ADXL354_REG_XDATA_L        0x09
#define ADXL354_REG_YDATA_H        0x0A
#define ADXL354_REG_YDATA_L        0x0B
#define ADXL354_REG_ZDATA_H        0x0C
#define ADXL354_REG_ZDATA_L        0x0D
#define ADXL354_REG_PARTID         0x00

#define ADXL354_RESET_VALUE        0x52
#define ADXL354_PARTID_VALUE       0xAD

#define SAMPLE_INTERVAL_US 100000
#define MAX_RETRIES        3

static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int spi_read_register(uint8_t reg, uint8_t *value) {
    char tx[2] = { (char)(reg | 0x80), 0x00 };
    char rx[2] = { 0, 0 };
    int ret = spiXfer(spi_handle, tx, rx, 2);
    if (ret != 2) {
        fprintf(stderr, "SPI read failed for register 0x%02X (ret=%d)\n", reg, ret);
        return -1;
    }
    *value = (uint8_t)rx[1];
    return 0;
}

static int spi_write_register(uint8_t reg, uint8_t value) {
    char tx[2] = { (char)(reg & 0x7F), (char)value };
    int ret = spiWrite(spi_handle, tx, 2);
    if (ret != 2) {
        fprintf(stderr, "SPI write failed for register 0x%02X (ret=%d)\n", reg, ret);
        return -1;
    }
    return 0;
}

static int read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    char tx[7] = { (char)(ADXL354_REG_XDATA_H | 0x80 | 0x40), 0, 0, 0, 0, 0, 0 };
    char rx[7] = { 0 };
    int ret = spiXfer(spi_handle, tx, rx, 7);
    if (ret != 7) {
        fprintf(stderr, "SPI read acceleration failed (ret=%d)\n", ret);
        return -1;
    }
    *x = (int16_t)(((uint16_t)(rx[2] & 0xFF) << 8) | (uint8_t)rx[1]);
    *y = (int16_t)(((uint16_t)(rx[5] & 0xFF) << 8) | (uint8_t)rx[4]);
    *z = (int16_t)(((uint16_t)(rx[6] & 0xFF) << 8) | (uint8_t)rx[5]);
    return 0;
}

static int log_data(int16_t x, int16_t y, int16_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    if (fprintf(log_file, "%s, X: %d, Y: %d, Z: %d\n", timestamp, x, y, z) < 0) {
        fprintf(stderr, "Failed to write to log file\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

static int initialize_adxl354(void) {
    uint8_t partid = 0;
    if (spi_read_register(ADXL354_REG_PARTID, &partid) != 0) {
        fprintf(stderr, "Failed to read PARTID\n");
        return -1;
    }
    if (partid != ADXL354_PARTID_VALUE) {
        fprintf(stderr, "Unexpected PARTID: 0x%02X (expected 0x%02X)\n", partid, ADXL354_PARTID_VALUE);
        return -1;
    }
    printf("ADXL354 detected (PARTID=0x%02X)\n", partid);

    if (spi_write_register(ADXL354_REG_RESET, ADXL354_RESET_VALUE) != 0) {
        fprintf(stderr, "Failed to reset ADXL354\n");
        return -1;
    }
    gpioDelay(1000);

    uint8_t status = 0;
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (spi_read_register(ADXL354_REG_STATUS, &status) != 0) {
            fprintf(stderr, "Failed to read status register\n");
            return -1;
        }
        if ((status & 0x04) != 0) {
            break;
        }
        gpioDelay(1000);
        retries++;
    }
    if (retries >= MAX_RETRIES) {
        fprintf(stderr, "ADXL354 not stable after reset\n");
        return -1;
    }

    if (spi_write_register(ADXL354_REG_POWER_CTL, 0x00) != 0) {
        fprintf(stderr, "Failed to clear RUN bit\n");
        return -1;
    }
    gpioDelay(1000);

    if (spi_write_register(ADXL354_REG_POWER_CTL, 0x01) != 0) {
        fprintf(stderr, "Failed to set RUN bit\n");
        return -1;
    }
    gpioDelay(1000);

    return 0;
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("vibration_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (initialize_adxl354() != 0) {
        fprintf(stderr, "ADXL354 initialization failed\n");
        cleanup();
        return 1;
    }

    printf("Starting vibration monitoring...\n");
    while (!terminate) {
        int16_t x, y, z;
        if (read_acceleration(&x, &y, &z) == 0) {
            if (log_data(x, y, z) != 0) {
                fprintf(stderr, "Logging failed\n");
            }
        } else {
            fprintf(stderr, "Failed to read acceleration data\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

