    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (initialize_adxl354() != 0) {
        fprintf(stderr, "ADXL354 initialization failed\n");
        cleanup();
        return 1;
    }

    printf("Starting vibration monitoring...\n");
    while (!terminate) {
        int16_t x, y, z;
        if (read_acceleration(&x, &y, &z) == 0) {
            if (log_data(x, y, z) != 0) {
                fprintf(stderr, "Logging failed\n");
            }
        } else {
            fprintf(stderr, "Failed to read acceleration data\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

