#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME  "gpiochip4"
#define GPIO_LINE_OFFSET 17
#define POLL_INTERVAL_SEC 1

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static void log_timestamped(const char *msg)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        perror("time");
        return;
    }
    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        perror("localtime_r");
        return;
    }
    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }
    printf("[%s] %s\n", ts, msg);
    fflush(stdout);
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    /* Install SIGINT handler for clean Ctrl-C exit */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the GPIO line for BCM 17 */
    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (line == NULL) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    /* Request the line as input */
    if (gpiod_line_request_input(line, "e18-d80nk-obstacle") < 0) {
        perror("gpiod_line_request_input");
        goto cleanup;
    }

    printf("Monitoring E18-D80NK obstacle sensor on %s line %d (BCM 17)...\n",
           GPIO_CHIP_NAME, GPIO_LINE_OFFSET);
    fflush(stdout);

    while (g_running) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            perror("gpiod_line_get_value");
            goto cleanup;
        }

        /* E18-D80NK outputs LOW when an obstacle is detected */
        if (val == 0) {
            log_timestamped("Self-parking sequence started");
            /* Simulate self-parking routine (1 second) */
            sleep(POLL_INTERVAL_SEC);
            log_timestamped("Self-parking sequence completed");
        }

        sleep(POLL_INTERVAL_SEC);
    }

    printf("\nExiting cleanly...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (line != NULL) {
        gpiod_line_release(line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    return ret;
}

