/*
 * KY-032 IR Obstacle Avoidance Sensor Monitor
 * Board:  Raspberry Pi 3 Model B+
 * Sensor 1: GPIO17 (physical pin 11)
 * Sensor 2: GPIO27 (physical pin 13)
 * Wiring:  KY-032 OUT -> 3.3 V via 1 kΩ resistor -> GPIO (active-low)
 *          KY-032 VCC -> 3.3 V
 *          KY-032 GND -> GND
 *
 * Build:  gcc -Wall -Wextra -O2 -o ky032_monitor ky032_monitor.c -lpigpio -lrt
 * Run:    sudo ./ky032_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 27
#define POLL_INTERVAL_US 100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */
static void print_timestamp(void)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        printf("[timestamp-error] ");
        return;
    }
    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        printf("[timestamp-error] ");
        return;
    }
    char buf[32];
    if (strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        printf("[timestamp-error] ");
        return;
    }
    printf("%s ", buf);
}

static void log_sensor_data(int s1, int s2)
{
    print_timestamp();
    printf("Sensor 1 (GPIO%d): %s | Sensor 2 (GPIO%d): %s\n",
           SENSOR_1_GPIO,
           s1 == 0 ? "OBSTACLE DETECTED" : "clear",
           SENSOR_2_GPIO,
           s2 == 0 ? "OBSTACLE DETECTED" : "clear");
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Install signal handlers for clean shutdown ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure GPIO pins as inputs ---- */
    if (gpioSetMode(SENSOR_1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", SENSOR_1_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR_2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", SENSOR_2_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Main polling loop ---- */
    while (g_running) {
        int s1 = gpioRead(SENSOR_1_GPIO);
        int s2 = gpioRead(SENSOR_2_GPIO);

        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "Error: GPIO read failed (s1=%d, s2=%d).\n", s1, s2);
            break;
        }

        log_sensor_data(s1, s2);

        /* Sleep 100 ms; gpioDelay is a busy-wait-free delay */
        gpioDelay(POLL_INTERVAL_US);
    }

    /* ---- Clean shutdown ---- */
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

