/*
 * ADIS16266 Gyroscope SPI Reader for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   ADIS16266 CS  -> GPIO8  (SPI0 CE0, /dev/spidev0.0)
 *   ADIS16266 SCLK-> GPIO11 (SPI0 SCLK)
 *   ADIS16266 DOUT-> GPIO9  (SPI0 MISO)
 *   ADIS16266 DIN -> GPIO10 (SPI0 MOSI)
 *   ADIS16266 VDD -> 3.3 V
 *   ADIS16266 GND -> GND
 *
 * Build: gcc -O2 -Wall -o adis16266_gyro adis16266_gyro.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U   /* 1 MHz */
#define SPI_MODE        SPI_MODE_3
#define SPI_BITS        8
#define SAMPLE_PERIOD_MS 100

/* ADIS16266 register addresses (MSB set = read, bit 6 = read) */
#define REG_XGYRO_OUT  0x04
#define REG_YGYRO_OUT  0x06
#define REG_ZGYRO_OUT  0x08
#define REG_TEMP_OUT   0x0A
#define REG_STATUS     0x0C

/* Scale factor: 0.02 deg/sec per LSB */
#define GYRO_SCALE 0.02f

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * ADIS16266 read protocol (2 transfers):
 *   Transfer 1: send address byte (MSB = 1, bit6 = 1 for read)
 *   Transfer 2: send 0x00,0x00; response contains the 16-bit data.
 */
static int adis16266_read_reg(int fd, uint8_t reg, int16_t *out)
{
    uint8_t tx1[2] = { (uint8_t)(reg | 0x40), 0x00 };
    uint8_t rx1[2] = { 0 };
    uint8_t tx2[2] = { 0x00, 0x00 };
    uint8_t rx2[2] = { 0 };

    struct spi_ioc_transfer tr1 = {
        .tx_buf        = (unsigned long)tx1,
        .rx_buf        = (unsigned long)rx1,
        .len           = 2,
        .speed_hz      = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs   = 0,
        .cs_change     = 0,
    };

    struct spi_ioc_transfer tr2 = {
        .tx_buf        = (unsigned long)tx2,
        .rx_buf        = (unsigned long)rx2,
        .len           = 2,
        .speed_hz      = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs   = 0,
        .cs_change     = 0,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(2), &tr1) < 0) {
        fprintf(stderr, "SPI transfer 1 failed: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(fd, SPI_IOC_MESSAGE(2), &tr2) < 0) {
        fprintf(stderr, "SPI transfer 2 failed: %s\n", strerror(errno));
        return -1;
    }

    *out = (int16_t)((rx2[0] << 8) | rx2[1]);
    return 0;
}

static void log_data(float x, float y, float z)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) == 0) {
        printf("[%ld.%06ld] X: %+.4f deg/s, Y: %+.4f deg/s, Z: %+.4f deg/s\n",
               (long)ts.tv_sec, ts.tv_nsec / 1000, x, y, z);
    } else {
        printf("X: %+.4f deg/s, Y: %+.4f deg/s, Z: %+.4f deg/s\n", x, y, z);
    }
    fflush(stdout);
}

int main(void)
{
    int fd = -1;
    int ret = EXIT_FAILURE;

    /* Install SIGINT handler for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open SPI device */
    fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", SPI_DEVICE, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Configure SPI mode */
    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Configure bits per word */
    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Configure max speed */
    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ failed: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("ADIS16266 Gyroscope Reader\n");
    printf("SPI device: %s | speed: %u Hz | mode: %u\n",
           SPI_DEVICE, speed, mode);
    printf("Press Ctrl+C to exit.\n\n");

    while (g_running) {
        int16_t raw_x = 0, raw_y = 0, raw_z = 0;
        bool read_ok = true;

        if (adis16266_read_reg(fd, REG_XGYRO_OUT, &raw_x) < 0) {
            read_ok = false;
        }
        if (adis16266_read_reg(fd, REG_YGYRO_OUT, &raw_y) < 0) {
            read_ok = false;
        }
        if (adis16266_read_reg(fd, REG_ZGYRO_OUT, &raw_z) < 0) {
            read_ok = false;
        }

        if (!read_ok) {
            fprintf(stderr, "SPI read error — continuing.\n");
        } else {
            float x = (float)raw_x * GYRO_SCALE;
            float y = (float)raw_y * GYRO_SCALE;
            float z = (float)raw_z * GYRO_SCALE;
            log_data(x, y, z);
        }

        /* Sleep 100 ms using nanosleep for portability */
        struct timespec req = { .tv_sec = 0, .tv_nsec = SAMPLE_PERIOD_MS * 1000000L };
        struct timespec rem;
        while (nanosleep(&req, &rem) == -1 && errno == EINTR && g_running) {
            req = rem;
        }
    }

    printf("\nShutting down cleanly.\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    return ret;
}

