#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LSM6DSR_ADDR        0x6A
#define LSM6DSR_WHO_AM_I    0x0F
#define LSM6DSR_WHO_AM_I_VAL 0x6C
#define LSM6DSR_CTRL1_XL    0x10
#define LSM6DSR_CTRL2_G     0x11
#define LSM6DSR_OUTX_L_G    0x22
#define LSM6DSR_OUTX_L_XL   0x28

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int reg_write(int handle, uint8_t reg, uint8_t val) {
    if (i2cWriteByteData(handle, reg, val) < 0) {
        fprintf(stderr, "Error writing 0x%02X to register 0x%02X\n", val, reg);
        return -1;
    }
    return 0;
}

static int reg_read(int handle, uint8_t reg, uint8_t *val) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading register 0x%02X\n", reg);
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

static int read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc != (int)len) {
        fprintf(stderr, "Error reading block from 0x%02X (got %d, expected %u)\n", reg, rc, len);
        return -1;
    }
    return 0;
}

static int init_lsm6dsr(int handle) {
    uint8_t who_am_i = 0;
    if (reg_read(handle, LSM6DSR_WHO_AM_I, &who_am_i) < 0) return -1;
    if (who_am_i != LSM6DSR_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", who_am_i, LSM6DSR_WHO_AM_I_VAL);
        return -1;
    }

    if (reg_write(handle, LSM6DSR_CTRL1_XL, 0x60) < 0) return -1;
    if (reg_write(handle, LSM6DSR_CTRL2_G,  0x60) < 0) return -1;

    return 0;
}

static int read_sensor_data(int handle, int16_t *ax, int16_t *ay, int16_t *az,
                            int16_t *gx, int16_t *gy, int16_t *gz) {
    uint8_t buf[6];

    if (read_block(handle, LSM6DSR_OUTX_L_XL, buf, 6) < 0) return -1;
    *ax = (int16_t)((buf[1] << 8) | buf[0]);
    *ay = (int16_t)((buf[3] << 8) | buf[2]);
    *az = (int16_t)((buf[5] << 8) | buf[4]);

    if (read_block(handle, LSM6DSR_OUTX_L_G, buf, 6) < 0) return -1;
    *gx = (int16_t)((buf[1] << 8) | buf[0]);
    *gy = (int16_t)((buf[3] << 8) | buf[2]);
    *gz = (int16_t)((buf[5] << 8) | buf[4]);

    return 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int handle = i2cOpen(1, LSM6DSR_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_lsm6dsr(handle) < 0) {
        fprintf(stderr, "LSM6DSR initialisation failed\n");
        i2cClose(handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (g_running) {
        int16_t ax, ay, az, gx, gy, gz;
        if (read_sensor_data(handle, &ax, &ay, &az, &gx, &gy, &gz) < 0) {
            fprintf(stderr, "Sensor read error, exiting\n");
            break;
        }

        printf("%d,%d,%d,%d,%d,%d\n", ax, ay, az, gx, gy, gz);
        fflush(stdout);

        if (g_running) {
            struct timespec ts = { .tv_sec = 0, .tv_nsec = 100 * 1000 * 1000 };
            nanosleep(&ts, NULL);
        }
    }

    i2cClose(handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

