        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int handle = i2cOpen(1, LSM6DSR_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_lsm6dsr(handle) < 0) {
        fprintf(stderr, "LSM6DSR initialisation failed\n");
        i2cClose(handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (g_running) {
        int16_t ax, ay, az, gx, gy, gz;
        if (read_sensor_data(handle, &ax, &ay, &az, &gx, &gy, &gz) < 0) {
            fprintf(stderr, "Sensor read error, exiting\n");
            break;
        }

        printf("%d,%d,%d,%d,%d,%d\n", ax, ay, az, gx, gy, gz);
        fflush(stdout);

        if (g_running) {
            struct timespec ts = { .tv_sec = 0, .tv_nsec = 100 * 1000 * 1000 };
            nanosleep(&ts, NULL);
        }
    }

    i2cClose(handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

