/*
 * FXOS8700 I2C reader for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   FXOS8700 SDA  -> GPIO2 (I2C1 SDA, pin 3)
 *   FXOS8700 SCL  -> GPIO3 (I2C1 SCL, pin 5)
 *   FXOS8700 VDD  -> 3.3 V
 *   FXOS8700 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o fxos8700 fxos8700.c -li2c
 * Run:    sudo ./fxos8700
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- FXOS8700 register definitions (from datasheet) ---- */
#define FXOS8700_I2C_ADDR        0x1D   /* SA0 tied high on Adafruit breakout */
#define FXOS8700_REG_STATUS      0x00
#define FXOS8700_REG_OUT_X_MSB   0x01   /* accel X MSB (14-bit left-aligned) */
#define FXOS8700_REG_OUT_X_LSB   0x02
#define FXOS8700_REG_OUT_Y_MSB   0x03
#define FXOS8700_REG_OUT_Y_LSB   0x04
#define FXOS8700_REG_OUT_Z_MSB   0x05
#define FXOS8700_REG_OUT_Z_LSB   0x06
#define FXOS8700_REG_M_OUT_X_MSB 0x07   /* mag X MSB (16-bit) */
#define FXOS8700_REG_M_OUT_X_LSB 0x08
#define FXOS8700_REG_M_OUT_Y_MSB 0x09
#define FXOS8700_REG_M_OUT_Y_LSB 0x0A
#define FXOS8700_REG_M_OUT_Z_MSB 0x0B
#define FXOS8700_REG_M_OUT_Z_LSB 0x0C
#define FXOS8700_REG_WHO_AM_I    0x0D
#define FXOS8700_REG_XYZ_DATA_CFG 0x0E
#define FXOS8700_REG_CTRL_REG1   0x2A
#define FXOS8700_REG_CTRL_REG2   0x2B
#define FXOS8700_REG_M_CTRL_REG1 0x5B
#define FXOS8700_REG_M_CTRL_REG2 0x5C
#define FXOS8700_REG_M_CTRL_REG3 0x5D
#define FXOS8700_REG_M_CTRL_REG4 0x5E
#define FXOS8700_REG_M_CTRL_REG5 0x5F

#define FXOS8700_WHO_AM_I_VAL    0xC7

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C block read from 0x%02X failed: got %zd of %zu (%s)\n",
                reg, n, len, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_fxos8700(int fd)
{
    uint8_t whoami = 0;
    if (i2c_read_reg8(fd, FXOS8700_REG_WHO_AM_I, &whoami) != 0)
        return -1;

    if (whoami != FXOS8700_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                whoami, FXOS8700_WHO_AM_I_VAL);
        return -1;
    }

    /* Standby mode so configuration registers can be changed */
    if (i2c_write_reg8(fd, FXOS8700_REG_CTRL_REG1, 0x00) != 0)
        return -1;

    /* Magnetometer: ultra-high resolution, OSR=1 */
    if (i2c_write_reg8(fd, FXOS8700_REG_M_CTRL_REG1, 0x1F) != 0)
        return -1;

    /* Magnetometer auto-increment enable */
    if (i2c_write_reg8(fd, FXOS8700_REG_M_CTRL_REG2, 0x20) != 0)
        return -1;

    /* Accel: +/-2g, 14-bit */
    if (i2c_write_reg8(fd, FXOS8700_REG_XYZ_DATA_CFG, 0x00) != 0)
        return -1;

    /* Active mode, 100 Hz ODR, no FSR */
    if (i2c_write_reg8(fd, FXOS8700_REG_CTRL_REG1, 0x01) != 0)
        return -1;

    return 0;
}

static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

int main(void)
{
    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus 1 ---- */
    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open /dev/i2c-1 failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, FXOS8700_I2C_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X failed: %s\n",
                FXOS8700_I2C_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Verify device presence ---- */
    uint8_t whoami = 0;
    if (i2c_read_reg8(g_i2c_fd, FXOS8700_REG_WHO_AM_I, &whoami) != 0) {
        fprintf(stderr, "Cannot read WHO_AM_I — sensor absent or bus error.\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (whoami != FXOS8700_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                whoami, FXOS8700_WHO_AM_I_VAL);
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Initialize sensor ---- */
    if (init_fxos8700(g_i2c_fd) != 0) {
        fprintf(stderr, "FXOS8700 initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("FXOS8700 initialized. Reading every 100 ms (Ctrl+C to stop).\n");

    /* ---- Main loop ---- */
    while (g_running) {
        uint8_t data[12];
        int ok = 0;

        for (int attempt = 0; attempt < 3 && g_running; attempt++) {
            if (i2c_read_block(g_i2c_fd, FXOS8700_REG_OUT_X_MSB, data, sizeof(data)) == 0) {
                ok = 1;
                break;
            }
            usleep(10000); /* 10 ms backoff before retry */
        }

        if (!ok) {
            fprintf(stderr, "Persistent I2C read failure — aborting.\n");
            break;
        }

        /* Accelerometer: 14-bit left-aligned, shift right 2 */
        int16_t ax = (int16_t)((data[0] << 8) | data[1]) >> 2;
        int16_t ay = (int16_t)((data[2] << 8) | data[3]) >> 2;
        int16_t az = (int16_t)((data[4] << 8) | data[5]) >> 2;

        /* Magnetometer: 16-bit */
        int16_t mx = (int16_t)((data[6] << 8) | data[7]);
        int16_t my = (int16_t)((data[8] << 8) | data[9]);
        int16_t mz = (int16_t)((data[10] << 8) | data[11]);

        printf("Accel: X=%6d  Y=%6d  Z=%6d  |  Mag: X=%6d  Y=%6d  Z=%6d\n",
               ax, ay, az, mx, my, mz);

        usleep(100000); /* 100 ms */
    }

    cleanup();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

