#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define ADXL345_ADDRESS 0x53
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATAX0 0x32
#define ADXL345_BW_RATE 0x2C
#define ADXL345_DATA_FORMAT 0x31
#define TILT_THRESHOLD 30.0
#define LOG_FILE "/var/log/tilt_events.log"
#define SAMPLE_INTERVAL_US 100000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int write_register(int handle, uint8_t reg, uint8_t value) {
    char buf[2] = {(char)reg, (char)value};
    if (i2cWriteDevice(handle, buf, 2) != 0) {
        fprintf(stderr, "Error writing to register 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

static int read_register(int handle, uint8_t reg, uint8_t *value) {
    char reg_buf[1] = {(char)reg};
    if (i2cWriteDevice(handle, reg_buf, 1) != 0) {
        fprintf(stderr, "Error setting register pointer to 0x%02X\n", reg);
        return -1;
    }
    char data_buf[1];
    if (i2cReadDevice(handle, data_buf, 1) != 1) {
        fprintf(stderr, "Error reading from register 0x%02X\n", reg);
        return -1;
    }
    *value = (uint8_t)data_buf[0];
    return 0;
}

static int read_acceleration(int handle, int16_t *x, int16_t *y, int16_t *z) {
    char reg_buf[1] = {(char)ADXL345_DATAX0};
    if (i2cWriteDevice(handle, reg_buf, 1) != 0) {
        fprintf(stderr, "Error setting register pointer to 0x%02X\n", ADXL345_DATAX0);
        return -1;
    }
    char data_buf[6];
    if (i2cReadDevice(handle, data_buf, 6) != 6) {
        fprintf(stderr, "Error reading acceleration data\n");
        return -1;
    }
    *x = (int16_t)((data_buf[1] << 8) | data_buf[0]);
    *y = (int16_t)((data_buf[3] << 8) | data_buf[2]);
    *z = (int16_t)((data_buf[5] << 8) | data_buf[4]);
    return 0;
}

static double calculate_tilt_angle(int16_t x, int16_t y, int16_t z) {
    double x_g = (double)x / 256.0;
    double y_g = (double)y / 256.0;
    double z_g = (double)z / 256.0;
    double tilt_angle = atan2(y_g, sqrt(x_g * x_g + z_g * z_g)) * 180.0 / M_PI;
    return tilt_angle;
}

static int log_tilt_event(double tilt_angle) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s - Tilt angle: %.2f degrees\n", timestamp, tilt_angle);
    fclose(fp);
    return 0;
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    int handle = i2cOpen(1, ADXL345_ADDRESS, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", handle);
        gpioTerminate();
        return 1;
    }

    uint8_t devid;
    if (read_register(handle, 0x00, &devid) != 0) {
        fprintf(stderr, "Error reading DEVID register\n");
        i2cClose(handle);
        gpioTerminate();
        return 1;
    }
    if (devid != 0xE5) {
        fprintf(stderr, "ADXL345 not detected (DEVID=0x%02X, expected 0xE5)\n", devid);
        i2cClose(handle);
        gpioTerminate();
        return 1;
    }

    if (write_register(handle, ADXL345_BW_RATE, 0x0A) != 0) {
        i2cClose(handle);
        gpioTerminate();
        return 1;
    }
