#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SOUND_SENSOR_GPIO 17
#define SAMPLE_INTERVAL_US 1000
#define WINDOW_DURATION_US 5000000
#define POST_WINDOW_DELAY_US 1000000

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int read_sound_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %s\n", gpio_pin, pigpio_error(value));
        return -1;
    }
    return value;
}

static int count_high_readings(int gpio_pin, int duration_us) {
    int count = 0;
    int elapsed = 0;
    while (elapsed < duration_us && program_running) {
        int reading = read_sound_sensor(gpio_pin);
        if (reading < 0) {
            return -1;
        }
        if (reading == 1) {
            count++;
        }
        gpioDelay(SAMPLE_INTERVAL_US);
        elapsed += SAMPLE_INTERVAL_US;
    }
    return count;
}

static void print_alert(int high_count, int threshold) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    if (high_count > threshold) {
        printf("%s - ALERT: High readings count = %d (threshold = %d)\n", timestamp, high_count, threshold);
    } else {
        printf("%s - Status: High readings count = %d (threshold = %d)\n", timestamp, high_count, threshold);
    }
    fflush(stdout);
}

int main(int argc, char *argv[]) {
    int threshold = 0;
    int high_count = 0;

    if (argc != 2) {
        fprintf(stderr, "Usage: %s <threshold>\n", argv[0]);
        return EXIT_FAILURE;
    }

    if (sscanf(argv[1], "%d", &threshold) != 1 || threshold <= 0) {
        fprintf(stderr, "Error: Invalid threshold value. Please enter a positive integer.\n");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SOUND_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as input\n", SOUND_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error registering SIGINT handler: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error registering SIGTERM handler: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Sound sensor monitoring started. Threshold: %d\n", threshold);
    fflush(stdout);

    while (program_running) {
        high_count = count_high_readings(SOUND_SENSOR_GPIO, WINDOW_DURATION_US);
        if (high_count < 0) {
            fprintf(stderr, "Error during sensor reading. Exiting.\n");
            break;
        }
        print_alert(high_count, threshold);
        gpioDelay(POST_WINDOW_DELAY_US);
    }

    gpioTerminate();
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

