/*
 * door_access.c — Raspberry Pi 4 Model B
 *
 * Two 12 V electromagnetic door locks, driven via TIP120 and 5 V relay modules
 * on GPIO17 (Door A) and GPIO27 (Door B), BCM numbering.
 *
 * Build:  gcc -Wall -Wextra -O2 -o door_access door_access.c -lgpiod
 * Run:    sudo ./door_access   (root needed for /dev/gpiochip0 access)
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define DOOR_A_PIN 17
#define DOOR_B_PIN 27
#define UNLOCK_DURATION_SEC 5
#define CODE_LENGTH 6
#define LOG_FILE "access_log.txt"
#define CHIP_NAME  "gpiochip0"

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int generate_code(char *out, size_t len)
{
    if (out == NULL || len < CODE_LENGTH + 1)
        return -1;

    for (int i = 0; i < CODE_LENGTH; i++) {
        int d = rand() % 10;
        out[i] = (char)('0' + d);
    }
    out[CODE_LENGTH] = '\0';
    return 0;
}

/* ------------------------------------------------------------------ */
static int read_code_from_user(char *out, size_t len)
{
    if (out == NULL || len < CODE_LENGTH + 1)
        return -1;

    printf("Enter security code: ");
    fflush(stdout);

    if (fgets(out, (int)len, stdin) == NULL) {
        if (feof(stdin))
            fprintf(stderr, "EOF on stdin.\n");
        else
            perror("fgets");
        return -1;
    }

    /* Strip trailing newline */
    out[strcspn(out, "\r\n")] = '\0';

    /* Reject empty input */
    if (out[0] == '\0') {
        fprintf(stderr, "Input is empty.\n");
        return -1;
    }

    /* Reject non-numeric */
    for (size_t i = 0; i < strlen(out); i++) {
        if (!isdigit((unsigned char)out[i])) {
            fprintf(stderr, "Invalid input: non-numeric character.\n");
            return -1;
        }
    }

    return 0;
}

/* ------------------------------------------------------------------ */
static int compare_codes(const char *user, const char *gen)
{
    return strcmp(user, gen);
}

/* ------------------------------------------------------------------ */
static int log_access(const char *code)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        perror("time");
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        perror("localtime_r");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed.\n");
        return -1;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    if (fprintf(fp, "%s,%s\n", ts, code) < 0) {
        perror("fprintf");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
static int unlock_door(struct gpiod_line *line, int pin)
{
    if (gpiod_line_set_value(line, 1) < 0) {
        fprintf(stderr, "Failed to set GPIO%d HIGH (unlock): %s\n",
                pin, strerror(errno));
        return -1;
    }

    /* Sleep in 1 s increments so we can exit promptly on signal */
    for (int i = 0; i < UNLOCK_DURATION_SEC && g_running; i++)
        sleep(1);

    if (gpiod_line_set_value(line, 0) < 0) {
        fprintf(stderr, "Failed to set GPIO%d LOW (lock): %s\n",
                pin, strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line_a = NULL;
    struct gpiod_line *line_b = NULL;
    int rc = EXIT_FAILURE;

    srand((unsigned int)time(NULL));

    if (install_signal_handlers() != 0)
        goto cleanup;

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (chip == NULL) {
        perror("gpiod_chip_open_by_name");
        goto cleanup;
    }

    line_a = gpiod_chip_get_line(chip, DOOR_A_PIN);
    if (line_a == NULL) {
        perror("gpiod_chip_get_line(DOOR_A_PIN)");
        goto cleanup;
    }

    line_b = gpiod_chip_get_line(chip, DOOR_B_PIN);
    if (line_b == NULL) {
        perror("gpiod_chip_get_line(DOOR_B_PIN)");
        goto cleanup;
    }

    /* Request both lines as outputs, default LOW (energized / closed) */
    if (gpiod_line_request_output(line_a, "door_access", 0) < 0) {
        perror("gpiod_line_request_output(line_a)");
        goto cleanup;
    }

    if (gpiod_line_request_output(line_b, "door_access", 0) < 0) {
        perror("gpiod_line_request_output(line_b)");
        goto cleanup;
    }

    printf("Door access control system started.\n");
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        char code[CODE_LENGTH + 1];
        char user[CODE_LENGTH + 1];

        if (generate_code(code, sizeof(code)) != 0) {
            fprintf(stderr, "Code generation failed.\n");
            break;
        }

        printf("Security code: %s\n", code);
        fflush(stdout);

        if (read_code_from_user(user, sizeof(user)) != 0) {
            if (!g_running)
                break;
            fprintf(stderr, "Invalid input, please try again.\n");
            continue;
        }

        if (compare_codes(user, code) == 0) {
            printf("Access granted!\n");

            if (unlock_door(line_a, DOOR_A_PIN) != 0 ||
                unlock_door(line_b, DOOR_B_PIN) != 0) {
                fprintf(stderr, "Unlock sequence failed.\n");
                break;
            }

            if (log_access(code) != 0) {
                fprintf(stderr, "Failed to log access.\n");
            }

            printf("Access logged.\n");
        } else {
            printf("Access denied.\n");
        }
    }

    rc = EXIT_SUCCESS;

cleanup:
    /* Ensure both doors are locked before releasing resources */
    if (line_a != NULL)
        gpiod_line_set_value(line_a, 0);
    if (line_b != NULL)
        gpiod_line_set_value(line_b, 0);

    if (line_a != NULL)
        gpiod_line_release(line_a);
    if (line_b != NULL)
        gpiod_line_release(line_b);
    if (chip != NULL)
        gpiod_chip_close(chip);

    printf("Exiting.\n");
    return rc;
}

