#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#define BH1750_ADDR 0x23
#define I2C_BUS 1
#define LOG_FILE "light_log.txt"
#define MAX_CONVERSION_TIME_MS 180
#define SAMPLE_INTERVAL_S 5

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_bh1750(int handle, float *lux) {
    unsigned char data[2];
    int result;

    /* Send one-time high-resolution mode command (0x20) */
    result = i2cWriteByte(handle, 0x20);
    if (result < 0) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }

    /* Wait for conversion to complete */
    gpioDelay(MAX_CONVERSION_TIME_MS * 1000);

    /* Read 2 bytes of data */
    result = i2cReadDevice(handle, (char *)data, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }

    /* Convert raw data to lux */
    unsigned int raw_value = (data[0] << 8) | data[1];
    *lux = (float)raw_value / 1.2;

    return 0;
}

static int log_data(const char *filename, float lux) {
    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "Timestamp: %s, Lux: %.2f\n", timestamp, lux);
    fclose(fp);
    return 0;
}

int main() {
    float lux;

    /* Register signal handler for Ctrl+C */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Open I2C device */
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    /* Main loop */
    while (running) {
        if (read_bh1750(i2c_handle, &lux) == 0) {
            if (log_data(LOG_FILE, lux) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        /* Sleep for the sample interval, checking running flag every second */
        for (int i = 0; i < SAMPLE_INTERVAL_S && running; i++) {
            gpioDelay(1000000);
        }
    }

    /* Clean up */
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    printf("\nExiting gracefully...\n");
    return 0;
}

