#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <time.h>
#include <fcntl.h>
#include <sys/socket.h>
#include <sys/ioctl.h>
#include <netinet/in.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define MPR121_ADDR 0x5A
#define I2C_BUS 1
#define TCP_PORT 12345
#define PWM_PIN 18
#define PWM_FREQ 1000
#define PWM_RANGE 1000
#define LOG_FILE "frequency_log.txt"
#define AUTH_MSG "MOTION_DETECTED:"
#define SECRET_KEY "MySecretKey"
#define PLAY_DURATION_SEC 5
#define SAMPLE_INTERVAL_US 20000

#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECONFIG 0x5E
#define MPR121_SOFTRESET 0x80

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static int server_fd = -1;
static int client_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int mpr121_write_reg(uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(i2c_fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

static int mpr121_read_reg(uint8_t reg, uint8_t *val) {
    if (write(i2c_fd, &reg, 1) != 1) {
        perror("I2C write (reg select) failed");
        return -1;
    }
    if (read(i2c_fd, val, 1) != 1) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

static int mpr121_init(void) {
    if (mpr121_write_reg(MPR121_SOFTRESET, 0x63) < 0) return -1;
    gpioDelay(10000);

    if (mpr121_write_reg(MPR121_ELECONFIG, 0x0C) < 0) return -1;
    gpioDelay(10000);

    return 0;
}

static int read_touch_data(uint16_t *touch_data) {
    uint8_t low, high;
    if (mpr121_read_reg(MPR121_TOUCHSTATUS_L, &low) < 0) return -1;
    if (mpr121_read_reg(MPR121_TOUCHSTATUS_H, &high) < 0) return -1;
    *touch_data = ((uint16_t)high << 8) | low;
    return 0;
}

static int authenticate_message(const char *message) {
    const char *secret = SECRET_KEY;
    size_t msg_len = strlen(message);
    size_t secret_len = strlen(secret);
    if (msg_len < secret_len) return 0;
    for (size_t i = 0; i < secret_len; i++) {
        if (message[i] != secret[i]) return 0;
    }
    return 1;
}

static void play_tone(int frequency) {
    if (frequency > 0) {
        gpioSetPWMfrequency(PWM_PIN, frequency);
        gpioPWM(PWM_PIN, PWM_RANGE / 2);
    } else {
        gpioPWM(PWM_PIN, 0);
    }
}

static void log_frequency(int frequency) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d,%d\n", (int)tm.tm_sec, frequency);
    fclose(fp);
}

static void cleanup(void) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (client_fd >= 0) {
        close(client_fd);
        client_fd = -1;
    }
    if (server_fd >= 0) {
        close(server_fd);
        server_fd = -1;
    }
    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction failed");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        gpioTerminate();
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPR121_ADDR) < 0) {
        perror("Failed to acquire I2C bus access");
        cleanup();
        return 1;
    }

    if (mpr121_init() < 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        cleanup();
        return 1;
    }

    gpioSetMode(PWM_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(PWM_PIN, PWM_FREQ);
    gpioSetPWMrange(PWM_PIN, PWM_RANGE);

    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        perror("Socket creation failed");
        cleanup();
        return 1;
    }

    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        perror("setsockopt failed");
        cleanup();
        return 1;
    }

    struct sockaddr_in address;
    memset(&address, 0, sizeof(address));
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(TCP_PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("Bind failed");
        cleanup();
        return 1;
    }

    if (listen(server_fd, 3) < 0) {
        perror("Listen failed");
        cleanup();
        return 1;
    }

    printf("Theremin server listening on port %d...\n", TCP_PORT);

    while (running) {
        client_fd = accept(server_fd, NULL, NULL);
        if (client_fd < 0) {
            if (errno == EINTR) continue;
            perror("Accept failed");
            break;
        }

        char buffer[1024];
        ssize_t bytes_received = recv(client_fd, buffer, sizeof(buffer) - 1, 0);
        if (bytes_received > 0) {
            buffer[bytes_received] = '\0';
            buffer[strcspn(buffer, "\r\n")] = '\0';

            if (strncmp(buffer, AUTH_MSG, strlen(AUTH_MSG)) == 0 &&
                authenticate_message(buffer)) {
                printf("Authentication successful\n");

                uint16_t touch_data;
                time_t start_time = time(NULL);
                while (running && (time(NULL) - start_time) < PLAY_DURATION_SEC) {
                    if (read_touch_data(&touch_data) == 0) {
                        int frequency = (touch_data & 0x0FFF) * 100 + 200;
                        play_tone(frequency);
                        log_frequency(frequency);
                    } else {
                        fprintf(stderr, "Failed to read touch data\n");
                        break;
                    }
                    gpioDelay(SAMPLE_INTERVAL_US);
                }
            } else {
                fprintf(stderr, "Authentication failed\n");
            }
        } else if (bytes_received < 0) {
            perror("Receive failed");
        }

        close(client_fd);
        client_fd = -1;
    }

    cleanup();
    return 0;
}

