/*
 * LSM303DLHC Magnetometer -> PWM LED on Raspberry Pi Zero W
 *
 * Wiring:
 *   LSM303DLHC SDA  -> Pi SDA1 (GPIO2, physical pin 3)
 *   LSM303DLHC SCL  -> Pi SCL1 (GPIO3, physical pin 5)
 *   LSM303DLHC VDD  -> 3.3 V
 *   LSM303DLHC GND  -> GND
 *   LED anode       -> GPIO17 (BCM 17, physical pin 11) via 330 Ω resistor
 *   LED cathode     -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o mag_led mag_led.c -lm
 *
 * LSM303DLHC magnetometer I2C addresses (7-bit):
 *   Magnetometer: 0x1E
 *   Accelerometer: 0x19  (not used here)
 *
 * Magnetometer data registers (auto-increment via 0x80 bit):
 *   0x03 - OUT_X_L_M (X low byte, auto-increment)
 *   0x04 - OUT_X_H_M (X high byte)
 *   0x05 - OUT_Y_L_M (Y low byte)
 *   0x06 - OUT_Y_H_M (Y high byte)
 *   0x07 - OUT_Z_L_M (Z low byte)
 *   0x08 - OUT_Z_H_M (Z high byte)
 *
 * PWM on GPIO17 is generated via the hardware PWM peripheral (BCM 18).
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

#include <pigpio.h>

/* ---- Configuration ---- */
#define I2C_BUS          "/dev/i2c-1"
#define LSM303_MAG_ADDR  0x1E

#define MAG_REG_OUT_X_L  0x03
#define MAG_REG_OUT_X_H  0x04
#define MAG_REG_OUT_Y_L  0x05
#define MAG_REG_OUT_Y_H  0x06
#define MAG_REG_OUT_Z_L  0x07
#define MAG_REG_OUT_Z_H  0x08

#define LED_GPIO         17
#define PWM_RANGE        1000
#define PWM_FREQ_HZ      1000   /* 1 kHz */
#define SAMPLE_PERIOD_US 100000 /* 100 ms */

#define LOG_FILE         "mag_led.log"

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd = -1;
static FILE    *g_log_fp = NULL;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- I2C helpers ---- */
static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, uint8_t len)
{
    if (fd < 0 || buf == NULL || len == 0)
        return -1;

    /* Write the register pointer (single byte) */
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }

    /* Read the data bytes */
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (uint8_t)n != len) {
        return -1;
    }
    return 0;
}

/* ---- Sensor read ---- */
static int read_magnetometer(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t buf[6];

    if (i2c_read_block(fd, MAG_REG_OUT_X_L | 0x80, buf, sizeof(buf)) != 0) {
        return -1;
    }

    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);
    return 0;
}

/* ---- LED control ---- */
static void set_led_brightness(int16_t z)
{
    /* Map Z magnitude to PWM duty cycle (0..PWM_RANGE) */
    int magnitude = abs(z);
    int duty = (magnitude * PWM_RANGE) / 32767; /* 16-bit signed max */

    if (duty > PWM_RANGE) duty = PWM_RANGE;
    if (duty < 0)         duty = 0;

    if (gpioPWM(LED_GPIO, duty) != 0) {
        fprintf(stderr, "Warning: gpioPWM failed on GPIO%d\n", LED_GPIO);
    }
}

/* ---- Logging ---- */
static void log_data(FILE *fp, int16_t x, int16_t y, int16_t z)
{
    if (fp == NULL) return;

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(fp, "[timestamp-error] Z=%d\n", z);
    } else {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, X=%d, Y=%d, Z=%d\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec,
                x, y, z);
    }
    fflush(fp);
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    /* Stop PWM and release GPIO */
    gpioPWM(LED_GPIO, 0);
    gpioTerminate();
}

/* ---- Main ---- */
int main(void)
{
    /* ---- Open log file ---- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        fclose(g_log_fp);
        g_log_fp = NULL;
        return EXIT_FAILURE;
    }

    /* ---- Configure LED GPIO for PWM ---- */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", LED_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioSetPWMrange(LED_GPIO, PWM_RANGE);
    gpioSetPWMfrequency(LED_GPIO, PWM_FREQ_HZ);
    gpioPWM(LED_GPIO, 0);

    /* ---- Open I2C bus ---- */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus '%s': %s\n",
                I2C_BUS, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Set slave address ---- */
    if (ioctl(g_i2c_fd, I2C_SLAVE, LSM303_MAG_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n",
                LSM303_MAG_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Verify sensor presence with a dummy read ---- */
    uint8_t dummy;
    if (i2c_read_block(g_i2c_fd, MAG_REG_OUT_X_L, &dummy, 1) != 0) {
        fprintf(stderr, "LSM303DLHC not detected at 0x%02X on %s\n",
                LSM303_MAG_ADDR, I2C_BUS);
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction failed: %s\n", strerror(errno));
    }

    printf("LSM303DLHC magnetometer reader started. Press Ctrl+C to exit.\n");
    printf("Logging to '%s'.\n", LOG_FILE);

    /* ---- Main loop ---- */
    while (g_running) {
        int16_t x, y, z;

        if (read_magnetometer(g_i2c_fd, &x, &y, &z) != 0) {
            fprintf(stderr, "I2C read error: %s\n", strerror(errno));
            fprintf(g_log_fp, "I2C read error: %s\n", strerror(errno));
            fflush(g_log_fp);
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        set_led_brightness(z);
        log_data(g_log_fp, x, y, z);

        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

