/*
 * HMC5883L hard-iron offset calibration and compensation.
 *
 * Board:  Raspberry Pi Zero W
 * Bus:    I2C bus 1 (GPIO2 = SDA, GPIO3 = SCL)
 * Address: 0x1E (HMC5883L default, SA0 tied to GND)
 *
 * Build:  gcc -O2 -Wall -Wextra -o hmc5883l_cal hmc5883l_cal.c -lpigpio -lrt
 * Run:    sudo ./hmc5883l_cal
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- HMC5883L constants ---- */
#define HMC5883L_ADDR        0x1E
#define REG_CONFIG_A         0x00
#define REG_CONFIG_B         0x01
#define REG_MODE             0x02
#define REG_DATA_X_MSB       0x03
#define REG_STATUS           0x09

#define CONFIG_A_8AVG_15HZ   0x70   /* 8-average, 15 Hz, normal measurement */
#define CONFIG_B_GAIN_1090  0x20   /* 1090 LSB/Gauss full-scale */
#define MODE_CONTINUOUS     0x00

#define SAMPLES_PER_AVERAGE 100
#define SAMPLE_PERIOD_US   500000  /* 500 ms */

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Low-level I2C helpers ---- */
static int reg_write(int handle, uint8_t reg, uint8_t val)
{
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0)
        fprintf(stderr, "[ERROR] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, val, rc);
    return rc;
}

static int reg_read(int handle, uint8_t reg)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0)
        fprintf(stderr, "[ERROR] i2cReadByteData(reg=0x%02X) failed: %d\n", reg, rc);
    return rc;
}

static int16_t combine_msb_lsb(int msb, int lsb)
{
    /* i2cReadByteData returns 0..255; bit 7 of the MSB byte is the sign bit. */
    int16_t val = (int16_t)((msb & 0x7F) << 8 | (uint8_t)lsb);
    if (msb & 0x80)
        val |= 0xF000;            /* sign-extend 16-bit */
    return val;
}

/* ---- Sensor initialization ---- */
static int init_hmc5883l(int handle)
{
    if (reg_write(handle, REG_CONFIG_A, CONFIG_A_8AVG_15HZ) < 0)
        return -1;
    if (reg_write(handle, REG_CONFIG_B, CONFIG_B_GAIN_1090) < 0)
        return -1;
    if (reg_write(handle, REG_MODE, MODE_CONTINUOUS) < 0)
        return -1;
    return 0;
}

/* ---- Read one 6-byte sample (X, Z, Y order) ---- */
static int read_magnetometer(int handle, int16_t *x, int16_t *y, int16_t *z)
{
    char buf[6];

    /* Set register pointer to 0x03 (DATA_X_MSB) so subsequent reads auto-increment. */
    if (i2cWriteByte(handle, REG_DATA_X_MSB) < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByte(DATA_X_MSB) failed\n");
        return -1;
    }

    int n = i2cReadDevice(handle, buf, 6);
    if (n != 6) {
        fprintf(stderr, "[ERROR] i2cReadDevice expected 6 bytes, got %d\n", n);
        return -1;
    }

    /* HMC5883L outputs X, Z, Y in that order. */
    *x = combine_msb_lsb((uint8_t)buf[0], (uint8_t)buf[1]);
    *z = combine_msb_lsb((uint8_t)buf[2], (uint8_t)buf[3]);
    *y = combine_msb_lsb((uint8_t)buf[4], (uint8_t)buf[5]);
    return 0;
}

/* ---- Running-average hard-iron compensation ---- */
static void compensate_hard_iron(int16_t *x, int16_t *y, int16_t *z,
                                 int16_t *ox, int16_t *oy, int16_t *oz,
                                 int count)
{
    if (count == 0) {
        *ox = *oy = *oz = 0;
        return;
    }
    int16_t sx = *ox, sy = *oy, sz = *oz;
    sx += *x; sy += *y; sz += *z;
    *ox = sx / count;
    *oy = sy / count;
    *oz = sz / count;
    *x -= *ox; *y -= *oy; *z -= *oz;
}

int main(void)
{
    /* ---- Signal handling ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] gpioInitialise failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus 1 at 0x1E ---- */
    g_i2c_handle = i2cOpen(1, HMC5883L_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=1, addr=0x%02X) failed: %d\n",
                HMC5883L_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Verify device presence ---- */
    int id = reg_read(g_i2c_handle, REG_CONFIG_A);
    if (id < 0) {
        fprintf(stderr, "[FATAL] HMC5883L not responding at 0x%02X\n", HMC5883L_ADDR);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Configure sensor ---- */
    if (init_hmc5883l(g_i2c_handle) < 0) {
        fprintf(stderr, "[FATAL] HMC5883L initialization failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- State ---- */
    int16_t offsets[3] = {0, 0, 0};
    int sample_count = 0;
    int64_t t_start = gpioTick();

    printf("HMC5883L running. Press Ctrl+C to stop.\n");

    while (g_running) {
        int16_t rx, ry, rz;

        if (read_magnetometer(g_i2c_handle, &rx, &ry, &rz) == 0) {
            compensate_hard_iron(&rx, &ry, &rz, &offsets[0], &offsets[1], &offsets[2],
                                 sample_count + 1);

            printf("X: %6d  Y: %6d  Z: %6d  |  Offsets: X=%6d Y=%6d Z=%6d\n",
                   rx, ry, rz, offsets[0], offsets[1], offsets[2]);
        } else {
            fprintf(stderr, "[WARN] Read failed; will retry next cycle.\n");
        }

        sample_count = (sample_count + 1) % SAMPLES_PER_AVERAGE;

        /* Sleep ~500 ms, but wake early if a signal arrives. */
        uint32_t elapsed = (gpioTick() - t_start) / 1000; /* ms */
        uint32_t remaining = SAMPLE_PERIOD_US / 1000;
        if (remaining > elapsed)
            gpioDelay((remaining - elapsed) * 1000); /* microseconds */
    }

    /* ---- Cleanup ---- */
    printf("\nShutting down...\n");
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

