/*
 * LSM303D accelerometer monitor for Raspberry Pi Zero W
 *
 * Wiring:
 *   LSM303D SDA  -> Pi GPIO2  (physical pin 3)
 *   LSM303D SCL  -> Pi GPIO3  (physical pin 5)
 *   LSM303D INT1 -> Pi GPIO23 (physical pin 16)
 *   LSM303D VDD  -> 3.3 V
 *   LSM303D GND  -> GND
 *
 * Build: gcc -O2 -Wall -Wextra -o lsm303d_mon lsm303d_mon.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

/* ---- LSM303D I2C addresses ---- */
#define LSM303D_ADDR_ACCEL 0x19
#define LSM303D_ADDR_MAG   0x1E

/* ---- LSM303D register addresses ---- */
#define LSM303D_WHO_AM_I      0x0F
#define LSM303D_CTRL_REG1_A   0x20
#define LSM303D_CTRL_REG4_A   0x23
#define LSM303D_CTRL_REG5_A   0x24
#define LSM303D_CTRL_REG6_A   0x25
#define LSM303D_CTRL_REG7_A   0x26
#define LSM303D_OUT_X_L_A     0x28
#define LSM303D_INT1_CFG      0x30
#define LSM303D_INT1_THS      0x32
#define LSM303D_INT1_DURATION 0x33

/* ---- Expected device ID ---- */
#define LSM303D_WHO_AM_I_VAL  0x49

/* ---- Sensitivity: 0.061 mg/LSB at +/-2 g ---- */
#define ACCEL_SENSITIVITY 0.061f

/* ---- Circular buffer ---- */
#define BUFFER_SIZE 64
#define DUMP_COUNT  10

typedef struct {
    int16_t x, y, z;
} accel_sample_t;

static accel_sample_t g_buffer[BUFFER_SIZE];
static int    g_head = 0;
static int    g_tail = 0;
static int    g_count = 0;

static volatile sig_atomic_t g_running = 1;

/* ---- I2C helpers ---- */
static int i2c_write_reg(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C burst read from 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- Circular buffer ---- */
static void buffer_push(accel_sample_t s) {
    g_buffer[g_head] = s;
    g_head = (g_head + 1) % BUFFER_SIZE;
    if (g_count == BUFFER_SIZE) {
        g_tail = (g_tail + 1) % BUFFER_SIZE;
    } else {
        g_count++;
    }
}

static void buffer_dump_last_n(int n) {
    if (g_count == 0) {
        printf("No samples in buffer yet.\n");
        return;
    }
    if (n > g_count) n = g_count;
    int start = (g_head - n + BUFFER_SIZE) % BUFFER_SIZE;
    printf("--- Last %d samples ---\n", n);
    for (int i = 0; i < n; i++) {
        int idx = (start + i) % BUFFER_SIZE;
        printf("  [%2d] X=%6d  Y=%6d  Z=%6d\n", i, g_buffer[idx].x, g_buffer[idx].y, g_buffer[idx].z);
    }
    printf("--- End of dump ---\n");
}

/* ---- Signal handler ---- */
static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* ---- Cleanup ---- */
static void cleanup(int i2c_fd, struct gpiod_line *int1_line) {
    if (i2c_fd >= 0) {
        /* Disable accelerometer: CTRL_REG1_A = 0x00 */
        (void)i2c_write_reg(i2c_fd, LSM303D_CTRL_REG1_A, 0x00);
        close(i2c_fd);
    }
    if (int1_line) {
        gpiod_line_release(int1_line);
    }
}

/* ---- Main ---- */
int main(void) {
    int i2c_fd = -1;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *int1_line = NULL;
    int ret = EXIT_FAILURE;

    /* Open I2C bus 1 (GPIO2/3 on Pi Zero W) */
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open /dev/i2c-1: %s\n", strerror(errno));
        goto out;
    }

    /* Verify device identity */
    uint8_t whoami = 0;
    if (i2c_read_reg(i2c_fd, LSM303D_WHO_AM_I, &whoami) < 0) {
        fprintf(stderr, "Cannot read WHO_AM_I register.\n");
        goto out;
    }
    if (whoami != LSM303D_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                whoami, LSM303D_WHO_AM_I_VAL);
        goto out;
    }
    printf("LSM303D detected (WHO_AM_I = 0x%02X).\n", whoami);

    /* Configure accelerometer: 100 Hz, +/-2 g, continuous update */
    if (i2c_write_reg(i2c_fd, LSM303D_CTRL_REG1_A, 0x27) < 0) goto out;
    /* CTRL_REG4_A: Z-axis enabled, +/-2 g */
    if (i2c_write_reg(i2c_fd, LSM303D_CTRL_REG4_A, 0x08) < 0) goto out;
    /* CTRL_REG5_A: INT1 on INT1 pin (default) */
    if (i2c_write_reg(i2c_fd, LSM303D_CTRL_REG5_A, 0x00) < 0) goto out;
    /* CTRL_REG6_A: no FIFO, no boot */
    if (i2c_write_reg(i2c_fd, LSM303D_CTRL_REG6_A, 0x00) < 0) goto out;
    /* CTRL_REG7_A: no high-resolution mode */
    if (i2c_write_reg(i2c_fd, LSM303D_CTRL_REG7_A, 0x00) < 0) goto out;

    /* Configure interrupt: threshold = 2000 mg (2000 * 0.061 = 122 mg), duration = 0 */
    uint8_t ths = (uint8_t)(2000.0f / ACCEL_SENSITIVITY);
    if (ths > 0x7F) ths = 0x7F;
    if (i2c_write_reg(i2c_fd, LSM303D_INT1_THS, ths) < 0) goto out;
    if (i2c_write_reg(i2c_fd, LSM303D_INT1_DURATION, 0x00) < 0) goto out;
    /* INT1_CFG: threshold comparison, no latching, active high, push-pull */
    if (i2c_write_reg(i2c_fd, LSM303D_INT1_CFG, 0x04) < 0) goto out;

    /* Open GPIO chip and request INT1 line */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        goto out;
    }
    int1_line = gpiod_chip_get_line(chip, 23);
    if (!int1_line) {
        fprintf(stderr, "Failed to get GPIO line 23: %s\n", strerror(errno));
        goto out;
    }
    if (gpiod_line_request_rising_edge_events(int1_line, "lsm303d_mon") < 0) {
        fprintf(stderr, "Failed to request rising-edge events on GPIO 23: %s\n", strerror(errno));
        goto out;
    }

    /* Install signal handler */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        goto out;
    }

    printf("Monitoring accelerometer on INT1 (GPIO23). Press Ctrl-C to exit.\n");

    /* Main loop */
    while (g_running) {
        /* Poll for interrupt events */
        struct timespec ts = { 0, 10000000 }; /* 10 ms */
        int ev = gpiod_line_event_wait(int1_line, &ts);
        if (ev < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "GPIO event wait error: %s\n", strerror(errno));
            break;
        }
        if (ev == 0) {
            /* Timeout, no event — read one sample */
            uint8_t raw[6];
            if (i2c_read_burst(i2c_fd, LSM303D_OUT_X_L_A | 0x80, raw, 6) < 0) {
                fprintf(stderr, "Warning: I2C read failed, skipping sample.\n");
                continue;
            }
            int16_t x = (int16_t)((raw[1] << 8) | raw[0]);
            int16_t y = (int16_t)((raw[3] << 8) | raw[2]);
            int16_t z = (int16_t)((raw[5] << 8) | raw[4]);
            accel_sample_t s = { x, y, z };
            buffer_push(s);
        } else {
            /* Event detected — dump last 10 samples */
            buffer_dump_last_n(DUMP_COUNT);
        }
    }

    ret = EXIT_SUCCESS;

out:
    cleanup(i2c_fd, int1_line);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

