#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SOLENOID_1_PIN 17
#define SOLENOID_2_PIN 27
#define DELAY_MS 500

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int set_line(int pin, int level) {
    if (gpioWrite(pin, level) < 0) {
        fprintf(stderr, "Error: gpioWrite(pin=%d, level=%d) failed\n", pin, level);
        return -1;
    }
    return 0;
}

static int delay_ms(int ms) {
    struct timespec req = {
        .tv_sec  = ms / 1000,
        .tv_nsec = (long)(ms % 1000) * 1000000L
    };
    struct timespec rem;
    while (nanosleep(&req, &rem) < 0) {
        if (g_running == 0) return -1;
        req = rem;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SOLENOID_1_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_OUTPUT) failed\n", SOLENOID_1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SOLENOID_2_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_OUTPUT) failed\n", SOLENOID_2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure both solenoids are de-energized at startup */
    if (set_line(SOLENOID_1_PIN, 0) < 0 || set_line(SOLENOID_2_PIN, 0) < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int active_pin = SOLENOID_1_PIN;
    int inactive_pin = SOLENOID_2_PIN;

    while (g_running) {
        if (set_line(active_pin, 1) < 0) break;
        if (delay_ms(DELAY_MS) < 0) break;
        if (set_line(active_pin, 0) < 0) break;
        if (delay_ms(DELAY_MS) < 0) break;

        /* Swap roles */
        int tmp = active_pin;
        active_pin = inactive_pin;
        inactive_pin = tmp;
    }

    /* Clean shutdown: de-energize both solenoids */
    set_line(SOLENOID_1_PIN, 0);
    set_line(SOLENOID_2_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

