#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define LOCK1_GPIO 17
#define LOCK2_GPIO 27
#define EXPECTED_CODE "123456"
#define CODE_LENGTH 6
#define READ_TIMEOUT_SEC 5
#define LOCK_DURATION_SEC 2

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int init_uart(const char *port) {
    int fd = open(port, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", port, strerror(errno));
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "tcgetattr failed on %s: %s\n", port, strerror(errno));
        close(fd);
        return -1;
    }

    cfsetispeed(&tty, B9600);
    cfsetospeed(&tty, B9600);

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_cflag &= ~(PARENB | PARODD);
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;
    tty.c_cflag |= CREAD | CLOCAL;

    tty.c_lflag &= ~(ICANON | ECHO | ECHOE | ECHONL | ISIG);
    tty.c_iflag &= ~(IXON | IXOFF | IXANY | IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL);
    tty.c_oflag &= ~OPOST;

    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = READ_TIMEOUT_SEC;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "tcsetattr failed on %s: %s\n", port, strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

static int read_code(int fd, char *code, size_t len) {
    size_t idx = 0;
    char ch;

    while (g_running && idx < len - 1) {
        ssize_t n = read(fd, &ch, 1);
        if (n < 0) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                continue;
            }
            fprintf(stderr, "Error reading from UART: %s\n", strerror(errno));
            return -1;
        } else if (n == 0) {
            return 0;
        }

        if (ch >= '0' && ch <= '9') {
            code[idx++] = ch;
        } else {
            if (idx > 0) {
                idx = 0;
            }
        }
        if (idx == len - 1) {
            code[idx] = '\0';
            return 1;
        }
    }
    return 0;
}

static int verify_code(const char *code) {
    return strncmp(code, EXPECTED_CODE, CODE_LENGTH) == 0;
}

static int set_lock(int gpio, int state) {
    if (gpioWrite(gpio, state) != 0) {
        fprintf(stderr, "Error writing GPIO %d: %s\n", gpio, pigpio_error(gpioWrite(gpio, state)));
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    set_lock(LOCK1_GPIO, 0);
    set_lock(LOCK2_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    int fd1 = -1, fd2 = -1;
    char code1[CODE_LENGTH + 1] = {0};
    char code2[CODE_LENGTH + 1] = {0};
    int got1 = 0, got2 = 0;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error installing signal handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(LOCK1_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", LOCK1_GPIO);
        cleanup();
        return 1;
    }
    if (gpioSetMode(LOCK2_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", LOCK2_GPIO);
        cleanup();
        return 1;
    }

    if (set_lock(LOCK1_GPIO, 0) != 0 || set_lock(LOCK2_GPIO, 0) != 0) {
        cleanup();
        return 1;
    }

    fd1 = init_uart("/dev/serial0");
    if (fd1 < 0) {
        cleanup();
        return 1;
    }

    fd2 = init_uart("/dev/serial1");
    if (fd2 < 0) {
        close(fd1);
        cleanup();
        return 1;
    }

    printf("Door lock system started. Waiting for codes...\n");

    while (g_running) {
        if (!got1) {
            int r = read_code(fd1, code1, sizeof(code1));
            if (r < 0) {
                break;
            } else if (r == 1) {
                got1 = 1;
                printf("Received code from port 1: %s\n", code1);
            }
        }

        if (!got2) {
            int r = read_code(fd2, code2, sizeof(code2));
            if (r < 0) {
                break;
            } else if (r == 1) {
                got2 = 1;
                printf("Received code from port 2: %s\n", code2);
            }
        }

        if (got1 && got2) {
            if (verify_code(code1) && verify_code(code2)) {
                printf("Codes match. Unlocking doors...\n");
                if (set_lock(LOCK1_GPIO, 1) == 0 && set_lock(LOCK2_GPIO, 1) == 0) {
                    sleep(LOCK_DURATION_SEC);
                    set_lock(LOCK1_GPIO, 0);
                    set_lock(LOCK2_GPIO, 0);
                }
            } else {
                fprintf(stderr, "Codes do not match!\n");
            }
            got1 = 0;
            got2 = 0;
            code1[0] = '\0';
            code2[0] = '\0';
        }
    }

    if (fd1 >= 0) close(fd1);
    if (fd2 >= 0) close(fd2);
    cleanup();
    printf("Door lock system stopped.\n");
    return 0;
}

