/*
 * Raspberry Pi 4 Model B – PIR motion detector with relay strike.
 *
 * Hardware:
 *   - HC-SR501 PIR sensor  -> GPIO4  (physical pin 7)
 *   - Relay strike control -> GPIO17 (physical pin 11)
 *
 * Behavior:
 *   - Polls the PIR every 50 ms.
 *   - On rising edge (PIR HIGH) the relay is energized for 1 s, then de-energized.
 *   - If the PIR signal stays HIGH for more than 10 s, a failsafe triggers:
 *       * relay de-energized
 *       * syslog warning + shutdown event
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o pir_strike pir_strike.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <syslog.h>
#include <gpiod.h>

#define PIR_LINE_OFFSET   4
#define RELAY_LINE_OFFSET 17
#define POLL_INTERVAL_MS  50
#define RELAY_PULSE_MS    1000
#define FAILSAFE_TIMEOUT  10   /* seconds */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0)
        syslog(LOG_WARNING, "sigaction(SIGINT) failed: %s", strerror(errno));
    if (sigaction(SIGTERM, &sa, NULL) != 0)
        syslog(LOG_WARNING, "sigaction(SIGTERM) failed: %s", strerror(errno));
}

static void log_event(int priority, const char *message)
{
    syslog(priority, "%s", message);
}

static void log_event_with_timestamp(int priority, const char *message)
{
    char ts[32];
    time_t now = time(NULL);
    struct tm tmv;

    if (localtime_r(&now, &tmv) != NULL) {
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tmv);
    } else {
        snprintf(ts, sizeof(ts), "unknown-time");
    }
    syslog(priority, "%s: %s", ts, message);
}

static void activate_relay(struct gpiod_line *relay_line)
{
    if (gpiod_line_set_value(relay_line, 1) < 0) {
        syslog(LOG_ERR, "Failed to energize relay: %s", strerror(errno));
        return;
    }
    log_event(LOG_INFO, "Relay energized (strike activated).");

    /* Pulse for 1 s, checking for shutdown signal every 100 ms. */
    for (int elapsed = 0; elapsed < RELAY_PULSE_MS && g_running; elapsed += 100) {
        usleep(100 * 1000);
    }

    if (gpiod_line_set_value(relay_line, 0) < 0) {
        syslog(LOG_ERR, "Failed to de-energize relay: %s", strerror(errno));
        return;
    }
    log_event(LOG_INFO, "Relay de-energized (strike deactivated).");
}

int main(void)
{
    openlog("pir_strike", LOG_PID | LOG_CONS, LOG_USER);
    install_signal_handlers();

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
    if (chip == NULL) {
        syslog(LOG_ERR, "Failed to open gpiochip4: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    struct gpiod_line *pir_line = gpiod_chip_get_line(chip, PIR_LINE_OFFSET);
    if (pir_line == NULL) {
        syslog(LOG_ERR, "Failed to get PIR line (offset %d): %s",
               PIR_LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    struct gpiod_line *relay_line = gpiod_chip_get_line(chip, RELAY_LINE_OFFSET);
    if (relay_line == NULL) {
        syslog(LOG_ERR, "Failed to get relay line (offset %d): %s",
               RELAY_LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(pir_line, "pir_strike") < 0) {
        syslog(LOG_ERR, "Failed to request PIR line as input: %s", strerror(errno));
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(relay_line, "pir_strike", 0) < 0) {
        syslog(LOG_ERR, "Failed to request relay line as output: %s", strerror(errno));
        gpiod_line_release(pir_line);
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    log_event(LOG_INFO, "PIR strike monitor started.");

    int last_pir_state = 0;
    time_t motion_start = 0;
    int relay_active = 0;

    while (g_running) {
        int pir_value = gpiod_line_get_value(pir_line);
        if (pir_value < 0) {
            syslog(LOG_ERR, "Failed to read PIR sensor: %s", strerror(errno));
            usleep(POLL_INTERVAL_MS * 1000);
            continue;
        }

        if (pir_value == 1 && last_pir_state == 0) {
            /* Rising edge – motion detected. */
            log_event(LOG_INFO, "Motion detected (PIR HIGH).");
            if (!relay_active) {
                activate_relay(relay_line);
                relay_active = 1;
            }
            motion_start = time(NULL);
        } else if (pir_value == 1 && last_pir_state == 1) {
            /* Motion still active – update failsafe timer. */
            if (motion_start != 0 &&
                difftime(time(NULL), motion_start) > FAILSAFE_TIMEOUT) {
                log_event(LOG_WARNING,
                          "PIR signal stuck HIGH for >10 s – triggering failsafe.");
                if (gpiod_line_set_value(relay_line, 0) < 0) {
                    syslog(LOG_ERR, "Failed to de-energize relay during failsafe: %s",
                           strerror(errno));
                } else {
                    log_event(LOG_INFO, "Relay de-energized during failsafe.");
                }
                log_event(LOG_WARNING, "Shutdown event logged.");
                log_event(LOG_INFO, "PIR strike monitor shutting down.");
                g_running = 0;
                break;
            }
        } else if (pir_value == 0 && last_pir_state == 1) {
            /* Motion ended. */
            log_event(LOG_INFO, "Motion ended (PIR LOW).");
            if (motion_start != 0) {
                double duration = difftime(time(NULL), motion_start);
                char msg[128];
                snprintf(msg, sizeof(msg),
                         "Motion duration: %.0f seconds", duration);
                log_event(LOG_INFO, msg);
            }
            motion_start = 0;
        }

        last_pir_state = pir_value;
        usleep(POLL_INTERVAL_MS * 1000);
    }

    /* Clean shutdown: ensure relay is LOW, release lines, close chip. */
    if (gpiod_line_set_value(relay_line, 0) < 0) {
        syslog(LOG_ERR, "Failed to set relay LOW on exit: %s", strerror(errno));
    }
    gpiod_line_release(pir_line);
    gpiod_line_release(relay_line);
    gpiod_chip_close(chip);
    log_event(LOG_INFO, "PIR strike monitor stopped.");
    closelog();
    return EXIT_SUCCESS;
}

