#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>

#define RELAY1_GPIO 4
#define RELAY2_GPIO 17
#define RELAY3_GPIO 27
#define RELAY4_GPIO 22

#define RELAY_ON_DURATION 300
#define PAUSE_DURATION 60
#define TIMER_INTERVAL 60

#define NUM_RELAYS 4

static const int relay_gpios[NUM_RELAYS] = {
    RELAY1_GPIO, RELAY2_GPIO, RELAY3_GPIO, RELAY4_GPIO
};

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void log_message(int priority, const char *message) {
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char timestamp[32];
    if (t != NULL) {
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    } else {
        snprintf(timestamp, sizeof(timestamp), "unknown-time");
    }
    syslog(priority, "%s: %s", timestamp, message);
}

static int set_relay(int gpio, int state) {
    if (gpioWrite(gpio, state) != 0) {
        char msg[128];
        snprintf(msg, sizeof(msg), "gpioWrite failed for GPIO %d (state=%d)", gpio, state);
        log_message(LOG_ERR, msg);
        return -1;
    }
    return 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpioSetMode(relay_gpios[i], PI_OUTPUT) != 0) {
            char msg[128];
            snprintf(msg, sizeof(msg), "gpioSetMode failed for GPIO %d", relay_gpios[i]);
            log_message(LOG_ERR, msg);
            gpioTerminate();
            return -1;
        }
        if (set_relay(relay_gpios[i], 1) != 0) {
            gpioTerminate();
            return -1;
        }
    }
    return 0;
}

static void cleanup_gpio(void) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        set_relay(relay_gpios[i], 1);
    }
    gpioTerminate();
}

static void timer_callback(void *user_data) {
    (void)user_data;
    static int current_relay = 0;
    static int phase = 0; /* 0 = on, 1 = pause */

    if (phase == 0) {
        if (set_relay(relay_gpios[current_relay], 0) != 0) {
            log_message(LOG_ERR, "Failed to activate relay");
            return;
        }
        char msg[128];
        snprintf(msg, sizeof(msg), "Relay %d activated for %d seconds", current_relay + 1, RELAY_ON_DURATION);
        log_message(LOG_INFO, msg);
        phase = 1;
    } else {
        if (set_relay(relay_gpios[current_relay], 1) != 0) {
            log_message(LOG_ERR, "Failed to deactivate relay");
            return;
        }
        char msg[128];
        snprintf(msg, sizeof(msg), "Relay %d deactivated", current_relay + 1);
        log_message(LOG_INFO, msg);
        current_relay = (current_relay + 1) % NUM_RELAYS;
        if (current_relay == 0) {
            log_message(LOG_INFO, "Irrigation cycle completed");
        }
        phase = 0;
    }
}

int main(void) {
    openlog("irrigation_system", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        log_message(LOG_ERR, "Failed to register SIGINT handler");
        closelog();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        log_message(LOG_ERR, "Failed to register SIGTERM handler");
        closelog();
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        log_message(LOG_ERR, "GPIO initialization failed, exiting");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetTimerFuncEx(0, TIMER_INTERVAL * 1000, timer_callback, NULL) != 0) {
        log_message(LOG_ERR, "Failed to set timer");
        cleanup_gpio();
        closelog();
        return EXIT_FAILURE;
    }

    log_message(LOG_INFO, "Irrigation system started");

    while (g_running) {
        sleep(1);
    }

    log_message(LOG_INFO, "Shutting down irrigation system");
    cleanup_gpio();
    closelog();
    return EXIT_SUCCESS;
}

