#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define MPU6050_ADDR 0x68
#define REG_PWR_MGMT_1 0x6B
#define REG_ACCEL_XOUT_H 0x3B
#define REG_ACCEL_XOUT_L 0x3C
#define REG_ACCEL_YOUT_H 0x3D
#define REG_ACCEL_YOUT_L 0x3E
#define REG_ACCEL_ZOUT_H 0x3F
#define REG_ACCEL_ZOUT_L 0x40

#define BUFFER_SIZE 100
#define TIMER_INTERVAL_MS 10

typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} accel_data_t;

typedef struct {
    accel_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

static int i2c_fd = -1;
static circular_buffer_t accel_buffer;
static volatile sig_atomic_t timer_fired = 0;
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write error (reg 0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write reg error (reg 0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read error (reg 0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_mpu6050(int fd) {
    if (i2c_write_byte(fd, REG_PWR_MGMT_1, 0x00) == -1) {
        return -1;
    }
    usleep(100000);
    return 0;
}

static int read_accel_data(int fd, accel_data_t *data) {
    uint8_t buf[6];
    if (i2c_read_bytes(fd, REG_ACCEL_XOUT_H, buf, 6) == -1) {
        return -1;
    }
    data->x = (int16_t)((buf[0] << 8) | buf[1]);
    data->y = (int16_t)((buf[2] << 8) | buf[3]);
    data->z = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

static void timer_handler(int signum) {
    (void)signum;
    timer_fired = 1;
}

static int setup_timer(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = timer_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGALRM, &sa, NULL) == -1) {
        perror("sigaction");
        return -1;
    }

    struct sigevent sev;
    memset(&sev, 0, sizeof(sev));
    sev.sigev_notify = SIGEV_SIGNAL;
    sev.sigev_signo = SIGALRM;

    timer_t timerid;
    if (timer_create(CLOCK_MONOTONIC, &sev, &timerid) == -1) {
        perror("timer_create");
        return -1;
    }

    struct itimerspec its;
    its.it_interval.tv_sec = 0;
    its.it_interval.tv_nsec = TIMER_INTERVAL_MS * 1000000L;
    its.it_value = its.it_interval;

    if (timer_settime(timerid, 0, &its, NULL) == -1) {
        perror("timer_settime");
        timer_delete(timerid);
        return -1;
    }

    return 0;
}

static int write_latest_file(const char *filename, const accel_data_t *data) {
    FILE *fp = fopen(filename, "w");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", filename, strerror(errno));
        return -1;
    }
    fprintf(fp, "%d,%d,%d\n", data->x, data->y, data->z);
    fclose(fp);
    return 0;
}

static void cleanup(void) {
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    unlink("/sys/kernel/mpu6050_accel/latest");
}

int main(void) {
    if (setup_timer() == -1) {
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd == -1) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) == -1) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        cleanup();
        return 1;
    }

    if (init_mpu6050(i2c_fd) == -1) {
        fprintf(stderr, "Error initializing MPU6050\n");
        cleanup();
        return 1;
    }

    if (symlink("/sys/kernel/mpu6050_accel/latest", "/sys/kernel/mpu6050_accel/latest") == -1) {
        fprintf(stderr, "Error creating symlink: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        cleanup();
        return 1;
    }

    memset(&accel_buffer, 0, sizeof(accel_buffer));

    while (program_running) {
        if (timer_fired) {
            timer_fired = 0;
            accel_data_t data;
            if (read_accel_data(i2c_fd, &data) == 0) {
                accel_buffer.data[accel_buffer.head] = data;
                accel_buffer.head = (accel_buffer.head + 1) % BUFFER_SIZE;
                if (accel_buffer.count < BUFFER_SIZE) {
                    accel_buffer.count++;
                }
                write_latest_file("/sys/kernel/mpu6050_accel/latest", &data);
            } else {
                fprintf(stderr, "Error reading acceleration data\n");
            }
        }
        usleep(10000);
    }

    cleanup();
    return 0;
}

