#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <pigpio.h>

#define RELAY1_PIN 18
#define RELAY2_PIN 23
#define RELAY3_PIN 24
#define RELAY4_PIN 25

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_relay(int pin, int state) {
    if (gpioWrite(pin, state) < 0) {
        fprintf(stderr, "Error writing to GPIO %d: %s\n", pin, strerror(errno));
        return -1;
    }
    return 0;
}

static int toggle_relay(int pin) {
    int current = gpioRead(pin);
    if (current < 0) {
        fprintf(stderr, "Error reading GPIO %d: %s\n", pin, strerror(errno));
        return -1;
    }
    if (set_relay(pin, current ? 0 : 1) < 0) {
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        if (gpioSetMode(pins[i], PI_OUTPUT) < 0) {
            fprintf(stderr, "Error setting GPIO %d as output: %s\n", pins[i], strerror(errno));
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (set_relay(pins[i], 0) < 0) {
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    const int intervals[] = {2, 3, 5, 7};
    const size_t num_relays = sizeof(intervals) / sizeof(intervals[0]);
    struct timespec next_time[num_relays];
    struct timespec now;

    for (size_t i = 0; i < num_relays; ++i) {
        clock_gettime(CLOCK_MONOTONIC, &next_time[i]);
        next_time[i].tv_sec += intervals[i];
    }

    while (running) {
        clock_gettime(CLOCK_MONOTONIC, &now);

        for (size_t i = 0; i < num_relays; ++i) {
            if (now.tv_sec > next_time[i].tv_sec ||
                (now.tv_sec == next_time[i].tv_sec && now.tv_nsec >= next_time[i].tv_nsec)) {
                if (toggle_relay(pins[i]) < 0) {
                    fprintf(stderr, "Error toggling relay %zu\n", i + 1);
                }
                next_time[i].tv_sec += intervals[i];
            }
        }

        struct timespec sleep_time = {0, 100000000}; /* 100 ms */
        nanosleep(&sleep_time, NULL);
    }

    for (size_t i = 0; i < num_relays; ++i) {
        set_relay(pins[i], 0);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

