#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define GYRO_XOUT_H 0x43
#define GYRO_YOUT_H 0x45
#define GYRO_ZOUT_H 0x47
#define SAMPLE_RATE 100
#define BUFFER_SIZE 100
#define THRESHOLD 50.0

typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

typedef struct {
    gyro_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int init_mpu6050(int fd) {
    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Error: Failed to acquire I2C bus access: %s\n", strerror(errno));
        return -1;
    }
    uint8_t buf[2] = {PWR_MGMT_1, 0x00};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to write to PWR_MGMT_1: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int read_gyro_data(int fd, gyro_data_t *data) {
    uint8_t reg = GYRO_XOUT_H;
    uint8_t buf[6];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error: Failed to write register address: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, buf, 6) != 6) {
        fprintf(stderr, "Error: Failed to read gyro data: %s\n", strerror(errno));
        return -1;
    }
    int16_t x = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t y = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t z = (int16_t)((buf[4] << 8) | buf[5]);
    data->x = (float)x / 131.0;
    data->y = (float)y / 131.0;
    data->z = (float)z / 131.0;
    return 0;
}

void add_to_buffer(circular_buffer_t *buffer, gyro_data_t data) {
    buffer->data[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

bool check_threshold(gyro_data_t data) {
    float magnitude = sqrt(data.x * data.x + data.y * data.y + data.z * data.z);
    return magnitude > THRESHOLD;
}

void callback(gyro_data_t data) {
    printf("Threshold exceeded! X: %.2f, Y: %.2f, Z: %.2f\n", data.x, data.y, data.z);
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error: Failed to open /dev/i2c-1: %s\n", strerror(errno));
        return 1;
    }

    if (init_mpu6050(i2c_fd) < 0) {
        close(i2c_fd);
        return 1;
    }

    circular_buffer_t buffer = {0};
    gyro_data_t gyro_data;

    while (running) {
        if (read_gyro_data(i2c_fd, &gyro_data) == 0) {
            add_to_buffer(&buffer, gyro_data);
            if (check_threshold(gyro_data)) {
                callback(gyro_data);
            }
        } else {
            fprintf(stderr, "Error reading gyro data, retrying...\n");
        }
        usleep(1000000 / SAMPLE_RATE);
    }

    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    printf("\nExiting gracefully.\n");
    return 0;
}

