/*
 * co2_monitor.c — MH-Z19B CO2 monitor for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   MH-Z19B TX  -> Pi GPIO15 (RXD, pin 10)
 *   MH-Z19B RX  -> Pi GPIO14 (TXD, pin  8)
 *   MH-Z19B VCC -> 5 V (pin 2 or 4)
 *   MH-Z19B GND -> GND (pin 6)
 *
 * Build:
 *   gcc -Wall -Wextra -O2 -o co2_monitor co2_monitor.c -lthe_driver_library -lrt
 *
 * Run:
 *   ./co2_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <termios.h>
#include <sys/time.h>

#include "the_driver_library.h" /* Replace with the actual driver header */

#define UART_DEVICE      "/dev/serial0"
#define BAUD_RATE        B9600
#define LOG_FILE         "co2_log.json"
#define ERROR_LOG_FILE   "co2_error.log"
#define SAMPLE_INTERVAL  5          /* seconds between readings */
#define RESPONSE_BYTES   9          /* MH-Z19B full response length */
#define READ_TIMEOUT_MS  1000       /* total timeout for a full response */
#define POLL_DELAY_MS    10         /* poll interval while waiting for data */
#define MAX_RETRIES      3          /* retries per partial read */

/* MH-Z19B documented command: 0xFE 0x44 0x00 0x08 0x00 0x00 0x00 0x00 0x79 */
static const uint8_t MHZ19B_CMD[RESPONSE_BYTES] = {
    0xFE, 0x44, 0x00, 0x08, 0x00, 0x00, 0x00, 0x00, 0x79
};

static volatile sig_atomic_t g_running = 1;
static int  g_uart_fd = -1;
static FILE *g_log_fp  = NULL;
static FILE *g_err_fp  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                    */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    struct timeval tv;
    struct tm tm_info;

    if (gettimeofday(&tv, NULL) != 0) {
        snprintf(buf, len, "1970-01-01T00:00:00.000000");
        return;
    }
    localtime_r(&tv.tv_sec, &tm_info);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tm_info);
    snprintf(buf + strlen(buf),
             len - strlen(buf),
             ".%06ld", (long)tv.tv_usec);
}

/* ------------------------------------------------------------------ */
/* Error logging                                                       */
/* ------------------------------------------------------------------ */
static void log_error(const char *msg)
{
    char ts[40];
    get_timestamp(ts, sizeof(ts));

    if (g_err_fp) {
        fprintf(g_err_fp, "%s: %s\n", ts, msg);
        fflush(g_err_fp);
    }
    fprintf(stderr, "%s: %s\n", ts, msg);
}

/* ------------------------------------------------------------------ */
/* UART setup                                                          */
/* ------------------------------------------------------------------ */
static int setup_uart(const char *device)
{
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd < 0) {
        perror("open UART");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("tcgetattr");
        close(fd);
        return -1;
    }

    cfsetispeed(&tty, BAUD_RATE);
    cfsetospeed(&tty, BAUD_RATE);

    tty.c_cflag  = (tty.c_cflag & ~CSIZE) | CS8;   /* 8 data bits */
    tty.c_cflag |= (CLOCAL | CREAD);               /* enable receiver */
    tty.c_cflag &= ~(PARENB | PARODD);             /* no parity */
    tty.c_cflag &= ~CSTOPB;                        /* 1 stop bit */
    tty.c_cflag &= ~CRTSCTS;                       /* no hardware flow */

    tty.c_iflag  = 0;                              /* raw input */
    tty.c_oflag  = 0;                              /* raw output */
    tty.c_lflag  = 0;                              /* non-canonical */

    tty.c_cc[VMIN]  = 0;                           /* non-blocking */
    tty.c_cc[VTIME] = 1;                           /* 100 ms inter-byte timeout */

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("tcsetattr");
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

/* ------------------------------------------------------------------ */
/* Send MH-Z19B command                                               */
/* ------------------------------------------------------------------ */
static int send_command(int fd)
{
    ssize_t n = write(fd, MHZ19B_CMD, RESPONSE_BYTES);
    if (n < 0) {
        perror("write command");
        return -1;
    }
    if (n != RESPONSE_BYTES) {
        fprintf(stderr, "Short write: %zd of %zu bytes\n", n, RESPONSE_BYTES);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read exactly RESPONSE_BYTES bytes with timeout                     */
/* ------------------------------------------------------------------ */
static int read_response(int fd, uint8_t *buf, size_t len)
{
    size_t total = 0;
    int elapsed = 0;

    while (total < len && elapsed < READ_TIMEOUT_MS) {
        ssize_t n = read(fd, buf + total, len - total);
        if (n < 0) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                usleep(POLL_DELAY_MS * 1000);
                elapsed += POLL_DELAY_MS;
                continue;
            }
            perror("read response");
            return -1;
        }
        if (n == 0) {
            usleep(POLL_DELAY_MS * 1000);
            elapsed += POLL_DELAY_MS;
            continue;
        }
        total += (size_t)n;
    }

    if (total != len) {
        fprintf(stderr, "Timeout: got %zu of %zu bytes after %d ms\n",
                total, len, elapsed);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Parse and validate response                                        */
/* ------------------------------------------------------------------ */
static int parse_response(const uint8_t *buf, uint16_t *co2_ppm)
{
    if (buf[0] != 0xFE) {
        fprintf(stderr, "Invalid start byte: 0x%02X\n", buf[0]);
        return -1;
    }

    uint8_t checksum = 0;
    for (int i = 1; i < RESPONSE_BYTES - 1; i++)
        checksum += buf[i];

    if (checksum != buf[RESPONSE_BYTES - 1]) {
        fprintf(stderr, "Checksum mismatch: calc=0x%02X recv=0x%02X\n",
                checksum, buf[RESPONSE_BYTES - 1]);
        return -1;
    }

    *co2_ppm = ((uint16_t)buf[2] << 8) | buf[3];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Log one reading as JSON                                            */
/* ------------------------------------------------------------------ */
static void log_co2(uint16_t co2_ppm)
{
    char ts[40];
    get_timestamp(ts, sizeof(ts));

    fprintf(g_log_fp,
            "{\"timestamp\":\"%s\",\"co2_ppm\":%u,\"error\":0}\n",
            ts, co2_ppm);
    fflush(g_log_fp);
    printf("{\"timestamp\":\"%s\",\"co2_ppm\":%u,\"error\":0}\n",
           ts, co2_ppm);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                            */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_uart_fd >= 0) {
        close(g_uart_fd);
        g_uart_fd = -1;
    }
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_err_fp) {
        fclose(g_err_fp);
        g_err_fp = NULL;
    }
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction SIGINT");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction SIGTERM");
        return EXIT_FAILURE;
    }

    g_uart_fd = setup_uart(UART_DEVICE);
    if (g_uart_fd < 0) {
        log_error("UART setup failed");
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("fopen log");
        cleanup();
        return EXIT_FAILURE;
    }

    g_err_fp = fopen(ERROR_LOG_FILE, "a");
    if (!g_err_fp) {
        perror("fopen error log");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MH-Z19B CO2 monitor started. UART=%s  Baud=9600  "
           "Log=%s  ErrorLog=%s\n",
           UART_DEVICE, LOG_FILE, ERROR_LOG_FILE);

    while (g_running) {
        if (send_command(g_uart_fd) != 0) {
            log_error("Failed to send command");
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        uint8_t buf[RESPONSE_BYTES];
        int got_full = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (read_response(g_uart_fd, buf, RESPONSE_BYTES) == 0) {
                got_full = 1;
                break;
            }
            usleep(100000); /* 100 ms backoff */
        }

        if (!got_full) {
            log_error("Failed to read full response after retries");
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        uint16_t co2_ppm = 0;
        if (parse_response(buf, &co2_ppm) == 0) {
            log_co2(co2_ppm);
        } else {
            log_error("Failed to parse response");
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int s = 0; s < SAMPLE_INTERVAL && g_running; s++)
            sleep(1);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

