#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

#define HMC5883L_ADDR 0x1E
#define HMC5883L_CONFIG_REG_A 0x00
#define HMC5883L_CONFIG_REG_B 0x01
#define HMC5883L_MODE_REG 0x02
#define HMC5883L_DATA_X_MSB 0x03
#define HMC5883L_DATA_Z_MSB 0x05
#define HMC5883L_DATA_Y_MSB 0x07

#define HARD_IRON_X_OFFSET 100.0
#define HARD_IRON_Y_OFFSET -50.0
#define TARGET_HEADING 90.0
#define HEADING_THRESHOLD 10.0
#define BUFFER_SIZE 100
#define GPIO_PIN 17
#define SAMPLE_INTERVAL_US 100000

typedef struct {
    float x;
    float y;
    float z;
} magnetometer_data_t;

typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static circular_buffer_t heading_buffer;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void init_circular_buffer(circular_buffer_t *cb) {
    cb->head = 0;
    cb->count = 0;
}

static void add_to_buffer(circular_buffer_t *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

static int init_hmc5883l(int handle) {
    if (i2cWriteByteData(handle, HMC5883L_CONFIG_REG_A, 0x70) < 0) {
        fprintf(stderr, "Error writing to config register A\n");
        return -1;
    }
    if (i2cWriteByteData(handle, HMC5883L_CONFIG_REG_B, 0x20) < 0) {
        fprintf(stderr, "Error writing to config register B\n");
        return -1;
    }
    if (i2cWriteByteData(handle, HMC5883L_MODE_REG, 0x00) < 0) {
        fprintf(stderr, "Error writing to mode register\n");
        return -1;
    }
    return 0;
}

static int read_magnetometer_data(int handle, magnetometer_data_t *data) {
    char buffer[6];
    if (i2cReadI2CBlockData(handle, HMC5883L_DATA_X_MSB, buffer, 6) != 6) {
        fprintf(stderr, "Error reading magnetometer data\n");
        return -1;
    }
    int16_t x = (int16_t)((buffer[0] << 8) | buffer[1]);
    int16_t z = (int16_t)((buffer[2] << 8) | buffer[3]);
    int16_t y = (int16_t)((buffer[4] << 8) | buffer[5]);
    data->x = (float)x;
    data->y = (float)y;
    data->z = (float)z;
    return 0;
}

static float calculate_heading(magnetometer_data_t data) {
    float x_compensated = data.x - HARD_IRON_X_OFFSET;
    float y_compensated = data.y - HARD_IRON_Y_OFFSET;
    float heading = atan2f(y_compensated, x_compensated) * 180.0 / M_PI;
    if (heading < 0) {
        heading += 360.0;
    }
    return heading;
}

static void control_gpio(float current_heading) {
    float diff = fabsf(current_heading - TARGET_HEADING);
    if (diff > 180.0) {
        diff = 360.0 - diff;
    }
    if (diff > HEADING_THRESHOLD) {
        gpioWrite(GPIO_PIN, 1);
    } else {
        gpioWrite(GPIO_PIN, 0);
    }
}

static void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(GPIO_PIN, 0);
    gpioTerminate();
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_hmc5883l(i2c_handle) < 0) {
        fprintf(stderr, "HMC5883L initialisation failed\n");
        cleanup();
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0);

    init_circular_buffer(&heading_buffer);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (running) {
        magnetometer_data_t data;
        if (read_magnetometer_data(i2c_handle, &data) == 0) {
            float heading = calculate_heading(data);
            add_to_buffer(&heading_buffer, heading);
            control_gpio(heading);
            printf("Heading: %.2f\n", heading);
        } else {
            fprintf(stderr, "Failed to read magnetometer data, retrying...\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return 0;
}

