/*
 * Raspberry Pi 5 - BH1750 Ambient Light Sensor & RGB Lamp Control
 *
 * Reads light level from a BH1750 sensor on I2C bus 1 (address 0x23),
 * logs lux + RGB states to lighting_log.txt every second, and drives
 * three 5 V relay-controlled RGB channels on GPIO 17 (RED), GPIO 27
 * (GREEN), GPIO 22 (BLUE) using BCM numbering.
 *
 * Build:  gcc -O2 -Wall -Wextra -o lighting_control lighting_control.c \
 *            -lpigpio -lrt
 * Run:    sudo ./lighting_control
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

/* ---- Configuration ---- */
#define I2C_BUS              1
#define BH1750_ADDR          0x23
#define BH1750_CONT_HIGH_RES 0x10   /* Continuous High-Resolution mode */
#define BH1750_CONV_MS       120    /* Conversion time in milliseconds */

#define RED_PIN    17
#define GREEN_PIN  27
#define BLUE_PIN   22

#define LUX_THRESHOLD_LOW   50.0f
#define LUX_THRESHOLD_MID   150.0f
#define LUX_THRESHOLD_HIGH  300.0f

#define LOG_FILE_NAME "lighting_log.txt"
#define POLL_INTERVAL_S 1

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd = -1;
static FILE    *g_log_fp = NULL;

/* ---- Prototypes ---- */
static void signal_handler(int sig);
static int  init_i2c(void);
static int  read_lux(float *lux_out);
static int  init_gpio(void);
static void control_rgb(float lux);
static void log_data(float lux, int red, int green, int blue);
static void cleanup(void);

/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Initialize I2C */
    if (init_i2c() != 0) {
        fprintf(stderr, "Error: I2C initialisation failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize GPIO */
    if (init_gpio() != 0) {
        fprintf(stderr, "Error: GPIO initialisation failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_fp = fopen(LOG_FILE_NAME, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Error: Cannot open log file '%s': %s\n",
                LOG_FILE_NAME, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Lighting control started. Logging to '%s'. Press Ctrl+C to exit.\n",
           LOG_FILE_NAME);

    /* Main loop */
    while (g_running) {
        float lux = 0.0f;
        int   red, green, blue;

        if (read_lux(&lux) != 0) {
            fprintf(stderr, "Warning: Failed to read lux value.\n");
            /* Turn off all lamps on sensor failure for safety */
            gpioWrite(RED_PIN, 0);
            gpioWrite(GREEN_PIN, 0);
            gpioWrite(BLUE_PIN, 0);
            red   = 0; green = 0; blue = 0;
        } else {
            control_rgb(lux);
            red   = gpioRead(RED_PIN);
            green = gpioRead(GREEN_PIN);
            blue  = gpioRead(BLUE_PIN);
        }

        log_data(lux, red, green, blue);
        sleep(POLL_INTERVAL_S);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
