                I2C_BUS, BH1750_ADDR, strerror(errno));
        return -1;
    }

    /* Start continuous high-resolution measurement */
    if (i2cWriteByte(g_i2c_fd, BH1750_CONT_HIGH_RES) < 0) {
        fprintf(stderr, "Error: Failed to start BH1750 measurement: %s\n",
                strerror(errno));
