/*
 * Raspberry Pi 5 - BH1750 Ambient Light Sensor & RGB Lamp Control
 *
 * Reads light level from a BH1750 sensor on I2C bus 1 (address 0x23),
 * logs lux + RGB states to lighting_log.txt every second, and drives
 * three 5 V relay-controlled RGB channels on GPIO 17 (RED), GPIO 27
 * (GREEN), GPIO 22 (BLUE) using BCM numbering.
 *
 * Build:  gcc -O2 -Wall -Wextra -o lighting_control lighting_control.c \
 *            -lpigpio -lrt
 * Run:    sudo ./lighting_control
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

/* ---- Configuration ---- */
#define I2C_BUS              1
#define BH1750_ADDR          0x23
#define BH1750_CONT_HIGH_RES 0x10   /* Continuous High-Resolution mode */
#define BH1750_CONV_MS       120    /* Conversion time in milliseconds */

#define RED_PIN    17
#define GREEN_PIN  27
#define BLUE_PIN   22

#define LUX_THRESHOLD_LOW   50.0f
#define LUX_THRESHOLD_MID   150.0f
#define LUX_THRESHOLD_HIGH  300.0f

#define LOG_FILE_NAME "lighting_log.txt"
#define POLL_INTERVAL_S 1

/* ---- Globals for cleanup ---- */
