static int      g_i2c_fd = -1;
static FILE    *g_log_fp = NULL;

/* ---- Prototypes ---- */
static void signal_handler(int sig);
static int  init_i2c(void);
static int  read_lux(float *lux_out);
static int  init_gpio(void);
static void control_rgb(float lux);
static void log_data(float lux, int red, int green, int blue);
static void cleanup(void);

/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Initialize I2C */
    if (init_i2c() != 0) {
        fprintf(stderr, "Error: I2C initialisation failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize GPIO */
    if (init_gpio() != 0) {
        fprintf(stderr, "Error: GPIO initialisation failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_fp = fopen(LOG_FILE_NAME, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Error: Cannot open log file '%s': %s\n",
                LOG_FILE_NAME, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Lighting control started. Logging to '%s'. Press Ctrl+C to exit.\n",
           LOG_FILE_NAME);

    /* Main loop */
    while (g_running) {
        float lux = 0.0f;
        int   red, green, blue;

        if (read_lux(&lux) != 0) {
            fprintf(stderr, "Warning: Failed to read lux value.\n");
