#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MOTOR_A_IN1 17
#define MOTOR_A_IN2 18
#define MOTOR_B_IN3 22
#define MOTOR_B_IN4 23

#define PWM_FREQUENCY 1000
#define PWM_RANGE 255
#define LOOP_DELAY_US 100000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int safe_write(unsigned gpio, int level) {
    if (gpioWrite(gpio, level) < 0) {
        fprintf(stderr, "Error: gpioWrite(%u, %d) failed\n", gpio, level);
        return -1;
    }
    return 0;
}

static int safe_pwm(unsigned gpio, int duty) {
    if (gpioPWM(gpio, duty) < 0) {
        fprintf(stderr, "Error: gpioPWM(%u, %d) failed\n", gpio, duty);
        return -1;
    }
    return 0;
}

static int motor_forward(int motor_a_duty, int motor_b_duty) {
    if (safe_write(MOTOR_A_IN1, 1) < 0) return -1;
    if (safe_write(MOTOR_B_IN3, 1) < 0) return -1;
    if (safe_pwm(MOTOR_A_IN2, motor_a_duty) < 0) return -1;
    if (safe_pwm(MOTOR_B_IN4, motor_b_duty) < 0) return -1;
    return 0;
}

static int motor_backward(int motor_a_duty, int motor_b_duty) {
    if (safe_write(MOTOR_A_IN1, 0) < 0) return -1;
    if (safe_write(MOTOR_B_IN3, 0) < 0) return -1;
    if (safe_pwm(MOTOR_A_IN2, motor_a_duty) < 0) return -1;
    if (safe_pwm(MOTOR_B_IN4, motor_b_duty) < 0) return -1;
    return 0;
}

static int motor_stop(void) {
    if (safe_write(MOTOR_A_IN1, 0) < 0) return -1;
    if (safe_write(MOTOR_B_IN3, 0) < 0) return -1;
    if (safe_pwm(MOTOR_A_IN2, 0) < 0) return -1;
    if (safe_pwm(MOTOR_B_IN4, 0) < 0) return -1;
    return 0;
}

static int motor_set_speed(int motor_a_duty, int motor_b_duty) {
    if (motor_a_duty < 0 || motor_a_duty > PWM_RANGE) {
        fprintf(stderr, "Error: motor A duty %d out of range\n", motor_a_duty);
        return -1;
    }
    if (motor_b_duty < 0 || motor_b_duty > PWM_RANGE) {
        fprintf(stderr, "Error: motor B duty %d out of range\n", motor_b_duty);
        return -1;
    }
    return 0;
}

static int motor_control(int distance_a, int distance_b, int *motor_a_duty, int *motor_b_duty) {
    int diff_a = 50 - distance_a;
    int diff_b = 50 - distance_b;

    if (diff_a > 0) {
        *motor_a_duty = diff_a * 2;
        if (*motor_a_duty > PWM_RANGE) *motor_a_duty = PWM_RANGE;
    } else {
        *motor_a_duty = 0;
    }

    if (diff_b > 0) {
        *motor_b_duty = diff_b * 2;
        if (*motor_b_duty > PWM_RANGE) *motor_b_duty = PWM_RANGE;
    } else {
        *motor_b_duty = 0;
    }

    if (distance_a < 50 && distance_b < 50) {
        return motor_forward(*motor_a_duty, *motor_b_duty);
    } else {
        return motor_backward(*motor_a_duty, *motor_b_duty);
    }
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <distance_a> <distance_b>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int distance_a = atoi(argv[1]);
    int distance_b = atoi(argv[2]);

    if (distance_a < 10 || distance_a > 100 || distance_b < 10 || distance_b > 100) {
        fprintf(stderr, "Error: distances must be between 10 and 100 cm\n");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(MOTOR_A_IN1, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_A_IN2, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_B_IN3, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_B_IN4, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(MOTOR_A_IN2, PWM_FREQUENCY) < 0 ||
        gpioSetPWMfrequency(MOTOR_B_IN4, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(MOTOR_A_IN2, PWM_RANGE) < 0 ||
        gpioSetPWMrange(MOTOR_B_IN4, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error: sigaction failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int motor_a_duty = 0;
    int motor_b_duty = 0;

    if (motor_control(distance_a, distance_b, &motor_a_duty, &motor_b_duty) < 0) {
        fprintf(stderr, "Error: motor_control failed\n");
        motor_stop();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        if (motor_control(distance_a, distance_b, &motor_a_duty, &motor_b_duty) < 0) {
            fprintf(stderr, "Error: motor_control failed\n");
            break;
        }
        gpioDelay(LOOP_DELAY_US);
    }

    motor_stop();
    gpioTerminate();
    return EXIT_SUCCESS;
}

