#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define MPU6050_ADDR 0x68
#define MPU6050_PWR_MGMT_1 0x6B
#define MPU6050_ACCEL_XOUT_H 0x3B
#define MPU6050_GYRO_XOUT_H 0x43

#define SERVO_PIN 18
#define SERVO_MIN_PULSE_US 500
#define SERVO_MAX_PULSE_US 2500
#define SERVO_RANGE 180

#define LOG_FILE "solar_tracker.log"
#define MAX_RETRIES 5
#define RETRY_DELAY_MS 10

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static int servo_fd = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

int i2c_read_reg16(int fd, uint8_t reg, int16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, 2) != 2) return -1;
    *val = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

int init_mpu6050(void) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        i2c_fd = open(I2C_BUS, O_RDWR);
        if (i2c_fd < 0) {
            fprintf(stderr, "Error opening I2C bus: %s. Retrying...\n", strerror(errno));
            retries++;
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }
        if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
            fprintf(stderr, "Error setting I2C slave address: %s. Retrying...\n", strerror(errno));
            close(i2c_fd);
            i2c_fd = -1;
            retries++;
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }
        uint8_t whoami;
        if (i2c_read_reg8(i2c_fd, 0x75, &whoami) < 0) {
            fprintf(stderr, "Error reading WHO_AM_I: %s. Retrying...\n", strerror(errno));
            close(i2c_fd);
            i2c_fd = -1;
            retries++;
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }
        if (whoami != 0x68) {
            fprintf(stderr, "WHO_AM_I mismatch: 0x%02X. Retrying...\n", whoami);
            close(i2c_fd);
            i2c_fd = -1;
            retries++;
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }
        if (i2c_write_reg8(i2c_fd, MPU6050_PWR_MGMT_1, 0x00) < 0) {
            fprintf(stderr, "Error writing to PWR_MGMT_1: %s. Retrying...\n", strerror(errno));
            close(i2c_fd);
            i2c_fd = -1;
            retries++;
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }
        return 0;
    }
    fprintf(stderr, "Failed to initialize MPU6050 after %d retries.\n", MAX_RETRIES);
    return -1;
}

int read_accel_data(int16_t *ax, int16_t *ay, int16_t *az) {
    if (i2c_read_reg16(i2c_fd, MPU6050_ACCEL_XOUT_H, ax) < 0) return -1;
    if (i2c_read_reg16(i2c_fd, MPU6050_ACCEL_XOUT_H + 2, ay) < 0) return -1;
    if (i2c_read_reg16(i2c_fd, MPU6050_ACCEL_XOUT_H + 4, az) < 0) return -1;
    return 0;
}

float calculate_pitch(int16_t ax, int16_t ay, int16_t az) {
    float x = (float)ax;
    float y = (float)ay;
    float z = (float)az;
    return atan2(x, sqrt(y * y + z * z)) * 180.0 / M_PI;
}

float calculate_roll(int16_t ax, int16_t ay, int16_t az) {
    float x = (float)ax;
    float y = (float)ay;
    float z = (float)az;
    return atan2(y, sqrt(x * x + z * z)) * 180.0 / M_PI;
}

int init_servo(void) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip2/pwm0");
    int fd = open(path, O_RDONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening servo sysfs path: %s\n", strerror(errno));
        return -1;
    }
    close(fd);
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip2/export");
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening export: %s\n", strerror(errno));
        return -1;
    }
    if (write(fd, "0", 1) != 1) {
        fprintf(stderr, "Error writing to export: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    usleep(100000);
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip2/pwm0/period");
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening period: %s\n", strerror(errno));
        return -1;
    }
    char buf[32];
    snprintf(buf, sizeof(buf), "%d", 20000000);
    if (write(fd, buf, strlen(buf)) != (ssize_t)strlen(buf)) {
        fprintf(stderr, "Error writing to period: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip2/pwm0/duty_cycle");
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening duty_cycle: %s\n", strerror(errno));
        return -1;
    }
    close(fd);
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip2/pwm0/enable");
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening enable: %s\n", strerror(errno));
        return -1;
    }
    if (write(fd, "1", 1) != 1) {
        fprintf(stderr, "Error writing to enable: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

int set_servo_angle(int angle) {
    if (angle < 0 || angle > SERVO_RANGE) {
        fprintf(stderr, "Invalid angle: %d\n", angle);
        return -1;
    }
    int pulse_width = SERVO_MIN_PULSE_US + (int)((float)angle / SERVO_RANGE * (SERVO_MAX_PULSE_US - SERVO_MIN_PULSE_US));
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip2/pwm0/duty_cycle");
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening duty_cycle: %s\n", strerror(errno));
        return -1;
    }
    char buf[32];
    snprintf(buf, sizeof(buf), "%d", pulse_width);
    if (write(fd, buf, strlen(buf)) != (ssize_t)strlen(buf)) {
        fprintf(stderr, "Error writing to duty_cycle: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

int log_data(float pitch, float roll, int position) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s,%.2f,%.2f,%d\n", timestamp, pitch, roll, position);
    fclose(fp);
    return 0;
}

void cleanup(void) {
    if (servo_fd >= 0) {
        close(servo_fd);
        servo_fd = -1;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (init_mpu6050() < 0) {
        cleanup();
        return 1;
    }

    if (init_servo() < 0) {
        cleanup();
        return 1;
    }

    int16_t ax, ay, az;
    float pitch, roll;
    int position;

    while (running) {
        if (read_accel_data(&ax, &ay, &az) < 0) {
            fprintf(stderr, "Error reading accelerometer data: %s\n", strerror(errno));
            usleep(100000);
            continue;
        }
        pitch = calculate_pitch(ax, ay, az);
        roll = calculate_roll(ax, ay, az);

        position = (int)(pitch * 2);
        if (position < 0) position = 0;
        if (position > SERVO_RANGE) position = SERVO_RANGE;

        if (set_servo_angle(position) < 0) {
            fprintf(stderr, "Error setting servo angle\n");
        }

        if (log_data(pitch, roll, position) < 0) {
            fprintf(stderr, "Error logging data\n");
        }

        usleep(100000);
    }

    cleanup();
    return 0;
}

