#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define NUM_RELAYS 4
#define FADE_DURATION 1800
#define PWM_FREQ 100
#define PWM_RANGE 100
#define SCHEDULE_FILE "lighting_schedule.txt"

static const int relay_pins[NUM_RELAYS] = {4, 17, 27, 22};

typedef struct {
    int hour;
    int minute;
    int second;
    int relay_number;
    int state; /* 0 = off, 1 = on */
} ScheduleEntry;

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t current_state[NUM_RELAYS] = {0};
static volatile sig_atomic_t target_state[NUM_RELAYS] = {0};
static volatile sig_atomic_t fade_start[NUM_RELAYS] = {0};
static volatile sig_atomic_t fade_progress[NUM_RELAYS] = {0};

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int parse_schedule_entry(const char *line, ScheduleEntry *entry) {
    if (sscanf(line, "%d:%d:%d,%d,%d",
               &entry->hour, &entry->minute, &entry->second,
               &entry->relay_number, &entry->state) != 5) {
        return -1;
    }
    if (entry->relay_number < 1 || entry->relay_number > NUM_RELAYS ||
        entry->state < 0 || entry->state > 1) {
        return -1;
    }
    return 0;
}

static int load_schedule(ScheduleEntry *schedule, int *schedule_size) {
    FILE *fp = fopen(SCHEDULE_FILE, "r");
    if (!fp) {
        perror("Error opening schedule file");
        return -1;
    }

    char line[256];
    int count = 0;
    while (fgets(line, sizeof(line), fp) && count < 100) {
        ScheduleEntry entry;
        if (parse_schedule_entry(line, &entry) == 0) {
            schedule[count++] = entry;
        } else {
            fprintf(stderr, "Invalid schedule entry: %s", line);
        }
    }
    fclose(fp);
    *schedule_size = count;
    return 0;
}

static int set_relay(int pin, int state) {
    if (gpioWrite(pin, state) != 0) {
        fprintf(stderr, "Error writing to GPIO %d\n", pin);
        return -1;
    }
    return 0;
}

static int fade_relay(int pin, int target) {
    int current = current_state[pin - 1];
    if (current == target) return 0;

    int duration = FADE_DURATION;
    int steps = PWM_RANGE;
    int delay_us = (duration * 1000000) / steps;

    for (int i = 0; i < steps && running; i++) {
        int duty = (current * (PWM_RANGE - 1)) / 100;
        if (gpioPWM(pin, duty) != 0) {
            fprintf(stderr, "Error setting PWM on GPIO %d\n", pin);
            return -1;
        }
        gpioDelay(delay_us);
        current_state[pin - 1] = current;
        if (current_state[pin - 1] == target) break;
        current_state[pin - 1] = target;
    }

    if (gpioPWM(pin, target ? PWM_RANGE : 0) != 0) {
        fprintf(stderr, "Error setting PWM on GPIO %d\n", pin);
        return -1;
    }
    return 0;
}

static void update_relay(int pin, int target) {
    if (target == current_state[pin - 1]) return;

    if (fade_start[pin - 1] == 0) {
        fade_start[pin - 1] = time(NULL);
        fade_progress[pin - 1] = 0;
        target_state[pin - 1] = target;
    } else {
        time_t now = time(NULL);
        if (now - fade_start[pin - 1] >= FADE_DURATION) {
            current_state[pin - 1] = target;
            fade_start[pin - 1] = 0;
            target_state[pin - 1] = 0;
            fade_progress[pin - 1] = 0;
        } else {
            fade_progress[pin - 1] = (now - fade_start[pin - 1]) * PWM_RANGE / FADE_DURATION;
            int duty = (fade_progress[pin - 1] * PWM_RANGE) / PWM_RANGE;
            if (gpioPWM(pin, duty) != 0) {
                fprintf(stderr, "Error setting PWM on GPIO %d\n", pin);
            }
        }
    }
}

static void cleanup(void) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        gpioWrite(relay_pins[i], 0);
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpioSetMode(relay_pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error setting GPIO %d as output\n", relay_pins[i]);
            gpioTerminate();
            return 1;
        }
        if (gpioSetPWMfrequency(relay_pins[i], PWM_FREQ) < 0) {
            fprintf(stderr, "Error setting PWM frequency on GPIO %d\n", relay_pins[i]);
            gpioTerminate();
            return 1;
        }
        if (gpioSetPWMrange(relay_pins[i], PWM_RANGE) < 0) {
            fprintf(stderr, "Error setting PWM range on GPIO %d\n", relay_pins[i]);
            gpioTerminate();
            return 1;
        }
        if (gpioPWM(relay_pins[i], 0) != 0) {
            fprintf(stderr, "Error initializing PWM on GPIO %d\n", relay_pins[i]);
            gpioTerminate();
            return 1;
        }
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    ScheduleEntry *schedule = malloc(100 * sizeof(ScheduleEntry));
    if (!schedule) {
        fprintf(stderr, "Memory allocation failed\n");
        cleanup();
        return 1;
    }

    int schedule_size = 0;
    if (load_schedule(schedule, &schedule_size) != 0) {
        free(schedule);
        cleanup();
        return 1;
    }

    time_t last_check = 0;

    while (running) {
        time_t now = time(NULL);
        if (now - last_check >= 1) {
            last_check = now;

            struct tm *local = localtime(&now);
            if (!local) {
                fprintf(stderr, "Error getting local time\n");
                continue;
            }

            int current_hour = local->tm_hour;
            int current_minute = local->tm_min;
            int current_second = local->tm_sec;

            for (int i = 0; i < schedule_size; i++) {
                if (schedule[i].hour == current_hour &&
                    schedule[i].minute == current_minute &&
                    schedule[i].second == current_second) {
                    target_state[schedule[i].relay_number - 1] = schedule[i].state;
                }
            }
        }

        for (int i = 0; i < NUM_RELAYS; i++) {
            update_relay(relay_pins[i], target_state[i]);
        }

        gpioDelay(100000);
    }

    free(schedule);
    cleanup();
    return 0;
}

