/*
 * Rudimentary theremin for Raspberry Pi Zero W
 * HC-SR04 ultrasonic distance sensor -> PWM buzzer frequency mapping
 *
 * Wiring:
 *   HC-SR04 TRIG -> GPIO23 (BCM)
 *   HC-SR04 ECHO -> GPIO24 (BCM)
 *   PWM buzzer   -> GPIO18 (BCM)
 *
 * Build: gcc -O2 -Wall -o theremin theremin.c -lpigpio -lrt
 * Run:   sudo ./theremin
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN      23
#define ECHO_PIN         24
#define BUZZER_PIN       18

#define SPEED_OF_SOUND   34300.0f   /* cm/s at ~20 °C */
#define MIN_DISTANCE_CM  2.0f
#define MAX_DISTANCE_CM  400.0f
#define MIN_FREQUENCY    200        /* Hz */
#define MAX_FREQUENCY    1000       /* Hz */
#define ECHO_TIMEOUT_US  30000      /* 30 ms (~5 m round trip) */
#define LOOP_DELAY_US    20000      /* 20 ms -> ~50 Hz */
#define MIN_CYCLE_US     60000      /* 60 ms between measurements */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Measure distance (cm) from the HC-SR04.
 * Returns true on success, false on timeout or sensor-absent.
 */
static bool read_distance(float *distance_out)
{
    uint32_t start_tick, end_tick, timeout_tick;

    /* --- Issue 10 µs trigger pulse --- */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to set TRIGGER high\n");
        return false;
    }
    gpioDelay(10);                 /* 10 µs */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to set TRIGGER low\n");
        return false;
    }

    /* --- Wait for echo rising edge (timeout) --- */
    start_tick = gpioTick();
    timeout_tick = start_tick + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: echo start timeout (sensor absent?)\n");
            return false;
        }
    }
    uint32_t echo_start = gpioTick();

    /* --- Wait for echo falling edge (timeout) --- */
    timeout_tick = echo_start + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: echo end timeout\n");
            return false;
        }
    }
    end_tick = gpioTick();

    uint32_t pulse_us = end_tick - echo_start;
    if (pulse_us == 0) {
        fprintf(stderr, "Error: zero pulse width\n");
        return false;
    }

    /* distance = (pulse_us * speed_of_sound) / 2 / 1e6 */
    *distance_out = (float)pulse_us * SPEED_OF_SOUND / 2000000.0f;
    return true;
}

/*
 * Map distance (cm) to frequency (Hz).
 * Returns true if the frequency is within the buzzer's valid range.
 */
static bool map_distance_to_frequency(float distance, int *frequency_out)
{
    if (distance < MIN_DISTANCE_CM) distance = MIN_DISTANCE_CM;
    if (distance > MAX_DISTANCE_CM) distance = MAX_DISTANCE_CM;

    float normalized = (distance - MIN_DISTANCE_CM) /
                       (MAX_DISTANCE_CM - MIN_DISTANCE_CM);
    int freq = (int)(MIN_FREQUENCY +
                     normalized * (MAX_FREQUENCY - MIN_FREQUENCY));

    if (freq < MIN_FREQUENCY || freq > MAX_FREQUENCY) {
        fprintf(stderr, "Error: frequency %d out of range [%d, %d]\n",
                freq, MIN_FREQUENCY, MAX_FREQUENCY);
        return false;
    }
    *frequency_out = freq;
    return true;
}

static void set_buzzer_frequency(int frequency)
{
    if (gpioSetPWMfrequency(BUZZER_PIN, frequency) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency(%d) failed\n", frequency);
    }
    if (gpioPWM(BUZZER_PIN, 128) < 0) {   /* 50 % duty cycle */
        fprintf(stderr, "Error: gpioPWM(128) failed\n");
    }
}

static void silence_buzzer(void)
{
    gpioPWM(BUZZER_PIN, 0);
}

int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO pins --- */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: cannot set TRIGGER_PIN %d as output\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: cannot set ECHO_PIN %d as input\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: cannot set BUZZER_PIN %d as output\n", BUZZER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(50);  /* let sensor settle */

    /* --- Install signal handler --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }

    printf("Theremin running. Press Ctrl+C to exit.\n");

    uint32_t last_trigger_tick = 0;

    while (g_running) {
        uint32_t now = gpioTick();
        if ((int32_t)(now - last_trigger_tick) < MIN_CYCLE_US) {
            gpioDelay(MIN_CYCLE_US - (now - last_trigger_tick));
            continue;
        }
        last_trigger_tick = now;

        float distance;
        if (!read_distance(&distance)) {
            /* Sensor error or timeout: silence buzzer */
            silence_buzzer();
            continue;
        }

        int frequency;
        if (!map_distance_to_frequency(distance, &frequency)) {
            silence_buzzer();
            continue;
        }

        set_buzzer_frequency(frequency);
        gpioDelay(LOOP_DELAY_US);
    }

    /* --- Cleanup --- */
    silence_buzzer();
    gpioTerminate();
    printf("\nTheremin stopped.\n");
    return EXIT_SUCCESS;
}

