#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define MPU6050_ADDR 0x68

#define PWR_MGMT_1 0x6B
#define GYRO_XOUT_H 0x43

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        return -1;
    }
    return 0;
}

static int read_gyro_data(int fd, float *x, float *y, float *z) {
    uint8_t buf[6];
    if (i2c_read_burst(fd, GYRO_XOUT_H, buf, 6) < 0) {
        return -1;
    }
    int16_t raw_x = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_y = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t raw_z = (int16_t)((buf[4] << 8) | buf[5]);
    *x = (float)raw_x / 131.0f;
    *y = (float)raw_y / 131.0f;
    *z = (float)raw_z / 131.0f;
    return 0;
}

static int log_data(FILE *fp, float x, float y, float z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        return -1;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    if (fprintf(fp, "%s,%.2f,%.2f,%.2f\n", timestamp, x, y, z) < 0) {
        return -1;
    }
    fflush(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    if (i2c_write_byte(fd, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error writing to PWR_MGMT_1: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    FILE *fp = fopen("gyro_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening gyro_log.txt: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    while (running) {
        float x, y, z;
        if (read_gyro_data(fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Error reading gyro data: %s\n", strerror(errno));
        } else {
            if (log_data(fp, x, y, z) < 0) {
                fprintf(stderr, "Error logging data: %s\n", strerror(errno));
            }
        }
        usleep(100000);
    }

    fclose(fp);
    close(fd);
    return EXIT_SUCCESS;
}

