#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>
#include <stdint.h>

#define BUTTON_PIN 17
#define BUZZER_PIN 18
#define DEBOUNCE_MS 50
#define PWM_DUTY 128  /* 50% of 255 */

/* Melody: note frequencies in Hz, durations in ms */
typedef struct {
    uint16_t freq;
    uint16_t dur;
} Note;

static const Note melody[] = {
    {262, 200}, {294, 200}, {330, 200}, {349, 200},
    {392, 200}, {440, 200}, {494, 200}, {523, 200}
};
static const int melody_len = (int)(sizeof(melody) / sizeof(melody[0]));

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t button_pressed = 0;
static volatile uint32_t last_press_tick = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void button_isr(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)userdata;
    if (level == 0) {  /* falling edge = pressed (active-low) */
        uint32_t diff = tick - last_press_tick;
        if (diff > DEBOUNCE_MS * 1000) {
            last_press_tick = tick;
            button_pressed = 1;
        }
    }
}

static int play_tone(uint16_t freq, uint16_t dur_ms) {
    if (gpioSetPWMfrequency(BUZZER_PIN, freq) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency(%u) failed\n", freq);
        return -1;
    }
    if (gpioPWM(BUZZER_PIN, PWM_DUTY) < 0) {
        fprintf(stderr, "Error: gpioPWM(%u) failed\n", PWM_DUTY);
        return -1;
    }
    gpioDelay(dur_ms * 1000);
    if (gpioPWM(BUZZER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioPWM(0) failed\n");
        return -1;
    }
    return 0;
}

static int play_melody(void) {
    for (int i = 0; i < melody_len; i++) {
        if (!running) return 0;
        if (button_pressed) return 0;  /* user cancelled */
        if (play_tone(melody[i].freq, melody[i].dur) < 0) return -1;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(BUTTON_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(BUTTON_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown(BUTTON_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(BUZZER_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetISRFuncEx(BUTTON_PIN, FALLING_EDGE, 0, button_isr, NULL) < 0) {
        fprintf(stderr, "Error: gpioSetISRFuncEx failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error: sigaction failed\n");
        gpioSetISRFuncEx(BUTTON_PIN, FALLING_EDGE, 0, NULL, NULL);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Doorbell ready. Press the button (GPIO17) to play the melody.\n");
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        if (button_pressed) {
            button_pressed = 0;
            printf("Button pressed! Playing melody...\n");
            if (play_melody() < 0) {
                fprintf(stderr, "Error: melody playback failed\n");
                break;
            }
        }
        gpioDelay(10000);  /* 10 ms poll */
    }

    /* Cleanup */
    gpioPWM(BUZZER_PIN, 0);
    gpioSetISRFuncEx(BUTTON_PIN, FALLING_EDGE, 0, NULL, NULL);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

