#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define WINDOW_SIZE 5
#define THRESHOLD 3
#define LOG_FILE "vibration_events.log"
#define DEFAULT_TIMEOUT_MS 1000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int get_iso8601_timestamp(char *buf, size_t len) {
    time_t rawtime;
    struct tm timeinfo;

    if (time(&rawtime) == (time_t)-1) {
        return -1;
    }
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        return -1;
    }
    if (strftime(buf, len, "%Y-%m-%dT%H:%M:%S%z", &timeinfo) == 0) {
        return -1;
    }
    return 0;
}

static int log_event(FILE *fp, int value) {
    char ts[32];
    if (get_iso8601_timestamp(ts, sizeof(ts)) != 0) {
        fprintf(stderr, "Error: failed to generate timestamp\n");
        return -1;
    }
    if (fprintf(fp, "%s,%d\n", ts, value) < 0) {
        fprintf(stderr, "Error: failed to write to log file: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "Warning: fflush failed: %s\n", strerror(errno));
    }
    return 0;
}

int main(int argc, char *argv[]) {
    int timeout_ms = DEFAULT_TIMEOUT_MS;
    int opt;

    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                timeout_ms = atoi(optarg);
                if (timeout_ms <= 0) {
                    fprintf(stderr, "Error: timeout must be positive\n");
                    return EXIT_FAILURE;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-t timeout_ms]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Warning: failed to set pull-down on GPIO%d\n", GPIO_PIN);
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGINT handler: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGTERM handler: %s\n", strerror(errno));
    }

    int values[WINDOW_SIZE] = {0};
    int idx = 0;
    int count = 0;
    int last_value = -1;

    printf("Monitoring SW-420 vibration sensor on GPIO%d (timeout=%d ms)...\n", GPIO_PIN, timeout_ms);
    fflush(stdout);

    while (g_running) {
        int level = gpioRead(GPIO_PIN);
        if (level < 0) {
            fprintf(stderr, "Error: gpioRead failed on GPIO%d\n", GPIO_PIN);
            break;
        }

        if (level != last_value) {
            if (log_event(fp, level) != 0) {
                fprintf(stderr, "Error: logging failed, continuing...\n");
            }
            last_value = level;
        }

        values[idx] = level;
        idx = (idx + 1) % WINDOW_SIZE;
        if (count < WINDOW_SIZE) {
            count++;
        }

        int high_count = 0;
        for (int i = 0; i < count; i++) {
            if (values[i] == 1) {
                high_count++;
            }
        }

        if (high_count >= THRESHOLD) {
            char ts[32];
            if (get_iso8601_timestamp(ts, sizeof(ts)) == 0) {
                printf("EARTHQUAKE ALERT at %s (HIGH=%d)\n", ts, high_count);
                fflush(stdout);
            } else {
                printf("EARTHQUAKE ALERT (HIGH=%d)\n", high_count);
                fflush(stdout);
            }
        }

        if (gpioDelay(timeout_ms * 1000) != 0) {
            fprintf(stderr, "Error: gpioDelay failed\n");
            break;
        }
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Warning: fclose failed: %s\n", strerror(errno));
    }
    gpioTerminate();
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

