#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define LSM303_ADDRESS 0x1E
#define LSM303_MAG_X_MSB 0x03
#define LSM303_MAG_X_LSB 0x04
#define LSM303_MAG_Y_MSB 0x05
#define LSM303_MAG_Y_LSB 0x06
#define LSM303_MAG_Z_MSB 0x07
#define LSM303_MAG_Z_LSB 0x08

#define X_OFFSET 10.0
#define Y_OFFSET -5.0
#define Z_OFFSET 20.0

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int read_magnetometer(int fd, float *x, float *y, float *z) {
    uint8_t x_msb, x_lsb, y_msb, y_lsb, z_msb, z_lsb;

    if (i2c_read_reg8(fd, LSM303_MAG_X_MSB, &x_msb) < 0) return -1;
    if (i2c_read_reg8(fd, LSM303_MAG_X_LSB, &x_lsb) < 0) return -1;
    if (i2c_read_reg8(fd, LSM303_MAG_Y_MSB, &y_msb) < 0) return -1;
    if (i2c_read_reg8(fd, LSM303_MAG_Y_LSB, &y_lsb) < 0) return -1;
    if (i2c_read_reg8(fd, LSM303_MAG_Z_MSB, &z_msb) < 0) return -1;
