#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define RELAY1_PIN 17
#define RELAY2_PIN 23
#define RELAY3_PIN 24
#define RELAY4_PIN 25

#define MOISTURE_THRESHOLD 30
#define IRRIGATION_DURATION 5
#define RELAY_GAP 1
#define POLL_INTERVAL 10

static const int relay_pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
static const int num_relays = sizeof(relay_pins) / sizeof(relay_pins[0]);

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int activate_relay(int pin, int duration) {
    if (gpioWrite(pin, 0) < 0) {
        fprintf(stderr, "Error: failed to activate relay on GPIO %d: %s\n", pin, strerror(errno));
        return -1;
    }
    gpioDelay(duration * 1000000);
    if (gpioWrite(pin, 1) < 0) {
        fprintf(stderr, "Error: failed to deactivate relay on GPIO %d: %s\n", pin, strerror(errno));
        return -1;
    }
    return 0;
}

static int irrigate_all_relays(void) {
    for (int i = 0; i < num_relays; i++) {
        if (activate_relay(relay_pins[i], IRRIGATION_DURATION) < 0) {
            return -1;
        }
        if (i < num_relays - 1) {
            gpioDelay(RELAY_GAP * 1000000);
        }
    }
    return 0;
}

static int log_irrigation_event(int relay_number, int moisture_level) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        return -1;
    }

    if (fprintf(log_file, "%s - Relay %d - Moisture Level: %d\n", timestamp, relay_number, moisture_level) < 0) {
        fprintf(stderr, "Error: failed to write to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error: failed to flush log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int simulate_moisture_reading(void) {
    return rand() % 101;
}

static void cleanup_gpio(void) {
    for (int i = 0; i < num_relays; i++) {
        gpioWrite(relay_pins[i], 1);
    }
    gpioTerminate();
}

int main(void) {
    srand((unsigned int)time(NULL));

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < num_relays; i++) {
        if (gpioSetMode(relay_pins[i], PI_OUTPUT) < 0) {
            fprintf(stderr, "Error: failed to set GPIO %d as output\n", relay_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioWrite(relay_pins[i], 1) < 0) {
            fprintf(stderr, "Error: failed to initialise GPIO %d to high\n", relay_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    log_file = fopen("irrigation_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: failed to open log file: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: failed to install SIGINT handler: %s\n", strerror(errno));
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error: failed to install SIGTERM handler: %s\n", strerror(errno));
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Smart Irrigation System started. Press Ctrl+C to exit.\n");

    while (running) {
        int moisture_level = simulate_moisture_reading();
        printf("Simulated moisture level: %d\n", moisture_level);

        if (moisture_level < MOISTURE_THRESHOLD) {
            printf("Moisture level below threshold. Irrigating all relays...\n");
            if (irrigate_all_relays() < 0) {
                fprintf(stderr, "Error: irrigation sequence failed\n");
            }
        }

        for (int i = 0; i < POLL_INTERVAL && running; i++) {
            gpioDelay(1000000);
        }
    }

    printf("\nShutting down...\n");
    cleanup_gpio();

    if (log_file != NULL) {
        fclose(log_file);
    }

    printf("Smart Irrigation System stopped.\n");
    return EXIT_SUCCESS;
}

