        fprintf(stderr, "Error: localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        return -1;
    }

    if (fprintf(log_file, "%s - Relay %d - Moisture Level: %d\n", timestamp, relay_number, moisture_level) < 0) {
        fprintf(stderr, "Error: failed to write to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error: failed to flush log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int simulate_moisture_reading(void) {
    return rand() % 101;
}

static void cleanup_gpio(void) {
    for (int i = 0; i < num_relays; i++) {
        gpioWrite(relay_pins[i], 1);
    }
    gpioTerminate();
}

int main(void) {
    srand((unsigned int)time(NULL));

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < num_relays; i++) {
        if (gpioSetMode(relay_pins[i], PI_OUTPUT) < 0) {
            fprintf(stderr, "Error: failed to set GPIO %d as output\n", relay_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioWrite(relay_pins[i], 1) < 0) {
            fprintf(stderr, "Error: failed to initialise GPIO %d to high\n", relay_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    log_file = fopen("irrigation_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: failed to open log file: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: failed to install SIGINT handler: %s\n", strerror(errno));
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error: failed to install SIGTERM handler: %s\n", strerror(errno));
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Smart Irrigation System started. Press Ctrl+C to exit.\n");

    while (running) {
        int moisture_level = simulate_moisture_reading();
        printf("Simulated moisture level: %d\n", moisture_level);

        if (moisture_level < MOISTURE_THRESHOLD) {
            printf("Moisture level below threshold. Irrigating all relays...\n");
            if (irrigate_all_relays() < 0) {
                fprintf(stderr, "Error: irrigation sequence failed\n");
            }
        }

        for (int i = 0; i < POLL_INTERVAL && running; i++) {
            gpioDelay(1000000);
        }
    }

    printf("\nShutting down...\n");
    cleanup_gpio();

    if (log_file != NULL) {
        fclose(log_file);
    }

    printf("Smart Irrigation System stopped.\n");
    return EXIT_SUCCESS;
}

