/*
 * Automated Plant Watering System — Raspberry Pi Zero W
 *
 * Two SG90 servo motors (valve + nozzle) controlled via a library API.
 * Library symbols (prefix "servo_") are resolved at runtime so the
 * build environment need not have pigpio installed.
 *
 * Wiring:
 *   Valve servo signal  -> GPIO17 (BCM 17, physical pin 11)
 *   Nozzle servo signal -> GPIO18 (BCM 18, physical pin 12)
 *   SG90 V+ / GND      -> 5 V / GND (use a logic-level converter if
 *                         the Pi is powered from a 3.3 V rail).
 *
 * Build:
 *   gcc -Wall -Wextra -O2 -o watering watering.c -lthe_driver_lib -lrt
 */

#define _POSIX_C_SOURCE 200809L

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>

/* ---- Runtime library resolution --------------------------------------- */
#include <dlfcn.h>

typedef struct {
    int valve_gpio;
    int nozzle_gpio;
} ServoConfig;

typedef struct {
    int moisture;
} SensorData;

/* Library function prototypes (dlsym'd at runtime) */
typedef int  (*servo_open_t)  (int gpio, int pulse_width);
typedef int  (*servo_close_t) (int gpio);
typedef int  (*servo_set_t)   (int gpio, int pulse_width);
typedef void (*servo_cleanup_t)(void);

static servo_open_t  servo_open  = NULL;
static servo_close_t servo_close = NULL;
static servo_set_t   servo_set   = NULL;
static servo_cleanup_t servo_cleanup = NULL;

static ServoConfig config = {17, 18};
static volatile sig_atomic_t running = 1;

/* ---- Pulse-width table ------------------------------------------------- */
static const int nozzle_angles[] = {0, 45, 90, 135, 180};
static const int nozzle_pw[]     = {500, 1000, 1500, 2000, 2500};
static const int num_angles      = (int)(sizeof(nozzle_angles) / sizeof(nozzle_angles[0]));

/* ---- Signal handler ---------------------------------------------------- */
static void signal_handler(int signum)
{
    (void)signum;
    running = 0;
}

/* ---- Library loading --------------------------------------------------- */
static int load_library(void)
{
    void *handle = dlopen("libthe_driver_lib.so", RTLD_LAZY);
    if (!handle) {
        fprintf(stderr, "Error: cannot load libthe_driver_lib.so: %s\n",
                dlerror());
        return -1;
    }

    servo_open     = (servo_open_t)     dlsym(handle, "servo_open");
    servo_close    = (servo_close_t)    dlsym(handle, "servo_close");
    servo_set      = (servo_set_t)      dlsym(handle, "servo_set");
    servo_cleanup  = (servo_cleanup_t)  dlsym(handle, "servo_cleanup");

    const char *dlsym_err = dlerror();
    if (dlsym_err) {
        fprintf(stderr, "Error: dlsym failed: %s\n", dlsym_err);
        dlclose(handle);
        return -1;
    }

    return 0;
}

/* ---- Servo helpers ----------------------------------------------------- */
static int open_valve(void)
{
    for (int attempt = 0; attempt < 3; ++attempt) {
        int rc = servo_open(config.valve_gpio, 1500);
        if (rc == 0)
            return 0;
        fprintf(stderr, "Warning: servo_open failed (attempt %d/3): %d\n",
                attempt + 1, rc);
        usleep(100000);
    }
    return -1;
}

static int close_valve(void)
{
    for (int attempt = 0; attempt < 3; ++attempt) {
        int rc = servo_close(config.valve_gpio);
        if (rc == 0)
            return 0;
        fprintf(stderr, "Warning: servo_close failed (attempt %d/3): %d\n",
                attempt + 1, rc);
        usleep(100000);
    }
    return -1;
}

static int set_nozzle_angle(int angle)
{
    if (angle < 0 || angle > 180) {
        fprintf(stderr, "Error: invalid nozzle angle %d\n", angle);
        return -1;
    }

    int pw = 500 + (int)((float)angle / 180.0f * 2000.0f);
    for (int attempt = 0; attempt < 3; ++attempt) {
        int rc = servo_set(config.nozzle_gpio, pw);
        if (rc == 0)
            return 0;
        fprintf(stderr, "Warning: servo_set failed (attempt %d/3): %d\n",
                attempt + 1, rc);
        usleep(100000);
    }
    return -1;
}

/* ---- Watering cycle ---------------------------------------------------- */
static void water_plant(void)
{
    printf("Watering plant...\n");
    fflush(stdout);

    for (int i = 0; i < num_angles && running; ++i) {
        if (set_nozzle_angle(nozzle_angles[i]) != 0) {
            fprintf(stderr, "Error: failed to set nozzle angle %d\n",
                    nozzle_angles[i]);
            continue;
        }
        printf("  Nozzle angle: %d degrees (pulse %d us)\n",
               nozzle_angles[i], nozzle_pw[i]);
        fflush(stdout);
        sleep(2);
    }

    if (close_valve() != 0)
        fprintf(stderr, "Critical: failed to close valve after watering.\n");
    else
        printf("Valve closed.\n");

    sleep(5);
}

/* ---- Main -------------------------------------------------------------- */
int main(void)
{
    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Load the library at runtime */
    if (load_library() != 0)
        return EXIT_FAILURE;

    /* Initialize servos */
    if (servo_open(config.valve_gpio, 500) != 0) {
        fprintf(stderr, "Error: failed to initialize valve servo.\n");
        servo_cleanup();
        return EXIT_FAILURE;
    }
    if (servo_open(config.nozzle_gpio, 500) != 0) {
        fprintf(stderr, "Error: failed to initialize nozzle servo.\n");
        servo_close(config.valve_gpio);
        servo_cleanup();
        return EXIT_FAILURE;
    }

    printf("Plant watering system started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    const int moisture_values[] = {20, 40, 60, 80, 100};
    const int num_moisture = (int)(sizeof(moisture_values) / sizeof(moisture_values[0]));

    while (running) {
        for (int i = 0; i < num_moisture && running; ++i) {
            SensorData sensor_data = {moisture_values[i]};
            printf("Soil moisture: %d%%\n", sensor_data.moisture);
            fflush(stdout);

            if (sensor_data.moisture < 50) {
                printf("Moisture below threshold. Opening valve...\n");
                fflush(stdout);
                if (open_valve() != 0) {
                    fprintf(stderr, "Critical: failed to open valve. "
                                    "Aborting watering cycle.\n");
                    close_valve();
                    break;
                }
                water_plant();
            } else {
                printf("Moisture sufficient. Skipping watering.\n");
                fflush(stdout);
            }
            sleep(5);
        }
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down...\n");
    fflush(stdout);

    /* Stop both servos */
    servo_close(config.valve_gpio);
    servo_close(config.nozzle_gpio);

    /* Release library resources */
    servo_cleanup();

    printf("Plant watering system stopped.\n");
    return EXIT_SUCCESS;
}

