/*
 * MPU-6050 Gyroscope Logger for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   MPU-6050 VCC  -> Pi 3.3V (Pin 1)
 *   MPU-6050 GND  -> Pi GND  (Pin 9)
 *   MPU-6050 SCL  -> Pi GPIO3 / SCL (Pin 5)
 *   MPU-6050 SDA  -> Pi GPIO2 / SDA (Pin 3)
 *
 * Build: gcc -O2 -Wall -o gyro_logger gyro_logger.c -lm
 * Run:   ./gyro_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <math.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- MPU-6050 constants (per datasheet) ---- */
#define MPU6050_ADDR        0x68
#define MPU6050_REG_SMPLRT_DIV   0x19
#define MPU6050_REG_GYRO_CONFIG  0x1B
#define MPU6050_REG_GYRO_XOUT_H  0x43
#define MPU6050_REG_PWR_MGMT_1   0x6B

/* ---- Application constants ---- */
#define I2C_BUS            "/dev/i2c-1"
#define LOG_FILE           "gyro_log.txt"
#define SAMPLE_HZ          10
#define SAMPLE_PERIOD_NS   (1000000000L / SAMPLE_HZ)
#define GYRO_SCALE         131.0f   /* LSB per deg/s at ±250°/s range */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to an 8-bit register. Returns 0 on success, -1 on error. */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_write_reg8(0x%02X, 0x%02X) failed: %s\n",
                reg, value, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read `len` bytes starting at `reg` into `buf`. Returns 0 on success, -1 on error. */
static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    /* Set register pointer */
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_burst: set reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    /* Read data */
    ssize_t n = read(fd, buf, len);
    if (n != (ssize_t)len) {
        fprintf(stderr, "i2c_read_burst: read from 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int init_mpu6050(int fd)
{
    /* Wake up: clear SLEEP bit in PWR_MGMT_1 (0x6B) */
    if (i2c_write_reg8(fd, MPU6050_REG_PWR_MGMT_1, 0x00) != 0)
        return -1;
    usleep(100000);  /* allow oscillator to stabilize */

    /* Sample rate divider = 7  -> 1 kHz / (1 + 7) = 125 Hz internal */
    if (i2c_write_reg8(fd, MPU6050_REG_SMPLRT_DIV, 0x07) != 0)
        return -1;

    /* Gyro config: ±250°/s range (0x00) */
    if (i2c_write_reg8(fd, MPU6050_REG_GYRO_CONFIG, 0x00) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read 6 bytes of gyro data and convert to deg/s. Returns 0 on success, -1 on error. */
static int read_gyro(int fd, float *gx, float *gy, float *gz)
{
    uint8_t buf[6];
    if (i2c_read_burst(fd, MPU6050_REG_GYRO_XOUT_H, buf, sizeof(buf)) != 0)
        return -1;

    int16_t raw_x = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_y = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t raw_z = (int16_t)((buf[4] << 8) | buf[5]);

    *gx = (float)raw_x / GYRO_SCALE;
    *gy = (float)raw_y / GYRO_SCALE;
    *gz = (float)raw_z / GYRO_SCALE;
    return 0;
}

/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, float gx, float gy, float gz)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f,%.2f,%.2f\n", ts, gx, gy, gz);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus ---- */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Acquire MPU-6050 on the bus ---- */
    if (ioctl(g_i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                MPU6050_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Verify sensor presence with a dummy read ---- */
    uint8_t dummy;
    if (i2c_read_burst(g_i2c_fd, MPU6050_REG_PWR_MGMT_1, &dummy, 1) != 0) {
        fprintf(stderr, "MPU-6050 not detected at 0x%02X on %s\n",
                MPU6050_ADDR, I2C_BUS);
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Initialize sensor ---- */
    if (init_mpu6050(g_i2c_fd) != 0) {
        fprintf(stderr, "MPU-6050 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Write CSV header if file is empty ---- */
    if (ftell(g_log_fp) == 0) {
        fprintf(g_log_fp, "timestamp,gyro_x,gyro_y,gyro_z\n");
        fflush(g_log_fp);
    }

    printf("MPU-6050 logging to %s at %d Hz. Press Ctrl+C to stop.\n",
           LOG_FILE, SAMPLE_HZ);

    /* ---- Main sampling loop ---- */
    struct timespec next;
    clock_gettime(CLOCK_MONOTONIC, &next);

    while (g_running) {
        float gx, gy, gz;
        if (read_gyro(g_i2c_fd, &gx, &gy, &gz) != 0) {
            fprintf(stderr, "Gyro read error; continuing.\n");
        } else {
            log_data(g_log_fp, gx, gy, gz);
        }

        /* Schedule next sample */
        next.tv_nsec += SAMPLE_PERIOD_NS;
        if (next.tv_nsec >= 1000000000L) {
            next.tv_sec  += 1;
            next.tv_nsec -= 1000000000L;
        }
        clock_nanosleep(CLOCK_MONOTONIC, TIMER_ABSTIME, &next, NULL);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

