    printf("  LOCK  : GPIO%d (active-low)\n", LOCK_BUTTON);
    printf("  UNLOCK: GPIO%d (active-low)\n", UNLOCK_BUTTON);
    printf("Press Ctrl-C to exit.\n");

    /* ---- main loop ---- */
    while (g_running) {
        int lock_state  = read_button_debounced(LOCK_BUTTON);
        int unlock_state = read_button_debounced(UNLOCK_BUTTON);

        if (lock_state == 0) {
            printf("Locking door...\n");
            if (rotate(STEPS_PER_ROTATION, 1) < 0) {
                fprintf(stderr, "Error: failed to lock door\n");
            } else {
                printf("Door locked.\n");
            }
            /* Wait for button release to avoid re-triggering */
            while (g_running && read_button_debounced(LOCK_BUTTON) == 0) {
                gpioDelay(10000); /* 10 ms poll */
            }
        }

        if (unlock_state == 0) {
            printf("Unlocking door...\n");
            if (rotate(STEPS_PER_ROTATION, -1) < 0) {
                fprintf(stderr, "Error: failed to unlock door\n");
            } else {
                printf("Door unlocked.\n");
            }
            while (g_running && read_button_debounced(UNLOCK_BUTTON) == 0) {
                gpioDelay(10000);
            }
        }

        gpioDelay(10000); /* 10 ms idle poll */
    }

    /* ---- graceful shutdown ---- */
    printf("\nShutting down...\n");
    deenergize();
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

