#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define LOG_FILE "distance_log.txt"
#define TIMEOUT_US 50000
#define TRIGGER_PULSE_US 10
#define SAMPLE_INTERVAL_S 1
#define SETTLE_DELAY_US 60000

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static long long get_time_us(void) {
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
        return 0;
    }
    return (long long)ts.tv_sec * 1000000LL + (long long)ts.tv_nsec / 1000LL;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set trigger pin %d as output\n", TRIGGER_PIN);
        return -1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set echo pin %d as input\n", ECHO_PIN);
        return -1;
    }
    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialise trigger pin low\n");
        return -1;
    }
    return 0;
}

static int trigger_sensor(void) {
    if (gpioWrite(TRIGGER_PIN, 1) != 0) {
        fprintf(stderr, "Failed to set trigger high\n");
        return -1;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "Failed to set trigger low\n");
        return -1;
    }
    return 0;
}

static long long measure_echo(void) {
    long long start_time = 0, end_time = 0;
    long long timeout_start;

    timeout_start = get_time_us();
    while (gpioRead(ECHO_PIN) == 0) {
        if (get_time_us() - timeout_start > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo rising edge\n");
            return -1;
        }
    }
    start_time = get_time_us();

    timeout_start = get_time_us();
    while (gpioRead(ECHO_PIN) == 1) {
        if (get_time_us() - timeout_start > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo falling edge\n");
            return -1;
        }
    }
    end_time = get_time_us();

    return end_time - start_time;
}

static float calculate_distance(long long pulse_duration_us) {
    return (float)pulse_duration_us / 2.0f / 10000.0f;
}

static int log_distance(float distance) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }
    if (fprintf(log_file, "%.2f\n", distance) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(log_file) != 0) {
        fprintf(stderr, "Failed to flush log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (init_gpio() != 0) {
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return 1;
    }

    printf("HC-SR04 distance logger started. Press Ctrl+C to exit.\n");

    while (running) {
        if (trigger_sensor() != 0) {
            log_distance(-1.0f);
            gpioDelay(SAMPLE_INTERVAL_S * 1000000);
            continue;
        }

        long long pulse_duration = measure_echo();
        if (pulse_duration < 0) {
            log_distance(-1.0f);
        } else {
            float distance = calculate_distance(pulse_duration);
            if (log_distance(distance) != 0) {
                fprintf(stderr, "Logging failed\n");
            }
        }

        gpioDelay(SETTLE_DELAY_US);
    }

    printf("\nShutting down...\n");
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
    printf("Cleanup complete.\n");
    return 0;
}

