#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define RELAY_GPIO 18
#define POLL_DELAY_US 100000
#define MAX_RETRIES 3

#define VL53L1X_REG_SOFT_RESET 0x000B
#define VL53L1X_REG_VHV_CONFIG 0x000C
#define VL53L1X_REG_PHASECAL 0x0010
#define VL53L1X_REG_RANGE_CONFIG 0x001E
#define VL53L1X_REG_INTERMEASUREMENT 0x001B
#define VL53L1X_REG_SYSTEM_THRESH_HIGH 0x001C
#define VL53L1X_REG_SYSTEM_THRESH_LOW 0x001D
#define VL53L1X_REG_SYSTEM_CONFIG 0x001F
#define VL53L1X_REG_SYSTEM_INTERRUPT 0x0014
#define VL53L1X_REG_RESULT_INTERRUPT_STATUS 0x0044
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x004D
#define VL53L1X_REG_RESULT_DISTANCE 0x0096

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value) {
    char buf[3] = { (char)(reg >> 8), (char)(reg & 0xFF), (char)value };
    return i2cWriteDevice(handle, buf, 3);
}

static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *buf, uint8_t len) {
    char reg_buf[2] = { (char)(reg >> 8), (char)(reg & 0xFF) };
    if (i2cWriteDevice(handle, reg_buf, 2) < 0) return -1;
    return i2cReadDevice(handle, (char *)buf, len);
}

static int vl53l1x_init(int handle) {
    if (i2c_write_reg16(handle, VL53L1X_REG_SOFT_RESET, 0x00) < 0) return -1;
    gpioDelay(1000);
    if (i2c_write_reg16(handle, VL53L1X_REG_SOFT_RESET, 0x01) < 0) return -1;
    gpioDelay(1000);
    if (i2c_write_reg16(handle, VL53L1X_REG_VHV_CONFIG, 0x0E) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_PHASECAL, 0x0B) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_RANGE_CONFIG, 0x00) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_INTERMEASUREMENT, 0x00) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_THRESH_HIGH, 0x00) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_THRESH_LOW, 0x00) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_CONFIG, 0x01) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_INTERRUPT, 0x01) < 0) return -1;
    return 0;
}

static int vl53l1x_read_distance(int handle, uint16_t *distance) {
    uint8_t status = 0;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_INTERRUPT, 0x01) < 0) {
            retries++;
            gpioDelay(1000);
            continue;
        }
        gpioDelay(10000);

        if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_INTERRUPT_STATUS, &status, 1) < 0) {
            retries++;
            gpioDelay(1000);
            continue;
        }

        if (status & 0x01) {
            uint8_t range_status = 0;
            if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_RANGE_STATUS, &range_status, 1) < 0) {
                retries++;
                gpioDelay(1000);
                continue;
            }
            if (range_status == 0x00) {
                uint8_t dist_buf[2] = {0};
                if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_DISTANCE, dist_buf, 2) < 0) {
                    retries++;
                    gpioDelay(1000);
                    continue;
                }
                *distance = ((uint16_t)dist_buf[0] << 8) | dist_buf[1];
                if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_INTERRUPT, 0x01) < 0) {
                    retries++;
                    gpioDelay(1000);
                    continue;
                }
                return 0;
            }
        }
        retries++;
        gpioDelay(1000);
    }
    return -1;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %s\n", I2C_BUS, VL53L1X_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (vl53l1x_init(i2c_handle) < 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("VL53L1X distance sensor started. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t distance = 0;
        if (vl53l1x_read_distance(i2c_handle, &distance) == 0) {
            printf("Distance: %u mm\n", distance);
            if (distance <= 500) {
                gpioWrite(RELAY_GPIO, 1);
            } else {
                gpioWrite(RELAY_GPIO, 0);
            }
        } else {
            fprintf(stderr, "Error reading distance from VL53L1X\n");
        }
        gpioDelay(POLL_DELAY_US);
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

