    sigaction(SIGTERM, &sa, NULL);

    printf("VL53L1X distance sensor started. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t distance = 0;
        if (vl53l1x_read_distance(i2c_handle, &distance) == 0) {
            printf("Distance: %u mm\n", distance);
            if (distance <= 500) {
                gpioWrite(RELAY_GPIO, 1);
            } else {
                gpioWrite(RELAY_GPIO, 0);
            }
        } else {
            fprintf(stderr, "Error reading distance from VL53L1X\n");
        }
        gpioDelay(POLL_DELAY_US);
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

