/*
 * MPU-6050 Gyroscope Reader for Raspberry Pi 3 Model B+
 * Bus: /dev/i2c-1 (GPIO2=SDA, GPIO3=SCL)
 * Build: gcc -O2 -Wall -o mpu6050 mpu6050.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- MPU-6050 constants (per datasheet) ---- */
#define MPU6050_ADDR        0x68
#define MPU6050_WHO_AM_I    0x75
#define MPU6050_WHO_AM_I_VAL 0x68

#define PWR_MGMT_1          0x6B
#define GYRO_CONFIG         0x1B
#define GYRO_XOUT_H         0x43

#define GYRO_SCALE_250DPS   250.0f
#define GYRO_SCALE_500DPS   500.0f
#define GYRO_SCALE_1000DPS  1000.0f
#define GYRO_SCALE_2000DPS  2000.0f

#define GYRO_SENSITIVITY_250DPS  (GYRO_SCALE_250DPS / 32768.0f)
#define GYRO_SENSITIVITY_500DPS  (GYRO_SCALE_500DPS / 32768.0f)
#define GYRO_SENSITIVITY_1000DPS (GYRO_SCALE_1000DPS / 32768.0f)
#define GYRO_SENSITIVITY_2000DPS (GYRO_SCALE_2000DPS / 32768.0f)

typedef struct {
    float x, y, z;
} gyro_data_t;

static volatile sig_atomic_t g_running = 1;
static int g_fd = -1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *dst, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, dst, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: got %zd of %zu (%s)\n",
                reg, n, len, strerror(errno));
        return -1;
    }
    return 0;
}

static int mpu6050_init(int fd)
{
    uint8_t who;
    if (i2c_read_burst(fd, MPU6050_WHO_AM_I, &who, 1) < 0)
        return -1;
    if (who != MPU6050_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who, MPU6050_WHO_AM_I_VAL);
        return -1;
    }

    /* Wake up: clear SLEEP bit (bit 6) in PWR_MGMT_1 */
    if (i2c_write_byte(fd, PWR_MGMT_1, 0x00) < 0)
        return -1;
    usleep(100000); /* allow oscillator to stabilize */

    /* Gyro config: ±250 °/s (FS_SEL = 0) */
    if (i2c_write_byte(fd, GYRO_CONFIG, 0x00) < 0)
        return -1;

    return 0;
}

static int read_gyro(int fd, gyro_data_t *out)
{
    uint8_t raw[6];
    if (i2c_read_burst(fd, GYRO_XOUT_H, raw, sizeof(raw)) < 0)
        return -1;

    int16_t rx = (int16_t)((raw[0] << 8) | raw[1]);
    int16_t ry = (int16_t)((raw[2] << 8) | raw[3]);
    int16_t rz = (int16_t)((raw[4] << 8) | raw[5]);

    /* ±250 °/s range => 131 LSB/°/s */
    const float scale = GYRO_SENSITIVITY_250DPS;
    out->x = (float)rx / scale;
    out->y = (float)ry / scale;
    out->z = (float)rz / scale;
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_fd = open("/dev/i2c-1", O_RDWR);
    if (g_fd < 0) {
        perror("open /dev/i2c-1");
        return EXIT_FAILURE;
    }

    if (ioctl(g_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(g_fd);
        return EXIT_FAILURE;
    }

    if (mpu6050_init(g_fd) < 0) {
        fprintf(stderr, "MPU-6050 initialization failed.\n");
        close(g_fd);
        return EXIT_FAILURE;
    }

    printf("MPU-6050 initialized. Logging angular velocity (°/s)...\n");

    while (g_running) {
        gyro_data_t d;
        if (read_gyro(g_fd, &d) < 0) {
            fprintf(stderr, "Gyro read error; continuing.\n");
            usleep(100000);
            continue;
        }

        printf("X: %7.2f  Y: %7.2f  Z: %7.2f\n", d.x, d.y, d.z);
        fflush(stdout);
        usleep(100000); /* 100 ms */
    }

    printf("\nExiting cleanly.\n");
    if (g_fd >= 0)
        close(g_fd);
    return EXIT_SUCCESS;
}

