#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_RELAYS 4
#define RELAY_ON_TIME 5
#define CYCLE_INTERVAL 86400
#define POLL_INTERVAL 60
#define LOG_FILE "watering_log.txt"

static const unsigned int relay_pins[NUM_RELAYS] = {17, 18, 27, 22};

static volatile sig_atomic_t running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *lines[NUM_RELAYS];

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_watering_event(void) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }
    char ts[64];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }
    if (fprintf(fp, "%s\n", ts) < 0) {
        perror("fprintf");
        fclose(fp);
        return -1;
    }
    if (fclose(fp) != 0) {
        perror("fclose");
        return -1;
    }
    return 0;
}

static int set_relay(int idx, int val) {
    if (gpiod_line_set_value(lines[idx], val) < 0) {
        perror("gpiod_line_set_value");
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (lines[i]) {
            gpiod_line_set_value(lines[i], 1);
            gpiod_line_release(lines[i]);
            lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = gpiod_chip_get_line(chip, relay_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "gpiod_chip_get_line failed for GPIO%u\n", relay_pins[i]);
            cleanup();
            return EXIT_FAILURE;
        }
        if (gpiod_line_request_output(lines[i], "watering", 1) < 0) {
            fprintf(stderr, "gpiod_line_request_output failed for GPIO%u\n", relay_pins[i]);
            cleanup();
            return EXIT_FAILURE;
        }
    }

    time_t last_cycle = time(NULL);
    if (last_cycle == (time_t)-1) {
        perror("time");
        cleanup();
        return EXIT_FAILURE;
    }

    while (running) {
        time_t now = time(NULL);
        if (now == (time_t)-1) {
            perror("time");
            break;
        }

        if (now - last_cycle >= CYCLE_INTERVAL) {
            if (log_watering_event() < 0) {
                fprintf(stderr, "Warning: failed to log watering event\n");
            }

            for (int i = 0; i < NUM_RELAYS && running; i++) {
                if (set_relay(i, 0) < 0) {
                    fprintf(stderr, "Failed to activate relay %d\n", i);
                    break;
                }
                sleep(RELAY_ON_TIME);
                if (set_relay(i, 1) < 0) {
                    fprintf(stderr, "Failed to deactivate relay %d\n", i);
                    break;
                }
            }

            last_cycle = now;
        }

        for (int i = 0; i < POLL_INTERVAL && running; i++) {
            sleep(1);
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

