#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define NUM_RELAYS 4
#define PWM_FREQUENCY 1000
#define PWM_RANGE 255
#define LOG_FILE "smart_lighting.log"
#define SUNRISE_DURATION 1800

const int relay_pins[NUM_RELAYS] = {17, 18, 27, 22};

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "[%s] %s\n", timestamp, message);
    fclose(fp);
}

int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpioSetMode(relay_pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d to output mode\n", relay_pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioSetPWMfrequency(relay_pins[i], PWM_FREQUENCY) < 0) {
            fprintf(stderr, "Failed to set PWM frequency for GPIO %d\n", relay_pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioSetPWMrange(relay_pins[i], PWM_RANGE) < 0) {
            fprintf(stderr, "Failed to set PWM range for GPIO %d\n", relay_pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioPWM(relay_pins[i], 0) != 0) {
            fprintf(stderr, "Failed to initialize PWM for GPIO %d\n", relay_pins[i]);
            gpioTerminate();
            return -1;
        }
    }
    return 0;
}

void set_relay_intensity(int pin, int intensity) {
    if (gpioPWM(pin, intensity) != 0) {
        fprintf(stderr, "Failed to set PWM for GPIO %d\n", pin);
    }
}

void sunrise_sequence() {
    int step_duration = SUNRISE_DURATION / 255;
    for (int intensity = 0; intensity <= 255 && program_running; intensity++) {
        for (int i = 0; i < NUM_RELAYS; i++) {
            set_relay_intensity(relay_pins[i], intensity);
        }
