/*
 * MPU-6050 Gyroscope Monitor with LED Threshold Indicator
 * Board:  Raspberry Pi 3 Model B+
 * Library: pigpio (modern, actively maintained)
 *
 * Wiring:
 *   MPU-6050 SDA -> GPIO2 (BCM 2, I2C bus 1 SDA)
 *   MPU-6050 SCL -> GPIO3 (BCM 3, I2C bus 1 SCL)
 *   MPU-6050 VCC -> 3.3 V
 *   MPU-6050 GND -> GND
 *   LED anode   -> GPIO17 (BCM 17) via 330 ohm resistor
 *   LED cathode -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o gyro_monitor gyro_monitor.c -lpigpio -lrt
 * Run:
 *   sudo ./gyro_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Configuration ---- */
#define I2C_BUS            1
#define MPU6050_ADDR       0x68   /* AD0 tied to GND */

#define REG_SMPLRT_DIV     0x19
#define REG_GYRO_CONFIG    0x1B
#define REG_GYRO_XOUT_H    0x43
#define REG_PWR_MGMT_1     0x6B

#define LED_GPIO           17
#define THRESHOLD_DPS      250.0f
#define SAMPLE_PERIOD_US   50000  /* 20 Hz */
#define BUFFER_SIZE        100
#define MAX_REINIT_ATTEMPTS 3

/* ---- Data Structures ---- */
typedef struct {
    struct timespec timestamp;
    float x, y, z;
} gyro_data_t;

typedef struct {
    gyro_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

/* ---- Globals ---- */
static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

/* ---- Prototypes ---- */
static int  init_mpu6050(void);
static int  read_gyro_data(float *x, float *y, float *z);
static void add_to_buffer(circular_buffer_t *buf, const gyro_data_t *d);
static void check_threshold(const gyro_data_t *d);
static void signal_handler(int sig);
static void cleanup(void);

/* ---- MPU-6050 Initialization ---- */
static int init_mpu6050(void) {
    /* Wake up: clear SLEEP bit, use internal 8 MHz clock */
    if (i2cWriteByteData(i2c_handle, REG_PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: failed to write PWR_MGMT_1 (0x6B)\n");
        return -1;
    }
    gpioDelay(100000); /* 100 ms settle */

    /* Sample rate divider = 7 -> 1 kHz / (1 + 7) = 125 Hz internal */
    if (i2cWriteByteData(i2c_handle, REG_SMPLRT_DIV, 0x07) < 0) {
        fprintf(stderr, "Error: failed to write SMPLRT_DIV (0x19)\n");
        return -1;
    }

    /* Gyro config: FS_SEL = 0 (±250 °/s) */
    if (i2cWriteByteData(i2c_handle, REG_GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: failed to write GYRO_CONFIG (0x1B)\n");
        return -1;
    }

    return 0;
}

/* ---- Read Gyroscope Data ---- */
static int read_gyro_data(float *x, float *y, float *z) {
    char buf[6];
    int16_t raw_x, raw_y, raw_z;

    if (i2cReadI2CBlockData(i2c_handle, REG_GYRO_XOUT_H, buf, 6) != 6) {
        fprintf(stderr, "Error: failed to read 6 bytes from GYRO_XOUT_H (0x43)\n");
        return -1;
    }

    raw_x = (int16_t)((buf[0] << 8) | (uint8_t)buf[1]);
    raw_y = (int16_t)((buf[2] << 8) | (uint8_t)buf[3]);
    raw_z = (int16_t)((buf[4] << 8) | (uint8_t)buf[5]);

    /* ±250 °/s range => 131 LSB/°/s */
    *x = (float)raw_x / 131.0f;
    *y = (float)raw_y / 131.0f;
    *z = (float)raw_z / 131.0f;

    return 0;
}

/* ---- Circular Buffer Operations ---- */
static void add_to_buffer(circular_buffer_t *buf, const gyro_data_t *d) {
    buf->data[buf->head] = *d;
    buf->head = (buf->head + 1) % BUFFER_SIZE;
    if (buf->count < BUFFER_SIZE) buf->count++;
}

/* ---- Threshold Check & LED Control ---- */
static void check_threshold(const gyro_data_t *d) {
    bool above = (fabsf(d->x) > THRESHOLD_DPS ||
                  fabsf(d->y) > THRESHOLD_DPS ||
                  fabsf(d->z) > THRESHOLD_DPS);

    gpioWrite(LED_GPIO, above ? 1 : 0);
}

/* ---- Signal Handler ---- */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* ---- Cleanup ---- */
static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

/* ---- Main ---- */
int main(void) {
    circular_buffer_t gyro_buffer = {0};
    float x, y, z;
    int reinit_attempts = 0;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure LED GPIO */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    /* Open I2C bus to MPU-6050 */
    i2c_handle = i2cOpen(I2C_BUS, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d). Check wiring and address.\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize MPU-6050 */
    if (init_mpu6050() < 0) {
        fprintf(stderr, "Error: MPU-6050 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Register signal handlers */
    signal(SIGINT,  signal_handler);
    signal(SIGTERM, signal_handler);

    printf("MPU-6050 monitoring started. Sampling at 20 Hz. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (!terminate) {
        struct timespec ts;
        clock_gettime(CLOCK_MONOTONIC, &ts);

        if (read_gyro_data(&x, &y, &z) == 0) {
            gyro_data_t sample = { .timestamp = ts, .x = x, .y = y, .z = z };
            add_to_buffer(&gyro_buffer, &sample);
            check_threshold(&sample);
            reinit_attempts = 0;
        } else {
            fprintf(stderr, "Warning: gyro read failed. Attempting re-initialization...\n");
            if (i2c_handle >= 0) {
                i2cClose(i2c_handle);
                i2c_handle = -1;
            }
            gpioDelay(1000000); /* 1 s backoff */

            for (int attempt = 0; attempt < MAX_REINIT_ATTEMPTS && !terminate; attempt++) {
                i2c_handle = i2cOpen(I2C_BUS, MPU6050_ADDR, 0);
                if (i2c_handle >= 0) {
                    if (init_mpu6050() == 0) {
                        printf("Re-initialization successful.\n");
                        break;
                    } else {
                        fprintf(stderr, "Re-init failed (attempt %d/%d)\n", attempt + 1, MAX_REINIT_ATTEMPTS);
                    }
                } else {
                    fprintf(stderr, "i2cOpen failed (attempt %d/%d)\n", attempt + 1, MAX_REINIT_ATTEMPTS);
                }
                gpioDelay(500000); /* 0.5 s between retries */
            }

            if (i2c_handle < 0) {
                fprintf(stderr, "Fatal: re-initialization failed after %d attempts. Exiting.\n", MAX_REINIT_ATTEMPTS);
                terminate = 1;
            }
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* Graceful shutdown */
    cleanup();
    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

