#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 3900000
#define SPI_MODE 0
#define LED_GPIO 17
#define THRESHOLD 200.0
#define BUFFER_SIZE 64
#define SAMPLE_DELAY_US 10000

#define MPU6050_REG_SMPLRT_DIV 0x19
#define MPU6050_REG_GYRO_CONFIG 0x1B
#define MPU6050_REG_GYRO_XOUT_H 0x43
#define MPU6050_REG_PWR_MGMT_1 0x6B

typedef struct {
    struct timespec timestamp;
    float x, y, z;
} gyro_data_t;

static gyro_data_t gyro_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int spi_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int spi_read_register(uint8_t reg, uint8_t *value) {
    char tx[2] = {(char)(reg | 0x80), 0x00};
    char rx[2] = {0};
    if (spiXfer(spi_handle, tx, rx, 2) != 2) return -1;
    *value = (uint8_t)rx[1];
    return 0;
}

static int spi_write_register(uint8_t reg, uint8_t value) {
    char tx[2] = {(char)(reg & 0x7F), (char)value};
    if (spiWrite(spi_handle, tx, 2) != 2) return -1;
    return 0;
}

static int read_gyro_data(float *x, float *y, float *z) {
    char tx[7] = {0};
    char rx[7] = {0};
    tx[0] = (char)(MPU6050_REG_GYRO_XOUT_H | 0x80 | 0x40);
    if (spiXfer(spi_handle, tx, rx, 7) != 7) return -1;
    int16_t raw_x = (int16_t)(((uint8_t)rx[1] << 8) | (uint8_t)rx[2]);
    int16_t raw_y = (int16_t)(((uint8_t)rx[3] << 8) | (uint8_t)rx[4]);
    int16_t raw_z = (int16_t)(((uint8_t)rx[5] << 8) | (uint8_t)rx[6]);
    *x = (float)raw_x / 131.0;
    *y = (float)raw_y / 131.0;
    *z = (float)raw_z / 131.0;
    return 0;
}

static void add_to_buffer(float x, float y, float z) {
    gyro_buffer[buffer_index].timestamp = (struct timespec){0, 0};
    clock_gettime(CLOCK_REALTIME, &gyro_buffer[buffer_index].timestamp);
    gyro_buffer[buffer_index].x = x;
    gyro_buffer[buffer_index].y = y;
    gyro_buffer[buffer_index].z = z;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

static void check_threshold(float x, float y, float z) {
    if (x > THRESHOLD || x < -THRESHOLD ||
        y > THRESHOLD || y < -THRESHOLD ||
        z > THRESHOLD || z < -THRESHOLD) {
        gpioWrite(LED_GPIO, 1);
        gpioDelay(500000);
        gpioWrite(LED_GPIO, 0);
        gpioDelay(500000);
    }
}

static void print_buffer(void) {
    printf("Timestamp,X,Y,Z\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int idx = (buffer_index + i) % BUFFER_SIZE;
        char ts[32];
        struct tm *tm_info = localtime(&gyro_buffer[idx].timestamp.tv_sec);
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm_info);
        printf("%s.%09ld,%.2f,%.2f,%.2f\n", ts, gyro_buffer[idx].timestamp.tv_nsec, gyro_buffer[idx].x, gyro_buffer[idx].y, gyro_buffer[idx].z);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed\n");
        gpioTerminate();
        return 1;
    }
    if (spi_write_register(MPU6050_REG_PWR_MGMT_1, 0x00) != 0 ||
        spi_write_register(MPU6050_REG_SMPLRT_DIV, 0x07) != 0 ||
        spi_write_register(MPU6050_REG_GYRO_CONFIG, 0x00) != 0) {
        fprintf(stderr, "MPU6050 configuration failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);
    signal(SIGINT, signal_handler);
    float x, y, z;
    while (!terminate) {
        if (read_gyro_data(&x, &y, &z) == 0) {
            add_to_buffer(x, y, z);
            check_threshold(x, y, z);
        } else {
            fprintf(stderr, "Gyro read error\n");
        }
        gpioDelay(SAMPLE_DELAY_US);
    }
    spiClose(spi_handle);
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
    print_buffer();
    return 0;
}

