#define ACCEL_XOUT_H 0x3B
#define LED_PIN      21
#define THRESHOLD    45.0
#define SAMPLE_US   100000

static int i2c_handle = -1;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_mpu6050(void) {
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: failed to wake MPU6050\n");
        return -1;
    }
    gpioDelay(100000);
    return 0;
}

static int read_accel(int16_t *ax, int16_t *ay, int16_t *az) {
    char buf[6];
    if (i2cReadI2CBlockData(i2c_handle, ACCEL_XOUT_H, buf, 6) != 6) {
        fprintf(stderr, "Error: failed to read accelerometer data\n");
        return -1;
    }
    *ax = (int16_t)((buf[0] << 8) | buf[1]);
    *ay = (int16_t)((buf[2] << 8) | buf[3]);
    *az = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

static void calculate_tilt(int16_t ax, int16_t ay, int16_t az,
                           float *roll, float *pitch) {
    float axf = (float)ax, ayf = (float)ay, azf = (float)az;
    *roll  = atan2f(ayf, azf) * 180.0f / (float)M_PI;
    *pitch = atan2f(-axf, sqrtf(ayf * ayf + azf * azf)) * 180.0f / (float)M_PI;
}

