    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    FILE *fp = fopen("tilt_log.txt", "a");
    if (fp) {
        fprintf(fp, "%s,%.2f,%.2f\n", timestamp, roll, pitch);
        fclose(fp);
    } else {
        fprintf(stderr, "Error: failed to open tilt_log.txt\n");
    }
}

static void control_led(float roll, float pitch) {
    int on = (fabsf(roll) > THRESHOLD || fabsf(pitch) > THRESHOLD) ? 1 : 0;
    gpioWrite(LED_PIN, on);
}

