#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

#define SI1145_ADDR 0x60
#define I2C_BUS "/dev/i2c-1"
#define LED_GPIO 17
#define PROXIMITY_THRESHOLD 100
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10
#define POLL_INTERVAL_MS 100

#define SI1145_REG_PART_ID 0x00
#define SI1145_REG_HW_KEY 0x07
#define SI1145_REG_MEAS_RATE0 0x08
#define SI1145_REG_ALS_VIS_DATA0 0x22
#define SI1145_REG_PS1_DATA0 0x24

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_si1145(int fd) {
    uint8_t part_id;
    if (i2c_read_reg8(fd, SI1145_REG_PART_ID, &part_id) < 0) return -1;
    if (part_id != 0x45) {
        fprintf(stderr, "Unexpected Part ID: 0x%02X (expected 0x45)\n", part_id);
        return -1;
    }
    if (i2c_write_reg8(fd, SI1145_REG_HW_KEY, 0x17) < 0) return -1;
    if (i2c_write_reg8(fd, SI1145_REG_MEAS_RATE0, 0x08) < 0) return -1;
    return 0;
}

static int read_si1145(int fd, uint16_t *ambient_light, uint16_t *proximity) {
    uint8_t als_low, als_high, prox_low, prox_high;
    if (i2c_read_reg8(fd, SI1145_REG_ALS_VIS_DATA0, &als_low) < 0) return -1;
    if (i2c_read_reg8(fd, SI1145_REG_ALS_VIS_DATA0 + 1, &als_high) < 0) return -1;
    if (i2c_read_reg8(fd, SI1145_REG_PS1_DATA0, &prox_low) < 0) return -1;
    if (i2c_read_reg8(fd, SI1145_REG_PS1_DATA0 + 1, &prox_high) < 0) return -1;
    *ambient_light = (uint16_t)((als_high << 8) | als_low);
    *proximity = (uint16_t)((prox_high << 8) | prox_low);
    return 0;
}

static void log_data(FILE *fp, uint16_t ambient_light, uint16_t proximity) {
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s,AmbientLight:%u,Proximity:%u\n", timestamp, ambient_light, proximity);
    fflush(fp);
}

static void cleanup(void) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, SI1145_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        cleanup();
        return 1;
    }
    if (init_si1145(i2c_fd) < 0) {
        fprintf(stderr, "Si1145 initialization failed\n");
        cleanup();
        return 1;
    }
    log_file = fopen("biometric_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup();
        return 1;
    }
    if (gpio_set_mode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_GPIO);
        cleanup();
        return 1;
    }
    gpio_write(LED_GPIO, 0);
    printf("Si1145 sensor initialized. Logging to biometric_log.txt\n");
    while (running) {
        uint16_t ambient_light = 0, proximity = 0;
        int retries = 0;
        int success = 0;
        while (retries < MAX_RETRIES && running) {
            if (read_si1145(i2c_fd, &ambient_light, &proximity) == 0) {
                success = 1;
                break;
            }
            retries++;
            if (retries < MAX_RETRIES) {
                usleep(RETRY_DELAY_MS * 1000);
            }
        }
        if (success) {
            log_data(log_file, ambient_light, proximity);
            if (proximity > PROXIMITY_THRESHOLD) {
                gpio_write(LED_GPIO, 1);
            } else {
                gpio_write(LED_GPIO, 0);
            }
        } else {
            fprintf(stderr, "Failed to read sensor data after %d retries\n", MAX_RETRIES);
        }
        usleep(POLL_INTERVAL_MS * 1000);
    }
    gpio_write(LED_GPIO, 0);
    cleanup();
    printf("Program terminated gracefully\n");
    return 0;
}

