#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define CS_PIN 8
#define SAMPLE_DELAY_US 10000
#define MAX_RETRIES 3

#define ADXRS290_REG_XGYRO_OUT 0x04
#define ADXRS290_REG_YGYRO_OUT 0x05
#define ADXRS290_READ_BIT 0x80

static int spi_handle = -1;
static FILE *fp = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int spi_init(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(CS_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set CS pin mode\n");
        gpioTerminate();
        return -1;
    }
    gpioWrite(CS_PIN, 1);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return -1;
    }
    return 0;
}

static int spi_read_register(uint8_t reg, int16_t *value) {
    char tx[2] = { (char)(reg | ADXRS290_READ_BIT), 0x00 };
    char rx[2] = { 0 };

    gpioWrite(CS_PIN, 0);
    int ret = spiXfer(spi_handle, tx, rx, 2);
    gpioWrite(CS_PIN, 1);

    if (ret != 2) {
        fprintf(stderr, "SPI transfer failed for reg 0x%02X (ret=%d)\n", reg, ret);
        return -1;
    }

    *value = (int16_t)((rx[1] << 8) | (rx[0] & 0xFF));
    return 0;
}

static int read_gyro_data(int16_t *x_rate, int16_t *y_rate) {
    if (spi_read_register(ADXRS290_REG_XGYRO_OUT, x_rate) != 0) {
        return -1;
    }
    if (spi_read_register(ADXRS290_REG_YGYRO_OUT, y_rate) != 0) {
        return -1;
    }
    return 0;
}

static int log_data(FILE *f, int16_t x_rate, int16_t y_rate) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return -1;
    }

