#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR_1_PIN 23
#define SENSOR_2_PIN 24
#define ALERT_PIN 17
#define SEISMIC_THRESHOLD_MS 500
#define ALERT_DURATION_MS 2000
#define LOG_FILE "seismic_events.txt"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm tm_info;
    char timestamp[32];
    if (localtime_r(&now, &tm_info) != NULL) {
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);
    } else {
        strncpy(timestamp, "UNKNOWN", sizeof(timestamp));
        timestamp[sizeof(timestamp) - 1] = '\0';
    }
    fprintf(log_file, "%s - %s\n", timestamp, message);
    fflush(log_file);
}

static void sensor_callback(int gpio, int level, uint32_t tick, void *userdata) {
    (void)tick;
    (void)userdata;
    if (level != 1 && level != 0) return;

    static uint32_t sensor1_start = 0;
    static uint32_t sensor2_start = 0;
    static int alert_active = 0;

    if (gpio == SENSOR_1_PIN) {
        if (level == 1) {
            sensor1_start = tick;
        } else {
            sensor1_start = 0;
        }
    } else if (gpio == SENSOR_2_PIN) {
        if (level == 1) {
            sensor2_start = tick;
        } else {
            sensor2_start = 0;
        }
    }

    if (sensor1_start != 0 && sensor2_start != 0) {
        uint32_t diff = sensor1_start > sensor2_start
                          ? sensor1_start - sensor2_start
                          : sensor2_start - sensor1_start;
        if (diff >= SEISMIC_THRESHOLD_MS * 1000) {
            if (!alert_active) {
                alert_active = 1;
                gpioWrite(ALERT_PIN, 1);
                log_event("Seismic event detected!");
                printf("Seismic event detected!\n");
                gpioSetTimerFuncEx(0, ALERT_DURATION_MS, NULL, NULL);
            }
        }
    }
}

static void timer_callback(void *userdata) {
    (void)userdata;
    gpioWrite(ALERT_PIN, 0);
    alert_active = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0 ||
        gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0 ||
        gpioSetMode(ALERT_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_DOWN) != 0 ||
        gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down resistors\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFuncEx(SENSOR_1_PIN, sensor_callback, NULL) != 0 ||
        gpioSetAlertFuncEx(SENSOR_2_PIN, sensor_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set alert callbacks\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetTimerFuncEx(0, ALERT_DURATION_MS, timer_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set timer callback\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to set signal handlers: %s\n", strerror(errno));
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Monitoring tilt sensors on GPIO%d and GPIO%d. Press Ctrl+C to exit.\n",
           SENSOR_1_PIN, SENSOR_2_PIN);

    while (running) {
        gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    gpioWrite(ALERT_PIN, 0);
    gpioSetAlertFuncEx(SENSOR_1_PIN, NULL, NULL);
    gpioSetAlertFuncEx(SENSOR_2_PIN, NULL, NULL);
    gpioSetTimerFuncEx(0, ALERT_DURATION_MS, NULL, NULL);
    fclose(log_file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

