#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0
#define LED_GPIO 17
#define THRESHOLD 20.0
#define BUFFER_SIZE 100
#define SAMPLE_DELAY_US 10000

#define ADXRS290_REG_XGYRO_OUT 0x04
#define ADXRS290_REG_TEMP_OUT 0x06
#define ADXRS290_REG_DIAG_STAT 0x08
#define ADXRS290_REG_SMPL_PRD 0x0A
#define ADXRS290_REG_AVG_CNT 0x0C
#define ADXRS290_REG_GLOB_CMD 0x0E

#define ADXRS290_GLOB_CMD_RESET 0x01
#define ADXRS290_GLOB_CMD_MODE_NORMAL 0x00

#define ADXRS290_DIAG_STAT_ERR_MASK 0x0F
#define ADXRS290_DIAG_STAT_TEMP_ERR 0x01
#define ADXRS290_DIAG_STAT_GYRO_ERR 0x02

#define ADXRS290_SMPL_PRD_100HZ 0x00
#define ADXRS290_AVG_CNT_8 0x00

#define ADXRS290_GYRO_SCALE 0.0087890625

typedef struct {
    struct timespec timestamp;
    float angular_rate;
} gyro_data_t;

static gyro_data_t gyro_buffer[BUFFER_SIZE];
static int buffer_head = 0;
static int buffer_tail = 0;
static int buffer_count = 0;

static int spi_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int spi_read_register(uint8_t reg, uint8_t *data, uint8_t len) {
    char tx[1 + len];
    char rx[1 + len];
    tx[0] = (char)(reg | 0x80);
    for (uint8_t i = 0; i < len; i++) {
        tx[i + 1] = 0x00;
    }
    if (spiXfer(spi_handle, tx, rx, 1 + len) != (int)(1 + len)) {
        return -1;
    }
    memcpy(data, rx + 1, len);
    return 0;
}

static int spi_write_register(uint8_t reg, uint8_t data) {
    char tx[2];
    tx[0] = (char)(reg & 0x7F);
    tx[1] = (char)data;
    if (spiWrite(spi_handle, tx, 2) != 2) {
        return -1;
    }
    return 0;
}

static int read_gyro_data(float *angular_rate) {
    uint8_t data[2];
    if (spi_read_register(ADXRS290_REG_XGYRO_OUT, data, 2) != 0) {
        return -1;
    }
    int16_t raw = (int16_t)((data[0] << 8) | data[1]);
    *angular_rate = (float)raw * ADXRS290_GYRO_SCALE;
    return 0;
}

static void add_to_buffer(float angular_rate) {
    clock_gettime(CLOCK_MONOTONIC, &gyro_buffer[buffer_head].timestamp);
    gyro_buffer[buffer_head].angular_rate = angular_rate;
    buffer_head = (buffer_head + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    } else {
        buffer_tail = (buffer_tail + 1) % BUFFER_SIZE;
    }
}

static void check_threshold(float angular_rate) {
    if (angular_rate > THRESHOLD) {
        gpioWrite(LED_GPIO, 1);
    } else {
        gpioWrite(LED_GPIO, 0);
    }
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED GPIO mode\n");
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    if (spi_write_register(ADXRS290_REG_GLOB_CMD, ADXRS290_GLOB_CMD_RESET) != 0) {
        fprintf(stderr, "Failed to reset gyroscope\n");
        cleanup();
        return EXIT_FAILURE;
    }
    gpioDelay(100000);

    if (spi_write_register(ADXRS290_REG_GLOB_CMD, ADXRS290_GLOB_CMD_MODE_NORMAL) != 0) {
        fprintf(stderr, "Failed to set normal mode\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (spi_write_register(ADXRS290_REG_SMPL_PRD, ADXRS290_SMPL_PRD_100HZ) != 0) {
        fprintf(stderr, "Failed to set sample period\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (spi_write_register(ADXRS290_REG_AVG_CNT, ADXRS290_AVG_CNT_8) != 0) {
        fprintf(stderr, "Failed to set averaging count\n");
        cleanup();
        return EXIT_FAILURE;
    }

    gpioDelay(100000);

    uint8_t diag_stat;
    if (spi_read_register(ADXRS290_REG_DIAG_STAT, &diag_stat, 1) != 0) {
        fprintf(stderr, "Failed to read diagnostic status\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (diag_stat & ADXRS290_DIAG_STAT_ERR_MASK) {
        fprintf(stderr, "Gyroscope diagnostic error: 0x%02X\n", diag_stat);
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Gyroscope monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        float angular_rate;
        if (read_gyro_data(&angular_rate) == 0) {
            add_to_buffer(angular_rate);
            check_threshold(angular_rate);
        } else {
            fprintf(stderr, "SPI read error\n");
        }
        gpioDelay(SAMPLE_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

