#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LAMP1_GPIO 17
#define LAMP2_GPIO 18
#define LAMP3_GPIO 27
#define PWM_FREQ 100
#define PWM_RANGE 255

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int set_lamp_brightness(int gpio, int brightness) {
    if (gpioPWM(gpio, brightness) < 0) {
        fprintf(stderr, "Error: failed to set PWM on GPIO %d\n", gpio);
        return -1;
    }
    return 0;
}

static int fade_lamp(int gpio, int duration_seconds) {
    if (duration_seconds <= 0) {
        fprintf(stderr, "Error: invalid duration %d for GPIO %d\n", duration_seconds, gpio);
        return -1;
    }

    int total_steps = duration_seconds * PWM_FREQ;
    if (total_steps <= 0) {
        total_steps = 1;
    }

    for (int step = 0; step <= total_steps && g_running; step++) {
        int brightness = (step * PWM_RANGE) / total_steps;
        if (set_lamp_brightness(gpio, brightness) < 0) {
            return -1;
        }
        gpioDelay(1000000 / PWM_FREQ);
    }

    if (!g_running) {
        return 0;
    }

    if (set_lamp_brightness(gpio, 0) < 0) {
        return -1;
    }
    return 0;
}

static void cleanup_lamps(void) {
    set_lamp_brightness(LAMP1_GPIO, 0);
    set_lamp_brightness(LAMP2_GPIO, 0);
    set_lamp_brightness(LAMP3_GPIO, 0);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <duration_seconds>\n", argv[0]);
        fprintf(stderr, "  duration_seconds: integer 1-3600\n");
        return EXIT_FAILURE;
    }

    char *endptr = NULL;
    long duration = strtol(argv[1], &endptr, 10);

    if (endptr == argv[1] || *endptr != '\0' || duration <= 0 || duration > 3600) {
        fprintf(stderr, "Error: invalid duration '%s'. Must be an integer 1-3600.\n", argv[1]);
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LAMP1_GPIO, PI_OUTPUT) < 0 ||
        gpioSetMode(LAMP2_GPIO, PI_OUTPUT) < 0 ||
        gpioSetMode(LAMP3_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(LAMP1_GPIO, PWM_FREQ) < 0 ||
        gpioSetPWMfrequency(LAMP2_GPIO, PWM_FREQ) < 0 ||
        gpioSetPWMfrequency(LAMP3_GPIO, PWM_FREQ) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(LAMP1_GPIO, PWM_RANGE) < 0 ||
        gpioSetPWMrange(LAMP2_GPIO, PWM_RANGE) < 0 ||
        gpioSetPWMrange(LAMP3_GPIO, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: failed to set PWM range\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (set_lamp_brightness(LAMP1_GPIO, PWM_RANGE) < 0 ||
        set_lamp_brightness(LAMP2_GPIO, PWM_RANGE) < 0 ||
        set_lamp_brightness(LAMP3_GPIO, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: failed to initialise lamps to full brightness\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Smart Sunset Simulator starting...\n");
    printf("Lamps on GPIO %d, %d, %d. Fading over %ld seconds.\n",
           LAMP1_GPIO, LAMP2_GPIO, LAMP3_GPIO, duration);
    printf("Press Ctrl+C to stop early.\n");
    fflush(stdout);

    if (!g_running) {
        cleanup_lamps();
        gpioTerminate();
        return EXIT_SUCCESS;
    }

    if (fade_lamp(LAMP1_GPIO, duration) < 0) {
        fprintf(stderr, "Error: fade for lamp 1 failed\n");
        cleanup_lamps();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (!g_running) {
        cleanup_lamps();
        gpioTerminate();
        return EXIT_SUCCESS;
    }

    if (fade_lamp(LAMP2_GPIO, duration) < 0) {
        fprintf(stderr, "Error: fade for lamp 2 failed\n");
        cleanup_lamps();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (!g_running) {
        cleanup_lamps();
        gpioTerminate();
        return EXIT_SUCCESS;
    }

    if (fade_lamp(LAMP3_GPIO, duration) < 0) {
        fprintf(stderr, "Error: fade for lamp 3 failed\n");
        cleanup_lamps();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("All lamps faded out. Exiting.\n");
    cleanup_lamps();
    gpioTerminate();
    return EXIT_SUCCESS;
}

