#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RED_PIN    17
#define YELLOW_PIN 22
#define GREEN_PIN  23
#define YELLOW2_PIN 24

#define RED_TIME    10
#define RED_YELLOW_TIME 2
#define GREEN_TIME  10
#define YELLOW_TIME 3

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int set_all_relays(int r, int y, int g, int y2) {
    if (gpioWrite(RED_PIN, r) < 0)    return -1;
    if (gpioWrite(YELLOW_PIN, y) < 0) return -1;
    if (gpioWrite(GREEN_PIN, g) < 0)  return -1;
    if (gpioWrite(YELLOW2_PIN, y2) < 0) return -1;
    return 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    if (gpioSetMode(RED_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(YELLOW_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(GREEN_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(YELLOW2_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO modes.\n");
        gpioTerminate();
        return -1;
    }

    /* Active-low relays: LOW = energized, HIGH = de-energized */
    if (set_all_relays(1, 1, 1, 1) < 0) {
        fprintf(stderr, "Error: failed to initialize all relay states.\n");
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void cleanup_gpio(void) {
    /* De-energize all relays (HIGH) before releasing */
    set_all_relays(0, 0, 0, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (init_gpio() < 0) {
        return EXIT_FAILURE;
    }

    printf("Traffic light simulation started. Press Ctrl+C to exit.\n");

    while (g_running) {
        printf("State: RED\n");
        if (set_all_relays(0, 1, 1, 1) < 0) break;
        sleep(RED_TIME);

        if (!g_running) break;

        printf("State: RED + YELLOW\n");
        if (set_all_relays(0, 0, 1, 1) < 0) break;
        sleep(RED_YELLOW_TIME);

        if (!g_running) break;

        printf("State: GREEN\n");
        if (set_all_relays(1, 1, 0, 1) < 0) break;
        sleep(GREEN_TIME);

        if (!g_running) break;

        printf("State: YELLOW\n");
        if (set_all_relays(1, 0, 1, 0) < 0) break;
        sleep(YELLOW_TIME);
    }

    cleanup_gpio();
    printf("\nTraffic light simulation stopped.\n");
    return EXIT_SUCCESS;
}

