    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(BUZZER_PIN, 0);
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

int main(void) {
    int consecutive_flame = 0;
    int last_flame_state = 1;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set flame sensor pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set buzzer pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(BUZZER_PIN, 0) != 0 || gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialize buzzer and LED states\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

