    while (program_running) {
        int flame_detected = (gpioRead(FLAME_SENSOR_PIN) == 0);

        if (flame_detected) {
            consecutive_flame++;
            if (consecutive_flame >= CONSECUTIVE_READS && last_flame_state != 0) {
                if (log_flame_detection() == 0) {
                    if (gpioWrite(BUZZER_PIN, 1) != 0 || gpioWrite(LED_PIN, 1) != 0) {
                        fprintf(stderr, "Failed to activate buzzer or LED\n");
                    }
                }
                last_flame_state = 0;
            }
        } else {
            consecutive_flame = 0;
            if (last_flame_state == 0) {
                if (gpioWrite(BUZZER_PIN, 0) != 0 || gpioWrite(LED_PIN, 0) != 0) {
                    fprintf(stderr, "Failed to deactivate buzzer or LED\n");
                }
                last_flame_state = 1;
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

