#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <pigpio.h>

#define SOLENOID_1_PIN 17
#define SOLENOID_2_PIN 27
#define DISPENSE_INTERVAL_MS 1000
#define SOLENOID_HALF_MS (DISPENSE_INTERVAL_MS / 2)
#define LOG_FILE "dispense_log.txt"

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static int log_dispense_event(int pin1, int pin2, int duration_ms) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s - Solenoid 1 (GPIO%d): %s, Solenoid 2 (GPIO%d): %s, Duration: %d ms\n",
            timestamp,
            pin1, (pin1 == 1) ? "ON" : "OFF",
            pin2, (pin2 == 1) ? "ON" : "OFF",
            duration_ms);

    if (fclose(fp) != 0) {
        perror("Error closing log file");
        return -1;
    }
    return 0;
}

static int dispense(int pin1, int pin2, int duration_ms) {
    if (gpioWrite(pin1, 1) != 0) {
        fprintf(stderr, "Error activating solenoid on GPIO%d\n", pin1);
        return -1;
    }
    if (gpioWrite(pin2, 1) != 0) {
        fprintf(stderr, "Error activating solenoid on GPIO%d\n", pin2);
        gpioWrite(pin1, 0);
        return -1;
    }

    gpioDelay(duration_ms * 1000);

    if (gpioWrite(pin1, 0) != 0) {
        fprintf(stderr, "Error deactivating solenoid on GPIO%d\n", pin1);
        return -1;
    }
    if (gpioWrite(pin2, 0) != 0) {
        fprintf(stderr, "Error deactivating solenoid on GPIO%d\n", pin2);
        return -1;
    }

    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SOLENOID_1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", SOLENOID_1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SOLENOID_2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", SOLENOID_2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(SOLENOID_1_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialize GPIO%d to LOW\n", SOLENOID_1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(SOLENOID_2_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialize GPIO%d to LOW\n", SOLENOID_2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
