#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MOTOR_A_FORWARD  17
#define MOTOR_A_BACKWARD 18
#define MOTOR_B_FORWARD  22
#define MOTOR_B_BACKWARD 23
#define ENA              24
#define ENB              25

#define KP 1.0
#define KI 0.01
#define KD 0.1

#define OBSTACLE_THRESHOLD 20.0
#define MAX_SPEED 255
#define MIN_SPEED -255
#define PWM_FREQ 1000
#define LOOP_DELAY_US 50000

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%d,%d\n",
            timestamp, tilt_error, distance, motor_a_speed, motor_b_speed);
    fflush(log_file);
}

static void set_motor_speed(int motor_a_speed, int motor_b_speed) {
    if (motor_a_speed > MAX_SPEED) motor_a_speed = MAX_SPEED;
    if (motor_a_speed < MIN_SPEED) motor_a_speed = MIN_SPEED;
    if (motor_b_speed > MAX_SPEED) motor_b_speed = MAX_SPEED;
    if (motor_b_speed < MIN_SPEED) motor_b_speed = MIN_SPEED;

    if (motor_a_speed > 0) {
        gpioWrite(MOTOR_A_FORWARD, 1);
        gpioWrite(MOTOR_A_BACKWARD, 0);
        gpioPWM(ENA, motor_a_speed);
    } else if (motor_a_speed < 0) {
        gpioWrite(MOTOR_A_FORWARD, 0);
        gpioWrite(MOTOR_A_BACKWARD, 1);
        gpioPWM(ENA, -motor_a_speed);
    } else {
        gpioWrite(MOTOR_A_FORWARD, 0);
        gpioWrite(MOTOR_A_BACKWARD, 0);
        gpioPWM(ENA, 0);
    }

    if (motor_b_speed > 0) {
        gpioWrite(MOTOR_B_FORWARD, 1);
        gpioWrite(MOTOR_B_BACKWARD, 0);
        gpioPWM(ENB, motor_b_speed);
    } else if (motor_b_speed < 0) {
        gpioWrite(MOTOR_B_FORWARD, 0);
        gpioWrite(MOTOR_B_BACKWARD, 1);
        gpioPWM(ENB, -motor_b_speed);
    } else {
        gpioWrite(MOTOR_B_FORWARD, 0);
        gpioWrite(MOTOR_B_BACKWARD, 0);
        gpioPWM(ENB, 0);
    }
}

static void obstacle_avoidance(void) {
    set_motor_speed(-MAX_SPEED, -MAX_SPEED);
    gpioDelay(500000);
    set_motor_speed(0, 0);
}

static void cleanup(void) {
    set_motor_speed(0, 0);
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    float tilt_error = 0.0;
    float distance = 0.0;
    int motor_a_speed = 0;
    int motor_b_speed = 0;
    float integral = 0.0;
    float previous_error = 0.0;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(MOTOR_A_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_A_BACKWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_BACKWARD, PI_OUTPUT);
    gpioSetMode(ENA, PI_OUTPUT);
    gpioSetMode(ENB, PI_OUTPUT);

    gpioSetPWMfrequency(ENA, PWM_FREQ);
    gpioSetPWMfrequency(ENB, PWM_FREQ);

    gpioWrite(ENA, 1);
    gpioWrite(ENB, 1);

    log_file = fopen("balance_log.txt", "w");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    fprintf(log_file, "timestamp,tilt_error,distance,motor_a_speed,motor_b_speed\n");
    fflush(log_file);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    srand((unsigned int)time(NULL));

    while (running) {
        tilt_error = (float)(rand() % 20000 - 10000) / 1000.0;
        distance = (float)(rand() % 380000 + 20000) / 100.0;

        float proportional = tilt_error;
        integral += tilt_error;
        float derivative = tilt_error - previous_error;
        float output = KP * proportional + KI * integral + KD * derivative;

        motor_a_speed = (int)output;
        motor_b_speed = (int)output;

        if (distance < OBSTACLE_THRESHOLD) {
            obstacle_avoidance();
        } else {
            set_motor_speed(motor_a_speed, motor_b_speed);
        }

        log_data(tilt_error, distance, motor_a_speed, motor_b_speed);
        previous_error = tilt_error;
        gpioDelay(LOOP_DELAY_US);
    }

    cleanup();
    return 0;
}

