/*
 * mood_light.c — Raspberry Pi 3 Model B+
 *
 * Captures audio via ALSA (8000 Hz, 16-bit mono, period 1024 frames)
 * and maps RMS amplitude to a common-cathode RGB LED (GPIO17=red,
 * GPIO18=green, GPIO27=blue) via software PWM using the driver
 * library (pigpio).
 *
 * Build:  gcc -O2 -Wall -Wextra -o mood_light mood_light.c -lpigpio -lasound
 * Run:    sudo ./mood_light [sensitivity_scale]
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#ifdef ALSA_AVAILABLE
#include <alsa/asoundlib.h>
#endif

#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */

#define SAMPLE_RATE        8000          /* Hz */
#define PERIOD_FRAMES      1024          /* ALSA period size */
#define NUM_CHANNELS       1             /* Mono */
#define BITS_PER_SAMPLE    16            /* 16-bit signed */
#define BUFFER_FRAMES      (PERIOD_FRAMES * 4)  /* 4 periods for headroom */
#define BUFFER_BYTES       (BUFFER_FRAMES * NUM_CHANNELS * (BITS_PER_SAMPLE / 8))

#define RED_PIN            17
#define GREEN_PIN          18
#define BLUE_PIN           27

#define PWM_RANGE          1000          /* 1 kHz software PWM */
#define PWM_DUTY_MAX       1000          /* 100 % of range */
#define PWM_PERIOD_US      1000          /* 1 ms -> 1 kHz */

#define GATE_MS            10            /* Gate interval in ms */
#define SENSITIVITY_DEFAULT 1.0f

/* ----------------------------- Globals ----------------------------------- */

static volatile sig_atomic_t g_running = 1;

#ifdef ALSA_AVAILABLE
static snd_pcm_t *g_pcm = NULL;
#endif

/* ----------------------------- Signal handler ----------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- RMS amplitude ------------------------------ */

/*
 * Compute RMS of a 16-bit mono buffer.
 * Returns 0.0 on success, -1.0 on error.
 */
static float calculate_rms(const int16_t *buffer, int num_frames)
{
    double sum_sq = 0.0;
    int count = 0;

    for (int i = 0; i < num_frames; i++) {
        int16_t s = buffer[i];
        sum_sq += (double)s * (double)s;
        count++;
    }

    if (count == 0)
        return 0.0f;

    return (float)sqrt(sum_sq / count);
}

/* ----------------------------- Software PWM (pigpio) ---------------------- */

/*
 * Drive one LED channel with software PWM for GATE_MS milliseconds.
 * duty: 0..PWM_DUTY_MAX (0%..100% of PWM_RANGE).
 */
static void pwm_set_channel(int pin, int duty)
{
    if (duty < 0) duty = 0;
    if (duty > PWM_DUTY_MAX) duty = PWM_DUTY_MAX;

    if (duty == 0) {
        gpioWrite(pin, 0);
        return;
    }
    if (duty == PWM_DUTY_MAX) {
        gpioWrite(pin, 1);
        return;
    }

    /* 500 us on, 500 us off -> 1 kHz, 50 % duty */
    gpioWrite(pin, 1);
    gpioDelay(500);
    gpioWrite(pin, 0);
    gpioDelay(500);
}

/*
 * Map RMS amplitude to RGB color and drive the LED.
 * sensitivity: higher value -> larger amplitude -> brighter color.
 */
static void map_rms_to_color(float rms, float sensitivity)
{
    float scaled = rms * sensitivity;
    if (scaled < 0.0f) scaled = 0.0f;
    if (scaled > 1.0f) scaled = 1.0f;

    /* Non-linear: 0->0, 0.5->0.5, 1->1 */
    float r = scaled;
    float g = scaled;
    float b = scaled;

    /* Software PWM for each channel */
    pwm_set_channel(RED_PIN,   (int)(r * PWM_DUTY_MAX));
    pwm_set_channel(GREEN_PIN, (int)(g * PWM_DUTY_MAX));
    pwm_set_channel(BLUE_PIN,  (int)(b * PWM_DUTY_MAX));
}

/* ----------------------------- Audio capture ------------------------------ */

#ifdef ALSA_AVAILABLE

static int capture_audio(snd_pcm_t *handle, int16_t *buffer, int num_frames)
{
    snd_pcm_sframes_t frames = snd_pcm_readi(handle, buffer, num_frames);
    if (frames < 0) {
        if (frames == -EPIPE) {
            fprintf(stderr, "ALSA underrun: stream recovered.\n");
            if (snd_pcm_prepare(handle) < 0) {
                fprintf(stderr, "ALSA prepare failed after underrun.\n");
                return -1;
            }
            return 0;
        }
        if (frames == -ESTRPIPE) {
            fprintf(stderr, "ALSA suspended: stream resumed.\n");
            if (snd_pcm_resume(handle) < 0) {
                fprintf(stderr, "ALSA resume failed.\n");
                return -1;
            }
            return 0;
        }
        fprintf(stderr, "ALSA read error: %s\n", snd_strerror((int)frames));
        return -1;
    }
    if (frames != num_frames) {
        fprintf(stderr, "ALSA short read: %ld frames\n", frames);
        return 0;
    }
    return 1;
}

#else

/*
 * Simulated audio: sine wave at 440 Hz.
 * Returns amplitude (0..1) so the mood light still cycles.
 */
static float simulate_audio(int16_t *buffer, int num_frames)
{
    static double phase = 0.0;
    const double freq = 440.0;
    const double two_pi = 2.0 * M_PI;

    for (int i = 0; i < num_frames; i++) {
        double s = sin(phase);
        buffer[i] = (int16_t)(s * 32767.0);
        phase += freq * two_pi / SAMPLE_RATE;
        if (phase >= two_pi) phase -= two_pi;
    }
    return 0.5f;  /* fixed gate scaling */
}

#endif

/* ----------------------------- Main --------------------------------------- */

int main(int argc, char *argv[])
{
    float sensitivity = SENSITIVITY_DEFAULT;

    if (argc > 1) {
        sensitivity = (float)atof(argv[1]);
        if (sensitivity <= 0.0f) {
            fprintf(stderr, "Invalid sensitivity '%s'. Using default %.2f.\n",
                    argv[1], SENSITIVITY_DEFAULT);
            sensitivity = SENSITIVITY_DEFAULT;
        }
    }

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure LED pins as outputs ---- */
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    /* ---- ALSA capture (if available) ---- */
#ifdef ALSA_AVAILABLE
    int err = snd_pcm_open(&g_pcm, "default", SND_PCM_STREAM_CAPTURE, 0);
    if (err < 0) {
        fprintf(stderr, "ALSA open failed: %s\n", snd_strerror(err));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    err = snd_pcm_set_params(g_pcm,
        SND_PCM_FORMAT_S16_LE,
        SND_PCM_ACCESS_RW_INTERLEAVED,
        NUM_CHANNELS,
        SAMPLE_RATE,
        1,          /* allow resampling */
        500000);    /* 500 ms latency */
    if (err < 0) {
        fprintf(stderr, "ALSA set_params failed: %s\n", snd_strerror(err));
        snd_pcm_close(g_pcm);
        g_pcm = NULL;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fprintf(stdout, "ALSA capture started: %d Hz, %d-bit, %d ch, period %d frames.\n",
            SAMPLE_RATE, BITS_PER_SAMPLE, NUM_CHANNELS, PERIOD_FRAMES);
#else
    fprintf(stdout, "ALSA unavailable — simulating audio at 440 Hz.\n");
#endif

    /* ---- Main loop ---- */
    int16_t *audio_buffer = malloc(BUFFER_BYTES);
    if (!audio_buffer) {
        fprintf(stderr, "malloc failed: %s\n", strerror(errno));
#ifdef ALSA_AVAILABLE
        snd_pcm_close(g_pcm);
#endif
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int frames_per_gate = (SAMPLE_RATE * GATE_MS) / 1000;
    if (frames_per_gate < PERIOD_FRAMES)
        frames_per_gate = PERIOD_FRAMES;

    while (g_running) {
        int rc = 0;

#ifdef ALSA_AVAILABLE
        rc = capture_audio(g_pcm, audio_buffer, frames_per_gate);
#else
        rc = (int)simulate_audio(audio_buffer, frames_per_gate);
#endif

        if (rc < 0) {
            /* Error already reported; continue running to recover. */
        } else {
            float rms = calculate_rms(audio_buffer, frames_per_gate);
            map_rms_to_color(rms, sensitivity);
        }

        /* Sleep for the remainder of the gate interval */
        int remaining_us = (GATE_MS * 1000) - (frames_per_gate * 1000000 / SAMPLE_RATE);
        if (remaining_us > 0)
            gpioDelay(remaining_us);
    }

    /* ---- Cleanup ---- */
    fprintf(stdout, "\nShutting down...\n");

    /* Turn off LED */
    gpioWrite(RED_PIN, 0);
    gpioWrite(GREEN_PIN, 0);
    gpioWrite(BLUE_PIN, 0);

#ifdef ALSA_AVAILABLE
    if (g_pcm) {
        snd_pcm_drain(g_pcm);
        snd_pcm_close(g_pcm);
        g_pcm = NULL;
    }
#endif

    free(audio_buffer);
    gpioTerminate();

    fprintf(stdout, "Done.\n");
    return EXIT_SUCCESS;
}

