#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TCS34725_ADDRESS 0x29
#define TCS34725_COMMAND_BIT 0x80
#define TCS34725_ENABLE 0x00
#define TCS34725_ATIME 0x01
#define TCS34725_ID 0x12
#define TCS34725_CDATA 0x14
#define TCS34725_RDATA 0x16
#define TCS34725_GDATA 0x18
#define TCS34725_BDATA 0x1A
#define TCS34725_ID_VALUE 0x44
#define INTEGRATION_TIME_MS 154
#define SAMPLE_INTERVAL_US 500000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int write_reg(int handle, uint8_t reg, uint8_t value) {
    char buf[2] = { (char)(TCS34725_COMMAND_BIT | reg), (char)value };
    if (i2cWriteDevice(handle, buf, 2) != 0) {
        fprintf(stderr, "Error writing to register 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

static int read_reg(int handle, uint8_t reg, uint8_t *value) {
    char cmd = (char)(TCS34725_COMMAND_BIT | reg);
    if (i2cWriteDevice(handle, &cmd, 1) != 0) {
        fprintf(stderr, "Error selecting register 0x%02X\n", reg);
        return -1;
    }
    char data;
    if (i2cReadDevice(handle, &data, 1) != 1) {
        fprintf(stderr, "Error reading register 0x%02X\n", reg);
        return -1;
    }
    *value = (uint8_t)data;
    return 0;
}

static int read_word(int handle, uint8_t reg, uint16_t *value) {
    char cmd = (char)(TCS34725_COMMAND_BIT | reg);
    if (i2cWriteDevice(handle, &cmd, 1) != 0) {
        fprintf(stderr, "Error selecting word register 0x%02X\n", reg);
        return -1;
    }
    char data[2];
    if (i2cReadDevice(handle, data, 2) != 2) {
        fprintf(stderr, "Error reading word register 0x%02X\n", reg);
        return -1;
    }
    *value = (uint16_t)((data[1] << 8) | data[0]);
    return 0;
}

static int init_sensor(int handle) {
    uint8_t id;
    if (read_reg(handle, TCS34725_ID, &id) != 0) return -1;
    if (id != TCS34725_ID_VALUE) {
        fprintf(stderr, "Invalid sensor ID: 0x%02X (expected 0x%02X)\n", id, TCS34725_ID_VALUE);
        return -1;
    }
    if (write_reg(handle, TCS34725_ENABLE, 0x03) != 0) return -1;
    if (write_reg(handle, TCS34725_ATIME, (uint8_t)(INTEGRATION_TIME_MS / 2.4)) != 0) return -1;
    return 0;
}

static int read_color_data(int handle, uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue) {
    if (read_word(handle, TCS34725_CDATA, clear) != 0) return -1;
    if (read_word(handle, TCS34725_RDATA, red) != 0) return -1;
    if (read_word(handle, TCS34725_GDATA, green) != 0) return -1;
    if (read_word(handle, TCS34725_BDATA, blue) != 0) return -1;
    return 0;
}

static void log_data(FILE *fp, uint16_t clear, uint16_t red, uint16_t green, uint16_t blue) {
    time_t now = time(NULL);
    fprintf(fp, "%ld,%u,%u,%u,%u\n", (long)now, clear, red, green, blue);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, TCS34725_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_sensor(i2c_handle) != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("color_data.csv", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,clear,red,green,blue\n");
        fflush(log_file);
    }

    uint16_t clear, red, green, blue;
    while (running) {
        if (read_color_data(i2c_handle, &clear, &red, &green, &blue) == 0) {
            log_data(log_file, clear, red, green, blue);
        } else {
            fprintf(stderr, "Error reading color data, logging zeros\n");
            log_data(log_file, 0, 0, 0, 0);
        }
