#include <stdbool.h>

#define RELAY1_PIN 17
#define RELAY2_PIN 27
#define RELAY3_PIN 22
#define RELAY4_PIN 23

#define SUNRISE_DURATION 3600
#define DAY_DURATION 21600
#define SUNSET_DURATION 3600
#define NIGHT_DURATION 518400

#define PWM_RANGE 100
#define PWM_FREQ 1000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void set_relay(int pin, int state) {
    if (gpioWrite(pin, state) != 0) {
        fprintf(stderr, "Error: gpioWrite(%d, %d) failed\n", pin, state);
        running = 0;
    }
}

static void all_relays_off(void) {
    set_relay(RELAY1_PIN, 1);
    set_relay(RELAY2_PIN, 1);
    set_relay(RELAY3_PIN, 1);
    set_relay(RELAY4_PIN, 1);
}

static void sunrise_cycle(void) {
    for (int elapsed = 0; elapsed < SUNRISE_DURATION && running; elapsed += 10) {
        int duty = (int)(((float)elapsed / SUNRISE_DURATION) * PWM_RANGE);
        if (duty > PWM_RANGE) duty = PWM_RANGE;
        if (duty < 0) duty = 0;

        set_relay(RELAY1_PIN, duty > 0 ? 0 : 1);
        set_relay(RELAY2_PIN, duty > 0 ? 0 : 1);
        set_relay(RELAY3_PIN, duty > 0 ? 0 : 1);
        set_relay(RELAY4_PIN, duty > 0 ? 0 : 1);

        gpioDelay(10000);
    }
}

static void sunset_cycle(void) {
    for (int elapsed = 0; elapsed < SUNSET_DURATION && running; elapsed += 10) {
        int duty = (int)(((float)(SUNSET_DURATION - elapsed) / SUNSET_DURATION) * PWM_RANGE);
        if (duty > PWM_RANGE) duty = PWM_RANGE;
        if (duty < 0) duty = 0;

        set_relay(RELAY1_PIN, duty > 0 ? 0 : 1);
        set_relay(RELAY2_PIN, duty > 0 ? 0 : 1);
        set_relay(RELAY3_PIN, duty > 0 ? 0 : 1);
        set_relay(RELAY4_PIN, duty > 0 ? 0 : 1);

        gpioDelay(10000);
    }
}

static void day_cycle(void) {
    for (int elapsed = 0; elapsed < DAY_DURATION && running; elapsed += 10) {
        set_relay(RELAY1_PIN, 0);
        set_relay(RELAY2_PIN, 0);
        set_relay(RELAY3_PIN, 0);
        set_relay(RELAY4_PIN, 0);
        gpioDelay(10000);
    }
}

static void night_cycle(void) {
    for (int elapsed = 0; elapsed < NIGHT_DURATION && running; elapsed += 10) {
        set_relay(RELAY1_PIN, 1);
        set_relay(RELAY2_PIN, 1);
        set_relay(RELAY3_PIN, 1);
        set_relay(RELAY4_PIN, 1);
        gpioDelay(10000);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY1_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(RELAY2_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(RELAY3_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(RELAY4_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    all_relays_off();

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        sunrise_cycle();
        if (!running) break;
        day_cycle();
        if (!running) break;
        sunset_cycle();
        if (!running) break;
        night_cycle();
    }

    all_relays_off();
    gpioTerminate();
    return EXIT_SUCCESS;
}

