#include <unistd.h>
#include <pigpio.h>

#define SENSOR_PIN 17
#define LOG_FILE "/home/pi/logs/motion_log.txt"
#define VIDEO_DIR "/home/pi/videos/"
#define DEBOUNCE_MS 200
#define CAPTURE_DURATION 5
#define POLL_INTERVAL_US 10000

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

static int get_timestamp(char *buf, size_t len) {
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        return -1;
    }
    if (strftime(buf, len, "%Y%m%d_%H%M%S", timeinfo) == 0) {
        return -1;
    }
    return 0;
}

static int log_motion_event(const char *timestamp) {
    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            perror("Error opening log file");
            return -1;
        }
    }
    if (fprintf(log_file, "%s\n", timestamp) < 0) {
        perror("Error writing to log file");
        return -1;
    }
    if (fflush(log_file) != 0) {
        perror("Error flushing log file");
        return -1;
    }
    return 0;
}

static int capture_video(const char *filename) {
    char command[512];
    int ret = snprintf(command, sizeof(command),
                       "raspivid -o %s -t %d -w 640 -h 480 -fps 15",
                       filename, CAPTURE_DURATION * 1000);
    if (ret < 0 || (size_t)ret >= sizeof(command)) {
        fprintf(stderr, "Error: command buffer too small\n");
        return -1;
    }
    printf("Executing: %s\n", command);
    int status = system(command);
    if (status == -1) {
        perror("Error executing raspivid");
        return -1;
    }
    if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
        fprintf(stderr, "raspivid failed (status=%d)\n", status);
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Error registering SIGINT handler");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as input\n", SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Motion detection started on GPIO %d. Press Ctrl+C to exit.\n", SENSOR_PIN);

    uint32_t last_trigger_tick = 0;

    while (running) {
        int level = gpioRead(SENSOR_PIN);
        if (level < 0) {
            fprintf(stderr, "Error reading GPIO %d\n", SENSOR_PIN);
            break;
        }

        if (level == 0) {
            uint32_t now = gpioTick();
            if (now - last_trigger_tick >= DEBOUNCE_MS * 1000) {
                char timestamp[32];
                if (get_timestamp(timestamp, sizeof(timestamp)) == 0) {
                    char filename[256];
                    int fn_ret = snprintf(filename, sizeof(filename), "%s%s.h264",
                                          VIDEO_DIR, timestamp);
                    if (fn_ret < 0 || (size_t)fn_ret >= sizeof(filename)) {
                        fprintf(stderr, "Error: filename too long\n");
                    } else {
                        printf("Motion detected at %s\n", timestamp);
                        if (log_motion_event(timestamp) != 0) {
                            fprintf(stderr, "Error logging motion event\n");
                        }
                        if (capture_video(filename) != 0) {
                            fprintf(stderr, "Error capturing video\n");
                        }
                    }
                } else {
                    fprintf(stderr, "Error getting timestamp\n");
                }
                last_trigger_tick = now;
            }
        }
        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

