#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define RELAY1 4
#define RELAY2 17
#define RELAY3 27
#define RELAY4 22
#define MOISTURE_THRESHOLD 30
#define LOG_FILE "irrigation_log.txt"
#define LOOP_DELAY_SEC 5

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_relay(int gpio, int state) {
    if (gpioWrite(gpio, state) != 0) {
        fprintf(stderr, "Error: gpioWrite(%d, %d) failed\n", gpio, state);
        return -1;
    }
    return 0;
}

static int log_data(int moisture, int r1, int r2, int r3, int r4) {
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "Error: time() failed: %s\n", strerror(errno));
        return -1;
    }
    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "Error: localtime_r() failed\n");
        return -1;
    }
    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error: strftime() failed\n");
        return -1;
    }
    if (fprintf(log_file, "%s, Moisture: %d, Relay1: %s, Relay2: %s, Relay3: %s, Relay4: %s\n",
                timestamp, moisture,
                r1 ? "ON" : "OFF",
                r2 ? "ON" : "OFF",
                r3 ? "ON" : "OFF",
                r4 ? "ON" : "OFF") < 0) {
        fprintf(stderr, "Error: fprintf() to log file failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(log_file) != 0) {
        fprintf(stderr, "Warning: fflush() failed: %s\n", strerror(errno));
    }
    return 0;
}

static void cleanup(void) {
    set_relay(RELAY1, 1);
    set_relay(RELAY2, 1);
    set_relay(RELAY3, 1);
    set_relay(RELAY4, 1);
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY1, PI_OUTPUT) != 0 ||
        gpioSetMode(RELAY2, PI_OUTPUT) != 0 ||
        gpioSetMode(RELAY3, PI_OUTPUT) != 0 ||
        gpioSetMode(RELAY4, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode() failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (set_relay(RELAY1, 1) != 0 || set_relay(RELAY2, 1) != 0 ||
        set_relay(RELAY3, 1) != 0 || set_relay(RELAY4, 1) != 0) {
        fprintf(stderr, "Error: initial relay state set failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGTERM) failed: %s\n", strerror(errno));
    }

    srand((unsigned int)time(NULL));

    while (running) {
        int moisture = rand() % 101;
        int r1 = (moisture < MOISTURE_THRESHOLD) ? 0 : 1;
        int r2 = (moisture < MOISTURE_THRESHOLD) ? 0 : 1;
        int r3 = (moisture < MOISTURE_THRESHOLD) ? 0 : 1;
        int r4 = (moisture < MOISTURE_THRESHOLD) ? 0 : 1;

        if (set_relay(RELAY1, r1) != 0 || set_relay(RELAY2, r2) != 0 ||
            set_relay(RELAY3, r3) != 0 || set_relay(RELAY4, r4) != 0) {
            fprintf(stderr, "Error: relay activation failed, exiting\n");
            break;
        }

        if (log_data(moisture, r1, r2, r3, r4) != 0) {
            fprintf(stderr, "Error: logging failed, exiting\n");
            break;
        }

        printf("Moisture: %d, Relay1: %s, Relay2: %s, Relay3: %s, Relay4: %s\n",
               moisture,
               r1 ? "ON" : "OFF",
               r2 ? "ON" : "OFF",
               r3 ? "ON" : "OFF",
               r4 ? "ON" : "OFF");

        for (int i = 0; i < LOOP_DELAY_SEC && running; i++) {
            gpioSleep(PI_TIME_RELATIVE, 1, 0);
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

