/*
 * ADXL345 free-fall detector for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   ADXL345 SDA  -> GPIO2  (I2C bus 1)
 *   ADXL345 SCL  -> GPIO3  (I2C bus 1)
 *   ADXL345 VDD  -> 3.3 V
 *   ADXL345 GND  -> GND
 *   Alarm buzzer / LED on GPIO27 (BCM) with appropriate series resistor
 *
 * Build:  gcc -O2 -Wall -Wextra -o freefall freefall.c -li2c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#include <pigpio.h>

/* ---- ADXL345 constants (from datasheet) ---- */
#define ADXL345_ADDR          0x53   /* AD0 tied high */
#define ADXL345_REG_DEVID     0x00
#define ADXL345_REG_POWER_CTL 0x2D
#define ADXL345_REG_DATAX0    0x32
#define ADXL345_REG_BW_RATE   0x2C
#define ADXL345_REG_DATA_FORMAT 0x31

#define ADXL345_DEVID         0xE5
#define ADXL345_RANGE_2G      0x00   /* ±2 g, 4 mg/LSB */
#define ADXL345_ODR_100HZ     0x0A   /* 100 Hz, 0x0A = 0b00001010 */

/* ---- Application constants ---- */
#define ALARM_GPIO            27
#define FREEFALL_THRESHOLD_G  0.2f
#define FREEFALL_DURATION_S   0.5f   /* seconds */
#define ALARM_DURATION_S      5.0f
#define POLL_INTERVAL_US      100000 /* 100 ms */
#define LOG_FILE              "freefall.log"

/* ---- Globals for signal handler ---- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd = -1;
static int      g_pigpio_ready = 0;

/* ---- Prototypes ---- */
static int  adxl345_init(int fd);
static int  adxl345_read_axes(int fd, float *x, float *y, float *z);
static bool detect_freefall(float x, float y, float z);
static void log_freefall(float x, float y, float z);
static void alarm_on(void);
static void alarm_off(void);
static void cleanup(void);
static void signal_handler(int sig);

/* ---- ADXL345 helpers ---- */

/*
 * Initialise the ADXL345: verify device identity, set ±2 g range,
 * 100 Hz output data rate, and enter measurement mode.
 */
static int adxl345_init(int fd)
{
    uint8_t devid;
    uint8_t reg;
    uint8_t val;

    /* Read and verify DEVID */
    if (i2cReadByteData(fd, ADXL345_REG_DEVID) < 0) {
        fprintf(stderr, "I2C read error (DEVID): %s\n", strerror(errno));
        return -1;
    }
    devid = (uint8_t)i2cReadByteData(fd, ADXL345_REG_DEVID);
    if (devid != ADXL345_DEVID) {
        fprintf(stderr, "ADXL345 not found (DEVID=0x%02X, expected 0x%02X)\n",
                devid, ADXL345_DEVID);
        return -1;
    }

    /* Set data format: ±2 g, full resolution, right-justified */
    reg = ADXL345_REG_DATA_FORMAT;
    val = ADXL345_RANGE_2G;
    if (i2cWriteByteData(fd, reg, val) < 0) {
        fprintf(stderr, "I2C write error (DATA_FORMAT): %s\n", strerror(errno));
        return -1;
    }

    /* Set output data rate to 100 Hz */
    reg = ADXL345_REG_BW_RATE;
    val = ADXL345_ODR_100HZ;
    if (i2cWriteByteData(fd, reg, val) < 0) {
        fprintf(stderr, "I2C write error (BW_RATE): %s\n", strerror(errno));
        return -1;
    }

    /* Enter measurement mode */
    reg = ADXL345_REG_POWER_CTL;
    val = 0x08; /* measure bit */
    if (i2cWriteByteData(fd, reg, val) < 0) {
        fprintf(stderr, "I2C write error (POWER_CTL): %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/*
 * Read 6 bytes of acceleration data (X0, X1, Y0, Y1, Z0, Z1) and convert
 * to g using the ±2 g, 4 mg/LSB resolution.
 */
static int adxl345_read_axes(int fd, float *x, float *y, float *z)
{
    uint8_t buf[6];
    int16_t raw_x, raw_y, raw_z;

    if (i2cReadI2CBlockData(fd, ADXL345_REG_DATAX0, (char *)buf, 6) != 6) {
        fprintf(stderr, "I2C block read error (DATAX0): %s\n", strerror(errno));
        return -1;
    }

    raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    raw_z = (int16_t)((buf[5] << 8) | buf[4]);

    *x = (float)raw_x * 0.004f;   /* ±2 g: 4 mg/LSB */
    *y = (float)raw_y * 0.004f;
    *z = (float)raw_z * 0.004f;

    return 0;
}

/* Detect free-fall: all three axes below threshold for FREEFALL_DURATION_S */
static bool detect_freefall(float x, float y, float z)
{
    return (fabsf(x) < FREEFALL_THRESHOLD_G &&
            fabsf(y) < FREEFALL_THRESHOLD_G &&
            fabsf(z) < FREEFALL_THRESHOLD_G);
}

/* Log a confirmed free-fall event to CSV with timestamp */
static void log_freefall(float x, float y, float z)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return;
    }

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.3f,%.3f,%.3f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            x, y, z);

    fclose(fp);
}

/* Drive the alarm GPIO high */
static void alarm_on(void)
{
    if (g_pigpio_ready) {
        gpioWrite(ALARM_GPIO, 1);
    }
}

/* Drive the alarm GPIO low */
static void alarm_off(void)
{
