    }

    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Free-fall detection started. Press Ctrl+C to exit.\n");

    /* ---- Main polling loop ---- */
    while (g_running) {
        float x, y, z;

        if (adxl345_read_axes(g_i2c_fd, &x, &y, &z) < 0) {
            /* I2C error: back off briefly and retry */
            usleep(POLL_INTERVAL_US);
            continue;
        }

        if (detect_freefall(x, y, z)) {
            /* Confirm by waiting, then re-read */
            usleep((useconds_t)(FREEFALL_DURATION_S * 1000000.0f));
            if (!g_running) {
                break;
            }

            float x2, y2, z2;
            if (adxl345_read_axes(g_i2c_fd, &x2, &y2, &z2) < 0) {
                fprintf(stderr, "I2C read failed during confirmation\n");
            } else if (detect_freefall(x2, y2, z2)) {
                printf("Free-fall detected!\n");
