#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define TRIGGER_PIN 4
#define ECHO_PIN 18
#define MAX_DISTANCE_CM 4.0
#define TIMEOUT_US 100000
#define TRIGGER_PULSE_US 10
#define CYCLE_DELAY_US 200000
#define LOG_FILE "distance_log.txt"

static volatile uint32_t echo_start_tick = 0;
static volatile uint32_t echo_end_tick = 0;
static volatile int echo_rising_seen = 0;
static volatile int echo_falling_seen = 0;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate_flag = 0;
static pthread_mutex_t tick_mutex = PTHREAD_MUTEX_INITIALIZER;

static void signal_handler(int sig) {
    (void)sig;
    terminate_flag = 1;
}

static void echo_rising_callback(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)userdata;
    if (level == 1) {
        pthread_mutex_lock(&tick_mutex);
        echo_start_tick = tick;
        echo_rising_seen = 1;
        echo_falling_seen = 0;
        pthread_mutex_unlock(&tick_mutex);
    }
}

static void echo_falling_callback(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)userdata;
    if (level == 0) {
        pthread_mutex_lock(&tick_mutex);
        echo_end_tick = tick;
        echo_falling_seen = 1;
        pthread_mutex_unlock(&tick_mutex);
    }
}

static double calculate_distance_cm(uint32_t pulse_width_us) {
    if (pulse_width_us == 0) return -1.0;
    double distance = (double)pulse_width_us * 0.0343 / 2.0;
    if (distance > MAX_DISTANCE_CM) return -1.0;
    return distance;
}

static void log_distance(double distance_cm) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
        return;
    }
    long long timestamp_ns = (long long)ts.tv_sec * 1000000000LL + ts.tv_nsec;
    if (log_file != NULL) {
        fprintf(log_file, "%lld,%.2f\n", timestamp_ns, distance_cm);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

static void trigger_sensor(void) {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set TRIGGER_PIN %d as output\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set ECHO_PIN %d as input\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down on ECHO_PIN %d\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(100000);

    if (gpioSetISRFuncEx(ECHO_PIN, RISING_EDGE, 0, echo_rising_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set rising-edge ISR on ECHO_PIN %d\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetISRFuncEx(ECHO_PIN, FALLING_EDGE, 0, echo_falling_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set falling-edge ISR on ECHO_PIN %d\n", ECHO_PIN);
        gpioSetISRFuncEx(ECHO_PIN, RISING_EDGE, 0, NULL, NULL);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioSetISRFuncEx(ECHO_PIN, RISING_EDGE, 0, NULL, NULL);
        gpioSetISRFuncEx(ECHO_PIN, FALLING_EDGE, 0, NULL, NULL);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
    }

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");

    while (!terminate_flag) {
        echo_rising_seen = 0;
        echo_falling_seen = 0;
        echo_start_tick = 0;
        echo_end_tick = 0;

        trigger_sensor();

        uint32_t start_tick = gpioTick();
        int timeout = 0;

        while (!terminate_flag && !echo_falling_seen) {
            uint32_t now = gpioTick();
            if ((now - start_tick) > TIMEOUT_US) {
                timeout = 1;
                break;
            }
            gpioDelay(100);
        }

        if (terminate_flag) break;

        if (timeout) {
            fprintf(stderr, "Sensor timeout: no echo received within %d us\n", TIMEOUT_US);
            log_distance(-1.0);
            gpioDelay(CYCLE_DELAY_US);
            continue;
        }

        if (!echo_rising_seen) {
            fprintf(stderr, "Invalid measurement: no rising edge detected\n");
            log_distance(-1.0);
            gpioDelay(CYCLE_DELAY_US);
            continue;
        }

        pthread_mutex_lock(&tick_mutex);
        uint32_t pulse_width = echo_end_tick - echo_start_tick;
        pthread_mutex_unlock(&tick_mutex);

        double distance = calculate_distance_cm(pulse_width);

        if (distance < 0) {
            fprintf(stderr, "Invalid distance: pulse width %u us\n", pulse_width);
            log_distance(-1.0);
        } else {
            log_distance(distance);
        }

        gpioDelay(CYCLE_DELAY_US);
    }

    printf("\nCleaning up...\n");
    gpioSetISRFuncEx(ECHO_PIN, RISING_EDGE, 0, NULL, NULL);
    gpioSetISRFuncEx(ECHO_PIN, FALLING_EDGE, 0, NULL, NULL);
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
    pthread_mutex_destroy(&tick_mutex);
    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

