        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set ECHO_PIN %d as input\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down on ECHO_PIN %d\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(100000);

    if (gpioSetISRFuncEx(ECHO_PIN, RISING_EDGE, 0, echo_rising_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set rising-edge ISR on ECHO_PIN %d\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetISRFuncEx(ECHO_PIN, FALLING_EDGE, 0, echo_falling_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set falling-edge ISR on ECHO_PIN %d\n", ECHO_PIN);
        gpioSetISRFuncEx(ECHO_PIN, RISING_EDGE, 0, NULL, NULL);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioSetISRFuncEx(ECHO_PIN, RISING_EDGE, 0, NULL, NULL);
        gpioSetISRFuncEx(ECHO_PIN, FALLING_EDGE, 0, NULL, NULL);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
    }

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");

    while (!terminate_flag) {
        echo_rising_seen = 0;
        echo_falling_seen = 0;
        echo_start_tick = 0;
        echo_end_tick = 0;

        trigger_sensor();

        uint32_t start_tick = gpioTick();
        int timeout = 0;

        while (!terminate_flag && !echo_falling_seen) {
            uint32_t now = gpioTick();
            if ((now - start_tick) > TIMEOUT_US) {
                timeout = 1;
                break;
            }
            gpioDelay(100);
        }

        if (terminate_flag) break;

        if (timeout) {
            fprintf(stderr, "Sensor timeout: no echo received within %d us\n", TIMEOUT_US);
            log_distance(-1.0);
            gpioDelay(CYCLE_DELAY_US);
            continue;
        }

        if (!echo_rising_seen) {
            fprintf(stderr, "Invalid measurement: no rising edge detected\n");
            log_distance(-1.0);
            gpioDelay(CYCLE_DELAY_US);
            continue;
        }

        pthread_mutex_lock(&tick_mutex);
        uint32_t pulse_width = echo_end_tick - echo_start_tick;
        pthread_mutex_unlock(&tick_mutex);

        double distance = calculate_distance_cm(pulse_width);

        if (distance < 0) {
            fprintf(stderr, "Invalid distance: pulse width %u us\n", pulse_width);
            log_distance(-1.0);
        } else {
            log_distance(distance);
        }

        gpioDelay(CYCLE_DELAY_US);
    }

    printf("\nCleaning up...\n");
    gpioSetISRFuncEx(ECHO_PIN, RISING_EDGE, 0, NULL, NULL);
    gpioSetISRFuncEx(ECHO_PIN, FALLING_EDGE, 0, NULL, NULL);
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
    pthread_mutex_destroy(&tick_mutex);
    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

