#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define LIS3DH_ADDR 0x19
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D
#define BUZZER_GPIO 17
#define FREEFALL_THRESHOLD_DEFAULT 0.2f
#define IMPACT_THRESHOLD_DEFAULT 1.5f
#define I2C_RETRIES 3
#define SAMPLE_DELAY_US 100000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg(int handle, uint8_t reg, uint8_t value) {
    for (int attempt = 0; attempt < I2C_RETRIES; attempt++) {
        int rc = i2cWriteByteData(handle, reg, value);
        if (rc >= 0) return 0;
        fprintf(stderr, "I2C write to reg 0x%02X failed (attempt %d): %d\n", reg, attempt + 1, rc);
        usleep(10000);
    }
    return -1;
}

static int i2c_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    for (int attempt = 0; attempt < I2C_RETRIES; attempt++) {
        int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
        if (rc == (int)len) return 0;
        fprintf(stderr, "I2C read block from reg 0x%02X failed (attempt %d): %d\n", reg, attempt + 1, rc);
        usleep(10000);
    }
    return -1;
}

static int lis3dh_init(int handle) {
    if (i2c_write_reg(handle, CTRL_REG1, 0x27) < 0) return -1;
    if (i2c_write_reg(handle, CTRL_REG4, 0x00) < 0) return -1;
    return 0;
}

static int read_accel(int handle, float *x, float *y, float *z) {
    uint8_t buf[6];
    if (i2c_read_block(handle, OUT_X_L, buf, 6) < 0) return -1;
    int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);
    *x = (float)raw_x / 16384.0f;
    *y = (float)raw_y / 16384.0f;
    *z = (float)raw_z / 16384.0f;
    return 0;
}

static float calc_magnitude(float x, float y, float z) {
    return sqrtf(x * x + y * y + z * z);
}

static void trigger_buzzer(int gpio) {
    gpioWrite(gpio, 1);
    gpioDelay(1000000);
    gpioWrite(gpio, 0);
}

int main(int argc, char *argv[]) {
    float freefall_threshold = FREEFALL_THRESHOLD_DEFAULT;
    float impact_threshold = IMPACT_THRESHOLD_DEFAULT;

    if (argc > 1) freefall_threshold = (float)atof(argv[1]);
    if (argc > 2) impact_threshold = (float)atof(argv[2]);

    printf("Freefall threshold: %.2f g, Impact threshold: %.2f g\n", freefall_threshold, impact_threshold);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(I2C_BUS, LIS3DH_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %d\n", I2C_BUS, LIS3DH_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (lis3dh_init(i2c_handle) < 0) {
        fprintf(stderr, "LIS3DH initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);
    gpioWrite(BUZZER_GPIO, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    float x, y, z, mag;
    bool in_freefall = false;

    while (running) {
        if (read_accel(i2c_handle, &x, &y, &z) < 0) {
            fprintf(stderr, "Failed to read accelerometer data\n");
            break;
        }

        mag = calc_magnitude(x, y, z);

        if (mag < freefall_threshold) {
            in_freefall = true;
            printf("Freefall detected (mag: %.2f g)\n", mag);
        } else if (in_freefall && mag > impact_threshold) {
            in_freefall = false;
            printf("Impact detected (mag: %.2f g)\n", mag);
            trigger_buzzer(BUZZER_GPIO);
        }

        usleep(SAMPLE_DELAY_US);
    }

    i2cClose(i2c_handle);
    gpioWrite(BUZZER_GPIO, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

