        move_motor(motor1_pins, NUM_STEPS, (i % 2) == 0);
        move_motor(motor2_pins, NUM_STEPS, (i % 2) == 0);
    }

    release_gpio();
    printf("\nMotors stopped. GPIO released.\n");
    return EXIT_SUCCESS;
}

