#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define DEFAULT_THRESHOLD 2.0f
#define DEFAULT_I2C_ADDRESS 0x19
#define LOG_FILE "/var/log/high_acceleration.log"
#define I2C_BUS 1
#define SAMPLE_INTERVAL_US 100000

#define LIS3DH_REG_CTRL1 0x20
#define LIS3DH_REG_CTRL4 0x23
#define LIS3DH_REG_OUT_X_L 0x28
#define LIS3DH_REG_WHO_AM_I 0x0F
#define LIS3DH_WHO_AM_I_VAL 0x33

#define CTRL1_VAL 0x57
#define CTRL4_VAL 0x08

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int write_reg(uint8_t reg, uint8_t val) {
    if (i2cWriteByteData(i2c_handle, reg, val) < 0) {
        fprintf(stderr, "Error writing reg 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

static int init_lis3dh(void) {
    if (write_reg(LIS3DH_REG_CTRL1, CTRL1_VAL) < 0) return -1;
    if (write_reg(LIS3DH_REG_CTRL4, CTRL4_VAL) < 0) return -1;
    return 0;
}

static int read_acceleration(float *x, float *y, float *z) {
    char buffer[6];
    if (i2cReadI2CBlockData(i2c_handle, LIS3DH_REG_OUT_X_L | 0x80, buffer, 6) != 6) {
        fprintf(stderr, "Error reading acceleration data\n");
        return -1;
    }
    int16_t raw_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t raw_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t raw_z = (int16_t)((buffer[5] << 8) | buffer[4]);
    *x = (float)raw_x / 16384.0f;
    *y = (float)raw_y / 16384.0f;
    *z = (float)raw_z / 16384.0f;
    return 0;
}

static void log_data(float x, float y, float z) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file\n");
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s, X: %.2f g, Y: %.2f g, Z: %.2f g\n", ts, x, y, z);
    fclose(fp);
}

static void shutdown_system(void) {
    printf("Shutting down system...\n");
    fflush(stdout);
    system("sudo shutdown -h now");
}

int main(int argc, char *argv[]) {
    float threshold = DEFAULT_THRESHOLD;
    int i2c_address = DEFAULT_I2C_ADDRESS;
    int opt;
    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = (int)strtol(optarg, NULL, 0);
                if (i2c_address < 0x03 || i2c_address > 0x77) {
                    fprintf(stderr, "Invalid I2C address: 0x%02X\n", i2c_address);
                    return 0;
                }
                break;
            case 't':
                threshold = strtof(optarg, NULL);
                if (threshold <= 0.0f) {
                    fprintf(stderr, "Threshold must be > 0\n");
                    return 0;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-t threshold_g]\n", argv[0]);
                return 0;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 0;
    }

    i2c_handle = i2cOpen(I2C_BUS, i2c_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 0;
    }

    int who = i2cReadByteData(i2c_handle, LIS3DH_REG_WHO_AM_I);
    if (who != LIS3DH_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", who, LIS3DH_WHO_AM_I_VAL);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 0;
    }

    if (init_lis3dh() < 0) {
        fprintf(stderr, "LIS3DH init failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 0;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    printf("Monitoring acceleration (threshold: %.2f g)...\n", threshold);
    fflush(stdout);

    while (running) {
        float x, y, z;
        if (read_acceleration(&x, &y, &z) == 0) {
            if (fabsf(x) > threshold || fabsf(y) > threshold || fabsf(z) > threshold) {
                log_data(x, y, z);
                shutdown_system();
                break;
            }
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

