#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LEFT_SENSOR_PIN   4
#define CENTER_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN  27
#define ALERT_PIN         22

#define BUFFER_SIZE 5
#define POLL_DELAY_US 10000
#define ALERT_DURATION_US 2000000

#define LINE_DETECTED 0
#define NO_LINE       1

typedef struct {
    int left;
    int center;
    int right;
} SensorData;

typedef struct {
    SensorData data[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

static volatile sig_atomic_t running = 1;
static int pigpio_initialized = 0;
static CircularBuffer sensor_buffer;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void init_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

static void add_to_buffer(CircularBuffer *cb, SensorData data) {
    cb->data[cb->head] = data;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

static void cleanup(void) {
    if (pigpio_initialized) {
        gpioWrite(ALERT_PIN, 0);
        gpioTerminate();
        pigpio_initialized = 0;
    }
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }
    pigpio_initialized = 1;

    if (gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input\n", LEFT_SENSOR_PIN);
        return -1;
    }
    if (gpioSetMode(CENTER_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input\n", CENTER_SENSOR_PIN);
        return -1;
    }
    if (gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input\n", RIGHT_SENSOR_PIN);
        return -1;
    }
    if (gpioSetMode(ALERT_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output\n", ALERT_PIN);
        return -1;
    }
    if (gpioWrite(ALERT_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise GPIO%d to LOW\n", ALERT_PIN);
        return -1;
    }
    return 0;
}

static int read_sensor(int pin) {
    int value = gpioRead(pin);
    if (value < 0) {
        fprintf(stderr, "Error: failed to read GPIO%d\n", pin);
        return -1;
    }
    return value;
}

static void activate_alert(void) {
    if (gpioWrite(ALERT_PIN, 1) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d HIGH\n", ALERT_PIN);
        return;
    }
    gpioDelay(ALERT_DURATION_US);
    if (gpioWrite(ALERT_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d LOW\n", ALERT_PIN);
    }
}

static void move_forward(void) {
    printf("Moving forward\n");
}

static void turn_left(void) {
    printf("Turning left\n");
}

static void turn_right(void) {
    printf("Turning right\n");
}

static void stop_robot(void) {
    printf("Stopping\n");
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (init_gpio() != 0) {
        cleanup();
        return 1;
    }

    init_circular_buffer(&sensor_buffer);

    int no_line_count = 0;
    int last_alert_active = 0;

    while (running) {
        int left = read_sensor(LEFT_SENSOR_PIN);
        int center = read_sensor(CENTER_SENSOR_PIN);
        int right = read_sensor(RIGHT_SENSOR_PIN);

        if (left < 0 || center < 0 || right < 0) {
            fprintf(stderr, "Error: sensor read failure, exiting\n");
            break;
        }

        SensorData current = {left, center, right};
        add_to_buffer(&sensor_buffer, current);

        printf("Left: %d, Center: %d, Right: %d\n", left, center, right);

        if (center == NO_LINE) {
            no_line_count++;
            if (no_line_count >= 5 && !last_alert_active) {
                activate_alert();
                last_alert_active = 1;
            }
        } else {
            no_line_count = 0;
            last_alert_active = 0;
        }

        if (center == LINE_DETECTED) {
            move_forward();
        } else if (left == LINE_DETECTED) {
            turn_left();
        } else if (right == LINE_DETECTED) {
            turn_right();
        } else {
            stop_robot();
        }

        gpioDelay(POLL_DELAY_US);
    }

    cleanup();
    return 0;
}

