#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x30
#define GPIO_RELAY 17
#define THRESHOLD 5.0f
#define POLL_TIMEOUT_MS 50
#define SAMPLE_INTERVAL_US 100000
#define LOG_FILE "magnetic_events.txt"

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void log_event(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];
    localtime_r(&now, &tm_info);
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(log_file, "%s: %s\n", ts, message);
    fflush(log_file);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_field(float *field) {
    char buf[2];
    int rc = i2cReadDevice(i2c_handle, buf, 2);
    if (rc != 2) {
        log_event("Error: I2C read failed");
        return -1;
    }
    int raw = (buf[0] << 8) | buf[1];
    *field = (float)raw * 0.01f;
    return 0;
}

static int set_relay(int state) {
    if (gpioWrite(GPIO_RELAY, state) != 0) {
        log_event("Error: GPIO write failed");
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    set_relay(0);
    if (log_file) {
        log_event("Program terminated");
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        log_event("Error: I2C open failed");
