#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define RELAY_GPIO 18
#define PORT 5000
#define BUFFER_SIZE 1024
#define LOG_FILE "relay_log.txt"

static volatile sig_atomic_t running = 1;
static int server_fd = -1;
static int client_fd = -1;
static FILE *log_file = NULL;

static void log_event(const char *message) {
    if (!log_file) return;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(log_file);
}

static void cleanup(void) {
    if (client_fd >= 0) { close(client_fd); client_fd = -1; }
    if (server_fd >= 0) { close(server_fd); server_fd = -1; }
    if (log_file) { fclose(log_file); log_file = NULL; }
    if (gpioInitialise() >= 0) {
        gpioWrite(RELAY_GPIO, 0);
        gpioTerminate();
    }
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int setup_socket(void) {
    int fd = socket(AF_INET, SOCK_STREAM, 0);
    if (fd < 0) { perror("socket"); return -1; }
    int opt = 1;
    if (setsockopt(fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        perror("setsockopt"); close(fd); return -1;
    }
    struct sockaddr_in addr = {0};
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = INADDR_ANY;
    addr.sin_port = htons(PORT);
    if (bind(fd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("bind"); close(fd); return -1;
    }
    if (listen(fd, 3) < 0) {
        perror("listen"); close(fd); return -1;
    }
    return fd;
}

static int handle_client(int client_fd) {
    char buffer[BUFFER_SIZE];
    ssize_t n = recv(client_fd, buffer, sizeof(buffer) - 1, 0);
    if (n <= 0) {
        if (n < 0) perror("recv");
        return -1;
    }
    buffer[n] = '\0';
    char *cmd = strtok(buffer, "\r\n");
    if (!cmd) return 0;
    for (int i = 0; i < (int)strlen(cmd); i++) cmd[i] = (char)tolower((unsigned char)cmd[i]);
    if (strcmp(cmd, "on") == 0) {
        if (gpioWrite(RELAY_GPIO, 1) == 0) {
            log_event("Relay activated");
            send(client_fd, "Relay activated\n", 18, 0);
        } else {
            log_event("Error activating relay");
            send(client_fd, "Error activating relay\n", 22, 0);
        }
    } else if (strcmp(cmd, "off") == 0) {
        if (gpioWrite(RELAY_GPIO, 0) == 0) {
            log_event("Relay deactivated");
            send(client_fd, "Relay deactivated\n", 20, 0);
        } else {
            log_event("Error deactivating relay");
            send(client_fd, "Error deactivating relay\n", 24, 0);
        }
    } else {
        log_event("Invalid command received");
        send(client_fd, "Invalid command\n", 16, 0);
    }
    return 0;
}

int main(void) {
    struct sigaction sa = {0};
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction"); return 1;
    }
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY_GPIO);
        gpioTerminate(); return 1;
    }
    gpioWrite(RELAY_GPIO, 0);
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) { perror("fopen"); gpioTerminate(); return 1; }
    log_event("Relay control service started");
    server_fd = setup_socket();
    if (server_fd < 0) { cleanup(); return 1; }
    printf("Listening on port %d...\n", PORT);
    while (running) {
        struct sockaddr_in client_addr = {0};
        socklen_t addrlen = sizeof(client_addr);
        client_fd = accept(server_fd, (struct sockaddr *)&client_addr, &addrlen);
        if (client_fd < 0) {
            if (errno == EINTR) continue;
            perror("accept");
            break;
        }
        char ip[INET_ADDRSTRLEN];
        inet_ntop(AF_INET, &client_addr.sin_addr, ip, sizeof(ip));
        printf("Connection from %s\n", ip);
        handle_client(client_fd);
        close(client_fd);
        client_fd = -1;
    }
    log_event("Relay control service stopped");
    cleanup();
    return 0;
}

