#define POLL_DELAY_US        100000        /* 100 ms */
#define LOG_FILE             "flow_log.txt"
#define MEAS_START_CMD       0x3608        /* start continuous measurement */
#define MEAS_START_CMD_LEN   2
#define FLOW_SCALE_FACTOR    0.00001f      /* raw -> ml/min */
#define CRC8_POLY            0x31          /* Sensirion: x^8 + x^5 + x^4 + 1 */
#define CRC8_INIT            0xFF

/* ----------------------------- Globals ----------------------------------- */
static int      i2c_h1 = -1;
static int      i2c_h2 = -1;
static volatile sig_atomic_t running = 1;

/* ----------------------------- Prototypes -------------------------------- */
static uint8_t  crc8(const uint8_t *data, int len);
static int      init_i2c(void);
static int      read_flow_rate(int handle, float *flow_out);
static void     log_flow_data(float f1, float f2);
static void     control_relay(float f1, float f2);
static void     cleanup(void);
static void     signal_handler(int sig);

/* ----------------------------- CRC-8 (Sensirion) ------------------------- */
static uint8_t crc8(const uint8_t *data, int len)
{
    uint8_t crc = CRC8_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ CRC8_POLY);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ----------------------------- I2C init ----------------------------------- */
static int init_i2c(void)
{
    i2c_h1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (i2c_h1 < 0) {
        fprintf(stderr, "Error opening I2C for sensor 1 (addr 0x%02X): %d\n",
                SENSOR1_ADDR, i2c_h1);
        return -1;
    }

    i2c_h2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (i2c_h2 < 0) {
        fprintf(stderr, "Error opening I2C for sensor 2 (addr 0x%02X): %d\n",
                SENSOR2_ADDR, i2c_h2);
        i2cClose(i2c_h1);
        i2c_h1 = -1;
        return -1;
    }

    /* Start continuous measurement on both sensors */
    uint8_t cmd[MEAS_START_CMD_LEN];
    cmd[0] = (uint8_t)(MEAS_START_CMD >> 8);
    cmd[1] = (uint8_t)(MEAS_START_CMD & 0xFF);

    if (i2cWriteDevice(i2c_h1, (char *)cmd, MEAS_START_CMD_LEN) != 0) {
        fprintf(stderr, "Error starting measurement on sensor 1\n");
        i2cClose(i2c_h1); i2c_h1 = -1;
        i2cClose(i2c_h2); i2c_h2 = -1;
        return -1;
    }
    if (i2cWriteDevice(i2c_h2, (char *)cmd, MEAS_START_CMD_LEN) != 0) {
        fprintf(stderr, "Error starting measurement on sensor 2\n");
        i2cClose(i2c_h1); i2c_h1 = -1;
        i2cClose(i2c_h2); i2c_h2 = -1;
        return -1;
    }

    return 0;
}

/* ----------------------------- Read flow ---------------------------------- */
static int read_flow_rate(int handle, float *flow_out)
{
    uint8_t buf[3];
    int n = i2cReadDevice(handle, (char *)buf, 3);
    if (n != 3) {
        fprintf(stderr, "I2C read failed (handle %d): got %d bytes\n",
                handle, n);
        return -1;
    }

    /* Validate CRC over the two data bytes */
    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on handle %d\n", handle);
        return -1;
    }

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *flow_out = (float)raw * FLOW_SCALE_FACTOR;
    return 0;
}

/* ----------------------------- Logging ------------------------------------ */
static void log_flow_data(float f1, float f2)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return;
    }

    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        fclose(fp);
        return;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char ts_str[40];
    strftime(ts_str, sizeof(ts_str), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(fp, "%s.%03ld, Sensor1: %.4f ml/min, Sensor2: %.4f ml/min\n",
            ts_str, ts.tv_nsec / 1000000L, f1, f2);
    fflush(fp);
    fclose(fp);
}

/* ----------------------------- Relay control ------------------------------ */
static void control_relay(float f1, float f2)
{
    int state = (f1 < FLOW_THRESHOLD || f2 < FLOW_THRESHOLD) ? 1 : 0;
    if (gpioWrite(RELAY_GPIO, state) != 0)
        fprintf(stderr, "Warning: gpioWrite(%d) failed\n", RELAY_GPIO);
}

/* ----------------------------- Cleanup ------------------------------------ */
static void cleanup(void)
{
    if (i2c_h1 >= 0) { i2cClose(i2c_h1); i2c_h1 = -1; }
    if (i2c_h2 >= 0) { i2cClose(i2c_h2); i2c_h2 = -1; }
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
}

/* ----------------------------- Signal handler ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ----------------------------- Main --------------------------------------- */
int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d) failed\n", RELAY_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_GPIO, 0);

    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        gpioWrite(RELAY_GPIO, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        float f1 = 0.0f, f2 = 0.0f;
        int ok1 = read_flow_rate(i2c_h1, &f1);
        int ok2 = read_flow_rate(i2c_h2, &f2);

        if (ok1 == 0 && ok2 == 0) {
            log_flow_data(f1, f2);
            control_relay(f1, f2);
        } else {
            fprintf(stderr, "Read error — skipping cycle\n");
        }

        gpioDelay(POLL_DELAY_US);
    }

    cleanup();
    printf("Shutdown complete.\n");
    return EXIT_SUCCESS;
}

