#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>

#define RAIN_SENSOR_PIN 17
#define MOTOR_ENABLE_PIN 22
#define MOTOR_INPUT1_PIN 23
#define MOTOR_INPUT2_PIN 24

#define MOTOR_RUN_TIME_US 5000000  /* 5 seconds in microseconds */
#define POLL_INTERVAL_US 200000     /* 200 ms */
#define DRY_THRESHOLD 3             /* 3 consecutive dry polls ≈ 600 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int safe_set_mode(unsigned pin, unsigned mode)
{
    if (gpioSetMode(pin, mode) < 0) {
        syslog(LOG_ERR, "gpioSetMode(pin=%u, mode=%u) failed", pin, mode);
        return -1;
    }
    return 0;
}

static int safe_write(unsigned pin, unsigned level)
{
    if (gpioWrite(pin, level) < 0) {
        syslog(LOG_ERR, "gpioWrite(pin=%u, level=%u) failed", pin, level);
        return -1;
    }
    return 0;
}

static int safe_set_pull(unsigned pin, unsigned pud)
{
    if (gpioSetPullUpDown(pin, pud) < 0) {
        syslog(LOG_ERR, "gpioSetPullUpDown(pin=%u, pud=%u) failed", pin, pud);
        return -1;
    }
    return 0;
}

static int safe_set_input(unsigned pin)
{
    return safe_set_mode(pin, PI_INPUT);
}

static int safe_set_output(unsigned pin)
{
    return safe_set_mode(pin, PI_OUTPUT);
}

static int safe_set_pull_up(unsigned pin)
{
    return safe_set_pull(pin, PI_PUD_UP);
}

static int safe_set_pull_down(unsigned pin)
{
    return safe_set_pull(pin, PI_PUD_DOWN);
}

static int safe_set_input_pull_up(unsigned pin)
{
    if (safe_set_input(pin) < 0) return -1;
    if (safe_set_pull_up(pin) < 0) return -1;
    return 0;
}

static int safe_set_output_low(unsigned pin)
{
    if (safe_set_output(pin) < 0) return -1;
    if (safe_write(pin, 0) < 0) return -1;
    return 0;
}

static int safe_stop_motor(void)
{
    int rc = 0;
    if (safe_write(MOTOR_INPUT1_PIN, 0) < 0) rc = -1;
    if (safe_write(MOTOR_INPUT2_PIN, 0) < 0) rc = -1;
    if (safe_write(MOTOR_ENABLE_PIN, 0) < 0) rc = -1;
    return rc;
}

static int safe_start_motor(void)
{
    int rc = 0;
    if (safe_write(MOTOR_INPUT1_PIN, 1) < 0) rc = -1;
    if (safe_write(MOTOR_INPUT2_PIN, 0) < 0) rc = -1;
    if (safe_write(MOTOR_ENABLE_PIN, 1) < 0) rc = -1;
    return rc;
}

static int safe_motor_run(int duration_us)
{
    if (safe_start_motor() < 0) return -1;
    syslog(LOG_INFO, "Motor started for %d us", duration_us);
    usleep(duration_us);
    if (safe_stop_motor() < 0) return -1;
    syslog(LOG_INFO, "Motor stopped");
    return 0;
}

static int safe_cleanup(void)
{
    int rc = 0;
    if (safe_stop_motor() < 0) rc = -1;
    if (gpioTerminate() < 0) {
        syslog(LOG_ERR, "gpioTerminate() failed");
        rc = -1;
    }
    return rc;
}

int main(void)
{
    openlog("rain_window", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        syslog(LOG_ERR, "sigaction(SIGINT) failed");
        closelog();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "sigaction(SIGTERM) failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "gpioInitialise() failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (safe_set_input_pull_up(RAIN_SENSOR_PIN) < 0) {
        safe_cleanup();
        closelog();
        return EXIT_FAILURE;
    }
    if (safe_set_output_low(MOTOR_ENABLE_PIN) < 0) {
        safe_cleanup();
        closelog();
        return EXIT_FAILURE;
    }
    if (safe_set_output_low(MOTOR_INPUT1_PIN) < 0) {
        safe_cleanup();
        closelog();
        return EXIT_FAILURE;
    }
    if (safe_set_output_low(MOTOR_INPUT2_PIN) < 0) {
        safe_cleanup();
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Program started");

    int dry_count = 0;
    int last_rain = 1;  /* assume dry at startup (pull-up high) */
    int motor_active = 0;

    while (g_running) {
        int rain = gpioRead(RAIN_SENSOR_PIN);
        if (rain < 0) {
            syslog(LOG_ERR, "gpioRead(rain=%d) failed", RAIN_SENSOR_PIN);
            usleep(POLL_INTERVAL_US);
            continue;
        }

        if (rain == 0 && last_rain == 1) {
            syslog(LOG_INFO, "Rain detected (rising edge)");
            if (safe_motor_run(MOTOR_RUN_TIME_US) < 0) {
                syslog(LOG_ERR, "Motor run failed");
            } else {
                motor_active = 0;
            }
        }

        if (rain == 1) {
            dry_count++;
        } else {
            dry_count = 0;
        }

        if (dry_count >= DRY_THRESHOLD && motor_active) {
            syslog(LOG_INFO, "Sensor dry for %d polls, stopping motor", DRY_THRESHOLD);
            if (safe_stop_motor() < 0) {
                syslog(LOG_ERR, "Failed to stop motor");
            } else {
                motor_active = 0;
            }
        }

        last_rain = rain;
        usleep(POLL_INTERVAL_US);
    }

    syslog(LOG_INFO, "Shutting down");
    if (safe_stop_motor() < 0) {
        syslog(LOG_ERR, "Failed to stop motor during shutdown");
    }
    if (safe_cleanup() < 0) {
        syslog(LOG_ERR, "Cleanup failed");
    }
    syslog(LOG_INFO, "Program terminated");
    closelog();
    return EXIT_SUCCESS;
}

