#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SERVO_PIN      18
#define LOCK_BUTTON    21
#define UNLOCK_BUTTON  22

#define LOCK_PULSE_US   2000
#define UNLOCK_PULSE_US 1000
#define DEBOUNCE_US     50000   /* 50 ms debounce */
#define POLL_US         10000   /* 10 ms poll interval */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int set_servo_pulse(int pulse_us)
{
    if (gpioServo(SERVO_PIN, pulse_us) < 0) {
        fprintf(stderr, "Error: gpioServo(%d) failed\n", pulse_us);
        return -1;
    }
    return 0;
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(SERVO_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LOCK_BUTTON, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(LOCK_BUTTON) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(UNLOCK_BUTTON, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(UNLOCK_BUTTON) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(LOCK_BUTTON, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown(LOCK_BUTTON) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(UNLOCK_BUTTON, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown(UNLOCK_BUTTON) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }
    if (signal(SIGTERM, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Warning: could not install SIGTERM handler\n");
    }

    printf("Door lock control ready. Press Ctrl+C to exit.\n");
    printf("  Lock button  : GPIO %d (BCM)\n", LOCK_BUTTON);
    printf("  Unlock button: GPIO %d (BCM)\n", UNLOCK_BUTTON);
    printf("  Servo pin    : GPIO %d (BCM)\n", SERVO_PIN);
    printf("  Lock pulse   : %d us\n", LOCK_PULSE_US);
    printf("  Unlock pulse : %d us\n", UNLOCK_PULSE_US);
    fflush(stdout);

    while (g_running) {
        if (gpioRead(LOCK_BUTTON) == 0) {
            if (set_servo_pulse(LOCK_PULSE_US) < 0) {
                gpioTerminate();
                return EXIT_FAILURE;
            }
            printf("Locking door...\n");
            fflush(stdout);
            gpioDelay(DEBOUNCE_US);
        }

        if (gpioRead(UNLOCK_BUTTON) == 0) {
            if (set_servo_pulse(UNLOCK_PULSE_US) < 0) {
                gpioTerminate();
                return EXIT_FAILURE;
            }
            printf("Unlocking door...\n");
            fflush(stdout);
            gpioDelay(DEBOUNCE_US);
        }

        gpioDelay(POLL_US);
    }

    printf("\nShutting down...\n");
    fflush(stdout);

    /* Stop servo pulses */
    if (gpioServo(SERVO_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioServo(0) failed\n");
    }

    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

