#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define PIR_PIN 4
#define LED_PIN 17
#define POLL_INTERVAL_US 100000
#define LED_ON_DURATION_S 60
#define LOG_FILE "security_log.txt"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_event(const char *event_type, const char *timestamp, int duration) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    if (fprintf(fp, "%s,%s,%d\n", event_type, timestamp, duration) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int log_motion_event(const char *timestamp) {
    return log_event("Motion", timestamp, 0);
}

static int log_led_event(const char *timestamp, int duration) {
    return log_event("LED", timestamp, duration);
}

static void get_timestamp(char *buf, size_t len) {
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        snprintf(buf, len, "1970-01-01T00:00:00");
        return;
    }
    strftime(buf, len, "%Y-%m-%dT%H:%M:%S", timeinfo);
}

int main(void) {
    int pir_state = 0;
    int led_state = 0;
    int ret = EXIT_SUCCESS;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PIR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set PIR pin mode\n");
        ret = EXIT_FAILURE;
        goto cleanup;
    }
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED pin mode\n");
        ret = EXIT_FAILURE;
        goto cleanup;
    }

    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialize LED pin state\n");
        ret = EXIT_FAILURE;
        goto cleanup;
    }

    printf("Security system started. Press Ctrl+C to exit.\n");

    while (running) {
        int current_pir = gpioRead(PIR_PIN);
        if (current_pir < 0) {
            fprintf(stderr, "Error reading PIR pin\n");
            ret = EXIT_FAILURE;
            break;
        }

        if (current_pir == 1 && pir_state == 0) {
            char timestamp[32];
            get_timestamp(timestamp, sizeof(timestamp));

            if (log_motion_event(timestamp) != 0) {
                fprintf(stderr, "Failed to log motion event\n");
                ret = EXIT_FAILURE;
                break;
            }

            if (gpioWrite(LED_PIN, 1) != 0) {
                fprintf(stderr, "Failed to turn on LED\n");
                ret = EXIT_FAILURE;
                break;
            }
            led_state = 1;

            printf("Motion detected! Floodlight ON.\n");

            time_t start_time = time(NULL);
            if (start_time == (time_t)-1) {
                fprintf(stderr, "Failed to get current time\n");
                ret = EXIT_FAILURE;
                break;
            }

            while (running && (time(NULL) - start_time) < LED_ON_DURATION_S) {
                gpioDelay(POLL_INTERVAL_US);
            }

            if (led_state == 1) {
                if (gpioWrite(LED_PIN, 0) != 0) {
                    fprintf(stderr, "Failed to turn off LED\n");
                    ret = EXIT_FAILURE;
                    break;
                }
                led_state = 0;
                printf("Floodlight OFF.\n");
            }

            time_t end_time = time(NULL);
            if (end_time == (time_t)-1) {
                fprintf(stderr, "Failed to get end time\n");
                ret = EXIT_FAILURE;
                break;
            }

            int duration = (int)(end_time - start_time);
            if (log_led_event(timestamp, duration) != 0) {
                fprintf(stderr, "Failed to log LED event\n");
                ret = EXIT_FAILURE;
                break;
            }
        }

        pir_state = current_pir;
        gpioDelay(POLL_INTERVAL_US);
    }

cleanup:
    if (led_state == 1) {
        gpioWrite(LED_PIN, 0);
    }
    gpioTerminate();
    return ret;
}

