    if (mpr121_write(handle, MPR121_CONFIG1, 0x10) < 0) return -1;
    if (mpr121_write(handle, MPR121_CONFIG2, 0x20) < 0) return -1;

    if (mpr121_write(handle, MPR121_AUTOCONFIG0, 0x0B) < 0) return -1;
    if (mpr121_write(handle, MPR121_AUTOCONFIG1, 0x00) < 0) return -1;
    if (mpr121_write(handle, MPR121_USL, 0xC8) < 0) return -1;
    if (mpr121_write(handle, MPR121_LSL, 0x82) < 0) return -1;
    if (mpr121_write(handle, MPR121_TL, 0xB4) < 0) return -1;

    if (mpr121_write(handle, MPR121_ELECONFIG, 0x0C) < 0) return -1;
    return 0;
}

static int mpr121_read_touch_status(int handle) {
    int lo = mpr121_read(handle, MPR121_TOUCHSTATUS_L);
    if (lo < 0) return -1;
    int hi = mpr121_read(handle, MPR121_TOUCHSTATUS_H);
    if (hi < 0) return -1;
    return (hi << 8) | lo;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(1, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1 at address 0x%02X: %s\n", MPR121_ADDR, pigpio_error(i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (mpr121_init(i2c_handle) < 0) {
        fprintf(stderr, "MPR121 initialization failed (sensor may be absent or bus error)\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY_GPIO);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(RELAY_GPIO, 0) < 0) {
        fprintf(stderr, "Failed to set GPIO %d LOW\n", RELAY_GPIO);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Relay control started. Press Ctrl+C to exit.\n");

    uint32_t last_touch_time = 0;
    bool relay_state = false;

    while (running) {
        int touch_status = mpr121_read_touch_status(i2c_handle);
        if (touch_status < 0) {
            fprintf(stderr, "Error reading touch status, retrying...\n");
            gpioDelay(100000);
            continue;
        }

        if (touch_status & 0x01) {
            uint32_t now = gpioTick();
            if (now - last_touch_time > DEBOUNCE_MS * 1000) {
                relay_state = !relay_state;
                if (gpioWrite(RELAY_GPIO, relay_state ? 1 : 0) < 0) {
                    fprintf(stderr, "Failed to write GPIO %d\n", RELAY_GPIO);
                } else {
                    printf("Relay toggled to %s\n", relay_state ? "ON" : "OFF");
                }
                last_touch_time = now;
            }
        }

        gpioDelay(10000);
    }

    gpioWrite(RELAY_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("Program terminated cleanly.\n");
    return EXIT_SUCCESS;
}

