#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <syslog.h>
#include <stdarg.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define SERVO_PIN 17
#define PIR_PIN 4
#define PORT 5000
#define LOG_FILE "security.log"
#define MAX_COMMAND_LENGTH 256
#define MAX_RESPONSE_LENGTH 256
#define SERVO_MIN_PULSE_WIDTH 1000
#define SERVO_MAX_PULSE_WIDTH 2000
#define SERVO_FREQUENCY 50

static volatile sig_atomic_t running = 1;
static int server_fd = -1;
static FILE *log_file = NULL;

static void log_message(int priority, const char *format, ...) {
    va_list args;
    va_start(args, format);
    char buffer[MAX_COMMAND_LENGTH];
    vsnprintf(buffer, sizeof(buffer), format, args);
    va_end(args);

    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char time_buf[80];
    strftime(time_buf, sizeof(time_buf), "%Y-%m-%dT%H:%M:%S", tstruct);

    if (log_file) {
        fprintf(log_file, "%s: %s\n", time_buf, buffer);
        fflush(log_file);
    }
    syslog(priority, "%s: %s", time_buf, buffer);
}

static void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

static int set_servo_angle(int angle) {
    if (angle < 0 || angle > 180) {
        log_message(LOG_ERR, "Invalid angle: %d. Must be between 0 and 180.", angle);
        return -1;
    }

    int pulse_width = SERVO_MIN_PULSE_WIDTH + (int)((float)angle / 180.0 * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH));

    if (gpioServo(SERVO_PIN, pulse_width) < 0) {
        log_message(LOG_ERR, "Failed to set servo pulse width to %d.", pulse_width);
        return -1;
    }

    char log_buffer[64];
    snprintf(log_buffer, sizeof(log_buffer), "Servo angle set to %d degrees (pulse width: %d us).", angle, pulse_width);
    log_message(LOG_INFO, "%s", log_buffer);
    return 0;
}

static int read_pir_sensor(void) {
    int pir_value = gpioRead(PIR_PIN);
    if (pir_value < 0) {
        log_message(LOG_ERR, "Failed to read PIR sensor.");
        return -1;
    }
    return pir_value;
}

static int handle_client(int client_socket) {
    char buffer[MAX_COMMAND_LENGTH];
    ssize_t bytes_received = recv(client_socket, buffer, sizeof(buffer) - 1, 0);
    if (bytes_received < 0) {
        log_message(LOG_ERR, "recv failed: %s", strerror(errno));
        return -1;
    } else if (bytes_received == 0) {
        log_message(LOG_INFO, "Client disconnected.");
        return 0;
    }

    buffer[bytes_received] = '\0';
    char *newline = strpbrk(buffer, "\r\n");
    if (newline) *newline = '\0';

    char log_buffer[MAX_COMMAND_LENGTH + 32];
    snprintf(log_buffer, sizeof(log_buffer), "Received command: %s", buffer);
    log_message(LOG_INFO, "%s", log_buffer);

    char response[MAX_RESPONSE_LENGTH];
    if (strncmp(buffer, "PIR", 3) == 0) {
        int pir_value = read_pir_sensor();
        if (pir_value < 0) {
            snprintf(response, sizeof(response), "PIR:ERROR");
        } else {
            snprintf(response, sizeof(response), "PIR:%d", pir_value);
        }
    } else if (strncmp(buffer, "set_servo_angle", 15) == 0) {
        int angle = atoi(buffer + 15);
        if (set_servo_angle(angle) == 0) {
            snprintf(response, sizeof(response), "OK");
        } else {
            snprintf(response, sizeof(response), "ERROR");
        }
    } else {
        snprintf(response, sizeof(response), "UNKNOWN_COMMAND");
    }

    if (send(client_socket, response, strlen(response), 0) < 0) {
        log_message(LOG_ERR, "send failed: %s", strerror(errno));
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    if (server_fd >= 0) {
        close(server_fd);
        server_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
    closelog();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    openlog("security_system", LOG_PID | LOG_CONS, LOG_USER);
    log_message(LOG_INFO, "Starting security system...");

    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed.");
        closelog();
        return 1;
    }

    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        log_message(LOG_ERR, "Failed to set SERVO_PIN %d as output.", SERVO_PIN);
        gpioTerminate();
        closelog();
        return 1;
    }

    if (gpioSetMode(PIR_PIN, PI_INPUT) < 0) {
        log_message(LOG_ERR, "Failed to set PIR_PIN %d as input.", PIR_PIN);
        gpioTerminate();
        closelog();
        return 1;
    }

    if (gpioSetPullUpDown(PIR_PIN, PI_PUD_DOWN) < 0) {
        log_message(LOG_WARNING, "Failed to set pull-down on PIR_PIN %d.", PIR_PIN);
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        log_message(LOG_ERR, "Failed to open log file: %s", strerror(errno));
        gpioTerminate();
        closelog();
        return 1;
    }

    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        log_message(LOG_ERR, "Socket creation failed: %s", strerror(errno));
        cleanup();
        return 1;
    }

    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        log_message(LOG_WARNING, "setsockopt failed: %s", strerror(errno));
    }

    struct sockaddr_in address;
    memset(&address, 0, sizeof(address));
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        log_message(LOG_ERR, "Bind failed: %s", strerror(errno));
        cleanup();
        return 1;
    }

    if (listen(server_fd, 3) < 0) {
        log_message(LOG_ERR, "Listen failed: %s", strerror(errno));
        cleanup();
        return 1;
    }

    log_message(LOG_INFO, "Listening on port %d...", PORT);

    while (running) {
        struct sockaddr_in client_address;
        socklen_t addrlen = sizeof(client_address);
        int client_socket = accept(server_fd, (struct sockaddr *)&client_address, &addrlen);
        if (client_socket < 0) {
            if (errno == EINTR && !running) {
                break;
            }
            log_message(LOG_ERR, "Accept failed: %s", strerror(errno));
            continue;
        }

        char client_ip[INET_ADDRSTRLEN];
        inet_ntop(AF_INET, &client_address.sin_addr, client_ip, sizeof(client_ip));
        log_message(LOG_INFO, "Connection accepted from %s:%d", client_ip, ntohs(client_address.sin_port));

        if (handle_client(client_socket) < 0) {
            log_message(LOG_ERR, "Error handling client.");
        }

        close(client_socket);
    }

    log_message(LOG_INFO, "Shutting down...");
    cleanup();
    return 0;
}

