#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define BH1750_ADDR             0x23
#define GROW_LIGHT_GPIO         23
#define LUX_THRESHOLD           150
#define SAMPLE_INTERVAL_SEC     2
#define BH1750_MEASUREMENT_MS   120
#define LOG_FILE_NAME           "grow_log.txt"

/* BH1750 continuous high-resolution mode (0x10) */
#define BH1750_CONT_HIGH_RES    0x10

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    /* Deactivate relay before terminating pigpio */
    gpioWrite(GROW_LIGHT_GPIO, 0);
    gpioTerminate();
}

static int read_bh1750(int handle, float *lux_out)
{
    char buf[2];
    int  rc;

    /* Send measurement command */
    rc = i2cWriteByte(handle, BH1750_CONT_HIGH_RES);
    if (rc < 0) {
        fprintf(stderr, "I2C write error (trigger): %d\n", rc);
        return -1;
    }

    /* Wait for conversion (max 120 ms for high-res mode) */
    gpioDelay(BH1750_MEASUREMENT_MS * 1000);

    /* Read 2-byte result */
    rc = i2cReadDevice(handle, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "I2C read error: expected 2 bytes, got %d\n", rc);
        return -1;
    }

    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static void log_data(FILE *fp, float lux)
{
    time_t     t;
    struct tm  tm_info;
    char       ts[32];

    time(&t);
    localtime_r(&t, &tm_info);
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(fp, "%s, %.2f\n", ts, lux);
    fflush(fp);
}

int main(void)
{
    float lux;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (g_log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure relay GPIO */
    if (gpioSetMode(GROW_LIGHT_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GROW_LIGHT_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(GROW_LIGHT_GPIO, 0);

    /* Open I2C bus 1 at BH1750 address */
    g_i2c_handle = i2cOpen(1, BH1750_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X: %d\n",
                BH1750_ADDR, g_i2c_handle);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Grow light controller started. Sampling every %d s.\n",
           SAMPLE_INTERVAL_SEC);

    while (g_running) {
        if (read_bh1750(g_i2c_handle, &lux) == 0) {
            log_data(g_log_file, lux);

            if (lux < LUX_THRESHOLD) {
                gpioWrite(GROW_LIGHT_GPIO, 1);
                printf("Lux %.2f < %d -> grow light ON\n", lux, LUX_THRESHOLD);
            } else {
                gpioWrite(GROW_LIGHT_GPIO, 0);
                printf("Lux %.2f >= %d -> grow light OFF\n", lux, LUX_THRESHOLD);
            }
        } else {
            fprintf(stderr, "Sensor read failed; will retry next cycle.\n");
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_SEC * 10 && g_running; i++) {
            gpioDelay(100000);
        }
