#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>
#include <getopt.h>

#define HX711_DOUT 23
#define HX711_SCK  24
#define SOLENOID_PIN 25

#define DEFAULT_THRESHOLD 1000.0
#define DEFAULT_SCALE 1.0
#define DEFAULT_DURATION 200
#define TARE_READINGS 10
#define MEASUREMENT_READINGS 5
#define MAX_RETRIES 3
#define DOUT_TIMEOUT_US 1000000
#define LOOP_DELAY_US 500000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_hx711(int *out_value) {
    if (gpioWrite(HX711_SCK, 0) < 0) {
        syslog(LOG_ERR, "Failed to write SCK LOW");
        return -1;
    }

    uint32_t start = gpioTick();
    while (gpioRead(HX711_DOUT)) {
        if (gpioTick() - start > DOUT_TIMEOUT_US) {
            syslog(LOG_ERR, "HX711 DOUT stuck HIGH (timeout)");
            return -1;
        }
        gpioDelay(100);
    }

    uint32_t raw = 0;
    for (int i = 0; i < 24; i++) {
        if (gpioWrite(HX711_SCK, 1) < 0) {
            syslog(LOG_ERR, "Failed to write SCK HIGH");
            return -1;
        }
        gpioDelay(1);
        raw <<= 1;
        if (gpioRead(HX711_DOUT)) {
            raw |= 1;
        }
        if (gpioWrite(HX711_SCK, 0) < 0) {
            syslog(LOG_ERR, "Failed to write SCK LOW");
            return -1;
        }
        gpioDelay(1);
    }

    if (gpioWrite(HX711_SCK, 1) < 0) {
        syslog(LOG_ERR, "Failed to write SCK HIGH for gain");
        return -1;
    }
    gpioDelay(1);
    if (gpioWrite(HX711_SCK, 0) < 0) {
        syslog(LOG_ERR, "Failed to write SCK LOW for gain");
        return -1;
    }
    gpioDelay(1);

    if (raw & 0x800000) {
        raw |= 0xFF000000;
    }

    *out_value = (int32_t)raw;
    return 0;
}

static int read_hx711_with_retry(int *out_value) {
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (read_hx711(out_value) == 0) {
            return 0;
        }
        syslog(LOG_WARNING, "HX711 read attempt %d/%d failed", attempt + 1, MAX_RETRIES);
        if (attempt < MAX_RETRIES - 1) {
            gpioDelay(100000);
        }
    }
    syslog(LOG_ERR, "HX711 read failed after %d attempts", MAX_RETRIES);
    return -1;
}

static double calculate_average_weight(int num_readings) {
    double sum = 0.0;
    int valid = 0;
    for (int i = 0; i < num_readings; i++) {
        int raw;
        if (read_hx711_with_retry(&raw) != 0) {
            syslog(LOG_ERR, "Failed to read HX711 during average (%d/%d)", i + 1, num_readings);
            continue;
        }
        sum += (double)raw;
        valid++;
    }
    if (valid == 0) {
        return 0.0;
    }
    return sum / valid;
}

static int tare_hx711(double *offset) {
    double sum = 0.0;
    int valid = 0;
    for (int i = 0; i < TARE_READINGS; i++) {
        int raw;
        if (read_hx711_with_retry(&raw) != 0) {
            syslog(LOG_ERR, "Tare failed at reading %d", i + 1);
            continue;
        }
        sum += (double)raw;
        valid++;
        gpioDelay(100000);
    }
    if (valid == 0) {
        syslog(LOG_ERR, "Tare failed: no valid readings");
        return -1;
    }
    *offset = sum / valid;
    syslog(LOG_INFO, "Tare complete, offset: %.2f", *offset);
    return 0;
}

static void activate_solenoid(int duration_ms) {
    if (gpioWrite(SOLENOID_PIN, 1) < 0) {
        syslog(LOG_ERR, "Failed to set solenoid HIGH");
        return;
    }
    gpioDelay(duration_ms * 1000);
    if (gpioWrite(SOLENOID_PIN, 0) < 0) {
        syslog(LOG_ERR, "Failed to set solenoid LOW");
    }
}

int main(int argc, char *argv[]) {
    double threshold = DEFAULT_THRESHOLD;
    double scale = DEFAULT_SCALE;
    int duration = DEFAULT_DURATION;
    int opt;

    while ((opt = getopt(argc, argv, "t:s:d:h")) != -1) {
        switch (opt) {
            case 't':
                threshold = atof(optarg);
                break;
            case 's':
                scale = atof(optarg);
                break;
            case 'd':
                duration = atoi(optarg);
                break;
            case 'h':
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-s scale] [-d duration]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    openlog("weight_monitor", LOG_PID | LOG_CONS, LOG_USER);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(HX711_DOUT, PI_INPUT) < 0) {
        syslog(LOG_ERR, "Failed to set HX711_DOUT as input");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(HX711_SCK, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set HX711_SCK as output");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SOLENOID_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set SOLENOID_PIN as output");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioWrite(SOLENOID_PIN, 0) < 0) {
        syslog(LOG_ERR, "Failed to initialize solenoid to LOW");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to set signal handlers");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    double offset = 0.0;
    if (tare_hx711(&offset) != 0) {
        syslog(LOG_ERR, "Tare failed, exiting");
        gpioWrite(SOLENOID_PIN, 0);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Weight monitoring started (threshold=%.2f, scale=%.2f, duration=%dms)", threshold, scale, duration);

    while (running) {
        double weight = calculate_average_weight(MEASUREMENT_READINGS) - offset;
        weight *= scale;

        syslog(LOG_INFO, "Weight: %.2f grams", weight);

        if (weight > threshold) {
            syslog(LOG_INFO, "Threshold exceeded (%.2f > %.2f), activating solenoid", weight, threshold);
            activate_solenoid(duration);
        }

        gpioDelay(LOOP_DELAY_US);
    }

    syslog(LOG_INFO, "Shutting down gracefully");
    gpioWrite(SOLENOID_PIN, 0);
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

