/*
 * relay_controller.c — MQTT relay controller for Raspberry Pi 4 Model B
 *
 * Build:  gcc -O2 -Wall -Wextra -o relay_controller relay_controller.c \
 *             -lmosquitto -lgpiod
 * Run:    ./relay_controller
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <errno.h>
#include <stdbool.h>
#include <gpiod.h>
#include <mosquitto.h>

#define MQTT_BROKER_ADDRESS  "localhost"
#define MQTT_BROKER_PORT     1883
#define MQTT_CLIENT_ID       "relay_controller_1"
#define MQTT_TOPIC           "home/lights/control"
#define MQTT_KEEPALIVE       60
#define GPIO_CHIP_NAME       "gpiochip4"
#define GPIO_LINE_OFFSET     17
#define GPIO_CONSUMER        "relay_controller"
#define PAYLOAD_BUFFER_SIZE  256
#define RECONNECT_DELAY_SEC  5

static volatile sig_atomic_t g_running = 1;
static struct mosquitto *g_mqtt = NULL;
static struct gpiod_chip *g_chip = NULL;
static struct gpiod_line *g_line = NULL;

static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

static void log_syslog(int priority, const char *message)
{
    syslog(priority, "%s", message);
}

static void log_syslog_err(int priority, const char *message)
{
    syslog(priority, "%s: %s", message, strerror(errno));
}

static int set_relay_state(bool on)
{
    int ret = gpiod_line_set_value(g_line, on ? 1 : 0);
    if (ret < 0) {
        log_syslog_err(LOG_ERR, "Failed to set GPIO value");
        return -1;
    }
    return 0;
}

static void on_connect(struct mosquitto *m, void *userdata, int result)
{
    (void)userdata;
    if (result == MOSQ_ERR_SUCCESS) {
        log_syslog(LOG_INFO, "Connected to MQTT broker");
        int rc = mosquitto_subscribe(m, NULL, MQTT_TOPIC, 0);
        if (rc != MOSQ_ERR_SUCCESS) {
            log_syslog(LOG_ERR, "Failed to subscribe to topic");
        } else {
            log_syslog(LOG_INFO, "Subscribed to topic");
        }
    } else {
        char msg[128];
        snprintf(msg, sizeof(msg), "MQTT connection error: %s",
                 mosquitto_connack_string(result));
        log_syslog(LOG_ERR, msg);
    }
}

static void on_disconnect(struct mosquitto *m, void *userdata, int rc)
{
    (void)m;
    (void)userdata;
    if (rc == 0) {
        log_syslog(LOG_INFO, "Disconnected from MQTT broker");
    } else {
        char msg[128];
        snprintf(msg, sizeof(msg), "Unexpected MQTT disconnect: %s",
                 mosquitto_strerror(rc));
        log_syslog(LOG_ERR, msg);
    }
}

static void on_message(struct mosquitto *m, void *userdata,
                       const struct mosquitto_message *message)
{
    (void)m;
    (void)userdata;

    if (message->payloadlen <= 0) {
        log_syslog(LOG_ERR, "Received empty MQTT payload");
        return;
    }

    char payload[PAYLOAD_BUFFER_SIZE];
    size_t len = (size_t)message->payloadlen;
    if (len >= PAYLOAD_BUFFER_SIZE) {
        len = PAYLOAD_BUFFER_SIZE - 1;
    }
    memcpy(payload, message->payload, len);
    payload[len] = '\0';

    if (strcmp(payload, "ON") == 0) {
        if (set_relay_state(true) == 0) {
            log_syslog(LOG_INFO, "Relay ON");
        }
    } else if (strcmp(payload, "OFF") == 0) {
        if (set_relay_state(false) == 0) {
            log_syslog(LOG_INFO, "Relay OFF");
        }
    } else {
        char msg[256];
        snprintf(msg, sizeof(msg),
                 "Invalid payload received: %s", payload);
        log_syslog(LOG_ERR, msg);
    }
}

static int initialize_gpio(void)
{
    g_chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!g_chip) {
        log_syslog_err(LOG_ERR, "Failed to open GPIO chip");
        return -1;
    }

    g_line = gpiod_chip_get_line(g_chip, GPIO_LINE_OFFSET);
    if (!g_line) {
        log_syslog_err(LOG_ERR, "Failed to get GPIO line");
        gpiod_chip_close(g_chip);
        g_chip = NULL;
        return -1;
    }

    if (gpiod_line_request_output(g_line, GPIO_CONSUMER, 0) < 0) {
        log_syslog_err(LOG_ERR, "Failed to request GPIO line as output");
        g_line = NULL;
        gpiod_chip_close(g_chip);
        g_chip = NULL;
        return -1;
    }

    return 0;
}

static void cleanup_gpio(void)
{
    if (g_line) {
        gpiod_line_set_value(g_line, 0);
        gpiod_line_release(g_line);
        g_line = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
}

static int initialize_mqtt(void)
{
    mosquitto_lib_init();

    g_mqtt = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!g_mqtt) {
        log_syslog_err(LOG_ERR, "Failed to create MQTT client");
        mosquitto_lib_cleanup();
        return -1;
    }

    mosquitto_connect_callback_set(g_mqtt, on_connect);
    mosquitto_disconnect_callback_set(g_mqtt, on_disconnect);
    mosquitto_message_callback_set(g_mqtt, on_message);

    int rc = mosquitto_connect(g_mqtt, MQTT_BROKER_ADDRESS,
                               MQTT_BROKER_PORT, MQTT_KEEPALIVE);
    if (rc != MOSQ_ERR_SUCCESS) {
        char msg[128];
        snprintf(msg, sizeof(msg),
                 "Failed to connect to MQTT broker: %s",
                 mosquitto_strerror(rc));
        log_syslog(LOG_ERR, msg);
        mosquitto_destroy(g_mqtt);
        g_mqtt = NULL;
        mosquitto_lib_cleanup();
        return -1;
    }

    return 0;
}

static void cleanup_mqtt(void)
{
    if (g_mqtt) {
        mosquitto_disconnect(g_mqtt);
        mosquitto_destroy(g_mqtt);
        g_mqtt = NULL;
    }
    mosquitto_lib_cleanup();
}

int main(void)
{
    openlog("mqtt_relay", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        log_syslog_err(LOG_ERR, "Failed to register signal handler");
        closelog();
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        closelog();
        return EXIT_FAILURE;
    }

    if (initialize_mqtt() != 0) {
        cleanup_gpio();
        closelog();
        return EXIT_FAILURE;
    }

    log_syslog(LOG_INFO, "Relay controller started");

    while (g_running) {
        int rc = mosquitto_loop(g_mqtt, 1000, 1);
        if (rc != MOSQ_ERR_SUCCESS) {
            char msg[128];
            snprintf(msg, sizeof(msg),
                     "MQTT loop error: %s", mosquitto_strerror(rc));
            log_syslog(LOG_ERR, msg);
            sleep(RECONNECT_DELAY_SEC);
        }
    }

    log_syslog(LOG_INFO, "Shutting down relay controller");
    cleanup_mqtt();
    cleanup_gpio();
    closelog();
    return EXIT_SUCCESS;
}

