#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>

#define SERVO1_PIN 7
#define SERVO2_PIN 8
#define SERVO3_PIN 9
#define SERVO4_PIN 10
#define SERVO5_PIN 11

#define SERVO1_PULSE 1000
#define SERVO2_PULSE 1500
#define SERVO3_PULSE 2000
#define SERVO4_PULSE 500
#define SERVO5_PULSE 2500

#define SERVO_MIN_PULSE 500
#define SERVO_MAX_PULSE 2500
#define SERVO_HOLD_US 3000000

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int pins[5] = {SERVO1_PIN, SERVO2_PIN, SERVO3_PIN, SERVO4_PIN, SERVO5_PIN};
    int pulses[5] = {SERVO1_PULSE, SERVO2_PULSE, SERVO3_PULSE, SERVO4_PULSE, SERVO5_PULSE};

    for (int i = 0; i < 5; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioServo(pins[i], pulses[i]) != 0) {
            fprintf(stderr, "Failed to set servo pulse on GPIO %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        printf("Servo %d: GPIO %d, pulse width: %d us\n", i + 1, pins[i], pulses[i]);
    }

    for (int i = 0; i < 5; i++) {
        if (gpioServo(pins[i], pulses[i]) != 0) {
            fprintf(stderr, "Failed to maintain servo pulse on GPIO %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        gpioDelay(SERVO_HOLD_US);
    }

    for (int i = 0; i < 5; i++) {
        if (gpioServo(pins[i], 0) != 0) {
            fprintf(stderr, "Failed to stop servo on GPIO %d\n", pins[i]);
        }
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

