/*
 * Closed-loop DC motor speed control for a Raspberry Pi 3 Model B+
 * Motor A:  IN1=GPIO17 (PWM), IN2=GPIO18 (direction)
 * Motor B:  IN3=GPIO22 (PWM), IN4=GPIO23 (direction)
 * Encoder A: phase A=GPIO4, phase B=GPIO5
 * Encoder B: phase A=GPIO6, phase B=GPIO12
 *
 * Build: gcc -O2 -Wall -o motor_control motor_control.c -lpigpio -lrt
 * Run:   sudo ./motor_control
 */
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MOTOR_A_PWM_PIN    17
#define MOTOR_A_DIR_PIN    18
#define MOTOR_B_PWM_PIN    22
#define MOTOR_B_DIR_PIN    23

#define ENCODER_A_A_PIN    4
#define ENCODER_A_B_PIN    5
#define ENCODER_B_A_PIN    6
#define ENCODER_B_B_PIN    12

#define PWM_FREQUENCY      10000   /* 10 kHz */
#define PWM_RANGE          255
#define TARGET_RPM         50.0
#define TICKS_PER_REV      64.0
#define LOOP_PERIOD_US     100000  /* 100 ms */
#define STALL_TIMEOUT_S    2.0
#define STALL_TICKS        (int)(STALL_TIMEOUT_S * 1000.0 / (1.0 / (TICKS_PER_REV / 60.0)))

static volatile sig_atomic_t g_running = 1;
static volatile int32_t g_enc_a_count = 0;
static volatile int32_t g_enc_b_count = 0;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void encoder_a_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio; (void)tick; (void)userdata;
    if (level == PI_HIGH) {
        int b = gpioRead(ENCODER_A_B_PIN);
        if (b == 1) {
            __sync_fetch_and_add(&g_enc_a_count, 1);
        } else {
            __sync_fetch_and_add(&g_enc_a_count, -1);
        }
    }
}

static void encoder_b_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio; (void)tick; (void)userdata;
    if (level == PI_HIGH) {
        int a = gpioRead(ENCODER_B_A_PIN);
        if (a == 1) {
            __sync_fetch_and_add(&g_enc_b_count, 1);
        } else {
            __sync_fetch_and_add(&g_enc_b_count, -1);
        }
    }
}

static void set_motor_pwm(int pwm_pin, int duty)
{
    if (duty < 0) duty = 0;
    if (duty > PWM_RANGE) duty = PWM_RANGE;
    if (gpioPWM(pwm_pin, duty) < 0) {
        fprintf(stderr, "Warning: gpioPWM failed on pin %d\n", pwm_pin);
    }
}

static void set_motor_direction(int dir_pin, int forward)
{
    if (gpioWrite(dir_pin, forward ? 1 : 0) < 0) {
        fprintf(stderr, "Warning: gpioWrite failed on pin %d\n", dir_pin);
    }
}

static void stop_motors(void)
{
    set_motor_pwm(MOTOR_A_PWM_PIN, 0);
    set_motor_pwm(MOTOR_B_PWM_PIN, 0);
    set_motor_direction(MOTOR_A_DIR_PIN, 0);
    set_motor_direction(MOTOR_B_DIR_PIN, 0);
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Motor PWM pins */
    if (gpioSetMode(MOTOR_A_PWM_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_B_PWM_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set PWM pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(MOTOR_A_PWM_PIN, PWM_FREQUENCY) < 0 ||
        gpioSetPWMfrequency(MOTOR_B_PWM_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(MOTOR_A_PWM_PIN, PWM_RANGE) < 0 ||
        gpioSetPWMrange(MOTOR_B_PWM_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: failed to set PWM range\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    stop_motors();

    /* Motor direction pins */
    if (gpioSetMode(MOTOR_A_DIR_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_B_DIR_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set direction pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    set_motor_direction(MOTOR_A_DIR_PIN, 0);
    set_motor_direction(MOTOR_B_DIR_PIN, 0);

    /* Encoder pins */
    if (gpioSetMode(ENCODER_A_A_PIN, PI_INPUT) < 0 ||
        gpioSetMode(ENCODER_A_B_PIN, PI_INPUT) < 0 ||
        gpioSetMode(ENCODER_B_A_PIN, PI_INPUT) < 0 ||
        gpioSetMode(ENCODER_B_B_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set encoder pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(ENCODER_A_A_PIN, PI_PUD_UP) < 0 ||
        gpioSetPullUpDown(ENCODER_A_B_PIN, PI_PUD_UP) < 0 ||
        gpioSetPullUpDown(ENCODER_B_A_PIN, PI_PUD_UP) < 0 ||
        gpioSetPullUpDown(ENCODER_B_B_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: failed to set encoder pull-up\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetISRFuncEx(ENCODER_A_A_PIN, RISING_EDGE, 0, encoder_a_isr, NULL) < 0 ||
        gpioSetISRFuncEx(ENCODER_B_A_PIN, RISING_EDGE, 0, encoder_b_isr, NULL) < 0) {
        fprintf(stderr, "Error: failed to register ISR for encoders\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    double integral_a = 0.0, integral_b = 0.0;
    const double Kp = 0.1;
    const double Ki = 0.01;
    const double dt = LOOP_PERIOD_US / 1000000.0;

    printf("Motor control started. Target RPM: %.1f\n", TARGET_RPM);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        int32_t enc_a = g_enc_a_count;
        int32_t enc_b = g_enc_b_count;

        /* Reset encoder counts for this iteration */
        g_enc_a_count = 0;
        g_enc_b_count = 0;

        double rpm_a = (enc_a / dt) / (TICKS_PER_REV / 60.0);
        double rpm_b = (enc_b / dt) / (TICKS_PER_REV / 60.0);

        /* PI control for Motor A */
        double error_a = TARGET_RPM - rpm_a;
        integral_a += error_a * dt;
        double output_a = Kp * error_a + Ki * integral_a;
        int duty_a = (int)output_a;
        if (duty_a < 0) duty_a = 0;
        if (duty_a > PWM_RANGE) duty_a = PWM_RANGE;

        /* PI control for Motor B */
        double error_b = TARGET_RPM - rpm_b;
        integral_b += error_b * dt;
        double output_b = Kp * error_b + Ki * integral_b;
        int duty_b = (int)output_b;
        if (duty_b < 0) duty_b = 0;
        if (duty_b > PWM_RANGE) duty_b = PWM_RANGE;

        /* Forward motion: Motor A forward, Motor B forward */
        set_motor_direction(MOTOR_A_DIR_PIN, 1);
        set_motor_direction(MOTOR_B_DIR_PIN, 1);
        set_motor_pwm(MOTOR_A_PWM_PIN, duty_a);
        set_motor_pwm(MOTOR_B_PWM_PIN, duty_b);

        /* Stall detection */
        static uint32_t last_a_tick = 0, last_b_tick = 0;
        uint32_t now = gpioTick();
        if (enc_a == 0 && (now - last_a_tick) > (uint32_t)(STALL_TIMEOUT_S * 1000000.0)) {
            fprintf(stderr, "Warning: Motor A stall detected (0 ticks for %.0f s)\n", STALL_TIMEOUT_S);
            last_a_tick = now;
        }
        if (enc_b == 0 && (now - last_b_tick) > (uint32_t)(STALL_TIMEOUT_S * 1000000.0)) {
            fprintf(stderr, "Warning: Motor B stall detected (0 ticks for %.0f s)\n", STALL_TIMEOUT_S);
            last_b_tick = now;
        }

        printf("Motor A: RPM=%.2f, PWM=%d  |  Motor B: RPM=%.2f, PWM=%d\n",
               rpm_a, duty_a, rpm_b, duty_b);

        gpioDelay(LOOP_PERIOD_US);
    }

    printf("\nShutting down...\n");
    stop_motors();
    gpioTerminate();
    return EXIT_SUCCESS;
}

