#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>

#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define GPIO_RELAY 17
#define LUX_THRESHOLD_DUSK 50
#define LUX_THRESHOLD_DAWN 200
#define LOG_FILE "chicken_coop_log.txt"
#define POLL_INTERVAL_SEC 5
#define BH1750_MEASUREMENT_DELAY_US 180000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;
static int relay_state = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_message(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file);
}

static int read_bh1750(int handle, float *lux_out) {
    unsigned char buf[2];
    int result;

    result = i2cWriteByte(handle, 0x10);
    if (result < 0) {
        log_message("Error: Failed to write measurement command to BH1750.");
        return -1;
    }

    gpioDelay(BH1750_MEASUREMENT_DELAY_US);

    result = i2cReadDevice(handle, (char *)buf, 2);
    if (result != 2) {
        log_message("Error: Failed to read 2 bytes from BH1750.");
        return -1;
    }

    unsigned int raw = ((unsigned int)buf[0] << 8) | buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static int control_relay(int state) {
    if (gpioWrite(GPIO_RELAY, state) < 0) {
        log_message("Error: Failed to write to GPIO relay.");
        return -1;
    }
    relay_state = state;
    char msg[64];
    snprintf(msg, sizeof(msg), "Relay set to %s", state ? "ON" : "OFF");
    log_message(msg);
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (relay_state) {
        gpioWrite(GPIO_RELAY, 0);
        relay_state = 0;
    }
    if (log_file) {
        log_message("Program terminated.");
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %d\n", I2C_BUS, BH1750_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_RELAY, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", GPIO_RELAY);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(GPIO_RELAY, 0);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_message("Program started.");

    while (running) {
        float lux;
        if (read_bh1750(i2c_handle, &lux) == 0) {
            char msg[128];
            snprintf(msg, sizeof(msg), "Lux = %.2f, Relay = %s", lux, relay_state ? "ON" : "OFF");
            log_message(msg);

            if (lux < LUX_THRESHOLD_DUSK && !relay_state) {
                if (control_relay(1) != 0) {
                    log_message("Error: Failed to activate relay.");
                }
            } else if (lux > LUX_THRESHOLD_DAWN && relay_state) {
                if (control_relay(0) != 0) {
                    log_message("Error: Failed to deactivate relay.");
                }
            }
        } else {
            log_message("Error: Failed to read lux value from BH1750. Turning off relay for safety.");
            control_relay(0);
        }

        for (int i = 0; i < POLL_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

