    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set touch sensor pin %d as input\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set relay pin %d as output\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialise relay pin %d to LOW\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_relay_state(relay_state);

    while (running) {
        current_touch = gpioRead(TOUCH_SENSOR_PIN);
        if (current_touch < 0) {
            fprintf(stderr, "Failed to read touch sensor pin %d\n", TOUCH_SENSOR_PIN);
            break;
        }

        if (current_touch == 1 && last_touch == 0) {
            gpioDelay(DEBOUNCE_DELAY_US);
            int post_debounce = gpioRead(TOUCH_SENSOR_PIN);
            if (post_debounce < 0) {
                fprintf(stderr, "Failed to read touch sensor pin %d after debounce\n", TOUCH_SENSOR_PIN);
                break;
            }
            if (post_debounce == 1) {
                relay_state = !relay_state;
                if (gpioWrite(RELAY_PIN, relay_state) != 0) {
                    fprintf(stderr, "Failed to write relay pin %d\n", RELAY_PIN);
                    break;
                }
                log_relay_state(relay_state);
            }
        }

        last_touch = current_touch;
        gpioDelay(LOOP_DELAY_US);
    }

    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

