#include <pthread.h>
#include <unistd.h>

#define FLOW_SENSOR_GPIO 17
#define SOLENOID_GPIO 27
#define FLOW_RATE_THRESHOLD_HIGH 5.0
#define FLOW_RATE_THRESHOLD_LOW 4.5
#define DEBOUNCE_TIMEOUT_US 1000000
#define SAMPLE_INTERVAL_US 1000000
#define PULSE_PER_LITER 7.5

static volatile sig_atomic_t program_running = 1;
static volatile sig_atomic_t flow_sensor_triggered = 0;
static volatile uint32_t last_trigger_tick = 0;
static volatile uint32_t pulse_count = 0;
static FILE *log_file = NULL;
static pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;

static void flow_sensor_isr(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio;
    (void)level;
    (void)userdata;
    uint32_t last = last_trigger_tick;
    uint32_t diff = tick - last;
    if (diff > DEBOUNCE_TIMEOUT_US) {
        last_trigger_tick = tick;
        pulse_count++;
    }
}

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_event(const char *message) {
    if (log_file == NULL) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file);
}

static void cleanup(void) {
    if (log_file != NULL) {
        log_event("Program exiting.");
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(SOLENOID_GPIO, 1);
    gpioTerminate();
    pthread_mutex_destroy(&pulse_mutex);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set flow sensor GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SOLENOID_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set solenoid GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(SOLENOID_GPIO, 1) != 0) {
        fprintf(stderr, "Failed to initialize solenoid state\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, 0, flow_sensor_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR for flow sensor\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

