    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Failed to set signal handlers");
        cleanup();
        return EXIT_FAILURE;
    }

    log_event("Program started.");

    int solenoid_state = 1;
    log_event("Solenoid valve is OPEN.");

    while (program_running) {
        uint32_t count;
        pthread_mutex_lock(&pulse_mutex);
        count = pulse_count;
        pulse_count = 0;
        pthread_mutex_unlock(&pulse_mutex);

        double flow_rate = (double)count / PULSE_PER_LITER * 60.0;
        char log_message[128];
        snprintf(log_message, sizeof(log_message), "Flow rate: %.2f LPM", flow_rate);
        log_event(log_message);

        if (flow_rate > FLOW_RATE_THRESHOLD_HIGH && solenoid_state == 1) {
            if (gpioWrite(SOLENOID_GPIO, 0) == 0) {
                solenoid_state = 0;
                log_event("Solenoid valve is CLOSED.");
            } else {
                log_event("Error: Failed to close solenoid valve.");
            }
        } else if (flow_rate < FLOW_RATE_THRESHOLD_LOW && solenoid_state == 0) {
            if (gpioWrite(SOLENOID_GPIO, 1) == 0) {
                solenoid_state = 1;
                log_event("Solenoid valve is OPEN.");
            } else {
                log_event("Error: Failed to open solenoid valve.");
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

