#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define HX711_DATA_PIN 23
#define HX711_SCK_PIN 24
#define SERVO_PIN 18
#define CONFIG_FILE "config.ini"
#define LOG_FILE "dispensing_log.json"
#define SERVER_IP "127.0.0.1"
#define SERVER_PORT 12345
#define CALIBRATION_FACTOR_KEY "calibration_factor"
#define DEFAULT_CALIBRATION_FACTOR 1.0
#define MAX_RETRIES 1000
#define TIMEOUT_US 1000
#define SERVO_MIN_PULSE_WIDTH 1000
#define SERVO_MAX_PULSE_WIDTH 2000
#define SERVO_PULSE_WIDTH_RANGE (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH)
#define SERVO_PULSE_WIDTH_RESOLUTION 1000.0
#define DISPENSE_STABILIZE_DELAY 1

static volatile sig_atomic_t running = 1;
static double calibration_factor = DEFAULT_CALIBRATION_FACTOR;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_hx711(int *value) {
    int retries = 0;
    while (gpioRead(HX711_DATA_PIN) == 1) {
        if (retries++ > TIMEOUT_US) {
            fprintf(stderr, "HX711 timeout: DATA pin stuck HIGH\n");
            return -1;
        }
        gpioDelay(1);
    }
    long data = 0;
    for (int i = 0; i < 24; i++) {
        gpioWrite(HX711_SCK_PIN, 1);
        gpioDelay(1);
        data = (data << 1) | gpioRead(HX711_DATA_PIN);
        gpioWrite(HX711_SCK_PIN, 0);
        gpioDelay(1);
    }
    gpioWrite(HX711_SCK_PIN, 1);
    gpioDelay(1);
    gpioWrite(HX711_SCK_PIN, 0);
    gpioDelay(1);
    if (data & 0x800000) data |= 0xFF000000;
    *value = (int)data;
    return 0;
}

static double read_weight(void) {
    int raw;
    if (read_hx711(&raw) != 0) return -1.0;
    return (double)raw / calibration_factor;
}

static int dispense(double target_weight) {
    int pulse_width = (int)((target_weight / SERVO_PULSE_WIDTH_RESOLUTION) * SERVO_PULSE_WIDTH_RANGE) + SERVO_MIN_PULSE_WIDTH;
    if (pulse_width < SERVO_MIN_PULSE_WIDTH) pulse_width = SERVO_MIN_PULSE_WIDTH;
    if (pulse_width > SERVO_MAX_PULSE_WIDTH) pulse_width = SERVO_MAX_PULSE_WIDTH;
    gpioServo(SERVO_PIN, pulse_width);
    gpioDelay(1000000);
    return 0;
}

static double calibrate(double known_weight, double actual_weight) {
    if (actual_weight == 0.0) return 1.0;
    return known_weight / actual_weight;
}

static int log_dispensing_event(double target_weight, double actual_weight, const char *error_message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "{\"date\": \"%04d-%02d-%02d\", \"time\": \"%02d:%02d:%02d\", \"target_weight\": %.2f, \"actual_weight\": %.2f, \"error\": \"%s\"}\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, target_weight, actual_weight, error_message);
    fclose(fp);
    return 0;
}

static int load_config(void) {
    FILE *fp = fopen(CONFIG_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Warning: Could not open config file '%s': %s. Using default calibration factor: %.2f\n", CONFIG_FILE, strerror(errno), calibration_factor);
        return -1;
    }
    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        char *key = strtok(line, "=\n");
        char *value = strtok(NULL, "=\n");
        if (key && value && strcmp(key, CALIBRATION_FACTOR_KEY) == 0) {
            double f = atof(value);
            if (f > 0.0) calibration_factor = f;
            else fprintf(stderr, "Warning: Invalid calibration factor in config file. Using default: %.2f\n", calibration_factor);
            break;
        }
    }
    fclose(fp);
    return 0;
}

static int setup_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_SCK_PIN, PI_OUTPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioWrite(HX711_SCK_PIN, 0);
    return 0;
}

static void cleanup_gpio(void) {
    gpioWrite(SERVO_PIN, 0);
    gpioWrite(HX711_SCK_PIN, 0);
    gpioTerminate();
}

static int setup_server(int *server_fd) {
    struct sockaddr_in address;
    int opt = 1;
    *server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (*server_fd < 0) {
        perror("socket failed");
        return -1;
    }
    if (setsockopt(*server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        perror("setsockopt failed");
        close(*server_fd);
        return -1;
    }
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = inet_addr(SERVER_IP);
    address.sin_port = htons(SERVER_PORT);
    if (bind(*server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        close(*server_fd);
        return -1;
    }
    if (listen(*server_fd, 3) < 0) {
        perror("listen failed");
        close(*server_fd);
        return -1;
    }
    return 0;
}

static void handle_client(int client_fd) {
    char buffer[1024] = {0};
    ssize_t bytes = read(client_fd, buffer, sizeof(buffer) - 1);
    if (bytes < 0) {
        perror("read failed");
        close(client_fd);
        return;
    }
    if (bytes == 0) {
        close(client_fd);
        return;
    }
    buffer[bytes] = '\0';
    double target_weight = atof(buffer);
    if (target_weight <= 0.0) {
        const char *msg = "Invalid target weight. Please provide a positive value.\n";
        send(client_fd, msg, strlen(msg), 0);
        log_dispensing_event(target_weight, 0.0, "Invalid target weight");
        close(client_fd);
        return;
    }
    printf("Received target weight: %.2f grams\n", target_weight);
    if (dispense(target_weight) != 0) {
        const char *msg = "Dispensing failed.\n";
        send(client_fd, msg, strlen(msg), 0);
        log_dispensing_event(target_weight, 0.0, "Dispensing failed");
        close(client_fd);
        return;
    }
    double actual_weight = read_weight();
    if (actual_weight < 0.0) {
        const char *msg = "Failed to read weight from HX711.\n";
        send(client_fd, msg, strlen(msg), 0);
        log_dispensing_event(target_weight, 0.0, "Failed to read weight");
        close(client_fd);
        return;
    }
    calibration_factor = calibrate(target_weight, actual_weight);
    char response[256];
    snprintf(response, sizeof(response), "Target weight: %.2f grams, Actual weight: %.2f grams\n", target_weight, actual_weight);
    send(client_fd, response, strlen(response), 0);
    log_dispensing_event(target_weight, actual_weight, "");
    close(client_fd);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    if (load_config() != 0) {
        fprintf(stderr, "Failed to load config. Using default calibration factor: %.2f\n", calibration_factor);
    }
    if (setup_gpio() != 0) {
        fprintf(stderr, "GPIO setup failed. Exiting.\n");
        return 1;
    }
    int server_fd = -1;
    if (setup_server(&server_fd) != 0) {
        fprintf(stderr, "Server setup failed. Exiting.\n");
        cleanup_gpio();
        return 1;
    }
    printf("Server listening on %s:%d\n", SERVER_IP, SERVER_PORT);
    while (running) {
        struct sockaddr_in client_addr;
        socklen_t addrlen = sizeof(client_addr);
        int client_fd = accept(server_fd, (struct sockaddr *)&client_addr, &addrlen);
        if (client_fd < 0) {
            if (running && errno != EINTR) perror("accept failed");
            continue;
        }
        printf("Connection accepted from %s:%d\n", inet_ntoa(client_addr.sin_addr), ntohs(client_addr.sin_port));
        handle_client(client_fd);
    }
    printf("\nShutting down...\n");
    cleanup_gpio();
    if (server_fd >= 0) close(server_fd);
    return 0;
}

