#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17
#define DEFAULT_DEBOUNCE_DELAY_MS 50

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t relay_state = 0;
static int debounce_delay_ms = DEFAULT_DEBOUNCE_DELAY_MS;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_relay_state(int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime() failed\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("%s Relay: %s\n", timestamp, state ? "ON" : "OFF");
    fflush(stdout);
}

static int set_relay(int state) {
    if (gpioWrite(RELAY_PIN, state) != 0) {
        fprintf(stderr, "Error: gpioWrite(RELAY_PIN, %d) failed\n", state);
        return -1;
    }
    relay_state = state;
    log_relay_state(state);
    return 0;
}

static int read_touch_sensor(void) {
    int value = gpioRead(TOUCH_SENSOR_PIN);
    if (value < 0) {
        fprintf(stderr, "Error: gpioRead(TOUCH_SENSOR_PIN) failed\n");
        return -1;
    }
    return value;
}

static void cleanup(void) {
    if (gpioInitialise() >= 0) {
        gpioWrite(RELAY_PIN, 0);
        gpioTerminate();
    }
}

int main(int argc, char *argv[]) {
    int opt;

    while ((opt = getopt(argc, argv, "d:")) != -1) {
        switch (opt) {
            case 'd':
                debounce_delay_ms = atoi(optarg);
                if (debounce_delay_ms <= 0) {
                    fprintf(stderr, "Error: debounce delay must be positive\n");
                    return EXIT_FAILURE;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-d debounce_ms]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(RELAY_PIN, PI_OUTPUT) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Error: gpioWrite(RELAY_PIN, 0) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction(SIGINT) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction(SIGTERM) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    int last_touch_state = 0;
    int first_read = 1;

    while (running) {
        int touch_value = read_touch_sensor();
        if (touch_value < 0) {
            gpioDelay(100000);
            continue;
        }

        if (first_read) {
            last_touch_state = touch_value;
            first_read = 0;
        }

        if (touch_value == 1 && last_touch_state == 0) {
            gpioDelay(debounce_delay_ms * 1000);
            int stable_touch = read_touch_sensor();
            if (stable_touch < 0) {
                continue;
            }
            if (stable_touch == 1) {
                if (relay_state == 0) {
                    if (set_relay(1) == 0) {
                        printf("Touch detected! Relay ON\n");
                        fflush(stdout);
                    }
                } else {
                    if (set_relay(0) == 0) {
                        printf("Touch detected! Relay OFF\n");
                        fflush(stdout);
                    }
                }
            }
        }

        last_touch_state = touch_value;
        gpioDelay(10000);
    }

    printf("\nShutting down...\n");
    set_relay(0);
    cleanup();
    return EXIT_SUCCESS;
}

