#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <string.h>
#include <errno.h>
#include <pigpio.h>

#define SERVO_PIN      18
#define SERVO_FREQ_HZ  50
#define SERVO_MIN_PW   500
#define SERVO_MAX_PW   2500
#define SERVO_START_PW 1500
#define STEP_DEG       10
#define MIN_ANGLE      0
#define MAX_ANGLE      180

static volatile sig_atomic_t g_stop = 0;

static void sigint_handler(int sig)
{
    (void)sig;
    g_stop = 1;
}

static int set_tty_raw(int fd)
{
    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("tcgetattr");
        return -1;
    }
    cfmakeraw(&tty);
    tty.c_cc[VMIN]  = 1;
    tty.c_cc[VTIME] = 0;
    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("tcsetattr");
        return -1;
    }
    return 0;
}

static int restore_tty(int fd, const struct termios *oldt)
{
    if (tcsetattr(fd, TCSANOW, oldt) != 0) {
        perror("tcsetattr (restore)");
        return -1;
    }
    return 0;
}

static int angle_to_pulsewidth(int angle)
{
    if (angle < MIN_ANGLE) angle = MIN_ANGLE;
    if (angle > MAX_ANGLE) angle = MAX_ANGLE;
    return SERVO_MIN_PW +
           (int)((long)(angle - MIN_ANGLE) *
                 (SERVO_MAX_PW - SERVO_MIN_PW) /
                 (MAX_ANGLE - MIN_ANGLE));
}

int main(void)
{
    int fd = -1;
    struct termios old_tty;
    int rc = EXIT_FAILURE;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", SERVO_PIN);
        goto cleanup;
    }

    if (gpioSetPWMfrequency(SERVO_PIN, SERVO_FREQ_HZ) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO%d\n", SERVO_PIN);
        goto cleanup;
    }

    if (gpioServo(SERVO_PIN, SERVO_START_PW) != 0) {
        fprintf(stderr, "Failed to start servo PWM on GPIO%d\n", SERVO_PIN);
        goto cleanup;
    }

    if (set_tty_raw(STDIN_FILENO) != 0) {
        goto cleanup;
    }

    if (tcgetattr(STDIN_FILENO, &old_tty) != 0) {
        perror("tcgetattr");
        goto cleanup;
    }

    if (signal(SIGINT, sigint_handler) == SIG_ERR) {
        perror("signal");
        goto cleanup;
    }

    int angle = 90;
    int pw   = angle_to_pulsewidth(angle);
    if (gpioServo(SERVO_PIN, pw) != 0) {
        fprintf(stderr, "Failed to set initial pulse width\n");
        goto cleanup;
    }
    printf("Servo angle: %d degrees (pulse width: %d us)\n", angle, pw);
    fflush(stdout);

    while (!g_stop) {
        char ch;
        ssize_t n = read(STDIN_FILENO, &ch, 1);
        if (n < 0) {
            if (errno == EINTR) continue;
            perror("read");
            break;
        }
        if (n == 0) continue;

        if (ch == '+') {
            angle += STEP_DEG;
        } else if (ch == '-') {
            angle -= STEP_DEG;
        } else if (ch == 'q') {
            break;
        } else {
            continue;
        }

        pw = angle_to_pulsewidth(angle);
        if (gpioServo(SERVO_PIN, pw) != 0) {
            fprintf(stderr, "Failed to set pulse width to %d us\n", pw);
            break;
        }
        printf("Servo angle: %d degrees (pulse width: %d us)\n", angle, pw);
        fflush(stdout);
    }

    if (gpioServo(SERVO_PIN, 0) != 0) {
        fprintf(stderr, "Failed to stop servo PWM\n");
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) close(fd);
    restore_tty(STDIN_FILENO, &old_tty);
    gpioTerminate();
    return rc;
}

