/*
 * motor_rpm_monitor.c — Raspberry Pi 3 Model B+
 *
 * Monitors a two-pole A3144 Hall-effect sensor on GPIO 17 (BCM) with
 * internal pull-up bias, counting rising-edge pulses to compute RPM
 * every 5 seconds and logging the result to motor_rpm.log.
 *
 * Build:  gcc -O2 -Wall -Wextra -o motor_rpm_monitor motor_rpm_monitor.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME   "gpiochip0"
#define GPIO_LINE_OFFSET 17          /* BCM 17, physical pin 11 */
#define DEBOUNCE_US      2000        /* 2 ms debounce window      */
#define SAMPLE_PERIOD_S  5           /* seconds between samples   */
#define LOG_FILE         "motor_rpm.log"

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
