/* ------------------------------------------------------------------ */
static int log_rpm(FILE *fp, double rpm)
{
    char ts[32];
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        perror("time()");
        return -1;
    }

    struct tm tmv;
    if (localtime_r(&now, &tmv) == NULL) {
        perror("localtime_r()");
        return -1;
    }

    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tmv) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%.2f\n", ts, rpm) < 0) {
        perror("fprintf()");
        return -1;
    }

