        pulse_count = 0;
        last_event = now_ts;
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (fp != NULL)
        fclose(fp);
    if (line != NULL)
        gpiod_line_release(line);
    if (chip != NULL)
        gpiod_chip_close(chip);

    if (ret == EXIT_SUCCESS)
        printf("\nExiting cleanly.\n");

    return ret;
}

