#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17
#define POLL_DELAY_US 50000
#define FORCE_OFF_TIMEOUT_S 10

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int safe_set_mode(unsigned pin, unsigned mode) {
    if (gpioSetMode(pin, mode) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%u, %u) failed\n", pin, mode);
        return -1;
    }
    return 0;
}

static int safe_write(unsigned pin, unsigned level) {
    if (gpioWrite(pin, level) != 0) {
        fprintf(stderr, "Error: gpioWrite(%u, %u) failed\n", pin, level);
        return -1;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (safe_set_mode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (safe_set_mode(RELAY_PIN, PI_OUTPUT) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (safe_write(RELAY_PIN, 0) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction failed\n");
        safe_write(RELAY_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int relay_state = 0;
    int last_touch = 0;
    int touch_count = 0;
    int force_off_active = 0;
    time_t force_off_start = 0;

    while (g_running) {
        int touch = gpioRead(TOUCH_SENSOR_PIN);
        if (touch < 0) {
            fprintf(stderr, "Error: gpioRead(%d) failed\n", TOUCH_SENSOR_PIN);
            break;
        }

        if (touch == 1) {
            touch_count++;
            if (!force_off_active) {
                if (last_touch == 0) {
                    relay_state = !relay_state;
                    if (safe_write(RELAY_PIN, relay_state) != 0) {
                        break;
                    }
                    printf("Relay toggled to %s\n", relay_state ? "ON" : "OFF");
                }
            } else if (touch_count >= (FORCE_OFF_TIMEOUT_S * 1000 / (POLL_DELAY_US / 1000))) {
                if (safe_write(RELAY_PIN, 0) != 0) {
                    break;
                }
                relay_state = 0;
                force_off_active = 0;
                printf("Relay forced OFF (timeout)\n");
            }
        } else {
            touch_count = 0;
            if (force_off_active) {
                force_off_active = 0;
            }
        }

        last_touch = touch;
        usleep(POLL_DELAY_US);
    }

    safe_write(RELAY_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

