#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define VALVE_PWM_PIN      18   /* BCM 18 — hardware PWM 0 */
#define VALVE_DIR_PIN      23   /* BCM 23 — enable / direction */
#define FLOW_SENSOR_PIN    24   /* BCM 24 — YF-S201 rising-edge flow sensor */

#define PWM_FREQUENCY_HZ   1000
#define PWM_RANGE          255
#define SAMPLE_PERIOD_US   100000  /* 100 ms */
#define LOG_FILE_NAME      "flow_log.csv"

static volatile sig_atomic_t g_running = 1;
static volatile int g_flow_count = 0;
static FILE *g_log_file = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void flow_sensor_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)level;
    (void)tick;
    (void)userdata;
    g_flow_count++;
}

static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    if (gpioSetMode(VALVE_PWM_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output (PWM).\n", VALVE_PWM_PIN);
        return -1;
    }

    if (gpioSetMode(VALVE_DIR_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output (direction).\n", VALVE_DIR_PIN);
        return -1;
    }

    if (gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input (flow sensor).\n", FLOW_SENSOR_PIN);
        return -1;
    }

    if (gpioSetPullUpDown(FLOW_SENSOR_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Warning: failed to set pull-down on GPIO %d.\n", FLOW_SENSOR_PIN);
    }

    if (gpioWrite(VALVE_DIR_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to drive GPIO %d high (direction).\n", VALVE_DIR_PIN);
        return -1;
    }

    if (gpioSetPWMfrequency(VALVE_PWM_PIN, PWM_FREQUENCY_HZ) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d.\n", VALVE_PWM_PIN);
        return -1;
    }

    if (gpioSetPWMrange(VALVE_PWM_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO %d.\n", VALVE_PWM_PIN);
        return -1;
    }

    if (gpioPWM(VALVE_PWM_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialize PWM duty cycle on GPIO %d.\n", VALVE_PWM_PIN);
        return -1;
    }

    if (gpioSetISRFuncEx(FLOW_SENSOR_PIN, RISING_EDGE, 0, flow_sensor_isr, NULL) < 0) {
        fprintf(stderr, "Error: failed to register ISR on GPIO %d.\n", FLOW_SENSOR_PIN);
        return -1;
    }

    return 0;
}

static void set_valve_position(int duty_cycle)
{
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;

    if (gpioPWM(VALVE_PWM_PIN, duty_cycle) < 0) {
        fprintf(stderr, "Warning: gpioPWM failed for duty cycle %d.\n", duty_cycle);
    }
}

static void log_data(double flow_rate, int valve_position)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        fprintf(stderr, "Warning: clock_gettime failed; logging without timestamp.\n");
        fprintf(g_log_file, "0,%.2f,%d\n", flow_rate, valve_position);
    } else {
        long long timestamp_ms = (long long)ts.tv_sec * 1000LL + ts.tv_nsec / 1000000LL;
        fprintf(g_log_file, "%lld,%.2f,%d\n", timestamp_ms, flow_rate, valve_position);
    }
    fflush(g_log_file);
}

static void cleanup(void)
{
    set_valve_position(0);
    gpioWrite(VALVE_DIR_PIN, 0);
    gpioSetISRFuncEx(FLOW_SENSOR_PIN, RISING_EDGE, 0, NULL, NULL);
    gpioTerminate();

    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
}

int main(int argc, char *argv[])
{
    double target_flow_rate = 0.0;
    int opt;

    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                target_flow_rate = atof(optarg);
                if (target_flow_rate <= 0.0) {
                    fprintf(stderr, "Error: target flow rate must be a positive number (L/min).\n");
                    return EXIT_FAILURE;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s -t <target_flow_rate_L_min>\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    if (target_flow_rate == 0.0) {
        fprintf(stderr, "Error: target flow rate not specified. Use -t <L/min>.\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (g_log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return EXIT_FAILURE;
    }

    fprintf(g_log_file, "# flow_log.csv — closed-loop proportional valve control\n");
    fprintf(g_log_file, "# timestamp_ms, flow_rate_L_min, valve_position_0-255\n");
    fflush(g_log_file);

    printf("Flow control started. Target flow rate: %.2f L/min\n", target_flow_rate);
    printf("Press Ctrl+C to stop.\n");

    while (g_running) {
        g_flow_count = 0;
        gpioDelay(SAMPLE_PERIOD_US);

        int pulses = g_flow_count;
