/*
 * Two-factor door access control — Raspberry Pi 3 Model B+
 *
 * Hardware:
 *   - Two YLI YM-180 electromagnetic lock actuators (active-high driver)
 *     -> GPIO 17 (BCM) = Lock 1
 *     -> GPIO 27 (BCM) = Lock 2
 *   - RFID reader on SPI channel 0, 100 kHz, 10-byte response
 *     (documented valid response value)
 *   - Button on GPIO 22 (BCM), active-low, internal pull-up
 *
 * Behavior:
 *   1. Poll RFID reader in a non-blocking loop.
 *   2. On valid 10-byte tag, require button press within 5 s.
 *   3. If button pressed, disengage both locks for 5 s, then re-engage.
 *   4. Log every event to /var/log/door_access.log with ISO-8601 timestamps.
 *   5. On SIGINT/SIGTERM, force locks to engaged state, close SPI, log, exit.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define LOCK_1_GPIO        17
#define LOCK_2_GPIO        27
#define BUTTON_GPIO        22
#define SPI_DEVICE         "/dev/spidev0.0"
#define SPI_SPEED_HZ       100000
#define SPI_BITS_PER_WORD  8
#define RFID_TAG_LEN       10
#define RFID_VALID_TAG     {0x01,0x02,0x03,0x04,0x05,0x06,0x07,0x08,0x09,0x0A}
#define LOG_FILE           "/var/log/door_access.log"
#define DEBOUNCE_MS        50
#define BUTTON_TIMEOUT_S   5
#define POLL_DELAY_US      100000

static volatile sig_atomic_t g_running = 1;
static int  g_spi_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Logging                                                            */
/* ------------------------------------------------------------------ */
static void log_event(const char *msg)
{
    if (!g_log_fp) return;

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(g_log_fp, "[timestamp-error] %s\n", msg);
    } else {
        fprintf(g_log_fp, "%04d-%02d-%02dT%02d:%02d:%02d %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    }
    fflush(g_log_fp);
}

/* ------------------------------------------------------------------ */
/* SPI                                                                */
/* ------------------------------------------------------------------ */
static int spi_init(void)
{
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        perror("open(" SPI_DEVICE ")");
        return -1;
    }

    unsigned int speed = SPI_SPEED_HZ;
    unsigned char bits = SPI_BITS_PER_WORD;
    unsigned char mode = SPI_MODE_0;

    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("ioctl(SPI_IOC_WR_MODE)");
        goto fail;
    }
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("ioctl(SPI_IOC_WR_BITS_PER_WORD)");
        goto fail;
    }
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("ioctl(SPI_IOC_WR_MAX_SPEED_HZ)");
        goto fail;
    }
    return 0;

fail:
    close(g_spi_fd);
    g_spi_fd = -1;
    return -1;
}

/*
 * Read RFID tag from the SPI device.
 * Returns 0 on success, -1 on SPI error, -2 if no tag (all-zero response).
 */
static int read_rfid_tag(unsigned char *tag, size_t len)
{
    if (len < RFID_TAG_LEN) {
        fprintf(stderr, "read_rfid_tag: buffer too small\n");
        return -1;
    }

    unsigned char tx[RFID_TAG_LEN] = {0};
    unsigned char rx[RFID_TAG_LEN] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf        = (unsigned long)tx,
        .rx_buf        = (unsigned long)rx,
        .len           = RFID_TAG_LEN,
        .speed_hz      = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS_PER_WORD,
        .delay_usecs   = 0,
        .cs_change     = 0,
    };

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("ioctl(SPI_IOC_MESSAGE)");
        return -1;
    }

    /* All-zero response indicates no tag present (per documented protocol). */
    int all_zero = 1;
    for (size_t i = 0; i < RFID_TAG_LEN; i++) {
        if (rx[i] != 0) { all_zero = 0; break; }
    }
    if (all_zero) return -2;

    memcpy(tag, rx, RFID_TAG_LEN);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Lock control                                                       */
/* ------------------------------------------------------------------ */
static void locks_engage(void)
{
    gpioWrite(LOCK_1_GPIO, 1);
    gpioWrite(LOCK_2_GPIO, 1);
}

static void locks_disengage(void)
{
    gpioWrite(LOCK_1_GPIO, 0);
    gpioWrite(LOCK_2_GPIO, 0);
}

/* ------------------------------------------------------------------ */
/* Button                                                             */
/* ------------------------------------------------------------------ */
static int button_pressed(void)
{
    static uint32_t last_tick = 0;
    static int      last_state = 1; /* pulled high => not pressed */

    int cur = gpioRead(BUTTON_GPIO);
    if (cur == 1) return 0; /* still released */

    uint32_t now = gpioTick();
    if (now - last_tick > DEBOUNCE_MS * 1000) {
        last_tick = now;
        last_state = cur;
        return 1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Access logic                                                       */
/* ------------------------------------------------------------------ */
static void access_granted(void)
{
    log_event("Access granted: tag verified, button pressed, locks toggled.");
    printf("Access granted.\n");
}

static void access_denied(void)
{
    log_event("Access denied: invalid tag or button not pressed.");
    printf("Access denied.\n");
}

static void access_failed(void)
{
    log_event("Access failed: RFID read error.");
    printf("Access failed.\n");
}

/* ------------------------------------------------------------------ */
/* Signal handling                                                    */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    /* Force locks to engaged state before releasing resources. */
    locks_engage();

    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }

    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }

    /* pigpio's gpioTerminate() is safe to call even if init failed. */
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- GPIO setup ---- */
    if (gpioSetMode(LOCK_1_GPIO, PI_OUTPUT) < 0 ||
        gpioSetMode(LOCK_2_GPIO, PI_OUTPUT) < 0 ||
        gpioSetMode(BUTTON_GPIO, PI_INPUT)  < 0) {
        fprintf(stderr, "gpioSetMode failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetPullUpDown(BUTTON_GPIO, PI_PUD_UP);
    locks_engage(); /* start with locks engaged */

    /* ---- SPI init ---- */
    if (spi_init() < 0) {
        fprintf(stderr, "SPI initialisation failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Log file ---- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("fopen(" LOG_FILE ")");
        close(g_spi_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Signals ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_event("Door access control system started.");

    /* ---- Main loop ---- */
    while (g_running) {
        unsigned char tag[RFID_TAG_LEN];
        int rc = read_rfid_tag(tag, sizeof(tag));

        if (rc == 0) {
            /* Valid tag received. */
            log_event("Valid RFID tag detected.");

            /* Wait for button press within timeout. */
            time_t start = time(NULL);
            int got_button = 0;
            while (g_running && !got_button) {
                if (button_pressed()) {
                    got_button = 1;
                } else if (time(NULL) - start >= BUTTON_TIMEOUT_S) {
                    log_event("Button timeout: no press within 5 s.");
                    got_button = 1; /* fail-safe: treat as denied */
                }
                gpioDelay(100000); /* 100 ms */
            }

            if (got_button) {
                locks_disengage();
                gpioDelay(BUTTON_TIMEOUT_S * 1000000); /* 5 s */
                locks_engage();
                access_granted();
            } else {
                access_denied();
            }
        } else if (rc == -2) {
            /* No tag present — normal, non-error state. */
            gpioDelay(POLL_DELAY_US);
        } else {
            /* SPI error. */
            access_failed();
            gpioDelay(POLL_DELAY_US);
        }
    }

    /* ---- Graceful shutdown ---- */
    log_event("Door access control system shutting down.");
    cleanup();
    return EXIT_SUCCESS;
}

