 *
 * Wiring (BCM numbering):
 *   Motor 1: ENA=GPIO23, IN1=GPIO24, IN2=GPIO25
 *   Motor 2: ENB=GPIO12, IN3=GPIO16, IN4=GPIO20
 *   Encoder 1: A=GPIO5, B=GPIO6
 *   Encoder 2: A=GPIO26, B=GPIO19
 *
 * Build: gcc -O2 -Wall -Wextra -o motor_pid motor_pid.c -lpigpio -lpthread
 * Run:   sudo ./motor_pid
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

/* ---- Pin assignments (BCM numbering) ---- */
#define MOTOR1_ENA 23
#define MOTOR1_IN1 24
#define MOTOR1_IN2 25
#define MOTOR2_ENB 12
#define MOTOR2_IN3 16
#define MOTOR2_IN4 20
#define ENC1_A     5
#define ENC1_B     6
#define ENC2_A    26
#define ENC2_B    19

/* ---- PID parameters ---- */
#define KP 1.0
#define KI 0.01
#define KD 0.1
#define TARGET_SPEED 60.0   /* RPM */
#define SAMPLE_TIME_MS 100
#define PWM_FREQ_HZ 100      /* 100 Hz software PWM */
#define PWM_RANGE 1000       /* 1000 steps per period */

/* ---- Globals ---- */
static volatile sig_atomic_t g_running = 1;
static FILE *g_log = NULL;

/* Encoder counts (protected by mutexes) */
static volatile int32_t g_enc1_count = 0;
static volatile int32_t g_enc2_count = 0;
static pthread_mutex_t g_enc_mutex = PTHREAD_MUTEX_INITIALIZER;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Software PWM thread for one motor ---- */
static void *pwm_thread(void *arg)
{
    int ena = *(int *)arg;
    int in1 = *(int *)(arg + sizeof(int));
    int in2 = *(int *)(arg + 2 * sizeof(int));
    free(arg);

    while (g_running) {
        /* Software PWM: 100 Hz, 1000 steps */
        for (int i = 0; i < PWM_RANGE && g_running; i++) {
            gpioPWM(ena, i);
            gpioDelay(1000 / PWM_FREQ_HZ / PWM_RANGE); /* ~1 ms per step */
        }
        /* Coast: disable PWM and set direction */
        gpioPWM(ena, 0);
        gpioWrite(in1, 0);
        gpioWrite(in2, 0);
    }
    return NULL;
}

/* ---- Quadrature decode for one encoder ---- */
static void encoder_callback(int gpio, int level, uint32_t tick, void *user)
{
    (void)tick;
    (void)user;

    if (level != PI_HIGH && level != PI_LOW)
        return;

    int enc_a = gpio;
    int enc_b = (enc_a == ENC1_A) ? ENC1_B : ENC2_B;
    int *count = (enc_a == ENC1_A) ? &g_enc1_count : &g_enc2_count;

    pthread_mutex_lock(&g_enc_mutex);

    int b_level = gpioRead(enc_b);
    if (b_level < 0) {
        pthread_mutex_unlock(&g_enc_mutex);
        return;
    }

    if (enc_a == ENC1_A) {
        if (level == PI_HIGH && b_level == PI_LOW)
            (*count)++;
        else if (level == PI_LOW && b_level == PI_HIGH)
            (*count)--;
    } else {
        if (level == PI_HIGH && b_level == PI_LOW)
            (*count)--;
        else if (level == PI_LOW && b_level == PI_HIGH)
            (*count)++;
    }

    pthread_mutex_unlock(&g_enc_mutex);
}

/* ---- Read encoder count (thread-safe) ---- */
static int32_t read_encoder(int idx)
{
    int32_t val;
    pthread_mutex_lock(&g_enc_mutex);
    if (idx == 1)
        val = g_enc1_count;
    else
        val = g_enc2_count;
    pthread_mutex_unlock(&g_enc_mutex);
    return val;
}

/* ---- PID ---- */
static double pid(double setpoint, double actual, double *integral,
                  double *prev_error, double dt)
{
    double error = setpoint - actual;
    *integral += error * dt;
    double deriv = (error - *prev_error) / dt;
    double out = KP * error + KI * (*integral) + KD * deriv;
    *prev_error = error;
    return out;
}

/* ---- Log data ---- */
static void log_data(double s1, double s2, double p, double i, double d, double pid_out)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    if (fprintf(g_log, "%s,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f\n",
                ts, s1, s2, p, i, d, pid_out) < 0) {
        perror("fprintf");
    }
    fflush(g_log);
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    /* Stop motors */
    gpioWrite(MOTOR1_IN1, 0);
    gpioWrite(MOTOR1_IN2, 0);
    gpioWrite(MOTOR2_IN3, 0);
    gpioWrite(MOTOR2_IN4, 0);
    gpioPWM(MOTOR1_ENA, 0);
    gpioPWM(MOTOR2_ENB, 0);

    /* Release lines */
    gpioSetMode(MOTOR1_ENA, PI_INPUT);
    gpioSetMode(MOTOR1_IN1, PI_INPUT);
    gpioSetMode(MOTOR1_IN2, PI_INPUT);
    gpioSetMode(MOTOR2_ENB, PI_INPUT);
    gpioSetMode(MOTOR2_IN3, PI_INPUT);
    gpioSetMode(MOTOR2_IN4, PI_INPUT);
    gpioSetMode(ENC1_A, PI_INPUT);
    gpioSetMode(ENC1_B, PI_INPUT);
    gpioSetMode(ENC2_A, PI_INPUT);
    gpioSetMode(ENC2_B, PI_INPUT);

    if (g_log) {
        fclose(g_log);
        g_log = NULL;
    }
    gpioTerminate();
}

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure motor control pins */
    int motor_pins[] = {MOTOR1_ENA, MOTOR1_IN1, MOTOR1_IN2,
                        MOTOR2_ENB, MOTOR2_IN3, MOTOR2_IN4};
    for (size_t i = 0; i < sizeof(motor_pins) / sizeof(motor_pins[0]); i++) {
        if (gpioSetMode(motor_pins[i], PI_OUTPUT) < 0) {
            fprintf(stderr, "Failed to set mode for GPIO %d\n", motor_pins[i]);
            cleanup();
            return EXIT_FAILURE;
        }
        gpioWrite(motor_pins[i], 0);
    }

    /* Configure encoder pins */
    int enc_pins[] = {ENC1_A, ENC1_B, ENC2_A, ENC2_B};
    for (size_t i = 0; i < sizeof(enc_pins) / sizeof(enc_pins[0]); i++) {
        if (gpioSetMode(enc_pins[i], PI_INPUT) < 0) {
            fprintf(stderr, "Failed to set mode for GPIO %d\n", enc_pins[i]);
            cleanup();
            return EXIT_FAILURE;
        }
        if (gpioSetPullUpDown(enc_pins[i], PI_PUD_UP) < 0) {
            fprintf(stderr, "Failed to set pull-up for GPIO %d\n", enc_pins[i]);
            cleanup();
            return EXIT_FAILURE;
        }
    }

    /* Register quadrature callbacks (BOTH_EDGES) */
    if (gpioSetAlertFuncEx(ENC1_A, encoder_callback, NULL) < 0 ||
        gpioSetAlertFuncEx(ENC1_B, encoder_callback, NULL) < 0 ||
        gpioSetAlertFuncEx(ENC2_A, encoder_callback, NULL) < 0 ||
        gpioSetAlertFuncEx(ENC2_B, encoder_callback, NULL) < 0) {
        fprintf(stderr, "Failed to set alert functions\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Start PWM threads (direction set to forward initially) */
    pthread_t pwm1, pwm2;
    int *pwm1_args = malloc(3 * sizeof(int));
    int *pwm2_args = malloc(3 * sizeof(int));
    if (!pwm1_args || !pwm2_args) {
        perror("malloc");
        free(pwm1_args); free(pwm2_args);
        cleanup();
        return EXIT_FAILURE;
    }
    pwm1_args[0] = MOTOR1_ENA; pwm1_args[1] = MOTOR1_IN1; pwm1_args[2] = MOTOR1_IN2;
    pwm2_args[0] = MOTOR2_ENB; pwm2_args[1] = MOTOR2_IN3; pwm2_args[2] = MOTOR2_IN4;
    if (pthread_create(&pwm1, NULL, pwm_thread, pwm1_args) != 0 ||
        pthread_create(&pwm2, NULL, pwm_thread, pwm2_args) != 0) {
        perror("pthread_create");
        free(pwm1_args); free(pwm2_args);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log = fopen("motor_log.csv", "a");
    if (!g_log) {
        perror("fopen");
        pthread_join(pwm1, NULL); pthread_join(pwm2, NULL);
        free(pwm1_args); free(pwm2_args);
        cleanup();
        return EXIT_FAILURE;
    }
    fprintf(g_log, "timestamp,speed1_rpm,speed2_rpm,p,i,d,pid_out\n");
    fflush(g_log);

    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* PID state */
    double integral1 = 0.0, prev_err1 = 0.0;
    double integral2 = 0.0, prev_err2 = 0.0;
    double dt = SAMPLE_TIME_MS / 1000.0;

    /* Main control loop */
    while (g_running) {
        int32_t c1 = read_encoder(1);
        int32_t c2 = read_encoder(2);

        /* RPM from encoder counts over sample period (100 ms) */
        double s1 = (double)c1 / dt / 60.0;
        double s2 = (double)c2 / dt / 60.0;

        double p1 = pid(TARGET_SPEED, s1, &integral1, &prev_err1, dt);
        double p2 = pid(TARGET_SPEED, s2, &integral2, &prev_err2, dt);

        /* Direction: 1 = forward, -1 = reverse */
        int dir1 = (p1 > 0) ? 1 : -1;
        int dir2 = (p2 > 0) ? 1 : -1;

        /* Set motor directions */
        gpioWrite(MOTOR1_IN1, dir1);
        gpioWrite(MOTOR1_IN2, dir1 == 1 ? 0 : 1);
        gpioWrite(MOTOR2_IN3, dir2);
        gpioWrite(MOTOR2_IN4, dir2 == 1 ? 0 : 1);

        /* Duty cycle proportional to PID output */
        int duty1 = (int)(PWM_RANGE * (fabs(p1) / 100.0));
        int duty2 = (int)(PWM_RANGE * (fabs(p2) / 100.0));

        /* Software PWM: 1000 steps per period */
        for (int i = 0; i < PWM_RANGE && g_running; i++) {
            gpioPWM(MOTOR1_ENA, duty1);
            gpioPWM(MOTOR2_ENB, duty2);
            gpioDelay(1000 / PWM_FREQ_HZ / PWM_RANGE);
        }

        /* Coast: disable PWM and set direction */
        gpioPWM(MOTOR1_ENA, 0);
        gpioPWM(MOTOR2_ENB, 0);
        gpioWrite(MOTOR1_IN1, 0);
        gpioWrite(MOTOR1_IN2, 0);
        gpioWrite(MOTOR2_IN3, 0);
        gpioWrite(MOTOR2_IN4, 0);

        /* Log */
        log_data(s1, s2, p1, integral1, p2, integral2);
    }

    /* Cleanup */
    pthread_join(pwm1, NULL);
    pthread_join(pwm2, NULL);
    free(pwm1_args);
    free(pwm2_args);
    cleanup();
    return EXIT_SUCCESS;
}

