    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* PID state */
    double integral1 = 0.0, prev_err1 = 0.0;
    double integral2 = 0.0, prev_err2 = 0.0;
    double dt = SAMPLE_TIME_MS / 1000.0;

    /* Main control loop */
    while (g_running) {
        int32_t c1 = read_encoder(1);
        int32_t c2 = read_encoder(2);

        /* RPM from encoder counts over sample period (100 ms) */
        double s1 = (double)c1 / dt / 60.0;
        double s2 = (double)c2 / dt / 60.0;

        double p1 = pid(TARGET_SPEED, s1, &integral1, &prev_err1, dt);
        double p2 = pid(TARGET_SPEED, s2, &integral2, &prev_err2, dt);

        /* Direction: 1 = forward, -1 = reverse */
        int dir1 = (p1 > 0) ? 1 : -1;
        int dir2 = (p2 > 0) ? 1 : -1;

        /* Set motor directions */
        gpioWrite(MOTOR1_IN1, dir1);
        gpioWrite(MOTOR1_IN2, dir1 == 1 ? 0 : 1);
        gpioWrite(MOTOR2_IN3, dir2);
        gpioWrite(MOTOR2_IN4, dir2 == 1 ? 0 : 1);

        /* Duty cycle proportional to PID output */
        int duty1 = (int)(PWM_RANGE * (fabs(p1) / 100.0));
        int duty2 = (int)(PWM_RANGE * (fabs(p2) / 100.0));

        /* Software PWM: 1000 steps per period */
        for (int i = 0; i < PWM_RANGE && g_running; i++) {
            gpioPWM(MOTOR1_ENA, duty1);
            gpioPWM(MOTOR2_ENB, duty2);
            gpioDelay(1000 / PWM_FREQ_HZ / PWM_RANGE);
        }

        /* Coast: disable PWM and set direction */
        gpioPWM(MOTOR1_ENA, 0);
        gpioPWM(MOTOR2_ENB, 0);
        gpioWrite(MOTOR1_IN1, 0);
        gpioWrite(MOTOR1_IN2, 0);
        gpioWrite(MOTOR2_IN3, 0);
        gpioWrite(MOTOR2_IN4, 0);

        /* Log */
        log_data(s1, s2, p1, integral1, p2, integral2);
    }

    /* Cleanup */
    pthread_join(pwm1, NULL);
    pthread_join(pwm2, NULL);
    free(pwm1_args);
    free(pwm2_args);
    cleanup();
    return EXIT_SUCCESS;
}

