#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define VALVE1_GPIO 17
#define VALVE2_GPIO 18
#define VALVE1_DURATION_MS 500
#define VALVE2_DURATION_MS 1000
#define VALVE1_PAUSE_MS 5000
#define VALVE2_PAUSE_MS 10000
#define LOG_FILE "valve_log.txt"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    if (log_file == NULL) return;
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }
    if (fprintf(log_file, "%s: %s\n", timestamp, message) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
    }
    if (fflush(log_file) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
    }
}

static void cleanup(void) {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    if (gpioInitialise() >= 0) {
        gpioWrite(VALVE1_GPIO, 0);
        gpioWrite(VALVE2_GPIO, 0);
        gpioTerminate();
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(VALVE1_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", VALVE1_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(VALVE2_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", VALVE2_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioWrite(VALVE1_GPIO, 0) != 0) {
        fprintf(stderr, "Failed to initialise GPIO %d LOW\n", VALVE1_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioWrite(VALVE2_GPIO, 0) != 0) {
        fprintf(stderr, "Failed to initialise GPIO %d LOW\n", VALVE2_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Water distribution system started. Press Ctrl+C to exit.\n");
    log_event("System started");

    while (running) {
        if (gpioWrite(VALVE1_GPIO, 1) != 0) {
            fprintf(stderr, "Failed to activate Valve 1 (GPIO %d)\n", VALVE1_GPIO);
            log_event("ERROR: Valve 1 activation failed");
            break;
        }
        log_event("Valve 1 activated");
        printf("Valve 1 activated for %d ms\n", VALVE1_DURATION_MS);

        gpioDelay(VALVE1_DURATION_MS * 1000);

        if (gpioWrite(VALVE1_GPIO, 0) != 0) {
            fprintf(stderr, "Failed to deactivate Valve 1 (GPIO %d)\n", VALVE1_GPIO);
            log_event("ERROR: Valve 1 deactivation failed");
            break;
        }
        log_event("Valve 1 deactivated");
        printf("Valve 1 deactivated\n");

        if (!running) break;

        if (VALVE1_PAUSE_MS > 0) {
            gpioDelay(VALVE1_PAUSE_MS * 1000);
        }

        if (!running) break;

        if (gpioWrite(VALVE2_GPIO, 1) != 0) {
            fprintf(stderr, "Failed to activate Valve 2 (GPIO %d)\n", VALVE2_GPIO);
            log_event("ERROR: Valve 2 activation failed");
            break;
        }
        log_event("Valve 2 activated");
        printf("Valve 2 activated for %d ms\n", VALVE2_DURATION_MS);

        gpioDelay(VALVE2_DURATION_MS * 1000);

        if (gpioWrite(VALVE2_GPIO, 0) != 0) {
            fprintf(stderr, "Failed to deactivate Valve 2 (GPIO %d)\n", VALVE2_GPIO);
            log_event("ERROR: Valve 2 deactivation failed");
            break;
        }
        log_event("Valve 2 deactivated");
        printf("Valve 2 deactivated\n");

        if (!running) break;

        if (VALVE2_PAUSE_MS > 0) {
            gpioDelay(VALVE2_PAUSE_MS * 1000);
        }
    }

    log_event("System stopped");
    printf("Water distribution system stopped.\n");
    cleanup();
    return EXIT_SUCCESS;
}

