#include <stdbool.h>

#define MPR121_ADDR 0x5A
#define RELAY_GPIO 17
#define I2C_BUS 1

#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_ELECTRODE_CONFIG 0x5E
#define MPR121_MHD_RISING 0x2B
#define MPR121_NHD_RISING 0x2C
#define MPR121_NCL_RISING 0x2D
#define MPR121_FDL_RISING 0x2E
#define MPR121_MHD_FALLING 0x2F
#define MPR121_NHD_FALLING 0x30
#define MPR121_NCL_FALLING 0x31
#define MPR121_FDL_FALLING 0x32
#define MPR121_NHD_PROX 0x33
#define MPR121_NCL_PROX 0x34
#define MPR121_FDL_PROX 0x35
#define MPR121_E0TTH 0x41
#define MPR121_E0RTH 0x42
#define MPR121_DEBOUNCE 0x5B
#define MPR121_CONFIG1 0x5C
#define MPR121_CONFIG2 0x5D
#define MPR121_ECR 0x5E

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int mpr121_write(uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing 0x%02X to register 0x%02X: %d\n", value, reg, rc);
    }
    return rc;
}

static int mpr121_init(void) {
    if (mpr121_write(MPR121_ECR, 0x00) < 0) return -1;
    gpioDelay(1000);

    if (mpr121_write(MPR121_MHD_RISING, 0x01) < 0) return -1;
    if (mpr121_write(MPR121_NHD_RISING, 0x01) < 0) return -1;
    if (mpr121_write(MPR121_NCL_RISING, 0x00) < 0) return -1;
    if (mpr121_write(MPR121_FDL_RISING, 0x00) < 0) return -1;
    if (mpr121_write(MPR121_MHD_FALLING, 0x01) < 0) return -1;
    if (mpr121_write(MPR121_NHD_FALLING, 0x01) < 0) return -1;
    if (mpr121_write(MPR121_NCL_FALLING, 0x00) < 0) return -1;
    if (mpr121_write(MPR121_FDL_FALLING, 0x00) < 0) return -1;
    if (mpr121_write(MPR121_NHD_PROX, 0x00) < 0) return -1;
    if (mpr121_write(MPR121_NCL_PROX, 0x00) < 0) return -1;
    if (mpr121_write(MPR121_FDL_PROX, 0x00) < 0) return -1;

    for (int i = 0; i < 12; i++) {
        if (mpr121_write(MPR121_E0TTH + 2 * i, 0x0F) < 0) return -1;
        if (mpr121_write(MPR121_E0RTH + 2 * i, 0x0A) < 0) return -1;
    }

    if (mpr121_write(MPR121_DEBOUNCE, 0x00) < 0) return -1;
    if (mpr121_write(MPR121_CONFIG1, 0x10) < 0) return -1;
    if (mpr121_write(MPR121_CONFIG2, 0x20) < 0) return -1;

    if (mpr121_write(MPR121_ECR, 0x8F) < 0) return -1;
    gpioDelay(100000);
    return 0;
}

static int read_touch_status(uint16_t *touch_status) {
    char buf[2];
    int rc = i2cReadI2CBlockData(i2c_handle, MPR121_TOUCHSTATUS_L, buf, 2);
    if (rc < 0) {
        fprintf(stderr, "Error reading touch status: %d\n", rc);
        return -1;
    }
    *touch_status = (uint16_t)((buf[1] << 8) | buf[0]);
    return 0;
}

static void toggle_relay(void) {
    static bool relay_state = false;
    relay_state = !relay_state;
    if (gpioWrite(RELAY_GPIO, relay_state) < 0) {
        fprintf(stderr, "Error writing to relay GPIO\n");
    } else {
        printf("Relay toggled to %s\n", relay_state ? "ON" : "OFF");
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (mpr121_init() < 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting relay GPIO mode\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_GPIO, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Monitoring MPR121 touch sensor. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t touch_status = 0;
        if (read_touch_status(&touch_status) == 0) {
            if (touch_status > 0) {
                toggle_relay();
            }
        }
        gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    gpioWrite(RELAY_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

