#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PIR_PIN 17
#define RELAY_PIN 18
#define UNLOCK_DURATION_MS 500
#define RATE_LIMIT_MS 2000
#define POLL_INTERVAL_US 50000
#define LOG_FILE "door_events.log"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *event_type, const char *details) {
    if (!log_file) return;
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(log_file, "%s.%03ld - %s: %s\n", timestamp, ts.tv_nsec / 1000000, event_type, details);
    fflush(log_file);
}

static void unlock_door(void) {
    if (gpioWrite(RELAY_PIN, 1) != 0) {
        fprintf(stderr, "Error: failed to activate relay on GPIO %d\n", RELAY_PIN);
        log_event("ERROR", "Failed to activate relay");
        return;
    }
    log_event("DOOR_UNLOCKED", "Door strike unlocked");
    gpioDelay(UNLOCK_DURATION_MS * 1000);
    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to deactivate relay on GPIO %d\n", RELAY_PIN);
        log_event("ERROR", "Failed to deactivate relay");
        return;
    }
    log_event("DOOR_LOCKED", "Door strike re-locked");
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PIR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input\n", PIR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(PIR_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error: failed to set pull-down on GPIO %d\n", PIR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize relay GPIO %d to OFF\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        gpioWrite(RELAY_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        fclose(log_file);
        gpioWrite(RELAY_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        fclose(log_file);
        gpioWrite(RELAY_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_event("SYSTEM_START", "Door monitoring system started");
    printf("Door monitoring system started. Press Ctrl+C to exit.\n");

    int last_pir_state = 0;
    int rate_limit_active = 0;
    struct timespec rate_limit_end;

    while (running) {
        int pir_state = gpioRead(PIR_PIN);
        if (pir_state < 0) {
            fprintf(stderr, "Error: failed to read PIR sensor on GPIO %d\n", PIR_PIN);
            log_event("ERROR", "Failed to read PIR sensor");
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        if (pir_state == 1 && last_pir_state == 0) {
            if (!rate_limit_active) {
                log_event("MOTION_DETECTED", "Motion detected");
                unlock_door();
                rate_limit_active = 1;
                clock_gettime(CLOCK_REALTIME, &rate_limit_end);
                rate_limit_end.tv_sec += RATE_LIMIT_MS / 1000;
                rate_limit_end.tv_nsec += (RATE_LIMIT_MS % 1000) * 1000000;
                if (rate_limit_end.tv_nsec >= 1000000000) {
                    rate_limit_end.tv_sec++;
                    rate_limit_end.tv_nsec -= 1000000000;
                }
            }
        }

        last_pir_state = pir_state;

        if (rate_limit_active) {
            struct timespec now;
            clock_gettime(CLOCK_REALTIME, &now);
            if (now.tv_sec > rate_limit_end.tv_sec ||
                (now.tv_sec == rate_limit_end.tv_sec && now.tv_nsec >= rate_limit_end.tv_nsec)) {
                rate_limit_active = 0;
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    log_event("SYSTEM_STOP", "Door monitoring system stopped");
    gpioWrite(RELAY_PIN, 0);
    fclose(log_file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

