#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define MOTOR1_GPIO 17
#define MOTOR2_GPIO 27
#define MIN_STEPS 5
#define MAX_STEPS 15
#define MIN_DUTY 0
#define MAX_DUTY 255
#define MIN_DURATION_MS 50
#define MAX_DURATION_MS 200

typedef struct {
    int duty1;
    int duty2;
    int duration_ms;
} MotorStep;

typedef struct {
    MotorStep *steps;
    int num_steps;
} MotorPattern;

volatile sig_atomic_t shutdown_flag = 0;

void signal_handler(int sig) {
    (void)sig;
    shutdown_flag = 1;
}

int generate_random_motor_step(MotorStep *step) {
    step->duty1 = (rand() % (MAX_DUTY - MIN_DUTY + 1)) + MIN_DUTY;
