#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27

#define CALIBRATION_FILE "calibration.txt"
#define LOG_FILE "weight_log.txt"

#define WEIGHT_THRESHOLD 10.0
#define CALIBRATION_SAMPLES 100
#define READ_TIMEOUT_US 500000
#define LOOP_DELAY_US 500000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_hx711(int data_pin, int clock_pin) {
    int data = 0;
    int timeout = 0;

    gpioSetMode(data_pin, PI_INPUT);
    gpioSetMode(clock_pin, PI_OUTPUT);

    while (gpioRead(data_pin) == 1) {
        gpioDelay(10);
        timeout += 10;
        if (timeout >= READ_TIMEOUT_US) {
            fprintf(stderr, "HX711 timeout waiting for data pin low\n");
            return -1;
        }
    }

    for (int i = 0; i < 24; i++) {
        gpioWrite(clock_pin, 1);
        gpioDelay(1);
        data = (data << 1) | gpioRead(data_pin);
        gpioWrite(clock_pin, 0);
        gpioDelay(1);
    }

    gpioWrite(clock_pin, 1);
    gpioDelay(1);
    gpioWrite(clock_pin, 0);
    gpioDelay(1);

    if (data & 0x800000) {
        data |= ~0xFFFFFF;
    }

    return data;
}

static double calculate_weight(int raw_value, double scale_factor, double offset) {
    return (double)raw_value / scale_factor - offset;
}

static int log_weight(double weight) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, %.2f\n", timestamp, weight);
    fclose(fp);
    return 0;
}

static int save_calibration(double scale_factor, double offset) {
    FILE *fp = fopen(CALIBRATION_FILE, "w");
    if (!fp) {
        perror("Error opening calibration file for writing");
        return -1;
    }
    fprintf(fp, "%.6f %.6f\n", scale_factor, offset);
    fclose(fp);
    return 0;
}

static int load_calibration(double *scale_factor, double *offset) {
    FILE *fp = fopen(CALIBRATION_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Calibration file not found. Using defaults.\n");
        *scale_factor = 1.0;
        *offset = 0.0;
        return -1;
    }

    if (fscanf(fp, "%lf %lf", scale_factor, offset) != 2) {
        fprintf(stderr, "Error reading calibration data. Using defaults.\n");
        *scale_factor = 1.0;
        *offset = 0.0;
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

static int calibrate_hx711(int data_pin, int clock_pin, double *scale_factor, double *offset) {
    long sum = 0;
    int valid_samples = 0;

    printf("Calibrating HX711 (place no weight on load cell)...\n");
    for (int i = 0; i < CALIBRATION_SAMPLES; i++) {
        int raw = read_hx711(data_pin, clock_pin);
        if (raw == -1) {
            fprintf(stderr, "Error reading HX711 during calibration.\n");
            return -1;
        }
        sum += raw;
        valid_samples++;
        gpioDelay(10000);
    }

    if (valid_samples == 0) {
        fprintf(stderr, "No valid samples during calibration.\n");
        return -1;
    }

    *offset = (double)sum / valid_samples;
    printf("Calibration complete. Offset: %.6f\n", *offset);
    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);
    gpioWrite(SOLENOID_PIN, 0);

    double scale_factor = 1.0;
    double offset = 0.0;

    if (load_calibration(&scale_factor, &offset) != 0) {
        scale_factor = 1.0;
        offset = 0.0;
    }

    if (calibrate_hx711(HX711_DATA_PIN, HX711_CLOCK_PIN, &scale_factor, &offset) == 0) {
        save_calibration(scale_factor, offset);
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    printf("Weight monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int raw_value = read_hx711(HX711_DATA_PIN, HX711_CLOCK_PIN);
        if (raw_value == -1) {
            fprintf(stderr, "Error reading HX711. Skipping iteration.\n");
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        double weight = calculate_weight(raw_value, scale_factor, offset);

        if (weight > WEIGHT_THRESHOLD) {
            gpioWrite(SOLENOID_PIN, 1);
            printf("Weight %.2f kg exceeds threshold. Solenoid engaged.\n", weight);
        } else {
            gpioWrite(SOLENOID_PIN, 0);
            printf("Weight %.2f kg below threshold. Solenoid disengaged.\n", weight);
        }

        if (log_weight(weight) != 0) {
            fprintf(stderr, "Error logging weight.\n");
        }

        gpioDelay(LOOP_DELAY_US);
    }

    gpioWrite(SOLENOID_PIN, 0);
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

