#define CHECK_INTERVAL_SEC 60
#define POST_ACTION_DELAY_SEC 60

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    if (gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT) != 0) {
        syslog(LOG_ERR, "Failed to set rain sensor pin %d as input", RAIN_SENSOR_PIN);
        return -1;
    }

    if (gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_PWM_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set motor control pins as output");
        return -1;
    }

    if (gpioSetPWMfrequency(MOTOR_PWM_PIN, PWM_FREQUENCY) < 0) {
        syslog(LOG_ERR, "Failed to set PWM frequency on pin %d", MOTOR_PWM_PIN);
        return -1;
    }

    if (gpioPWM(MOTOR_PWM_PIN, 0) != 0) {
        syslog(LOG_ERR, "Failed to initialise PWM duty cycle to 0 on pin %d", MOTOR_PWM_PIN);
        return -1;
    }

    return 0;
}

static void stop_motor(void) {
    gpioWrite(MOTOR_IN1_PIN, 0);
    gpioWrite(MOTOR_IN2_PIN, 0);
    gpioPWM(MOTOR_PWM_PIN, 0);
}

static int read_rain_sensor(void) {
    int low_count = 0;

    for (int i = 0; i < DEBOUNCE_READINGS; i++) {
        int val = gpioRead(RAIN_SENSOR_PIN);
        if (val < 0) {
            syslog(LOG_ERR, "Failed to read rain sensor pin %d", RAIN_SENSOR_PIN);
            return -1;
        }
        if (val == 0) {
            low_count++;
        }
        if (i < DEBOUNCE_READINGS - 1) {
            gpioDelay(DEBOUNCE_DELAY_US);
        }
    }

    return (low_count >= 3) ? 1 : 0;
}

static int control_motor(int duration_sec) {
    if (gpioWrite(MOTOR_IN1_PIN, 1) != 0 ||
        gpioWrite(MOTOR_IN2_PIN, 0) != 0) {
        syslog(LOG_ERR, "Failed to set motor direction pins");
        return -1;
    }

    if (gpioPWM(MOTOR_PWM_PIN, PWM_DUTY_CYCLE) != 0) {
        syslog(LOG_ERR, "Failed to set PWM duty cycle to %d on pin %d", PWM_DUTY_CYCLE, MOTOR_PWM_PIN);
        return -1;
    }

    syslog(LOG_INFO, "Closing window: motor running for %d seconds", duration_sec);

    for (int i = 0; i < duration_sec && program_running; i++) {
        sleep(1);
    }

    stop_motor();
    syslog(LOG_INFO, "Window closing sequence complete");
    return 0;
}

static void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    syslog(LOG_INFO, "%s: %s", timestamp, message);
}

int main(void) {
    openlog("window_control", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to register signal handlers");
        closelog();
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        stop_motor();
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Window control system started");

    while (program_running) {
        int rain_detected = read_rain_sensor();
        if (rain_detected < 0) {
            syslog(LOG_ERR, "Sensor read error, retrying in %d seconds", CHECK_INTERVAL_SEC);
            sleep(CHECK_INTERVAL_SEC);
            continue;
        }

        if (rain_detected) {
            syslog(LOG_INFO, "Rain detected");
            if (control_motor(MOTOR_RUN_TIME_SEC) != 0) {
                syslog(LOG_ERR, "Motor control failed");
            }
            sleep(POST_ACTION_DELAY_SEC);
        }

        if (program_running) {
            sleep(CHECK_INTERVAL_SEC);
        }
    }

    stop_motor();
    gpioTerminate();
    syslog(LOG_INFO, "Window control system stopped");
    closelog();
    return EXIT_SUCCESS;
}

