#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/time.h>
#include <sys/stat.h>
#include <sys/types.h>

#define HX711_DT_PIN 23
#define HX711_SCK_PIN 24
#define SOLENOID_PIN 17
#define WEIGHT_THRESHOLD 100
#define LOCK_DURATION 5
#define LOG_FILE "stock_events.txt"
#define HX711_TIMEOUT_US 1000000

static volatile sig_atomic_t running = 1;
static int log_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    if (log_fd < 0) return;
    struct timeval tv;
    struct tm tm_info;
    char timestamp[32];
    char log_entry[256];

    gettimeofday(&tv, NULL);
    localtime_r(&tv.tv_sec, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    snprintf(log_entry, sizeof(log_entry), "%s.%06ld: %s\n", timestamp, tv.tv_usec, message);

    if (write(log_fd, log_entry, strlen(log_entry)) < 0) {
        perror("write to log file failed");
    }
}

static int gpio_export(int pin) {
    char buf[32];
    int fd = open("/sys/class/gpio/export", O_WRONLY);
    if (fd < 0) {
        perror("open export failed");
        return -1;
    }
    snprintf(buf, sizeof(buf), "%d", pin);
    if (write(fd, buf, strlen(buf)) < 0) {
        if (errno != EBUSY) {
            perror("write to export failed");
            close(fd);
            return -1;
        }
    }
    close(fd);
    return 0;
}

static int gpio_unexport(int pin) {
    char buf[32];
    int fd = open("/sys/class/gpio/unexport", O_WRONLY);
    if (fd < 0) {
        perror("open unexport failed");
        return -1;
    }
    snprintf(buf, sizeof(buf), "%d", pin);
    if (write(fd, buf, strlen(buf)) < 0) {
        perror("write to unexport failed");
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int gpio_set_direction(int pin, const char *dir) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", pin);
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("open direction failed");
        return -1;
    }
    if (write(fd, dir, strlen(dir)) < 0) {
        perror("write to direction failed");
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int gpio_write(int pin, int value) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("open value failed");
        return -1;
    }
    char val = (value == 0) ? '0' : '1';
    if (write(fd, &val, 1) < 0) {
        perror("write to value failed");
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int read_hx711(void) {
    int data = 0;
    int timeout = 0;

    if (gpio_write(HX711_SCK_PIN, 0) < 0) return -1;

    while (1) {
        int val = gpio_read(HX711_DT_PIN);
        if (val < 0) return -1;
        if (val == 0) break;
        usleep(10);
        timeout++;
        if (timeout > HX711_TIMEOUT_US) {
            log_event("HX711 timeout: data line stuck high");
            return -1;
        }
    }

    for (int i = 0; i < 24; i++) {
        if (gpio_write(HX711_SCK_PIN, 1) < 0) return -1;
        usleep(1);
        data = (data << 1) | gpio_read(HX711_DT_PIN);
        if (gpio_write(HX711_SCK_PIN, 0) < 0) return -1;
        usleep(1);
    }

    if (gpio_write(HX711_SCK_PIN, 1) < 0) return -1;
    usleep(1);
    if (gpio_write(HX711_SCK_PIN, 0) < 0) return -1;
    usleep(1);

    if (data & 0x800000) {
        data |= ~0xFFFFFF;
    }

    return data;
}

static int activate_solenoid(int duration) {
    if (gpio_write(SOLENOID_PIN, 1) < 0) {
        log_event("Failed to activate solenoid");
        return -1;
    }
    sleep(duration);
    if (gpio_write(SOLENOID_PIN, 0) < 0) {
        log_event("Failed to deactivate solenoid");
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction failed");
        return 1;
    }

    if (gpio_export(HX711_DT_PIN) < 0 || gpio_export(HX711_SCK_PIN) < 0 || gpio_export(SOLENOID_PIN) < 0) {
        log_event("Failed to export GPIO pins");
        return 1;
    }

    if (gpio_set_direction(HX711_DT_PIN, "in") < 0 || gpio_set_direction(HX711_SCK_PIN, "out") < 0 || gpio_set_direction(SOLENOID_PIN, "out") < 0) {
        log_event("Failed to set GPIO directions");
        gpio_unexport(HX711_DT_PIN);
        gpio_unexport(HX711_SCK_PIN);
        gpio_unexport(SOLENOID_PIN);
        return 1;
    }

    if (gpio_write(HX711_SCK_PIN, 0) < 0) {
        log_event("Failed to initialize SCK low");
        gpio_unexport(HX711_DT_PIN);
        gpio_unexport(HX711_SCK_PIN);
        gpio_unexport(SOLENOID_PIN);
        return 1;
    }

    log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        perror("open log file failed");
        gpio_unexport(HX711_DT_PIN);
        gpio_unexport(HX711_SCK_PIN);
        gpio_unexport(SOLENOID_PIN);
        return 1;
    }

    log_event("Program started");

    while (running) {
        int weight = read_hx711();
        if (weight < 0) {
            log_event("Error reading weight from HX711");
        } else {
            char msg[64];
            snprintf(msg, sizeof(msg), "Weight: %d g", weight);
            log_event(msg);
            if (weight < WEIGHT_THRESHOLD) {
                log_event("Weight below threshold, activating solenoid");
                if (activate_solenoid(LOCK_DURATION) < 0) {
                    log_event("Error activating solenoid");
                }
            }
        }
        sleep(1);
    }

    log_event("Program exiting");
    gpio_write(SOLENOID_PIN, 0);
    gpio_unexport(HX711_DT_PIN);
    gpio_unexport(HX711_SCK_PIN);
    gpio_unexport(SOLENOID_PIN);
    if (log_fd >= 0) close(log_fd);
    return 0;
}

