#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27
#define WEIGHT_THRESHOLD 5.0
#define CALIBRATION_FILE "calibration.txt"
#define LOG_FILE "security.log"
#define HX711_TIMEOUT_US 100000
#define CLOCK_DELAY_US 1
#define SAMPLE_DELAY_US 100000

static volatile sig_atomic_t running = 1;
static double calibration_factor = 1.0;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_hx711(int32_t *out) {
    if (gpioWrite(HX711_CLOCK_PIN, 0) < 0) return -1;
    gpioDelay(CLOCK_DELAY_US);

    uint32_t start = gpioTick();
    while (gpioRead(HX711_DATA_PIN) == 1) {
        if (gpioTick() - start > HX711_TIMEOUT_US) return -2;
        gpioDelay(10);
    }

    int32_t value = 0;
    for (int i = 0; i < 24; i++) {
        if (gpioWrite(HX711_CLOCK_PIN, 1) < 0) return -1;
        gpioDelay(CLOCK_DELAY_US);
        if (gpioWrite(HX711_CLOCK_PIN, 0) < 0) return -1;
        gpioDelay(CLOCK_DELAY_US);
        value <<= 1;
        if (gpioRead(HX711_DATA_PIN) == 1) value |= 1;
    }

    if (gpioWrite(HX711_CLOCK_PIN, 1) < 0) return -1;
    gpioDelay(CLOCK_DELAY_US);
    if (gpioWrite(HX711_CLOCK_PIN, 0) < 0) return -1;
    gpioDelay(CLOCK_DELAY_US);

    if (value & 0x800000) value |= 0xFF000000;
    *out = value;
    return 0;
}

static double calibrate_hx711(void) {
    double known_weight = 0.0;
    int32_t raw_value = 0;

    printf("Place a known weight on the load cell and enter its weight in kilograms: ");
    if (scanf("%lf", &known_weight) != 1 || known_weight <= 0.0) {
        fprintf(stderr, "Invalid input. Please enter a positive number.\n");
        return -1.0;
    }
    while (getchar() != '\n');

    printf("Reading HX711...\n");
    if (read_hx711(&raw_value) != 0) {
        fprintf(stderr, "HX711 read error during calibration.\n");
        return -1.0;
    }

    if (raw_value == 0) {
        fprintf(stderr, "Calibration failed: raw value is zero.\n");
        return -1.0;
    }

    return (double)raw_value / known_weight;
}

static void log_event(double weight) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            perror("Error opening log file");
            return;
        }
    }

    if (fprintf(log_file, "%s, %.2f kg\n", timestamp, weight) < 0) {
        perror("Error writing to log file");
    }
    fflush(log_file);
}

static void cleanup(void) {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(SOLENOID_PIN, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed.\n");
        return 1;
    }

    if (gpioSetMode(HX711_DATA_PIN, PI_INPUT) < 0 ||
        gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(SOLENOID_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes.\n");
        gpioTerminate();
        return 1;
    }

    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioWrite(SOLENOID_PIN, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Failed to set SIGINT handler");
        cleanup();
        return 1;
    }

    printf("Calibrating HX711...\n");
    calibration_factor = calibrate_hx711();
    if (calibration_factor <= 0.0) {
        fprintf(stderr, "Calibration failed. Exiting.\n");
        cleanup();
        return 1;
    }
    printf("Calibration factor: %.2f\n", calibration_factor);

    FILE *cal_file = fopen(CALIBRATION_FILE, "w");
    if (cal_file == NULL) {
        perror("Error opening calibration file");
        cleanup();
        return 1;
    }
    if (fprintf(cal_file, "%.6f\n", calibration_factor) < 0) {
        perror("Error writing calibration factor");
    }
    fclose(cal_file);

    printf("Security system started. Press Ctrl+C to exit.\n");

    while (running) {
        int32_t raw_value = 0;
        if (read_hx711(&raw_value) != 0) {
            fprintf(stderr, "HX711 read error. Retrying...\n");
            gpioDelay(SAMPLE_DELAY_US);
