#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define PIR_PIN 17
#define BUZZER_PIN 18
#define BUZZER_DURATION_US 2000000  /* 2 seconds in microseconds */
#define POLL_INTERVAL_US 100000     /* 100 ms */

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    /* Ensure buzzer is off before terminating pigpio */
    gpioWrite(BUZZER_PIN, 0);
    gpioTerminate();
}

static int log_motion(void) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        return -1;
    }

    if (fprintf(log_file, "%s\n", timestamp) < 0) {
        fprintf(stderr, "Error: failed to write to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error: fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    int ret = EXIT_FAILURE;

    /* Register signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to register SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure PIR pin as input */
    if (gpioSetMode(PIR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input\n", PIR_PIN);
        goto cleanup;
    }

    /* Configure buzzer pin as output and ensure it starts off */
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output\n", BUZZER_PIN);
        goto cleanup;
    }
    if (gpioWrite(BUZZER_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise buzzer state on GPIO%d\n", BUZZER_PIN);
        goto cleanup;
    }

    /* Open log file in append mode */
    log_file = fopen("motion_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: failed to open motion_log.txt: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("Motion detection system started. Press Ctrl+C to exit.\n");

    while (running) {
        int motion = gpioRead(PIR_PIN);
        if (motion < 0) {
            fprintf(stderr, "Error: failed to read PIR sensor on GPIO%d\n", PIR_PIN);
            goto cleanup;
        }

        if (motion == 1) {
            printf("Motion detected!\n");

            if (log_motion() != 0) {
                fprintf(stderr, "Warning: motion not logged\n");
