            /* Activate buzzer for 2 seconds */
            if (gpioWrite(BUZZER_PIN, 1) != 0) {
                fprintf(stderr, "Error: failed to activate buzzer on GPIO%d\n", BUZZER_PIN);
                goto cleanup;
            }

            /* Sleep in small increments so signals are caught promptly */
            uint32_t elapsed = 0;
            while (running && elapsed < BUZZER_DURATION_US) {
                uint32_t chunk = (BUZZER_DURATION_US - elapsed > 100000) ? 100000 : (BUZZER_DURATION_US - elapsed);
                usleep(chunk);
                elapsed += chunk;
            }

            if (gpioWrite(BUZZER_PIN, 0) != 0) {
                fprintf(stderr, "Error: failed to deactivate buzzer on GPIO%d\n", BUZZER_PIN);
                goto cleanup;
            }
        }

        usleep(POLL_INTERVAL_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    cleanup();
    return ret;
}

