#define MIN_DURATION 1
#define MAX_DURATION 3600

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int read_watering_duration(const char *filename, int *duration) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening config file '%s': %s\n", filename, strerror(errno));
        return -1;
    }

    char line[256];
    if (fgets(line, sizeof(line), fp) == NULL) {
        if (feof(fp)) {
            fprintf(stderr, "Error: config file '%s' is empty\n", filename);
        } else {
            fprintf(stderr, "Error reading config file '%s': %s\n", filename, strerror(errno));
        }
        fclose(fp);
        return -1;
    }
    fclose(fp);

    char *token = strtok(line, "=\n\r");
    if (token == NULL || strcmp(token, "duration") != 0) {
        fprintf(stderr, "Error: config file '%s' does not contain 'duration='\n", filename);
        return -1;
    }

    token = strtok(NULL, "=\n\r");
    if (token == NULL) {
        fprintf(stderr, "Error: config file '%s' missing value after '='\n", filename);
        return -1;
    }

    char *endptr;
    long val = strtol(token, &endptr, 10);
    if (*endptr != '\0' || endptr == token) {
        fprintf(stderr, "Error: config file '%s' contains invalid duration value '%s'\n", filename, token);
        return -1;
    }

    if (val < MIN_DURATION || val > MAX_DURATION) {
        fprintf(stderr, "Error: duration %ld out of range [%d, %d]\n", val, MIN_DURATION, MAX_DURATION);
        return -1;
    }

    *duration = (int)val;
    return 0;
}

static int control_valve(int gpio_pin, int duration) {
    if (gpioWrite(gpio_pin, 1) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d high (valve ON)\n", gpio_pin);
        return -1;
    }
    printf("Valve ON for %d seconds\n", duration);

    time_t start = time(NULL);
    while (g_running && (time(NULL) - start) < duration) {
        sleep(1);
    }

    if (gpioWrite(gpio_pin, 0) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d low (valve OFF)\n", gpio_pin);
        return -1;
    }
    printf("Valve OFF\n");
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

