    if (gpioWrite(GPIO_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise GPIO %d low\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to install SIGINT handler: %s\n", strerror(errno));
        gpioWrite(GPIO_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to install SIGTERM handler: %s\n", strerror(errno));
        gpioWrite(GPIO_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int duration = 0;
    if (read_watering_duration(CONFIG_FILE, &duration) != 0) {
        fprintf(stderr, "Error: failed to read watering duration from '%s'\n", CONFIG_FILE);
        gpioWrite(GPIO_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Watering duration: %d seconds\n", duration);

    if (control_valve(GPIO_PIN, duration) != 0) {
        fprintf(stderr, "Error: valve control failed\n");
        gpioWrite(GPIO_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioWrite(GPIO_PIN, 0);
    gpioTerminate();
    printf("Watering cycle complete.\n");
    return EXIT_SUCCESS;
}

