#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define LEFT_SENSOR_PIN   4
#define MIDDLE_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN  27

#define MOTOR_LEFT_PWM_PIN  22
#define MOTOR_RIGHT_PWM_PIN 23

#define PWM_FREQUENCY 1000
#define PWM_RANGE     255

#define LOG_FILE_NAME "trace_log.txt"

#define SAMPLE_DELAY_US 10000

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void log_data(int left, int middle, int right, int left_speed, int right_speed) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    fprintf(g_log_file, "%s,%d,%d,%d,%d,%d\n", timestamp, left, middle, right, left_speed, right_speed);
    fflush(g_log_file);
}

static void set_motor_speed(int left_speed, int right_speed) {
    if (left_speed < 0) left_speed = 0;
    if (left_speed > PWM_RANGE) left_speed = PWM_RANGE;
    if (right_speed < 0) right_speed = 0;
    if (right_speed > PWM_RANGE) right_speed = PWM_RANGE;

    if (gpioPWM(MOTOR_LEFT_PWM_PIN, left_speed) < 0) {
        fprintf(stderr, "Error setting PWM on left motor pin: %s\n", strerror(errno));
    }
    if (gpioPWM(MOTOR_RIGHT_PWM_PIN, right_speed) < 0) {
        fprintf(stderr, "Error setting PWM on right motor pin: %s\n", strerror(errno));
    }
}

static void stop_motors(void) {
    set_motor_speed(0, 0);
}

static void cleanup(void) {
    stop_motors();
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    int left_sensor, middle_sensor, right_sensor;
    int left_speed, right_speed;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error setting mode for left sensor pin: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(MIDDLE_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error setting mode for middle sensor pin: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error setting mode for right sensor pin: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(MOTOR_LEFT_PWM_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting mode for left motor PWM pin: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(MOTOR_RIGHT_PWM_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting mode for right motor PWM pin: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(MOTOR_LEFT_PWM_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error setting PWM frequency for left motor pin: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(MOTOR_RIGHT_PWM_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error setting PWM frequency for right motor pin: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(MOTOR_LEFT_PWM_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Error setting PWM range for left motor pin: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(MOTOR_RIGHT_PWM_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Error setting PWM range for right motor pin: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE_NAME, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error installing SIGINT handler: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Line following robot started. Press Ctrl+C to exit.\n");

    while (g_running) {
        left_sensor   = gpioRead(LEFT_SENSOR_PIN);
        middle_sensor = gpioRead(MIDDLE_SENSOR_PIN);
        right_sensor  = gpioRead(RIGHT_SENSOR_PIN);

        if (left_sensor < 0 || middle_sensor < 0 || right_sensor < 0) {
            fprintf(stderr, "Error reading sensor pins: %s\n", strerror(errno));
            break;
        }

        if (middle_sensor == 0) {
            left_speed  = 150;
            right_speed = 150;
        } else if (left_sensor == 0) {
            left_speed  = 150;
            right_speed = 75;
        } else if (right_sensor == 0) {
            left_speed  = 75;
            right_speed = 150;
        } else {
            left_speed  = 0;
            right_speed = 0;
        }

        set_motor_speed(left_speed, right_speed);
        log_data(left_sensor, middle_sensor, right_sensor, left_speed, right_speed);

        gpioDelay(SAMPLE_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

