#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define GROW_LAMP_GPIO 23
#define LUX_THRESHOLD 150
#define LOG_FILE "grow_log.txt"
#define MEASUREMENT_DELAY_MS 180

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    if (!log_file) return;
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(log_file, "%s.%03ld: %s\n", timestamp, ts.tv_nsec / 1000000, message);
    fflush(log_file);
}

static int read_bh1750(int handle, uint16_t *lux_out) {
    if (i2cWriteByte(handle, 0x10) < 0) {
        log_event("Error: Failed to trigger measurement.");
        return -1;
    }
    gpioDelay(MEASUREMENT_DELAY_MS * 1000);
    int raw = i2cReadWordData(handle, 0x00);
    if (raw < 0) {
        log_event("Error: Failed to read measurement data.");
        return -1;
    }
    *lux_out = (uint16_t)raw;
    return 0;
}

static void control_lamp(int gpio, int state) {
    if (gpioWrite(gpio, state) < 0) {
        log_event("Error: Failed to write to GPIO.");
    }
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    control_lamp(GROW_LAMP_GPIO, 0);
    if (log_file) {
        log_event("Program terminated.");
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
