#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LOCK_BUTTON_PIN  21
#define UNLOCK_BUTTON_PIN 22
#define SERVO_PIN        18

#define SERVO_MIN_PULSE_WIDTH 500
#define SERVO_MAX_PULSE_WIDTH 2500

#define LOCK_PULSE_WIDTH  1000
#define UNLOCK_PULSE_WIDTH 2000

#define DEBOUNCE_DELAY_US 100000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    if (gpioSetMode(LOCK_BUTTON_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set lock button pin mode.\n");
        return -1;
    }
    if (gpioSetMode(UNLOCK_BUTTON_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set unlock button pin mode.\n");
        return -1;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set servo pin mode.\n");
        return -1;
    }

    if (gpioSetPullUpDown(LOCK_BUTTON_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on lock button.\n");
        return -1;
    }
    if (gpioSetPullUpDown(UNLOCK_BUTTON_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on unlock button.\n");
        return -1;
    }

    return 0;
}

static int set_servo_pulse_width(int pulse_width) {
    if (pulse_width < SERVO_MIN_PULSE_WIDTH || pulse_width > SERVO_MAX_PULSE_WIDTH) {
        fprintf(stderr, "Error: pulse width %d us out of range [%d, %d].\n",
                pulse_width, SERVO_MIN_PULSE_WIDTH, SERVO_MAX_PULSE_WIDTH);
        return -1;
    }
    if (gpioServo(SERVO_PIN, pulse_width) != 0) {
        fprintf(stderr, "Error: gpioServo failed for pulse width %d.\n", pulse_width);
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Door lock control program started. Press Ctrl+C to exit.\n");

    while (running) {
        int lock_state  = gpioRead(LOCK_BUTTON_PIN);
        int unlock_state = gpioRead(UNLOCK_BUTTON_PIN);

        if (lock_state == 0) {
            gpioDelay(DEBOUNCE_DELAY_US);
            if (!running) break;
            if (gpioRead(LOCK_BUTTON_PIN) == 0) {
                if (set_servo_pulse_width(LOCK_PULSE_WIDTH) == 0) {
                    printf("Door locked.\n");
                }
            }
        }

        if (unlock_state == 0) {
            gpioDelay(DEBOUNCE_DELAY_US);
            if (!running) break;
            if (gpioRead(UNLOCK_BUTTON_PIN) == 0) {
                if (set_servo_pulse_width(UNLOCK_PULSE_WIDTH) == 0) {
                    printf("Door unlocked.\n");
                }
            }
        }

        gpioDelay(10000);
    }

    cleanup();
    printf("Program terminated cleanly.\n");
    return EXIT_SUCCESS;
}

