#include <pigpio.h>

#define MOTOR1_GPIO 17
#define MOTOR2_GPIO 27
#define MOTOR1_PULSE_MS 200
#define MOTOR2_PULSE_MS 300

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int safe_write(int gpio, int value) {
    if (gpioWrite(gpio, value) < 0) {
        fprintf(stderr, "Error: gpioWrite(%d, %d) failed\n", gpio, value);
        return -1;
    }
    return 0;
}

static void cleanup_lines(void) {
    gpioWrite(MOTOR1_GPIO, 0);
    gpioWrite(MOTOR2_GPIO, 0);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(MOTOR1_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_OUTPUT) failed\n", MOTOR1_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(MOTOR2_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_OUTPUT) failed\n", MOTOR2_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (safe_write(MOTOR1_GPIO, 0) < 0 || safe_write(MOTOR2_GPIO, 0) < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        cleanup_lines();
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        cleanup_lines();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (g_running) {
        if (safe_write(MOTOR1_GPIO, 1) < 0) {
            cleanup_lines();
            gpioTerminate();
            return EXIT_FAILURE;
        }
        gpioDelay(MOTOR1_PULSE_MS * 1000);
        if (!g_running) break;
        if (safe_write(MOTOR1_GPIO, 0) < 0) {
            cleanup_lines();
            gpioTerminate();
            return EXIT_FAILURE;
        }

        if (safe_write(MOTOR2_GPIO, 1) < 0) {
            cleanup_lines();
            gpioTerminate();
            return EXIT_FAILURE;
        }
        gpioDelay(MOTOR2_PULSE_MS * 1000);
        if (!g_running) break;
        if (safe_write(MOTOR2_GPIO, 0) < 0) {
            cleanup_lines();
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    cleanup_lines();
    gpioTerminate();
    return EXIT_SUCCESS;
}

