#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>
#include <zmq.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN 27
#define ZMQ_ENDPOINT "tcp://*:5555"
#define ZMQ_SUB_ENDPOINT "tcp://localhost:5555"
#define POLL_INTERVAL_US 10000
#define ALARM_DURATION_S 1

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int gpio_export(int pin) {
    int fd = open(GPIO_CHIP, O_WRONLY);
    if (fd < 0) {
        perror("open gpiochip");
        return -1;
    }
    char buf[64];
    int len = snprintf(buf, sizeof(buf), "export %d out", pin);
    if (write(fd, buf, len) < 0) {
        perror("export");
        close(fd);
        return -1;
    }
    close(fd);
    usleep(100000);
    return 0;
}

static int gpio_unexport(int pin) {
    int fd = open(GPIO_CHIP, O_WRONLY);
    if (fd < 0) {
        perror("open gpiochip");
        return -1;
    }
    char buf[64];
    int len = snprintf(buf, sizeof(buf), "unexport %d", pin);
    if (write(fd, buf, len) < 0) {
        perror("unexport");
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int gpio_set_value(int pin, int value) {
    int fd = open(GPIO_CHIP, O_WRONLY);
    if (fd < 0) {
        perror("open gpiochip");
        return -1;
    }
    char buf[64];
    int len = snprintf(buf, sizeof(buf), "value%d=%d", pin, value);
    if (write(fd, buf, len) < 0) {
        perror("set value");
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int gpio_get_value(int pin) {
    int fd = open(GPIO_CHIP, O_RDONLY);
    if (fd < 0) {
        perror("open gpiochip");
        return -1;
    }
    char buf[64];
    int len = snprintf(buf, sizeof(buf), "value%d", pin);
    if (write(fd, buf, len) < 0) {
        perror("write value");
        close(fd);
        return -1;
    }
    lseek(fd, 0, SEEK_SET);
    char val;
    if (read(fd, &val, 1) < 0) {
        perror("read value");
        close(fd);
        return -1;
    }
    close(fd);
    return (val == '1') ? 1 : 0;
}

static int zmq_init_server(void) {
    void *context = zmq_ctx_new();
    if (!context) {
        perror("zmq_ctx_new");
        return -1;
    }
    void *socket = zmq_socket(context, ZMQ_PUB);
    if (!socket) {
        perror("zmq_socket");
        zmq_ctx_destroy(context);
        return -1;
    }
    int rc = zmq_bind(socket, ZMQ_ENDPOINT);
    if (rc != 0) {
        perror("zmq_bind");
        zmq_close(socket);
        zmq_ctx_destroy(context);
        return -1;
    }
    return (int)(intptr_t)socket;
}

static int zmq_init_client(void) {
    void *context = zmq_ctx_new();
    if (!context) {
        perror("zmq_ctx_new");
        return -1;
    }
    void *socket = zmq_socket(context, ZMQ_SUB);
    if (!socket) {
        perror("zmq_socket");
        zmq_ctx_destroy(context);
        return -1;
    }
    int rc = zmq_connect(socket, ZMQ_SUB_ENDPOINT);
    if (rc != 0) {
        perror("zmq_connect");
        zmq_close(socket);
        zmq_ctx_destroy(context);
        return -1;
    }
    rc = zmq_setsockopt(socket, ZMQ_SUBSCRIBE, "SOUND_ALERTS", 12);
    if (rc != 0) {
        perror("zmq_setsockopt");
        zmq_close(socket);
        zmq_ctx_destroy(context);
        return -1;
    }
    return (int)(intptr_t)socket;
}

static void publish_alert(int socket_fd) {
    char message[64];
    snprintf(message, sizeof(message), "SOUND_ALERTS: %ld", (long)time(NULL));
    int rc = zmq_send((void *)(intptr_t)socket_fd, message, strlen(message), 0);
    if (rc < 0) {
        perror("zmq_send");
    }
}

static void handle_alert(int socket_fd) {
    char buffer[256];
    zmq_msg_t msg;
    int rc = zmq_msg_init(&msg);
    if (rc != 0) {
        perror("zmq_msg_init");
        return;
