/*
 * NEC IR Remote Decoder for Raspberry Pi 3 Model B+
 * Sensor: TSOP38238 on GPIO17 (BCM)
 * Protocol: NEC (8-bit address, 8-bit command, 8-bit inverted address, 8-bit inverted command)
 * Build: gcc -O2 -Wall -o ir_decoder ir_decoder.c -lpigpio -lmosquitto -lrt
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <pigpio.h>
#include <mosquitto.h>

#define IR_GPIO 17
#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "ir/decoded"
#define MAX_PULSES 68
#define NEC_HDR_MARK 9000
#define NEC_HDR_SPACE 4500
#define NEC_BIT_MARK 560
#define NEC_ONE_SPACE 1690
#define NEC_ZERO_SPACE 560
#define NEC_RPT_SPACE 2250
#define NEC_TOL 200

static volatile sig_atomic_t running = 1;
static volatile uint32_t pulses[MAX_PULSES];
static volatile int pulse_count = 0;
static struct mosquitto *mosq = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int in_range(uint32_t val, uint32_t target, uint32_t tol) {
    return (val >= target - tol) && (val <= target + tol);
}

static void ir_callback(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)userdata;
    if (level != 0) return; /* Only falling edges */
    if (pulse_count >= MAX_PULSES) {
        syslog(LOG_ERR, "Pulse buffer overflow, resetting");
        pulse_count = 0;
        return;
    }
    uint32_t last_tick = (pulse_count == 0) ? 0 : pulses[pulse_count - 1];
    uint32_t diff = tick - last_tick;
    pulses[pulse_count++] = diff;
}

static int decode_nec(uint32_t *p, int count, uint8_t *addr, uint8_t *cmd) {
    if (count < 68) return -1;
    if (!in_range(p[0], NEC_HDR_MARK, NEC_TOL)) return -1;
    if (!in_range(p[1], NEC_HDR_SPACE, NEC_TOL)) return -1;
    uint32_t raw = 0;
    for (int i = 0; i < 32; i++) {
        int idx = 2 + i * 2;
        if (idx + 1 >= count) return -1;
        if (!in_range(p[idx], NEC_BIT_MARK, NEC_TOL)) return -1;
        uint32_t space = p[idx + 1];
        if (in_range(space, NEC_ONE_SPACE, NEC_TOL)) {
            raw |= (1u << (31 - i));
        } else if (!in_range(space, NEC_ZERO_SPACE, NEC_TOL)) {
            return -1;
        }
    }
    uint8_t a = (raw >> 24) & 0xFF;
    uint8_t c = (raw >> 16) & 0xFF;
    uint8_t ia = (raw >> 8) & 0xFF;
    uint8_t ic = raw & 0xFF;
    if (a != (~ia & 0xFF)) return -1;
    if (c != (~ic & 0xFF)) return -1;
    *addr = a;
    *cmd = c;
    return 0;
}

static void publish_mqtt(uint8_t addr, uint8_t cmd) {
    char payload[128];
    int len = snprintf(payload, sizeof(payload),
        "{\"address\":%u,\"command\":%u}", addr, cmd);
    if (len < 0 || (size_t)len >= sizeof(payload)) return;
    int rc = mosquitto_publish(mosq, NULL, MQTT_TOPIC, len, payload, 0, false);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT publish failed: %s", mosquitto_strerror(rc));
    }
}

int main(void) {
    openlog("ir_decoder", LOG_PID | LOG_CONS, LOG_USER);
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to install signal handlers");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialization failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(IR_GPIO, PI_INPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO%d as input", IR_GPIO);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(IR_GPIO, PI_PUD_UP) != 0) {
        syslog(LOG_ERR, "Failed to set pull-up on GPIO%d", IR_GPIO);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFuncEx(IR_GPIO, ir_callback, NULL) != 0) {
        syslog(LOG_ERR, "Failed to set alert function on GPIO%d", IR_GPIO);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    mosquitto_lib_init();
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "Failed to create MQTT client");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    int rc = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT connect failed: %s", mosquitto_strerror(rc));
        mosquitto_destroy(mosq);
        mosq = NULL;
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "IR decoder started on GPIO%d", IR_GPIO);

    while (running) {
        gpioDelay(100000); /* 100 ms */
        if (pulse_count >= 68) {
            uint8_t addr = 0, cmd = 0;
            if (decode_nec(pulses, pulse_count, &addr, &cmd) == 0) {
                syslog(LOG_INFO, "Decoded: addr=0x%02X cmd=0x%02X", addr, cmd);
                publish_mqtt(addr, cmd);
            } else {
                syslog(LOG_WARNING, "Invalid NEC frame (%d pulses)", pulse_count);
            }
            pulse_count = 0;
        }
        mosquitto_loop(mosq, 100, 1);
    }

    syslog(LOG_INFO, "Shutting down");
    gpioSetAlertFuncEx(IR_GPIO, NULL, NULL);
    gpioTerminate();
    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
    }
    mosquitto_lib_cleanup();
    closelog();
    return EXIT_SUCCESS;
}

