#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <math.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define NUM_SENSORS    4
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5005
#define CONV_TIME_MS   180
#define LOOP_DELAY_MS  1000

static const unsigned char sensor_addrs[NUM_SENSORS] = {0x23, 0x5C, 0x4B, 0x32};

static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int i2c_write(int fd, const unsigned char *buf, size_t len) {
    ssize_t n = write(fd, buf, len);
    if (n < 0) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "I2C short write: %zd of %zu bytes\n", n, len);
        return -1;
    }
    return 0;
}

static int i2c_read(int fd, unsigned char *buf, size_t len) {
    size_t total = 0;
    while (total < len) {
        ssize_t n = read(fd, buf + total, len - total);
        if (n < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
            return -1;
        }
        if (n == 0) {
            fprintf(stderr, "I2C read: unexpected EOF\n");
            return -1;
        }
        total += (size_t)n;
    }
    return 0;
}

static float read_bh1750(int fd, unsigned char addr) {
    unsigned char cmd = 0x10; /* Continuous H-Resolution mode */
    unsigned char buf[2];

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X failed: %s\n", addr, strerror(errno));
        return NAN;
    }

    if (i2c_write(fd, &cmd, 1) < 0) return NAN;

    usleep(CONV_TIME_MS * 1000);

    if (i2c_read(fd, buf, 2) < 0) return NAN;

    unsigned int raw = ((unsigned int)buf[0] << 8) | buf[1];
    if (raw == 0) return NAN;
    return (float)raw / 1.2f;
}

static int send_multicast(int sock, const char *data) {
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);

    if (sendto(sock, data, strlen(data), 0,
               (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        fprintf(stderr, "sendto failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    int i2c_fd = -1;
    int sock = -1;
    int rc = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        goto cleanup;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "open %s failed: %s\n", I2C_BUS, strerror(errno));
        goto cleanup;
    }

    sock = socket(AF_INET, SOCK_DGRAM, 0);
    if (sock < 0) {
        fprintf(stderr, "socket failed: %s\n", strerror(errno));
        goto cleanup;
    }

    unsigned char ttl = 1;
    if (setsockopt(sock, IPPROTO_IP, IP_MULTICAST_TTL, &ttl, sizeof(ttl)) < 0) {
        fprintf(stderr, "setsockopt IP_MULTICAST_TTL failed: %s\n", strerror(errno));
        goto cleanup;
    }

    while (!terminate) {
        char data[256];
        int off = 0;
        for (int i = 0; i < NUM_SENSORS; i++) {
            float lux = read_bh1750(i2c_fd, sensor_addrs[i]);
            if (isnan(lux)) {
                fprintf(stderr, "Sensor %d (0x%02X) read error\n", i + 1, sensor_addrs[i]);
                off += snprintf(data + off, sizeof(data) - off, "%d,NaN;", i + 1);
            } else {
                off += snprintf(data + off, sizeof(data) - off, "%d,%.1f;", i + 1, lux);
            }
        }
        if (off > 0 && data[off - 1] == ';') data[--off] = '\0';

        if (send_multicast(sock, data) < 0) {
            fprintf(stderr, "Multicast send failed\n");
        } else {
            printf("Sent: %s\n", data);
        }

        for (int ms = 0; ms < LOOP_DELAY_MS && !terminate; ms += 100) {
            usleep(100 * 1000);
        }
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (i2c_fd >= 0) close(i2c_fd);
    if (sock >= 0) close(sock);
    return rc;
}

