#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SENSOR_ADDR    0x28
#define LOG_FILE       "airflow_log.txt"
#define MAX_RETRIES    3
#define RETRY_DELAY_MS 100
#define SAMPLE_PERIOD  1

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void msleep(unsigned ms)
{
    struct timespec ts = { ms / 1000, (long)(ms % 1000) * 1000000L };
    nanosleep(&ts, NULL);
}

static int i2c_open(const char *bus, uint8_t addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", bus, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n", addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        if (errno == EIO) {
            fprintf(stderr, "I2C read error (EIO): %s\n", strerror(errno));
        } else if (errno == ENXIO) {
            fprintf(stderr, "I2C no device at address 0x%02X (ENXIO)\n", SENSOR_ADDR);
        } else {
            fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        }
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "I2C short read: got %zd of %zu bytes\n", n, len);
        return -1;
    }
    return 0;
}

static int read_flow_rate(int fd, float *flow_out)
{
    uint8_t buf[2];
    int attempt;

    for (attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2c_read_bytes(fd, buf, sizeof(buf)) == 0) {
            uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
            uint16_t masked = raw & 0x3FFF;
            *flow_out = (float)masked / 100.0f;
            return 0;
        }
        if (attempt < MAX_RETRIES - 1)
            msleep(RETRY_DELAY_MS);
    }
    return -1;
}

static int log_flow_rate(FILE *fp, float flow_rate)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }
    if (fprintf(fp, "%s, %.2f SLPM\n", ts, flow_rate) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    struct sigaction sa;
    float flow_rate;

    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = i2c_open(I2C_BUS, SENSOR_ADDR);
    if (g_i2c_fd < 0)
        return EXIT_FAILURE;

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    printf("Airflow monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        if (read_flow_rate(g_i2c_fd, &flow_rate) == 0) {
            if (log_flow_rate(g_log_fp, flow_rate) != 0)
                fprintf(stderr, "Logging failed; continuing.\n");
        } else {
            fprintf(stderr, "Failed to read flow rate after %d retries.\n", MAX_RETRIES);
        }
        sleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down...\n");
    if (g_log_fp) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    printf("Resources released. Goodbye.\n");
    return EXIT_SUCCESS;
}

