#define DEFAULT_I2C_ADDRESS 0x08
#define DEFAULT_INTERVAL 1
#define DEFAULT_FILENAME "seismic_data.csv"
#define I2C_BUS "/dev/i2c-1"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

#define D7S_REG_X_LSB 0x00
#define D7S_REG_X_MSB 0x01
#define D7S_REG_Y_LSB 0x02
#define D7S_REG_Y_MSB 0x03
#define D7S_REG_Z_LSB 0x04
#define D7S_REG_Z_MSB 0x05
#define D7S_REG_STATUS 0x06

#define STATUS_ERROR 0x01

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *data_file = NULL;
static FILE *error_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    if (error_file) {
        fprintf(error_file, "%s: %s (errno: %d - %s)\n", timestamp, message, errno, strerror(errno));
        fflush(error_file);
    }
