#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <termios.h>
#include <sys/select.h>
#include <time.h>
#include <signal.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE   B115200
#define LINE_BUF_SZ 512
#define READ_BUF_SZ 256
#define POLL_TIMEOUT_SEC 2
#define POLL_TIMEOUT_USEC 0
#define IBT_SEC 0
#define IBT_USEC 500000

static volatile sig_atomic_t g_running = 1;
static int g_uart_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int setup_uart(const char *device, speed_t baud) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", device, strerror(errno));
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "tcgetattr failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    cfsetispeed(&tty, baud);
    cfsetospeed(&tty, baud);

    tty.c_cflag &= ~PARENB;
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CSIZE;
    tty.c_cflag |= CS8;
    tty.c_cflag |= CLOCAL | CREAD;

    tty.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG);
    tty.c_iflag &= ~(IXON | IXOFF | IXANY | IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL);
    tty.c_oflag &= ~OPOST;

    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 5;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "tcsetattr failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

static int parse_line(const char *line, time_t *timestamp, float *range) {
    char *endptr = NULL;
    errno = 0;
    long ts = strtol(line, &endptr, 10);
    if (errno != 0 || endptr == line || *endptr != ',') {
        return -1;
    }

    char *range_start = endptr + 1;
    errno = 0;
    float r = strtof(range_start, &endptr);
    if (errno != 0 || endptr == range_start || (*endptr != '\0' && *endptr != '\n' && *endptr != '\r')) {
        return -1;
    }

    *timestamp = (time_t)ts;
    *range = r;
    return 0;
}

static void log_data(time_t timestamp, float range) {
    struct tm tm_info;
    if (localtime_r(&timestamp, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }

    char time_str[32];
    if (strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    printf("Timestamp: %s, Range: %.2f meters\n", time_str, range);
    fflush(stdout);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return 1;
    }

    g_uart_fd = setup_uart(UART_DEVICE, BAUD_RATE);
    if (g_uart_fd < 0) {
        return 1;
    }

    char line_buf[LINE_BUF_SZ];
    size_t line_len = 0;
    char read_buf[READ_BUF_SZ];

    while (g_running) {
        fd_set readfds;
        FD_ZERO(&readfds);
        FD_SET(g_uart_fd, &readfds);

        struct timeval timeout;
        timeout.tv_sec = POLL_TIMEOUT_SEC;
        timeout.tv_usec = POLL_TIMEOUT_USEC;

        int retval = select(g_uart_fd + 1, &readfds, NULL, NULL, &timeout);

        if (retval < 0) {
            if (errno == EINTR) {
                continue;
            }
            fprintf(stderr, "select() error: %s\n", strerror(errno));
            break;
        }

        if (retval == 0) {
            fprintf(stderr, "Timeout: no data received from radar sensor (sensor absent or bus error)\n");
            continue;
        }

        ssize_t n = read(g_uart_fd, read_buf, sizeof(read_buf));
        if (n < 0) {
            if (errno == EINTR) {
                continue;
            }
            fprintf(stderr, "read() error: %s\n", strerror(errno));
            break;
        }

        if (n == 0) {
            continue;
        }

        for (ssize_t i = 0; i < n; i++) {
            char c = read_buf[i];

            if (c == '\n') {
                line_buf[line_len] = '\0';

                time_t timestamp = 0;
                float range = 0.0f;
                if (parse_line(line_buf, &timestamp, &range) == 0) {
                    log_data(timestamp, range);
                } else {
                    fprintf(stderr, "Invalid data format: %s\n", line_buf);
                }

                line_len = 0;
            } else if (c != '\r') {
                if (line_len < LINE_BUF_SZ - 1) {
                    line_buf[line_len++] = c;
                } else {
                    fprintf(stderr, "Line buffer overflow, discarding line\n");
                    line_len = 0;
                }
            }
        }
    }

    if (g_uart_fd >= 0) {
        close(g_uart_fd);
        g_uart_fd = -1;
    }

    printf("Program terminated gracefully.\n");
    return 0;
}

