#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LEFT_SENSOR_PIN   4
#define MIDDLE_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN  27
#define UART_DEVICE       "/dev/ttyAMA0"
#define BAUD_RATE         115200
#define LOOP_DELAY_US     100000  /* 100 ms -> 10 Hz */

static volatile sig_atomic_t g_running = 1;
static int g_uart_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    if (g_uart_handle >= 0) {
        serClose(g_uart_handle);
        g_uart_handle = -1;
    }
    gpioTerminate();
}

static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    if (gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set left sensor pin mode.\n");
        return -1;
    }
    if (gpioSetMode(MIDDLE_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set middle sensor pin mode.\n");
        return -1;
    }
    if (gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set right sensor pin mode.\n");
        return -1;
    }

    if (gpioSetPullUpDown(LEFT_SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on left sensor pin.\n");
        return -1;
    }
    if (gpioSetPullUpDown(MIDDLE_SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on middle sensor pin.\n");
        return -1;
    }
    if (gpioSetPullUpDown(RIGHT_SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on right sensor pin.\n");
        return -1;
    }

    return 0;
}

static int initialize_uart(void)
{
    g_uart_handle = serOpen(UART_DEVICE, BAUD_RATE, 0);
    if (g_uart_handle < 0) {
        fprintf(stderr, "Error: failed to open UART %s (handle=%d).\n",
                UART_DEVICE, g_uart_handle);
        return -1;
    }
    return 0;
}

static void log_sensor_data(int left, int middle, int right)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    printf("[%s] Left: %d, Middle: %d, Right: %d\n",
           timestamp, left, middle, right);
    fflush(stdout);
}

static void send_emergency_stop(void)
{
    const char *msg = "EMERGENCY STOP!\n";
    int written = serWrite(g_uart_handle, (char *)msg, strlen(msg));
    if (written < 0) {
        fprintf(stderr, "Error: failed to write to UART (serWrite returned %d).\n",
                written);
    } else if (written != (int)strlen(msg)) {
        fprintf(stderr, "Warning: partial UART write (%d of %zu bytes).\n",
                written, strlen(msg));
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (initialize_gpio() != 0) {
        return 1;
    }

    if (initialize_uart() != 0) {
        gpioTerminate();
        return 1;
    }

    printf("KY-033 3-Way Tracking Sensor Monitor started.\n");
    printf("Left=GPIO%d, Middle=GPIO%d, Right=GPIO%d, UART=%s @ %d baud.\n",
           LEFT_SENSOR_PIN, MIDDLE_SENSOR_PIN, RIGHT_SENSOR_PIN,
           UART_DEVICE, BAUD_RATE);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (g_running) {
        int left   = gpioRead(LEFT_SENSOR_PIN);
        int middle = gpioRead(MIDDLE_SENSOR_PIN);
        int right  = gpioRead(RIGHT_SENSOR_PIN);

        if (left < 0 || middle < 0 || right < 0) {
            fprintf(stderr, "Error: GPIO read failure (left=%d, middle=%d, right=%d).\n",
                    left, middle, right);
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        log_sensor_data(left, middle, right);

        if (left == 0 && middle == 0 && right == 0) {
            send_emergency_stop();
        }

        gpioDelay(LOOP_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    printf("Program terminated.\n");
    return 0;
}

